INSERT INTO `ibf_content_cache_posts` VALUES ('686', 'Приветствую. Тему открывал я. Но как говорилось выше она канула в лету.<br />Вот собственно я.<br /><span style=\'color:#000000;background:#000000\'><img src=\"http://s017.radikal.ru/i424/1202/79/85c4217d3da2.jpg\" border=\"0\" class=\"linked-image\" /></span><br />Если в 2 словах о себе скромен и добр. <br /><img src=\"style_emoticons/<#EMO_DIR#>/rolleyes.gif\" style=\"vertical-align:middle\" emoid=\":rolleyes:\" border=\"0\" alt=\"rolleyes.gif\" />', '1338719660');
INSERT INTO `ibf_content_cache_posts` VALUES ('699', '<b><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->Почистил я тему от хлама и флуда. Но ни одна зараза не сделала комплимент, что Вероника, очень симпатичная и красивая девушка. Ну что ж, тогда это сделаю я. Вероника, ты очень красивая и милая девушка.<br /><br /><br />P.S Продолжаем постить фото<!--colorc--></span><!--/colorc-->.</b>', '1338719660');
