INSERT INTO `ibf_content_cache_posts` VALUES ('131', '<!--quoteo(post=130:date=28.3.2012, 15&#58;46:name=BenQ)--><div class=\'quotetop\'>Цитата(BenQ &#064; 28.3.2012, 15&#58;46) <a href=\"index.php?act=findpost&amp;pid=130\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->еще уберите плиз Option.ini <br />и после патча персонажа нельзя создать<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><br />На счет Option.ini, запускайте через L2Play.exe в папке system.<br /><br /><br />на счет создания персонажей, читаем тут: <a href=\"http://onlineage2.com/forum/index.php?showtopic=5\" target=\"_blank\">http://onlineage2.com/forum/index.php?showtopic=5</a>', '1338900996');
