INSERT INTO `ibf_content_cache_posts` VALUES ('741', 'Я незнаю где искать и как понять что она именно из С3 просто обидно квест такой большой сколько денег пришлось на тп потратить из-за него а в награду фигушки.<br /><br />О и кстати тут ещё одна проблемка с НПЦ Metheus в церкви Гирана он там должен быть а его нет но когда я ввожу /target и его имя то оно появляется', '1338901298');
INSERT INTO `ibf_content_cache_posts` VALUES ('742', '<!--quoteo(post=741:date=24.5.2012, 14&#58;03:name=NikaLondon)--><div class=\'quotetop\'>Цитата(NikaLondon &#064; 24.5.2012, 14&#58;03) <a href=\"index.php?act=findpost&amp;pid=741\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Я незнаю где искать и как понять что она именно из С3 просто обидно квест такой большой сколько денег пришлось на тп потратить из-за него а в награду фигушки.<br /><br />О и кстати тут ещё одна проблемка с НПЦ Metheus в церкви Гирана он там должен быть а его нет но когда я ввожу /target и его имя то оно появляется<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><br /><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro--><b>Сейчас проверю и исправлю.</b><!--colorc--></span><!--/colorc-->', '1338901298');
