INSERT INTO `ibf_core_hooks_files` VALUES ('5', '2', 'boardIndexSideBarAdCode_1f5f9c01695a220711a3eda852f4403d.php', 'boardIndexSideBarAdCode.php', 'templateHooks', 'boardIndexSideBarAdCode', 'a:7:{s:12:\"dataLocation\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}', '<?php\n\nclass boardIndexSideBarAdCode\n{\n	/**#@+\n	 * Registry Object Shortcuts\n	 *\n	 * @access	protected\n	 * @var		object\n	 */\n	protected $registry;\n	protected $settings;\n	/**#@-*/\n	\n	public function __construct()\n	{\n		/* Make registry objects */\n		$this->registry		=  ipsRegistry::instance();\n		$this->settings 	=& $this->registry->fetchSettings();\n	}\n	\n	public function getOutput()\n	{\n		if( $this->registry->getClass(\'IPSAdCode\')->userCanViewAds() )\n		{\n			return $this->registry->getClass(\'IPSAdCode\')->getAdCode(\'ad_code_board_sidebar\');\n		}\n		else\n		{\n			return \'\';\n		}\n	}\n\n}');
