INSERT INTO `ibf_core_hooks_files` VALUES ('8', '5', 'boardIndexTags_565d83ac58187b5f57a0cd6108a9c3db.php', 'boardIndexTags.php', 'templateHooks', 'boardIndexTags', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}', '<?php\n\nclass boardIndexTags\n{\n	public $registry;\n	\n	public function __construct()\n	{\n		$this->registry = ipsRegistry::instance();\n	}\n	\n	public function getOutput()\n	{\n		$classToLoad = IPSLib::loadLibrary( IPSLib::getAppDir(\'forums\') . \'/sources/classes/hooks/gateway.php\', \'forums_hookGateway\', \'forums\' );\n		$hook = new $classToLoad( $this->registry );\n		\n		return $hook->tags();\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('9', '6', 'alpha_ef8c2e4ca928b5959b733b2b9c727469.php', 'mlist_aplharu.php', 'templateHooks', 'alpha', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:10:\"skin_mlist\";s:12:\"skinFunction\";s:16:\"member_list_show\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:5:\"chars\";s:8:\"position\";s:10:\"outer.post\";}', '<?php\n\nclass alpha\n{\n	public function getOutput()\n	{\n	    $template = ipsRegistry::instance()->output->getTemplate(\'mlist\')->member_alpha_ru(\n	        ipsRegistry::instance()->output->getTemplate(\'mlist\')->functionData[\'member_list_show\'][0][\'url\']\n	    );\n	    \n        $js = <<<JS\n\n				<script type=\'text/javascript\'>\n					$(\'alpha_switch\').observe(\'click\', function(){\n							if( $(\'mlist_tabs_ru\') )\n							{\n								$(\'mlist_tabs\').toggle();\n								$(\'mlist_tabs_ru\').toggle();\n							}\n					} );\n\n					$(\'alpha_switch_en\').observe(\'click\', function(){\n							if( $(\'mlist_tabs\') )\n							{\n								$(\'mlist_tabs\').toggle();\n								$(\'mlist_tabs_ru\').toggle();\n							}\n					} );\n\nJS;\n        if ( ord( urldecode(ipsRegistry::$request[\'quickjump\']) ) > 90 )\n        {\n            $js .= <<<JS\n					$(\'mlist_tabs\').toggle();\nJS;\n        }\n        else\n        {\n            $js .= <<<JS\n					$(\'mlist_tabs_ru\').toggle();\nJS;\n        }\n        \n        $js .= <<<JS\n				</script>\nJS;\n        \n        return $template . $js;\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('14', '7', 'boardIndexStatusUpdates_67d9e78b590eee009ec724c18a214d79.php', 'boardIndexStatusUpdates.php', 'templateHooks', 'boardIndexStatusUpdates', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}', null);
INSERT INTO `ibf_core_hooks_files` VALUES ('17', '10', 'shoutboxOnlineTab_6aebad7bffc6b2fdd050455665e56880.php', 'shoutboxOnlineTab.php', 'templateHooks', 'shoutboxOnlineTab', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_global\";s:12:\"skinFunction\";s:14:\"globalTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:13:\"accessreports\";s:8:\"position\";s:11:\"pre.startif\";}', '<?php\n\nclass shoutboxOnlineTab\n{\n	protected $registry;\n	protected $settings;\n	protected $memberData;\n	\n	public function __construct()\n	{\n		/* Make registry objects */\n		$this->registry   =  ipsRegistry::instance();\n		$this->settings   =& $this->registry->fetchSettings();\n		$this->memberData =& $this->registry->member()->fetchMemberData();\n	}\n	\n	public function getOutput()\n	{\n		/* All the ways we can return nothing */\n		if ( !$this->settings[\'shoutbox_online\'] || !$this->memberData[\'g_shoutbox_view\'] || !$this->memberData[\'g_shoutbox_use\'] || $this->memberData[\'_cache\'][\'shoutbox_banned\'] )\n		{\n			return \'\';\n		}\n		\n		/* Our library is loaded? */\n		if ( !class_exists(\'app_class_shoutbox\') || !$this->registry->isClassLoaded(\'shoutboxLibrary\') )\n		{\n			ipsRegistry::getAppClass( \'shoutbox\' );\n		}\n		\n		/* Start me up */\n		$this->registry->shoutboxLibrary->_startup();\n		\n		/* Run our common \'active users\' function */\n		$active = $this->registry->shoutboxLibrary->getMembersViewing( false );\n\n		if ( $active[\'TOTAL\'] )\n		{\n			return $this->registry->output->getTemplate(\'shoutbox_hooks\')->hookOnlineTab( $active[\'TOTAL\'] );\n		}\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('15', '8', 'shoutboxGlobalShoutbox_88d8fb75ef1ad2031781c16295e3c4b3.php', 'shoutboxGlobalShoutbox.php', 'templateHooks', 'shoutboxGlobalShoutbox', 'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:11:\"cats_forums\";s:8:\"position\";s:11:\"pre.startif\";}', '<?php\n\nclass shoutboxGlobalShoutbox\n{\n	protected $registry;\n	protected $settings;\n	protected $request;\n	protected $member;\n	protected $memberData;\n	protected $cache;\n	\n	public function __construct()\n	{\n        /* Make registry objects */\n		$this->registry   =  ipsRegistry::instance();\n		$this->settings   =& $this->registry->fetchSettings();\n		$this->request    =& $this->registry->fetchRequest();\n		$this->member     =  $this->registry->member();\n		$this->memberData =& $this->registry->member()->fetchMemberData();\n		$this->cache      =  $this->registry->cache();\n	}\n	\n	public function getOutput()\n	{\n		/* Check temporary ban status */\n		if( $this->memberData[\'temp_ban\'] )\n		{\n			# Let\'s just return, it is useless to process it since it is already done in ipsRegistry\n			return;\n		}\n		\n		/* Check the new way to ban */\n		if ( $this->memberData[\'member_banned\'] == 1 )\n		{\n			return;\n		}\n		\n		/* No permission to view the board */\n		if ( $this->memberData[\'g_view_board\'] != 1 )\n		{\n			return;\n		}\n		\n		/* Offline or can\'t view? */\n		if ( !$this->settings[\'shoutbox_online\'] || !$this->memberData[\'g_shoutbox_view\'] || (!$this->memberData[\'g_shoutbox_view\'] && !$this->memberData[\'g_shoutbox_use\']) || ( $this->settings[\'board_offline\'] && !$this->memberData[\'g_access_offline\'] ) )\n		{\n			return;\n		}\n		\n		/** Shoutbox app? - Are we shoutbox banned? **/\n		if ( ipsRegistry::$current_application == \'shoutbox\' || $this->memberData[\'_cache\'][\'shoutbox_banned\'] )\n		{\n			return;\n		}\n		\n		/* Login enforced? */\n		if ( !$this->memberData[\'member_id\'] && $this->settings[\'force_login\'] == 1 )\n		{\n			return;\n		}\n		\n		/* Printing the page? */\n		if ( !empty( $_GET[\'forcePrint\'] ) && ( $_GET[\'_k\'] == $this->member->form_hash ) )\n		{\n			return;\n		}\n		\n		/* Display only on index page? */\n		if ( $this->settings[\'shoutbox_global_display_loc\'] == \'idx\' )\n		{\n			// idx shortcut not used?\n			if ( $this->request[\'act\'] == \'idx\' || (ipsRegistry::$current_application == \'forums\' && ipsRegistry::$current_module == \'forums\' && ipsRegistry::$current_section == \'boards\') )\n			{\n				// Go on!\n			}\n			else\n			{\n				return;\n			}\n		}\n		else\n		{\n			// Check pages?\n			if ( !in_array( $this->settings[\'shoutbox_global_hook\'], array( \'s\', \'ct\', \'cb\' ) ) && $this->pagesCheckList() )\n			{\n				return;\n			}\n		}\n		\n		/* Our library is loaded? */\n		if( !class_exists(\'app_class_shoutbox\') OR !$this->registry->isClassLoaded(\'shoutboxLibrary\') )\n		{\n			require_once( IPSLib::getAppDir(\'shoutbox\').\'/app_class_shoutbox.php\' );\n			$app_class_shoutbox = new app_class_shoutbox( ipsRegistry::instance() );\n		}\n		\n		$this->registry->getClass(\'shoutboxLibrary\')->global_on = true;\n		$this->registry->getClass(\'shoutboxLibrary\')->_startup();\n		\n		// Check prefs\n		if ( !$this->registry->getClass(\'shoutboxLibrary\')->prefs[\'global_display\'] )\n		{\n			return;\n		}\n		\n		// We have the right amount of posts\n		// to use it if we can use it?\n		if ( $this->memberData[\'g_shoutbox_use\'] && $this->memberData[\'g_shoutbox_posts_req\'] )\n		{\n			$this->memberData[\'g_shoutbox_posts_req\'] = intval($this->memberData[\'g_shoutbox_posts_req\']);\n			if ($this->memberData[\'g_shoutbox_posts_req\'] && $this->memberData[\'posts\'] < $this->memberData[\'g_shoutbox_posts_req\'])\n			{\n				$this->memberData[\'g_shoutbox_use\'] = 0;\n				$this->registry->getClass(\'shoutboxLibrary\')->moderator = 0;\n			}\n		}\n		\n		$d = array( \'shout_height\' => $this->registry->getClass(\'shoutboxLibrary\')->prefs[\'shoutbox_gheight\'],\n					\'announcement\' => $this->registry->getClass(\'shoutboxLibrary\')->_get_announcement(),\n					\'noshouts\'     => $this->registry->getClass(\'shoutboxLibrary\')->_noShoutsMessage(),\n					\'shouts\'       => $this->registry->getClass(\'shoutboxLibrary\')->return_shouts(true),\n					);\n		\n		/* Setup JS things */\n		$d[\'js\']  = $this->registry->getClass(\'output\')->getTemplate(\'shoutbox\')->javascript( $d );\n		$d[\'js\'] .= $this->registry->getClass(\'shoutboxLibrary\')->show_lang_for_js_use();\n		\n		/* Which hook? - Added in 1.1.1 */\n		if ( $this->settings[\'shoutbox_global_hook\'] == \'s\' )\n		{\n			$hook = \'hookGlobalShoutboxSidebar\';\n		}\n		else\n		{\n			# Not sidebar? Use the normal one then\n			$hook = \'hookGlobalShoutbox\';\n		}\n		\n		return $this->registry->getClass(\'output\')->getTemplate(\'shoutbox_hooks\')->$hook( $d );\n	}\n	\n	private function pagesGetList()\n	{\n		$pages = array();\n\n		foreach ( explode(\"\\n\", $this->settings[\'shoutbox_global_pages_list\']) as $row )\n		{\n			// We have a row?\n			$row = trim($row);\n			if ($row == \'\')\n			{\n				continue;\n			}\n			\n			// We have segments?\n			$segments = explode(\",\", $row);\n			if ( count($segments) <= 0 )\n			{\n				continue;\n			}\n			\n			// Parse segments\n			$list = array();\n			foreach ( $segments as $v )\n			{\n				if ( preg_match(\"#(.+?)=(.+?)#i\", $v) )\n				{\n					list($key, $value) = explode(\'=\', $v);\n					$list[ $key ] = $value;\n				}\n			}\n\n			if ( count($list) )\n			{\n				$pages[] = $list;\n			}\n		}\n		\n		return $pages;\n	}\n	\n	private function pagesCheckList()\n	{\n		if ( $this->settings[\'shoutbox_global_pages_type\'] == \'d\' || $this->settings[\'shoutbox_global_pages_list\'] == \'\' )\n		{\n			return false;\n		}\n				\n		// Get pages from cache\n		$pages = $this->pagesGetList();\n		\n		// Go through pages if we have some\n		if ( count($pages) )\n		{\n			foreach ( $pages as $page )\n			{\n				/* Reset some vars */\n				$totalParts = count($page);\n				$foundParts = 0;\n				\n				foreach ( $page as $key => $value )\n				{\n					/* If we have a main key let\'s reset with the ipsRegistry values */\n					if ( $key == \'app\' )\n					{\n						$this->request[ $key ] = ipsRegistry::$current_application;\n					}\n					elseif ( $key == \'module\' )\n					{\n						$this->request[ $key ] = ipsRegistry::$current_module;\n					}\n					elseif ( $key == \'section\' )\n					{\n						$this->request[ $key ] = ipsRegistry::$current_section;\n					}\n					\n					if ( $value == \'*\' && isset($this->request[ $key ]) )\n					{\n						$foundParts++;\n					}\n					elseif ( strtolower($this->request[ $key ]) == strtolower($value) )\n					{\n						$foundParts++;\n					}\n					else\n					{\n						break;\n					}\n				}\n				\n				if ( $foundParts == $totalParts )\n				{\n					return $this->settings[\'shoutbox_global_pages_type\'] == \'e\' ? TRUE : FALSE;\n				}\n			}\n		}\n		\n		return $this->settings[\'shoutbox_global_pages_type\'] == \'e\' ? FALSE: TRUE;\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('16', '9', 'shoutboxActiveUsers_c5a977fe486fca8cddf79d84602771d4.php', 'shoutboxActiveUsers.php', 'templateHooks', 'shoutboxActiveUsers', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:11:\"activeNames\";s:8:\"position\";s:10:\"post.endif\";}', '<?php\n\nclass shoutboxActiveUsers\n{\n	protected $registry;\n	protected $settings;\n	protected $memberData;\n	\n	public function __construct()\n	{\n        /* Make registry objects */\n		$this->registry   =  ipsRegistry::instance();\n		$this->settings   =& $this->registry->fetchSettings();\n		$this->memberData =& $this->registry->member()->fetchMemberData();\n	}\n	\n	public function getOutput()\n	{\n		if ( $this->settings[\'shoutbox_active_groups\'] == \"\" )\n		{\n			return;\n		}\n		\n		if ( $this->settings[\'shoutbox_online\'] && in_array( $this->memberData[\'member_group_id\'], explode( \",\", $this->settings[\'shoutbox_active_groups\'] ) ) )\n		{\n			/* Our library is loaded? */\n			if( !class_exists(\'app_class_shoutbox\') OR !$this->registry->isClassLoaded(\'shoutboxLibrary\') )\n			{\n				require_once( IPSLib::getAppDir(\'shoutbox\').\'/app_class_shoutbox.php\' );\n				$app_class_shoutbox = new app_class_shoutbox( ipsRegistry::instance() );\n			}\n			\n			$this->registry->getClass(\'shoutboxLibrary\')->global_on = true;\n			$this->registry->getClass(\'shoutboxLibrary\')->_startup();\n			\n			/* Which hook? - Added in 1.1.1 */\n			if ( $this->settings[\'shoutbox_active_hook\'] == \'s\' )\n			{\n				$hook = \'hookActiveUsersSidebar\';\n			}\n			else\n			{\n				$hook = \'hookActiveUsers\';\n			}\n			\n			return $this->registry->output->getTemplate(\'shoutbox_hooks\')->$hook( $this->registry->getClass(\'shoutboxLibrary\')->getMembersViewing(false) );\n		}\n		\n		return \'\';\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('30', '14', 'ajaxFastReplyDivider_4238a278f2f7b22949adb7a64e5d26a5.php', 'ajaxFastReplyDivider.php', 'templateHooks', 'ajaxFastReplyDivider', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:10:\"skin_topic\";s:12:\"skinFunction\";s:17:\"topicViewTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:9:\"post_data\";s:8:\"position\";s:10:\"outer.post\";}', '<?php\n\nclass ajaxFastReplyDivider\n{\n	/**#@+\n	 * Registry Object Shortcuts\n	 *\n	 * @access	protected\n	 * @var		object\n	 */\n	protected $registry;\n	/**#@-*/\n	\n	public function __construct()\n	{\n		/* Make registry object */\n		$this->registry	= ipsRegistry::instance();\n	}\n	\n	public function getOutput()\n	{\n		$this->html = $this->registry->getClass(\'output\')->getTemplate(\'topic\')->ajaxFastReplyDivider();\n		return $this->html;\n	}\n}\n\n?>');
INSERT INTO `ibf_core_hooks_files` VALUES ('31', '14', 'ajaxFastReply_c5587c178b843f532fc9b34d427cb4aa.php', 'ajaxFastReply.php', 'commandHooks', 'ajaxFastReply', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:25:\"public_forums_ajax_topics\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', '<?php\n\nclass ajaxFastReply extends (~extends~)\n{\n	public $registry;\n		\n	public function doExecute( ipsRegistry $registry )\n	{\n		if ( $this->request[\'do\'] == \'ajaxFastReply\' )\n		{\n			$this->doAjaxFastReply( $registry );\n		}\n		\n		parent::doExecute( $registry ); // Get on with the rest.\n	}\n		\n	private function doAjaxFastReply( ipsRegistry $registry )\n	{\n		//-----------------------------------------\n		// INIT\n		//-----------------------------------------\n\n		$fid				= intval( $this->request[\'f\'] );\n		$tid				= intval( $this->request[\'t\'] );\n		$post_date		= intval( $this->request[\'post_date\'] );\n\n   		//-----------------------------------------\n		// Set things right\n		//-----------------------------------------\n		\n		$this->request[\'Post\'] =  IPSText::parseCleanValue( $_POST[\'Post\'] );\n\n		//-----------------------------------------\n		// Check P|T|FID\n		//-----------------------------------------\n\n		if ( ! $fid || ! $tid || ! $post_date )\n		{\n			$this->returnJsonError( \'No post/topic/forum passed.\' );\n		}\n		\n		if ( ! $this->memberData[\'member_id\'] )\n		{\n			$this->returnJsonError( \'You must be logged in to use this feature.\' );\n		}\n		\n		$pass = 1;\n		\n		if ( ! $this->settings[\'en30_ajaxfastreply\'] )\n		{\n			$pass = 0;\n		}\n		\n		if ( in_array( $this->memberData[\'member_group_id\'], explode( \",\", $this->settings[\'en30_nonajaxgroups\'] ) ) )\n		{\n			$pass = 0;\n		}\n		\n		if ( in_array( $fid, explode( \",\", $this->settings[\'en30_nonajaxforums\'] ) ) )\n		{\n			$pass = 0;\n		}\n		\n		if ( ! $pass )\n		{\n			$this->returnJsonError( \'You are not authorized to access this feature.\' );\n		}\n		\n    	//-----------------------------------------\n    	// Make sure we have a valid auth key\n    	//-----------------------------------------\n    	\n    	if ( $this->request[\'auth_key\'] != $this->member->form_hash )\n		{\n			$this->returnJsonError( \'The request could not be authenticated. Please refresh the page and try again.\' );\n		}\n		\n		if ( $this->memberData[\'restrict_post\'] )\n		{\n			if ( $this->memberData[\'restrict_post\'] == 1 )\n			{\n				$this->returnJsonError( \'Your posting ability has been disabled.\' );\n			}\n\n			$post_arr = IPSMember::processBanEntry( $this->memberData[\'restrict_post\'] );\n\n			if ( time() >= $post_arr[\'date_end\'] )\n			{\n				//-----------------------------------------\n				// Update this member\'s profile\n				//-----------------------------------------\n				\n				IPSMember::save( $this->memberData[\'member_id\'], array( \'core\' => array( \'restrict_post\' => 0 ) ) );\n			}\n			else\n			{\n				$this->returnJsonError( \'You do not have permission to use this feature.\' );\n			}\n		}\n		\n		if ( $this->settings[\'flood_control\'] > 0 )\n		{\n			if ( $this->memberData[\'g_avoid_flood\'] != 1 )\n			{\n				if ( time() - $this->memberData[\'last_post\'] < $this->settings[\'flood_control\'] )\n				{\n					$this->returnJsonError( \"You must wait {$this->settings[\'flood_control\']} seconds before posting again.\" );\n				}\n			}\n		}\n\n		//-----------------------------------------\n		// Load Lang\n		//-----------------------------------------\n\n		$this->registry->getClass( \'class_localization\')->loadLanguageFile( array( \'public_boards\', \'public_topic\' ) );\n\n		if ( ! is_object( $this->postClass ) )\n		{\n			require_once( IPSLib::getAppDir( \'forums\' ) . \"/sources/classes/post/classPost.php\" );\n			require_once( IPSLib::getAppDir( \'forums\' ) . \"/sources/classes/post/classPostForms.php\" );\n			\n			$this->registry->getClass( \'class_localization\')->loadLanguageFile( array( \'public_editors\' ), \'core\' );\n			\n			$this->postClass =  new classPostForms( $this->registry );\n		}\n		\n		\n		# Is Preview Mode\n		$this->postClass->setIsPreview( FALSE );\n		\n		# Forum Data\n		$this->postClass->setForumData( $this->registry->getClass(\'class_forums\')->forum_by_id[ $fid ] );\n		\n		# IDs\n		$this->postClass->setTopicID( $tid );\n		$this->postClass->setForumID( $fid );\n		\n		/* Topic Data */\n		$this->postClass->setTopicData( $this->DB->buildAndFetch( array( \n																			\'select\'   => \'t.*, p.poll_only\', \n																			\'from\'     => array( \'topics\' => \'t\' ), \n																			\'where\'    => \"t.forum_id={$fid} AND t.tid={$tid}\",\n																			\'add_join\' => array(\n																								array( \n																										\'type\'	=> \'left\',\n																										\'from\'	=> array( \'polls\' => \'p\' ),\n																										\'where\'	=> \'p.tid=t.tid\'\n																									)\n																								)\n									) 							)	 );\n									\n		# Published\n		$this->postClass->setPublished( $this->memberData[\'g_avoid_q\'] ? TRUE : ( $this->_checkPostModeration( $doCodes[ $do ][1] ) === TRUE ? TRUE : FALSE ) );\n		\n		# Set Author\n		$this->postClass->setAuthor( $this->member->fetchMemberData() );\n		\n		# Set from ajax\n		$this->postClass->setIsAjax( TRUE );\n\n		# Post Content\n		$this->postClass->setPostContent( $_POST[\'Post\'] );\n		\n		$this->request[\'enablesig\'] = ( isset( $this->request[\'enablesig\'] ) ) ? $this->request[\'enablesig\'] : \'yes\';\n		$this->request[\'enableemo\'] = ( isset( $this->request[\'enableemo\'] ) ) ? $this->request[\'enableemo\'] : \'yes\';\n\n		$this->postClass->setSettings( array( \'enableSignature\' => ( $this->request[\'enablesig\']  == \'yes\' ) ? 1 : 0,\n											   \'enableEmoticons\' => ( $this->request[\'enableemo\']  == \'yes\' ) ? 1 : 0,\n											   \'post_htmlstatus\' => intval( $this->request[\'post_htmlstatus\'] ),\n											   \'enableTracker\'   => intval( $this->request[\'enabletrack\'] ) ) );\n											   \n		//-----------------------------------------\n        // Checks...\n        //-----------------------------------------\n       \n        $this->registry->getClass(\'class_forums\')->forumsCheckAccess( $this->postClass->getForumData(\'id\'), 1, \'forum\', $this->postClass->getTopicData() );\n\n		# Get Edit form\n		try\n		{\n			/**\n			 * If there was an error, return it as a JSON error\n			 */\n			if ( $this->postClass->addReply() === FALSE )\n			{\n				$this->returnJsonError( $this->postClass->getPostError() );\n			}\n			\n			$topic = $this->postClass->getTopicData();\n			$post  = $this->postClass->getPostData();\n			\n			//-----------------------------------------\n	        // v1.0.6 Topic Marker Fix\n	        //-----------------------------------------			\n        \n			$this->registry->getClass(\'classItemMarking\')->markRead( array( \'forumID\' => $fid, \'itemID\' => $tid ) );\n			\n			//-----------------------------------------\n			// Now get the replies from the database\n			//-----------------------------------------		\n			\n			$_post_joins = array(\n									array( \n											\'select\' => \'m.member_id as mid,m.name,m.member_group_id,m.email,m.joined,m.posts, m.last_visit, m.last_activity,m.login_anonymous,m.title,m.hide_email, m.warn_level, m.warn_lastwarn, m.members_display_name, m.members_seo_name, m.has_gallery, m.has_blog, m.members_bitoptions\',\n											\'from\'   => array( \'members\' => \'m\' ),\n											\'where\'  => \'m.member_id=p.author_id\',\n											\'type\'   => \'left\'\n										),\n									array( \n											\'select\' => \'pp.*\',\n											\'from\'   => array( \'profile_portal\' => \'pp\' ),\n											\'where\'  => \'m.member_id=pp.pp_member_id\',\n											\'type\'   => \'left\'\n									),\n									array( \n											\'select\' => \'g.g_access_cp\',\n											\'from\'   => array( \'groups\' => \'g\' ),\n											\'where\'  => \'g.g_id=m.member_group_id\',\n											\'type\'   => \'left\'\n									),\n									array( \n											\'select\' => \'t.tid\',\n											\'from\'   => array( \'topics\' => \'t\' ),\n											\'where\'  => \"t.tid = {$tid}\",\n											\'type\'   => \'left\'\n									)								);\n								\n			/* Add custom fields join? */\n			if( $this->settings[\'custom_profile_topic\'] == 1 )\n			{\n				$_post_joins[] = array( \n										\'select\' => \'pc.*\',\n										\'from\'   => array( \'pfields_content\' => \'pc\' ),\n										\'where\'  => \'pc.member_id=p.author_id\',\n										\'type\'   => \'left\'\n									);\n			}							\n			\n			/* Reputation system enabled? */\n			if( $this->settings[\'reputation_enabled\'] )\n			{\n				/* Get the rep library */\n				require_once( IPS_ROOT_PATH . \'sources/classes/class_reputation_cache.php\' );\n				$repCache = new classReputationCache();\n				\n				/* Add the join to figure out if the user has already rated the post */\n				$_post_joins[] = $repCache->getUserHasRatedJoin( \'pid\', \'p.pid\', \'forums\' );\n				\n				/* Add the join to figure out the total ratings for each post */\n				if( $this->settings[\'reputation_show_content\'] )\n				{\n					$_post_joins[] = $repCache->getTotalRatingJoin( \'pid\', \'p.pid\', \'forums\' );\n				}\n			}\n			\n			/* Cache? */\n			if ( IPSContentCache::isEnabled() )\n			{\n				if ( IPSContentCache::fetchSettingValue(\'post\') )\n				{\n					$_post_joins[] = IPSContentCache::join( \'post\', \'p.pid\' );\n				}\n				\n				if ( IPSContentCache::fetchSettingValue(\'sig\') )\n				{\n					$_post_joins[] = IPSContentCache::join( \'sig\' , \'m.member_id\', \'ccb\', \'left\', \'ccb.cache_content as cache_content_sig, ccb.cache_updated as cache_updated_sig\' );\n				}\n			}\n			\n			//-----------------------------------------\n			// Get posts\n			//-----------------------------------------\n			\n			$posts = array();\n\n			$this->DB->build( array( \n									\'select\'   => \'p.*\',\n									\'from\'	   => array( \'posts\' => \'p\' ),\n									\'where\'	   => \"p.topic_id = {$tid} AND p.post_date > {$post_date}\",\n									\'order\'	   => $this->settings[\'post_order_column\'] . \' \' . $this->settings[\'post_order_sort\'],\n									\'add_join\' => $_post_joins\n							)	);\n	\n			$exec = $this->DB->execute();\n\n			while ( $row = $this->DB->fetch( $exec ) )\n			{\n				$last_post			= $row[\'post_date\'];\n				$row[\'member_id\']	= $row[\'mid\'];\n	\n				$return = $this->parsePostRow( $row );\n\n				$poster = $return[\'poster\'];\n				$row	= $return[\'row\'];\n				$poster[\'member_id\'] = $poster[\'mid\'];\n\n				/* Reputation */	\n				if( $this->settings[\'reputation_enabled\'] )\n				{\n					$row[\'pp_reputation_points\'] = $row[\'pp_reputation_points\'] ? $row[\'pp_reputation_points\'] : 0;\n					$row[\'has_given_rep\']        = $row[\'has_given_rep\'] ? $row[\'has_given_rep\'] : 0;\n					$row[\'rep_points\']           = $row[\'rep_points\'] ? $row[\'rep_points\'] : 0;\n				}\n				\n				//-----------------------------------------\n				// Pre-display-parse\n				//-----------------------------------------\n				\n				IPSText::getTextClass( \'bbcode\' )->parse_smilies			= $row[\'use_emo\'];\n				IPSText::getTextClass( \'bbcode\' )->parse_html				= ( $this->registry->getClass(\'class_forums\')->forum_by_id[ $fid ][\'use_html\'] and $this->memberData[\'g_dohtml\'] and $row[\'post_htmlstate\'] ) ? 1 : 0;\n				IPSText::getTextClass( \'bbcode\' )->parse_nl2br				= $row[\'post_htmlstate\'] == 2 ? 1 : 0;\n				IPSText::getTextClass( \'bbcode\' )->parse_bbcode				= 1;\n				IPSText::getTextClass( \'bbcode\' )->parsing_section			= \'topics\';\n				IPSText::getTextClass( \'bbcode\' )->parsing_mgroup			= $this->postClass->getAuthor(\'member_group_id\');\n				IPSText::getTextClass( \'bbcode\' )->parsing_mgroup_others	= $this->postClass->getAuthor(\'mgroup_others\');\n					\n				$row[\'post\']	= IPSText::getTextClass( \'bbcode\' )->preDisplayParse( $row[\'post\'] );\n	\n				if ( IPSText::getTextClass( \'bbcode\' )->error )\n				{\n					$this->returnJsonError( $this->lang->words[ IPSText::getTextClass( \'bbcode\' )->error ] );\n				}\n				\n				$this->DB->build( array( \'select\' => \'*\', \'from\' => \'topics\', \'where\' => \'tid=\'.$tid ) );									\n				$this->DB->execute();\n				\n				$topicData = $this->DB->fetch();\n				\n				$topicData[\'posts\'] ++;\n	\n				$ajaxRow = $this->registry->getClass(\'output\')->replaceMacros( $this->registry->getClass(\'output\')->getTemplate(\'topic\')->ajaxFastReplyRow(\n								$this->registry->class_forums->forum_by_id[ $fid ],\n								$topicData,\n								array( \'post\' => $row, \'author\' => $poster )\n							)\n																											);\n				$ajaxRow = preg_replace( \"#<!--hook\\.([^\\>]+?)-->#\", \'\', $ajaxRow );\n\n				$posts[] = array(\n										\'post\'				=> $ajaxRow,\n										\'pid\'				=> $row[\'pid\'],\n										\'queued\'		=> $row[\'queued\'],\n										\'rep_points\'	=> $row[\'rep_points\'] ,\n										);\n			}\n\n			//-----------------------------------------\n			// Return data\n			//-----------------------------------------\n\n			$this->returnJsonArray( array( \'posts\' => $posts, \'last_post\' => $last_post ) );\n		}\n		catch ( Exception $error )\n		{\n			$this->returnJsonError( $error->getMessage() );\n		}\n	}\n	\n	/**\n	 * Builds an array of post data for output\n	 *\n	 * @access	public\n	 * @param	array	$row	Array of post data\n	 * @return	array\n	 **/\n	public function parsePostRow( $row = array() )\n	{\n		//-----------------------------------------\n		// Memory Debug\n		//-----------------------------------------\n		\n		$_NOW   = IPSDebug::getMemoryDebugFlag();\n		$poster = array();\n		\n		//-----------------------------------------\n		// Cache member\n		//-----------------------------------------\n		\n		if ( $row[\'author_id\'] != 0 )\n		{\n			//-----------------------------------------\n			// Is it in the hash?\n			//-----------------------------------------\n			\n			if ( isset( $this->cached_members[ $row[\'author_id\'] ] ) )\n			{\n				//-----------------------------------------\n				// Ok, it\'s already cached, read from it\n				//-----------------------------------------\n				\n				$poster = $this->cached_members[ $row[\'author_id\'] ];\n				$row[\'name_css\'] = \'normalname\';\n			}\n			else\n			{\n				$row[\'name_css\'] = \'normalname\';\n				$poster = $row;\n				\n				if ( isset( $poster[\'cache_content_sig\'] ) )\n				{\n					$poster[\'cache_content\'] = $poster[\'cache_content_sig\'];\n					$poster[\'cache_updated\'] = $poster[\'cache_updated_sig\'];\n				}\n				else\n				{\n					unset( $poster[\'cache_content\'], $poster[\'cache_updated\'] );\n				}\n				\n				$poster = IPSMember::buildDisplayData( $poster, array( \'signature\' => 1, \'customFields\' => 1, \'warn\' => 1, \'avatar\' => 1, \'checkFormat\' => 1 ) );\n				$poster[\'member_id\'] = $row[\'mid\'];\n				\n				//-----------------------------------------\n				// Add it to the cached list\n				//-----------------------------------------\n				\n				$this->cached_members[ $row[\'author_id\'] ] = $poster;\n			}\n		}\n		else\n		{\n			//-----------------------------------------\n			// It\'s definitely a guest...\n			//-----------------------------------------\n			\n			$row[\'author_name\']	= $this->settings[\'guest_name_pre\'] . $row[\'author_name\'] . $this->settings[\'guest_name_suf\'];\n			\n			$poster = IPSMember::setUpGuest( $row[\'author_name\'] );\n			$poster[\'members_display_name\']		= $row[\'author_name\'];\n			$poster[\'_members_display_name\']	= $row[\'author_name\'];\n			$poster[\'custom_fields\']			= \"\";\n			$poster[\'warn_img\']					= \"\";\n			$row[\'name_css\']					= \'unreg\';\n		}\n		\n		# Memory Debug\n		IPSDebug::setMemoryDebugFlag( \"PID: \".$row[\'pid\'] . \" - Member Parsed\", $_NOW );\n		\n		//-----------------------------------------\n		// Queued\n		//-----------------------------------------\n		\n		if ( $this->topic[\'topic_firstpost\'] == $row[\'pid\'] and $this->topic[\'approved\'] != 1 )\n		{\n			$row[\'queued\'] = 1;\n		}\n		\n		//-----------------------------------------\n		// Parse the post\n		//-----------------------------------------\n		\n		if ( ! $row[\'cache_content\'] )\n		{\n			$_NOW2   = IPSDebug::getMemoryDebugFlag();\n		\n			IPSText::getTextClass( \'bbcode\' )->parse_smilies			= $row[\'use_emo\'];\n			IPSText::getTextClass( \'bbcode\' )->parse_html				= ( $this->forum[\'use_html\'] and $this->caches[\'group_cache\'][ $row[\'member_group_id\'] ][\'g_dohtml\'] and $row[\'post_htmlstate\'] ) ? 1 : 0;\n			IPSText::getTextClass( \'bbcode\' )->parse_nl2br				= $row[\'post_htmlstate\'] == 2 ? 1 : 0;\n			IPSText::getTextClass( \'bbcode\' )->parse_bbcode				= $this->forum[\'use_ibc\'];\n			IPSText::getTextClass( \'bbcode\' )->parsing_section			= \'topics\';\n			IPSText::getTextClass( \'bbcode\' )->parsing_mgroup			= $row[\'member_group_id\'];\n			IPSText::getTextClass( \'bbcode\' )->parsing_mgroup_others	= $row[\'mgroup_others\'];\n\n			$row[\'post\']	= IPSText::getTextClass( \'bbcode\' )->preDisplayParse( $row[\'post\'] );\n		\n			IPSDebug::setMemoryDebugFlag( \"topics::parsePostRow - bbcode parse - Completed\", $_NOW2 );\n			\n			IPSContentCache::drop( \'post\', $row[\'pid\'] );\n			// Commented out for bug #14252, replace is unreliable\n			//IPSContentCache::update( $last_post[\'pid\'], \'post\', $this->formatPostForCache( $new_post ) );\n		}\n		else\n		{\n			$row[\'post\'] = \'<!--cached-\' . gmdate( \'r\', $row[\'cache_updated\'] ) . \'-->\' . $row[\'cache_content\'];\n		}\n		\n		//-----------------------------------------\n		// View image...\n		//-----------------------------------------\n		\n		if ( ! $this->memberData[\'view_img\'] )\n		{\n			$row[\'post\'] = IPSText::getTextClass( \'bbcode\' )->memberViewImages( $row[\'post\'] );\n		}\n		\n		//-----------------------------------------\n		// Highlight...\n		//-----------------------------------------\n		\n		if ( $this->request[\'hl\'] )\n		{\n			$row[\'post\'] = IPSText::searchHighlight( $row[\'post\'], $this->request[\'hl\'] );\n		}\n		\n		//-----------------------------------------\n		// Multi Quoting?\n		//-----------------------------------------\n\n		if ( $this->qpids )\n		{\n			if ( strstr( \',\'.$this->qpids.\',\', \',\'.$row[\'pid\'].\',\' ) )\n			{\n				$row[\'_mq_selected\'] = 1;\n			}\n		}\n		\n		//-----------------------------------------\n		// Multi PIDS?\n		//-----------------------------------------\n\n		if ( $this->memberData[\'is_mod\'] )\n		{\n			if ( $this->request[\'selectedpids\'] )\n			{\n				if ( strstr( \',\'.$this->request[\'selectedpids\'].\',\', \',\'.$row[\'pid\'].\',\' ) )\n				{\n					$row[\'_pid_selected\'] = 1;\n				}\n\n				$this->request[\'selectedpidcount\'] =  count( explode( \",\", $this->request[\'selectedpids\']  ) );\n			}\n		}\n		\n		//-----------------------------------------\n		// Delete button..\n		//-----------------------------------------\n		\n		$row[\'_can_delete\'] = $row[\'pid\'] != $this->topic[\'topic_firstpost\'] \n							  ? $this->_getDeleteButtonData( $row ) \n							  : FALSE;		\n\n		$row[\'_can_edit\']   = $this->_getEditButtonData( $row );\n		$row[\'_show_ip\']	= $this->_getIPAddressData();\n		\n		//-----------------------------------------\n		// Siggie stuff\n		//-----------------------------------------\n		\n		$row[\'signature\'] = \"\";\n		\n		if ( isset( $poster[\'signature\'] ) AND $poster[\'signature\'] AND $this->memberData[\'view_sigs\'] )\n		{\n			if ($row[\'use_sig\'] == 1)\n			{\n				$row[\'signature\'] = $this->registry->output->getTemplate( \'global\' )->signature_separator( $poster[\'signature\'] );\n			}\n		}\n		\n		//-----------------------------------------\n		// Fix up the membername so it links to the members profile\n		//-----------------------------------------\n	\n		if ( $poster[\'member_id\'] )\n		{\n			$poster[\'_members_display_name\'] = \"<a href=\'{$this->settings[\'_base_url\']}showuser={$poster[\'member_id\']}\'>{$poster[\'members_display_name_short\']}</a>\";\n		}\n		\n		//-----------------------------------------\n		// Post number\n		//-----------------------------------------\n		\n		if ( $this->topic_view_mode == \'linearplus\' and $this->topic[\'topic_firstpost\'] == $row[\'pid\'])\n		{\n			$row[\'post_count\'] = 1;\n			\n			if ( ! $this->first )\n			{\n				$this->post_count++;\n			}\n		}\n		else\n		{\n			$this->post_count++;\n		\n			$row[\'post_count\'] = intval($this->request[\'st\']) + $this->post_count;\n		}\n		\n		$row[\'forum_id\'] = $this->topic[\'forum_id\'];		\n		\n		//-----------------------------------------\n		// Memory Debug\n		//-----------------------------------------\n	\n		IPSDebug::setMemoryDebugFlag( \"PID: \".$row[\'pid\']. \" - Completed\", $_NOW );\n		\n		return array( \'row\' => $row, \'poster\' => $poster );\n	}\n	\n	/**\n	 * Return whether or not we have permission to delete the post\n	 *\n	 * @access	public\n	 * @return	bool\n	 **/\n	public function _getDeleteButtonData( $poster )\n	{\n		if ( ! $this->memberData[\'member_id\']  )\n		{\n			return FALSE;\n		}\n		\n		if ( $this->memberData[\'g_is_supmod\'] OR $this->moderator[\'delete_post\'] )\n		{\n			return TRUE;\n		}\n		\n		if ( $poster[\'member_id\'] == $this->memberData[\'member_id\'] and ( $this->memberData[\'g_delete_own_posts\'] ) )\n		{\n			return TRUE;\n		}\n		\n		return FALSE;\n	}\n	\n	/**\n	 * Return whether or not we can edit this post\n	 *\n	 * @access	public\n	 * @param	array 		Array of post data\n	 * @return  bool\n	 **/\n	public function _getEditButtonData( $poster=array() )\n	{\n		if ( $this->memberData[\'member_id\'] == \"\" or $this->memberData[\'member_id\'] == 0 )\n		{\n			return FALSE;\n		}\n				\n		if ( $this->memberData[\'g_is_supmod\'] )\n		{\n			return TRUE;\n		}\n		\n		if ( $this->moderator[\'edit_post\'] )\n		{\n			return TRUE;\n		}\n		\n		if ( $poster[\'member_id\'] == $this->memberData[\'member_id\'] and ($this->memberData[\'g_edit_posts\']) )\n		{\n			// Have we set a time limit?\n			if ($this->memberData[\'g_edit_cutoff\'] > 0)\n			{\n				if ( $poster[\'post_date\'] > ( time() - ( intval($this->memberData[\'g_edit_cutoff\']) * 60 ) ) )\n				{\n					return TRUE;\n				}\n				else\n				{\n					return FALSE;\n				}\n			}\n			else\n			{\n				return TRUE;\n			}\n		}\n		\n		return FALSE;\n	}\n	\n	/**\n	 * Get reply button data\n	 *\n	 * @access	public\n	 * @return	array\n	 **/\n	public function _getReplyButtonData()\n	{\n		//-----------------------------------------\n		// INIT\n		//-----------------------------------------\n		\n		$image = \'\';\n		$url   = \'\';\n		\n		if ($this->topic[\'state\'] == \'closed\' OR ($this->topic[\'poll_state\'] AND $this->poll_only ) )\n		{\n			/* Do we have the ability to post in closed topics or is this a poll only?*/\n			if ($this->memberData[\'g_post_closed\'] == 1)\n			{\n				$url   = $this->settings[\'base_url_with_app\'] . \"module=post&amp;section=post&amp;do=reply_post&amp;f=\".$this->forum[\'id\'].\"&amp;t=\".$this->topic[\'tid\'];\n				$image = \'locked\';\n			}\n			else\n			{\n				$image = \"locked\";\n			}\n		}\n		else\n		{\n			if ( $this->topic[\'state\'] == \'moved\' )\n			{\n				$image = \"moved\";\n			}\n			else\n			{\n				//if ( $this->_ppd_ok !== TRUE )\n				//{\n					/* Posts per day restriction */\n					//$image = \'locked\';\n				//}\n				if( $this->forum[\'min_posts_post\'] && $this->forum[\'min_posts_post\'] > $this->memberData[\'posts\'] )\n				{\n					$image = \"locked\";\n				}\n				else if( ! $this->forum[\'status\'] )\n				{\n					$image = \"locked\";\n				}\n				else\n				{\n					if ( $this->memberData[\'member_id\'] AND ( ( ( $this->memberData[\'member_id\'] == $this->topic[\'starter_id\'] ) AND ! $this->memberData[\'g_reply_own_topics\'] ) OR ( ! $this->memberData[\'g_reply_other_topics\'] ) ) )\n					{\n						$image = \"no_reply\";\n					}\n					else if( $this->registry->permissions->check( \'reply\', $this->forum ) == TRUE )\n					{\n						$url   = $this->settings[\'base_url_with_app\'] . \"module=post&amp;section=post&amp;do=reply_post&amp;f=\".$this->forum[\'id\'].\"&amp;t=\".$this->topic[\'tid\'];\n						$image = \"reply\";\n					}\n					else\n					{\n						$image = \"no_reply\";\n					}\n				}\n			}\n		}\n\n		return array( \'image\' => $image, \'url\' => $url );\n	}\n	\n	/**\n	 * Return whether we can see the IP address or not\n	 *\n	 * @access	public\n	 * @return	bool\n	 **/\n	public function _getIPAddressData()\n	{\n		if ( $this->memberData[\'g_is_supmod\'] != 1 && ( !isset($this->moderator[\'view_ip\']) OR $this->moderator[\'view_ip\'] != 1 ) )\n		{\n			return FALSE;\n		}\n		else\n		{\n			return TRUE;\n		}\n	}\n	\n	/**\n	 * Checks to see if this member is forced to have their posts\n	 * moderated\n	 *\n	 * @access	private\n	 * @param	string	Type of post (new, reply, edit, poll)\n	 * @return	boolean	Whether to PUBLISH this topic or not\n	 */\n	private function _checkPostModeration( $type )\n	{\n		/* First off, is the member\'s group moderated? */\n		if ( $this->postClass->checkGroupIsPostModerated( $this->memberData ) === TRUE )\n		{\n			return FALSE;\n		}\n		\n		/* Does this member have mod_posts enabled? */\n		if ( $this->memberData[\'mod_posts\'] )\n		{\n			/* Mod Queue Forever */\n			if ( $this->memberData[\'mod_posts\'] == 1 )\n			{\n				return FALSE;\n			}\n			else\n			{\n				/* Do we need to remove the mod queue for this user? */\n				$mod_arr = IPSMember::processBanEntry( $this->memberData[\'mod_posts\'] );\n				\n				/* Yes, they are ok now */\n				if ( time() >= $mod_arr[\'date_end\'] )\n				{\n					IPSMember::save( $this->memberData[\'member_id\'], array( \'core\' => array( \'mod_posts\' => 0 ) ) );\n				}\n				/* Nope, still don\'t want to see them */\n				else\n				{\n					return FALSE;\n				}\n			}\n		}\n		\n		/* Check to see if this forum has moderation enabled */\n		$forum = $this->postClass->getForumData();\n\n		switch( intval( $forum[\'preview_posts\'] ) )\n		{\n			default:\n			case 0:\n				return TRUE;\n			break;\n			case 1:\n				return FALSE;\n			break;\n			case 2:\n				return ( $type == \'new\' ) ? FALSE : TRUE;\n			break;\n			case 3:\n				return ( $type == \'reply\' ) ? FALSE : TRUE;\n			break;\n		}\n		\n		/* Our post can be seen! */\n		return TRUE;\n	}\n}\n\n?>');
INSERT INTO `ibf_core_hooks_files` VALUES ('28', '13', 'sos31_othersgroups_global_68d44f6a53a6aba829054e0748810d1a.php', 'sos31_othersgroups_global.php', 'skinHooks', 'sos31_othersgroups_global', 'a:7:{s:12:\"dataLocation\";s:0:\"\";s:15:\"classToOverload\";s:11:\"skin_global\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', 'class sos31_othersgroups_global extends skin_global(~id~)\n{\n	public function userInfoPane( $author, $contentid, $options )\n	{\n		$grupos = array();\n       \n      	if ( $author[\'mgroup_others\'] )\n      	{\n        	$grupos = explode( \",\", IPSText::cleanPermString( $author[\'mgroup_others\'] ) );\n\n			$grupo = ipsRegistry::cache()->getCache( \'group_cache\' );\n			\n			foreach ( $grupos as $sec_group )\n			{\n	        	if ( $sec_group != $author[\'member_group_id\'] )\n				{\n					$g_others[] = $grupo[ $sec_group ][\'prefix\'].$grupo[ $sec_group ][\'g_title\'].$grupo[ $sec_group ][\'suffix\'];\n				}\n			}\n			\n			if ( count( $g_others ) )\n            {\n				$author[\'other_groups\'] = implode( \", \", $g_others );\n            }\n		}\n\n		if ( count( $g_others ) )\n		{\n			$text1 = \"<li><span class=\'ft\'>Others:</span><span class=\'fc\'>\";\n			$text2 = \"</span></li>\";\n		\n			$author[\'_group_formatted\'] .= $text1.$author[\'other_groups\'].$text2;\n		}\n		\n		return parent::userInfoPane( $author, $contentid, $options );\n	}	\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('29', '13', 'sos31_othersgroups_profiles_ff8a54f5cf94e5f10f893ba11a4defb6.php', 'sos31_othersgroups_profiles.php', 'skinHooks', 'sos31_othersgroups_profiles', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:12:\"skin_profile\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', 'class sos31_othersgroups_profiles extends skin_profile(~id~)\n{	\n	public function showCard( $member, $download=0 )\n	{\n		$grupos = array();\n   \n      	if ( $member[\'mgroup_others\'] )\n      	{\n        	$grupos = explode( \",\", IPSText::cleanPermString( $member[\'mgroup_others\'] ) );\n\n			$grupo = ipsRegistry::cache()->getCache( \'group_cache\' );\n			\n			foreach ( $grupos as $sec_group )\n			{\n	        	if ( $sec_group != $member[\'member_group_id\'] )\n				{\n					$g_others[] = $grupo[ $sec_group ][\'prefix\'].$grupo[ $sec_group ][\'g_title\'].$grupo[ $sec_group ][\'suffix\'];\n				}\n			}\n			\n			if ( count( $g_others ) )\n            {\n				$member[\'other_groups\'] = implode( \", \", $g_others );\n            }\n		}\n\n		$member[\'g_title\'] = $this->caches[\'group_cache\'][ $member[\'member_group_id\'] ][\'prefix\'].$this->caches[\'group_cache\'][ $member[\'member_group_id\'] ][\'g_title\'].$this->caches[\'group_cache\'][ $member[\'member_group_id\'] ][\'suffix\'];\n		\n		if ( count( $g_others ) )\n		{\n			$text1 = \"<dt>Others:</dt><dd>\";\n			$text2 = \"</dd>\";\n		\n			$member[\'g_title\'] .= $text1.$member[\'other_groups\'].$text2;\n		}\n\n		\n		return parent::showCard( $member, $download );\n	}\n\n	public function profileModern( $tabs=array(), $member=array(), $comments=\'\', $friends=array(), $visitors=array(), $default_tab=\'status\', $default_tab_content=\'\' )\n	{\n		$grupos = array();\n   \n      	if ( $member[\'mgroup_others\'] )\n      	{\n        	$grupos = explode( \",\", IPSText::cleanPermString( $member[\'mgroup_others\'] ) );\n\n			$grupo = ipsRegistry::cache()->getCache( \'group_cache\' );\n			\n			foreach ( $grupos as $sec_group )\n			{\n	        	if ( $sec_group != $member[\'member_group_id\'] )\n				{\n					$g_others[] = $grupo[ $sec_group ][\'prefix\'].$grupo[ $sec_group ][\'g_title\'].$grupo[ $sec_group ][\'suffix\'];\n				}\n			}\n			\n			if ( count( $g_others ) )\n            {\n				$member[\'other_groups\'] = implode( \", \", $g_others );\n		\n				$text1 = \"<dt>Others:</dt><dd>\";\n				$text2 = \"</dd>\";\n		\n				$member[\'g_title\'] .= $text1.$member[\'other_groups\'].$text2;\n            }\n		}\n		\n		return parent::profileModern( $tabs, $member, $comments, $friends, $visitors, $default_tab, $default_tab_content );\n	}\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('23', '11', 'statusLikeJavascript_0b2e2f83c877c5d47b0da8c662806afc.php', 'statusLikeJavascript.php', 'commandHooks', 'statusLikeJavascript', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:27:\"public_forums_forums_boards\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', null);
INSERT INTO `ibf_core_hooks_files` VALUES ('24', '11', 'statusLikeAjaxNotifications_5a6c043ad009ec93fc26b8d9acb6f67c.php', 'statusLikeAjaxNotifications.php', 'commandHooks', 'statusLikeAjaxNotifications', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:26:\"public_members_ajax_status\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', null);
INSERT INTO `ibf_core_hooks_files` VALUES ('25', '11', 'statusLikeNotifications_570fa8743f1897a28ac95b609c8a11b8.php', 'statusLikeNotifications.php', 'commandHooks', 'statusLikeNotifications', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:29:\"public_members_profile_status\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', null);
INSERT INTO `ibf_core_hooks_files` VALUES ('26', '11', 'statusLike_74713455291ad586c22e1ca0e7c47fb4.php', 'statusLike.php', 'templateHooks', 'statusLike', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:12:\"skin_profile\";s:12:\"skinFunction\";s:13:\"statusUpdates\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:9:\"canDelete\";s:8:\"position\";s:11:\"pre.startif\";}', null);
INSERT INTO `ibf_core_hooks_files` VALUES ('27', '12', 'tbShowRepInTopicView_dd63baff1661653099d31b15c0cda24e.php', 'tbShowRepInTopicView.php', 'skinHooks', 'tbShowRepInTopicView', 'a:6:{s:15:\"classToOverload\";s:11:\"skin_global\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', '/**\n * Invision Byte\n * (T30) Show Reputation in Topic View\n *\n * Skin Overloader\n *\n * @author		Terabyte\n * @copyright	(c) 2006 - 2010 Terabyte\n * @link		http://www.invisionbyte.net/\n * @since		03/07/2009\n * @updated		17/04/2010\n * @version		1.1.0 (11000)\n */\n\nclass tbShowRepInTopicView extends skin_global(~id~)\n{\n    public function userInfoPane( $author, $contentid, $options )\n    {\n    	$output = parent::userInfoPane( $author, $contentid, $options );\n    	\n    	if ( $this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\'] && isset($author[\'pp_reputation_points\']) )\n    	{\n    		if ( $this->settings[\'tb_srtv_groups\'] == \'\' || !in_array( $this->memberData[\'member_group_id\'], explode(\',\', $this->settings[\'tb_srtv_groups\']) ) )\n    		{\n    			$output .= parent::tbSrtvHook( $author );\n   			}\n        }\n        \n        return $output;\n    }\n}');
INSERT INTO `ibf_core_hooks_files` VALUES ('32', '14', 'ajaxFastReplyJS_fde842a5fba5ae6b15b388c579a5b4ef.php', 'ajaxFastReplyJS.php', 'templateHooks', 'ajaxFastReplyJS', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:10:\"skin_topic\";s:12:\"skinFunction\";s:17:\"topicViewTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:9:\"fastReply\";s:8:\"position\";s:9:\"pre.endif\";}', '<?php\n\nclass ajaxFastReplyJS\n{\n	protected $registry;\n	protected $request;\n	protected $DB;\n	protected $settings;\n	protected $memberData;\n	\n	public function __construct()\n	{\n		$this->registry			= ipsRegistry::instance();\n		$this->settings			=& $this->registry->fetchSettings();\n		$this->memberData	=& $this->registry->member()->fetchMemberData();\n	}\n	\n	public function getOutput()\n	{\n		if ( $this->settings[\'en30_ajaxfastreply\'] )\n		{\n			if ( ! in_array( $this->memberData[\'member_group_id\'], explode( \",\", $this->settings[\'en30_nonajaxgroups\'] ) ) )\n			{\n				$forum = $this->registry->output->getTemplate(\'topic\')->functionData[\'topicViewTemplate\'][0][\'forum\'];\n				\n				if ( ! in_array( $forum[\'id\'], explode( \",\", $this->settings[\'en30_nonajaxforums\'] ) ) )\n				{\n					return $this->registry->getClass(\'output\')->getTemplate(\'topic\')->ajaxFastReplyJS();\n				}\n			}\n		}\n	}\n}\n\n?>');
INSERT INTO `ibf_core_hooks_files` VALUES ('33', '14', 'ajaxFastReplyRedirectHandler_d0ae6eae04804ef7b42ad875622e78f6.php', 'ajaxFastReplyRedirectHandler.php', 'commandHooks', 'ajaxFastReplyRedirectHandler', 'a:8:{s:12:\"dataLocation\";s:0:\"\";s:14:\"libApplication\";s:0:\"\";s:15:\"classToOverload\";s:27:\"public_forums_forums_topics\";s:9:\"skinGroup\";N;s:12:\"skinFunction\";N;s:4:\"type\";N;s:2:\"id\";N;s:8:\"position\";N;}', '<?php\n\nclass ajaxFastReplyRedirectHandler extends (~extends~)\n{		\n	public function returnLastPost()\n	{\n		$st = 0;\n		\n		$mode 	= $this->topic_view_mode;\n		\n		$pre	= $mode != \'threaded\' ? \'st\' : \'start\';\n		\n		if( $mode == \'threaded\' )\n		{\n			$this->settings[\'display_max_posts\'] = $this->settings[\'threaded_per_page\'] ;\n			$this->request[\'st\'] =  $this->request[\'start\'] ;\n		}		\n			\n		if ($this->topic[\'posts\'])\n		{\n			if ( (($this->topic[\'posts\'] + 1) % $this->settings[\'display_max_posts\']) == 0 )\n			{\n				$pages = ($this->topic[\'posts\'] + 1) / $this->settings[\'display_max_posts\'];\n			}\n			else\n			{\n				$number = ( ($this->topic[\'posts\'] + 1) / $this->settings[\'display_max_posts\'] );\n				$pages = ceil( $number);\n			}\n			\n			$st = ($pages - 1) * $this->settings[\'display_max_posts\'];\n			\n			if( $this->settings[\'post_order_sort\'] == \'desc\' )\n			{\n				$st = (ceil(($this->topic[\'posts\']/$this->settings[\'display_max_posts\'])) - $pages) * $this->settings[\'display_max_posts\'];\n			}\n		}\n		\n		$this->DB->build( array( \n										\'select\' => \'pid\',\n										\'from\'   => \'posts\',\n										\'where\'  => \"queued=0 AND topic_id=\".$this->topic[\'tid\'],\n										\'order\'  => $this->settings[\'post_order_column\'].\' DESC\',\n										\'limit\'  => array( 0,1 )\n							)	  );\n							 \n		$this->DB->execute();\n		\n		$post = $this->DB->fetch();\n		\n		$this->registry->output->silentRedirect($this->settings[\'base_url\'].\"showtopic=\".$this->topic[\'tid\'].\"&pid={$post[\'pid\']}&{$pre}={$st}\", $this->topic[\'title_seo\'] );\n	}\n}\n\n?>');
INSERT INTO `ibf_core_hooks_files` VALUES ('34', '15', 'facebookLikeBox_0b52d2e5128faf87d122c0a8abad2c4d.php', 'facebookLikeBox.php', 'templateHooks', 'facebookLikeBox', 'a:7:{s:12:\"dataLocation\";s:0:\"\";s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}', '<?php\n\n/**\n * Product Title:		(IM) Facebook Like Box\n * Product Version:		1.0.1\n * Author:				Michael McCune\n * Website:				Coders Refuge\n * Website URL:			http://www.codersrefuge.com/\n * Email:				michael.mccune@gmail.com\n */\n\nclass facebookLikeBox\n{\n	public $registry;\n	\n	public function __construct()\n	{\n		$this->registry =  ipsRegistry::instance();\n		$this->settings =& $this->registry->fetchSettings();\n	}\n	\n	public function getOutput()\n	{\n		/* INIT */\n		$extra  = array();\n		$_extra = \'\';\n		\n		/* Build the extra settings */\n		if ( $this->settings[\'flbWidth\'] )\n		{\n			$extra[] = \'width=\"\' . $this->settings[\'flbWidth\'] . \'\"\';\n		}\n		if ( $this->settings[\'flbConnections\'] )\n		{\n			$extra[] = \'connections=\"\' . $this->settings[\'flbConnections\'] . \'\"\';\n		}\n		if ( !$this->settings[\'flbStream\'] )\n		{\n			$extra[] = \'stream=\"false\"\';\n		}\n		if ( !$this->settings[\'flbHeader\'] )\n		{\n			$extra[] = \'header=\"false\"\';\n		}\n		\n		/* Did we customize this? */\n		if ( count( $extra ) )\n		{\n			$_extra .= \' \' . implode( \' \', $extra );\n		}\n		\n		/* Return */\n		return $this->registry->output->getTemplate( \'boards\' )->hookFacebookLikeBox( $_extra );\n	}	\n}');
