INSERT INTO `ibf_core_sys_conf_settings` VALUES ('1', 'Включить WebDav', 'Разрешить внешнее редактирование стилей', '1', 'yes_no', 'webdav_on', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('2', 'Регистрационный ключ', 'Это регистрационный ключ IP.Board, а не ваш код клиента или пароль  для входа в клиент-центр. \n\nКлюч вы получаете вместе с письмом об активации вашей покупки IP.Board.\n\n<br />НЕ УДАЛЯЙТЕ ИЛИ РЕДАКТИРУЙТЕ ДАННЫЙ КЛЮЧ, ЕСЛИ ВЫ НЕ УВЕРЕНЫ В СВОИХ ДЕЙСТВИЯХ!', '2', 'input', 'ipb_reg_number', '12345-12345-12345-12345', '', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('3', 'Мета тег: image_src', 'Facebook используют данный тег при публикации и/или синхронизации содержимого. Максимальные размеры изображения 130px x 110px. Макрос {style_image_url} может использоваться для указания URL до директории изображений стиля.', '3', 'input', 'meta_imagesrc', '', '{style_image_url}/meta_image.png', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('4', 'Название форума', 'Используется в навигационном меню, заголовке страницы, письмах с форума.', '3', 'input', 'board_name', 'OnLineage2.COM - Форумы (Rise of Darkness)', 'Invision Power Board', '', '', '1', '1', 'Названия и адреса', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('5', 'Название сайта', 'Показывается в навигационном меню форума.', '3', 'input', 'home_name', 'Главная страница сайта', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('6', 'Адрес сайта', '', '3', 'input', 'home_url', 'http://OnLineage2.COM', '', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('7', 'Action формы загрузок', '<b>Необязательно для заполнения</b>\n<br />Опция позволяет переопределить значение домена в action формы загрузок.  Данная настройка может быть полезна для форумов, работающих на нескольких серверах, в целях распределения нагрузки.<br />\nПример значения поля: http://master.mysite.ru/forums', '3', 'input', 'upload_domain', '', '', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('8', 'URL к директории загрузок', 'URL адрес, ведущий к вашей директории \"uploads\".\n<!--SUGGEST-->', '3', 'input', 'upload_url', 'http://onlineage2.com/forum/uploads', '', '', 'if( $show == 1 )\n{\n	$this_host   = getenv( \'SERVER_NAME\' );\n	$this_script = getenv( \'SCRIPT_NAME\' );\n	$this_script = str_replace( \"&#092;&#092;&#092;&#092;\", \"/\", $this_script );\n\n	if( $this_host AND $this_script )\n	{\n		$this_script = str_replace( \'/\'.CP_DIRECTORY.\'/index.php\', \'/uploads\', $this_script );\n		$r[\'conf_description\'] = str_replace( \"<!--SUGGEST-->\", \"<br />IP.Board определил URL к директории загрузок так: <strong>http://\".$this_host.$this_script . \'</strong>\', $r[\'conf_description\'] );\n	}\n}', '1', '5', 'Пути и адреса форума', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('9', 'Путь до директории загрузок', 'Вводите абсолютный (полный) путь до директории загрузок \"uploads\". Важно понимать, что это не URL.\n<!--SUGGEST-->', '3', 'input', 'upload_dir', '/var/www/forum/uploads', '', 'upload_dir', 'if( $show == 1 )\n{\n	$this_script = str_replace( \'&#092;&#092;&#092;&#092;\', \'/\', getenv( \'SCRIPT_FILENAME\' ) );\n 	\n	if( $this_script )\n	{\n		$this_script = str_replace( \'/\'.CP_DIRECTORY.\'/index.php\', \'/uploads\', $this_script );\n 		$r[\'conf_description\'] = str_replace( \"<!--SUGGEST-->\", \"<br />IP.Board определил следующий путь к директории загрузок: <strong>\".$this_script . \'</strong>\', $r[\'conf_description\'] );\n	}\n}', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('10', 'Путь до директории кеша', '<b>Необязательно для заполнения</b>\n<br />Опция позволяет определить путь до директории, где расположены поддиректории skin_cache, style_avatars, style_emoticons, style_images. Данная настройка может быть полезна для форумов, работающих на нескольких серверах, в целях распределения нагрузки.<br />\nПример значения поля: /home/srv/clustered_data/forums/\n', '3', 'input', 'ipb_cache_path', '', '', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('11', 'URL к директории кеша', '<b>Необязательно для заполнения</b>\n    <br />\n    Если вы изменили «Путь до директории кеша», необходимо также указать и URL до него.', '3', 'input', 'ipb_cache_url', '', '', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('12', 'Сжать javascript?', 'Вы можете включить сжатие javascript и CSS для уменьшения HTTP запросов к серверу.<br />\nОпция не работает, если включена загрузка javascript из Google.', '3', 'yes_no', 'use_minify', '', '1', '', '', '1', '8', '', '1', 'minify, reduce, compress, javascript');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('13', 'URL к директории изображений', '<b>Необязательно для заполнения</b>\n<br />URL адрес, ведущий к изображениям, используемым в стиле форума (style_images). Данная настройка может быть полезна для форумов, работающих на нескольких серверах, в целях распределения нагрузки.<br />\nПример заполнения поля: http://img.domain.ru/forums/', '3', 'input', 'ipb_img_url', '', '', '', 'if( $save == 1 && $value )\n{\n		/* Flag skins for recache */\n		require_once( IPS_ROOT_PATH . \'sources/classes/skins/skinFunctions.php\' );\n		require_once( IPS_ROOT_PATH . \'sources/classes/skins/skinCaching.php\' );\n		$skinCaching	= new skinCaching( $this->registry );\n		\n		/* Flag all for recache */\n		$skinCaching->flagSetForRecache();\n}', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('14', '&quot;Название&quot; владельца лицензии', 'Это имя будет выведено в&nbsp;строке &laquo;Лицензия зарегистрирована на:&raquo; <br />Например: <em>Иван&nbsp;Иванов</em>,&nbsp;<em>IBResource</em>', '3', 'input', 'ipb_reg_name', '', '', '', '', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('15', 'Режим отладки', 'Опция позволяет настроить детальность информации, выводимой внизу страниц форума', '3', 'dropdown', 'debug_level', '', '0', '0=0: Отключен&#13;\n1=1: Выводить уровень загрузки сервера, время генерации страницы и число запросов&#13;\n2=2: Выводить информацию уровня 1 плюс данные из GET и POST&#13;\n3=3: Выводить информацию уровня 2 плюс запросы к базе данных', '', '1', '11', 'Прочие настройки', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('16', 'Убрать ссылку на форум из навигации', 'Если пользователь находится в приложении, отличающемся от форума, ссылка на главную страницу форума будет убрана. \nНапример, до отключения опции навигация выглядит так:\nInvision Power Board> Список пользователей\n\nпосле - так:\nСписок пользователей', '3', 'yes_no', 'remove_forums_nav', '', '0', '', '', '1', '99', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('17', 'Антиспам-сервис', 'Желаете удалять старые записи из журнала работы с анти-спам сервисом (по умолчанию через 30 дней)', '4', 'yes_no', 'ipb_prune_spam', '', '1', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('18', 'Посещения поисковых ботов', 'Желаете удалять старые записи из журнала посещений поисковых ботов (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_spider', '', '1', '', '', '1', '10', 'Очистка журналов', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('19', 'Менеджер задач', 'Желаете удалять старые записи из журнала менеджера задач (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_task', '', '1', '', '', '1', '20', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('20', 'Действия администраторов', 'Желаете удалять старые записи из журнала действий администраторов (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_admin', '', '0', '', '', '1', '30', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('21', 'Действия модераторов', 'Желаете удалять старые записи из журнала действий модераторов (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_mod', '', '0', '', '', '1', '40', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('22', 'E-mail отправления', 'Желаете удалять старые записи из журнала e-mail отправлений (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_email', '', '1', '', '', '1', '50', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('23', 'E-mail ошибки', 'Желаете удалять старые записи из журнала e-mail ошибок (по умолчанию через 30 дней)??', '4', 'yes_no', 'ipb_prune_emailerror', '', '1', '', '', '1', '60', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('24', 'SQL ошибки', 'Желаете удалять старые записи из журнала SQL ошибок (по умолчанию через 30 дней)?', '4', 'yes_no', 'ipb_prune_sql', '', '1', '', '', '1', '70', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('25', 'Попытки входа в админцентр', 'Желаете удалять старые записи из журнала попыток входа в админцентр (по умолчанию через 30 дней)?', '4', 'yes_no', 'prune_admin_login_logs', '', '1', '', '', '1', '80', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('26', 'Общие ошибки (error_log)', 'Желаете удалять старые записи из журнала общих ошибок (по умолчанию через 30 дней)?', '4', 'yes_no', 'prune_error_logs', '', '1', '', '', '1', '90', '', '1', 'prune, error, logs');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('27', 'Записывать ошибки', 'Записывать все ошибки выбранного уровня.', '4', 'dropdown', 'error_log_level', '', '4', '0=Не записывать никаких общих ошибок&#13;\n1=Записывать абсолютно все ошибки&#13;\n2=Записывать все ошибки 1 уровня и выше&#13;\n3=Записывать все ошибки 2 уровня и выше&#13;\n4=Записывать все ошибки 3 уровня и выше&#13;\n5=Записывать все ошибки 4 уровня и выше&#13;\n6=Записывать все ошибки 5 уровня', '', '1', '100', 'Журнал ошибок', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('28', 'Уведомление администратору', 'Уведомлять на e-mail для входящих писем о записи ошибок.', '4', 'dropdown', 'error_log_notify', '', '0', '0=Не уведомлять вообще&#13;\n1=Уведомлять обо всех ошибках&#13;\n2=Уведомлять об ошибках 1 уровня и выше&#13;\n3=Уведомлять об ошибках 2 уровня и выше&#13;\n4=Уведомлять об ошибках 3 уровня и выше&#13;\n5=Уведомлять об ошибках 4 уровня и выше&#13;\n6=Уведомлять об ошибках 5 уровня', '', '1', '110', '', '1', 'email, admin, notify, error, log');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('29', 'Включить соединение с Вконтакте?', 'Первоначально вам НЕОБХОДИМО создать приложение Вконтакте. Сделать это можно <a href=\"http://vkontakte.ru/apps.php?act=add&site=1\">здесь</a>', '28', 'yes_no', 'vk_enabled', '1', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('30', 'ID приложения', 'ID выдается после создания приложения Вконтакте.', '28', 'input', 'vk_api_id', '2972532', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('31', 'Защищенный ключ', 'Защищенный ключ выдается после создания приложения Вконтакте', '28', 'input', 'vk_secret', 'ei74wgc4yXkRWWtRBxMo', '', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('32', 'Пользовательская группа по умолчанию', 'В эту группу будут попадать все пользователи, создавшие свой аккаунт на форуме через аккаунт Вконтакте. Опция не распространяет своего действия на пользователей, которые добавили свой Вконтакте аккаунт после обычной регистрации на форуме.', '28', 'dropdown', 'vk_mgid', '', '3', '#show_groups#', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('33', 'Включить соединение с Facebook?', 'Первоначально вам НЕОБХОДИМО настроить сам Facebook.<br /?Для этого перейдите <a href=\"http://www.facebook.com/developers/editapp.php?new\">сюда</a>', '5', 'yes_no', 'fbc_enable', '1', '0', '', '', '1', '20', 'Facebook Connect', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('34', 'ID приложения', 'ID выдается после создания Facebook Application.', '5', 'input', 'fbc_appid', 'OnLineage2', '', '', '', '1', '21', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('35', 'Приватный ключ', 'Данный ключ показывается как \"Секретно\" после создания Facebook Application.', '5', 'input', 'fbc_secret', 'NH6HRXF7QA', '', '', '', '1', '22', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('36', 'Facebook обработка &quot;Отображаемого имения&quot;', 'Какое имя использовать в качестве отображаемого, при создании учетной записи на форуме и входе через Facebook.', '5', 'dropdown', 'fb_realname', '', 'any', 'any=на выбор пользователя\r\nprefilled=на выбор пользователя, но заполнить данными имени из facebook\r\nenforced=использовать имя из facebook', '', '1', '24', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('37', 'Пользовательская группа по умолчанию', 'В эту группу будут попадать все пользователи, создавшие свой аккаунт на форуме через аккаунт Facebook. Опция не распространяет своего действия на пользователей, которые добавили свой Facebook аккаунт после обычной регистрации на форуме.', '5', 'dropdown', 'fbc_mgid', '', '3', '#show_groups#', '', '1', '25', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('38', ' &quot;Локаль&quot; Facebook Javascript', 'Какую локаль необходимо использовать для виджетов Facebook. Полный список локалей: http://wiki.developers.facebook.com/index.php/Facebook_Locales', '5', 'input', 'fb_locale', '', 'ru_RU', '', '', '1', '26', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('39', 'Группа для Facebook &quot;Bot&quot;', 'Facebook проверяет страницу с материалом при использовании кнопок «Мне нравится» и «Поделиться». Укажите группу, в которую будет попадать робот, зашедший для проверки на форум . Например, если для гостей у вас скрыта часть форумов, то стоит выставить группу «Пользователи».', '5', 'multi', 'fbc_bot_group', '', '2', '#show_groups#', '', '1', '27', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('40', 'Включить интеграцию с Twitter', 'Вам также необходимо настроить Twitter приложение <a href=\"http://twitter.com/oauth_clients\">здесь</a>', '5', 'yes_no', 'tc_enabled', '', '0', '', '', '1', '30', 'Интеграция с Twitter', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('41', 'Consumer Secret', '', '5', 'input', 'tc_secret', '', '', '', '', '1', '31', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('42', 'Consumer Key', '', '5', 'input', 'tc_token', '', '', '', '', '1', '32', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('43', 'Пользовательская группа по умолчанию', 'В эту группу будут попадать все пользователи, создавшие свой аккаунт на форуме через аккаунт Twitter. Опция не распространяет своего действия на пользователей, которые добавили свой Twitter аккаунт после обычной регистрации на форуме.', '5', 'dropdown', 'tc_mgid', '', '3', '#show_groups#', '', '1', '33', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('44', 'Включить возможность делиться ссылками', 'На страницах с контентом будут добавлены ссылки для публикации контента в различных сервисах. Данная возможность может быть отключена для конкретных форумов непосредственно в настройках самих форумов.', '5', 'yes_no', 'sl_enable', '', '1', '', '', '1', '40', 'Публикация контента в сервисах', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('45', 'Разрешить список опубликованных материалов', 'Так как нет возможности проверять права доступа для опубликованных на сервисах материалов вы можете полностью отключить отображение списков таких материалов.', '5', 'yes_no', 'sl_publicdata', '', '1', '', '', '1', '41', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('46', 'Метод отправки почты', 'Выберите способ, которым будет отправляться почта с форума. Если PHP функция mail() не работает или не доступна, используйте SMTP. Если вы не уверены, что необходимо выбрать в данном параметре, проконсультируйтесь с вашим хостинг-провайдером.', '6', 'dropdown', 'mail_method', '', 'mail', 'mail=PHP Mail()\r\nsmtp=SMTP', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('47', 'Отправлять HTML форматированные сообщения', '', '6', 'yes_no', 'email_use_html', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('48', 'Email адрес для писем', 'На этот email будут приходить все письма', '6', 'input', 'email_in', 'support@onlineage2.com', '', '', '', '1', '2', 'Email Addresses', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('49', 'Email адрес для поля От', 'Данный email будет виден в поле От, во всех письмах, пришедших от форума.', '6', 'input', 'email_out', 'support@onlineage2.com', '', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('50', 'Адрес сервера', 'По умолчанию \'localhost\'', '6', 'input', 'smtp_host', '', 'localhost', '', '', '1', '4', 'SMTP Set-up', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('51', 'Порт сервера', 'По умолчанию 25', '6', 'input', 'smtp_port', '', '25', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('52', 'Использовать &#39;&lt;&#39; и &#39;&gt;&#39; в &#39;to&#39; и &#39;from&#39; адресах?', 'Некоторые SMTP сервера требуют особого формата адресов. Если у вас есть проблема с отправкой писем, попробуйте включить или отключить эту опцию', '6', 'yes_no', 'mail_wrap_brackets', '', '0', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('53', 'Имя пользователя на сервере', 'В случае использования \'localhost\' обычно не требуется.', '6', 'input', 'smtp_user', '', '', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('54', 'Пароль пользователя', 'В случае использования \'localhost\' обычно не требуется.', '6', 'input', 'smtp_pass', '', '', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('55', 'Дополнительные опции для функции', 'Вы можете добавить дополнительные опции, которые будут переданы параметром в функцию Mail().\nНапример: -femail@address.com задаст принудительное значение \'From\' для всех писем.', '6', 'input', 'php_mail_extra', '', '', '', '', '1', '9', 'PHP Mail Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('56', 'Настройка SMTP HELO', 'Выберите тип, необходимый для вашего SMTP сервера.', '6', 'dropdown', 'smtp_helo', '', 'HELO', 'HELO=HELO\r\nEHLO=EHLO', '', '1', '9', '', '1', 'helo ehlo');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('57', 'Включить IP.Converge?', 'Если опция включена, IPB будет производить идентификацию через  IP.Converge.', '7', 'yes_no', 'ipconverge_enabled', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('58', 'Адрес IP.Converge', 'Корневой URL адрес приложения IP.Converge.', '7', 'input', 'ipconverge_url', '', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('59', 'Идентификационный номер (Product ID) IP.Converge', 'Номер, полученный от IP.Converge сервера.', '7', 'input', 'ipconverge_pid', '', '', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('60', 'Включить XML-RPC API', 'При включении данной системы программы-клиенты смогут использовать XML-RPC интерфейс форума.', '8', 'yes_no', 'xmlrpc_enable', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('61', 'Журналирование', 'Позволяет указать тип записей для журнала XML-RPC. Если вы выбираете Все, то в журнал записываются все запросы XML-RPC, если - Ошибки, то в журнал записываются проблемные запросы.', '8', 'dropdown', 'xmlrpc_log_type', '', 'all', 'all=Все\r\nfailed=Ошибки', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('62', 'Время жизни записей журнала', 'За какой промежуток времени хранить записи журнала. Например, если вы введете значение опции 30, то в журнале будут записи за последние 30 дней.', '8', 'input', 'xmlrpc_log_expire', '', '30', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('63', 'Разрешить X_FORWARDED_FOR?', 'Если данная опция включена, то система будет учитывать заголовки X_FORWARDED_FOR при получении IP-адреса пользователя. Это бывает полезно в Интранет сетях, когда REMOTE_ADDR один  и тот же для всех пользователей сети. Однако данный заголовок очень легко изменить, и этим фактом могут воспользоваться с целью подмены IP адреса.', '9', 'yes_no', 'xforward_matching', '', '0', '', '', '1', '11', 'Безопасность', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('64', 'Метод восстановления забытого пароля', 'Рекомендуем использовать метод \'Выслать по почте случайно сгенерированный пароль\', поскольку это самый безопасный метод.', '9', 'dropdown', 'lp_method', '', 'random', 'random=высылать по почте случайно сгенерированный пароль\r\nchoose=разрешить пользователю самому ввести новый пароль', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('65', 'Время жизни ключа авторизации пользователя', 'В течение указанного промежутка времени, ключ авторизации (он устанавливается в cookie пользователя) будет считаться действительным. По истечению указанного срока, пользователю выставляется новый ключ. Чем меньше временной интервал, тем больше защищены пользователи от кражи cookies.', '9', 'dropdown', 'login_key_expire', '', '7', '0=без срочный (не рекомендуется)\r\n3=истекает через 3 дня\r\n7=истекает через 7 дней\r\n30=истекает через 30 дней', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('66', 'Длительность сессии', 'Число секунд, проходящее до того, как сессия пользователя истечёт и будет удалена. Чем меньше это число, тем меньше шансов, что сессию перехватят.', '9', 'input', 'session_expiration', '', '3600', '', '', '1', '15', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('67', 'Учитывать IP адрес пользователя при проверке сессии?', 'Если функция включена, IP адрес пользователя должен совпадать со значением, хранимым в таблице сессий. Отключите данную функцию в интранете, когда многие пользователи имеют один и тот же IP адрес.', '9', 'yes_no', 'match_ipaddress', '', '1', '', '', '1', '16', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('68', 'Учитывать браузер пользователя при проверке сессии?', 'Данная функция еще более снижает вероятность перехвата сессии, но это значит, что сессия пользователя прекратиться, если он одновременно воспользуется несколькими браузерами.', '9', 'yes_no', 'match_browser', '', '0', '', '', '1', '17', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('69', 'Количество неудачных попыток авторизоваться', 'Количество неудавшихся попыток авторизоваться до того, как учетная запись будет заблокирована.<br />\n<b>Совет</b>: Установите 0, чтобы отключить функцию.', '9', 'input', 'ipb_bruteforce_attempts', '', '3', '', '', '1', '18', 'Защита от перебора паролей', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('70', 'Сбрасывать счетчик неудачных попыток через Х минут', 'Через сколько минут сбросить счет неудачных попыток авторизации? <br />\n<b>Совет</b>: Установите 0, чтобы не сбрасывать неудавшиеся попытки. <!-- locked -->', '9', 'input', 'ipb_bruteforce_period', '', '15', '', '', '1', '19', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('71', 'Автоматически разблокировать учетную запись?', 'Если запись заблокирована из-за неудачных попыток авторизации, можно разблокировать учетную запись через определенный промежуток времени после неудачных попыток.<br />\n<b>Совет</b>: Отключение данной функции потребует разблокировать учетные записи вручную во вкладке Система.', '9', 'yes_no', 'ipb_bruteforce_unlock', '', '1', '', '', '1', '20', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('72', 'Убрать ссылку на АЦ с форума?', 'Если функция активна, ссылка на АЦ не будет отображаться в заголовке форума. Полезно, если вы переименовали папку \'admin\'.', '9', 'yes_no', 'security_remove_acp_link', '', '0', '', '', '1', '24', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('73', 'Использовать https протокол для форм входа?', 'Использование протокола HTTPS, позволяет защитить передачу логина и пароля. Использовать данную опцию можно только в случае правильной настройки web-сервера.', '9', 'yes_no', 'logins_over_https', '', '0', '', '', '1', '25', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('74', 'Использовать активацию учетных записей пользователей?', 'Администратор может вручную утверждать все новые учетные записи или установить проверку электронных адресов пользователей. Если установлен метод проверки \"Активация по e-mail, затем администратором\", то пользователь получает проверочное электронное письмо. При успешной активации, пользователь попадает в очередь на утверждение администратором.', '9', 'dropdown', 'reg_auth_type', '0', 'user', 'admin_user=активация по e-mail, затем администратором\r\nuser=активация пользователем по e-mail\r\nadmin=активация администратором\r\n0=нет', '', '1', '26', 'Безопасность [работа с пользователями]', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('75', 'Удалять неактивированные учетные записи после X дней', 'Включение этой опции позволяет удалять все учётные записи автоматически, если они не были активированы в течение указанного количества дней. Введите 0, чтобы не удалять автоматически неподтвержденные регистрации.', '9', 'input', 'validate_day_prune', '', '0', '', '', '1', '27', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('76', 'Уведомлять при регистрации нового пользователя?', 'Включение опции позволяет уведомлять администрацию о каждой новой регистрации пользователя на форуме.', '9', 'yes_no', 'new_reg_notify', '', '0', '', '', '1', '28', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('77', 'Заставлять посетителей авторизоваться, чтобы увидеть форум?', 'Если эта настройка включена, посетители должны будут либо авторизоваться, либо зарегистрироваться перед тем, как продолжить просмотр форума.', '9', 'yes_no', 'force_login', '1', '0', '', '', '1', '32', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('78', 'Отключить регистрацию?', 'Включение этой настройки полностью отключает возможность регистрации посетителей на форуме.', '9', 'dropdown', 'no_reg', '', '0', '0=нет\r\n1=только внутреннюю\r\n2=все возможные методы регистрации', '', '1', '33', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('79', 'Удалять коды chr(0xCA) при вводе?', 'Символ chr(0xCA) может использоваться в качестве \'скрытого\' символа пробела для эмуляции зарегистрированных имен – <strong>может стать причиной пропадания символов в сообщениях в кодировках, отличных от западной</strong>.', '9', 'yes_no', 'strip_space_chr', '', '0', '', '', '1', '34', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('80', 'Флуд-контроль — интервал задержки', 'Заставит пользователей подождать перед размещением следующего сообщения.<br>Если оставить настройку пустой, флуд-контроль будет отключён. Не относится к пользователям, принадлежащим к группе, которой разрешено обходить флуд-контроль.', '9', 'input', 'flood_control', '', '0', '', '', '1', '36', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('81', 'Разрешить пользователям просматривать список активных пользователей?', 'Если настройка включена, пользователи и посетители получат возможность просматривать списки активных пользователей. Темы и форумы, которые пользователь не имеет право просматривать, не показываются.', '9', 'yes_no', 'allow_online_list', '', '1', '', '', '1', '37', 'Приватность', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('82', 'Отключить возможность анонимной авторизации?', 'Если опция включена, то пользователи не увидят опцию \"Скрытность\" в форме входа.', '9', 'yes_no', 'disable_anonymous', '', '0', '', '', '1', '38', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('83', 'Показывать версию IPB?', '', '9', 'yes_no', 'ipb_display_version', '', '1', '', '', '1', '40', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('84', 'Тип поиска', 'Вы можете использовать или традиционный тип или <a href=\"http://www.sphinxsearch.com/\">Sphinx</a> (если доступно).\n<!--FULLTEXT-->\n<br />\n<!--FULLCHECK-->', '10', 'dropdown', 'search_method', '', 'traditional', 'traditional=Традиционный\r\nsphinx=Sphinx', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('85', 'Включить полнотекстовый поиск?', 'Работает, если выбран традиционный тип поиска. Если база данных настроена некорректно, то полнотекстовый (fulltext) поиск может плохо искать по ключевым словам на русском языке.', '10', 'yes_no', 'use_fulltext', '', '1', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('86', 'Минимальная длина ключевого слова', 'Чем меньше минимальная длина, тем более возможны в результатах появление предлогов \'в\', \'на\', \'под\' и т.д.\n\nОбратите внимание, что эта настройка НЕ будет работать при включенном полнотекстовом режиме поиска.', '10', 'input', 'min_search_word', '', '4', 'min_search_word', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('87', 'Ограничить результаты поиска по темам и сообщениям', 'Укажите максимальное количество, возвращаемых поиском, результатов. Данное ограничение только для \'стандартного поиска\', но не для Sphinx.', '10', 'dropdown', 'search_hardlimit', '', '200', '100=100\r\n200=200\r\n300=300\r\n400=400\r\n500=500\r\n1000=1000', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('88', 'Количество отображаемых на одной странице результатов', 'Пол умолчанию 25.', '10', 'input', 'search_per_page', '', '25', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('89', 'Новые публикации должны использовать только SQL', 'При включении данной опции получение данных о новых публикациях будет выполняться только через SQL. Это позволяет убрать временной лаг при работе Sphinx.', '10', 'yes_no', 'force_sql_vnc', '', '1', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('90', 'Просмотр новых публикаций: игнорирование разделов', 'Выберите разделы, публикации из которых <b>не</b> будут отображаться в результатах \"просмотра новых публикаций\".\n\nЗажав клавишу Ctrl можно выбрать несколько разделов.', '10', 'multi', 'vnp_block_forums', '', '', '#show_forums#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'vnp_block_forums\']) )\n	{\n		$_POST[\'vnp_block_forums\'] = implode(\",\",$_POST[\'vnp_block_forums\']);\n	}\n	else\n	{\n		$_POST[\'vnp_block_forums\'] = \"\";\n	}\n	\n	$key = \'vnp_block_forums\';\n}\nif ( $show == 1 )\n{\n$key = \'vnp_block_forums[]\';\n}', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('91', 'Тип поиска словосочетаний', 'При типе \"ИЛИ\" в результатах поиска будут материалы, содержащие хотя бы одно слово, входящее в словосочетание.\n\nПри типе \"И\" в результатах будут только те материалы, которые содержат оба слова.\n\nОпция имеет силу только для «Традиционного» поиска', '10', 'dropdown', 's_andor_type', '', 'and', 'and=И\r\nor=ИЛИ', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('92', 'По умолчанию новыми публикациями считать:', '', '10', 'dropdown', 'default_vnc_method', '', 'unread', 'unread=Не прочитанное\r\nlastvisit=Новое с последнего посещения', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('93', 'Скрыть уведомление о полнотекстовом поиске?', 'Если вы используете традиционный и обычный тип поиска, а ваш SQL сервер поддерживает полнотекстовый поиск, то на главной странице админцентра будет отображаться соответствующее уведомление. Вы можете скрыть его, включив данную опцию.', '10', 'yes_no', 'hide_ftext_note', '', '0', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('94', 'Адрес сервера', 'Адрес вашего сервера Sphinx.\r\nПо умолчанию 127.0.0.1.', '10', 'input', 'search_sphinx_server', '', '127.0.0.1', '', '', '1', '10', 'Настройки Sphinx', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('95', 'Ограничить &quot;Темы/Сообщения этого пользователя&quot; результатами за X дней', 'Количество дней считается с момента последнего сообщения пользователя. Таким образом, если последний раз пользователь отправлял сообщение/тему в марте, и вы указали в настройках лимит в 30 дней, то поиск будет искать все темы/сообщения за февраль (т.е. 30-ю днями ранее последней даты отправки сообщения).', '10', 'input', 'search_ucontent_days', '', '365', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('96', 'Порт', 'Порт, используемый для соединения с вашим Sphinx сервером.\r\nПо умолчанию 3312.', '10', 'input', 'search_sphinx_port', '', '3312', '', '', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('97', 'Базовый путь', 'Базовый путь для индексов и логов Sphinx.', '10', 'input', 'sphinx_base_path', '', '/var/sphinx', '', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('98', 'Префикс для Sphinx индекса', 'Использование уникального префикса для индекса данного форума. Это позволяет использовать один Sphinx демон для нескольких форумов IP.Board', '10', 'input', 'sphinx_prefix', '', '', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('99', 'Включить поддержку расширенных запросов', 'При включении возможности расширенных запросов у пользователей появится возможность делать запросы вида \"ключ*\", в итоге будут найдено все, что содержит слова \"ключ\", \"ключи\", \"ключевой\" и подобное. На больших форумах включение данной опции может привести к падению скорости создания поискового индекса. После включения опции необходимо <a href=\'{ACP_URL}app=core&&core&module=applications&section=applications&do=build_sphinx\'>перестроить все Sphinx индексы</a>', '10', 'yes_no', 'sphinx_wildcard', '', '0', '', '', '1', '14', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('100', 'Кодировка страниц форума', 'Кодировка для всех HTML страниц системы. Мы настоятельно рекомендуем использовать UTF-8', '11', 'input', 'gb_char_set', 'utf-8', 'UTF-8', '', '', '1', '1', 'Кодировки', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('101', 'Способ перекодировки текста', 'Не все способы могут поддерживаться сервером', '11', 'dropdown', 'charset_conv_method', '', 'mb', 'internal=Внтренний\r\nmb=mb функции\r\nrecode=recode\r\niconv=iconv', '', '1', '2', '', '1', 'multibyte, utf8, utf-8, charset, recode, iconv, mb, internal');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('102', 'Отключить AJAX для текстов', 'Полезно для сайтов имеющих проблемы с неверным отображением символов национальных кодировок, не поддерживаемых PHP.', '11', 'yes_no', 'disable_text_ajax', '', '0', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('103', 'Включить безопасный режим для стилей?', 'В безопасном режиме работы стилей система подключает шаблоны стилей из базы данных. В обычном режиме, система использует шаблоны стилей из кеш-файлов, хранящихся в директории cache. Безопасный режим необходим в случае проблем с чтением стилей из кеш-файлов, например, когда появляются PHP ошибки, связанные с safemode и/или open_basedir.', '11', 'yes_no', 'safe_mode_skins', '', '0', '', '', '1', '4', 'Серверное окружение', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('104', 'Отключить GZIP?', 'GZIP позволяет быстрее отправлять страницы клиентам, сжимая их и экономя трафик, однако, не все серверы позволяют использовать данный формат, а некоторые серверы используют GZIP по умолчанию.', '11', 'yes_no', 'disable_gzip', '', '0', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('105', 'Принудительно отправлять HTTP заголовки?', '', '11', 'yes_no', 'print_headers', '', '1', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('106', 'Отправлять HTTP заголовки для отключения кеширования?', 'Данная опция отключит кеширование страниц форума браузерами<br /><b>Примечание</b>: Необходимо активировать опцию выше, чтобы данная настройка имела действие.', '11', 'yes_no', 'nocache', '', '1', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('107', 'Тип переадресации', 'Способы переадресации для браузера. Опция позволяет решить проблему не отображения страниц после отправки ответа, перехода к новой теме раздела и т.п', '11', 'dropdown', 'header_redirect', '', 'location', 'location=Location type (*nix savvy)\r\nrefresh=Refresh (Windows savvy)\r\nhtml=HTML META redirect (Если другие варианты не работают)', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('108', 'Имя пользователя', 'Это имя пользователя будет использоваться во всех .htaccess файлах.', '11', 'input', 'http_auth_username', '', '', '', '', '1', '12', 'HTTP авторизация', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('109', 'Пароль', 'Этот пароль будет использоваться во всех файлах .htaccess.', '11', 'input', 'http_auth_password', '', '', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('110', 'Домен', 'Используйте <u>.</u>domain.ru для установки cookies, которые будут действовать как на основном домене (domain.ru) так и на всех субдоменах данного домена.', '11', 'input', 'cookie_domain', '', '', '', '', '1', '500', 'Cookies', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('111', 'Префикс', 'Используйте префикс, если у вас установлено несколько форумов на одном домене.', '11', 'input', 'cookie_id', '', '', '', '', '1', '501', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('112', 'Путь', '', '11', 'input', 'cookie_path', '', '', '', '', '1', '502', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('113', 'Включить систему', 'Опция позволяет включить или отключить систему показа рекламы на форуме', '12', 'yes_no', 'ad_code_global_enabled', '', '0', '', '', '1', '1', 'Основные настройки', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('114', 'Группы без просмотра рекламы', 'Выбранные группы не будут видеть рекламу на форуме', '12', 'multi', 'ad_code_exempt_groups', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'ad_code_exempt_groups\']) )\n	{\n		$_POST[\'ad_code_exempt_groups\'] = implode(\",\",$_POST[\'ad_code_exempt_groups\']);\n	}\n	else\n	{\n		$_POST[\'ad_code_exempt_groups\'] = \"\";\n	}\n	\n	$key = \'ad_code_exempt_groups\';\n}\nif ( $show == 1 )\n{\n    $key=\'ad_code_exempt_groups[]\';\n}', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('115', 'Код для добавления в шапку', 'Данный код будет вставлен в шапку форума', '12', 'textarea', 'ad_code_global_header', '', '', '', '', '1', '3', '', '1', 'ad,advertisement,code,header');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('116', 'Код для добавления в подвал', 'Данный код будет добавлен в подвал форума', '12', 'textarea', 'ad_code_global_footer', '', '', '', '', '1', '4', '', '1', 'ad,code,advertisement,footer');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('117', 'Код для добавления в шапку', 'Данный код будет вставляться только на главной странице форума. Опция перекрывает значение, указанное в параметре «Код для добавления в шапку» основных настроек.', '12', 'textarea', 'ad_code_board_index_header', '', '', '', '', '1', '5', 'Главная страница', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('118', 'Код для добавления в подвал', 'Данный код будет вставляться только на главной странице форума. Опция перекрывает значение, указанное в параметре «Код для добавления в подвал» основных настроек.', '12', 'textarea', 'ad_code_board_index_footer', '', '', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('119', 'Код для добавления в боковую панель', 'Данный код будет вставлен в боковую панель главной страницы', '12', 'textarea', 'ad_code_board_sidebar', '', '', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('120', 'Код для добавления в шапку', 'Данный код будет вставляться только на странице тем форума. Опция перекрывает значение, указанное в параметре «Код для добавления в шапку» основных настроек.', '12', 'textarea', 'ad_code_forum_view_header', '', '', '', '', '1', '8', 'Страница форума', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('121', 'Код для добавления в подвал', 'Данный код будет вставляться только на странице тем форума. Опция перекрывает значение, указанное в параметре «Код для добавления в подвал» основных настроек.', '12', 'textarea', 'ad_code_forum_view_footer', '', '', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('122', 'Код для добавления после первой темы', 'Данный код будет вставлен после первой темы в списке тем форума', '12', 'textarea', 'ad_code_forum_view_topic_code', '', '', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('123', 'Код для добавления в шапку', 'Данный код будет вставляться только на странице темы форума. Опция перекрывает значение, указанное в параметре «Код для добавления в шапку» основных настроек.', '12', 'textarea', 'ad_code_topic_view_header', '', '', '', '', '1', '11', 'Страница темы', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('124', 'Код для добавления в подвал', 'Данный код будет вставляться только на странице темы форума. Опция перекрывает значение, указанное в параметре «Код для добавления в подвал» основных настроек.', '12', 'textarea', 'ad_code_topic_view_footer', '', '', '', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('125', 'Код для добавления после первого сообщения', 'Данный код будет добавлен после первого сообщения темы', '12', 'textarea', 'ad_code_topic_view_code', '', '', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('126', 'Система включена?', 'Включить или отключить систему тегов', '13', 'yes_no', 'tags_enabled', '', '1', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('127', 'Тип системы', 'Открытая система позволяет пользователям самим создавать теги. Закрытая - администраторы создают теги, пользователи их используют.', '13', 'dropdown', 'tags_open_system', '', '1', '1=Открытая (создание и добавление тегов на лету)&#13;\n0=Закрытая (использование только заранее созданных тегов)', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('128', 'Использование тегов как префиксов тем', '', '13', 'dropdown', 'tags_can_prefix', '', '1', '0=Запретить&#13;\n1=Только администраторам&#13;\n2=Всем кто имеет соответствующие права', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('129', 'Разрешенные теги', 'При использовании закрытого типа системы в данной настройке вы должны указать список тегов, которые можно использовать. Разделитель - запятая.', '13', 'textarea', 'tags_predefined', '', '', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('130', 'Преобразовывать имена тегов к нижнему регистру', '', '13', 'yes_no', 'tags_force_lower', '', '0', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('131', 'Минимальное количество тегов к записи', '0 - отключает ограничение.', '13', 'input', 'tags_min', '', '0', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('132', 'Максимальное количество тегов к записи', '0 - отключает ограничение', '13', 'input', 'tags_max', '', '10', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('133', 'Минимальная длина тега', '0 - отключает ограничение', '13', 'input', 'tags_len_min', '', '2', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('134', 'Макисмальная длина тега', '0 - отключает ограничение', '13', 'input', 'tags_len_max', '', '30', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('135', 'Проверять теги через фильтр нецензурных слов', '', '13', 'yes_no', 'tags_clean', '', '1', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('136', 'Лимит загрузки сервера', 'Когда загрузка достигает указанного предела, отображается «форум перегружен»<br>Вы можете отключить лимит, просто не заполняя данное поле.', '14', 'input', 'load_limit', '', '', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('137', 'Отключить кеширование (prefetch)?', 'Некоторые веб-оптимизаторы могут кешировать страницы перед запросом пользователя. Это существенно ускоряет загрузку страницы пользователем, однако, создает дополнительную нагрузку на сервер.', '14', 'yes_no', 'disable_prefetching', '', '1', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('138', 'Включить кеширование?', 'Если включить данную опцию, некоторые данные будут кешироваться для сохранения ресурсов сервера.', '14', 'yes_no', 'cc_on', '', '1', '', '', '1', '4', 'Кеширование содержимого', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('139', 'Кеширование сообщений', 'Введите количество дней, через которое кешируемые сообщения будет обновляться?<br/ >\nВведите 0 для отключения кеширования сообщений.', '14', 'input', 'cc_posts', '', '7', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('140', 'Кеширование подписей', 'Введите количество дней, через которое кешируемые подписи будет обновляться?<br /> Введите 0 для отключения кеширования подписей.', '14', 'input', 'cc_sigs', '', '180', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('141', 'Показывать дополнительные поля профиля при просмотре тем?', 'Если включить данную опцию форум будет использовать «тяжелый» запрос к базе данных «LEFT JOIN...», который сделает выборку необходимых данных из соответствующей таблицы.', '14', 'yes_no', 'custom_profile_topic', '', '1', '', '', '1', '8', 'Оптимизация ресурсов SQL сервера', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('142', 'Период отсутствия, через которое пользователь считается неактивным (в минутах)', '', '14', 'input', 'au_cutoff', '', '15', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('143', 'Немедленно обновлять просмотры темы?', 'Если данная опция включена, счетчик количества просмотров темы будет обновляться каждый раз, когда кто-нибудь просматривает данную тему. Если она отключена, то просмотры темы будут записываться в другую таблицу и обновляться каждые 3 часа. Это значительно уменьшит загрузку таблицы тем, если ваш форум очень посещаемый', '14', 'yes_no', 'update_topic_views_immediately', '', '0', '', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('144', 'Отмечать темы, в которые отвечал пользователь?', '', '14', 'yes_no', 'show_user_posted', '', '1', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('145', 'Удалять длительные поисковые запросы?', 'Количество секунд, после истечения которых, поисковый запрос будет удален.<br />\nВведите 0 для отключения удаления.', '14', 'input', 'kill_search_after', '', '30', '', '', '1', '14', '', '1', 'resources, search, kill');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('146', 'Отключить «Пользователи, просматривающие данный форум»?', 'Позволяет уменьшить количество запросов на 1 при каждом просмотре форума', '14', 'yes_no', 'no_au_forum', '', '0', 'no_au_forum', '', '1', '15', 'Отключение возможностей', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('147', 'Отключить «Пользователи, просматривающие данную тему»?', 'Позволяет уменьшить количество запросов на 1 при каждом просмотре темы', '14', 'yes_no', 'no_au_topic', '', '0', '', '', '1', '16', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('148', 'Показывать активных пользователей?', '', '14', 'yes_no', 'show_active', '', '1', '', '', '1', '17', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('149', 'Отключить краткое изложение темы?', 'Отключить отображение краткого изложения темы внизу страницы, на которой пишется ответ в тему?', '14', 'yes_no', 'disable_summary', '', '0', '', '', '1', '18', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('150', 'Разрешить пользователям пользоваться поиском?', '', '14', 'yes_no', 'allow_search', '', '1', '', '', '1', '19', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('151', 'Показывать статистику форума?', 'Отображение статистики форума внизу главной страницы.', '14', 'yes_no', 'show_totals', '', '1', '', '', '1', '21', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('152', 'Отключить статистику профилей?', 'Статистика посещений профилей пользователями на большом форуме может создавать большую нагрузку.', '14', 'yes_no', 'disable_profile_stats', '', '0', '', '', '1', '22', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('153', 'Отключить подфорумы на главной странице форума', 'Отключить отображение подфорумов на главной странице форума?', '14', 'yes_no', 'disable_subforum_show', '', '0', '', '', '1', '24', 'Уменьшение HTML кода', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('154', 'Подгружать javascript файлы из серверов Google', 'Включив эту функцию, некоторые javascript файлы будут загружаться из серверов Google, что позволит немного снизить нагрузку на ваш сервер.', '14', 'yes_no', 'remote_load_js', '', '0', '', '', '1', '26', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('155', 'Включить отслеживание прочитанных тем?', '', '14', 'yes_no', 'topic_marking_enable', '', '1', '', '', '1', '28', 'Отслеживание статуса прочитанных тем', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('156', 'Отключить отслеживание через Cookie', 'Даже если вы отключили систему отслеживания выше, форум будет продолжать отслеживать статусы с использованием cookies. Вы можете полностью отключить отслеживание, включив эту опцию, что позволит несколько разгрузить сервер при больших нагрузках.', '14', 'yes_no', 'topic_marking_noquery', '', '0', '', '', '1', '29', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('157', 'Перевести форум в режим offline?', 'Форум будет доступен только тем, кто имеет права для просмотра форума в режиме offline.\r\n(настраивается в правах групп пользователей)', '15', 'yes_no', 'board_offline', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('158', 'Сообщение', 'Данное сообщение будет выведено тем пользователям, которые не могут использовать форум в режиме offline.', '15', 'editor', 'offline_msg', 'Идет обновление баз данных', '', '', '', '1', '2', '', '0', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('159', 'Журналировать действия поисковых роботов?', 'Опция позволяет включить ведение подробного журнала посещения поисковым роботом вашего форума. Данную настройку имеет смысл включать на короткое время, только для анализа индексируемости вашего форума. При большом количестве поисковых роботов на вашем форуме, из-за этой настройки может возникнуть большая нагрузка на сервер.', '16', 'yes_no', 'spider_visit', '', '0', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('160', 'Показывать ботов в списке активных пользователей?', '', '16', 'yes_no', 'spider_active', '', '1', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('161', 'Перенаправление на новые URL?', 'Включение данной опции позволяет перенаправить посетителя, пришедшего по старому адресу, вида showxxxx=x, на новый ЧПУ адрес страницы.', '16', 'yes_no', 'seo_r_on', '', '0', '', '', '1', '14', 'Настройки ЧПУ', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('162', 'Тип URL', 'При типе URL «Путь» адреса будут иметь вид <b>/index.php/forum/2-news/</b><br />\nПри типе URL «Запрос» - <b>/index.php?/forum/2-news/</b><br /><br />\nВыбор типа ограничивается так же программным обеспечением сервера. Следует знать, что если используется веб сервер Apache и PHP его модуль, то можно использовать оба типа URL. Если же сервер на платформе Windows или PHP установлен как CGI, то использовать можно только тип «Запрос»', '16', 'dropdown', 'url_type', '', 'query_string', 'path_info=Путь&#13;\nquery_string=Запрос', 'if ( $show == 1 AND ! $this->settings[\'use_friendly_urls\'] )\n{\n	$r[\'conf_description\'] .= \"<div style=\'color:red\'>Внимание: ЧПУ не автивировано. Вам необходимо изменить \'conf_global.php\' и добавить в конец файла строку: <kbd>&#092;$INFO&#092;[\'use_friendly_urls\'&#092;]            = \'1\';</kdb></div>\";\n}', '1', '16', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('163', 'Использовать .htaccess mod_rewrite?', 'При включении этой опции необходимо будет создать файл .htaccess в корневой директории форума со следующим содержимым.<br />\n<!-- MOD_REWITE_EXAMPLE -->', '16', 'yes_no', 'htaccess_mod_rewrite', '', '0', '', 'if( $show == 1 )\n{\n	$r[\'conf_description\'] = str_replace( \'<!-- MOD_REWITE_EXAMPLE -->\', nl2br( $this->registry->adminFunctions->fetchModRewrite() ), $r[\'conf_description\'] );\n}', '1', '17', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('164', 'Title', 'Укажите текст, который будет использоваться в мета-теге title. Если оставить поле пустым, будет использоваться название форума.', '16', 'input', 'seo_index_title', '', '', '', '', '1', '19', 'Главная страница', '1', 'seo,title');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('165', 'Description', 'Укажите текст, который будет использоваться в мета-теге description', '16', 'textarea', 'seo_index_md', '', '', '', '', '1', '20', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('166', 'Keywords', 'Укажите текст, который будет использоваться в мета-теге keywords', '16', 'textarea', 'seo_index_mk', '', '', '', '', '1', '20', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('167', 'Показать ссылку на правила в подвале форума', '', '17', 'yes_no', 'gl_show', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('168', 'Название', '', '17', 'input', 'gl_title', '', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('169', 'Ссылка на страницу правил', 'Введите URL страницы, где расположены ваши правила или оставьте это поле пустым.', '17', 'input', 'gl_link', '', '', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('170', 'Если не используете ссылку на правила; введите текст правил здесь', 'Разрешен HTML', '17', 'editor', 'gl_guidelines', '', '', '', '', '1', '4', '', '0', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('171', 'Правила и условия регистрации', 'Данные правила будут показаны пользователю в процессе регистрации новой учетной записи на форуме.\n<b>HTML разрешен</b>', '17', 'editor', 'reg_rules', '', '<b>Правила и положения форума</b>\n\nПожалуйста, уделите немного внимания и прочтите краткие правила, указанные ниже. Если вы принимаете их и желаете продолжить процесс регистрации, отметьте свое согласие и нажмите кнопку «Регистрация». Для отмены регистрации нажмите кнопку «Назад» в вашем браузере.\n\nПожалуйста, помните, что мы не отвечаем на все публикуемые сообщения.\n\nНа форуме отсутствует предварительная проверка открываемых тем и публикаций. Как только вы отправляете сообщение — оно сразу публикуется на форуме. Администрация форума снимает с себя ответственность за содержание сообщений, публикуемых пользователями. Ответственность за содержание сообщения несёт только его автор.\n\nНа форуме запрещено:\nотправка сообщений не по содержанию форума/темы, оскорбления и угрозы в адрес пользователей форума, пропаганда расовой, национальной и религиозной вражды; реклама и самореклама;\nненормативная лексика, сексуальные домогательства и т.д.\n\nНарушители правил будут строго наказаны модераторами или администраторами форума и им будет закрыт доступ на форум.\n\nПринимая данные правила, вы соглашаетесь не публиковать любой материал, защищенный авторским правом, если авторское право не принадлежит вам.', '', '', '1', '5', 'Правила и условия регистрации', '0', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('172', 'Ключ для удаления копирайта', 'Данный ключ вы должны получить у IPS.', '18', 'input', 'ipb_copy_number', '12345-12345-12345-12345', '', '', 'if( $save == 1 )\n{\n  if( !preg_match( \"#^[0-9]+?-[0-9]+?-[0-9]+?-[0-9]+?#\", $_POST[ $key ] ) )\n  {\n   $_POST[ $key ] = \"\";\n  }\n}', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('173', 'Не показывать копирайт?', '', '18', 'yes_no', 'ips_cp_purchase', '1', '0', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('174', 'Использовать регистрационную систему COPPA?', 'Включение <a href=\"http://www.ftc.gov/ogc/coppa1.htm\" target=\"_blank\">COPPA</a> на вашем форуме потребует, чтобы все дети младше 13 лет имели письменное разрешение от родителей, отправленное по факсу или почте.', '19', 'yes_no', 'use_coppa', '', '0', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('175', 'Номер факса для получения заявлений', '', '19', 'input', 'coppa_fax', '', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('176', 'Почтовый адрес для получения заявлений', '', '19', 'textarea', 'coppa_address', '', '', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('177', 'Дополнительная COPPA информация', 'Этот текст будет отображен в форме заполнения заявления родительского разрешения на посещение форума.', '19', 'editor', 'coppa_consent_extra', '', '', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('178', 'Часовой пояс сервера', '<span style=\'color:red\'>Если вы выбрали правильный часовой пояс, а показания часов отличаются на час, то это связано с летним/зимним временем. Пользователи вашего форума могут откорректировать эту функцию в Настройках форума при помощи Панели управления пользователя.</span>', '20', 'dropdown', 'time_offset', '3', '0', '', 'if ( $show == 1 )\n{\n	ipsRegistry::getClass(\'class_localization\')->loadLanguageFile( array( \'public_usercp\' ), \'core\' );\n	\n	foreach( ipsRegistry::getClass(\'class_localization\')->words as $off => $words )\n	{\n		if (preg_match(\"/^time_(-?[&#092;d&#092;.]+)$/\", $off, $match))\n		{\n			$dropdown[ $match[1] ] = array( $match[1], $words );\n		}\n	}\n	\n	ksort($dropdown);\n}', '1', '1', 'Корректировка времени', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('179', 'Корректировка времени сервера', 'Позволяет более точно настроить время на сервере. Значение указывается в минутах, со знаком + или -, соответственно для добавления или вычитания определенного количества минут.\n<br>Текущее время в системе (с использованием всех настроек):<br /><-T->', '20', 'input', 'time_adjust', '', '0', '', 'if ( $show )\n{\n $d_date = ipsRegistry::getClass(\'class_localization\')->getDate(time(), \'LONG\',1);\n$r[\'conf_description\'] = str_replace( \'<-T->\', $d_date, $r[\'conf_description\'] );\n}', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('180', 'Использовать относительные даты?', '', '20', 'dropdown', 'time_use_relative', '', '1', '0=Нет&#13;\n1=Да ( сегодня и вчера )&#13;\n2=Да ( последние X минут, сегодня и вчера)&#13;\n3=Да ( все сразу )', '', '1', '3', 'Относительные даты', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('181', 'Формат относительных дат', '{--} заменяется на «сегодня» или «вчера»', '20', 'input', 'time_use_relative_format', '', '{--}, %I:%M %p', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('182', 'Автоматический перевод часов', 'Включение данной опции позволяет автоматически производить переход пользователей с летнее/зимнее время.', '20', 'yes_no', 'time_dst_auto_correction', '', '1', '', '', '1', '5', 'Переход на зимнее/летнее время', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('183', 'Полный формат', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_long', '', '%d %B %Y - %H:%M', '', '', '1', '6', 'Формат дат', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('184', 'Сокращенный формат', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_short', '', '%d %b %Y %H:%M', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('185', 'Альтернативный сокращенный формат', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_short2', '', '%d %B %Y', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('186', 'Формат даты регистрации', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_joined', '', '%d-%B %y', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('187', 'Краткий формат', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_tiny', '', '%d %b %Y - %H:%M', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('188', 'Формат даты', 'Назначение ключей можно посмотреть в <a href=\'http://uk.php.net/manual/en/function.strftime.php\'>PHP strftime</a>', '20', 'input', 'clock_date', '', '%d %b %Y', '', '', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('189', 'Количество тем, отображаемых в списке тем форума', '', '21', 'input', 'display_max_topics', '', '30', '', '', '1', '1', 'Просмотр тем', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('190', 'Количество оценок для отображения рейтинга темы', 'Количество оценок темы, требуемое для отображения рейтинг темы. Если их меньше, то рейтинг не показывается.', '21', 'input', 'topic_rating_needed', '', '1', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('191', 'Количество сообщений в теме, после которого тема становится «горячей»?', '', '21', 'input', 'hot_topic', '', '15', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('192', 'Удалять ссылки на перенесенные темы через Х дней', 'Если установлено значение 0, автоматическое удаление производиться не будет', '21', 'input', 'topic_redirect_prune', '', '30', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('193', 'Через сколько дней удалять отмеченные к удалению темы', 'Темы и сообщения при удалении помечаются флагом о необходимости их удаления. При этом физически они остаются в базе, что позволяет вам восстановить их через модераторскую панель. Данная опция позволяет настроить количество дней через которое темы и сообщения отмеченные к удалению будут физически удалены.', '21', 'input', 'days_to_keep_deletions', '', '5', '', '', '1', '5', '', '1', 'delete, deletions, deleted, deletion, marked');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('194', 'Максимальная длина заголовка темы', '', '21', 'input', 'topic_title_max_len', '', '150', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('195', 'Удалять множество восклицательных/вопросительных знаков в названиях тем?', 'Например, Посмотрите!!!!! будет заменено на Посмотрите!.', '21', 'yes_no', 'etfilter_punct', '', '0', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('196', 'Запретить использование только заглавных букв в названиях тем?', 'Например, НАЖМИТЕ СЮДА будет заменено на Нажмите сюда — следует правильно выбрать локаль на сервере', '21', 'yes_no', 'etfilter_shout', '', '0', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('197', 'Количество сообщений, размещаемых на одной странице темы', '', '21', 'input', 'display_max_posts', '', '20', '', '', '1', '10', 'Просмотр сообщений', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('198', 'Открывать внешние ссылки в новом окне?', 'Ссылки, которые ведут на внешние ресурсы, будут открываться в новом окне (в браузере должен быть включен javascript).', '21', 'yes_no', 'links_external', '1', '1', '', '$this->DB->delete( \'content_cache_posts\' );\n$this->DB->delete( \'content_cache_sigs\' );\n', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('199', 'Автоматически изменять размер изображений при определенном размере', 'По умолчанию система пытается изменить изображения так, чтобы оно не вылезало за ширину экрана. Однако, если вы хотите, чтобы уменьшение шло при конкретной ширине/высоте, используйте эту опцию. Если вы введете 600, то все изображения чья высота/ширина больше 600, будут уменьшены не зависимо от того помещаются они на экране или нет.', '21', 'input', 'resize_img_force', '', '0', '', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('200', 'Не игнорируемые группы пользователей', 'Пользователей выбранных групп не возможно будет добавить в список игнорирования', '21', 'multi', 'cannot_ignore_groups', '', ',4,', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'cannot_ignore_groups\']) )\n	{\n		$_POST[\'cannot_ignore_groups\'] = \',\'.implode(\",\",$_POST[\'cannot_ignore_groups\']).\',\';\n	}\n	else\n	{\n		$_POST[\'cannot_ignore_groups\'] = \"\";\n	}\n	\n	$key = \'cannot_ignore_groups\';\n}\nif ( $show == 1 )\n{\n$key = \'cannot_ignore_groups[]\';\n}', '1', '16', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('201', 'Сортировать сообщения по', '', '21', 'dropdown', 'post_order_column', '', 'pid', 'pid=номеру&#13;\npost_date=дате публикации', '', '1', '17', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('202', 'Сортировать сообщения по', '', '21', 'dropdown', 'post_order_sort', '', 'asc', 'asc=возрастанию (0-9)&#13;\ndesc=убыванию (9-0)', '', '1', '18', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('203', 'Максимальное количество смайлов в одном сообщении', '', '21', 'input', 'max_emos', '', '10', '', '', '1', '19', 'Создание сообщений', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('204', 'Максимальное количество изображений в одном сообщении', '', '21', 'input', 'max_images', '', '10', '', '', '1', '20', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('205', 'Разрешенные к публикации в сообщениях расширения файлов изображений', 'Определите расширения файлов изображений, публикуемых через тэги [img][/img].\nРазделяйте их, используя запятую (gif,jpeg,jpg)', '21', 'input', 'img_ext', '', 'gif,jpeg,jpg,png', '', '', '1', '21', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('206', 'Максимальный размер сообщения (в килобайтах)', '', '21', 'input', 'max_post_length', '', '100', '', '', '1', '22', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('207', 'Автоматически разбирать ссылки на медиа-контент?', 'Включение опции позволяет распознавать ссылки на медиа-контент, даже если для них не был указан необходимый bb-код.', '21', 'yes_no', 'bbcode_automatic_media', '', '1', '', '', '1', '23', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('208', 'Максимальная высота прикрепленного к сообщению медиа ролика (в пикселях)', 'Только при использовании тегов [media], где они разрешены', '21', 'input', 'max_h_flash', '', '199', '', '', '1', '24', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('209', 'Максимальная ширина прикрепленного к сообщению медиа ролика (в пикселях)', 'Только при использовании тегов [media], где они разрешены', '21', 'input', 'max_w_flash', '', '199', '', '', '1', '25', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('210', 'Запретить цитирование цитат?', 'Эта опция будет удалять любой цитируемый текст при цитировании сообщения, содержащего цитаты.<br><a href=\'#\' title=\'и если это имеет какой-то смысл, то вы гораздо умнее меня.\'>..</a>', '21', 'yes_no', 'strip_quotes', '', '1', '', '', '1', '26', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('211', 'Максимальное число цитат в одном сообщении', 'Используя этот пункт, вы можете предотвратить создание сообщений с очень большим количеством цитат, это исключает возможное «падение» некоторых браузеров.', '21', 'input', 'max_quotes_per_post', '', '10', '', '', '1', '27', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('212', 'Склейка сообщений', 'Когда пользователь публикует 2 сообщения подряд в одну тему с интервалом не более <em>n</em> минут, то его сообщения объединяются в одно. Введите кол-во минут, в течение которых такие сообщения склеиваются. Введите 0, чтобы отключить опцию.', '21', 'input', 'post_merge_conc', '', '0', '', '', '1', '28', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('213', 'Использовать фильтрацию URL?', 'Если вы хотите ввести фильтр ссылок, основываясь на настройке белого и черного списков, включите данную функцию. Фильтрация URL позволяет (белый список) и запрещает (черный список) использовать определенные ссылки в сообщениях и изображениях.', '21', 'yes_no', 'ipb_use_url_filter', '', '0', '', '', '1', '29', 'Фильтрация ссылок', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('214', 'Какой фильтр использовать?', 'От выбора типа списка зависит логика работы фильтра ссылок.<br />\nЕсли вы выбираете черный список, то вы запрещаете публикацию только ОПРЕДЕЛЕННЫХ ссылок, в то время как все остальные ссылки будут разрешены. <br />\nЕсли вы выбираете белый список, то вы запрещаете публикацию ВСЕХ ссылок, кроме тех, что перечислены в списке.', '21', 'dropdown', 'ipb_url_filter_option', '', 'black', 'white=белый список&#13;\nblack=черный список', '', '1', '30', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('215', 'Настройки белого списка', 'Здесь можно указать ссылки, которые вы хотите позволить. Можно использовать подстановочный символ *. По одной ссылке на строку.<br /><br />\n\nНапример: http://www.yourdomain.com*<br />\nhttp://*.google.com/*', '21', 'textarea', 'ipb_url_whitelist', '', '', '', '', '1', '31', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('216', 'Настройки черного списка', 'Здесь можно указать ссылки, которые вы хотите запретить. Можно использовать подстановочный символ *. По одной ссылке на строку.<br /><br />\nНапример: http://*.somedomain.com*<br />\nhttp://competitor_domain.com*', '21', 'textarea', 'ipb_url_blacklist', '', '', '', '', '1', '32', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('217', 'Добавлять rel=&quot;nofollow&quot; к размещенным ссылкам?', '', '21', 'yes_no', 'posts_add_nofollow', '', '1', '', '', '1', '33', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('218', 'Показывать прикрепленные изображения в сообщении?', 'Если данная опция отключена, то прикрепленное изображение будет выводиться в тексте сообщения, как ссылка.', '21', 'yes_no', 'show_img_upload', '', '1', '', '', '1', '34', 'Прикрепленные изображения', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('219', 'Показывать эскизы прикрепленных изображений?', 'Если опция выше включена, то включение еще и этой позволит отображать в сообщении уменьшенную копию прикрепленного изображения. Это экономит трафик и загружается гораздо быстрее. Нажав на уменьшенную копию, пользователь загрузит полномасштабное изображение.', '21', 'yes_no', 'siu_thumb', '', '1', 'siu_thumb', '', '1', '36', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('220', 'Размер эскиза прикрепленного изображения [ширина] ', 'Если обе опции выше включены, то вы можете здесь определить максимальную ширину эскиза. Если прикрепляемое изображение будет меньше по размерам, то он будет попросту сразу отображено без каких-либо действий с ним.', '21', 'input', 'siu_width', '', '100', '', '', '1', '37', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('221', 'Размер эскиза прикрепленного изображения [высота]', 'Если обе опции выше включены, то вы можете здесь определить максимальную высоту эскиза. Если прикрепляемое изображение будет меньше по размерам, то он будет попросту сразу отображено без каких-либо действий с ним.', '21', 'input', 'siu_height', '', '100', '', '', '1', '38', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('222', 'Максимальный размер прикрепляемого изображения [ширина]', 'Если изображение будет больше указанного ограничения, то оно будет уменьшено.', '21', 'input', 'attach_img_max_w', '', '1200', '', '', '1', '39', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('223', 'Имя гостя [префикс]', 'Опция позволяет сделает имена пользователей и гостей различными, путем добавления префикса к имени гостя. Это позволяет предотвратить проблему совпадения их имен.', '21', 'input', 'guest_name_pre', '', 'Гость_', '', '', '1', '40', 'Имена гостей', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('224', 'Максимальный размер прикрепляемого изображения  [высота]', 'Если изображение будет больше указанного ограничения, то оно будет уменьшено.', '21', 'input', 'attach_img_max_h', '', '1600', '', '', '1', '40', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('225', 'Отключить lightbox?', 'Позволяет отключить эффекты при просмотре прикрепленных изображений на форуме.', '21', 'yes_no', 'disable_lightbox', '', '0', '', '', '1', '40', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('226', 'Имя гостя [суффикс]', 'Опция позволяет сделать имена пользователей и гостей различными, путем добавления суффикса к имени гостя. Это позволяет предотвратить проблему совпадения их имен.', '21', 'input', 'guest_name_suf', '', '_*', '', '', '1', '41', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('227', 'Максимальное количество вопросов в одном опросе', 'Введите максимальное количество вопросов, которые пользователи могут создать в одном опросе.', '21', 'input', 'max_poll_questions', '', '3', '', '', '1', '43', 'Опросы', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('228', 'Максимальное количество вариантов ответа в опросе', '', '21', 'input', 'max_poll_choices', '', '20', '', '', '1', '44', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('229', 'Разрешить пользователям просматривать результаты опроса, не теряя права голоса в нем?', '', '21', 'yes_no', 'allow_result_view', '', '1', '', '', '1', '45', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('230', 'Разрешить автору опроса голосовать в нем?', '', '21', 'yes_no', 'allow_creator_vote', '', '1', '', '', '1', '46', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('231', 'Разрешить автору создавать «только опросы»?', 'Если данная опция включена, авторы опросов могут запретить создавать ответные сообщения в теме опроса.', '21', 'yes_no', 'ipb_poll_only', '', '0', '', '', '1', '47', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('232', 'Разрешить открытые опросы?', 'В открытых опросах можно видеть, кто за какой вариант ответа проголосовал.', '21', 'yes_no', 'poll_allow_public', '', '1', '', '', '1', '48', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('233', 'Разрешить удалять свой голос?', 'Если включено, то пользователи смогут удалять свои голоса. Для администраторов и супермодераторов эта опция включена всегда.', '21', 'yes_no', 'poll_allow_vdelete', '', '1', '', '', '1', '49', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('234', 'Количество часов с момента создания темы, в течение которых автору доступна возможность добавления к ней опроса', 'Опция не распространяется на администраторов и супермодераторов.', '21', 'input', 'startpoll_cutoff', '', '24', '', '', '1', '50', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('235', 'Разрешить загрузку нескольких файлов с использованием flash-загрузчика?', '', '21', 'yes_no', 'uploadFormType', '', '1', '', '', '1', '52', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('236', 'Максимальное количество медиа файлов в сообщении', 'Большое количество медиа файлов может привести к «падению» браузера.', '21', 'input', 'max_media_files', '', '2', '', '', '1', '53', '', '1', 'media, bbcode');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('237', 'Максимальное количество ЛС на одной странице при просмотре списка сообщений', 'По умолчанию - 50.', '22', 'input', 'show_max_msg_list', '', '50', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('238', 'Не игнорируемые группы:', 'Пользователи не смогут блокировать получение личных сообщений от пользователей выбранных групп. Можно выбрать несколько.', '22', 'multi', 'unblockable_pm_groups', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'unblockable_pm_groups\']) )\n	{\n		$_POST[\'unblockable_pm_groups\'] = implode(\",\",$_POST[\'unblockable_pm_groups\']);\n	}\n	else\n	{\n		$_POST[\'unblockable_pm_groups\'] = \"\";\n	}\n	\n	$key = \'unblockable_pm_groups\';\n}\nif ( $show == 1 )\n{\n    $key=\'unblockable_pm_groups[]\';\n}', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('239', 'Отключить лимит личного ящика для групп:', 'Пользователи выбранных групп смогут отправлять личные сообщения другим пользователям, даже если их личный ящик переполнен.', '22', 'multi', 'override_inbox_full', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'override_inbox_full\']) )\n	{\n		$_POST[\'override_inbox_full\'] = implode(\",\",$_POST[\'override_inbox_full\']);\n	}\n	else\n	{\n		$_POST[\'override_inbox_full\'] = \"\";\n	}\n	\n	$key = \'override_inbox_full\';\n}\nif ( $show == 1 )\n{\n    $key=\'override_inbox_full[]\';\n}', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('240', 'Включить систему предупреждений?', '', '23', 'yes_no', 'warn_on', '', '1', '', '', '1', '1', 'Система предупреждений', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('241', 'Минимальный уровень предупреждений', 'Допустимы отрицательные числа. Если используются отрицательные числа, мы не рекомендуем использовать графическое и процентное отображение.<br />При регистрации уровень предупреждений пользователя всегда нулевой.', '23', 'input', 'warn_min', '', '0', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('242', 'Максимальный уровень предупреждений', '', '23', 'input', 'warn_max', '', '10', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('243', 'Разрешить предупреждать пользователя, если у него уже максимальный/минимальный уровень предупреждений?', '', '23', 'yes_no', 'warn_past_max', '', '0', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('244', 'Защищенные группы', 'Группы, пользователи которых не могут быть предупреждены.<br />Вы можете использовать выбрать более одной (используя клавишу Ctrl).', '23', 'multi', 'warn_protected', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'warn_protected\']) )\n	{\n		$_POST[\'warn_protected\'] = implode(\",\",$_POST[\'warn_protected\']);\n	}\n	else\n	{\n		$_POST[\'warn_protected\'] = \"\";\n	}\n	\n	$key = \'warn_protected\';\n}\nif ( $show == 1 )\n{\n    $key=\'warn_protected[]\';\n}', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('245', 'Разрешить пользователю видеть свои предупреждения?', 'Если включено, то пользователи смогут видеть свой текущий уровень предупреждений и их причины.', '23', 'yes_no', 'warn_show_own', '', '0', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('246', 'Модераторы могут блокировать пользователей?', 'Относится к модераторам, имеющим право пользоваться системой предупреждений.<br />Администраторы всегда могут блокировать через панель предупреждений.', '23', 'yes_no', 'warn_mod_ban', '', '1', '', '', '1', '8', 'Права модераторов форума', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('247', 'Модераторы могут включать проверку всех публикуемых пользователем сообщений?', 'Относится к модераторам, имеющим право пользоваться системой предупреждений.<br />Администраторы всегда могут включать данную проверку через панель предупреждений.', '23', 'yes_no', 'warn_mod_modq', '', '1', '', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('248', 'Модераторы могут отключать пользователю возможность публикации?', 'Относится к модераторам, имеющим право пользоваться системой предупреждений.<br />Администраторы всегда могут отключать публикацию через панель предупреждений.', '23', 'yes_no', 'warn_mod_post', '', '1', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('249', 'Количество предупреждений одному пользователю от одного модератора за день', '', '23', 'input', 'warn_mod_day', '', '3', '', '', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('250', 'Супермодераторы могут блокировать пользователей?', 'Администраторы по умолчанию могут блокировать через панель предупреждений.', '23', 'yes_no', 'warn_gmod_ban', '', '1', '', '', '1', '12', 'Права супермодераторов', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('251', 'Супермодераторы могут включать проверку всех публикуемых пользователем сообщений?', 'Могут ли супермодераторы включать проверку всех публикуемых пользователем сообщений перед публикацией в форум через панель предупреждений?', '23', 'yes_no', 'warn_gmod_modq', '', '1', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('252', 'Супермодераторы могут отключать пользователю возможность публикации ?', 'По умолчанию администраторы могут отключать пользователю возможность публикации через панель предупреждений.', '23', 'yes_no', 'warn_gmod_post', '', '1', '', '', '1', '14', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('253', 'Количество предупреждений одному пользователю от одного супермодератора за день', '', '23', 'input', 'warn_gmod_day', '', '3', '', '', '1', '15', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('254', 'Группы, имеющие доступ к системе жалоб?', 'Укажите, какие группы имеют доступ к системе жалоб. <!--PERM_LINK-->', '23', 'multi', 'report_mod_group_access', '4,6', '4', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'report_mod_group_access\']) )\n	{\n		$_POST[\'report_mod_group_access\'] = implode(\",\",$_POST[\'report_mod_group_access\']);\n	}\n	else\n	{\n		$_POST[\'report_mod_group_access\'] = \"\";\n	}\n	\n	$key = \'report_mod_group_access\';\n}\nif ( $show == 1 )\n{\n    $key=\'report_mod_group_access[]\';\n    $r[\'conf_description\'] = str_replace( \"<!--PERM_LINK-->\", \'<a href=\"\' . $this->settings[\'base_url\'] . \'module=report&section=reports&do=plugin\">Настройки плагинов системы жалоб</a>\', $r[\'conf_description\'] );\n}', '1', '16', 'Система жалоб', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('255', 'Включить систему репутаций?', '', '24', 'yes_no', 'reputation_enabled', '', '1', '', '', '1', '741', 'Основные настройки', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('256', 'Отключить репутацию группам:', 'Пользователи, выбранных групп, не смогут получать оценки репутации.', '24', 'multi', 'reputation_protected_groups', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'reputation_protected_groups\']) )\n	{\n		$_POST[\'reputation_protected_groups\'] = implode(\",\",$_POST[\'reputation_protected_groups\']);\n	}\n	else\n	{\n		$_POST[\'reputation_protected_groups\'] = \"\";\n	}\n	\n	$key = \'reputation_protected_groups\';\n}\nif ( $show == 1 )\n{\n    $key=\'reputation_protected_groups[]\';\n}', '1', '742', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('257', 'Тип репутации', 'Тип позволяет вам выбрать режим работы системы репутации. Вы можете настроить репутацию так чтобы пользователи могли выставлять только положительные оценки, или только отрицательные.', '24', 'dropdown', 'reputation_point_types', '', 'like', 'positive=только положительное изменение репутации&#13;\nnegative=только отрицательное изменение репутации&#13;\nboth=любое изменение репутации\nlike=только положительное с отображением кому понравилось (like-тип)', '', '1', '743', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('258', 'Выделять публикации, имеющий более X баллов', 'Введите число баллов, которое требуется иметь публикации, чтобы она выделялась/подсвечивалась на странице.', '24', 'input', 'reputation_highlight', '', '50', '', '', '1', '744', 'Настройки отображения', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('259', 'Отображать репутацию пользователей?', 'Включение данной опции позволит выводить репутацию пользователя в его профиле.', '24', 'yes_no', 'reputation_show_profile', '', '1', '', '', '1', '745', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('260', 'Отображать количество баллов публикаций', 'Включение данной опции позволит выводить количество баллов, около каждого оцененного материала.', '24', 'yes_no', 'reputation_show_content', '', '1', '', '', '1', '746', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('261', 'Разрешить пользователям оценивать свои публикации?', 'Включение данной опции позволит авторам выставлять оценку своим публикациям (сообщения, записи и прочее).', '24', 'yes_no', 'reputation_can_self_vote', '', '1', '', '', '1', '747', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('262', 'Символы, допустимые в именах пользователей', 'Если опция включена, Invision Board при регистрации будет запрещать использование в именах пользователей символов, отсутствующих в списке.<br /><br />\nЧтобы разрешить использование только цифр и букв, используйте комбинацию: <b>a-zA-Z0-9а-яА-Я</b>', '25', 'input', 'username_characters', '', '', '', '', '1', '1', 'Настройки имен пользователей', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('263', 'Отображаемое сообщение об ошибке', 'Если вы указали список символов в именах пользователей, и пользователь при регистрации пытается использовать запрещенные символу, данное сообщение об ошибке будет отображено.<br /><b>Совет:</b> Вы можете использовать {chars}, чтобы отобразить разрешенные символы.', '25', 'input', 'username_errormsg', '', 'Имя может содержать только следующие символы: {chars}', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('264', 'Запретить переводы строк в именах?', 'Запрет переводов строк и html тегов в именах пользователя и отображаемых именах.', '25', 'yes_no', 'usernames_nobr', '', '0', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('265', 'Разрешить «Отображаемое имя»', 'Если опция включена, пользователи могут ввести «Отображаемое имя», отличное от «Имени пользователя» (для авторизации). Данная функция НЕОБХОДИМА для внешних методов аутентификации.', '25', 'yes_no', 'auth_allow_dnames', '', '1', '', '', '1', '4', 'Настройки отображаемых имен', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('266', 'Максимальная длина отображаемого имени', 'Максимальное количество символов, допустимое в отображаемом имени.', '25', 'input', 'max_user_name_length', '', '26', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('267', 'Запретить «Отображаемые имена», совпадающие с существующими «Именами пользователей»', 'Если опция включена, пользователи не могут выбирать «Отображаемое имя», совпадающее с другим «Отображаемым именем» ИЛИ другим «Именем пользователя». Если опция отключена, пользователи не cмогут выбирать только «Отображаемое имя», совпадающее с другим «Отображаемым именем».', '25', 'yes_no', 'auth_dnames_nologinname', '', '1', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('268', 'Количество сообщений, необходимых набрать пользователю, чтобы получить возможность изменять свое звание?', 'Введите 0, чтобы запретить пользователям когда-либо изменять свое звание.', '26', 'input', 'post_titlechange', '', '500', '', '', '1', '1', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('269', 'Включить функцию &quot;дружбы&quot; между пользователями', '', '26', 'yes_no', 'friends_enabled', '', '1', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('270', 'Позволить пользователям оценивать друг друга?', '', '26', 'yes_no', 'pp_allow_member_rate', '', '1', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('271', 'Время жизни запросов на восстановление пароля', 'Сколько дней считать запрос на восстановление пароля действительным', '26', 'input', 'lost_pw_prune', '', '60', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('272', 'Максимальная ширина фотографии пользователя на странице темы', 'Если 0 или пустое значение, то будет использовано изображение с размерами 100x100.', '26', 'input', 'member_topic_avatar_max', '', '0', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('273', 'Разрешить анимированные GIF в мини-каритинках профиля?', 'При включении анимация будет работать для мини-картинок профилей на главной странице форума и списке тем. Картинки на странице профиля анимируются всегда.', '26', 'yes_no', 'member_photo_gif_animate', '1', '0', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('274', 'Разрешить пользователям загружать фотографии через указание URL', 'Если пользователь имеет право загружать фотографию и включена эта опция, то он сможет указать URL фотографии для загрузки ее на форум.', '26', 'yes_no', 'mem_photo_url', '', '1', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('275', 'Разрешить использовать граватары?', '<a href=\'http://en.gravatar.com/\' target=\'_blank\'>Перейдите по ссылке, чтобы узнать, что такое граватар</a>.', '26', 'yes_no', 'allow_gravatars', '', '1', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('277', 'Автоматически удалять подписку на тему, если в ней нет ответов более [x] дней', 'Чтобы запретить автоматическое удаление, оставьте это поле пустым или введите 0', '26', 'input', 'subs_autoprune', '', '0', '', '', '1', '8', 'Подписки на тему и форум', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('278', 'Автоматически подписывать на каждый форум', 'Укажите группы, пользователи в которых будут автоматически получать уведомления обо всех новых темах (а не ответах) во всех доступных им форумах. Это означает, что пользователи, выбранные в первоначальную группу, будут получать электронные сообщения каждый раз, когда создается новая тема, а их нет на форуме.<br /><b>Примечание:</b> Электронные письма будут отправлены только тем, кто выбрал опцию \'Получать письма от администраторов\'.', '26', 'multi', 'autoforum_sub_groups', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'autoforum_sub_groups\']) )\n	{\n		$_POST[\'autoforum_sub_groups\'] = implode(\",\",$_POST[\'autoforum_sub_groups\']);\n	}\n	else\n	{\n		$_POST[\'autoforum_sub_groups\'] = \"\";\n	}\n	\n	$key = \'autoforum_sub_groups\';\n}\nif ( $show == 1 )\n{\n    $key=\'autoforum_sub_groups[]\';\n}', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('279', 'Настройки подписки для новых пользователей', '', '26', 'dropdown', 'auto_track_method', '0', '', '0=Не подписываться автоматически&#13;\nnone=Подписываться без уведомлений&#13;\nimmediate=Подписываться с неотложными уведомлениями&#13;=Delayed email notifications\noffline=Подписываться с отложенными уведомлениями&#13;\ndaily=Подписываться с ежедневным дайжестом&#13;\nweekly=Подписываться с еженедельным дайжестом', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('280', 'Разрешить гостям видеть подписи?', '', '26', 'yes_no', 'guests_sig', '', '1', '', '', '1', '11', 'Настройки для гостей', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('281', 'Включить работу с сервисом?', '', '27', 'yes_no', 'spam_service_enabled', '', '1', '', '', '1', '1', 'Базовые настройки', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('300', 'Разрешенные расширения файлов для фотографий', 'Разделяйте допустимые расширения файлов запятыми (gif,png,jpeg) и т.д.', '26', 'input', 'photo_ext', '', 'gif,jpg,jpeg,png', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('283', 'Сообщать сервису о пометке пользователя спамером?', 'Включение данной опции позволит отправлять информацию о пометке пользователя как спамера на сервис антиспама.', '27', 'yes_no', 'spam_service_send_to_ips', '', '1', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('284', 'Лимит времени соединения с сервисом', 'В течение указанного времени (в секундах) форум будет ждать ответа от сервиса при соединении с ним.', '27', 'input', 'spam_service_timeout', '', '15', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('285', 'Действие в случае истечения лимита времени на соединение с сервисом', '', '27', 'dropdown', 'spam_service_action_timeout', '', '1', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '4', 'Взаимодействие с сервисом', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('286', 'Действие для код-ответа 0', 'Код-ответа 0 означает, что сервис не смог правильно обработать запрос по каким-то техническим причинам.', '27', 'dropdown', 'spam_service_action_0', '', '1', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('287', 'Действие для код-ответа 1', 'Код-ответа 1 высылается сервисом в случае, если регистрирующийся пользователь не может быть спамером.', '27', 'dropdown', 'spam_service_action_1', '', '1', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('288', 'Действие для код-ответа 2', 'Код-ответа 2 высылается сервисом в случае, если регистрирующийся пользователь может-быть вероятным спамером', '27', 'dropdown', 'spam_service_action_2', '', '1', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('289', 'Действие для код-ответа 3', 'Код-ответа 3 высылается сервисом в случае, если регистрирующийся пользователь может быть спамером', '27', 'dropdown', 'spam_service_action_3', '', '2', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('290', 'Действие для код-ответа 4', 'Код-ответа 4 высылается сервисом в случае, если регистрирующийся пользователь спамер', '27', 'dropdown', 'spam_service_action_4', '', '3', '1=Продолжить регистрацию&#13;\n2=Пометить пользователя как нуждающегося в проверке администратором&#13;\n3=Зарегистрировать пользователя и сразу забанить', '', '1', '9', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('291', 'Уведомлять при появлении нового спамера?', 'Включение опции позволяет уведомлять администрацию, если какой-либо пользователь был отмечен как спамер.', '27', 'yes_no', 'spm_notify', '', '0', '', '', '1', '10', 'Автоматическая работа со спамерам', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('292', 'При отметке пользователя спамером производить действия', '', '27', 'dropdown', 'spm_option', '', 'disable', 'none=Бездействовать&#13;\ndisable=Отключить возможность отправки сообщений/личных сообщений&#13;\nunapprove=Отключить возможность отправки сообщений/личных сообщений и скрыть сообщения&#13;\nban=Скрыть сообщения, очистить профиль и заблокировать запись', '', '1', '11', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('293', 'Скрывать сообщения за X дней при отметке пользователя спамером', 'В значении опции необходимо указать количество дней, за которые сообщения от пользователя, помеченного как спамер, будут скрыты. Например, если указать 3 дня, то при отметке пользователя спамером, все его сообщения за предыдущие 3 дня будут скрыты. \n      Вы можете ввести значение 0, тогда все сообщения пользователя будут скрыты.', '27', 'input', 'spm_post_days', '', '3', '', '', '1', '12', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('294', 'Механизм генерации Captcha', 'Можно выбрать использование стороннего сервиса reCAPTHCHA или же использовать GD библиотеку.', '27', 'dropdown', 'bot_antispam_type', '', 'recaptcha', 'none=Нет&#13;\nrecaptcha=reCAPTCHA&#13;\ndefault=С использованием GD', '', '1', '13', 'CAPTCHA', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('295', 'Включить Captcha при отправке сообщений гостями?', 'При включенной опции, гостям необходимо будет пройти CAPTCHA тест, при попытке добавления темы или сообщения.', '27', 'yes_no', 'guest_captcha', '', '1', '', '', '1', '14', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('296', 'Публичный ключ (Public Key)', '<a href=\'http://www.recaptcha.net\'>Получить ключ</a>', '27', 'input', 'recaptcha_public_key', '', '6LcpWAMAAAAAAA4klDtDNuDH6LsGgBX5mBoJ3naK', '', '', '1', '15', 'Настройки reCAPTCHA', '1', 'recaptcha, captcha');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('297', 'Приватный ключ (Private Key)', '<a href=\'http://www.recaptcha.net\'>Получить ключ</a>', '27', 'input', 'recaptcha_private_key', '', '6LcpWAMAAAAAAETX5jHd9NlPtIHJA4G-ra3X2RQB', '', '', '1', '16', '', '1', 'recaptcha, captcha');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('298', 'Язык интерфейса', '', '27', 'dropdown', 'recaptcha_language', '', 'ru', 'en=English\r\nnl=Dutch\r\nfr=French\r\nde=German\r\npt=Portuguese\r\nru=Русский\r\nes=Spanish\r\ntr=Turkish', '', '1', '17', '', '1', 'recaptcha');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('299', 'Оформление', 'Вы можете выбрать одну из стандартных тем, которая будет использоваться для оформления формы вывода reCAPTCHA.', '27', 'dropdown', 'recaptcha_theme', '', 'clean', 'clean=Clean\r\nred=Red\r\nwhite=White\r\nblackglass=Blackglass', '', '1', '18', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('301', 'Ключ для работы с сервисом', 'Получить ключ вы можете в клиент-центре.', '27', 'input', 'spam_service_api_key', '', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('302', 'Shout refresh rate', 'The amount of time to refresh the shoutbox shouts (in seconds).<br />\n<strong style=\'color: red;\'>NOTE: Due to resource issues, you cannot set this any lower than 30 seconds.</strong>', '29', 'input', 'shoutbox_shouts_refresh', '', '60', '', 'if ( $save == 1 )\n{\n	if ( intval( $_POST[\'shoutbox_shouts_refresh\'] ) < 30 )\n	{\n		$value = 30;\n	}\n}', '1', '1', 'Ajax Refresh Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('303', 'Members viewing refresh rate', 'The amount of time to refresh the members viewing shoutbox (in seconds).<br />\n<strong style=\'color: red;\'>NOTE: Due to resource issues, you cannot set this any lower than 30 seconds.</strong>', '29', 'input', 'shoutbox_members_viewing_refresh', '', '60', '', 'if ( $save == 1 )\n{\n	if ( intval( $_POST[\'shoutbox_members_viewing_refresh\'] ) < 30 )\n	{\n		$value = 30;\n	}\n}', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('304', 'Inactivity cutoff', 'The number of minutes to use to check for inactivity timeout.<br /><i>Ex: 5 minutes - After 5 minutes, if no user activity, Shoutbox will halt operations.</i><br />\n<strong style=\'color: red;\'>NOTE: Due to resource issues, you cannot set this any greater than 30 minutes.</strong>', '29', 'input', 'shoutbox_inactivity_cutoff', '', '10', '', 'if ( $save == 1 )\n{\n	if ( intval( $_POST[\'shoutbox_inactivity_cutoff\'] ) > 30 )\n	{\n		$value = 30;\n	}\n}', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('305', 'Auto-hide refresh button?', 'When this setting is set to yes the refresh button will disappear while the shoutbox is checking for new shouts.<br />This is useful when you don\'t want your members to flood the ajax check', '29', 'yes_no', 'shoutbox_autohide_refresh', '', '1', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('326', 'Disable the refresh image?', 'Stops the image from showing at the top of the page each time an ajax refresh action occurs (refreshing the shouts list or active users list).', '29', 'yes_no', 'shoutbox_disable_refresh_image', '', '0', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('306', 'Shoutbox title', 'The title of your shoutbox.<br /><i>Ex:  My Shoutbox</i>', '33', 'input', 'shoutbox_title', 'Мини чат', 'Shoutbox', '', '', '1', '1', 'Global Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('307', 'Announcement', 'Display an announcement above the shouts for the Shoutbox.', '33', 'editor', 'shoutbox_announcement', '', '', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('308', 'Format shouter names?', 'Format a shouters name to their groups prefix & suffix formatting?', '33', 'yes_no', 'shoutbox_format_names', '', '1', '', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('309', 'Add fading affect', 'Add a fading affect when submitting a new shout?', '33', 'yes_no', 'shoutbox_shout_fade', '', '1', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('310', 'Long time format', 'The format here is the same as <a href=\'http://php.net/strftime\'>PHP\'s strftime</a>', '33', 'input', 'shoutbox_time_long', '', '%d %B %Y - %I:%M %p', '', '', '1', '5', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('311', 'Today time format', 'This time format is used for the shouts made \"Today\".<br />The format here is the same as <a href=\'http://php.net/strftime\'>PHP\'s strftime</a>', '33', 'input', 'shoutbox_time_today', '', '%I:%M %p', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('327', 'Allow Shoutbox Popup?', 'Show a button that will let users open the Shoutbox in a popup window?', '33', 'yes_no', 'shoutbox_popup', '', '1', '', '', '1', '7', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('312', 'Shouts displayed per page', 'The number of shouts to be displayed per page.<br /><i>Enter 0 to display all one 1 page.</i>', '33', 'input', 'shoutbox_archive_perpage', '', '20', '', '', '1', '9', 'Archive Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('313', 'Prune Old Shouts?', 'Specify here if you want to remove daily shouts older than X days.<br /><b>Enter 0 to disable the task.</b><br />\n<b>Enter -1 to prune all shouts when the task runs</b>', '33', 'input', 'shoutbox_autoprune', '', '0', '', '', '1', '11', 'Task Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('314', 'Shoutbox online', 'Is the shoutbox online?', '31', 'yes_no', 'shoutbox_online', '', '1', '', '', '1', '1', 'Online/Offline Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('315', 'Offline message', 'The message to display when the Shoutbox is offline.', '31', 'editor', 'shoutbox_offline_message', '', 'The Shoutbox is currently offline.', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('332', 'Hook to enable?', 'Select which one of the hooks you want to enable', '34', 'dropdown', 'shoutbox_global_hook', '', 't', 't=Top of Each Page\r\nb=Bottom of Each Page\r\ns=Sidebar (Board Index Only)\r\nct=Above Forum Categories (Board Index Only)\r\ncb=Below Forum Categories (Board Index Only)', 'if ( $save == 1 || ( $this->request[\'do\'] == \'setting_revert\' && $this->request[\'id\'] == $r[\'conf_id\'] ) )\n{\n	$_POST[\'shoutbox_global_hook\'] = $_POST[\'shoutbox_global_hook\'] ? $_POST[\'shoutbox_global_hook\'] : $r[\'conf_default\'];\n	\n	switch( $_POST[\'shoutbox_global_hook\'] )\n	{\n		case \'s\': $newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}\'; break;\n		case \'b\': $newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_global\";s:12:\"skinFunction\";s:14:\"globalTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:15:\"mainpageContent\";s:8:\"position\";s:10:\"post.endif\";}\'; break;\n		case \'t\': $newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_global\";s:12:\"skinFunction\";s:14:\"globalTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:15:\"mainpageContent\";s:8:\"position\";s:11:\"pre.startif\";}\'; break;\n		case \'ct\': $newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:11:\"cats_forums\";s:8:\"position\";s:11:\"pre.startif\";}\'; break;\n		case \'cb\': $newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:11:\"cats_forums\";s:8:\"position\";s:10:\"post.endif\";}\'; break;\n	}\n	\n	$this->DB->update( \'core_hooks_files\', array( \'hook_data\' => $newHookData ), \"hook_classname=\'shoutboxGlobalShoutbox\'\" );\n	$this->cache->rebuildCache( \'hooks\', \'global\' );\n	\n	require_once( IPS_ROOT_PATH . \'sources/classes/skins/skinFunctions.php\' );\n	require_once( IPS_ROOT_PATH . \'sources/classes/skins/skinCaching.php\' );\n	$skinCaching = new skinCaching( $this->registry );\n	$skinCaching->flagSetForRecache();\n}', '1', '4', 'Location Settings', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('316', 'Truncate shouter names', 'After how many characters do you want to truncate shouter names? This is useful if your members have a long name that breaks the layout of the shoutbox.', '32', 'input', 'shoutbox_truncate_names', '', '15', '', '', '1', '1', 'Display Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('317', 'Shouts to display', 'Select the number of shouts to display.', '32', 'input', 'shoutbox_shouts_limit', '', '20', '', '', '1', '2', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('318', 'Shouts display ordering', 'Select which order to display the shouts in.', '32', 'dropdown', 'shoutbox_shout_ordering', '', 'desc', 'asc=Older -> Newer\ndesc=Newer -> Older', '', '1', '3', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('328', 'Show user photo?', 'Show a photo icon of the shouter beside their name?', '32', 'yes_no', 'shoutbox_show_photos', '1', '0', '', '', '1', '4', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('319', 'Flood limit', 'The # of seconds to wait in between each shout.<br /><i>Enter 0 for no flood limit.</i>', '32', 'input', 'shoutbox_flood_limit', '', '10', '', '', '1', '5', 'Shouting Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('331', 'Display on?', 'Select where to display the global shoutbox.<br /><strong style=\"color:blue\">NOTE: This setting won\'t have any effect if you are using the sidebar hook</strong>', '34', 'dropdown', 'shoutbox_global_display_loc', '', 'all', 'all=Every Page\r\nidx=Board Index Page', '', '1', '5', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('320', 'Stop shouting in shouts?', 'Will turn: <strong>CLICK HERE</strong> into <strong>Click Here</strong>.', '32', 'yes_no', 'shoutbox_stop_shouting', '', '0', '', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('321', 'Max shout length', 'The maximum length a shout message can be.<br /><i>Size is in Kilobytes (kB)<br />0 = No max length</i>', '32', 'input', 'shoutbox_max_shout_length', '', '0', '', '', '1', '6', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('322', 'Allow Smilies', 'Allow smilie in shouts?', '32', 'yes_no', 'shoutbox_allow_smilies', '', '1', '', '', '1', '7', 'Shout Parsing', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('323', 'Allow BBCode', 'Allow BBCode to be used in shouts?', '32', 'yes_no', 'shoutbox_allow_bbcode', '', '1', '', '', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('330', 'Number of emoticons to display per row', 'How many emoticons do you want to display on each row of the emoticons popup?', '34', 'input', 'shoutbox_emos_perrow', '', '5', '', '', '1', '9', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('340', 'Default height', 'Set the default height new users will have for the shout area of the main Shoutbox application.', '33', 'input', 'shoutbox_default_height', '', '275', '', 'if ( $save == 1 )\n{\n	if ( intval( $_POST[\'shoutbox_default_height\'] ) < 100 )\n	{\n		$value = 100;\n	}\n}', '1', '8', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('325', 'Loads shouts from DB', 'Enabling this settings shouts are loaded from DB instead of using the cache. This is useful if you are using an external caching method like <strong>xcache</strong>.', '32', 'yes_no', 'shoutbox_skip_cache', '', '0', '', '', '1', '11', 'Optimization', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('329', 'Number of emoticons to display per page', 'In the emoticons popup, how many total emoticons do you want to display per page?', '34', 'input', 'shoutbox_emos_perpage', '', '20', '', '', '1', '8', 'Emoticon Settings', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('333', 'Pages list', 'Enter one command per line, separated with a comma.<br />\nCommands should consist of application, module, and/or section values for that page, or anything that is part of the $_POST data for that particular page\'s URL.<br /><br />\nFor example, to include or exclude this from showing on the profile page for Member #1, use:<br />\napp=members,module=profile,id=1', '34', 'textarea', 'shoutbox_global_pages_list', '', '', '', '', '1', '7', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('334', 'Type of Page Check', 'Page Check checks the address of the loaded page to see if you want to exclude or include the shoutbox there.<br /><strong style=\"color:blue\">NOTE: This setting won\'t have any effect if you are using the sidebar hook</strong>', '34', 'dropdown', 'shoutbox_global_pages_type', '', 'd', 'd=DISABLE Page Check\r\ne=EXCLUDE from specified pages\r\ni=INCLUDE only in specified pages', '', '1', '6', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('335', 'Shouts display ordering', 'Select which order to display the shouts.', '34', 'dropdown', 'shoutbox_global_shout_ordering', '', 'desc', 'asc=Older -> Newer\ndesc=Newer -> Older', '', '1', '2', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('336', 'Global Shoutbox Look', 'Select which global Shoutbox look to display.<br />Theme 1 - Input & buttons over to right of the shouts.<br />Theme 2 - Input is a single line and buttons are below the shouts.<br /><strong style=\"color:blue\">NOTE: This setting won\'t have any effect if you are using the sidebar hook</strong>', '34', 'dropdown', 'shoutbox_global_theme', '2', '1', '1=Theme 1\r\n2=Theme 2', '', '1', '1', 'Display Settings', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('337', 'Enable Ajax Update?', 'If set to <strong>YES</strong> active users in the shoutbox are updated live with ajax. <strong style=\"color:blue\"><br />Don\'t enable this setting on busy boards!</strong>', '35', 'yes_no', 'shoutbox_active_ajax', '', '0', '', '', '1', '3', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('338', 'Allowed groups...', 'When the \"Active Users\" hook is enabled it will show a list of active users in the shoutbox on board index for the selected groups.', '35', 'multi', 'shoutbox_active_groups', '', '', '#show_groups#', 'if ( $save == 1)\n{\n	if ( is_array($_POST[\'shoutbox_active_groups\']) )\n	{\n		$_POST[\'shoutbox_active_groups\'] = \',\'.implode(\",\",$_POST[\'shoutbox_active_groups\']).\',\';\n	}\n	else\n	{\n		$_POST[\'shoutbox_active_groups\'] = \"\";\n	}\n	\n	$key = \'shoutbox_active_groups\';\n}\nif ( $show == 1 )\n{\n$key = \'shoutbox_active_groups[]\';\n}', '1', '2', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('339', 'Hook to enable?', 'Select which one of the hooks you want to enable<br /><strong style=\"color:red\">NOTE: Each time you change this setting you need to recache the skin sets in Look & Feel > Template Tools</strong>', '35', 'dropdown', 'shoutbox_active_hook', '', 'b', 'b=Board Statistics\r\ns=Sidebar (Board Index Only)', 'if ( $save == 1 )\n{\n	if ( $_POST[\'shoutbox_active_hook\'] == \'s\' )\n	{\n		$newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:7:\"foreach\";s:2:\"id\";s:11:\"side_blocks\";s:8:\"position\";s:9:\"outer.pre\";}\';\n	}\n	else\n	{\n		$newHookData = \'a:6:{s:15:\"classToOverload\";s:0:\"\";s:9:\"skinGroup\";s:11:\"skin_boards\";s:12:\"skinFunction\";s:18:\"boardIndexTemplate\";s:4:\"type\";s:2:\"if\";s:2:\"id\";s:11:\"activeNames\";s:8:\"position\";s:10:\"post.endif\";}\';\n	}\n	\n	$this->DB->update( \'core_hooks_files\', array( \'hook_data\' => $newHookData ), \"hook_classname=\'shoutboxActiveUsers\'\" );\n	\n	$this->cache->rebuildCache( \'hooks\', \'global\' );\n}', '1', '1', 'Active User Settings', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('341', 'Archive clock format', 'Select the type of clock you want to use for selecting a date/time range in the archive', '33', 'dropdown', 'shoutbox_archive_clock', '', 'ampm', 'ampm=12 hour (am/pm)\r\n24hr=24 hour', '', '1', '10', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('342', 'Allow use of the /me tag?', 'Allow users to type /me in posts, to be replaced with their user name?', '33', 'yes_no', 'shoutbox_me_tag', '', '1', '', '', '1', '12', 'Feature Settings', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('343', 'Allow the @ link?', 'Shows an @ symbol beside each user name in the Shoutbox, which adds that user name into the shout posting area when clicked', '33', 'yes_no', 'shoutbox_at_tag', '', '1', '', '', '1', '13', '', '1', '');
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('344', 'Default height', 'Set the default height new users will have for the shout area.', '34', 'input', 'shoutbox_default_gheight', null, '132', '', 'if ( $save == 1 )\n{\n	if ( intval( $_POST[\'shoutbox_default_gheight\'] ) < 100 )\n	{\n		$value = 100;\n	}\n}', '1', '3', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('345', 'Запрещённые Группы', 'Выберите Группы которым запрещено видеть Репутацию в Темах, чтобы посмотреть Репутацию пользователя им придёться зайти в профиль пользователя.', '36', 'multi', 'tb_srtv_groups', null, '', '#show_groups#', 'if ( $save == 1)\n{\n    if ( is_array($_POST[ $key ]) )\n    {\n        $_POST[ $key ] = implode(\",\",$_POST[ $key ]);\n    }\n    else\n    {\n        $_POST[ $key ] = \"\";\n    }\n}\nif ( $show == 1 )\n{\n    $key .= \'[]\';\n}', '1', '1', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('346', 'Ajaxify fast replies?', 'Enable the hook or use the conventional fast reply?', '37', 'yes_no', 'en30_ajaxfastreply', null, '1', '', '', '1', '1', 'Functionality', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('347', 'Exclude forums from ajax fast replies', 'Select forum(s) that will require the conventional fast reply to be used instead of the ajaxified one.', '37', 'multi', 'en30_nonajaxforums', null, '', '#show_forums#', 'if ( $save == 1)\n{\n    if ( is_array($_POST[\'en30_nonajaxforums\']) )\n    {\n        $_POST[\'en30_nonajaxforums\'] = implode(\",\",$_POST[\'en30_nonajaxforums\']);\n    }\n    else\n    {\n        $_POST[\'en30_nonajaxforums\'] = \"\";\n    }\n    \n    $key = \'en30_nonajaxforums\';\n}\nif ( $show == 1 )\n{\n    $key = \'en30_nonajaxforums[]\';\n}', '1', '2', 'Permissions', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('348', 'Exclude groups from making ajax fast replies', 'Select group(s) that will be forced to use the conventional fast reply instead of the ajaxified one.', '37', 'multi', 'en30_nonajaxgroups', null, '', '#show_groups#', 'if ( $save == 1)\n{\n    if ( is_array($_POST[\'en30_nonajaxgroups\']) )\n    {\n        $_POST[\'en30_nonajaxgroups\'] = implode(\",\",$_POST[\'en30_nonajaxgroups\']);\n    }\n    else\n    {\n        $_POST[\'en30_nonajaxgroups\'] = \"\";\n    }\n    \n    $key = \'en30_nonajaxgroups\';\n}\nif ( $show == 1 )\n{\n    $key = \'en30_nonajaxgroups[]\';\n}', '1', '3', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('349', 'Effect', 'Select a built-in effect that will reveal the  ajax post and new replies to the user.', '37', 'dropdown', 'en30_revealeffect', null, '1', '0=Effect.Shake\r\n1=Effect.Appear\r\n2=Effect.Pulsate\r\n3=Effect.BlindDown\r\n4=Effect.Highlight', '', '1', '5', 'Reveal Effect', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('350', 'Effect Parameters', 'Configure the reveal effect\'s parameters to change its behavior according to:<br /><a href=\"http://wiki.github.com/madrobby/scriptaculous\" target=\"_blank\">http://wiki.github.com/madrobby/scriptaculous</a><br /><br />Enter {} to use default parameters.', '37', 'input', 'en30_revealeffectparams', null, '{ duration: 1.5, queue: \'end\' }', '', '', '1', '6', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('351', 'Effect Parameters', 'Configure the scroll effect\'s parameters to change its behavior according to:<br /><a href=\"http://wiki.github.com/madrobby/scriptaculous/effectscrollto\" target=\"_blank\">http://wiki.github.com/madrobby/scriptaculous/effectscrollto</a>', '37', 'input', 'en30_scrolleffectparams', null, '{ offset: -70, queue: \'end\' }', '', '', '1', '4', 'Scroll Effect', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('352', 'New Reply Effect', 'Select a built-in effect that will highlight any new replies to the user.', '37', 'dropdown', 'en30_newreplyeffect', null, '4', '0=Effect.Shake\r\n2=Effect.Pulsate\r\n4=Effect.Highlight', '', '1', '7', 'New Reply Effect', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('353', 'Effect Parameters', 'Configure the new reply effect\'s parameters to change its behavior according to:<br /><a href=\"http://wiki.github.com/madrobby/scriptaculous\" target=\"_blank\">http://wiki.github.com/madrobby/scriptaculous</a><br /><br />Enter {} to use default parameters.', '37', 'input', 'en30_newreplyeffectparams', null, '{ duration: 2.0, startcolor: \'#ffff99\', queue: \'end\' }', '', '', '1', '8', '', '1', null);
INSERT INTO `ibf_core_sys_conf_settings` VALUES ('354', 'Box Width', 'Specify the width in pixels.  Leave blank to use the Facebook default of 292.', '38', 'input', 'flbWidth', '270', '', '', '', '1', '2', '', '1', null);
