INSERT INTO `ibf_core_sys_lang_words` VALUES ('24', '1', 'core', 'admin_applications', 'sphinx_cronjob_details', 'You can find the cronjobs you should set up on your server for Sphinx below.<br />If you have already added these cronjobs to your server previously, please be sure to edit the old ones instead of adding duplicates.', 'Ниже приведены задачи для крона, которые необходимы для правильной индексации базы sphinx.<br/>Если вы уже добавляли задачи в cron, то убедитесь, что прежде чем добавить новые, вы удалили старые.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('25', '1', 'core', 'admin_applications', 'sphinx_cronjob_nofiledesc', 'The file \'%s\' may not exist on your server. If you still need to upload it, ignore this warning, otherwise please double-check the path.', 'Файла \'%s\' не существует. Если вы еще не загрузили его, то проигнорируйте данное предупреждение, в противном случае убедитесь в правильности пути.', '32006', '', '0');
