INSERT INTO `ibf_core_sys_lang_words` VALUES ('406', '1', 'core', 'admin_global', 'license_expired_info', 'It appears that your license key is expired.  Your license key opens up access to many more services and offerings from Invision Power Services, Inc., including access to our chat service, our spam monitoring service, and technical support and updates.  If you are interested in renewing your license, please visit your client center.', 'Срок действия вашего лицензионного ключа закончился. Активный ключ дает доступ к множеству дополнительных услуг и сервисов, включая антиспам сервис, техническую поддержку и доступ к новым версиям продукта. Если вам интересно продлить вашу лицензию, пожалуйста, зайдите в ваш клиент-центр и продлите лицензию в меню Покупки.', '32006', '', '0');
