INSERT INTO `ibf_core_sys_lang_words` VALUES ('408', '1', 'core', 'admin_global', 'license_missing_info', 'It appears that you have not yet entered your license key.  Providing your license key opens up access to many more services and offerings from Invision Power Services, Inc., including access to our chat service and our spam monitoring service.  You should take a moment to <a href=\'%s\'>provide your license key</a>', 'Ваш лицензионный ключ еще не введен. Активный ключ дает доступ к множеству дополнительных услуг и сервисов, включая антиспам сервис и т.д. Ввести ключ вы можете на <a href=\'%s\'>странице по ссылке</a>.', '32006', '', '0');
