INSERT INTO `ibf_core_sys_lang_words` VALUES ('1071', '1', 'core', 'admin_mycp', 'spam_service_disabled_msg', 'You are entitled to the Spam Monitoring Service, but it is currently disabled. The Spam Monitoring Service helps prevent spam registrations from your community.', 'Вам доступен сервис анти-спама для вашего сообщества, однако, он сейчас выключен. Сервис позволяет улучшить защиту от спамеров.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1072', '1', 'core', 'admin_mycp', 'spam_service_error_msg', 'The last call to the Spam Monitoring Service resulted in an error (%s). If the problem persists, you may wish to contact technical support for assistance.', 'Последнее обращение к сервису анти-спама было с ошибкой (%s). Если проблема повторится, пожалуйста, свяжитесь с технической поддержкой для проверки соединения и решения проблемы.', '32006', '', '0');
