INSERT INTO `ibf_core_sys_lang_words` VALUES ('1084', '1', 'core', 'admin_mycp', 'cp_upgradefinishfolder_msg', 'We have detected that %s is present on your server. You should remove this folder to prevent potential abuse.', 'Обнаружено наличие директории %s на вашем сервере. Вам необходимо удалить эту директорию в целях безопасности.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1085', '1', 'core', 'admin_mycp', 'sphinxconfig_outofdate_desc', 'You have not downloaded the updated sphinx configuration file since you last installed or updated an application in IP.Board. This may cause your sphinx indexes to be out of date and potentially lead to issues with searching.<br /><br/>You should update your sphinx configuration file and cronjobs following any update:', 'Ваш форум имеет не самую последнюю версию конфигурационного файла sphinx. Это может вызвать возможные потери или ошибки в поиске.<br /><br />Вы должны обновить sphinx конфигурационный файл и cronjobs:', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1086', '1', 'core', 'admin_mycp', 'suhosin_badvalue1', 'The minimum recommended value for the configuration option \'suhosin.post.max_vars\' is 4096, however your value is %s. <strong>Your host will need to change this in the php.ini file.</strong>', 'Минимальное значение, рекомендуемое для опции \'suhosin.post.max_vars\' - 4096, на вашей системе значение %s. <strong>Необходимо привести значение в соответствии с рекомендуемым, исправив его в php.ini файле.</strong>  ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1087', '1', 'core', 'admin_mycp', 'lc_msg_notfound', 'Your community is reporting a URL of \'<b>%s</b>\' which is not found in our system, please remove your key and then readd it with the correct URL, you can do this via the License Key section of the ACP.', 'Ваше сообщество \'<b>%s</b>\' не зарегистрировано в нашей системе, пожалуйста, свяжитесь с нашими менеджерами.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1088', '1', 'core', 'admin_mycp', 'suhosin_badvalue2', 'The minimum recommended value for the configuration option \'suhosin.request.max_vars\' is 4096, however your value is %s. <strong>Your host will need to change this in the php.ini file.</strong>', 'Минимальное значение, рекомендуемое для опции \'suhosin.request.max_vars\' - 4096, на вашей системе значение %s. <strong>Необходимо привести значение в соответствии с рекомендуемым, исправив его в php.ini файле.</strong>  ', '32006', '', '0');
