INSERT INTO `ibf_core_sys_lang_words` VALUES ('1113', '1', 'core', 'admin_mycp', 'minifynot_writeable', 'You have Minify switched on in your settings but IP.Board cannot write to /cache/tmp. Please check permissions on that directory. If this message persists, please turn off minify.', 'Minify включен в настройках вашего форума, но не может записывать данные в папку /cache/tmp. Пожалуйста, проверьте CHMOD права к ней. Если сообщение не уберется, выключите Minify.', '32006', '', '0');
