INSERT INTO `ibf_core_sys_lang_words` VALUES ('1116', '1', 'core', 'admin_mycp', 'ds_log_all_desc', 'You have \'IPS_LOG_ALL\' enabled which writes debug log files into /cache. This can quickly fill up a drive and affect performance. Please edit your initdata.php to turn this off when you have finished debugging', 'В системе включена настройка \'IPS_LOG_ALL\'. Это может привести к переполнению диска, а также сказаться на производительности форума. Пожалуйста отключите настройку в initdata.php, когда журналирование вам будет ненужно.', '32006', '', '0');
