INSERT INTO `ibf_core_sys_lang_words` VALUES ('1186', '1', 'core', 'admin_mycp', 'cp_php_warning', 'IP.Board requires at least PHP 5.0.0 to operate fully.<br />Some sections of the ACP may not operate until you upgrade.', 'Для полноценного функционирования Invision Power Board требуется версия не ниже PHP 5.0.0<br />Некоторые разделы АЦ могут не работать, пока вы не обновите вашу версию PHP.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1187', '1', 'core', 'admin_mycp', 'cp_unlocked_warning', 'Remove <b>%s/install/index.php</b> from your server at once!<br />Leaving it on your server WILL compromise the security of your system.', 'Удалите <b>admin/install/index.php</b> c вашего сервера!<br />Оставив этот файл вы рискуете безопасностью.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1188', '1', 'core', 'admin_mycp', 'cp_upgrade_warning', 'IPB has detected that an upgrade has not been completed.  Your current version is %s, but you have the upgrade routines on your server for %s. Click <a href=\'%s/upgrade/index.php\'>here</a> to complete.', 'IPB обнаружил что обновление не закончено. Ваша текущая версия %s, но вы начали обновление до версии %s. Нажмите <a href=\'%s/upgrade/index.php\'>here</a> для завершения.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1189', '1', 'core', 'admin_mycp', 'cp_installer_warning', 'Although the installer appears to be locked, we recommend you remove it from your server for security.<br />Simply remove <b>admin/install/index.php</b> from your installation to remove this message.', 'Не смотря на то, что скрипт инсталляции системы заблокирован системно, мы рекомендуем вам полностью удалить его с сервера.<br />Сделать это можно просто удалив <b>admin/install/index.php</b> с сервера.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1190', '1', 'core', 'admin_mycp', 'cp_warning_rebuild', 'You\'ll need to update all your skin caches to ensure the new template bits have been added correctly.<br /><br /><b>&gt;&gt; <a href=\'%s&amp;app=core&amp;module=templates&amp;section=tools&amp;do=rebuildalltemplates&amp;removewarning=1\'>REBUILD ALL SKIN CACHES & REMOVE THIS WARNING</a> &lt;&lt;</b>', 'Необходимо осуществить обновление всех кешей шаблонов,чтобы убедиться, что все изменения вступили в силу.<br /><br /><b>&gt;&gt; <a href=\'%s&amp;app=core&amp;module=templates&amp;section=tools&amp;do=rebuildalltemplates&amp;removewarning=1\'>Обновить кеши всех стилей</a> &lt;&lt;</b>', '32006', '', '0');
