INSERT INTO `ibf_core_sys_lang_words` VALUES ('1213', '1', 'core', 'admin_mycp', 'lc_msg_nokey', 'You have not entered your license key, <a href=\'%s\'>click here</a> to enter it now and receive access to the services provided by your license!', 'Вы не ввели ключ лицензии, <a href=\'%s\'>нажмите здесь</a>, чтобы заполнить его сейчас.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1214', '1', 'core', 'admin_mycp', 'cp_profilephotoerr_msg', 'Please check the permissions on the profile photo directory \'<b>%s</b>\' and make sure that it is writable.', 'Проверьте права доступа к директории \'<b>%s</b>\' и убедитесь, что есть права на запись', '32006', '', '0');
