INSERT INTO `ibf_core_sys_lang_words` VALUES ('1337', '1', 'core', 'admin_posts', 'bbcode_noparse', 'Prevent other codes parsing?', 'Предотвращать разбор вложенных кодов ?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1338', '1', 'core', 'admin_posts', 'bbcode_optional_info', 'Is the option value optional?  If \'yes\', when the \'option\' is omitted, the \'content\' value is used instead.', 'Значение option необязательно?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1339', '1', 'core', 'admin_posts', 'bbcode_noparse_info', 'Prevents parsing of other BBCodes within this BBCode', 'Предотвращает обработку других BB-кодов внутри этого BB-кода', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1340', '1', 'core', 'admin_posts', 'bbcode_replace', 'Custom BBCode Replacement', 'Шаблон замены BB-кода', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1341', '1', 'core', 'admin_posts', 'bbcode_replace_info', '&lt;tag&gt;{content}&lt;/tag&gt;<br />&lt;tag thing=\'{option}\'&gt;{content}&lt;/tag&gt;<br />Note: Javascript cannot be used.', 'HTML-код, которым должен быть заменен BB-код.<br />&lt;tag&gt;{content}&lt;/tag&gt;<br />&lt;tag thing=\'{option}\'&gt;{content}&lt;/tag&gt;', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1342', '1', 'core', 'admin_posts', 'bbcode_php', 'OR PHP file to execute', 'ИЛИ PHP файл для исполнения', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1343', '1', 'core', 'admin_posts', 'bbcode_switch_info', 'Use this if you wish to swap the {content} for {option} (i.e. when using tags like [tag={content}]{option}[/tag])', 'Используется для создания тега вида [tag={content}]{option}[/tag]. ', '32006', '', '0');
