INSERT INTO `ibf_core_sys_lang_words` VALUES ('1616', '1', 'core', 'admin_security', 'sec_your_installation_is_checked_a', 'Your installation is checked and suggestions are made on how to improve the security of your community.', 'При помощи настроек и инструментов ниже вы сможете проверить и повысить безопасность вашего IPB.', '32006', '', '0');
