INSERT INTO `ibf_core_sys_lang_words` VALUES ('1619', '1', 'core', 'admin_security', 'sec_the_security_center_is_a_centr', 'The Security Center is a centralized repository of security tools and settings.', 'Центр безопасности — это хранилище инструментов и настроек, отвечающих за безопасность форума.', '32006', '', '0');
