INSERT INTO `ibf_core_sys_lang_words` VALUES ('1622', '1', 'core', 'admin_security', 'sec_acp_htaccess_protection', 'ACP .htaccess protection', 'Защита файлом \'.htaccess\' АЦ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1623', '1', 'core', 'admin_security', 'sec_invision_power_board_can_write', 'IP.Board can write .htaccess protection into your admin directory.', 'Invision Power Board может создать файл \'.htaccess\', который защитит директорию админцентра. ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1624', '1', 'core', 'admin_security', 'sec_information', 'information', 'информация', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1625', '1', 'core', 'admin_security', 'sec_please_note', 'Please note', 'Помните', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1626', '1', 'core', 'admin_security', 'sec_using_this_tool_will_overwrite', 'Using this tool will overwrite any current protection in your admin directory. You will also be required to enter the username and password immediately after saving.', 'Используя этот инструмент, вы перезапишите любой имеющийся файл защиты в директории админцентра. После сохранения данных, вам будет предложено ввести указанные имя пользователя и пароль. Хотим заметить, что если вы переименуете директорию админцентра, вам так же будет необходимо удалить этот файл при помощи FTP-клиента — в противном случае доступ в админцентр для вас будет заблокирован.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1627', '1', 'core', 'admin_security', 'sec_username', 'Username', 'Имя пользователя', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1628', '1', 'core', 'admin_security', 'sec_cp_htaccess_protection', 'ACP .htaccess protection', 'Защита файлом \'.htaccess\' АЦ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1629', '1', 'core', 'admin_security', 'sec_ipboard_is_unable_to_write_int', 'IP.Board is unable to write into your admin directory', 'IP.Board не может создать файл в директории администратора', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1630', '1', 'core', 'admin_security', 'sec_proceed', 'Proceed', 'Создать файл', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1631', '1', 'core', 'admin_security', 'sec_password', 'Password', 'Пароль', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1632', '1', 'core', 'admin_security', 'sec_step_1', 'Step 1:', 'Шаг 1:', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1633', '1', 'core', 'admin_security', 'sec_renaming_the_cp_sitecontrol_di', 'Renaming the ACP \"admin\" directory', 'Изменение директории АЦ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1634', '1', 'core', 'admin_security', 'sec_please_create_a_file_called_ht', 'Please create a file called \".htpasswd\" and copy the contents below into it. Once saved, upload this new file into your \'admin\' folder.', 'Пожалуйста создайте файл с названием \".htpasswd\". Добавьте нижеследующие строки в него и загрузите его в директорию \'admin\' на сервере.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1635', '1', 'core', 'admin_security', 'sec_please_create_a_file_called_ht_1', 'Please create a file called \".htaccess\" and copy the contents below into it. Once saved, upload this new file into your \'admin\' folder.', 'Пожалуйста создайте файл с названием \".htaccess\". Добавьте нижеследующие строки в него и загрузите его в директорию \'admin\' на сервере.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1636', '1', 'core', 'admin_security', 'sec_ipboard_has_a_dedicated_direct', 'IP.Board has a dedicated directory for the administration center. To further enhance security, you can rename this ACP directory.', 'Invision Power Board обнаружил директорию админцентра. В целях повышения безопасности, вы можете изменить эту директорию.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1637', '1', 'core', 'admin_security', 'sec_locate_the_admin_directory_cho', 'Locate the \'admin\' directory. Choose \'rename\' from your FTP client menu and rename it. For the purposes of this 				tutorial, we\'ll rename it \'admin_secret\'.', 'Найдите директорию \'admin\'. Он содержит один файл - \'index.php\'. Выберите команду «Переименовать» в вашей FTP-программе и укажите новое название. В этой инструкции мы будем использовать название \'admin_secret\'. Если у вас в указанной директории создан файл защиты \'.htaccess\', вы ДОЛЖНЫ его удалить. В противном случае вы не сможете авторизоваться в админцентр. Вы сможете создать этот файл заново после выполнения следующего шага.  ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1638', '1', 'core', 'admin_security', 'sec_first_youll_need_to_physically', 'First, you\'ll need to physically rename the directory. Connect to your server via FTP and then browse to your IP.Board directory (this is the one that has your 				index.php file in it).', 'Во-первых, вы должны переименовать директорию. Подключитесь к серверу при помощи FTP и найдите директорию с IPB (директория, в котором находится файл \'index.php\').', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1639', '1', 'core', 'admin_security', 'sec_locate_the_initdataphp_file_th', 'Locate the \'initdata.php\' file. This is in your root IP.Board folder. Download it and open it in a text editor.', 'Найдите файл \'initdata.php\'. Он находится в корневой директории IPB. Скачайте его и откройте в текстовом редакторе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('1640', '1', 'core', 'admin_security', 'sec_change_the_line_define_cp_dire', 'Change the line: <pre>define( \'CP_DIRECTORY\', \'<strong>admin</strong>\' );</pre> to <pre>define( \'CP_DIRECTORY\', \'<strong>admin_secret</strong>\' );</pre>', 'Измените строку: <pre>define( \'CP_DIRECTORY\', \'<strong>admin</strong>\' );</pre> на <pre>define( \'CP_DIRECTORY\', \'<strong>admin_secret</strong>\' );</pre>', '32006', '', '0');
