INSERT INTO `ibf_core_sys_lang_words` VALUES ('1729', '1', 'core', 'admin_sql', 'my_tooold', 'Sorry, your MySQL version is less than 3.23.21, and does not work with many sections of this MySQL Toolbox. In honesty, you should not even being seeing this message if you are using 3.23.21. The community just doesn\'t work! I am just adding this language file in for the heck of it.', 'К сожалению версия MySQL, установленная у вас ниже чем 3.23.21. Управление MySQL не доступно. Да и вообще система не должна работать.', '32006', '', '0');
