INSERT INTO `ibf_core_sys_lang_words` VALUES ('1838', '1', 'core', 'admin_system', 'ext_top_desc', 'You can edit the files in the \'translate\' directory. Once you have translated the file you can import these changes directly into the database.<br /><strong>Before editing, please set your text editor to save files as UTF-8 regardless of the character set your community uses.</strong>', 'Вы можете изменять файлы в директории /translate/. После перевода вы можете импортировать изменения в базу данных.  <br /><strong>Перед редактированием настройте в вашем текстовом редакторе кодировку UTF-8, потому что форум использует ее.</strong>', '32006', '', '0');
