INSERT INTO `ibf_core_sys_lang_words` VALUES ('2117', '1', 'core', 'admin_system', 's_allex_bad', 'The deep scanner has found the following files.<br /><strong>%s</strong> of %s files are rating 7/10 or more.<br />If you\'re unsure of their origin, please investigate them immediately.', 'Глубокое сканирование обнаружило следующие файлы. <br /><strong>%s</strong> из %s файлов имеют рейтинг 7/10 или более. Если вы не уверены в происхождении этих файлов, то немедленно просмотрите их.', '32006', '', '0');
