INSERT INTO `ibf_core_sys_lang_words` VALUES ('2218', '1', 'core', 'admin_templates', 'skin_gen_convert_go', 'Convert Now', 'Конвертировать сейчас', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2219', '1', 'core', 'admin_templates', 'sk_ee_main_desc', 'Once enabled, you can edit templates and CSS outside the Admin CP by using a WebDav client. The details you need are shown below. For more instruction on how to use this feature please see <a href=\'http://link.hatynka.in/S6zG\' target=\'_blank\'>this page.</a>', 'Если включено, то вы можете изменять шаблоны и CSS вне админцентра, используя WebDav программу. Все данные, которые вам понадобятся, находятся ниже. Подробная информация по использованию этой функции смотрите <a href=\'http://link.hatynka.in/S6zG\' target=\'_blank\'>по ссылке</a>. ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2220', '1', 'core', 'admin_templates', 'skin_gen_convert_desc', 'If you want full control over the HTML, CSS and replacements, you can convert this to a full skin.<br /><strong>This action cannot be undone.</strong>', 'Если вы хотите полного контроля над HTML, CSS и макросы, вам нужно конвертировать это в полный стиль.<br /><strong>Вернуть назад будет невозможно.</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2221', '1', 'core', 'admin_templates', 'skin_gen_convert_title', 'Convert to full skin', 'Конвертировать в полный стиль', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2222', '1', 'core', 'admin_templates', 'skin_gen_convert_done', 'The skin has been converted', 'Стиль успешно сконвертирован', '32006', '', '0');
