INSERT INTO `ibf_core_sys_lang_words` VALUES ('2224', '1', 'core', 'admin_templates', 'skin_gen_new_title', 'Create New Skin', 'Создать новый стиль', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2225', '1', 'core', 'admin_templates', 'skin_gen_ready_button_edit', 'Edit Skin Settings', 'Изменить настройки стиля', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2226', '1', 'core', 'admin_templates', 'skin_gen_manual_title', 'Manual Mode', 'Ручной режим', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2227', '1', 'core', 'admin_templates', 'skin_gen_ready_title', 'New Skin Created', 'Новый стиль создан', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2228', '1', 'core', 'admin_templates', 'skin_gen_ready_desc', 'The skin has been created. Simply click the button below to launch a new browser window.', 'Стиль успешно создан. Для открытия в новом окне браузера просто нажмите на кнопку чуть ниже.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2229', '1', 'core', 'admin_templates', 'skin_gen_new_visual_desc', 'The visual editor allows you to change color and board width using a visual editor with instant preview.  Please be aware that the visual editor should be considered a beta feature, and that additional improvements and features are expected yet.', 'Визуальный редактор позволяет изменять цвета дизайна вашего форума, щелкая прямо на визуальные элементы дизайна и задавая цвет.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2230', '1', 'core', 'admin_templates', 'skin_gen_new_visual_title', 'Visual Editor', 'Визуальный редактор', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2231', '1', 'core', 'admin_templates', 'skin_gen_new_vis_skin_title', 'New Visual Editor Skin', 'Создать новый визуальный стиль', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2232', '1', 'core', 'admin_templates', 'skin_gen_new_vis_skin_desc', 'This new skin will remain hidden to others until you set it as visible.', 'Этот новый стиль будет оставаться скрытым от других пользователей, пока вы не сделаете его видимым.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2233', '1', 'core', 'admin_templates', 'skin_gen_next', 'Next', 'Дальше', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2234', '1', 'core', 'admin_templates', 'skin_gen_desc', 'Created by visual editor', 'Создано через визуальный редактор', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2235', '1', 'core', 'admin_templates', 'skin_gen_manual_desc', 'This gives you full control over the HTML and CSS code which is all fully editable for advanced layout changes.', 'Это даст вам возможность полностью изменять исходный коды HTML и CSS.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2236', '1', 'core', 'admin_templates', 'merge_uncommitted_desc', '<strong>You have %s items with uncommitted (\'unsaved\') changes.</strong><div class=\'desctext\'>This means that although the items are now merged, they need to be committed (\'saved\') before the changes will show on your community. Please use the checkboxes and drop down to commit these changes.</div>', '<strong>У вас %s отозванных несохраненных изменений.</strong><div class=\'desctext\'>Хоть элементы сейчас и объединены, но они требуют сохранения для того, чтобы они появились на работающем форуме. Вы можете сделать это просто проставив галочки напротив нужных пунктов и выбрать нужную операцию в выпадающем меню.</div>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2237', '1', 'core', 'admin_templates', 'merge_conflicts_desc', '<strong>You have %s items with conflicts that need resolving.</strong><div class=\'desctext\'>This means that the items could not be automatically \'merged\'. You need to either edit them manually to \'resolve\' the conflicts or use the \'resolve all\' option to determine the final template.</div>', '<strong>У вас %s конфликтов, требующих исправления.</strong><div class=\'desctext\'>Это означает, что эти элементы не могут быть автоматически объединены. Вам нужно или исправить конфликтные моменты вручную или использовать опцию \'Исправить все\' для формирования окончательного шаблона.</div>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2238', '1', 'core', 'admin_templates', 'in', 'in', 'в', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2239', '1', 'core', 'admin_templates', 'ie_importfail_old_version', 'Warning: The skin set you are attempting to import was created for <strong>IP.Board %s</strong>. You are currently running IP.Board %s.<br />You can continue but the skin may have errors or missing functionality.<br /><br /><a href=\'%s\' class=\'button\' />Continue and import skin</a>', 'Внимание: стиль, который вы пытаетесь установить предназначен для версии <strong>IP.Board %s</strong>. Вы используете версию %s.<br /> Данную операцию можно продолжить, однако возможны проблемы в работе этого стиля.<br /><br /><a href=\'%s\' class=\'button\' />Продолжить</a>\n', '32006', '', '0');
