INSERT INTO `ibf_core_sys_lang_words` VALUES ('2246', '1', 'core', 'admin_templates', 'ss_keynogoodyo', 'You cannot use that Skin Key as it is already in use. Please select another.', 'Вы не можете использовать этот ключ, так как он уже используется другим стилем. Пожалуйста, выберите другой.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2247', '1', 'core', 'admin_templates', 'merge_done_desc', '<strong>All your templates have been saved and are now \'live\' on your community</strong><div class=\'desctext\'>You can optionally edit them further or uncommit (\'revert\') the changes by using the checkboxes and drop down box.</div>', '<strong>Все ваши шаблоны сохранены и сейчас отображаются на \'живом\' форуме</strong><div class=\'desctext\'>При желании вы можете редактировать их дальше или отозвать (Обратить) сделанные изменения, просто проставив галочки напротив нужных и выбрать нужную операцию в выпадающем меню.</div>', '32006', '', '0');
