INSERT INTO `ibf_core_sys_lang_words` VALUES ('2522', '1', 'core', 'admin_templates', 'el_wrongformat', 'The file you uploaded is not in the correct format. It has to be one of the following: GIF, JPG/JPEG, or PNG.', 'Загруженный файл имеет не верное расширение. Оно должно быть одним из следующих: GIF, JPG/JPEG, PNG.', '32006', '', '0');
