INSERT INTO `ibf_core_sys_lang_words` VALUES ('2527', '1', 'core', 'admin_templates', 'sk_selectskinxml_info', 'This will be compared against your master HTML templates - so make sure they\'re up-to-date before running this tool', 'Будет произведено сравнение с HTML шаблонами главного стиля', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2528', '1', 'core', 'admin_templates', 'sk_skipnewmiss_info', 'If you are comparing an old ipb_templates.xml file from an older IPB release, then you may wish to disable this. If you are comparing an XML file from a customized skin set, you should enable this.', 'Если вы сравниваете старый \'ipb_templates.xml\' из более старого IPB, вы можете отключить этот пункт. Если вы сравниваете с XML файлом из измененного стиля, вы должны включить этот пункт.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2529', '1', 'core', 'admin_templates', 'sk_skipnewmiss', 'Skip all new/missing template bits?', 'Пропускать все новые/ошибочные шаблоны?', '32006', '', '0');
