INSERT INTO `ibf_core_sys_lang_words` VALUES ('2531', '1', 'core', 'admin_templates', 'sk_type_info', '\"Contains\" will match the string entered below if it occurs anywhere in the query string. \"Is Exactly\" will look to match the string entered below with the entire query string.', 'Если выбран пункт \'содержит\', то будут выбраны совпадения, которые содержат строку ниже, а если выбран пункт \'в точности\', то будут выбраны только строки точно совпадающие с введенным текстом.', '32006', '', '0');
