INSERT INTO `ibf_core_sys_lang_words` VALUES ('2996', '1', 'core', 'admin_tools', 're_320photos', 'Convert 3.1 avatars/photos to 3.2 photos', 'Конвертировать аватары/фотографии из IPB 3.1 в фотографии IPB 3.2', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2997', '1', 'core', 'admin_tools', 're_320photos_info', 'IP.Board 3.2.x has one image to identify every user.  You can use this tool upon upgrading to convert avatars or photos from IP.Board 3.1.x to IP.Board 3.2 photos.', 'В IP.Board 3.2.x в профиле у каждого участника используется одно изображение. Вы можете использовать утилиту для конвертирования аватаров или фотографий из IP.Board 3.1.x в новый формат фотографий IP.Board 3.2.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2998', '1', 'core', 'admin_tools', 're_msgsconverted', 'PMs have already been converted. No action required', 'Личные сообщения уже сконвертированы, никакие действия не требуются', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('2999', '1', 'core', 'admin_tools', 're_pmsconverted', 'All PMs converted', 'Все личные сообщения успешно конвертированы', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3000', '1', 'core', 'admin_tools', 're_300pms', 'Convert 2.x PMs To 3.0.x Format', 'Конвертировать личные сообщения из 2.x в формат 3.0.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3001', '1', 'core', 'admin_tools', 're_230to300', 'IP.Board 2.3.x -> 3.0.x Upgrade Tools', 'Система обновления IP.Board 2.3.x -> 3.0.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3002', '1', 'core', 'admin_tools', 're_300pms_info', 'If you chose to skip PM conversion during the upgrade and cannot run the shell tool, then please run this tool', 'Если вы выбрали \"пропустить конвертирование личных сообщений\" во время обновления и не можете запустить shell скрипт, пожалуйста, запустите следующую утилиту:', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3003', '1', 'core', 'admin_tools', 're_310to320', 'IP.Board 3.1.x -> 3.2.x Upgrade Tools', 'Утилиты обновления IP.Board 3.1.x -> 3.2.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3004', '1', 'core', 'admin_tools', 're_runtool', ' RUN TOOL &gt;&gt;', 'Запустить &gt;&gt;', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3005', '1', 'core', 'admin_tools', 're_21to22', 'IP.Board 2.1.x -> 2.2.0 Upgrade Tools', 'Инструменты очистки после обновления 2.1.x -> 2.2.0', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3006', '1', 'core', 'admin_tools', 're_20to21', 'IP.Board 2.0.x -> 2.1.0 Upgrade Tools', 'Инструменты очистки после обновления 2.0.x -> 2.1.0', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3007', '1', 'core', 'admin_tools', 're_1xto20', 'IP.Board 1.x.x -> 2.0.0 Upgrade Tools', 'Инструменты очистки после обновления 1.x.x -> 2.0.0', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3008', '1', 'core', 'admin_tools', 're_21to22_info', 'These tools will clean up and rebuild content from an upgrade from the IP.Board 2.1.x series', 'Этот инструмент проведет очистку и обновление содержимого после перехода с IP.Board 2.1.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3009', '1', 'core', 'admin_tools', 're_1xto20_info', 'These tools will clean up and rebuild content from an upgrade from the IP.Board 1.x.x series', 'Этот инструмент проведет очистку и обновление содержимого после перехода с IP.Board 1.x.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3010', '1', 'core', 'admin_tools', 're_20to21_info', 'These tools will clean up and rebuild content from an upgrade from the IP.Board 2.0.x series', 'Этот инструмент проведет очистку и обновление содержимого после перехода с IP.Board 2.0.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3011', '1', 'core', 'admin_tools', 're_dupe2', 'Remove Duplicate System Setting Groups from IPB 2.1.x', 'Удаление повторяющихся настроек в 2.1.х', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3012', '1', 'core', 'admin_tools', 're_dupe2_info', 'After an upgrade from IPB 2.0.x or import from another forum software, you may find that due to running an upgrade tool twice or a time-out you\'ll end up with some duplicate tool groups in the System Settings.', 'Инструмент позволяет очистить настройки форума от дубликатов, которые могут возникнуть при обновлении форума с версии 2.0.х', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3013', '1', 'core', 'admin_tools', 're_events_info', 'This tool converts IPB 2.0.x calendar events to the new format. Use this tool after a manual upgrade or when some calendar events didn\'t convert.', 'Инструмент позволяет преобразовать события календаря созданные в версии 2.0.х в новый формат, используемый в версии 2.1.х. Используйте данный инструмент после ручного обновления.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3014', '1', 'core', 'admin_tools', 're_polls', 'Convert 2.0.x Polls to 2.1.x Format', 'Конвертация опросов 2.0.х в формат версии 2.1.х', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3015', '1', 'core', 'admin_tools', 're_polls_info', 'This tool converts IPB 2.0.x polls to the new format. Use this tool after a manual upgrade or when some polls didn\'t convert.', 'Инструмент позволяет преобразовать опросы созданные в версии 2.0.х в новый формат, используемый в версии 2.1.х. Используйте данный инструмент после ручного обновления.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3016', '1', 'core', 'admin_tools', 're_events', 'Convert 2.0.x Calendar Events to 2.1.x Format', 'Конвертация событий календаря 2.0.х в формат версии 2.1.х', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3017', '1', 'core', 'admin_tools', 're_dupe1_info', 'After an upgrade from a previous version or import from another forum software, you may find that due to running an upgrade tool twice or a time-out you\'ll end up with some duplicate tools in the System Settings.<br />This tool finds the duplicates which have a greater ID than the original.', 'Инструмент позволяет очистить настройки форума от дубликатов, которые могут возникнуть в результате конвертации форума с другой форумной системы или при обновлении форума с версии 1.х.х.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3018', '1', 'core', 'admin_tools', 're_dupe1', 'Remove Duplicate System Settings from IPB 2.0.x', 'Удаление повторяющихся настроек в 2.0.x', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3019', '1', 'core', 'admin_tools', 're_ban', 'Find & Restore old IPB Ban Settings', 'Восстановление бан фильтров', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3020', '1', 'core', 'admin_tools', 're_converge_info', 'After an upgrade from a previous version or import from another forum software, you may find that because several of your members have used duplicate email addresses, their account has been moved into the validating group.<br />This tool finds these members and restores them into the default member group and asks them to change their email address.', 'Инструмент позволяет найти пользователей, чья учетная запись содержит дублирующий e-mail адрес, а аккаунт переведен в группу ожидающих активации. Такое может произойти в результате обновления или же конвертации форума с другой форумной системы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3021', '1', 'core', 'admin_tools', 're_s_last', 'Reset last registered member', 'Сбросить информацию о последнем зарегистрированном пользователе?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3022', '1', 'core', 'admin_tools', 're_stats', 'Recount Statistics', 'Пересчет статистики', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3023', '1', 'core', 'admin_tools', 're_percycle', 'Per Cycle', 'за цикл', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3024', '1', 'core', 'admin_tools', 're_ban_info', 'After an upgrade from a previous version, you may find that your ban settings are no longer stored.<br />Running this tool attempts to import your old ban settings. Old entries will not overwrite new entries.', 'Инструмент позволяет восстановить фильтры бана, которые могли быть потеряны в результате обновления с 1.х.х. При восстановлении, новые настройки не удаляются.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3025', '1', 'core', 'admin_tools', 're_converge', 'Find & Restore \'Converged\' Members', 'Поиск и восстановление пользователей', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3026', '1', 'core', 'admin_tools', 're_rebuild_info', 'This will rebuild the submitted content including BBCode, custom bbcode, HTML (where allowed) and emoticons. This is only necessary upon upgrading to IP.Board 3.0, and does not need to be run more than once.', 'Инструмент обновляет содержимое всего контента. Осуществляется перестройка оформления BB-кодов, HTML, смайликов внутри контента. Данный инструмент нужено запустить только единожды - после обновления до IP.Board 3.0', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3027', '1', 'core', 'admin_tools', 're_rebuild', 'Rebuild Content [Posts, Calendar Entries, Private Messages, Announcements, Signatures, etc.]', 'Перестроение контента [сообщений, календарей, личных сообщений, подписей и т.п]', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3028', '1', 'core', 'admin_tools', 're_topics', 'Resynchronize Topics', 'Синхронизация тем', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3029', '1', 'core', 'admin_tools', 're_topics_info', 'This will recount replies, attachment count and the topic starter and last poster for all your topics.', 'Инструмент позволяет обновить счетчики, а так же информацию о последнем авторе для всех ваших тем.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3030', '1', 'core', 'admin_tools', 're_s_most', 'Reset \'Most online\' statistic?', 'Сбросить информацию о рекорде посещаемости?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3031', '1', 'core', 'admin_tools', 're_s_total', 'Recount total topics and posts', 'Пересчитать количество тем и сообщений?', '32006', '', '0');
