INSERT INTO `ibf_core_sys_lang_words` VALUES ('3037', '1', 'core', 'admin_tools', 're_seouser_info', 'This will reset the SEO display name for all members', 'Инструмент сбрасывает все SEO имена пользователей', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3038', '1', 'core', 'admin_tools', 're_thumb_info', 'This will rebuild all your attachment image thumbnails to the current size. This is useful if you\'ve recently changed the thumbnail size and wish to update all current attachments<br />This is moderately resource intensive.', 'Обновление размера изображений предпросмотра прикрепленных изображений. Используйте, если недавно меняли настройки размера изображений предпросмотра и хотите обновить существующие изображения.<br />Для этого инструмента требуется большее количество ресурсов.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3039', '1', 'core', 'admin_tools', 're_data', 'Rebuild Attachment Data', 'Обновить информацию о прикрепленных файлах', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3040', '1', 'core', 'admin_tools', 're_orph', 'Remove Orphaned Attachments', 'Удалить потерянные файлы', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3041', '1', 'core', 'admin_tools', 're_data_info', 'This will rebuild all your attachment data such as filesize, location and file extension<br />This is moderately resource intensive.', 'Обновление информации обо всех прикрепленных файлов.<br />Для этого инструмента требуется большее количество ресурсов.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3042', '1', 'core', 'admin_tools', 're_user_info', 'This will reset the saved usernames in posts, topics, logs, etc. Useful if you\'ve recently converted or manually changed member\'s names.', 'Обновление сохраненных имен пользователей в сообщениях, темах, журналах и т.д. Полезно, если вы недавно вручную меняли имена пользователей.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3043', '1', 'core', 'admin_tools', 're_count', 'Rebuild User Post Counts', 'Обновление счетчиков пользователей', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3044', '1', 'core', 'admin_tools', 're_count_info', 'This will recount members posts based on CURRENT posts from the database. This will almost certainly REDUCE the post counts for your members as deleted and pruned posts will no longer be counted. This should not be used if you wish to retain your member\'s current post counts.<br /><strong>THERE IS NO UNDO!</strong>', 'Пересчет сообщений пользователей. В большинстве случаев это приводит к уменьшению количества сообщений. Не следует использовать этот инструмент, если вы хотите сохранить текущее количество сообщений. <strong>ЭТО ДЕЙСТВИЕ НЕЛЬЗЯ ОТМЕНИТЬ!</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3045', '1', 'core', 'admin_tools', 're_orph_info', 'This will check and remove all orphaned \'post-\' attachments not assigned to a post.<br />This is moderately resource intensive.', 'Проверка и удаление потеряных \'post-\' файлов, не связанных ни с одним сообщением.<br />Для этого инструмента требуется большее количество ресурсов.', '32006', '', '0');
