INSERT INTO `ibf_core_sys_lang_words` VALUES ('3047', '1', 'core', 'admin_tools', 're_pphoto_info', 'This will rebuild all your profile image thumbnails to the current size. This is useful if you\'ve recently changed the thumbnail size and wish to update all current photos<br />This is moderately resource intensive.', 'Обновление размера изображение предпросмотра в профиле. Используйте, если недавно изменили настройки размера изображений.<br />Для этого инструмента требуется большее количество ресурсов.', '32006', '', '0');
