INSERT INTO `ibf_core_sys_lang_words` VALUES ('3081', '1', 'core', 'admin_tools', 'l_msg', 'This section will allow you to manage your log in authentication methods.  Login handlers are executed and handled, if they are enabled, in the order in which they are listed below.  You can chain together multiple login methods, or use an external data source for account authentication.<br />&nbsp;', 'Здесь вы можете управлять модулями авторизации. Обработчики авторизации задействуются в так, как показаны ниже. Вы можете связать вместе несколько методов авторизации или использовать внешний источник данных.<br />&nbsp; ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3082', '1', 'core', 'admin_tools', 'l_installer404', 'We could not find the installer file for the Log In method you wish to install.', 'Не удалось найти скрипт установщика для устанавливаемого метода авторизации', '32006', '', '0');
