INSERT INTO `ibf_core_sys_lang_words` VALUES ('3085', '1', 'core', 'admin_tools', 'a_msg', 'This page shows all the recorded XML-RPC requests.<br />The red cross indicates an error during the request and a green tick indicates a successful request.', 'На странице отображены все записанные запросы XML-RPC<br />Красный крест означает ошибку, а зеленая галочка говорит о том, что запрос прошел успешно.', '32006', '', '0');
