INSERT INTO `ibf_core_sys_lang_words` VALUES ('3545', '1', 'forums', 'admin_forums', 'frm_f_ascat', 'Treat this forum as a category? (No posts in it)', 'Сделать форум категорией?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3546', '1', 'forums', 'admin_forums', 'frm_f_ascat_info', 'If this is set to \'Yes\' previously posted topics will not display, and posting in this forum will not be allowed.  Users will only be allowed to view the subforums under this forum.  If this is set to yes, the rest of the settings will have no effect.', 'Если вы выберите «Да», то форум будет категорией, в нем будут запрещено открытие тем и публикация сообщений, соответственно, все нижеследующие настройки не будут иметь силы.<br /><br />Если выберите «Нет», то форум будет обычным, в нем будут разрешено открытие тем, публикация сообщений (если это разрешено).', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3547', '1', 'forums', 'admin_forums', 'frm_f_redirect_num', 'Number of redirect clicks', 'Количество нажатий на ссылку (перемещений)', '32006', '', '0');
