INSERT INTO `ibf_core_sys_lang_words` VALUES ('3552', '1', 'forums', 'admin_forums', 'frm_f_perm_list', 'Allow members who can see the forum but cannot read topics to see the topic list', '<strong>Разрешить пользователям видеть названия тем в списке, но запретить им просмотр содержимого этих тем?</strong>', '32006', '', '0');
