INSERT INTO `ibf_core_sys_lang_words` VALUES ('3555', '1', 'forums', 'admin_forums', 'frm_f_redirect_en_info', 'If \'yes\' you can skip the rest of this form as the settings will have no effect and this forum will act like as a redirect link. Current posts will not be accessible when enabled.', 'При выборе «Да» нижеследующие блоки настроек не будут иметь силы, так как форум станет лишь ссылкой. Уже существующие темы в форуме будут недоступны.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3556', '1', 'forums', 'admin_forums', 'frm_f_perm_cust_info', 'You may use HTML - linebreaks automatically converted to &lt;br&gt;.<br />If left blank, a default \'permission denied\' error is used.', 'HTML разрешен.<br />Переносы строк автоматически заменяются на тег &lt;br&gt;.<br />Если оставить это поле пустым, то (при включенной опции выше) пользователям, пытающимся зайти в тему будет выводиться стандартное сообщение форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3557', '1', 'forums', 'admin_forums', 'frm_f_perm_cust', 'Custom \'Permission Denied\' Message', 'Специальное сообщение, выводимое пользователям при попытке зайти в тему (если включен пункт выше)', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3558', '1', 'forums', 'admin_forums', 'frm_f_perm_hide_info', 'Useful if you have settings that prohibit some members from seeing posts in this forum while allowing them to see the forum itself', 'Полезно, если некоторым пользователям запрещено просматривать сообщения в данном форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3559', '1', 'forums', 'admin_forums', 'frm_f_perm_list_info', 'If yes, the member will be able to see the topic titles but will not be able to read the topic posts when clicked.', 'При выборе «Да» пользователи смогут видеть только список названий тем, но не смогут в них войти.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3560', '1', 'forums', 'admin_forums', 'frm_f_post_title', 'Postable Forum Settings: Options', 'Настройки сообщений', '32006', '', '0');
