INSERT INTO `ibf_core_sys_lang_words` VALUES ('3872', '1', 'forums', 'admin_rss', 'im_invdate', 'An invalid date was found in at least one of the RSS articles -- current time will be used instead.', 'Найдена некорректная дата в не менее, чем одной RSS статье — будет использоваться текущее время.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3873', '1', 'forums', 'admin_rss', 'im_nodate', 'A date was not found in at least one of the RSS articles -- current time will be used instead.', 'Дата не найдена в не менее, чем одной RSS статье — будет использоваться текущее время.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3874', '1', 'forums', 'admin_rss', 'im_nodesc', 'At least one article was missing a title or a description/content field. If all articles are missing both fields, nothing would import. Otherwise IP.Board would skip just the items missing both a title and content.', 'Не менее, чем одна статья имеет некорректный заголовок или содержание. Если все статьи имеют оба некорректных поля, ничего не импортируется. IPB пропустит эти данные.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3875', '1', 'forums', 'admin_rss', 'im_nocontent', 'We could not find any actual content to import (topics, news articles, etc.)', 'Не найдено настоящего контента (темы, новости и т.д.) (нечего импортировать)', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('3876', '1', 'forums', 'admin_rss', 'im_redforum', 'The specified forum is either a redirect forum, or a category, and cannot display new topics.', 'Указанный форум — форум переадресации или категория, или же невозможно открывать новые темы в нем.', '32006', '', '0');
