INSERT INTO `ibf_core_sys_lang_words` VALUES ('3878', '1', 'forums', 'admin_rss', 'im_memval', 'We could not validate the member used to import articles.', 'Мы не можем разрешить пользователя, используемого для импорта статей.', '32006', '', '0');
