INSERT INTO `ibf_core_sys_lang_words` VALUES ('4013', '1', 'members', 'admin_bulkmail', 'b_noid', 'There was no ID passed to the mailer. Please try again.', 'ID отправителя не найден. Попробуйте еще раз.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4014', '1', 'members', 'admin_bulkmail', 'bulkmail_notes_tl', 'Important Information', 'Важно', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4015', '1', 'members', 'admin_bulkmail', 'bulkmail_notes_info', 'Please be aware that bulk emails are sent by a task in IP.Board in the System Scheduler.  They are not sent immediately upon saving or resending a bulk email.  You can manually run this task in the System Scheduler if you wish to force emails to send immediately, otherwise\n							they will be sent based on activity on your forums.  Also, please be aware that any users who elect <em>not</em> to receive emails from the administrator in their user control panel will <strong>not</strong> receive bulk mails.', 'Отправка рассылки осуществляется задачей в планировщике задач IP.Board. Поэтому рассылка не стартует мгновенно. Вы можете вручную запустить задачу в планировщике, если вам крайне необходимо осуществить рассылку в ближайшее время. Также учитывайте тот факт, что пользователи, выбравшие опцию «<em>Не</em> получать сообщения от администрации форума» в своих настройках, <em>не</em> получат писем рассылки.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4016', '1', 'members', 'admin_bulkmail', 'b_initiated', 'Bulk mail initiated!', 'Отправка рассылки начата!', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4017', '1', 'members', 'admin_bulkmail', 'b_entercont', 'You must enter a mail subject and mail content before submitting. Please try again.', 'Необходимо ввести тему и текст письма.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4018', '1', 'members', 'admin_bulkmail', 'b_nosend', 'Cannot send - the mail doesn\'t have a subject and content. Please try again.', 'Невозможно отправить - не указана тема и текст письма. Попробуйте еще раз.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4019', '1', 'members', 'admin_bulkmail', 'b_maillogedit', 'Bulk mail ( %s ) edited', 'Рассылка ( %s ) изменена', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4020', '1', 'members', 'admin_bulkmail', 'b_countmember', 'Sending the bulk mail to <strong>%s</strong> members', 'Отправка рассылки <strong>%s</strong> пользователям', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4021', '1', 'members', 'admin_bulkmail', 'b_sending_info', 'Clicking the \'Start Sending The Mail\' button below will activate the task manager\'s send bulk mail function which will send the mail in batches until the all the mail has been sent. You can watch the progress from the main Bulk Mail screen and cancel the mail from being sent.<br />We strongly recommend that you opt to send 20 mails per cycle as a maximum. Any more per cycle could severly affect performance of your server while the mail is being sent out.<br /><br />As the mail is sent out in cycles of <em><b>n</b></em> &nbsp;per minute, it can take a while to process all the mail.', 'Нажатие на кнопку «Отправить» добавит эту рассылку в задачи форума. Задача останется текущей до тех пор, пока все письма не будут отправлены.<br />За процессом отправки писем вы можете следить в окне администрирования «Список рассылок», там же можно отменить отправку рассылки.<br />Настоятельно рекомендуется не рассылать больше 50 писем за один раз, так как это может существенно замедлить работу вашего сервера в момент рассылки писем.<br /><br />Поскольку раз в минуту отправляется по n писем, этот процесс может занять длительное время. ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4022', '1', 'members', 'admin_bulkmail', 'b_editmail', 'Edit This Mail', 'Изменить письмо', '32006', '', '0');
