INSERT INTO `ibf_core_sys_lang_words` VALUES ('4160', '1', 'members', 'admin_groups', 'gf_gformpre_info', 'This changes the formatting (color, font, etc) of the username of anyone in this group.<br />(Example:&lt;span style=\'color:red\'&gt;)', 'При отображении в списке активных пользователей перед именем каждого пользователя этой группы будет добавлена строчка из это настройки. Вы можете использовать эту опцию для раскраски имен пользователей групп, например: <span style=\'color:red\'>', '32006', '', '0');
