INSERT INTO `ibf_core_sys_lang_words` VALUES ('4164', '1', 'members', 'admin_groups', 'gf_uglobal', 'Global Upload Limit<br /><span class=\'desctext\'>Max total global file space for all uploads for each user in this group. (Includes: PMs and Posts)</span>', 'Дисковая квота на хранение всех файлов (включая личные сообщения и сообщения в темах)', '32006', '', '0');
