INSERT INTO `ibf_core_sys_lang_words` VALUES ('4185', '1', 'members', 'admin_groups', 'gf_sflood_info', 'Stops search abuse. Enter 0 or leave blank for no flood control.', 'Введите количество секунд, в течение которых пользователь этой группы после использования поиска не сможет им воспользоваться повторно. Эта опция защищает форум от атак на сервер за счет массового поиска в короткий период времени.\r\nВведите 0 для отключения ограничения.', '32006', '', '0');
