INSERT INTO `ibf_core_sys_lang_words` VALUES ('4491', '1', 'members', 'admin_member', 'm_yoursusp', '{membername},\n your account at %s has been temporarily suspended.\n\nYour account will not be functional until {date_end} (depending on your timezone). This is an automated process and you do not need to do anything to expedite the unsuspension process.\n\nCommunity Address: ', '{membername}, Администратор форума %s временно заблокировал вашу учетную запись.<br />Ваша учетная запись будет активна с {date_end} (в зависимости от вашего часового пояса). Это полностью автоматический процесс блокировки и от вас не требуется ничего делать для его ускорения или прекращения.<br />Адрес форума:', '32006', '', '0');
