INSERT INTO `ibf_core_sys_lang_words` VALUES ('4772', '1', 'members', 'admin_member', 'cf_f_desc_info', 'Max Characters: 250<br />Can be used to note hidden/required status', 'Максимальное количество символов: 250<br />Может быть использовано для примечаний.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4773', '1', 'members', 'admin_member', 'cf_f_key_info', 'This is a key that can be used to identify the field (e.g. in skins)', 'Ключ может использоваться для идентификации поля.<br />(Например в шаблонах)', '32006', '', '0');
