INSERT INTO `ibf_core_sys_lang_words` VALUES ('4778', '1', 'members', 'admin_member', 'cf_f_title_info', 'Max characters: 200', 'Максимальное количество символов: 200', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4779', '1', 'members', 'admin_member', 'cf_f_order', '<strong class=\'title\'>Display order</strong>', '<strong>Порядок сортировки</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4780', '1', 'members', 'admin_member', 'cf_f_reg_info', 'If \'yes\', the field will be shown upon registration.', 'При выборе «Да», это дополнительное поле будет предложено заполнить при регистрации.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4781', '1', 'members', 'admin_member', 'cf_f_must', '<strong class=\'title\'>Field MUST be completed and not left empty?</strong>', '<strong>Это поле обязательно к заполнению?</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4782', '1', 'members', 'admin_member', 'cf_f_must_info', 'If \'yes\', an error will be shown if this field is not completed.', 'При выборе «Да», будет выводиться сообщение об ошибке до тех пор, пока пользователь его не заполнит.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4783', '1', 'members', 'admin_member', 'cf_filter_type_info', 'If \'yes\', the field will be checked against the URL whitelist/blacklist filtering.  Be careful to only enable this option on fields that you expect URLs to be submitted in.', 'При выборе «Да» будет происходить фильтрация вставляемых URL адресов по списку. Будьте осторожны, используя эту опцию.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4784', '1', 'members', 'admin_member', 'cf_f_reg', '<strong class=\'title\'>Include on registration page?</strong>', '<strong>Добавить на страницу регистрации?</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4785', '1', 'members', 'admin_member', 'cf_srch_type', 'Search Type', 'Тип поиска', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4786', '1', 'members', 'admin_member', 'cf_srch_type_info', 'Used when searching for members based on their value of this field', 'Используется при поиске пользователей по значению данного поля', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4787', '1', 'members', 'admin_member', 'cf_filter_type', 'Apply URL Filtering', 'Применить фильтрацию URL адресов', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4788', '1', 'members', 'admin_member', 'cf_f_option', '<strong class=\'title\'>Option Content (for drop downs, checkboxes and radio buttons)</strong>', '<strong>Содержимое опций для выпадающего меню</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4789', '1', 'members', 'admin_member', 'cf_f_form_info', 'Use: <strong>a</strong> for alpha characters.<br />Use: <strong>n</strong> for numerics.<br />If you enter one \'a\', that will allow one letter. Entering \'aa\' will allow two letters, and so on.<br />Example, for credit card numbers: nnnn-nnnn-nnnn-nnnn<br />Example, Date of Birth: nn-nn-nnnn<br />Leave blank to accept any input', 'Использование:<strong>a</strong> — буквы<br /><strong>n</strong> — цифры.<br />Например, кредитная карта: nnnn-nnnn-nnnn-nnnn<br />Например, дата рождения: nn-nn-nnnn<br />Оставьте поле пустым для использования любых символов.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4790', '1', 'members', 'admin_member', 'cf_f_form', '<strong class=\'title\'>Expected Input Format</strong>', '<strong>Формат поля</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4791', '1', 'members', 'admin_member', 'cf_f_order_info', 'When editing and displaying (numeric 1 lowest)', 'При редактировании и отображении.<br />Цифра 1 — самая низкая позиция.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4792', '1', 'members', 'admin_member', 'cf_f_edit', '<strong class=\'title\'>Field can be edited by the member?</strong>', '<strong>Поле может быть изменено пользователем?</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4793', '1', 'members', 'admin_member', 'cf_f_option_info', 'In sets, one set per line<br>Example for \'Gender\' field:<br>m=Male<br>f=Female<br>u=Not Telling<br>Will produce:<br><select name=\'pants\'><option value=\'m\'>Male</option><option value=\'f\'>Female</option><option value=\'u\'>Not Telling</option></select><br>m,f or u stored in database. When showing field in profile, will use value from pair (f=Female, shows \'Female\')', 'Использование: <strong>ключ=значение</strong> (по одному значению на строку)<br />Пример для поля <strong>Пол:</strong><br />m=Мужской<br />f=Женский<br />u=Не скажу<br /><strong>Результат:</strong><br /><select name=\'pants\'><option value=\'m\'>Женский</option><option value=\'u\'>Не скажу</option></select><br />Одно из значений: <strong>m</strong>, <strong>f</strong> или <strong>u</strong> будет сохранено в базе данных.<br />При отображении в профиле выводится <strong>Пол: Не скажу</strong> (при выборе пользователем значения <strong>Не скажу</strong>)', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4794', '1', 'members', 'admin_member', 'cf_removeto', '<strong class=\'title\'>Custom Profile Field to remove...</strong>', '<strong>Поле профиля для удаления</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4795', '1', 'members', 'admin_member', 'cf_removeconf', 'Removal Confirmation', 'Подтверждение удаления', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4796', '1', 'members', 'admin_member', 'cf_f_priv', '<strong class=\'title\'>Make this a private profile field?</strong>', '<strong>Сделать это поле личным?</strong>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4797', '1', 'members', 'admin_member', 'cf_f_priv_info', 'If yes, field only visible to profile owner, super moderators and admins. If \'no\', members can search within this field.', 'При выборе «Да», поле будет видимым только для самого пользователя, супермодераторов и администраторов.<br />При выборе «Нет», остальные пользователи смогут искать по этому полю.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4798', '1', 'members', 'admin_member', 'cf_f_edit_info', 'If \'no\', the member cannot edit the field but Super Moderators and Admins will be able to.', 'При выборе «Нет», пользователь не сможет редактировать это поле, но смогут супермодераторы и администраторы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('4799', '1', 'members', 'admin_member', 'cf_g_save', 'Create Group', 'Сохранить', '32006', '', '0');
