INSERT INTO `ibf_core_sys_lang_words` VALUES ('5074', '1', 'members', 'admin_restrictions', 'r_allowaccess_info', 'When &quot;ALLOW ACCESS TO THIS FUNCTION&quot; is enabled you may set the individual access permissions for the sub-features of this particular function. Otherwise, changes to the individual access permission will have no effect.', 'Если «РАЗРЕШИТЬ ДОСТУП К ЭТОЙ ФУНКЦИИ» включен, то вы можете указать индивидуальные разрешения для ее под-функций. Иначе изменения индивидуальных разрешений не даст желаемого эффекта.', '32006', '', '0');
