INSERT INTO `ibf_core_sys_lang_words` VALUES ('5472', '1', 'core', 'public_emails', 'imp_text', 'IMPORTANT: To prevent malicious use, all emails sent via this form are logged and the contents recorded and available to the administrators. DO NOT email user names, passwords or any personal details.', 'ВАЖНО: для предотвращения возможного неправомерного использования данной возможности, все письма, отправленные через эту форму заносятся в специальный журнал, доступный администрации форума. НИ В КОЕМ случае не отправляйте пароли, логины или любую другую личную информацию.', '32006', '', '0');
