INSERT INTO `ibf_core_sys_lang_words` VALUES ('5493', '1', 'core', 'public_emails', 'show_address_text', 'You can send this member an email by clicking on the link below. IP.Board does not show email addresses in the topic view to prevent email addresses being harvested by \'spam bots\'.', 'Для отправки e-mail письма пользователю воспользуйтесь размещенной ниже ссылкой. IPB не показывает e-mail адреса для защиты от спам-ботов. ', '32006', '', '0');
