INSERT INTO `ibf_core_sys_lang_words` VALUES ('5495', '1', 'core', 'public_emails', 'msg_txt', 'Note: By using this form, the recipient will be able to view your email address', 'Примечание: получатель письма узнает ваш e-mail адрес ', '32006', '', '0');
