INSERT INTO `ibf_core_sys_lang_words` VALUES ('5501', '1', 'core', 'public_email_content', 'subject__other_status_reply', '<a href=\'%s\'>%s</a> has replied to <a href=\'%s\'>%s</a>\'s <a href=\'%s\'>status</a>', '<a href=\'%s\'>%s</a> прокомментировал <a href=\'%s\'>%s</a> <a href=\'%s\'>статус</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5502', '1', 'core', 'public_email_content', 'subject__status_reply', '<a href=\'%s\'>%s</a> has replied to your <a href=\'%s\'>status</a>', '<a href=\'%s\'>%s</a> прокомментировал ваш <a href=\'%s\'>статус</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5503', '1', 'core', 'public_email_content', 'personal_convo_new_reply', '<#NAME#>,\n\n<#POSTER#> has replied to a personal conversation entitled \"<#TITLE#>\".\n\n<#POSTER#> said:\n======================================================================\n<#TEXT#>\n======================================================================\n\nPLEASE DO NOT REPLY DIRECTLY TO THIS EMAIL!\nYou can reply to this personal conversation by following the link below:\n\n<#BOARD_ADDRESS#><#LINK#>\n', '<#NAME#>, <#POSTER#> ответил в личную беседу \"<#TITLE#>\".\n<#POSTER#> сказал:\n<#TEXT#>\nВы можете просмотреть полный диалог беседы по указанной ниже ссылке:\n<#BOARD_ADDRESS#><#LINK#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5504', '1', 'core', 'public_email_content', 'subject__personal_convo_new_reply', '<a href=\'%s\'>%s</a> has replied to a <a href=\'%s\'>personal conversation</a>', '<a href=\'%s\'>%s</a> написал новое сообщение в <a href=\'%s\'>личной беседе</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5505', '1', 'core', 'public_email_content', 'subject__error_log_notification', 'An error has been generated on your site', 'На вашем форуме возникла ошибка', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5506', '1', 'core', 'public_email_content', 'personal_convo_invite', '<#NAME#>,\n\n<#POSTER#> has added you to their personal conversation entitled \"<#TITLE#>\".\n\nYou can read this personal conversation by following the link below:\n\n<#BOARD_ADDRESS#><#LINK#>\n', '<#NAME#>, <#POSTER#> добавил вас к личной беседе \"<#TITLE#>\". \nВы можете прочитать диалог по указанной ниже ссылке:\n<#BOARD_ADDRESS#><#LINK#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5507', '1', 'core', 'public_email_content', 'subject__personal_convo_invite', '<a href=\'%s\'>%s</a> has added you to a <a href=\'%s\'>personal conversation</a>', '<a href=\'%s\'>%s</a> приглашает вас принять участие в <a href=\'%s\'>беседе</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5508', '1', 'core', 'public_email_content', 'subject__account_created', 'Your account has been created', 'Ваша учетная запись успешно создана', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5509', '1', 'core', 'public_email_content', 'account_created', '<#NAME#>,\n\nYour account has been created successfully at <#BOARD_NAME#>.\n\nIf we were waiting on a parental consent form, this means the form has been received and documented.\n\nYour details are as follows:\n\nUsername: <#NAME#>\nEmail Address: <#EMAIL#>\nPassword: <#PASSWORD#>\n\nPlease be aware that we do not store a plain text copy of your password, and you can change your password at any time through your control panel on the site.\n\nVisit this link to join into our discussions!\n\n<#BOARD_ADDRESS#>\n', '<#NAME#>,\n\nВаша учетная запись успешно создана на форуме <#BOARD_NAME#>\n\nДанные для доступа к форумам следующие:\n\nИмя пользователя: <#NAME#> \nПароль: <#PASSWORD#>\nE-mail: <#EMAIL#>\n\nПожалуйста, запомните, что мы не храним ваш пароль, но вы можете его изменить в любой время в ваших личных данных.\n\nПриятного общения!\n\n<#BOARD_ADDRESS#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5510', '1', 'core', 'public_email_content', 'subject__new_friend_approved', '<a href=\'%s\'>%s</a> approved your friend request', '<a href=\'%s\'>%s</a> активировал дружбу с вами', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5511', '1', 'core', 'public_email_content', 'new_friend_approved', '<#MEMBERS_DISPLAY_NAME#>,\n\n<#FRIEND_NAME#> has approved your friend request!\n\nLog in and then manage your friends: <#LINK#>\n', '<#MEMBERS_DISPLAY_NAME#>, <#FRIEND_NAME#> принял предложение стать вашим другом! Управление вашим списком друзей по ссылке: <#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5512', '1', 'core', 'public_email_content', 'new_friend_request', '<#MEMBERS_DISPLAY_NAME#>,\n\n<#FRIEND_NAME#> wants to be your friend!\n\nThis message has been sent because <#FRIEND_NAME#> has added you to their friends\nlist. As you\'ve chosen to approve all friend requests, you will need to visit your\nfriends list and approve them.\n\nLog in and then manage your friends: <#LINK#>\n', '<#MEMBERS_DISPLAY_NAME#>, <#FRIEND_NAME#> хочет стать вашим другом! Так как у вас включена проверка желающих стать вашими друзьями, то для того, чтобы он появился в вашем списке друзей, его запрос необходимо подтвердить (или отклонить). Сделать это можно по ссылке: <#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5513', '1', 'core', 'public_email_content', 'subject__new_friend_added', '<a href=\'%s\'>%s</a> added you as a friend', '<a href=\'%s\'>%s</a> добавил вас в друзья', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5514', '1', 'core', 'public_email_content', 'new_friend_added', '<#MEMBERS_DISPLAY_NAME#>,\n\n<#FRIEND_NAME#> has successfully added you to their friends list.\n\nManage your friends: <#LINK#>\n', '<#MEMBERS_DISPLAY_NAME#>, <#FRIEND_NAME#> стал вашим другом.\nУправление списком ваших друзей: <#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5515', '1', 'core', 'public_email_content', 'subject__new_comment_request', '<a href=\'%s\'>New comment</a> from <a href=\'%s\'>%s</a> pending approval', '<a href=\'%s\'>Новый комментарий</a> от <a href=\'%s\'>%s</a> ожидает подтверждения', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5516', '1', 'core', 'public_email_content', 'subject__new_friend_request', '<a href=\'%s\'>%s</a> sent you a <a href=\'%s\'>friend request</a>', '<a href=\'%s\'>%s</a> <a href=\'%s\'>хочет</a> дружить с вами', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5517', '1', 'core', 'public_email_content', 'subject__post_was_quoted', '<a href=\'%s\'>%s</a> <a href=\'%s\'>quoted</a> a <a href=\'%s\'>post you made</a>', '<a href=\'%s\'>%s</a> <a href=\'%s\'>процитировал</a> ваше <a href=\'%s\'>сообщение</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5518', '1', 'core', 'public_email_content', 'new_comment_added', '<#MEMBERS_DISPLAY_NAME#>,\n\n<#COMMENT_NAME#> has left you a comment on your profile.\n\nManage your comments: <#LINK#>\n', '<#MEMBERS_DISPLAY_NAME#>, \n\n<#COMMENT_NAME#> оставил комментарий в вашем профиле.\n\nУправление такими комментариями по ссылке: <#LINK#>  ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5519', '1', 'core', 'public_email_content', 'subject__new_comment_added', '<a href=\'%s\'>New comment</a> from <a href=\'%s\'>%s</a>', '<a href=\'%s\'>Новый комментарий</a> от <a href=\'%s\'>%s</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5520', '1', 'core', 'public_email_content', 'error_log_notification', 'Dear admin,\n\nAn error has been generated on your forums.  You are being sent this notification based on your error log notification settings in the Admin Control Panel.  This error meets the criteria for errors that you have set to be notified about.\n\nThe error code is: <#CODE#>\nThe error message is: <#MESSAGE#>\nThe user who saw this error is: <#VIEWER#>\nThe IP address of this user is: <#IP_ADDRESS#>\n\nPlease login to your Admin Control Panel to use the error log viewer tool for further information.\n\n<#BOARD_ADDRESS#>\n', 'На вашем форуме возникла ошибка!\n\nВы получили это уведомление, так как у вас включена соответствующая функция в админцентре.\n\nДанные по ошибке.\n\nКод ошибки: <#CODE#> \nСообщение: <#MESSAGE#> \nПользователь, кто обнаружил ошибку: <#VIEWER#> \nЕго IP-адрес: <#IP_ADDRESS#> \n\nБолее подробную информация вы можете получить, просмотрев журнал error_log.\n\n<#BOARD_ADDRESS#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5521', '1', 'core', 'public_email_content', 'new_status', '<#NAME#>,\n\n<#OWNER#> has just posted a new status update.\n\n======================================================================\n<#STATUS#>\n======================================================================\n\n\nYou can turn off status notification by visiting <#URL#>\n', '<#NAME#>,\n\n<#OWNER#> только что обновил статус.\n\n======================================================================\n<#STATUS#>\n======================================================================\n\n\nВы можете отключить уведомления по адресу <#URL#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5522', '1', 'core', 'public_email_content', 'subject__new_status', '<a href=\'%s\'>%s</a> has posted a new <a href=\'%s\'>status update</a>', '<a href=\'%s\'><#OWNER#></a> обновил свой <a href=\'%s\'>статус</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5523', '1', 'core', 'public_email_content', 'subject__email_convo', 'Personal Conversation Archive', 'Архив личной переписки', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5524', '1', 'core', 'public_email_content', 'email_convo', '<#NAME#>,\n\nAttached to this message is a HTML file containing a personal conversation archive:\nConversation title: <#TITLE#>\nConversation started: <#DATE#>\n<#LINK#>\n', '<#NAME#>,\n\nК письму прикреплен архив личной переписки:\nНазвание: <#TITLE#>\nНачало: <#DATE#>\n<#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5525', '1', 'core', 'public_email_content', 'new_likes', 'Hello!\n\n<#MEMBER_NAME#> just liked a post you made!\n\n<#SHORT_POST#>\n<#URL#>\n', 'Здравствуйте!\n\nПользователю <#MEMBER_NAME#> понравилось вашe сообщение на форуме!\n\n<#SHORT_POST#>\n<#URL#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5526', '1', 'core', 'public_email_content', 'subject__new_likes', '<a href=\'%s\'>%s</a> liked a <a href=\'%s\'>post you made</a> in <a href=\'%s\'>%s</a>', '<a href=\'%s\'>%s</a> понравилось <a href=\'%s\'>сообщение, сделанное вами,</a> в <a href=\'%s\'>%s</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5527', '1', 'core', 'public_email_content', 'footer', '\nRegards,\n\nThe <#BOARD_NAME#> team.\n<#BOARD_ADDRESS#>\n', 'С уважением, <#BOARD_NAME#>, <#BOARD_ADDRESS#> ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5528', '1', 'core', 'public_email_content', 'header', '', '', '32006', null, '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5529', '1', 'core', 'public_email_content', 'new_comment_request', '<#MEMBERS_DISPLAY_NAME#>,\n\n<#COMMENT_NAME#> has left you a comment that requires your approval.\n\nAs you\'ve chosen to approve all new comments the new comment will not appear on your\nprofile until it\'s been approved.\n\nLog in and then manage your comments: <#LINK#>\n', '<#MEMBERS_DISPLAY_NAME#>, <#COMMENT_NAME#> оставил комментарий в вашем профиле. Так как у вас включена премодерация комментариев, для того, чтобы он появился, необходимо вам его активировать, в противном случае удалить. Сделать это можно по ссылке: <#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5530', '1', 'core', 'public_email_content', 'new_topic_queue_notify', 'Hello!\n\nThis email has been sent from: <#BOARD_NAME#>.\n\nA new topic has been entered into the moderation queue and is awaiting\napproval.\n\n----------------------------------\nTopic: <#TOPIC#>\nForum: <#FORUM#>\nAuthor: <#POSTER#>\nTime: <#DATE#>\nManage Queue: <#LINK#>\n----------------------------------\n<#POST#>\n----------------------------------\n\nIf you no longer require notification, you can stop these emails by simply\nremoving your email address from the forum settings options.\n\n<#BOARD_ADDRESS#>\n\n', '<#BOARD_NAME#>\n\nНа форуме появилось новая тема для проверки и публикации/удаления модератором.\n\nТема: <#TOPIC#>\nФорум: <#FORUM#>\nАвтор:  <#POSTER#>\nВремя: <#DATE#>\n\nДля совершения действий с темой перейдите по ссылке: <#LINK#> \n----------------------------------\n<#POST#>\n----------------------------------\n\nЕсли вы больше не хотите получать такие уведомления, удалите ваш e-mail адрес в настройках форума.\n\nАдрес форума: <#BOARD_ADDRESS#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5531', '1', 'core', 'public_email_content', 'personal_convo_new_convo', '<#NAME#>,\n\n<#POSTER#> has sent you a new personal conversation entitled \"<#TITLE#>\".\n\n<#POSTER#> said:\n======================================================================\n<#TEXT#>\n======================================================================\n\nPLEASE DO NOT REPLY DIRECTLY TO THIS EMAIL!\nYou can reply to this personal conversation by following the link below:\n\n<#BOARD_ADDRESS#><#LINK#>\n', '<#NAME#>, <#POSTER#> отправил вам сообщение с заголовком \"<#TITLE#>\". \n<#POSTER#> сказал: ======================================================================\n<#TEXT#>\nВы можете просмотреть беседу с ним, пройдя по указанной ниже ссылке:\n<#BOARD_ADDRESS#><#LINK#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5532', '1', 'core', 'public_email_content', 'subject__personal_convo_new_convo', '<a href=\'%s\'>%s</a> started a new <a href=\'%s\'>personal conversation</a> with you', '<a href=\'%s\'>%s</a> начал новую <a href=\'%s\'>беседу</a> с вами', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5533', '1', 'core', 'public_email_content', 'status_reply', '<#NAME#>,\n\n<#POSTER#> <#BLURB#>\n\nStatus: (<#OWNER#>) <#STATUS#>\n======================================================================\n<#TEXT#>\n======================================================================\n\n\nYou can turn off status notification by visiting <#URL#>\n', '<#NAME#>,\n\n<#POSTER#> <#BLURB#>\n\nСтатус: (<#OWNER#>) <#STATUS#>\n======================================================================\n<#TEXT#>\n======================================================================\n\n\nВы можете отключить уведомления по адресу <#URL#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5534', '1', 'core', 'public_email_content', 'complete_reg', '\nSuccess!\n\nAn administrator has accepted your registration request or email address change at <#BOARD_NAME#>. You may now log in with\nyour chosen details and access your full user account at <#BOARD_ADDRESS#>\n', '<#BOARD_NAME#>.\n\nПоздравляем! \n\nАдминистратор успешно активировал вашу регистрацию (или смену e-mail адреса).\nТеперь вы можете войти на форум и пользоваться всеми возможностями полноценного пользователя.\n\nАдрес форума: <#BOARD_ADDRESS#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5535', '1', 'core', 'public_email_content', 'subject__complete_reg', 'Account: %s, validated at %s', 'Учетная запись: %s, подтверждена %s', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5536', '1', 'core', 'public_email_content', 'new_post_queue_notify', 'Hello!\n\nThis email has been sent from: <#BOARD_NAME#>.\n\nA new post has been entered into the moderation queue and is awaiting\napproval.\n\n----------------------------------\nTopic: <#TOPIC#>\nForum: <#FORUM#>\nAuthor: <#POSTER#>\nTime: <#DATE#>\nManage Queue: <#LINK#>\n----------------------------------\n<#POST#>\n----------------------------------\n\nIf you no longer require notification, you can stop these emails by simply\nremoving your email address from the forum settings options.\n\n<#BOARD_ADDRESS#>\n\n', '<#BOARD_NAME#>\n\nНа форуме появилось новое сообщение для проверки и публикации/удаления модератором.\n\nТема: <#TOPIC#>\nФорум: <#FORUM#>\nАвтор:  <#POSTER#>\nВремя: <#DATE#>\n\nДля совершения действий с сообщением перейдите по ссылке: <#LINK#> \n----------------------------------\n<#POST#>\n----------------------------------\n\nЕсли вы больше не хотите получать такие уведомления, удалите ваш e-mail адрес в настройках форума.\n\nАдрес форума: <#BOARD_ADDRESS#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5537', '1', 'core', 'public_email_content', 'subject__new_post_queue_notify', 'New Post Awaiting Approval', 'Новое сообщение, требующее активации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5538', '1', 'core', 'public_email_content', 'subject__digest_forum_weekly', 'Your weekly new topics digest', 'Обзор новых тем за неделю', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5539', '1', 'core', 'public_email_content', 'digest_forum_weekly', '<#NAME#>,\n\nThis is the digest of posts created this week in forum <#FORUM_NAME#>.\n\n----------------------------------------------------------------------\n\n\n\n<#CONTENT#>\n\n\n\n\n----------------------------------------------------------------------\n\nThe forum can be found here:\n<#URL#>\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time by visiting the \"Content I Follow\" section of our community here: <#BOARD_ADDRESS#>?app=core&module=search&do=followed\n', '<#NAME#>, \n\nЭто письмо содержит обзор новых тем за последнюю неделю:\n\n---------------------------------------------------------------------- \n<#CONTENT#> \n---------------------------------------------------------------------- \n\nРаздел форума, на который вы подписались, по ссылке:\n<#BOARD_ADDRESS#>?showforum=<#FORUM_ID#>\n\nОтписаться:\n-------------- \nВы можете управлять своими подписками в данной секции форума: <#BOARD_ADDRESS#>?app=core&module=search&do=followed', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5540', '1', 'core', 'public_email_content', 'reg_validate', '\n<#NAME#>,\nThis email has been sent from <#BOARD_ADDRESS#>.\n\nYou have received this email because this email address\nwas used during registration for our forums.\nIf you did not register at our forums, please disregard this\nemail. You do not need to unsubscribe or take any further action.\n\n------------------------------------------------\nActivation Instructions\n------------------------------------------------\n\nThank you for registering.\nWe require that you \"validate\" your registration to ensure that\nthe email address you entered was correct. This protects against\nunwanted spam and malicious abuse.\n\nTo activate your account, simply click on the following link:\n\n<#THE_LINK#>\n\n(Some email client users may need to copy and paste the link into your web\nbrowser).\n\n------------------------------------------------\nNot working?\n------------------------------------------------\n\nIf you could not validate your registration by clicking on the link, please\nvisit this page:\n\n<#MAN_LINK#>\n\nIt will ask you for a user id number, and your validation key. These are shown\nbelow:\n\nUser ID: <#ID#>\n\nValidation Key: <#CODE#>\n\nPlease copy and paste, or type those numbers into the corresponding fields in the form.\n\nIf you still cannot validate your account, it\'s possible that the account has been removed.\nIf this is the case, please contact an administrator to rectify the problem.\n\nThank you for registering and enjoy your stay!\n', '<#NAME#>,\n\nВ форуме по адресу <#BOARD_ADDRESS#> появилась регистрационная запись,\nв которой был указал ваш электронный адрес (e-mail).\n\nЕсли вы не понимаете, о чем идет речь — просто проигнорируйте это сообщение!\n\nЕсли же именно вы решили зарегистрироваться в форуме по адресу <#BOARD_ADDRESS#>,\nто вам следует подтвердить свою регистрацию и тем самым активировать вашу учетную запись.\nПодтверждение регистрации производится один раз и необходимо для повышения безопасности форума и защиты его от злоумышленников.\nЧтобы активировать вашу учетную запись, необходимо перейти по ссылке:\n<#THE_LINK#>\nАктивация произойдет автоматически.\n\nЕсли таким способом активировать учетную запись не удалось, попробуйте сделать это вручную. Пройдите по ссылке\n<#MAN_LINK#>\nи введите указанные ниже ID пользователя и код активации (не пароль!) в соответствующие поля.\n\n===================================\nID пользователя: <#ID#>\nКод активации: <#CODE#>\n===================================\n\nПосле активации учетной записи вы сможете войти в форум, используя выбранные вами имя пользователя (login) и пароль. С этого момента вы сможете оставлять сообщения.\n\nПожалуйста, не забудьте заполнить свои личные данные.\n\nБлагодарим за регистрацию!', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5541', '1', 'core', 'public_email_content', 'send_text', 'I thought you might be interested in reading this web page: <#THE LINK#>\n\nFrom,\n\n<#USER NAME#>\n', 'Сообщение от пользователя: <#USER NAME#>\n\nСообщаю, что вам будет интересно прочитать указанную по ссылке страницу:\n<#THE LINK#> ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5542', '1', 'core', 'public_email_content', 'admin_newuser', '\nHello,\n\nYou have received this email because a new user has completed their registration!\n\n------------------------------------------------\nLog in name: <#LOG_IN_NAME#>\nDisplay name: <#DISPLAY_NAME#>\nEmail: <#EMAIL#>\nIP Address: <#IP#>\nDate: <#DATE#>\n------------------------------------------------\n\nYou can turn off user notification in the Admin Control Panel\n\nHave a super day!\n', 'Здравствуйте.\n\nПользователь <#LOG_IN_NAME#> зарегистрировался <#DATE#>\n\n(вы можете отключить подобные уведомления в админцентре)', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5543', '1', 'core', 'public_email_content', 'lost_pass', '\n<#NAME#>,\nThis email has been sent from <#BOARD_ADDRESS#>.\n\nYou have received this email because a user account password recovery\nwas instigated by you on <#BOARD_NAME#>.\n\n------------------------------------------------\nIMPORTANT!\n------------------------------------------------\n\nIf you did not request this password change, please IGNORE and DELETE this\nemail immediately. Only continue if you wish your password to be reset!\n\n------------------------------------------------\nActivation Instructions Below\n------------------------------------------------\n\nWe require that you \"validate\" your password recovery to ensure that\nyou instigated this action. This protects against\nunwanted spam and malicious abuse.\n\nSimply click on the link below and complete the rest of the form\n\n<#THE_LINK#>\n\n(Some email client users may need to copy and paste the link into your web\nbrowser).\n\n------------------------------------------------\nNot working?\n------------------------------------------------\n\nIf you could not validate your password recovery request by clicking on the link, please\nvisit this page:\n\n<#MAN_LINK#>\n\nIt will ask you for a user id number, and your validation key. These are shown\nbelow:\n\nUser ID: <#ID#>\n\nValidation Key: <#CODE#>\n\nPlease copy and paste, or type those numbers into the corresponding fields in the form.\n\n------------------------------------------------\nIs this not working?\n------------------------------------------------\n\nIf you cannot re-activate your account, it\'s possible that the account has been removed or you\nare in the process of another activation, such as registering or changing your registered email address.\nIf this is the case, then please complete the previous activation.\nIf the error persists, please contact an administrator to rectify the problem.\n\nIP address of sender: <#IP_ADDRESS#>\n\n', 'Здравствуйте, <#NAME#>!\n\nВы получили это письмо, поскольку был сделан запрос на восстановление вашего пароля в форуме «<#BOARD_NAME #>».\nЕсли вы не делали такой запрос, проигнорируйте и удалите это сообщение.\n\n\nЕсли же вы в самом деле забыли свой пароль, заново активируйте вашу учетную запись.\n\nЧтобы активировать вашу учетную запись, необходимо перейти по ссылке\n<#THE_LINK#>\nАктивация произойдет автоматически.\n\nЕсли таким способом сбросить пароль не удалось, попробуйте активировать вручную. Пройдите по ссылке\n<#MAN_LINK#>\nи введите указанные ниже ID пользователя и код активации (не пароль!) в соответствующие поля.\n\n===================================\nID пользователя: <#ID#>\nКод активации: <#CODE#>\n===================================\n\nПосле активации учетной записи следуйте инструкциям по восстановлению пароля, которые будет сообщать вам форум.\n\nЕсли ничего не получается, свяжитесь с администратором форума!\n(IP адрес отправителя: <#IP_ADDRESS#>)', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5544', '1', 'core', 'public_email_content', 'possibleSpammer', '\n\nHello,\n\nYou have received this email because you chose to be notified when a possible spammer is flagged.\n\nName: <#MEMBER_NAME#>\nEmail: <#EMAIL#>\nIP: <#IP#>\nRegistered: <#DATE#>\n\nYou can view this user here: <#LINK#>\n\nHave a super day!\n', 'Здравствуйте.\n\nОбнаружен возможный «спамер» (человек или робот, рассылающий спам).\n\nИмя: <#MEMBER_NAME#>\nE-mail: <#EMAIL#>\nIP-адрес: <#IP#>\nДата регистрации: <#DATE#> \n\nПросмотреть другую информацию и возможные действия по пользователю можно по ссылке:\n<#LINK#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5545', '1', 'core', 'public_email_content', 'digest_forum_daily', '<#NAME#>,\n\nThis is your daily new topics digest for forum <#FORUM_NAME#>!\n\n----------------------------------------------------------------------\n\n\n\n<#CONTENT#>\n\n\n\n\n----------------------------------------------------------------------\n\nThe forum can be found here:\n<#URL#>\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time by visiting the \"Content I Follow\" section of our community here: <#BOARD_ADDRESS#>?app=core&module=search&do=followed\n', '<#NAME#>, \n\nЭто письмо содержит обзор новых тем за сегодня:\n\n---------------------------------------------------------------------- \n<#CONTENT#> \n---------------------------------------------------------------------- \n\nРаздел форума, на который вы подписались, по ссылке:\n<#URL#>\n\nОтписаться:\n-------------- \nВы можете управлять своими подписками в данной секции форума: <#BOARD_ADDRESS#>?app=core&module=search&do=followed', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5546', '1', 'core', 'public_email_content', 'subject__digest_forum_daily', 'Your daily new topics digest', 'Обзор новых тем за день', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5547', '1', 'core', 'public_email_content', 'digest_topic_daily', '<#NAME#>,\n\nThis is the digest of posts in topic \"<#TITLE#>\" for today.\n\n----------------------------------------------------------------------\n\n\n\n<#CONTENT#>\n\n\n\n\n----------------------------------------------------------------------\n\nThe topic can be found here:\n<#URL#>\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time here: <#UNSUBCRIBE_URL#>\n', '<#NAME#>, \n\nЭто письмо содержит обзор сообщений темы «<#TITLE#>» за сегодня:\n\n---------------------------------------------------------------------- \n<#CONTENT#> \n---------------------------------------------------------------------- \n\nАдрес темы: <#BOARD_ADDRESS#>?showtopic=<#TOPIC_ID#>&view=getnewpost \n\nОтписаться:\n-------------- \nВы можете управлять своими подписками в боковом блоке «Подписки» вкладки «Обсуждения» на форуме.\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5548', '1', 'core', 'public_email_content', 'subject__digest_topic_daily', 'Your daily new posts digest', 'Обзор новых сообщений за день', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5549', '1', 'core', 'public_email_content', 'digest_topic_weekly', '<#NAME#>,\n\nThis is the digest of posts in topic \"<#TITLE#>\" for this week.\n\n----------------------------------------------------------------------\n\n\n\n<#CONTENT#>\n\n\n\n\n----------------------------------------------------------------------\n\nThe topic can be found here:\n<#URL#>\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time here: <#UNSUBCRIBE_URL#>\n', '<#NAME#>, \n\nЭто письмо содержит обзор сообщений темы «<#TITLE#>» за последнюю неделю:\n\n---------------------------------------------------------------------- \n<#CONTENT#> \n---------------------------------------------------------------------- \n\nАдрес: <#URL#>\n\nОтписаться:\n--------------\nВы можете управлять своими подписками в данной секции форума: <#BOARD_ADDRESS#>?app=core&module=search&do=followed', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5550', '1', 'core', 'public_email_content', 'subject__digest_topic_weekly', 'Your weekly new posts digest', 'Обзор новых сообщений за неделю', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5551', '1', 'core', 'public_email_content', 'newemail', '\n<#NAME#>,\nThis email has been sent from <#BOARD_ADDRESS#>.\n\nYou have received this email because you requested an\nemail address change.\n\n------------------------------------------------\nActivation Instructions Below\n------------------------------------------------\n\nWe require that you \"validate\" your email address change to ensure that\nyou instigated this action. This protects against\nunwanted spam and malicious abuse.\n\nTo activate your account, simply click on the following link:\n\n<#THE_LINK#>\n\n(Some email client users may need to copy and paste the link into your web\nbrowser).\n\n------------------------------------------------\nNot working?\n------------------------------------------------\n\nIf you could not validate your email address change by clicking on the link, please\nvisit this page:\n\n<#MAN_LINK#>\n\nIt will ask you for a user id number, and your validation key. These are shown\nbelow:\n\nUser ID: <#ID#>\n\nValidation Key: <#CODE#>\n\nPlease copy and paste, or type those numbers into the corresponding fields in the form.\n\nOnce the activation is complete, you may need to log back in to update your member group\npermissions.\n\n------------------------------------------------\nHelp! I get an error!\n------------------------------------------------\n\nIf you cannot re-activate your account, it\'s possible that the account has been removed or you\nare in the process of another activation, such as registering or changing your registered email address.\nIf this is the case, then please complete the previous activation.\nIf the error persists, please contact an administrator to rectify the problem.\n\n', 'Здравствуйте, <#NAME#>!\n\nВы получили это письмо, потому что выслали запрос на изменение E-mail.\n\n------------------------------------------------\nИнструкция по активации\n------------------------------------------------\n\nВам необходимо будет активировать изменение e-mail адреса, это необходимо для проверки того, что это действие сделали именно вы. Также это требуется для защиты от нежелательных злоупотреблений и спама.\n\nДля активации учетной записи зайдите по ссылке:\n\n<#THE_LINK#>\n\n------------------------------------------------\nНе сработало?\n------------------------------------------------\n\nЕсли подтвердить вам не удалось, зайдите по ссылке\n\n<#MAN_LINK#>\n\nи введите указанные ниже ID пользователя и код активации (не пароль!) в соответствующие поля.\n\n===================================\nID пользователя: <#ID#>\nКод активации: <#CODE#>\n===================================\n\nЕсли ничего не получается, свяжитесь с администратором форума!', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5552', '1', 'core', 'public_email_content', 'lost_pass_email_pass', '\n<#NAME#>,\nThis email has been sent from <#BOARD_ADDRESS#>.\n\nThis email completes your lost password request.\n\n------------------------------------------------\nYOUR NEW PASSWORD\n------------------------------------------------\n\nYour username is: <#USERNAME#>\nYour email address is: <#EMAIL#>\nYour new password is: <#PASSWORD#>\n\nLog in here: <#LOGIN#>\n\nPlease be careful to use the correct information (username or email address) to login to the site.\n\n------------------------------------------------\nCHANGING YOUR PASSWORD\n------------------------------------------------\n\nOnce you\'ve logged in, you can visit your User CP to\nchange your password.\n\nUser CP: <#THE_LINK#>\n\n', '<#BOARD_ADDRESS#>\n\n<#NAME#>, Вы создали новый пароль.\n\n------------------------------------------------ НОВЫЙ ПАРОЛЬ\n------------------------------------------------ \nИмя пользователя: <#USERNAME#>\nПароль: <#PASSWORD#>\nE-mail: <#EMAIL#>\n\nВойти на форум с новыми данными: <#LOGIN#>\n\n------------------------------------------------ ИЗМЕНЕНИЕ ПАРОЛЯ \n----------------------------------------\nПосле входа вы можете изменить свой пароль в своих личных данных: <#THE_LINK#>\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5553', '1', 'core', 'public_email_content', 'forward_page', '\n<#TO_NAME#>\n\n\n<#THE_MESSAGE#>\n\n---------------------------------------------------\nPlease note that <#BOARD_NAME#> has no control over the\ncontents of this message.\n---------------------------------------------------\n', '<#BOARD_NAME#>\n\n<#TO_NAME#> \n\n--------------------------------------------------- \n<#THE_MESSAGE#>\n---------------------------------------------------\n\nИмейте в виду, что форум не несет ответственность за содержание данного письма.\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5554', '1', 'core', 'public_email_content', 'subs_new_topic', '<#NAME#>,\n\n<#POSTER#> has just posted a new topic entitled \"<#TITLE#>\" in forum \"<#FORUM#>\".\n\n----------------------------------------------------------------------\n<#POST#>\n----------------------------------------------------------------------\n\nThe topic can be found here:\n<#URL#>\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time here: <#UNSUBCRIBE_URL#>\n\nIf you are not following any forums and wish to stop receiving notifications, uncheck the setting\n\"Send me any updates sent by the board administrator\" found in \'My Settings\' under \'Notification Options\'.\n', '<#NAME#>, <#POSTER#> открыл новую тему \"<#TITLE#>\" в разделе \"<#FORUM#>\".\n\n----------------------------------------------------------------------\n<#POST#>\n----------------------------------------------------------------------\n\nАдрес темы: <#BOARD_ADDRESS#>?showtopic=<#TOPIC_ID#> \n\nИмейте в виду, что вы можете подписаться на уведомления о новых ответах в этой теме. Это можно сделать как из самой темы, так и нажав на указанную ниже ссылку: <#BOARD_ADDRESS#>?app=core&module=usercp&tab=forums&area=watch&watch=topic&do=list&tid=<#TOPIC_ID#>\n\nОтписаться:\n-------------- \nВы можете управлять своими подписками в боковом блоке «Подписки» вкладки «Обсуждения» на форуме.\nЕсли вы не хотите больше получать никаких уведомлений с форума просто отключите соответствующую опцию « Сообщать мне обо всех изменениях, проводимых администратором форума.» в вашем профиле в меню «Общие настройки».\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5555', '1', 'core', 'public_email_content', 'subject__subs_new_topic', '<a href=\'%s\'>%s</a> posted topic <a href=\'%s\'>%s</a>', '<a href=\'%s\'>%s</a> создал тему <a href=\'%s\'>%s</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5556', '1', 'core', 'public_email_content', 'subject__new_topic_queue_notify', 'New Topic Awaiting Approval', 'Новая тема, требующая активации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5557', '1', 'core', 'public_email_content', 'post_was_quoted', 'Hello!\n\nThis message is to notify you that one of your posts has been quoted by <#MEMBER_NAME#>.\n\nThe post that was quoted can be found here:\n\n<#ORIGINAL_POST#>\n\nThe post that <#MEMBER_NAME#> submitted can be found here:\n\n<#NEW_POST#>\n\n----------------------------------\n<#POST#>\n----------------------------------\n\nIf you no longer wish to receive notifications of quoted posts, you can adjust your preferences on the\ncommunity by clicking My Settings, and then choosing Notification Options.\n\n<#BOARD_ADDRESS#>\n\n', 'Здравствуйте!\n\nУведомляем вас о том, что одно из ваших сообщений было процитировано <#MEMBER_NAME#>.\n\nПрочитать сообщение от <#MEMBER_NAME#> вы можете по ссылке: \n\n<#NEW_POST#>\n\n----------------------------------\n<#POST#>\n----------------------------------\n\nЕсли вы больше не хотите получать уведомления о цитировании ваших сообщений, вы можете изменить необходимые параметры в настройках вашего профиля в разделе «Настройки уведомлений».\n\n<#BOARD_ADDRESS#>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5558', '1', 'core', 'public_email_content', 'subs_with_post', '<#NAME#>,\n\n<#POSTER#> has just posted a reply to a topic that you have subscribed to titled \"<#TITLE#>\".\n\n----------------------------------------------------------------------\n<#POST#>\n----------------------------------------------------------------------\n\nThe topic can be found here: <#URL#>\n\n\n\nIf you have configured in your control panel to receive immediate topic reply notifications, you may receive an\nemail for each reply made to this topic.  Otherwise, only 1 email is sent per board visit for each subscribed topic. \nThis is to limit the amount of mail that is sent to your inbox.\n\nUnsubscribing:\n--------------\n\nYou can unsubscribe at any time here: <#UNSUBCRIBE_URL#>\n', '<#NAME#>, <#POSTER#> опубликовал ответ в тему \"<#TITLE#>\", на которую вы подписаны.\n\n----------------------------------------------------------------------\n<#POST#>\n----------------------------------------------------------------------\n\nАдрес темы: <#BOARD_ADDRESS#>?showtopic=<#TOPIC_ID#>&view=getnewpost\n\nЕсли у вас включена немедленная доставка уведомлений о новых сообщениях в этой теме, вы будете получать письмо с уведомлением на каждый новый ответ в тему. В противном случае только одно такое письмо со всеми новыми ответами будет приходить между каждым вашим визитом на форум.\n\nВы можете управлять своими подписками в боковом блоке «Подписки» вкладки «Обсуждения» на форуме.\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5559', '1', 'core', 'public_email_content', 'subject__subs_with_post', '<a href=\'%s\'>%s</a> replied to <a href=\'%s\'>%s</a>', '<a href=\'%s\'>%s</a> ответил в тему <a href=\'%s\'>%s</a>', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5560', '1', 'core', 'public_email_content', 'email_member', '<#MEMBER_NAME#>,\n\n<#FROM_NAME#> has sent you this email from <#BOARD_ADDRESS#>.\n\n\n<#MESSAGE#>\n\n---------------------------------------------------\nPlease note that <#BOARD_NAME#> has no control over the\ncontents of this message.\n---------------------------------------------------\n\n', '<#BOARD_ADDRESS#>\n\n<#MEMBER_NAME#>, \n\n<#FROM_NAME#> отправил вам письмо.\n\n---------------------------------------------------\n <#MESSAGE#> \n--------------------------------------------------- \n\nИмейте в виду, что форум не несет ответственность за содержание данного письма.\n', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5561', '1', 'core', 'public_error', 'noappcomments', 'There was a problem with the request.  Please go back and try again.', 'Возникла проблема с обработкой запроса. Попробуйте вернуться на предыдущую страницу и повторить действие снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5562', '1', 'core', 'public_error', 'posting_bad_captcha', 'You did not provide the correct words for the security check.', 'Вы ввели некорректные слова в коде безопасности.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5563', '1', 'core', 'public_error', 'nocomment_found', 'We could not find the comment you were looking for.', 'Система не смогла найти комментарий, который вы ищете.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5564', '1', 'core', 'public_error', 'forward_turned_off', 'Sorry, this feature has been disabled', 'К сожалению в данный момент возможность отключена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5565', '1', 'core', 'public_error', 'login_no_authkey', 'We encountered a problem processing your login request.  Please try again.', 'Произошла ошибка в процессе авторизации. Пожалуйста попробуйте позже.', '32006', '', '0');
