INSERT INTO `ibf_core_sys_lang_words` VALUES ('5568', '1', 'core', 'public_error', 'fb_not_remote', 'You cannot log in with your Facebook credentials for this member. You must log in with your community credentials using the normal log in form', 'Вы не можете зайти на форум с использованием этого Facebook-аккаунта. Вам необходимо зайти на форум используя обычные данные.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5569', '1', 'core', 'public_error', 'no_remote_reg', 'The administrator has disabled all registrations and as such, you are not able to complete your log in at this time.', 'Администрация отключила возможность регистрации на форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5570', '1', 'core', 'public_error', 'incorrect_furl', 'Sorry, we could not locate the page you are requesting to view. Please click <a href=\'#\' onclick=\'window.location = ipb.vars.base_url\'>here</a> to return to the community index', 'К сожалению, не удалось найти запрашиваемую вами страницу. Пожалуйста вернитесь на <a href=\'#\' onclick=\'window.location = ipb.vars.base_url\'>главную страницу</a> форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5571', '1', 'core', 'public_error', 'twitter_app_error', 'There is an error with your Twitter application settings. Please check to ensure that you have properly set a callback URL in your Twitter application configuration.', 'Есть проблема с настройками вашего Twitter-приложения. Пожалуйста, убедитесь, что в приложении указан правильный callback URL', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5572', '1', 'core', 'public_error', 'twit_not_remote', 'You cannot log in with your Twitter credentials for this member. You must log in with your community credentials using the normal log in form', 'Вы не можете авторизоваться с использованием Twitter-аккаунта. Вам необходимо войти в систему используя обычны способ входа.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5573', '1', 'core', 'public_error', 'err_UNKNOWN', 'An unknown error occurred ', 'Возникла ошибка ', '32006', '', '0');
