INSERT INTO `ibf_core_sys_lang_words` VALUES ('5578', '1', 'core', 'public_error', 'moderate_no_permission_deleted_items', 'You do not have permisson to remove or restore one or more of the selected posts or topics.', 'Вы не можете восстанавливать удаленные публикации', '32006', '', '0');
