INSERT INTO `ibf_core_sys_lang_words` VALUES ('5587', '1', 'core', 'public_error', 'command_class_incorrect', 'The requested action could not be performed, there are no valid commands classes in the requested file: %s', 'Запрашиваемое действие не может быть выполнено. В файле: %s не найдены необходимые классы действий.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5588', '1', 'core', 'public_error', 'command_file_missing', 'The requested action could not be performed, because we could not locate the following file: %s', 'Запрашиваемое действие не может быть выполнено. Требуемый файл: %s не найден', '32006', '', '0');
