INSERT INTO `ibf_core_sys_lang_words` VALUES ('5590', '1', 'core', 'public_error', 'search_off', 'Search is not enabled on the community at this time.', 'В данный момент поиск на форуме отключен.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5591', '1', 'core', 'public_error', 'no_permission_for_display_names', 'You do not have permission to change your display name.', 'Вы не можете изменить имя пользователя.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5592', '1', 'core', 'public_error', 'no_permission_to_search', 'You do not have permission to use the search system.', 'Вы не можете использовать поиск на форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5593', '1', 'core', 'public_error', 'bad_delete_cookies_key', 'The link you followed to delete your cookies appears to be badly formed.  Please go back and click the link again.', 'Очистить cookies не удалось. Ссылка «Очистить cookies» имеет неверный формат.  Пожалуйста, вернитесь назад и попробуйте еще раз.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5594', '1', 'core', 'public_error', 'you_are_banned', 'You are not allowed to visit this community.', 'Вам запрещено просматривать форум.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5595', '1', 'core', 'public_error', 'bad_logout_key', 'The link you followed to logout appears to be badly formed.  Please go back and click the link again.', 'Выйти не удалось. Ссылка «Выход» имеет неверный формат.  Пожалуйста, вернитесь назад и попробуйте еще раз.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5596', '1', 'core', 'public_error', 'no_view_board', 'You are not allowed to visit this community.', 'Вы не можете просматривать форум.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5597', '1', 'core', 'public_error', 'validation_key_incorrect', 'The validation key you supplied to reset your password does not appear to be valid.', 'Не удалось сбросить пароль. Ключ валидации неверный.', '32006', '', '0');
