INSERT INTO `ibf_core_sys_lang_words` VALUES ('5599', '1', 'core', 'public_error', 'uid_key_incorrect', 'The user id you supplied to reset your password does not appear to be valid.', 'Неверный идентификатор пользователя.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5600', '1', 'core', 'public_error', 'fbc_authorization_already_linked', 'That member account is already linked to a Facebook profile', 'Пользовательская запись уже присоединена к Facebook', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5601', '1', 'core', 'public_error', 'fbc_disabled', 'Facebook Connect is not enabled', 'Facebook Connect отключен', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5602', '1', 'core', 'public_error', 'no_login_methods', 'Could not load any login handlers', 'Не удалось загрузить модули авторизации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5603', '1', 'core', 'public_error', 'lostpass_no_member', 'We could not find the member account for the user id you supplied.', 'Пользователя с такими данными не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5604', '1', 'core', 'public_error', 'lostpass_not_validating', 'The member specified is not presently awaiting validation for a lost password request.', 'Пользователь не запрашивал восстановление пароля.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5605', '1', 'core', 'public_error', 'lostpass_not_lostpass', 'Your lost password reset request is not actually a lost password reset request.  Yes, we\'re confused too.  Please report this to an administrator.', 'Ваш запрос на восстановление пароля на самом деле не является запросом на восстановление пароля. Вы не понимаете о чем это, к сожалению мы тоже. Пожалуйста свяжитесь с администрацией форума и сообщите им об этой ошибке.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5606', '1', 'core', 'public_error', 'lostpass_key_wrong', 'The validation key supplied does not match the key we have on record.  Please verify it is correct and resubmit the request.', 'Ключ валидации не совпадает с ключем, хранящимся в наших записях. Вероятно, вам следует повторить отправку запроса. ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5607', '1', 'core', 'public_error', 'lostpass_new_reg', 'Your account is awaiting admin validation.  An admin will take a look at it as soon as possible.', 'Ваша учетная запись ожидает подтверждения администратора.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5608', '1', 'core', 'public_error', 'lostpass_name_email', 'You did not supply your name or email address.', 'Вы не ввели имя или e-mail.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5609', '1', 'core', 'public_error', 'lostpass_external_fail', 'There was an error changing your password in one of our external systems.  Please notify an administrator.', 'Возникла проблема со сменой пароля. Сообщите об этом администрации форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5610', '1', 'core', 'public_error', 'lostpass_no_user', 'We could not find the member account for the name or email address you supplied.  Please verify the information and resubmit the form.', 'К сожалению нам не удалось найти пользователя с такими данными. Пожалуйста проверьте отправляемую информацию.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5611', '1', 'core', 'public_error', 'lostpass_no_mid', 'We found your member account, but there is no member id set for the account.  Please notify an administrator.', 'Пользователь найден, однако, его запись повреждена. Пожалуйста, сообщите об этом администрации форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5612', '1', 'core', 'public_error', 'coppa_form_fill', 'You must select your birthday from the dropdown menus before you can continue.', 'Вы должны указать ваш день рождения прежде чем продолжить регистрацию.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5613', '1', 'core', 'public_error', 'partial_reg_noid', 'We could not find the partial registration record, or your member account.  Please notify an administrator.', 'Пользователь найден, однако, его запись повреждена. Пожалуйста, сообщите об этом администрации форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5614', '1', 'core', 'public_error', 'no_validate_key', 'We could not find the validation request you are attempting to verify.  This is likely because you have already validated your account, or an administrator has validated your account for you.  Please try to login with your registration details now.', 'Неверный ключ активации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5615', '1', 'core', 'public_error', 'validate_admin_turn', 'You have completed your portion of the validation request already.  An administrator must approve your account before you have full access.', 'Спасибо за активацию аккаунта. Администрация форума должна проверить вашу учетную запись, прежде чем вы получите полный доступ к форуму.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5616', '1', 'core', 'public_error', 'validation_key_invalid', 'Your validation key did not match the one in our records.  Please verify the link you followed or contact an administrator for assistance.', 'Неверный ключ активации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5617', '1', 'core', 'public_error', 'registration_disabled', 'The administrator is currently not accepting new membership registrations.', 'В данный момент регистрация на форуме отключена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5618', '1', 'core', 'public_error', 'awaiting_coppa', 'You must have your parent or guardian complete the COPPA form and submit it to the administrator before your member account can be created.', 'Необходимо чтобы ваши родители или опекуны заполнили форму COPPA и отправили ее администрации форума перед созданием учетной записи на форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5619', '1', 'core', 'public_error', 'reputation_missing_data', 'Your reputation submission could not be saved because not all of the necessary information was provided.', 'Репутация не может быть изменена, так как в запросе отсутствуют необходимые данные.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5620', '1', 'core', 'public_error', 'help_no_id', 'The help topic you requested could not be found.', 'Раздел помощи, запрошенный вами, не удалось найти.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5621', '1', 'core', 'public_error', 'han_login_create_failed', 'Your account could not be created in our external system properly.  Please notify an administrator.', 'Не удалось добавить вашу учетную запись во внешнюю базу пользователей. Пожалуйста свяжитесь с администрацией форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5622', '1', 'core', 'public_error', 'no_report_none_perm', 'We couldn\'t figure out what you were attempting to accomplish, so we felt an error was appropriate.', 'У вас не достаточно прав чтобы завершить то, что вы хотите.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5623', '1', 'core', 'public_error', 'reports_need_tidcid', 'You did not submit enough information for us to find the report you requested.', 'Отправленных данных не достаточно, чтобы система смогла найти запрашиваемую жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5624', '1', 'core', 'public_error', 'reports_no_topic', 'Well, we thought there was an open report on this topic but perhaps we were wrong.  Go back and try reporting the topic again.', 'В системе не найдено запрашиваемой жалобы. Вероятно стоит повторить отправку жалобы на тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5625', '1', 'core', 'public_error', 'reports_what_now', 'We could not determine what type of content you are attempting to report.', 'Не удалось определить тип содержимого, на которое вы хотите отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5626', '1', 'core', 'public_error', 'no_report_prune_perm', 'You do not have permission to prune or delete reports.', 'У вас не достаточно прав чтобы удалять жалобы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5627', '1', 'core', 'public_error', 'no_reports_permission', 'You do not have permission to access the report center.', 'У вас нет доступа к системе жалоб.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5628', '1', 'core', 'public_error', 'report_not_found', 'The report that you are attempting to view could not be found.', 'Жалоба не найдена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5629', '1', 'core', 'public_error', 'search_plugin_file', 'We could not find a file to appropriately search our systems.', 'Не найден соответствующий плагин поиска.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5630', '1', 'core', 'public_error', 'search_plugin_class', 'We could not find a file to appropriately search our systems.', 'Не найден соответствующий плагин поиска.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5631', '1', 'core', 'public_error', 'search_invalid_plugin', 'We could not find a file to appropriately search our systems.', 'Не найден соответствующий плагин поиска.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5632', '1', 'core', 'public_error', 'reports_like_whoa', 'Hmm, well that is certainly odd.  The number of reports we found in the database to delete doesn\'t match what you requested to delete.  Please try again.', 'Количество жалоб, отмеченных как удаляемые не совпадают с количеством жалоб, которые хотите удалить вы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5633', '1', 'core', 'public_error', 'reports_no_comment', 'We could not find the report you are attempting to submit a comment to.', 'Не удалось сохранить комментарий к жалобе, так как в запросе отсутствуют необходимые данные.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5634', '1', 'core', 'public_error', 'reports_no_rid', 'We could not find the report you are attempting to view.', 'Жалоба не найдена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5635', '1', 'core', 'public_error', 'reports_cant_empty', 'You must submit a message with your report.', 'Необходимо написать жалобу, прежде чем отправить ее.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5636', '1', 'core', 'public_error', 'reports_cant_report', 'You do not have permission to report the item you are attempting to report.', 'У вас не достаточно прав для отправки жалобы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5637', '1', 'core', 'public_error', 'sphinx_api_missing', 'Search is not available as the Sphinx API is not available, please contact an administrator about this issue', 'Поиск не доступен. Отсутствует Sphinx API. Пожалуйста, свяжитесь с администрацией форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5638', '1', 'core', 'public_error', 'search_no_term', 'You must specify a search term.', 'Необходимо ввести ключ поиска.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5639', '1', 'core', 'public_error', 'usercp_bad_tab', 'We could not find the section of the User Control Panel you requested.', 'Не удалось найти запрашиваемую вами секцию пользовательской панели.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5640', '1', 'core', 'public_error', 'reports_blog_entry_id', 'We could not determine which blog or entry you are attempting to report.', 'Системе не удалось найти запись в блоге или сам блог на которую(ый) вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5641', '1', 'core', 'public_error', 'reports_no_entry', 'We could not find the blog entry that you are attempting to report.', 'Системе не удалось найти запись в блоге на которую вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5642', '1', 'core', 'public_error', 'reports_must_be_member', 'You must be a registered member and logged in to our site in order to report this content.', 'Для отправки жалобы вам необходимо быть зарегистрированным и авторизованным пользователем.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5643', '1', 'core', 'public_error', 'reports_input_not_match', 'The data you submitted does not match the expected format.', 'Данные, отправленные вами, не соответствуют необходимому формату.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5644', '1', 'core', 'public_error', 'reports_cannot_view_entry', 'You do not have permission to report this blog entry.', 'У вас нет прав чтобы отправить жалобу на эту запись блога.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5645', '1', 'core', 'public_error', 'reports_no_msg', 'We could not find the private message you were attempting to report.', 'Системе не удалось найти личное сообщение на которое вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5646', '1', 'core', 'public_error', 'reports_no_file', 'We could not determine which file you were attempting to report.', 'Системе не удалось найти файл на который вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5647', '1', 'core', 'public_error', 'contact_what_action', 'You didn\'t specify what action you would like to take.', 'Неверное использование функций форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5648', '1', 'core', 'public_error', 'reports_no_member', 'We could not find the member profile you were attempting to report', 'Системе не удалось найти пользователя на чей профиль вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5649', '1', 'core', 'public_error', 'reports_missing_tidpid', 'We could not determine which topic or post you were attempting to report.', 'Системе не удалось найти тему или сообщение на которую(ое) вы пытаетесь отправить жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5650', '1', 'core', 'public_error', 'contact_need_message', 'You did not specify why you are reporting this post.', 'Вы не указали причину по которой отправляете жалобу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5651', '1', 'core', 'public_error', 'announcements_supermods', 'Only super-moderators have access to manage announcements on our site.', 'Управление объявлениями доступно только супермодераторам.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5652', '1', 'core', 'public_error', 'members_only_mail', 'Only members may contact other members through our community.', 'Только зарегистрированные пользователи могут отправлять e-mail письма друг другу.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5653', '1', 'core', 'public_error', 'mail_member_private', 'Sorry, but this member does not wish to be contacted by email through this community.', 'К сожалению пользователь не желает получать email письма от других пользователей форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5654', '1', 'core', 'public_error', 'mail_member_no_member', 'We could not find the member you were attempting to send an email to.', 'Система не смогла найти пользователя, которому вы пытаетесь отправить e-mail.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5655', '1', 'core', 'public_error', 'mail_member_no_mid', 'We could not determine which member you were attempting to send an email to.', 'Система не смогла найти пользователя, которому вы пытаетесь отправить e-mail.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5656', '1', 'core', 'public_error', 'no_member_mail', 'Sorry, you are not permitted to send an email via this community.', 'Извините, но вам не доступна возможность отправки e-mail писем с форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5657', '1', 'core', 'public_error', 'forward_only_members', 'Only members can forward topics from our community.', 'Отправка темы по e-mail доступна только зарегистрированным пользователям.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5658', '1', 'core', 'public_error', 'forward_no_fid', 'We could not determine which forum the topic is in.', 'Системе не удалось найти форум, которому принадлежит данная тема.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5659', '1', 'core', 'public_error', 'forward_no_tid', 'We could not determine which topic you were attempting to forward.', 'Темы не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5660', '1', 'core', 'public_error', 'email_address_invalid', 'The email address you entered is not in a valid format.  Please check it and resubmit the form.', 'Введенный вами e-mail адрес неверный. Пожалуйста проверьте его и отправьте форму снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5661', '1', 'core', 'public_error', 'announcement_id_missing', 'We could not determine which announcement you were attempting to view.', 'Система не смогла найти объявление, которое вы пытаетесь посмотреть.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5662', '1', 'core', 'public_error', 'attach_missing_tid', 'We could not determine which topic you were attempting to view attachments from.', 'Система не смогла найти тему к которой принадлежат прикрепленные файлы, которые вы пытаетесь посмотреть.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5663', '1', 'core', 'public_error', 'announcement_no_perms', 'You do not have permission to read the requested announcement.', 'У вас нет прав чтобы прочитать запрашиваемое объявление.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5664', '1', 'core', 'public_error', 'attach_no_attachments', 'The specified topic does not have any attachments to view.', 'Указанная тема не содержит прикрепленных файлов.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5665', '1', 'core', 'public_error', 'attach_no_forum_perm', 'You do not have permission to view attachments in the forum this topic is in.', 'У вас нет прав для просмотра прикрепленный файлов в форуме в котором находится тема с прикреплениями.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5666', '1', 'core', 'public_error', 'findpost_missing_topic', 'We could not find the topic that this post belongs to.', 'Система не смогла найти тему к которой принадлежит это сообщение.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5667', '1', 'core', 'public_error', 'forums_no_id', 'We could not find the forum you were attempting to view.', 'Система не смогла найти форум, который вы пытаетесь посмотреть.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5668', '1', 'core', 'public_error', 'findpost_missing_pid', 'We could not find the post you were attempting to view.', 'Система не смогла найти сообщение, которое вы пытаетесь посмотреть.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5669', '1', 'core', 'public_error', 'forums_why_l_gt_1', 'Why is the L greater than 1?  Looks kinda suspicious if you ask me.', 'Почему L больше 1? Потому что гладиолус!', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5670', '1', 'core', 'public_error', 'forums_no_rules', 'There are no forum-specific rules configured for this forum.  Please refer to the community rules instead.', 'Данный раздел не имеет каких-то особенных правил. Пожалуйста ознакомьтесь с основными правилами форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5671', '1', 'core', 'public_error', 'forums_no_access', 'You do not have permission to view topics in this forum.', 'У вас нет прав для просмотра тем в данном форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5672', '1', 'core', 'public_error', 'forums_pass_blank', 'This forum requires a password to gain access to it.  Please go back and fill in the password field before submitting the form.', 'Данный форум защищен паролем. Пожалуйста вернитесь назад и заполните поле пароля, прежде чем снова отправить форму.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5673', '1', 'core', 'public_error', 'forums_wrong_pass', 'Sorry, but the password you entered is not correct.  Please contact an administrator for assistance.', 'К сожалению введенный вами пароль не верен. Обратитесь к администрации форума за помощью.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5674', '1', 'core', 'public_error', 'markread_no_id', 'We could not find the forum id you were attempting to mark as read.', 'Система не смогла найти форум, который вы хотите пометить прочтенным.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5675', '1', 'core', 'public_error', 'topics_no_tid', 'We could not determine which topic you were attempting to view.', 'Система не смогла найти тему, которую вы пытаетесь посмотреть.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5676', '1', 'core', 'public_error', 'topic_not_approved', 'You do not have permission to view this topic.', 'У вас нет прав для просмотра этой темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5677', '1', 'core', 'public_error', 'topics_no_fid', 'We could not determine which forum this topic is in.', 'Система не смогла найти форум, которому принадлежит тема.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5678', '1', 'core', 'public_error', 'topic_rate_locked', 'You are not allowed to rate topics that are locked.', 'Вы не можете оценивать закрытые темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5679', '1', 'core', 'public_error', 'topic_rate_no_perm', 'You do not have permission to rate this topic.', 'У вас нет прав для выставления рейтинга этой теме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5680', '1', 'core', 'public_error', 'topic_cannot_vote', 'You do not have permission to vote in this poll.', 'Вы не можете голосовать в данном опросе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5681', '1', 'core', 'public_error', 'topic_vote_already', 'You have already voted in this poll. You are only allowed to vote in a poll once.', 'Вы уже голосовали в этом опросе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5682', '1', 'core', 'public_error', 'forums_bad_filter', 'The topic filter settings you submitted are not valid.  Please go back and reset your topic filter settings.', 'Параметры фильтрации темы неверны. Пожалуйста вернитесь назад и обновите настройки фильтра темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5683', '1', 'core', 'public_error', 'topic_vote_noreply', 'You do not have permission to vote in this poll.', 'Вы не можете оставлять сообщения в данном опросе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5684', '1', 'core', 'public_error', 'topic_vote_locked', 'You are not allowed to vote in polls that are locked.', 'Вы не можете голосовать в опросах, которые закрыты.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5685', '1', 'core', 'public_error', 'topics_post_not_in_topic', 'You requested a post that is not part of this topic.  Please verify the URL you clicked or contact an administrator.', 'Вы запросили сообщение, которое не является частью данной темы. Проверьте правильность ссылки, по которой вы нажали или обратитесь к администрации форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5686', '1', 'core', 'public_error', 'topics_none_newer', 'There are no newer topics in this forum.', 'В форуме не осталось новых тем.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5687', '1', 'core', 'public_error', 'topics_none_older', 'There are no older topics in this forum.', 'В форуме не осталось старых тем.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5688', '1', 'core', 'public_error', 'topic_vote_not_enough', 'You must cast your vote in each question of the poll.', 'Необходимо ответить на каждый вопрос опроса.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5689', '1', 'core', 'public_error', 'topics_not_yours', 'You cannot view this topic because it is not your topic and the administrator has specified that you can only view your own topics.', 'Вы пытаетесь просмотреть тему, автором которой вы не являетесь. Вы можете просматривать только свои темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5690', '1', 'core', 'public_error', 'topics_not_yours2', 'You cannot view this topic because it is not your topic and the administrator has specified that you can only view your own topics in this forum.', 'Вы пытаетесь просмотреть тему, автором которой вы не являетесь. В данном разделе форума вы можете просматривать только свои темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5691', '1', 'core', 'public_error', 'tracker_no_tid', 'We could not determine which topic you are attempting to subscribe to.', 'Тема, на которую вы пытаетесь подписаться, не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5692', '1', 'core', 'public_error', 'tracker_no_fid', 'We could not determine which forum the topic you are attempting to subscribe to is in.', 'Системе не удалось найти форум темы на которую вы пытаетесь подписаться.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5693', '1', 'core', 'public_error', 'tracker_only_members', 'Only registered members can subscribe to topics on our community.  Why not register an account?', 'Опция отслеживания тем доступна только нашим зарегистрированным пользователям. Почему бы не зарегистрироваться сейчас?', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5694', '1', 'core', 'public_error', 'tracker_already_track', 'You are already subscribed to this topic.', 'Вы уже подписаны на эту тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5695', '1', 'core', 'public_error', 'mod_no_move_forum', 'We could not determine which forum you were attempting to move the topic into.', 'Форума, куда вы пытаетесь перенести тему, не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5696', '1', 'core', 'public_error', 'mod_admin_edit', 'You are not permitted to edit an administrator.', 'Вы не можете редактировать профиль администратора.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5697', '1', 'core', 'public_error', 'mod_only_supermods', 'Only supermoderators have access to perform this function.', 'Данная возможность доступна только супермодераторам.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5698', '1', 'core', 'public_error', 'mod_no_mid', 'We could not determine which member you were attempting to edit.', 'Системе не удалось найти пользователя, профиль которого вы пытаетесь отредактировать.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5699', '1', 'core', 'public_error', 'mod_no_move_save', 'Why, oh why, would you attempt to move a topic into the same forum it is already in?  Do YOU see the logic in that?', 'Вы пытаетесь переместить тему в тот же самый форум, в котором она находится сейчас.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5700', '1', 'core', 'public_error', 'mod_no_delete_post_find', 'We could not find the post you were attempting to delete.', 'Сообщение, которое вы пытаетесь удалить, не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5701', '1', 'core', 'public_error', 'mod_um_what_now', 'We couldn\'t figure out what you were attempting to do.', 'Действие, которое вы пытаетесь произвести, не существует в системе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5702', '1', 'core', 'public_error', 'mod_topics_merge_two', 'You need to select at least two topics in order to merge them.', 'Для объединения необходимо выбрать как минимум две темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5703', '1', 'core', 'public_error', 'mod_no_prune_member', 'We could not find the member whose topics you are attempting to prune.', 'Пользователь, чьи сообщения вы пытаетесь удалить, не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5704', '1', 'core', 'public_error', 'mod_no_prune_topics', 'We could not find any topics to prune that met your filter criteria.', 'Системе не удалось найти сообщения для удаления, удовлетворяющие вашему фильтру.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5705', '1', 'core', 'public_error', 'mod_no_open_perms', 'You do not have permission to open this topic.', 'Вы не можете открыть эту тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5706', '1', 'core', 'public_error', 'mod_no_open_opened', 'The topic you are attempting to open is already open.', 'Вы пытаетесь открыть уже открытую тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5707', '1', 'core', 'public_error', 'mod_no_topic_title', 'You must specify the topic title.', 'Вы должны указать название темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5708', '1', 'core', 'public_error', 'mod_no_delete_post', 'You do not have permission to delete the post.', 'Вы не можете удалить это сообщение', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5709', '1', 'core', 'public_error', 'moderate_no_permission', 'You do not have permission to carry out that function.', 'Вы не можете использовать эту возможность.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5710', '1', 'core', 'public_error', 'mod_same_topics', 'You cannot merge a topic into itself.  That would be illogical captain! (tm)', 'Вы пытаетесь объединить тему саму с собой. Это же не логично!', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5711', '1', 'core', 'public_error', 'mod_missing_old_topic', 'We could not find one of the topics you were attempting to merge.', 'Не существует одной из тем, которые вы пытаетесь объединить.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5712', '1', 'core', 'public_error', 'mod_no_delete_topic', 'You do not have permission to delete this topic.', 'Вы не можете удалить эту тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5713', '1', 'core', 'public_error', 'mod_missing_url_title', 'You must fill in the form completely.  You omitted either the URL of the topic or the new topic title.', 'Похоже что вы не заполнили форму надлежащим образом. Вы пропустили или URL, или название новой темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5714', '1', 'core', 'public_error', 'mod_no_close_topic', 'You do not have permission to close this topic.', 'Вы не можете закрыть эту тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5715', '1', 'core', 'public_error', 'mod_no_pids', 'You did not select any posts for moderation.', 'Вы не выбрали ни одного сообщения для осуществления этого действия.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5716', '1', 'core', 'public_error', 'mod_only_one_pid', 'You must select more than one post for moderation.', 'Необходимо выбрать более одного сообщения для осуществления этого действия.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5717', '1', 'core', 'public_error', 'mod_merge_posts', 'It appears we\'re missing some input from your form submission.  Did you fill in the form completely?', 'Недостаточно данных для завершения этого действия. Пожалуйста убедитесь, что форма была правильно заполнена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5718', '1', 'core', 'public_error', 'mod_forum_no_posts', 'The forum you are attempting to move the topic to does not allow posting or displaying of topics.', 'Вы пытаетесь перенести тему в форум где запрещен просмотр тем или отправка сообщений. ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5719', '1', 'core', 'public_error', 'mod_no_forum_move', 'We could not find the forum you were attempting to place the topic into.', 'Вы пытаетесь перенести тему в несуществующий форум.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5720', '1', 'core', 'public_error', 'mod_need_title', 'You must specify the topic title of the new topic.', 'Вы должны ввести название новой темы.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5721', '1', 'core', 'public_error', 'mod_delete_first_post', 'You cannot delete the first post in a topic.  You should delete the topic itself instead.', 'Вы пытаетесь удалить первое сообщение в теме. Этого делать нельзя. Если вам нужно удалить тему, воспользуйтесь специально предназначенной для этого опцией.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5722', '1', 'core', 'public_error', 'mod_too_much_split', 'You cannot split all posts within this topic to another topic.  You must leave at least one post in this topic.', 'Вы пытаетесь перенести все сообщения темы, этого делать нельзя. В старой теме должно остаться хотя бы одно сообщение.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5723', '1', 'core', 'public_error', 'mod_not_enough_split', 'There are not enough posts in this topic to split it.', 'В этой теме недостаточно сообщений для того чтобы разделить ее.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5724', '1', 'core', 'public_error', 'mod_no_tid', 'We could not determine which topic you were attempting to moderate.', 'Темы не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5725', '1', 'core', 'public_error', 'mod_topic_unpinned', 'The topic you are attempting to unpin is not currently pinned.', 'Вы пытаетесь опустить уже опущенную тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5726', '1', 'core', 'public_error', 'mod_topic_pinned', 'The topic you are attempting to pin is already pinned.', 'Вы пытаетесь поднять уже поднятую тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5727', '1', 'core', 'public_error', 'posting_restricted', 'Your posting rights have been removed by an administrator.', 'Вам запрещено общаться на форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5728', '1', 'core', 'public_error', 'posting_off_susp', 'Your posting rights have been temporarily suspended. The suspension is due to end %s.', 'Вам запретили общаться на форуме до %s.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5729', '1', 'core', 'public_error', 'flood_control', 'The administrator has limited the number of new posts you can submit within a short time frame. Please wait %s seconds before replying or posting a new topic.', 'Стоит делать передышку в %s секунд между отправками новых тем и сообщений.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5730', '1', 'core', 'public_error', 'posting_bad_action', 'We could not determine what action you were attempting to take.', 'Невозможно определить что пытаетесь сделать.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5731', '1', 'core', 'public_error', 'multimod_not_found', 'We could not determine which multi-moderation tool you were attempting to use.', 'Запрашиваемое действие мульти-модерации не существует в системе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5732', '1', 'core', 'public_error', 'multimod_no_perms', 'You do not have permission to use this multi-moderation tool on this topic.', 'Вы не можете использовать мульти-модерацию на данной теме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5733', '1', 'core', 'public_error', 'multimod_no_topic', 'We could not determine which topic you were attempting to take action against.', 'Темы не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5734', '1', 'core', 'public_error', 'mod_bad_fid', 'You appear to have submitted an invalid forum.', 'Идентификатор форума неверен.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5735', '1', 'core', 'public_error', 'mod_bad_pid', 'You appear to have submitted an invalid post.', 'Идентификатор сообщения неверен.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5736', '1', 'core', 'public_error', 'mod_bad_tid', 'You appear to have submitted an invalid topic.', 'Идентификатор темы неверен.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5737', '1', 'core', 'public_error', 'mod_no_authorization_key', 'We use an authorization key to verify you really submitted the form, and the authorization key was not supplied with your form submission or was invalid.  Please go back, reload the form and try to submit it again.', 'Для подтверждения того, что именно вы отправили формы используется ключ авторизации. Вместе с этой формой ключ не был отправлен либо он неверный. Пожалуйста, вернитесь назад, обновите страницу и попробуйте отправить снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5738', '1', 'core', 'public_error', 'mod_no_mm_id', 'We could not determine which multi-moderation tool you were attempting to use.', 'Невозможно определить какой инструмент мультимодерации вы пытаетесь использовать.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5739', '1', 'core', 'public_error', 'mod_no_multimod', 'You do not have permission to use this multi-moderation tool.', 'Вы не можете использовать функцию мульти-модерации.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5740', '1', 'core', 'public_error', 'mod_stupid_beggar', 'Out of all the options in all the drop down, you had to choose one with dashed lines, well done. Go back and behave yourself.', 'Отлично, вы только что умудрились из всех опций в списке выбрать самую бесполезную, состоящую из одних черточек. Вернитесь назад и исправьте ошибку.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5741', '1', 'core', 'public_error', 'forums_no_view_topic', 'You do not have permission to view this topic.', 'Вы не можете просматривать эту тему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5742', '1', 'core', 'public_error', 'posting_bad_auth_key', 'Your secure key, used to verify you are posting the topic, did not match the one submitted.  Please go back, reload the form, and try again.', 'Ваш ключ безопасности, использующийся для проверки того, что именно вы отправляете данные формы не совпал с отправленным. Пожалуйста, вернитесь назад, обновите страницу и попробуйте отправить снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5743', '1', 'core', 'public_error', 'forums_no_permission', 'You do not have permission to view this forum.', 'Вы не можете просматривать этот форум.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5744', '1', 'core', 'public_error', 'forums_not_enough_posts', 'You do not have enough posts to view topics in this forum.', 'Вы еще не набрали необходимого количества сообщений чтобы просматривать список тем данного форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5745', '1', 'core', 'public_error', 'post_too_short', 'You must enter a post.', 'Сообщение слишком короткое.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5746', '1', 'core', 'public_error', 'post_too_long', 'Your post was too long.  Please go back and shorten it a little.', 'Сообщение слишком длинное.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5747', '1', 'core', 'public_error', 'posting_mismatch_topic', 'There was a problem loading the post you are attempting to edit.  Please notify an administrator.', 'При попытке редактирования сообщения возникла проблема. Пожалуйста сообщите об этом администрации форума.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5748', '1', 'core', 'public_error', 'members_tool_supmod', 'You do not have permission to access this moderator tool.', 'Вы не имеете доступа к этой модераторской возможности.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5749', '1', 'core', 'public_error', 'friends_not_enabled', 'The friends feature is not enabled on this community.', 'Возможность добавления пользователей в друзья на данном форуме отключена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5750', '1', 'core', 'public_error', 'posting_not_enough_posts', 'You do not have enough posts to post in this forum.', 'Вы еще не набрали необходимое количество сообщений, чтобы отправлять сообщения в данном форуме.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5751', '1', 'core', 'public_error', 'forums_no_guests', 'You must be logged in to see this forum.', 'Для просмотра этого форума вы должны быть авторизованным пользователем.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5752', '1', 'core', 'public_error', 'pp_friend_timeflood', 'You cannot re-add a friend for five minutes after removing them', 'Вы не можете добавить этого пользователя в друзья, потому что менее пяти минут назад вы отказались от дружбы с ним.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5753', '1', 'core', 'public_error', 'member_bad_birthday', 'You must enter for your birthday at least the month and day of your birthday.', 'Вы должны указать как минимум месяц и день вашего дня рождения.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5754', '1', 'core', 'public_error', 'members_profile_disabled', 'You are not permitted to modify all or some of your profile information.', 'Вы не можете изменять некоторую информацию в своем профиле.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5755', '1', 'core', 'public_error', 'customfields_toobig', 'One of the fields you filled in was too large (\'%s\').  Please shorten it up a little.', 'Одно из заполненных вами полей, содержит слишком большое значение (\'%s\'). ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5756', '1', 'core', 'public_error', 'customfields_invalid', 'One of the fields you filled in requires values in a specific format, but the value you supplied did not meet this format (\'%s\').', 'Значение одного из заполненных вами полей не соответствует ожидаемому формату (\'%s\').', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5757', '1', 'core', 'public_error', 'customfields_empty', 'You did not fill in a value for one of the fields that requires a value (\'%s\').', 'Вы не заполнили обязательное поле (\'%s\').', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5758', '1', 'core', 'public_error', 'cannot_view_memberlist', 'You do not have permission to view the member listing.', 'Вы не можете просматривать список пользователей.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5759', '1', 'core', 'public_error', 'messenger_no_guests', 'You must be logged in to use the private messaging system.', 'Для использования личных сообщений необходимо войти в систему.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5760', '1', 'core', 'public_error', 'messenger_disabled', 'You are not allowed to use the private messaging system.', 'Вы не можете пользоваться личными сообщениями.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5761', '1', 'core', 'public_error', 'messenger_bad_key', 'Your secure key, used to verify your identity, did not match the one submitted.  Please go back, reload the form, and try again.', 'Ключ безопасности, который подтверждает вашу личность, не совпадает с отправленным. Пожалуйста, вернитесь назад, обновите страницу и попробуйте отправить снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5762', '1', 'core', 'public_error', 'messenger_no_msgid', 'We could not determine which message you were attempting to view.', 'Сообщения, которое вы пытаетесь просмотреть, не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5763', '1', 'core', 'public_error', 'messenger_you_be_banned_yo', 'You have been banned from this personal conversation.', 'К сожалению вам закрыли доступ к этой переписке.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5764', '1', 'core', 'public_error', 'onlinelist_disabled', 'You are not permitted to view our online list.', 'Вы не можете просматривать список онлайн пользователей.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5765', '1', 'core', 'public_error', 'dnames_off', 'The administrator does not allow members to change their display names.', 'Возможность изменения имени пользователя отключена администратором.', '32006', '', '0');
