INSERT INTO `ibf_core_sys_lang_words` VALUES ('5773', '1', 'core', 'public_error', 'warn_system_off', 'The warn system is presently disabled.', 'Система предупреждений отключена.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5774', '1', 'core', 'public_error', 'warn_no_user', 'We could not find the requested user.  Please go back and try again.', 'Запрошенный вами пользователь не существует. Попробуйте вернуться назад и повторить попытку.', '32006', '', '0');
