INSERT INTO `ibf_core_sys_lang_words` VALUES ('5778', '1', 'core', 'public_error', 'warn_past_max_low', 'You cannot lower this member\'s warn level any more at this time.', 'На данный момент времени понизить уровень предупреждений у данного пользователя невозможно.', '32006', '', '0');
