INSERT INTO `ibf_core_sys_lang_words` VALUES ('5780', '1', 'core', 'public_error', 'warn_bad_key', 'Your secure key, used to verify your identity, did not match the one submitted.  Please go back, reload the form, and try again.', 'Ключ безопасности, который подтверждает вашу личность, не совпадает с отправленным. Пожалуйста, вернитесь назад, обновите страницу и попробуйте отправить снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5781', '1', 'core', 'public_error', 'warned_already', 'This member has been warned once already within the allotted time allowed.', 'Вы пытаетесь предупредить пользователя, который уже был предупрежден.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5782', '1', 'core', 'public_error', 'cal_no_perm', 'You do not have permission to view this calendar or this calendar does not exist.', 'Вы не можете просматривать этот календарь, либо календарь просто не существует в системе.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5783', '1', 'core', 'public_error', 'calendar_bad_approve', 'You do not have permission to approve this calendar event.', 'У вас нет прав для удаления этого события.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5784', '1', 'core', 'public_error', 'calendar_event_not_found', 'We could not find that calendar event.', 'Запрашиваемое вами событие не найдено.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5785', '1', 'core', 'public_error', 'calendar_no_guests', 'You must be logged in to save events to our calendar.', 'Добавлять события в календарь могут только авторизованные пользователи.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5786', '1', 'core', 'public_error', 'calendar_delete_no_perm', 'You do not have permission to delete this calendar event.', 'Вы не можете удалять события из этого календаря.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5787', '1', 'core', 'public_error', 'calendar_bad_key', 'There was a problem authenticating your request.  Please go back and click the link again.', 'Ошибка безопасности. Пожалуйста вернитесь назад и попробуйте снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5788', '1', 'core', 'public_error', 'calendar_bad_delete', 'We could not find the event you were attempting to delete.', 'Удаляемое вами событие не существует.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5789', '1', 'core', 'public_error', 'calendar_dmy_missing', 'The day, month or year values supplied in the URL do not appear to valid.', 'Значения даты, месяца или года, переданные по ссылке не верны.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5790', '1', 'core', 'public_error', 'calendar_no_post_perm', 'You do not have permission to add events to this calendar.', 'Вы не можете добавлять новые события в этот календарь.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5791', '1', 'core', 'public_error', 'calendar_no_edit_perm', 'You do not have permission to edit this calendar event.', 'Вы не можете редактировать события этого календаря.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5792', '1', 'core', 'public_error', 'calendar_post_too_short', 'You must submit event details in order to save this event.', 'Для добавления события необходимо более подробно описать его.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5793', '1', 'core', 'public_error', 'calendar_invalid_date_view', 'You requested to see events for an invalid date.  Please go back and try again.', 'Вы пытаетесь вывести события для неверной даты. Пожалуйста вернитесь назад и попробуйте снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5794', '1', 'core', 'public_error', 'calendar_no_birthdays', 'We did not find any birthdays on this date.', 'В этот день дней рождения не найдено.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5795', '1', 'core', 'public_error', 'calendar_invalid_date', 'The date you chose for the event is not a valid date.  For example, February 30th and April 31st are invalid dates.  Please verify your input and resubmit the form.', 'Выбранная вами дата неверна. Например не может быть 30 февраля или 31 апреля. Пожалуйста убедитесь в правильности ввода даты и отправьте форму снова.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5796', '1', 'core', 'public_error', 'calendar_range_wrong', 'The end date must occur after the start date, and cannot exceed the December 31, 2037.', 'Дата окончания события должна быть после даты начала.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5797', '1', 'core', 'public_error', 'calendar_title_too_long', 'The calendar title cannot be longer than 64 characters.', 'Название события не может превышать 64 символов.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5798', '1', 'core', 'public_error', 'calendar_no_title', 'You must submit a valid event title in order to save this event.', 'Необходимо указать название события', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5799', '1', 'core', 'public_error', 'calendar_post_too_long', 'Your event details were too large.  Please shorten it up a little.', 'Описание события велико. Попробуйте сократить его и повторить добавление события.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('5800', '1', 'core', 'public_error', 'no_chat_account_number', 'The chat room has not been properly setup by the administrator (the chat room account number has not been supplied).', 'Чат не установлен.', '32006', '', '0');
