INSERT INTO `ibf_core_sys_lang_words` VALUES ('5834', '1', 'core', 'public_error', 'poss_hack_attempt', 'We are treating that action as a possible hack attempt. This action will be logged and the community administrator will be informed via email.', 'Система определила данное действие как попытку взлома. О данном факте было сообщено администратору форума.', '32006', '', '0');
