INSERT INTO `ibf_core_sys_lang_words` VALUES ('6757', '1', 'core', 'public_login', 'twitter_connect_account_desc', 'If have an existing forum account, simply log in as normal then visit <a href=\'%s\' target=\'_blank\'>this page</a> to connect your forum account with your Twitter account', 'Если у вас уже есть учетная запись на форуме, войдите с ее помощью, а затем перейдите на <a href=\'%s\' target=\'_blank\'>эту страницу</a> чтобы связать вашу запись с аккаунтом в Twitter', '32006', '', '0');
