INSERT INTO `ibf_core_sys_lang_words` VALUES ('6911', '1', 'core', 'public_modcp', 'ip_warn_text', '<b>Please Note</b>: You may enter a wildcard \'*\' (without quotes) as the last part of the IP address.<br />For example, 127.*.*.* will match all IP address that start with 127.<br />127.1.0.* will match all IP addresses that start with 127.1.0.<br />An error will occur if you attempt to use a wildcard in the middle of the IP address. For example, 127.*.0.1 will return an error.', '<b>Внимание</b>: Вы можете использовать символ \'*\' (без кавычек) в любой части IP-адреса.<br />Например, 127.*.*.* будет проверять по всем IP, которые начинаются с 127.<br /> 127.1.0.* будет проверять по всем начинающимся с 127.1.0.<br />Если вы используете * в середине IP-адреса, то система не сможет провести поиск. Например, 127.*.0.1 вернет ошибку.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('6912', '1', 'core', 'public_modcp', 'ipm_group', 'Group', 'Группа', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('6913', '1', 'core', 'public_modcp', 'ip_desc_text', '<strong>Resolve IP Address</strong>: This option will allow you to look up an IP address for more information (note, you must enter all 4 parts of the IP address to use this tool)<br /><strong>Find Posts with this IP</strong>: This option will run a search for all posts associated with this IP address (limited to 500 results)<br /><strong>Find members who registered with this IP</strong>: This tool will run a seach for all members who registered with the entered IP address', '<strong>Информация</strong>: Эта опция позволяет получить информацию IP-адресу (нужно вводить IP-адрес полностью)<br /><strong>Найти сообщения</strong>: Эта опция позволяет найти все сообщения, написанные с введенного IP-адреса (результат ограничен 500ами)<br /><strong>Найти пользователей</strong>: Эта опция позволяет показать всех пользователей, которые регистрировались с этим IP-адресом', '32006', '', '0');
