INSERT INTO `ibf_core_sys_lang_words` VALUES ('7131', '1', 'core', 'public_register', 'lp_text', 'Enter your username or email address in the field below. The username or email address is case <b>in</b>sensitive. Once you have submitted the form, you will receive an email asking for validation of this request to ensure that no malicious use has occurred. This email will also contain a link that you must click for further instruction.', 'Введите ваш логин и e-mail адрес в соответствующие поля формы. Данные <strong>не</strong> чувствительны к регистру букв. <br />После отправки формы, вы получите письмо с просьбой о подтверждении запроса, а так же ссылкой на дальнейшие инструкции.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7132', '1', 'core', 'public_register', 'reg_error_no_name_spec', '  Be aware that some special characters use more than 1 character.', ' Помните, что некоторые специальные символы используют более чем 1 символ.', '32006', '', '0');
