INSERT INTO `ibf_core_sys_lang_words` VALUES ('7151', '1', 'core', 'public_register', 'coppa_bounce', 'You must either cancel your registration or have your parent complete the COPPA registration form and send it to us', 'Вы должны отменить регистрацию или попросить одного из родителей заполнить форму COPPA и отправить ее нам.', '32006', '', '0');
