INSERT INTO `ibf_core_sys_lang_words` VALUES ('7174', '1', 'core', 'public_register', 'rv_done', '<strong>Your revalidation request was successful</strong><br />A revalidation email has been sent to the registered address for that member. Please check your email within the next few minutes - including any \'junk mail\' or \'spam\' folders you may have.', '<strong>Повторное письмо с активацией отправлено</strong><br />Письмо было отправлено на email адрес, указанный при регистрации. Через несколько минут проверьте ваш email. Возможно наши письма распознаются вашим почтовым клиентом как спам, если снова не найдете письма проверьте это.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7175', '1', 'core', 'public_register', 'rv_process', 'Revalidation Process', 'Повторная активация ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7176', '1', 'core', 'public_register', 'rv_ins_name', 'Please enter your sign in name below to search for any pending validation requests. If any are found, the email will be resent to the email address you registered with.', 'Введите логин, указанный при регистрации, для поиска незавершенной активации. Если такая активация будет найдена, вам повторно будет выслано письмо с деталями активации вашей учетной записи.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7177', '1', 'core', 'public_register', 'rv_ins_email', 'Please enter your sign in email below to search for any pending validation requests. If any are found, the email will be resent to the email address you registered with.', 'Введите email, указанный при регистрации, для поиска незавершенной активации. Если такая активация будет найдена, вам повторно будет выслано письмо с деталями активации вашей учетной записи.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7178', '1', 'core', 'public_register', 'rv_ins_both', 'Please enter your sign in name or email below to search for any pending validation requests. If any are found, the email will be resent to the email address you registered with.', 'Введите логин или email, указанный при регистрации, для поиска незавершенной активации. Если такая активация будет найдена, вам повторно будет выслано письмо с деталями активации вашей учетной записи.', '32006', '', '0');
