INSERT INTO `ibf_core_sys_lang_words` VALUES ('7199', '1', 'core', 'public_register', 'coppa_info', 'Birthday', 'Информация COPPA', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7200', '1', 'core', 'public_register', 'confirm_over_thirteen', 'Please supply your birthday to continue', 'В соответствии с законом COPPA о защите несовершеннолетних в Интернете, мы должны проверить, что вы старше 13 лет. Если вы младше, вам нужно <a href=\'<#FORM_LINK#>\'>получить разрешение</a> от ваших родителей, чтобы пользоваться этим форумом.', '32006', '', '0');
