INSERT INTO `ibf_core_sys_lang_words` VALUES ('7202', '1', 'core', 'public_register', 'coppa_link', 'Please select your birthday', 'Укажите дату вашего рождения', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7203', '1', 'core', 'public_register', 'coppa_form', 'COPPA Form', 'Форма COPPA', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7204', '1', 'core', 'public_register', 'coppa_form_text', 'A parent or guardian must complete and mail or fax a signed <#FORM_LINK#> to the administrator of the community before a child under the age of 13 can complete the registration process.<br />For further information, please contact the forum administrator', 'Один из родителей или опекун должен заполнить и отправить по почте или факсом подписанный <#FORM_LINK#> администратору форума перед тем, как ребенок не достигший 13 лет сможет зарегистрироваться на форуме.<br />За дополнительной информацией, пожалуйста, <a href=\"javascript:contact_admin();\">Обратитесь к администратору форума</a> ', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7205', '1', 'core', 'public_register', 'coppa_link_form', 'permission form', 'форма разрешения', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7206', '1', 'core', 'public_register', 'coppa_email_subject', 'COPPA Registration Information', 'COPPA Информация регистрации', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7207', '1', 'core', 'public_register', 'cp2_text', ' All users under the age of 13 must seek permission from a parent or guardian before you may participate on these forums.<br /><br />Once the parental consent form has been received, an account will be created for you with the information supplied, and an email will be sent to the provided email address to notify you that your account is ready for use.  You can then change your account details from your \'My Controls\' area upon logging in with your new account.', 'Все пользователи возрастом до 13 лет, обязаны иметь разрешение родителей, для дальнейшего участия и пользования этими форумами.<br /><br />Как только администрация форума получит разрешение от ваших родителей, учетная запись для вас будет создана.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7208', '1', 'core', 'public_register', 'cp2_title', 'Our COPPA registration policy', 'Наше регистрационное соглашение COPPA', '32006', '', '0');
