INSERT INTO `ibf_core_sys_lang_words` VALUES ('7210', '1', 'core', 'public_register', 'cpf_perm_parent', 'Instructions for a parent or guardian<br /><br />Please print this form out, complete it and fax it to the number specified (if present) or mail to the mailing address below.', 'Инструкции для родителей или опекунов<br /><br />Пожалуйста, распечатайте эту форму, заполните ее и перешлите по факсу на наш номер. Если факса не имеется, вы можете переслать эту форму по нижеуказанному адресу.', '32006', '', '0');
