INSERT INTO `ibf_core_sys_lang_words` VALUES ('7220', '1', 'core', 'public_register', 'cpf_sign', 'Please sign the form below and send to us.<br /><br />I understand that I may consent to the collection of necessary information about my child without permitting the site to disclose such information to third parties.  I also understand that the site will not collect more information about my child than is reasonably necessary to participate on the site.<br /><br />\n									I confirm that the information that the child has supplied is correct. I understand that the profile information may be changed by entering a password and I understand that I may ask for this registration profile to be removed.  I understand that I can contact the owner of this site at any time to determine what information about my child has been collected, to confirm how that information is used, and to request that the site no longer collect information about my child.', 'Просим вас подписать нижеследующую форму и переслать ее нам.<br><br>Я подтверждаю, что информация, предоставленная ребенком верна. Я соглашаюсь, что информация профиля может быть изменена только после ввода пароля. И я принимаю то что, я могу затребовать удаления этого профиля в любой момент.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7221', '1', 'core', 'public_register', 'cpf_address', '<b>Mailing Address:</b>', '<b>Адрес для писем:</b>', '32006', '', '0');
