INSERT INTO `ibf_core_sys_lang_words` VALUES ('7226', '1', 'core', 'public_register', 'email_validate_text', 'You will be sent an email to the email address you give after registering. Please read the email carefully, you will need to validate your account by clicking on a link in the email.', 'Вам будет выслан e-mail на адрес указанный при регистрации. Пожалуйста внимательно ознакомьтесь с ним, вам необходимо будет проследовать по ссылке в письме, чтобы активировать вашу учетную запись.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7227', '1', 'core', 'public_register', 'lp_email_or', '<em>-OR-</em> Email Address', 'ИЛИ ваш e-mail', '32006', '', '0');
