INSERT INTO `ibf_core_sys_lang_words` VALUES ('7230', '1', 'core', 'public_register', 'agree_submit', 'I have read, understood and agree to these rules and conditions', 'Я ознакомился с правилами и условиями, и принимаю их.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7231', '1', 'core', 'public_register', 'std_text', 'Please ensure that you complete all the fields fully, taking particular care over the password fields.', 'Пожалуйста убедитесь, что все поля формы заполнены. Особенно тщательно проверьте поля паролей.', '32006', '', '0');
