INSERT INTO `ibf_core_sys_lang_words` VALUES ('7551', '1', 'core', 'public_usercp', 'auto_but_no_email', 'You are automatically following all topics you reply to with no notification frequency selected.  This will cause the topics to show in your followed content area, but you will not receive notifications for these topics.', 'Вы автоматически следите за всеми темами, в которых вы отвечаете, без какой-либо подписки на уведомления по ним. Это приведет к то, что эти темы будут показывать в разделе с контентом, за которым вы следите, но вы не будете получать уведомления по ним.', '32006', '', '0');
