INSERT INTO `ibf_core_sys_lang_words` VALUES ('7582', '1', 'core', 'public_usercp', 'ucp_customize_msg', 'This page allows you to customize your profile background. These customizations will be shown to all members visiting your profile page.', 'На данной странице вы можете персонализировать свой профиль, а именно изменить фон. Изменения будут видны всем пользователям, просматривающим ваш профиль.', '32006', '', '0');
