INSERT INTO `ibf_core_sys_lang_words` VALUES ('7868', '1', 'core', 'public_usercp', 'dst_error', 'An error occurred when trying to automatically change your DST settings. If the error continues, please switch off auto DST correction.', 'Произошла ошибка при попытке автоматически изменить ваши настройки перехода на летнее время. Если ошибка продолжается, пожалуйста, отключите автокоррекцию перехода на летнее время.', '32006', '', '0');
INSERT INTO `ibf_core_sys_lang_words` VALUES ('7869', '1', 'core', 'public_usercp', 'conv_email_warning', 'Your email address has been changed because it was in use by another account. This means that all email will NOT go to your correct email address - this could include lost password notifications, etc.<br />PLEASE change your email address immediately.', 'Ваш e-mail адрес изменен в связи с тем, что данный e-mail используется на другой учетной записи. Это означает, что вы не будете получать никаких писем с форума, такие как уведомление о восстановлении забытого пароля и т.д.<br />Немедленно измените свой e-mail адрес.', '32006', '', '0');
