INSERT INTO `ibf_core_sys_lang_words` VALUES ('7921', '1', 'core', 'public_usercp', 'ce_auth', '<strong>PLEASE NOTE:</strong> You will have to re-activate your account after changing your email address.<br />An email will be sent to the email address you specify below, outlining what you need to do.<br />Proceeding with this action will sign you out. It is strongly recommended that you reset your password before changing your email address if you are unable to remember your password.', '<br /><br />ПРИМЕЧАНИЕ: После изменения e-mail адреса вы должны будете переактивировать вашу учетную запись.<br />На ваш e-mail адрес будет отправлено письмо с подробными инструкциями о дальнейших действиях.<br /><br />Вы должны будете переавторизоваться. Настоятельно рекомендуем вам, перед изменением e-mail адреса, воспользоваться функцией восстановления пароля, если вы его не помните.', '32006', '', '0');
