INSERT INTO `ibf_inline_notifications` VALUES ('4', '50', '1338126508', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/168/\'>Давайте знакомиться</a>', 'Здравствуйте!\n\nПользователю L2MarkuS понравилось вашe сообщение на форуме!\n\nПриветствую. Тему открывал я. Но как говорилось выше она канула в лету.Вот собственно я.Если в 2 словах о себе скромен и добр.\nhttp://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686', '15', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686', null, null, '0', null);
INSERT INTO `ibf_inline_notifications` VALUES ('5', '6', '1338126512', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__717\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/168/\'>Давайте знакомиться</a>', 'Здравствуйте!\n\nПользователю L2MarkuS понравилось вашe сообщение на форуме!\n\nну раз все начали выкладывать тогда и я выложу))\nhttp://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__717', '15', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__717', null, null, '0', null);
INSERT INTO `ibf_inline_notifications` VALUES ('7', '15', '1338137884', '2', '<a href=\'http://onlineage2.com/forum/index.php?/user/76/\'>neverm1nd</a> начал новую <a href=\'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=73#msg73\'>беседу</a> с вами', 'L2MarkuS, neverm1nd отправил вам сообщение с заголовком \"онлайн\". \nneverm1nd сказал: ======================================================================\nдобрый вечер.хотел бы поиграть на вашем серве,но прежде хотелось бы узнать какой у вас онлайн(нигде не нашел).так же можно дату открытия сервака?.Спасибо\nВы можете просмотреть беседу с ним, пройдя по указанной ниже ссылке:\nhttp://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=73#msg73\n', '76', 'new_private_message', 'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=73#msg73', 'members', 'pm', '73', 'db1e5c24e8d226bc1e88fa0b97fca3be');
INSERT INTO `ibf_inline_notifications` VALUES ('8', '76', '1338138870', '2', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> написал новое сообщение в <a href=\'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=73&msgID=__firstUnread__\'>личной беседе</a>', 'neverm1nd, L2MarkuS ответил в личную беседу \"онлайн\".\nL2MarkuS сказал:\n------------ QUOTE ----------\n\nдобрый вечер.хотел бы поиграть на вашем серве,но прежде хотелось бы узнать какой у вас онлайн(нигде не нашел).так же можно дату открытия сервака?.Спасибо\n-----------------------------\n\n\n\nДобрый вечер. Сервер открыт 1 мая. Можно спокойно начинать играть. Онлайн хромает, но есть 10 - 20 челвое.\nВы можете просмотреть полный диалог беседы по указанной ниже ссылке:\nhttp://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=73&msgID=__firstUnread__\n', '15', 'reply_private_message', 'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=73&msgID=__firstUnread__', 'members', 'pm', '73', 'db1e5c24e8d226bc1e88fa0b97fca3be');
INSERT INTO `ibf_inline_notifications` VALUES ('9', '50', '1338141850', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/43/\'>L2DontStrong</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/168/\'>Давайте знакомиться</a>', 'Здравствуйте!\n\nПользователю L2DontStrong понравилось вашe сообщение на форуме!\n\nПриветствую. Тему открывал я. Но как говорилось выше она канула в лету.Вот собственно я.Если в 2 словах о себе скромен и добр.\nhttp://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686', '0', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__686', null, null, '0', null);
INSERT INTO `ibf_inline_notifications` VALUES ('12', '6', '1338311563', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__790\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/213/\'>Бонусы за голосование.</a>', 'Здравствуйте!\n\nПользователю L2MarkuS понравилось вашe сообщение на форуме!\n\nрецы на А гр пухи и куски,т.к. куски падают только с РБ и при прохождении кв,и рецы на пухи(цены примерное около 30-45 итемов)1.5 мес игры.думаю это всем понравится)))и поинты(хп и маны)\nhttp://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__790', '15', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__790', null, null, '0', null);
INSERT INTO `ibf_inline_notifications` VALUES ('13', '62', '1338314397', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__792\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/213/\'>Бонусы за голосование.</a>', 'Здравствуйте!\n\nПользователю L2MarkuS понравилось вашe сообщение на форуме!\n\nрецы и куски какой-то тоскливый вариант. Слишком уж влияет на процесс.Можно давать нечто типо билетиков на лотерею, а в ней с небольшим шансом немного адены. Прям совсем мелочь, чтобы просто интерес был. Несколько тысяч ни на что не повлияют, а приятное то не уйдет никуда. Либо давать за голоса...\nhttp://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__792', '15', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/213/page__view__findpost__p__792', null, null, '0', null);
