INSERT INTO `ibf_inline_notifications` VALUES ('15', '15', '1338364299', '2', '<a href=\'http://onlineage2.com/forum/index.php?/user/62/\'>oldhippy</a> начал новую <a href=\'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=76#msg78\'>беседу</a> с вами', 'L2MarkuS, oldhippy отправил вам сообщение с заголовком \"Привет\". \noldhippy сказал: ======================================================================\nГлупейший вопрос - как писать в чат? Хоть убей, не доходит)\nВы можете просмотреть беседу с ним, пройдя по указанной ниже ссылке:\nhttp://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=76#msg78\n', '62', 'new_private_message', 'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=showConversation&topicID=76#msg78', 'members', 'pm', '76', '3894a88c8040c0c123fe0394cb0e83c7');
INSERT INTO `ibf_inline_notifications` VALUES ('16', '62', '1338364842', '2', '<a href=\'http://onlineage2.com/forum/index.php?/user/15/\'>L2MarkuS</a> написал новое сообщение в <a href=\'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=76&msgID=__firstUnread__\'>личной беседе</a>', 'oldhippy, L2MarkuS ответил в личную беседу \"Привет\".\nL2MarkuS сказал:\n------------ QUOTE ----------\n\nГлупейший вопрос - как писать в чат? Хоть убей, не доходит)\n-----------------------------\n\n\n\n\nДобрый день. Писать очень просто. Вверху (чуть ниже верха, есть строчка, куда вводить текст с сообщением. Как ввели сообщение, нажимаете на кнопочку \"Сообщение\" и сообщение отправляется в чат.)\n\nВот я сделал для вас скриншот. Передите по сылке: http://s017.radikal.ru/i400/1205/83/15d672450289.jpg\nВы можете просмотреть полный диалог беседы по указанной ниже ссылке:\nhttp://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=76&msgID=__firstUnread__\n', '15', 'reply_private_message', 'http://onlineage2.com/forum/index.php?app=members&module=messaging&section=view&do=findMessage&topicID=76&msgID=__firstUnread__', 'members', 'pm', '76', '3894a88c8040c0c123fe0394cb0e83c7');
