INSERT INTO `ibf_inline_notifications` VALUES ('21', '62', '1338377493', '1', '<a href=\'http://onlineage2.com/forum/index.php?/user/86/\'>Мистер Финч</a> понравилось <a href=\'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__823\'>сообщение, сделанное вами,</a> в <a href=\'http://onlineage2.com/forum/index.php?/topic/168/\'>Давайте знакомиться</a>', 'Здравствуйте!\n\nПользователю Мистер Финч понравилось вашe сообщение на форуме!\n\nНу почему же ветераны. Я в детстве играл в с3, да, собственно, начинал с самого прелюда. Сейчас почти 20 лет.Зовут Алексей. живу в Магнитогорске, что в Челябинской области.\nhttp://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__823', '86', 'new_likes', 'http://onlineage2.com/forum/index.php?/topic/168/page__view__findpost__p__823', null, null, '0', null);
