INSERT INTO `ibf_message_posts` VALUES ('66', '66', '1337794219', '<!--quoteo--><div class=\'quotetop\'>Цитата</div><div class=\'quotemain\'><!--quotec--><!--quoteo--><div class=\'quotetop\'>Цитата</div><div class=\'quotemain\'><!--quotec-->У меня тут такая просьба)<br />Можно ли моего перса переименовать?)<br />Или поменять местами имена двум моим персам?)<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />Напишите оригинальный ник, и напишите ник на который менять.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />Ник персонажа - 4ydoTpaBka<br />Поменять на - OverSoul<br />Просто другово персонажа возьму) а овер будет как твинк.', 'bc3b051c27abea401fe91bfd4c65f283', '23', '213.79.8.90', '1');
