INSERT INTO `ibf_message_posts` VALUES ('71', '71', '1337826905', '<!--quoteo--><div class=\'quotetop\'>Цитата</div><div class=\'quotemain\'><!--quotec-->У меня есть маленькая просьба)<br />Можно поменять имя моему персу?<br />Или поменять местами двум моим персанажам? А то 7 дней ждать удаления персонажа не хочется)<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />Отпишите ники и ихни, и 1 первый и 1 последний символы логина, и адрес электронной почты (не обезательно).', 'b29ca262ac5a0137e289782490ac22e4', '0', '84.94.167.199', '1');
INSERT INTO `ibf_message_posts` VALUES ('73', '73', '1338137884', 'добрый вечер.хотел бы поиграть на вашем серве,но прежде хотелось бы узнать какой у вас онлайн(нигде не нашел).так же можно дату открытия сервака?.Спасибо', '52fb8f36f84fcd2012be832229c4f3d3', '76', '188.255.13.52', '1');
INSERT INTO `ibf_message_posts` VALUES ('74', '73', '1338138871', '[quote name=&#39;neverm1nd&#39; timestamp=&#39;1338137884&#39;]<br />\nдобрый вечер.хотел бы поиграть на вашем серве,но прежде хотелось бы узнать какой у вас онлайн(нигде не нашел).так же можно дату открытия сервака?.Спасибо[/quote]<br />\n<br />\nДобрый вечер. Сервер открыт 1 мая. Можно спокойно начинать играть. Онлайн хромает, но есть 10 - 20 челвое.', '11bb9868b9322e65b6da6558a5de7e42', '15', '94.179.114.152', '0');
