INSERT INTO `ibf_posts` VALUES ('104', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1332862690', '0', '<!--quoteo(post=103:date=27.3.2012, 15&#58;34:name=BenQ)--><div class=\'quotetop\'>Цитата(BenQ &#064; 27.3.2012, 15&#58;34) <a href=\"index.php?act=findpost&amp;pid=103\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->скачал патч перестает заходить можно ли ? как то поправить<br />или может я чет не то делаю<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><br />Скачайте автоапдейт, и обновите им ваш клиент. потом зайдите в папку system и запустите L2Play.exe', '0', '35', null, '0', null, 'a606651d7add66987bbe8b4f702b4738', '0', '', '0', '0', '0', null, null);
