INSERT INTO `ibf_posts` VALUES ('171', '0', '1333133568', '16', 'NikaLondon', '1', '1', '195.189.105.138', '1333133512', '0', 'Не могу выбить книгу на лошадку (а это междупрочим самый основной скил у меня).Мало того что сначала очень долго искала моба,так когда нашла,дропа нет ни книга ни денег вообще ничего не падает-_- <br />о да чуть не забыла дописать моб Tanor Silenos', '0', '50', null, '1', 'NikaLondon', '1256d4fc260d212f0819aea2ce9db7e6', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('172', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1333139491', '0', '<!--quoteo(post=171:date=30.3.2012, 18&#58;51:name=NikaLondon)--><div class=\'quotetop\'>Цитата(NikaLondon &#064; 30.3.2012, 18&#58;51) <a href=\"index.php?act=findpost&amp;pid=171\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Не могу выбить книгу на лошадку (а это междупрочим самый основной скил у меня).Мало того что сначала очень долго искала моба,так когда нашла,дропа нет ни книга ни денег вообще ничего не падает-_- <br />о да чуть не забыла дописать моб Tanor Silenos<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><br />Укажите называние моба.', '0', '50', null, '0', null, '1bde73b44ff609518bc7fd8aa3e904c3', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('185', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1333192052', '0', '<!--quoteo(post=175:date=31.3.2012, 0&#58;39:name=Spoil)--><div class=\'quotetop\'>Цитата(Spoil &#064; 31.3.2012, 0&#58;39) <a href=\"index.php?act=findpost&amp;pid=175\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->у гнома пропадают после релога рецепты зачитанные.<br />не работает торг с др чарами.<br />краски неправильно работают а именно(поставил краски +3 вит -4 мен, +3 инт -4 мен, +1вит -2 мен итого пишет  +1 инт  +4 вит  -8 мен)<br />не одеваются заточенные вещи<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><br />Исправляю.', '0', '53', null, '0', null, '4e3c607659cfc5556eb9efb4d594a0cf', '0', '', '0', '0', '0', null, null);
