INSERT INTO `ibf_posts` VALUES ('251', '0', null, '0', 'Одуванчик', '1', '1', '178.176.136.173', '1333377875', '0', '<!--quoteo(post=250:date=2.4.2012, 18&#58;43:name=4ydoTpaBka)--><div class=\'quotetop\'>Цитата(4ydoTpaBka &#064; 2.4.2012, 18&#58;43) <a href=\"index.php?act=findpost&amp;pid=250\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Хмм, у меня с вашего апдейтера все равно не пускает =&#092;<br />Пришлось в инете скачать файл dll что бы пускало без песочницы<!--QuoteEnd--></div><!--QuoteEEnd--><br />А это уже косяк клиента.', '0', '57', null, '0', null, '31212b0c61c5b3dacacc23e7d66e075b', '0', '', '0', '0', '0', null, null);
