INSERT INTO `ibf_posts` VALUES ('254', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1333382241', '0', '<!--quoteo(post=252:date=2.4.2012, 15&#58;40:name=NikaLondon)--><div class=\'quotetop\'>Цитата(NikaLondon &#064; 2.4.2012, 15&#58;40) <a href=\"index.php?act=findpost&amp;pid=252\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Вот хотела сходить в каты потестить а перс не ныряет под воду(( Только плавает по воде и всё.И это не только в катах везде так.Персы плавают над водой и полоса дыхания тоже появляеться.А перс не ныряет<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />Это наверно только в катакомбах. Окей сегодня исправлю.', '0', '64', null, '0', null, '6472e4bfd8f48e34842abf4b5feebca8', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('255', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1333382287', '0', '<!--quoteo(post=250:date=2.4.2012, 14&#58;43:name=4ydoTpaBka)--><div class=\'quotetop\'>Цитата(4ydoTpaBka &#064; 2.4.2012, 14&#58;43) <a href=\"index.php?act=findpost&amp;pid=250\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Хмм, у меня с вашего апдейтера все равно не пускает =&#092;<br />Пришлось в инете скачать файл dll что бы пускало без песочницы<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />А как dll называется?', '0', '57', null, '0', null, '6ff00e3b57ddb96b0034fa38a9b4b8d6', '0', '', '0', '0', '0', null, null);
