INSERT INTO `ibf_posts` VALUES ('281', '0', null, '6', 'Spoil', '1', '1', '31.181.49.240', '1333459825', '0', '<!--quoteo(post=280:date=3.4.2012, 12&#58;22:name=L2MarkuS)--><div class=\'quotetop\'>Цитата(L2MarkuS &#064; 3.4.2012, 12&#58;22) <a href=\"index.php?act=findpost&amp;pid=280\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Вот именно, была ли....С таким темпом можно сказать что Дино, Веспер и.т.д был на С3.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />в С3 сосок не дают,с каких хроник появился баф для новичков?с С4?как появился баф у хелперов,так и появились соски', '0', '67', null, '0', null, '9caa6dd2c0af4924c977fc30f08837a7', '0', '', '0', '0', '0', null, null);
