INSERT INTO `ibf_posts` VALUES ('287', '0', '1333468664', '0', 'Archive', '1', '1', '79.182.23.99', '1333468340', '0', '<!--quoteo(post=284:date=3.4.2012, 15&#58;01:name=BenQ)--><div class=\'quotetop\'>Цитата(BenQ &#064; 3.4.2012, 15&#58;01) <a href=\"index.php?act=findpost&amp;pid=284\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Dion weapon &amp; armor <br />Застревает в текстуру рестарт не помогает<br />между прилавок и ковриком =)<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />проверю и исправлю сегодня', '0', '61', null, '0', 'L2MarkuS', '8d0ec560b1121020e92b0b067a38a504', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('288', '0', '1333468651', '0', 'Archive', '1', '1', '79.182.23.99', '1333468433', '0', '<!--quoteo(post=270:date=3.4.2012, 5&#58;53:name=DARKFORCE)--><div class=\'quotetop\'>Цитата(DARKFORCE &#064; 3.4.2012, 5&#58;53) <a href=\"index.php?act=findpost&amp;pid=270\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Кубик у ШК Phantom Cubic агрится на монстров нормально но не дает эффекта(понижение скорости атаки,силы атаки и физической защиты цели).Vampiric cubic не агрится на монстров совсем.Пассивный скилл Shields Defense не увеличивает шанс защиты щитом, что с ним что без.Скилл Hex не дает эффекта понижения защиты.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />скиллы исправлю, а кубики маркуса работа', '0', '61', null, '0', 'L2MarkuS', '9b65f9223dd50c746783bfed4279dd6c', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('289', '0', null, '0', 'Archive', '1', '1', '79.182.23.99', '1333468563', '0', '<!--quoteo(post=239:date=1.4.2012, 17&#58;34:name=DARKFORCE)--><div class=\'quotetop\'>Цитата(DARKFORCE &#064; 1.4.2012, 17&#58;34) <a href=\"index.php?act=findpost&amp;pid=239\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Прошу людей составить список из тех профессий которые были проверены.Все ли работает или работает как надо.<br />И поставте кота обратно,врятли тут ктото будет на обт сам сдавать 2 профы да и 1 тоже.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />первые профы все рабочие и прохождимые я проверил (вторые еще не проверял)', '0', '62', null, '0', null, 'bbc2cfb1011d30f65100beca15209c63', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('290', '0', null, '15', 'L2MarkuS', '1', '1', '192.168.1.3', '1333468910', '0', '<!--quoteo(post=284:date=3.4.2012, 15&#58;01:name=BenQ)--><div class=\'quotetop\'>Цитата(BenQ &#064; 3.4.2012, 15&#58;01) <a href=\"index.php?act=findpost&amp;pid=284\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Dion weapon &amp; armor <br />Застревает в текстуру рестарт не помогает<br />между прилавок и ковриком =)<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />В личном кабинете телепортируйте себя.', '0', '61', null, '0', null, '10dfd15d4e3b24519f3edb5b33060143', '0', '', '0', '0', '0', null, null);
