INSERT INTO `ibf_posts` VALUES ('294', '0', '1333541175', '0', 'Archive', '1', '1', '84.94.167.199', '1333493153', '0', '<!--quoteo(post=270:date=3.4.2012, 5&#58;53:name=DARKFORCE)--><div class=\'quotetop\'>Цитата(DARKFORCE &#064; 3.4.2012, 5&#58;53) <a href=\"index.php?act=findpost&amp;pid=270\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Кубик у ШК Phantom Cubic агрится на монстров нормально но не дает эффекта(понижение скорости атаки,силы атаки и физической защиты цели).Vampiric cubic не агрится на монстров совсем.Пассивный скилл Shields Defense не увеличивает шанс защиты щитом, что с ним что без.Скилл Hex не дает эффекта понижения защиты.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br />Кубики маркус исправил,<br /><br /><!--quoteo(post=270:date=3.4.2012, 5&#58;53:name=DARKFORCE)--><div class=\'quotetop\'>Цитата(DARKFORCE &#064; 3.4.2012, 5&#58;53) <a href=\"index.php?act=findpost&amp;pid=270\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Скилл Hex не дает эффекта понижения защиты.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><div align=\"center\"><br />исправил<br /><br /><img src=\"http://img4host.net/upload/041402514f7c386b09fab.png\" border=\"0\" class=\"linked-image\" /><br /><br /><img src=\"http://img4host.net/upload/041404224f7c38c668f2d.png\" border=\"0\" class=\"linked-image\" /></div>', '0', '61', null, '0', 'Archive', '2d07e1b0352ea72c2c099249e93a317b', '0', '', '0', '0', '0', null, null);
