INSERT INTO `ibf_posts` VALUES ('516', '0', null, '15', 'L2MarkuS', '1', '1', '127.0.0.1', '1337352866', '0', '<!--quoteo(post=515:date=18.5.2012, 14&#58;52:name=Евгений)--><div class=\'quotetop\'>Цитата(Евгений &#064; 18.5.2012, 14&#58;52) <a href=\"index.php?act=findpost&amp;pid=515\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->1. Не могу найти Felim Lizardman Warriors. По l2db: <a href=\"http://l2db.ru/npc/location/14/c3\" target=\"_blank\">http://l2db.ru/npc/location/14/c3</a> или я не вижу или там вообще ни каких ящериц нету.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><b><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->По квестам профессий, просьба использовать l2dc.ru. Я устаю повторять это. l2db - от с4 и выше. <!--colorc--></span><!--/colorc--><br /><br /><br /><a href=\"http://www.l2dc.ru/l2races/?t=racetree\" target=\"_blank\">http://www.l2dc.ru/l2races/?t=racetree</a> <!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->вот тут выбирайте вашу профессию и проходите.<!--colorc--></span><!--/colorc--> </b>', '0', '112', null, '0', null, '07d191329d976d0c9844e810c0c52167', '0', '', '0', '0', '0', null, null);
