INSERT INTO `ibf_posts` VALUES ('646', '0', null, '15', 'L2MarkuS', '1', '1', '178.94.34.56', '1337760318', '0', '<b><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->Название:<!--colorc--></span><!--/colorc--> <!--coloro:#A0522D--><span style=\"color:#A0522D\"><!--/coloro-->Path to a Roque<!--colorc--></span><!--/colorc--><br /><!--coloro:#8B0000--><span style=\"color:#8B0000\"><!--/coloro-->Требуемый уровень: 19<br />затраты на телепортацию <br />Map: World <br />10 SoE (на всякий случай) <br />запас Soulshot<!--colorc--></span><!--/colorc--><br /><br /><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->Телепортируемся в Gludin.<br /><!--colorc--></span><!--/colorc--><br /><br /><!--coloro:#0000FF--><span style=\"color:#0000FF\"><!--/coloro-->1 Ищем у западных ворот Captain Bezique, разговариваем с ним, получаем Bezique&#39;s Letter.<br /><br />2 Ищем в юго-западной части центральной площади Neti, разговариваем с ней, получаем Neti&#39;s Dagger и Neti&#39;s Bow. Телепортируемся в Abandoned Camp. Бежим в Ruins of Agony.<br /><br />3 Охотимся с помощью Neti&#39;s Dagger и Neti&#39;s Bow на Ruin Spartoi, Raging Spartoi, Tracker Skeleton и Tracker Skeleton Leader, пока не соберем 10 Spartoi&#39;s Bone Используем SoE. Телепортируемся в Gludin.<br /><br />4 Ищем Neti, разговариваем с ней, получаем Horseshoe Of Light.<br /><br />5 Ищем у западных ворот Captain Bezique, разговариваем с ним, получаем Wanted Bill. Телепортируемся в Abandoned Camp.<br /><br />6 Охотимся с помощью Neti&#39;s Dagger и Neti&#39;s Bow на Cat&#39;s Eye Bandit, пока не соберем Stolen Necklace, Stolen Tomes, Stolen Jewelry, Stolen Ring. Используем SoE.<br /><br />7 Ищем у западных ворот Captain Bezique, разговариваем с ним, получаем Bezique&#39;s Recommendation.<br /><br />8 Ищем в гильдии бойцов Grand Master Ramos, разговариваем с ним и становимся Rogue.<br />	<br />Задание выполнено.<!--colorc--></span><!--/colorc--><br /><br /><!--coloro:#008000--><span style=\"color:#008000\"><!--/coloro-->Квест пройдет успешно. <!--colorc--></span><!--/colorc--><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro-->&copy; L2MarkuS<!--colorc--></span><!--/colorc--><br /><br /></b>', '0', '143', null, '1', null, '66a97350e455cf4c379973c902f0f7e7', '0', '', '0', '0', '0', null, null);
