INSERT INTO `ibf_posts` VALUES ('552', '0', null, '15', 'L2MarkuS', '1', '1', '127.0.0.1', '1337502107', '0', '<!--quoteo(post=544:date=19.5.2012, 10&#58;33:name=4ydoTpaBka)--><div class=\'quotetop\'>Цитата(4ydoTpaBka &#064; 19.5.2012, 10&#58;33) <a href=\"index.php?act=findpost&amp;pid=544\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Не знаю, в ту ли тему пишу.<br />В Pilgrims Necroplis кривая геодата.<br />В воду трудно попасть.<br />Около первого зикурата приходится делать рестарт, т.к. не реагирует разговор с нпц.<br />Как вошел в сам некрополис, намертво замираю, и пишет что я то вошел в воду, то вышел из неё.<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro--><b>Сегодня будет исправлено.</b><!--colorc--></span><!--/colorc-->', '0', '111', null, '0', null, 'aa6750c7250a340b7ac6da2f9a05e6fc', '0', '', '0', '0', '0', null, null);
