INSERT INTO `ibf_posts` VALUES ('558', '0', '1337571256', '37', 'Евгений', '1', '1', '176.215.240.113', '1337504457', '0', 'Long Live the Paagrio Lord - пройдено<br />Into the City of Humans - не берется у Centurion Petukai (связанный TO THE IMMORTAL PLATEAU невыполним)<br />Proof of Valor - пройден<br />Wrath of Ancestors - пройден.<br /><br />Позже продолжу отписываться.', '0', '122', null, '1', 'Евгений', '3d52172006dc0c587ac560fb15813eb8', '0', '', '0', '0', '0', null, null);
