INSERT INTO `ibf_posts` VALUES ('593', '0', null, '15', 'Morgan', '1', '1', '178.92.114.218', '1337594624', '0', '<!--quoteo(post=590:date=21.5.2012, 9&#58;45:name=NikaLondon)--><div class=\'quotetop\'>Цитата(NikaLondon &#064; 21.5.2012, 9&#58;45) <a href=\"index.php?act=findpost&amp;pid=590\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->Будет ли у нас на сервере оффлайн торговля?<!--QuoteEnd--></div><!--QuoteEEnd--><br /><br /><!--coloro:#FF0000--><span style=\"color:#FF0000\"><!--/coloro--><b>Нет пока не будет. Может быть в будущем.</b><!--colorc--></span><!--/colorc-->', '0', '128', null, '0', null, 'b8201c63a5b4bbe18e9167514583f951', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('589', '0', null, '37', 'Евгений', '1', '1', '176.215.240.113', '1337592401', '0', '<!--quoteo(post=587:date=21.5.2012, 16&#58;42:name=Morgan)--><div class=\'quotetop\'>Цитата(Morgan &#064; 21.5.2012, 16&#58;42) <a href=\"index.php?act=findpost&amp;pid=587\"><{POST_SNAPBACK}></a></div><div class=\'quotemain\'><!--quotec-->А какой кввест то?<!--QuoteEnd--></div><!--QuoteEEnd--><br />К 7му пункту (7. Wrath of Ancestors с Goblin Grave Robber падает по 1 КИ.) <img src=\"style_emoticons/<#EMO_DIR#>/smile.gif\" style=\"vertical-align:middle\" emoid=\":)\" border=\"0\" alt=\"smile.gif\" />. Для этого и нумеровал, чтобы по 10 раз не писать.', '0', '109', null, '0', null, '06996b252b3da3161ae1cd7ddb16989f', '0', '', '0', '0', '0', null, null);
