INSERT INTO `ibf_posts` VALUES ('899', '0', '1338898873', '62', 'oldhippy', '1', '1', '31.162.200.199', '1338769277', null, '[quote name=&#39;oldhippy&#39; timestamp=&#39;1338279594&#39; post=&#39;783&#39;]<br />\ngrim collector квест, который в глудио на скелетов - падает по 1 квест итему с моба. так должно быть?<br />\n[/quote]<br />\n<br />\n[quote name=&#39;Play Boy&#39; timestamp=&#39;1338280331&#39; post=&#39;784&#39;]<br />\n[b]Нет, сейчас исправим.[/b]<br />\n[/quote]<br />\n<br />\nв теме Облава на квесты и баги. Я об этом говорю.', '0', '229', null, '0', 'Play Boy', '3c8e71fae74695461cb1c1368cf6747f', '0', '', '0', '0', '0', null, null);
