INSERT INTO `ibf_posts` VALUES ('798', '0', null, '15', 'L2MarkuS', '1', '1', '94.179.117.238', '1338364903', null, '[quote name=&#39;oldhippy&#39; timestamp=&#39;1338364817&#39; post=&#39;797&#39;]<br />\nтак лучше?)<br />\n[/quote]<br />\n<br />\nДа, вполне. Только я его сейчас не много перемодерирую.', '0', '216', null, '0', null, 'f16b571e2c03b387173dccd02dd99367', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('799', '0', null, '86', 'Мистер Финч', '1', '1', '94.179.117.238', '1338367707', null, 'Не на все квесты идет распределение дропа итемов. Это надо понимать.', '0', '216', null, '0', null, '08c812edb7997943194061d4c36712e1', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('800', '0', null, '86', 'Мистер Финч', '1', '1', '94.179.117.238', '1338368189', null, 'Все что выше указанное, полный маразм не сформировавшегося мозга. (Я сразу прошу прощение за оскорбления). но А рецепты это пиздец ребята. Давайте уже за L2TOP бонусы сделаем получение сразу А шмота и.т.д? Мм? <br />\n<br />\nМоё мнение - это поставить свитки, блесс скроллы, бутылки высокого повышения маны и пойсоны хп. Создать какой нибуть предмет, который повышает статы игрока в x2  на определенное время, маски, украшения, (кстати, ту же маску можно сделать, чтобы она давала какой-то мини-стат игроку - тоже приятно) Но вот эта хуита которая описана выше, просто меня убила.', '0', '213', null, '0', null, 'a890ed6bdbe27b7b51859afe45e64608', '0', '', '0', '0', '0', null, null);
