INSERT INTO `ibf_posts` VALUES ('824', '0', '1338377946', '0', 'L2DontStrong', '1', '1', '2.54.251.99', '1338377515', null, '[color=#222222]После доработки датапака мое и [/color][color=#222222]L[/color][color=#222222]2[/color][color=#222222]MarkuS[/color][color=#222222] место займет другой человек и поднимется на главные администраторы,<br />\nНа сервер я выделил денег для раскрутки онлайна а так же с финансами помог [/color][color=#222222]L[/color][color=#222222]2[/color][color=#222222]MarkuS[/color][color=#222222] [/color][color=#222222]и [/color][color=#222222]L[/color][color=#222222]2[/color][color=#222222]DontStrong[/color][color=#222222].[/color]', '0', '219', null, '0', 'World News', 'bb2e6589a9c962bc8c82406cfa9c8c69', '0', '', '0', '0', '0', null, null);
