INSERT INTO `ibf_posts` VALUES ('865', '0', null, '86', 'Мистер Финч', '1', '1', '127.0.0.1', '1338550951', null, '[quote name=&#39;nokira&#39; timestamp=&#39;1338550883&#39; post=&#39;864&#39;]<br />\nо боже.. только не она&#33;<br />\nсидят персы, которые выкачены до 2 лвла и из-за них жуткие лаги.<br />\n[/quote]<br />\n<br />\nДык мало того, на С3 это будет говено, потому что это С3. Хотя даже если у админов руки прямые они бы могли оффторг сделать с 20 уровня как сейчас чат.', '0', '128', null, '0', null, 'e06a9f0074f365094f08e8dfc00148ef', '0', '', '0', '0', '0', null, null);
