INSERT INTO `ibf_posts` VALUES ('868', '0', null, '86', 'Мистер Финч', '1', '1', '127.0.0.1', '1338551557', null, '[quote name=&#39;nokira&#39; timestamp=&#39;1338551499&#39; post=&#39;867&#39;]<br />\nав и пв.. суть в с3 - реюз и более кучные скилы<br />\n[/quote]<br />\n<br />\nА толку? некром слип парализ, фир  = die', '0', '37', null, '0', null, '738fbba869e14be265b57b63569d39ee', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('869', '0', null, '0', 'Одуванчик', '1', '1', '178.176.185.83', '1338552034', null, '[quote name=&#39;Мистер Финч&#39; timestamp=&#39;1338551557&#39; post=&#39;868&#39;]<br />\nА толку? некром слип парализ, фир  = die<br />\n[/quote]<br />\nТы хоть иногда блин читаешь название тем??', '0', '37', null, '0', null, '0dd9c094d7c369493d223720bee73f37', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('870', '0', null, '86', 'Мистер Финч', '1', '1', '127.0.0.1', '1338552976', null, '[quote name=&#39;Одуванчик&#39; timestamp=&#39;1338552034&#39; post=&#39;869&#39;]<br />\nТы хоть иногда блин читаешь название тем??<br />\n[/quote]<br />\n<br />\nБля ну честно ты заебал. Представь читаю. И умею читать. А ещё пишу как нагнуть дагера.', '0', '37', null, '0', null, '8d2ecebcb415d847a3310ebeb3d81a2a', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('871', '0', null, '0', 'Одуванчик', '1', '1', '178.176.185.83', '1338553169', null, '[quote name=&#39;Мистер Финч&#39; timestamp=&#39;1338552976&#39; post=&#39;870&#39;]<br />\nБля ну честно ты заебал. Представь читаю. И умею читать. А ещё пишу как нагнуть дагера.<br />\n[/quote]<br />\nОоо, треш начался, давай, больше эмоций, больше мата)) По делу, в теме о том, какой дагерщик круче, всем ср*ть на то, что с ними сделает некр)', '0', '37', null, '0', null, '88688388a3928c9c8f3bb83df704112c', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('872', '0', null, '86', 'Мистер Финч', '1', '1', '127.0.0.1', '1338553463', null, '[quote name=&#39;Одуванчик&#39; timestamp=&#39;1338553169&#39; post=&#39;871&#39;]<br />\nОоо, треш начался, давай, больше эмоций, больше мата)) По делу, в теме о том, какой дагерщик круче, всем ср*ть на то, что с ними сделает некр)<br />\n[/quote]<br />\n<br />\nТы хоть знаешь что такое ТРЕШ? Есть 3 варианта. Один из двух вариантов - Направление..........???? ну или в твоём случае маленькая пиписька...', '0', '37', null, '0', null, '5d2ebe592b5ac94ff52a1fb8fbc78972', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('873', '0', null, '0', 'Одуванчик', '1', '1', '178.176.185.83', '1338553813', null, '[quote name=&#39;Мистер Финч&#39; timestamp=&#39;1338553463&#39; post=&#39;872&#39;]<br />\nТы хоть знаешь что такое ТРЕШ? Есть 3 варианта. Один из двух вариантов - Направление..........???? ну или в твоём случае маленькая пиписька...<br />\n[/quote]<br />\nМаленькая?? Странно, вчера ночью ты говорил мне совершенно другое(((', '0', '37', null, '0', null, 'eb9ebffb0a3ef990ace7842ea3fe73cf', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('874', '0', null, '86', 'Мистер Финч', '1', '1', '127.0.0.1', '1338554052', null, '[quote name=&#39;Одуванчик&#39; timestamp=&#39;1338553813&#39; post=&#39;873&#39;]<br />\nМаленькая?? Странно, вчера ночью ты говорил мне совершенно другое(((<br />\n[/quote]<br />\n<br />\nНу да, судя по аве, ты точно не &quot;Гетеро&quot; <img src=\'http://onlineage2.com/forum/public/style_emoticons/<#EMO_DIR#>/biggrin.png\' class=\'bbc_emoticon\' alt=\':D\' />', '0', '37', null, '0', null, '8da60d35780ecd89747e7a5ecc1b3169', '0', '', '0', '0', '0', null, null);
INSERT INTO `ibf_posts` VALUES ('897', '0', null, '15', 'L2MarkuS', '1', '1', '94.179.152.248', '1338755985', null, '[color=#ff0000][b]Требование:[/b][/color]<br />\n<br />\n<br />\n[b][color=#b22222]1.[/color] [color=#0000cd]Хорошо владеть русским языком.[/color][/b]<br />\n[b][color=#b22222]2. [/color][color=#0000cd]Возраст не меньше 20 лет.[/color][/b]<br />\n[b][color=#b22222]3.[/color] [color=#0000cd]Посещаемость форума в день минимум[/color] [color=#800080]4 часа [/color][color=#ff0000](Random)[/color][/b]<br />\n[b][color=#b22222]4. [/color][color=#0000ff]С чувством юмора, и в тоже время серьезностью.[/color][/b]<br />\n<br />\n<br />\n<br />\n[color=#006400][b]Предложения?[/b][/color]', '0', '230', null, '1', null, '69b43b1ee551801117173185ea6f6f50', '0', '', '0', '0', '0', null, null);
