INSERT INTO `ibf_skin_cache` VALUES ('977', '1338223376', 'phptemplate', '1', 'group', 'skin_editors', '', '', '', 'class skin_editors_1 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n$this->_funcHooks[\'ajaxEditBox\'] = array(\'jsNotLoaded\',\'ajaxerror\',\'showreason\',\'appendedit\',\'showappendedit\',\'showeditoptions\',\'htmlstatus\');\n$this->_funcHooks[\'editor\'] = array(\'jsNotLoaded\',\'ismini\',\'hasType\',\'ismini\',\'hasHeight\',\'hasMinimize\',\'hasCallback\',\'hasSaveKey\');\n$this->_funcHooks[\'editorJS\'] = array(\'hasemoticons\');\n$this->_funcHooks[\'editorLoadJs\'] = array(\'hasimages\',\'noSmilies\',\'bypassCkEditor\');\n$this->_funcHooks[\'editorSettings\'] = array(\'isSelected\',\'isSelected\');\n$this->_funcHooks[\'editorShell\'] = array(\'notlightweight\',\'shellnotlightweight\',\'shellremoveemoticons\',\'shellsecondbarlightweight\');\n$this->_funcHooks[\'ips_editor\'] = array(\'removeemoticons\');\n$this->_funcHooks[\'mediaGenericWrapper\'] = array(\'haswidth\',\'hasheight\',\'hasimage\',\'hasdescription\',\'genericmedia\',\'hasrows\');\n$this->_funcHooks[\'sharedMedia\'] = array(\'mediatabs\');\n\n\n}\n\n/* -- ajaxEditBox --*/\nfunction ajaxEditBox($post=\"\", $pid=0, $error_msg=\"\", $extraData) {\n$IPBHTML = \"\";\nif( IPSLib::locationHasHooks( \'skin_editors\', $this->_funcHooks[\'ajaxEditBox\'] ) )\r\n{\r\n$count_33cf98834fa2e8417354