INSERT INTO `ibf_skin_cache` VALUES ('1000', '1338223377', 'phptemplate', '1', 'group', 'skin_topic', '', '', '', 'class skin_topic_1 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n$this->_funcHooks[\'ajaxFastReplyJS\'] = array(\'isLoggedIn\',\'canDeleteUrls\');\n$this->_funcHooks[\'ajaxFastReplyRow\'] = array(\'noRep\',\'posRep\',\'negRep\',\'repIgnored\',\'userIgnored\',\'postMid\',\'postOnline\',\'postMember\',\'postAdmin\',\'postIp\',\'postModSelected\',\'postModCheckbox\',\'postIcon\',\'postEditByReason\',\'postEditBy\',\'postSignature\',\'repHighlight\',\'hasNoRep\',\'hasPosRep\',\'hasNegRep\',\'giveRepUp\',\'giveRepDown\',\'hasNotGivenRep\',\'canRep\',\'reputationBox\',\'postIsReported\',\'canReportPost\',\'multiquote\',\'canEdit\',\'canDelete\',\'approveUnapprove\',\'approvePost\',\'reportedPostData\',\'initIgnoredPost\',\'bottomNewTopic\',\'bottomClosedButtonLink\',\'bottomReplyButtonLink\',\'bottomReplyButton\',\'bottomIsClosed\',\'endFirstPost\');\n$this->_funcHooks[\'announcement_show\'] = array(\'announceMember\',\'canmanage\',\'disablelightbox\');\n$this->_funcHooks[\'hookFacebookLike\'] = array(\'checkAccess\',\'fbAppIdPresent\');\n$this->_funcHooks[\'likeSummaryContents\'] = array(\'likeOnlyMembers\');\n$this->_funcHooks[\'pollDisplay\'] = array(\'lastVoter\',\'poll_voters\',\'hasVoters\',\'viewVoters\',\'votersJs\',\'multiVote\',\'showingResults\'