rtModForm\',\'hasPosts\',\'modButtonCount\',\'showModOptionsinner\',\'mmModOptions\',\'showModOptions\',\'modOptions\',\'hasUnreadNext\',\'modOptionsLink\',\'isLockedFR\',\'isMember\',\'loadJsManually\',\'fastReply\',\'canShare\',\'auNames\',\'topicActiveUsers\',\'scrollToPost\');\n\n\n}\n\n/* -- ajax__deletePost --*/\nfunction ajax__deletePost() {\n$IPBHTML = \"\";\n$IPBHTML .= \"<h3>{$this->lang->words[\'dlp_title\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<h4 class=\'row2 ipsPad\'><strong>{$this->lang->words[\'dlp_remove_from_view\']}</strong></h4>\n		<div class=\'ipsPad ipsForm_center\'>\n			{$this->lang->words[\'dlp_remove_from_view_desc\']}<br />\n			<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_remove_from_view_extra\']}</span><br /><br />\n			<form action=\'#{removeUrl}\' method=\'POST\'>\n				<input type=\'text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' class=\'input_text\' style=\'width: 60%\' /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlp_remove\']}\' />\n			</form>\n		</div>\n	</div>\n	\" . (($this->registry->class_forums->canHardDeletePosts( $this->request[\'id\'], $topic )) ? (\"\n		<div class=\'ipsPad ipsForm_center\' style=\'font-size: 32px\'>\n			{$this->lang->words[\'dlp_or\']}\n		</div>\n		<div class=\'ipsBox_container\'>\n			<h4 class=\'row2 ipsPad\'><strong>{$this->lang->words[\'dlp_delete_from_topic\']}</strong></h4>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dlp_delete_from_topic_desc\']}</br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_delete_from_topic_extra\']}</span><br /><br />\n				<input type=\'button\' class=\'input_submit\' onclick=\\\"window.location=\'#{permaUrl}\';\\\" value=\'{$this->lang->words[\'dlp_delete_now\']}\' />\n			</div>\n		</div>\n	\") : (\"\")) . \"\n</div>\";\nreturn $IPBHTML;\n}\n\n/* -- ajaxFastReplyDivider --*/\nfunction ajaxFastReplyDivider() {\n$IPBHTML = \"\";\n$IPBHTML .= \"<div id=\\\"ajaxFastReply\\\" title=\\\"#\\\" name=\\\"\" . time() . \"\\\"></div>\";\nreturn $IPBHTML;\n}\n\n/* -- ajaxFastReplyJS --*/\nfunction ajaxFastReplyJS() {\n$IPBHTML = \"\";\nif( IPSLib::locationHasHooks( \'skin_topic\', $this->_funcHooks[\'ajaxFastReplyJS\'] ) )\r\n{\r\n$count_ab6cf9ec0ed5ec85e422ffdd277d5931 = is_array($this->functionData[\'ajaxFastReplyJS\']) ? count($this->functionData[\'ajaxFastReplyJS\']) : 0;\n}\n$IPBHTML .= \"<script type=\\\"text/javascript\\\">\n\n// Jump to anchor embedded in query string\n\nvar regex = /pid__([0-9]+)/;\nvar anchor;\n\nif ( regex.test( document.location ) )\n{\n	anchor = \\\"#entry\\\" + regex.exec( document.location )[1];\n}\nelse\n{\n	regex = /&pid=([0-9]+)/;\n	\n	if ( regex.test( document.location ) )\n	{\n		anchor = \\\"#entry\\\" + regex.exec( document.location )[1];\n	}\n}\n\nif ( anchor != undefined )\n{\n	document.location.hash = anchor;\n}\n\n\" . (($this->memberData[\'member_id\']) ? (\"\n\ndocument.observe( \\\"dom:loaded\\\", function()\n{\n	// Avoid ipb.delegate.register() as it takes over \\\"Use Full Editor\\\" button, too\n		\n	$(\'submit_post\').observe( \'click\', ajaxFastReply );\n		\n	// Set current timestamp for getting new replies\n		\n	$(\'ajaxFastReply\').setAttribute( \'title\', document.location.hash );\n		\n	// Browser back/forward button functionality\n		\n	setInterval( \\\"ajaxAnchorCheck()\\\", 150 );\n});\n\n\") : (\"\")) . \"\n\n/* ------------------------------ */\n// [EN31] Ajax Fast Reply v1.0.6\n/* ------------------------------ */\n\nfunction ajaxAnchorCheck()\n{\n	// Init effects\n	\n	var effects = new Array(5);\n									effects[0]	= function( id, parameters ) { new Effect.Shake( id, parameters ); };\n									effects[1]	= function( id, parameters ) { new Effect.Appear( id, parameters ); };\n									effects[2]	= function( id, parameters ) { new Effect.Pulsate( id, parameters ); };\n									effects[3]	= function( id, parameters ) { new Effect.BlindDown( id, parameters ); };\n									effects[4]	= function( id, parameters ) { new Effect.Highlight( id, parameters ); };\n	\n	// Has the hash changed? This fires either when\n	// a post is made or the back/forward button is pressed\n	\n	if ( document.location.hash != $(\'ajaxFastReply\').getAttribute( \'title\' ) )\n	{\n		// Init greatest PID and number of posts hidden/shown\n		\n		var pid			= 0;\n		var posts		= 0;\n		var ajaxDiv		= $(\'ajaxFastReply\');\n		var pidArray		= new Array();\n		\n		// If a hash does not contain #entry,\n		// all ajax-returned posts are hidden\n		\n		if ( document.location.hash.indexOf( \\\"#entry\\\" ) != -1 )\n		{\n			// When new posts are added, this is set to the greatest PID returned\n			\n			pid = document.location.hash.replace( \\\"#entry\\\", \\\"\\\" );\n		}\n		\n		// Loop our returned ajax posts\n\n		for ( var i = 0; i < ajaxDiv.childNodes.length; i++ )\n		{\n			if ( ajaxDiv.childNodes[i].nodeType === 1 )\n			{\n				if ( ajaxDiv.childNodes[i].id.indexOf( \'post_id_\' ) != -1 )\n				{\n					// Did we meet the criteria?\n					\n					if ( parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ) > pid )\n					{\n						// Hide and unload the post\n						\n						ajaxDiv.childNodes[i].style.display = \\\"none\\\";\n						ajaxDiv.childNodes[i].setAttribute( \'title\', \'unloaded\' );\n					}\n					else\n					{\n						if ( ajaxDiv.childNodes[i].title == \'created\' )\n						{\n							// Scroll to the current post\n\n							if ( posts == 0 && ajaxDiv.title.indexOf( \'-reset\' ) == -1 )\n							{\n								new Effect.ScrollTo( \\\"entry\\\" + parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ), {$this->settings[\'en30_scrolleffectparams\']} );\n							}\n							\n							// Does this effect highlight or reveal?\n							\n							if ( {$this->settings[\'en30_revealeffect\']} % 2 == 0 )\n							{\n								new Effect.Appear( \\\"post_id_\\\" + parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ), { duration: 0.1, queue: \'end\' } );\n							}\n							\n							// Display the main effect\n							\n							effects[ {$this->settings[\'en30_revealeffect\']} ]( ajaxDiv.childNodes[i].id, {$this->settings[\'en30_revealeffectparams\']} );\n							\n							// Post is loaded, increment and add to PID array\n							\n							ajaxDiv.childNodes[i].setAttribute( \'title\', \'loaded\' );\n							\n							pidArray[posts] = ajaxDiv.childNodes[i].id.substr( 8 );\n							posts++;\n						}\n						else\n						{\n							if ( ajaxDiv.childNodes[i].getAttribute( \'title\' ) == \'unloaded\' )\n							{\n								ajaxDiv.childNodes[i].style.display = \\\"block\\\";\n\n								// Post is loaded, increment total posts\n																	\n								ajaxDiv.childNodes[i].setAttribute( \'title\', \'loaded\' );\n								posts++;\n							}\n						}\n					}\n				}\n			}\n		}\n		\n		// Highlight any new replies\n		\n		if ( pidArray.length > 1 )\n		{\n			for ( var i = 0; i < ( pidArray.length - 1 ); i++ )\n			{\n				// Queue the highlight effect					\n				new effects[ {$this->settings[\'en30_newreplyeffect\']} ]( \\\"post_id_\\\" + pidArray[i], {$this->settings[\'en30_newreplyeffectparams\']} );\n			}\n		}\n					\n		// Reset the current anchor\n		ajaxDiv.setAttribute( \'title\', document.location.hash );\n	}\n}\n\nfunction ajaxMakeVisible( i )\n{\n	// Nice and easy\n	$(\'ajaxFastReply\').childNodes[i].style.display	= \'block\';\n}\n\nfunction ajaxAnchorSet( anchor )\n{\n	document.location.hash = anchor;\n	$(\'ajaxFastReply\').setAttribute( \'title\', anchor + \'-reset\' );\n}\n\nfunction ajaxFastReply( e )\n{\n	// Prevent standard execution of onclick()\n	Event.stop(e);\n\n	var elem = Event.element( e );\n	var form = elem.form;\n	\n	try\n	{\n		// Need to update for submit manually in this case\n		\n		ipb.editors[ \'fast-reply\' ].update_for_form_submit();\n		var Post = $( \'fast-reply_textarea\' ).getValue();\n	}\n	catch( err )\n	{\n		Debug.error( err );\n		Debug.dir( ipb.editors );\n		return;\n	}\n\n	if( Post.blank() )\n	{\n		alert( ipb.lang[\'post_empty\'] );\n		return;\n	}\n\n	// Set up POST url\n	var url = \'{$this->settings[\'base_url\']}app=forums&module=ajax&section=topics&do=ajaxFastReply\';\n\n	// Set up ajax request with our form data\n	\n	new Ajax.Request(	url,\n						{\n							method: \'post\',\n							evalJSON: \'force\',\n							encoding: \'{$this->settings[\'gb_char_set\']}\',\n							parameters: {\n								md5check: 			\'{$this->member->form_hash}\',\n								f:				form.f.value,\n								t:				form.t.value,\n								st:				form.st.value,\n								auth_key:			form.auth_key.value,\n								fast_reply_used:		form.fast_reply_used.value,\n								enableemo:			form.enableemo.value,\n								enablesig:			form.enablesig.value,\n								Post: 				Post.encodeParam(),\n								submit:				form.submit.value,\n								post_date:			$(\'ajaxFastReply\').getAttribute( \'name\' )\n							},\n\n							onSuccess: function(ajax)\n							{\n								// Debug Mode\n								//alert( ajax.responseText );\n\n								if( ajax.responseJSON[\'error\'] )\n								{\n									alert( \'Error: \' + ajax.responseJSON[\'error\'] );\n									return;\n								}\n								else\n								{\n									// Success!\n									// Clear fast reply textarea\n									\n									if ( ! USE_RTE )\n									{\n										// Using STD\n										$(\'fast-reply_textarea\').value = \\\"\\\";\n									}\n									else\n									{\n										// Using RTE\n										$(\'fast-reply_iframe\').contentWindow.document.getElementById( \'fast-reply_html\' ).childNodes[1].innerHTML = \\\"\\\";\n									}\n																	\n									// Make shortcut to returned posts JSON array\n									\n									var posts = ajax.responseJSON[\'posts\'];\n									\n									// Make shortcut to our ajax divider\n\n									var ajaxDiv	 = $(\'ajaxFastReply\');\n									\n									// Do we have a merged post on the page?\n									\n									var hasMergedPost = false;\n\n									for ( var i = 0; i < posts.length; i++ )\n									{\n										if ( document.getElementById( \'post_id_\' + posts[i][\'pid\'] ) != undefined )\n										{\n											hasMergedPost = true;\n											break;\n										}\n									}\n									\n									// Change anchor to support back/forward\n									// button functionality\n									\n									if ( ! hasMergedPost && document.location.hash != \\\"#entry\\\" + posts[ ( posts.length - 1 ) ][\'pid\'] )\n									{\n										// Firefox will flicker anytime we change the hash,\n										// even if to the same hash. The if() avoids the flicker\n										\n										document.location.hash = \\\"#entry\\\" + posts[ ( posts.length - 1 ) ][\'pid\'];\n									}\n									\n									// Init vars to be assigned in for() loop\n									\n									var a;\n									var b;\n									var pid;\n									var postDivs;\n									var postRow;\n									var rowClass;\n									var entryAnchor;\n\n									for ( var i = 0; i < posts.length; i++ )\n									{\n										// Shortcut PID\n										pid = posts[i][\'pid\'];\n										\n										// Delete concurrent posts if a merged post is returned\n										\n										if ( hasMergedPost )\n										{\n											postDivs = ajaxDiv.parentNode.getElementsByTagName( \'div\' );\n\n											for ( a = 0; a < postDivs.length; a++ )\n											{\n												if ( postDivs[a].nodeType === 1 )\n												{\n													if ( postDivs[a].id.indexOf( \'post_id\' ) != -1 )\n													{\n														if ( parseInt( postDivs[a].id.substr( 8 ) ) == pid )\n														{\n															// Scroll to the to-be-merged post\n															\n															new Effect.ScrollTo( postDivs[a].id, {$this->settings[\'en30_scrolleffectparams\']} );\n															\n															// Fade it out, then remove it from the DOM\n\n															new Effect.Fade( postDivs[a].id, { queue: \\\"end\\\", \n															afterFinish: function( effect ) { \n																							var pid = effect.element.id.substr( 8 );\n																							if ( effect.element.parentNode.id == \'ajaxFastReply\' )\n			{\n				$(\'ajaxFastReply\').removeChild( effect.element );\n			}\n																							else\n			{\n				$(\'ajaxFastReply\').parentNode.removeChild( effect.element );\n			}\n\n			ajaxAnchorSet( \\\"#entry\\\" + pid );\n																							}	\n		}\n	);\n															break;\n														}\n													}\n												}\n											}\n										}\n										\n										// Create our post anchor\n										\n										entryAnchor	= document.createElement( \'a\' );\n										\n										entryAnchor.setAttribute( \'id\', \\\"entry\\\" + pid );\n										ajaxDiv.appendChild( entryAnchor );\n										\n										// Create our post row\n										\n										postRow			= document.createElement( \'div\' );\n										rowClass		= \\\"post_block hentry clear\\\";\n										\n										// Set up the row class\n										\n										if ( {$this->settings[\'reputation_highlight\']} != 0 && posts[i][\'rep_points\'] >= {$this->settings[\'reputation_highlight\']} )\n										{\n											rowClass = rowClass + \\\" rep_highlight\\\";\n										}\n										\n										if ( posts[i][\'queued\'] == 1 )\n										{\n											rowClass = rowClass + \\\" moderated\\\";\n										}\n										\n										if ( {$this->settings[\'reputation_enabled\']} == 1 )\n										{\n											rowClass = rowClass + \\\"  with_rep\\\";\n										}\n										\n										// Set up our post divider attribute\n										\n										postRow.setAttribute( \\\"class\\\", rowClass );\n										postRow.setAttribute( \\\"title\\\", \\\"created\\\" );\n										postRow.setAttribute( \\\"id\\\", \\\"post_id_\\\" + pid );\n										\n										// This fixes the flicker of Effect.BlindDown() in Firefox\n										\n										postRow.style.margin = \\\"0\\\";\n										\n										// Hide it by default\n										\n										postRow.style.display	= \\\"none\\\";\n										postRow.innerHTML	= posts[i][\'post\'];\n										\n										// Insert it into our ajaxDiv\n\n										ajaxDiv.appendChild( p