INSERT INTO `ibf_skin_cache` VALUES ('1023', '1338668441', 'phptemplate', '2', 'group', 'skin_editors', '', '', '', 'class skin_editors_2 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n$this->_funcHooks[\'editor\'] = array(\'jsNotLoaded\',\'ismini\',\'hasType\',\'ismini\',\'hasHeight\',\'hasMinimize\',\'hasCallback\',\'hasSaveKey\');\n\n\n}\n\n/* -- ajaxEditBox --*/\nfunction ajaxEditBox($post=\"\", $pid=0, $error_msg=\"\", $extraData) {\n$IPBHTML = \"\";\n$IPBHTML .= \"<!--no data in this master skin-->\";\nreturn $IPBHTML;\n}\n\n/* -- editor --*/\nfunction editor($formField=\'post\', $content=\'\', $options=array(), $autoSaveData=array()) {\n$IPBHTML = \"\";\nif( IPSLib::locationHasHooks( \'skin_editors\', $this->_funcHooks[\'editor\'] ) )\r\n{\r\n$count_168539e29840e72644cddfeeba29d199 = is_array($this->functionData[\'editor\']) ? count($this->functionData[\'editor\']) : 0;\n$this->functionData[\'editor\'][$count_168539e29840e72644cddfeeba29d199][\'formField\'] = $formField;\n$this->functionData[\'editor\'][$count_168539e29840e72644cddfeeba29d199][\'content\'] = $content;\n$this->functionData[\'editor\'][$count_168539e29840e72644cddfeeba29d199][\'options\'] = $options;\n$this->functionData[\'editor\'][$count_168539e29840e72644cddfeeba29d199][\'autoSaveData\'] = $autoSaveData;\n}\n\n/* Always return as UTF-8 */\n	array_walk_recursive( $autoSaveData, array( \'IPS