INSERT INTO `ibf_skin_cache` VALUES ('1052', '1338668441', 'css', '2', 'name', 'ipb_print', 'position', '1', '0', '* {\n	font-family: Georgia, \"Times New Roman\", serif;\n}\n\nhtml #content {\n	font-size: 10pt;\n}\n\n#admin_bar,\n#header,\n#footer_utilities,\n#utility_links,\n.post_mod,\n.author_info,\n.rep_bar,\n.post_controls,\n.top,\n#content_jump,\n.topic_buttons,\n.topic_options,\nh1,\n.post_id,\nh3 img,\n.ip,\nhr,\n.moderation_bar,\n.topic_jump,\n.topic_share,\n#fast_reply,\n#reputation_filter,\n.statistics {\n	display: none;\n}\n\n#breadcrumb {\n	display: block !important;\n}\n	#breadcrumb li {\n		float: left;\n	}\n\n.post_block {\n	margin-bottom: 25pt;\n	border-top: 2pt solid gray;\n	line-height: 60%; \n	padding-top: 10px;\n}\n\n.posted_info {\n	color: gray !important;\n	font-size: 8pt !important;\n	text-decoration: none !important;\n	border-bottom: 1pt solid lightgray;\n	padding-bottom: 3px;\n}\n\n.post_block h3 {\n	display: inline !important;\n	margin: 0px !important;\n	padding: 0px !important;\n}\n\n.post_block h3 a {\n	color: black !important;\n	text-decoration: none !important;\n	font-style: normal !important;\n}\n\n	.post_block .post_body a:after {\n	    content: \" (\" attr(href) \") \";\n	}\n\n.post_body {\n	margin-left: 10pt;\n	line-height: 100%;\n	margin-top: 15pt;\n}\n\nh1, h2, h3 {\n	font-weight: bold;\n}\n\n#copyright {\n	text-align: center;\n	color: gray;\n	font-size: 9pt;\n}', 'setBy', 'appInfo', 'core-0', 'attributes', 'media=\"print\"', 'modules', '');
