INSERT INTO `ibf_skin_cache` VALUES ('1043', '1338668441', 'phptemplate', '2', 'group', 'skin_shoutbox_hooks', '', '', '', 'class skin_shoutbox_hooks_2 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n\n\n}\n\n/* -- hookActiveUsers --*/\nfunction hookActiveUsers($stats) {\n$IPBHTML = \"\";\n$IPBHTML .= \"\";\nreturn $IPBHTML;\n}\n\n/* -- hookActiveUsersSidebar --*/\nfunction hookActiveUsersSidebar($stats) {\n$IPBHTML = \"\";\n$IPBHTML .= \"\";\nreturn $IPBHTML;\n}\n\n/* -- hookGlobalShoutbox --*/\nfunction hookGlobalShoutbox($d=\'\') {\n$IPBHTML = \"\";\n$IPBHTML .= \"\";\nreturn $IPBHTML;\n}\n\n/* -- hookGlobalShoutboxEmoticons --*/\nfunction hookGlobalShoutboxEmoticons($emoticons=array()) {\n$IPBHTML = \"\";\n$IPBHTML .= \"\";\nreturn $IPBHTML;\n}\n\n/* -- hookGlobalShoutboxSidebar --*/\nfunction hookGlobalShoutboxSidebar($d=\'\') {\n$IPBHTML = \"\";\n$IPBHTML .= \"\";\nreturn $IPBHTML;\n}\n\n/* -- hookOnlineTab --*/\nfunction hookOnlineTab($count=0) {\n$IPBHTML = \"\";\n$IPBHTML .= \"<!--no data in this master skin-->\";\nreturn $IPBHTML;\n}\n\n\n}\n', '', '', '', '', '', '', '');
INSERT INTO `ibf_skin_cache` VALUES ('1053', '1338668441', 'css', '2', 'name', 'ipb_styles', 'position', '1', '0', '/************************************************************************/\n/* IP.Board 3 Mobile CSS - By Rikki Tissier - (c)2008 Invision Power Services	*/\n/************************************************************************/\n/* ipb_styles.css														*/\n/************************************************************************/\n\n/************************************************************************/\n/* RESET (Thanks to YUI) */\n\nbody,div,dl,dt,dd,ul,ol,li,h1,h2,h3,h4,h5,h6,pre,form,fieldset,input,textarea,p,blockquote,th,td { margin:0; padding:0; } \ntable {	border-collapse:collapse; border-spacing:0; }\nfieldset,img { border:0; }\naddress,caption,cite,code,dfn,th,var { font-style:normal; font-weight:normal; }\nol,ul { list-style:none; }\ncaption,th { text-align:left; }\nh1,h2,h3,h4,h5,h6 { font-size:100%;	font-weight:normal; }\nq:before,q:after { content:\'\'; }\nabbr,acronym { border:0; }\nhr { display: none; }\naddress{ display: inline; }\n\n/************************************************************************/\n/* ELEMENT STYLES */\n\nhtml, body, form, fieldset, p, div, h1, h2, h3, h4, h5, h6 {\n	-webkit-text-size-adjust:none !important;\n}\n\nbody {\n	background: #cad6e2;\n	color: #192b40;\n	font: normal 13px helvetica, arial, verdana, tahoma, sans-serif;\n	position: relative;\n}\n\nh1 {\n	background: #5376a0; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#6b9ed2), color-stop(100%,#517db1)); /* Chrome,Safari4+ */\n	border-bottom: 1px solid #111;\n	text-align: center;\n}\n\nh1 a {\n	font-size: 1.2em; \n	font-weight: bold; \n	padding: 0;\n	text-shadow: 0px -1px 0 rgba(0,0,0,0.8);\n	display: inline-block;\n	max-width: 140px;\n	overflow: hidden;\n	text-overflow: ellipsis;\n	white-space: nowrap;\n	color: #fff;\n	text-decoration: none;\n	line-height: 42px; \n	height: 42px;\n}\n	\n#content { -webkit-box-shadow: 0px 2px 12px rgba(0,0,0,0.2); }\n\n#footer {\n	margin: 0 auto;\n	text-align: center;\n	padding: 10px 0;\n	font-size: 11px;\n}\n	\n	#show_skins, #show_langs, #full_version, #app_link {\n		font-size: 12px;\n		text-decoration: none;\n		display: inline-block;\n		-webkit-border-radius: 10px;\n		padding: 5px 10px;\n		color: #fff;\n		background: #b8c6df; /* Old browsers */\n		background: -moz-linear-gradient(top, #b8c6df 0%, #9eafcd 100%); /* FF3.6+ */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#b8c6df), color-stop(100%,#9eafcd)); /* Chrome,Safari4+ */\n		text-shadow: 0px -1px 0px rgba(0,0,0,0.2);\n		margin-bottom: 4px;\n	}\n\nh3, h4, h5, h6, strong { font-weight: bold; }\nem { font-style: italic; }\nimg, .input_check, .input_radio { vertical-align: middle; }\nlegend { display: none; }\ntable { width: 100%; }\ntd { padding: 3px; }\n\nbody a:hover {\n	text-decoration: underline !important;\n}\n\n.clearfix:after { content: \".\";display: block;height: 0;clear: both;visibility: hidden;}\n.hidden, #loadingBox img, .post_controls { display: none; }\n.visible { display: block;}\n\n/* Cancel */\n.cancel {\n	color: #ad2930;\n	font-size: 90%;\n	font-weight: bold;\n}\n	\nh2 {\n	background: #45484d; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#45484d), color-stop(100%,#000000)); /* Chrome,Safari4+ */\n	color: #fff;\n	font-size: 14px;\n	padding: 10px 10px;\n	text-shadow: -1px -1px 0 rgba(0,0,0,1);\n}\n\n	h2 a {\n		color: #fff;\n		text-decoration: none;\n	}\n	\n	h2.secondary {\n		background: #f1f1f1;\n		color: #1d3652;\n		text-shadow: none;\n		padding: 5px;\n	}\n		\n		h2.secondary span.subtext {\n			color: #9d9d9d;\n		}\n		\n		h2.secondary a {\n			color: #1d3652;\n			font-size: 16px;\n		}\n		\n#user_navigation {\n	background: #393939; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#393939), color-stop(100%,#212121)); /* Chrome,Safari4+ */\n	-webkit-box-shadow: 0px 4px 10px rgba(0,0,0,0.7);\n	z-index: 5;\n}\n\n	#user_navigation .launcher ul { margin: 10px 10px 20px 10px; }\n	#user_navigation .launcher li {\n		width: 33.33%;\n		float: left;\n	}\n\n	#user_navigation .launcher li a, #user_navigation #user_bar {\n		display: block;\n		position: relative;\n		margin: 3px;\n		height: 80px;\n		padding: 10px 0 0 0;\n		border: 1px solid #373737;\n		-webkit-border-radius: 7px;\n		text-align: center;\n		font-size: 13px;\n		text-decoration: none;\n		color: #b3b3b3;\n		text-shadow: 0px -1px 0px rgba(0,0,0,0.9);\n		background: #1c1c1c; /* Old browsers */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#1c1c1c), color-stop(100%,#282828)); /* Chrome,Safari4+ */\n		-webkit-box-shadow: 0px 0px 5px rgba(0,0,0,0.8) inset;\n	}\n\n		#user_navigation .launcher li a:hover .icon, #user_navigation .launcher li a:active .icon { opacity: 0.8; }\n\n		#user_navigation .launcher li.dummy span {\n			display: block;\n			background: #1c1c1c;\n			border: 1px solid #373737;\n			padding: 10px 0 0 0;\n			height: 80px;\n			margin: 3px;\n			-webkit-border-radius: 7px;\n			opacity: 0.4;\n		}\n\n	#user_navigation .icon {\n		display: block;\n		width: 50px;\n		height: 50px;\n		background-image: url(http://onlineage2.com/forum/public/style_images/mobile/app_icon_sprite.png );\n		background-repeat: no-repeat;\n		margin: 0 auto 7px;\n		opacity: 0.4;\n	}\n\n	#user_navigation .ipsHasNotifications {\n		position: absolute;\n		top: -3px;\n		right: 3px;\n		display: block;\n		height: 20px; line-height: 20px;\n		padding: 0 10px;\n		background: #ff3019; /* Old browsers */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#ff3019), color-stop(100%,#e00404));\n		border: 1px solid #e00404;\n		-webkit-border-radius: 5px;\n		color: #fff;\n		font-size: 12px;\n		text-shadow: 0px -1px 0 #950303;		\n	}\n\n	#nav_members .icon { background-position: 0px 0px; }\n	#nav_notifications .icon { background-position: -222px 0px; }\n	#nav_blog .icon { background-position: -55px 0px; }\n	#nav_statuses .icon { background-position: -168px 0px; }\n	#nav_gallery .icon { background-position: -110px 0px; }\n	#nav_vnc .icon { background-position: -54px -55px; }\n	#nav_search .icon { background-position: 0px -54px; }\n	#nav_messages .icon { background-position: -110px -54px; }\n	#nav_markread .icon { background-position: -168px -54px; }\n\n	#user_navigation #user_bar {\n		height: auto;\n		padding: 10px;\n	}\n	\n#secondary_navigation {\n	position: absolute;\n	top: 0;\n	left: 5px;\n}\n	#secondary_navigation a {\n		max-width: 70px;\n		line-height: 32px;\n		margin-top: 5px;\n		-webkit-border-radius: 4px;\n		padding: 0 5px;\n		color: #fff;\n		white-space: nowrap;\n		display: block;\n		color: #fff;\n		text-decoration: none;\n		text-overflow: ellipsis;\n		overflow: hidden;\n		background: #375880;\n		-webkit-box-shadow: 0px 0px 4px rgba(0,0,0,0.4) inset;\n		text-shadow: 0px -1px 0 rgba(0,0,0,0.7);\n		font-size: 11px;\n	}\n\n	#secondary_navigation a:hover {\n		text-decoration: none !important;\n	}\n\n	#options-button {\n		text-indent: -3000em;\n		position: absolute;\n		top: 0;\n		right: 5px;\n		width: 40px;\n		line-height: 32px;\n		-webkit-border-radius: 4px;\n		margin-top: 5px;\n		display: block;\n		color: #fff;\n		text-decoration: none;\n		background: #375880 url(http://onlineage2.com/forum/public/style_images/mobile/mobile_nav.png ) no-repeat 50% 50%;\n		-webkit-box-shadow: 0px 0px 4px rgba(0,0,0,0.4) inset;\n	}	\n	\n#search_bar, h3 {\n	background: #f6f6f6 url(http://onlineage2.com/forum/public/style_images/mobile/search_bar_bg.png) repeat-x top;\n	padding: 6px;\n	text-align: center;\n	border-bottom: 1px solid #b8b8b8;\n	border-top: 1px solid #e0e0e0;\n}\n\n	#search_bar #main_search { width: 60%; }\n	\n	#search_bar .button {\n		width: 21%;\n		margin-left: 2%;\n		font: normal 11px arial, verdana, tahoma, sans-serif;\n	}\n		\n		#search_bar #adv_search {\n			width: 8%;\n			margin-left: 0;\n		}\n\nh3 { text-align: left; }\n\n#footer form, #footer fieldset { display: inline; }\n#board_index .icon { min-width: 35px; margin: 4px 5px 0 5px; }\n#board_index .row_content { margin-left: 42px; }\n\n.desc {\n	color: #a2a2a2;\n	font-size: 90%;\n}\n\n.photo {\n	border: 1px solid #d8e1ea;\n}\n\n.line_spacing {\n	line-height: 150%;\n}\n\n.padding { \n	padding: 10px;\n}\n\n.master_list .row {\n	background: #ffffff;\n	padding: 10px 10px;\n	border-top: 1px solid #e9edf1;\n	overflow: hidden;\n}\n\n	.master_list .row.unread {\n		background: #f5f9fd;\n	}\n		.master_list .row.unread .title {\n			font-weight: bold;\n		}\n	\n	.master_list .title { \n		font-size: 14px;\n	}\n	\n	.master_list .row h4 {\n		margin-bottom: 5px;\n	}\n	\n	.master_list .row a,\n	.master_list .mini_pagination a,\n	.master_list .pagination a {\n		color: #375f8d;\n		text-decoration: none;\n	}\n\n	.master_list .row .icon {\n		float: left;\n		margin: 0 5px 0 -5px;\n		min-width: 18px;\n	}\n\n		.master_list .row .icon img {\n			vertical-align: middle;\n		}\n	\n	.master_list .post {\n		padding: 10px 15px;\n	}\n	\n	.master_list .row_content {\n		margin-left: 25px;\n	}\n	\n	.master_list .topic_reply {\n		margin: 5px;\n		border: 1px solid #b8b8b8;\n		position: relative;\n	}\n	\n		.master_list .topic_reply .post { \n			clear: both; \n			border-top: 0; \n		}\n\n		.topic_reply h2 { \n			padding: 7px 0 8px 50px; \n			line-height: 1.1;\n			-webkit-border-radius: 5px 5px 0 0;\n		}\n		.topic_reply h2 span { \n			display: block; \n		}\n	\n	.master_list .controls, .submit {\n		padding: 6px;\n		text-align: left;\n		min-height: 35px;\n	}\n	\n		.master_list .post_controls {\n			background: #f3f3f3;\n			padding: 6px;\n			text-align: right;\n		}\n	\n		.master_list .post_controls a {\n			font-size: 90%;\n			color: #727272;\n			text-decoration: none;\n			margin: 0 10px;\n		}\n	\n	.master_list .pagination {\n		float: right;\n		padding: 4px;\n	}\n	\n	.master_list .topic_prefix {\n		font-size: 75%;\n		color: #a2a2a2;\n		font-weight: bold;\n	}\n	\n	.master_list .subtext {\n		font-size: 80%;\n		font-weight: normal;\n		color: #808080;\n	}\n	\n		.master_list h2 .subtext {\n			color: #1d3652;\n		}\n	\n	.master_list .mini_pagination,\n	.master_list .pagination {\n		font-size: 90%;\n		margin-left: 10px;\n	}\n\n		.master_list .pagination {\n			font-size: 100%;\n		}\n\n		.master_list .mini_pagination a,\n		.master_list .pagination span.page a  {	\n			padding: 1px 4px;\n			border: 1px solid #b8b8b8;\n			background: #f9f9f9;\n			display: inline-block;\n			font-weight: bold;\n		}\n		\n		.master_list .pagination span.page.active {\n			background: #192b41;\n			border: 1px solid #192b41;\n			padding: 1px 4px;\n			color: #fff;\n		}\n		\n		.master_list .pagination span.total {\n			font-style: normal !important;\n			font-size: 90% !important;\n		}\n	\n	.master_list .submit {\n		padding: 12px 10px;\n		font-weight: bold;\n		font-size: 13px;\n	}\n	\n	.master_list .right_info {\n		float: right;\n		padding: 2px 6px;\n		background: #1d3652;\n		color: #fff;\n		font-weight: bold;\n		font-size: 80%;\n		-moz-border-radius: 3px;\n		-webkit-border-radius: 3px;\n	}\n	\n	.master_list .poll_question {\n		padding-left: 30px;\n	}\n	\n		.master_list .poll_question .title {\n			margin-left: -10px;\n		}\n\n	.master_list .topic_reply {\n		background: #fff;\n		border: 1px solid #aaa;	\n		-webkit-border-radius: 6px;\n		-webkit-box-shadow: 0px 0px 3px rgba(0,0,0,0.1);\n	}\n\n		.topic_reply .post_controls	{\n			background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#ffffff), color-stop(47%,#f6f6f6), color-stop(100%,#ededed)); /* Chrome,Safari4+ */\n		}\n\n		.topic_reply .post_controls a {\n			background: #BECBDB;\n			background: -webkit-gradient(linear, left top, left bottom, from(rgba(190, 203, 219, 0.5)), to(rgba(190, 203, 219, 1.0)), color-stop(0.5, rgba(190, 203, 219, 1)));\n			background: -moz-linear-gradient(left, rgba(190, 203, 219, 0.5), rgba(190, 203, 219, 1.0));\n			border: 1px solid rgba(0,0,0,0.3);\n			color: #222;\n			text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.9);\n			display: inline-block;\n			margin: 2px;\n			padding: 7px 20px;		\n			border-radius: 5px;\n			-moz-border-radius: 5px;\n			-o-border-radius: 5px;\n			-webkit-border-radius: 5px;\n		}\n\n.master_list .topic_reply.moderated,\n.master_list .row.moderated {\n	background: #fbf8f9;\n}\n\n	.master_list .topic_reply.moderated a,\n	.master_list .row.moderated a {\n		color: #742030;\n	}\n\n.master_list .topic_reply.moderated {\n	border-color: #b75a5a;\n}\n\n.master_list .topic_reply.moderated h2.secondary {\n	background: #f1dfe2;\n}\n				\ndiv.touch-row a.title { font-size: 1.2em; }\nh2.touch-row {\n	background: #B6C7DB;\n	background-image: -webkit-gradient(linear, left top, left bottom, from(#8EA3BC), to(#62758B), color-stop(0.5, #8EA3BC));\n	border-bottom: 1px solid #62758B;\n	border-top: 1px solid #62758B;\n}\n\n.touch-row .rowContent { margin-left: 45px; }\n.touch-row-arrow {\n	opacity: 0.4;\n	width: 12px;\n	height: 18px;\n	background: transparent url(http://onlineage2.com/forum/public/style_images/mobile/rarrow.png) no-repeat !important;\n	float: right;\n	display: block;\n	position: relative;\n}\n		\n.no_messages {\n	background: #fff;\n	padding: 10px;\n	text-align: center;\n	color: #a2a2a2;\n	font-size: 14px;\n}		\n		\n.post_rep { float: right; }\n\n.ipsLikeButton_enabled, .ipsLikeButton_disabled {\n	width: 26px;\n	height: 26px;\n	display: block;\n	text-indent: -2000em;\n	position: relative;\n	top: 3px; right: 10px;\n	background-image: url(http://onlineage2.com/forum/public/style_images/mobile/like_unlike.png );\n	background-repeat: no-repeat;\n} 	\n\n	.ipsLikeButton_enabled { background-position: top; }\n	.ipsLikeButton_disabled { background-position: bottom; }\n\nspan.error {\n	color: #8a2020;\n}\n\ninput.error {\n	background: #ffe0e0;\n}\n\n.message {\n	background: #dbf1cc;\n	color: #255c00;\n	text-shadow: 0px 1px 0px rgba(255,255,255,0.7);\n	padding: 10px 10px;\n	text-align: center;\n}\n\n	.message.error { background: #ffe0e0; }\n\n#submit_post {\n	width: auto;\n	padding-left: 10px;\n	padding-right: 10px;\n}\n\n/* Buttons */\n.buttons { padding: 0; text-align: center; }\n.button {\n	background: #3b3a3b; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#3b3a3b), color-stop(100%,#212121)); /* Chrome,Safari4+ */\n	border-radius: 3px;\n	border: 1px solid #3a3e42;\n	-moz-box-shadow: inset 0 1px 0 0 #5c5c5c, 0px 2px 3px rgba(0,0,0,0.2);\n	-webkit-box-shadow: inset 0 1px 0 0 #5c5c5c, 0px 2px 3px rgba(0,0,0,0.2);\n	box-shadow: inset 0 1px 0 0 #5c5c5c, 0px 2px 3px rgba(0,0,0,0.2);\n	color: #fff;\n	text-shadow: 0 -1px 0 #000;\n	font: 300 1.1em/1.3 \"Helvetica Neue\", Helvetica, Arial, sans-serif;\n	margin: 0;\n	padding: 8px 10px;\n	width: 120px;\n	display: inline-block;\n	text-decoration: none;\n}\n\n	.buttons .prev { /*position: absolute; left: 7px;*/float: left;	}\n	.buttons .next { /*position: absolute; right: 7px;*/ float: right; }\n\n.button.secondary {\n	background: #eaeaea; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#eaeaea), color-stop(100%,#c4c4c4)); /* Chrome,Safari4+ */\n	color: #313131;\n	border-color: #acacac;\n	text-shadow: 0 1px 0 #fff;\n	-webkit-box-shadow: inset 0 1px 0 0 #fff;\n	box-shadow: inset 0 1px 0 0 #fff;\n	min-width: 80px;\n	width: auto;\n	padding: 5px 10px;\n	font-size: 13px;\n}\n\n.buttons .page-button { 	\n	background: #f7fbfc; /* Old browsers */\n	background: -moz-linear-gradient(top, #f7fbfc 0%, #d9edf2 40%, #c5e4ec 100%); /* FF3.6+ */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#f7fbfc), color-stop(40%,#d9edf2), color-stop(100%,#c5e4ec)); /* Chrome,Safari4+ */\n	-webkit-box-shadow: inset 0 1px 0 0 rgba(255,255,255,0.4), 0px 2px 3px rgba(0,0,0,0.2);\n	border: 1px solid rgba(0,0,0,0.3);\n	color: #222;\n	text-shadow: 0px 1px 0px rgba(255, 255, 255, 0.9);\n	width: 50px !important;\n	min-width: 0;\n}\n\n.buttons .disabled, .button.disabled\n{\n	background: #eeeeee; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#efefef), color-stop(100%,#c7c7c7)); /* Chrome,Safari4+ */\n	opacity: 1;\n	cursor: default;\n	text-shadow: none;\n	opacity: 0.4;\n	color: #7c7c7c;\n}\n\n.controls {\n	background: #deefff; /* Old browsers */\n	background: -moz-linear-gradient(top, #deefff 0%, #98bede 100%); /* FF3.6+ */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#deefff), color-stop(100%,#98bede));\n	border-top: 1px solid #abc4dc !important;\n	border-bottom: 1px solid #6f96b7 !important;\n	text-align: center;\n}\n\n.controls .buttons { background: transparent !important;}\n\n.submit {\n	background: #f4f4f4; /* Old browsers */\n	background: -moz-linear-gradient(top, #f4f4f4 0%, #dcdcdc 100%); /* FF3.6+ */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#f4f4f4), color-stop(100%,#dcdcdc)); /* Chrome,Safari4+ */\n	text-align: center;\n	border-top: 1px solid #e4e4e4;\n	border-bottom: 1px solid #c8c8c8;\n}\n\n#content .master_list a.input_submit {\n	padding: 5px 20px !important;\n}\n\n.editor textarea { height: 125px; width: 100%; }\n.attach { margin-bottom: 4px; }\n\n/* Member list filters */\n#filter-option {\n	display: inline-block; \n	margin: 5px 0; \n	text-decoration: none !important;\n	text-align: center;\n}\n\n.letter-page strong, .letter-page a, .letter-page a:hover { \n	background: #fff; \n	border: 1px solid #ccc; \n	color: #222;\n	display: inline-block; \n	margin: 5px 0; \n	padding: 10px; \n	text-decoration: none !important;\n	width: 8px;\n	text-align: center;	\n	-webkit-border-radius: 5px;\n	-moz-border-radius: 5px;\n	border-radius: 5px;\n}\n\n.letter-page { margin: 0; }\n.letter-page.all strong, .letter-page.all a { width: 30px; }\n.letter-page.active strong { background: #ddd; }\n\n/* Poll */\n.progress_bar {\n	background-color: #fff;\n	border: 1px solid #d5dde5;\n}\n\n	.progress_bar span {\n		background: #243f5c url(http://onlineage2.com/forum/public/style_images/mobile/gradient_bg.png) repeat-x left 50%;\n		color: #fff;\n		font-size: 0em;\n		font-weight: bold;\n		text-align: center;\n		text-indent: -2000em; /* Safari fix */\n		height: 10px;\n		display: block;\n		overflow: hidden;\n		-webkit-border-radius: 7px;\n	}\n\n	.progress_bar.limit span {\n		background: #b82929 url(http://onlineage2.com/forum/public/style_images/mobile/progressbar_warning.png) repeat-x center;\n	}\n\n	.progress_bar span span {\n		display: none;\n	}\n\n.progress_bar.topic_poll {\n	border: 1px solid #d5dde5;\n	margin-top: 2px;\n	-webkit-border-radius: 8px;\n}\n\n.ipsForm_vertical .ipsField {\n	background: #fff;\n	padding: 10px;\n}\n\n.ipsForm_vertical .ipsField_title {\n	display: block;\n	font-weight: bold;\n	font-size: 14px;\n	margin-bottom: 3px;\n}\n\n.ipsForm_vertical .ipsField_content { }\n\n.ipsForm_vertical .ipsField_checkbox input {\n	float: left;\n	margin-top: 2px;\n}\n\n.ipsForm_vertical .ipsField_checkbox .ipsField_content {\n	margin-left: 20px;\n}\n\n.input_text {\n	font-size: 13px;\n	padding: 4px 3px;\n	border-radius: 2px;\n	border-width: 1px;\n	border-style: solid;\n	border-color: #848484 #c1c1c1 #e1e1e1 #c1c1c1;\n	background: #fff;\n	width: 98%;\n}\n\n.input_text:focus {\n	border-color: #4e4e4e #7c7c7c #a3a3a3 #7c7c7c;\n	-webkit-box-shadow: 0px 0px 5px rgba(0,0,0,0.3);\n	-moz-box-shadow: 0px 0px 5px rgba(0,0,0,0.3);\n	box-shadow: 0px 0px 5px rgba(0,0,0,0.3);\n}\n\n.ipsEditor_textarea {\n	min-height: 100px;\n}\n\n/* Photo resizing */\n.post img {	max-width: 100%; }\nimg.photo {	float: left; width: 50px; height: 50px; }\n\n.topic_reply img.photo {\n	margin: 0;\n	position: absolute;\n	top: 5px;\n	left: 5px;\n	width: 35px;\n	height: 35px;\n}\n\n#member_list img.photo, #notifications img.photo { width: 35px; height: 35px; }\n\n.status_updates .row img {\n	float: left;\n	width: 30px;\n	height: 30px;\n	margin-right: 15px;\n}\n\n/* Filter bar */\n.ipsFilterBar {\n	background: #f2f5f6; /* Old browsers */\n	background: -moz-linear-gradient(top, #f2f5f6 0%, #e3eaed 37%, #c8d7dc 100%); /* FF3.6+ */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#f2f5f6), color-stop(37%,#e3eaed), color-stop(100%,#c8d7dc)); /* Chrome,Safari4+ */\n	border-top: 1px solid #888 !important;\n	border-bottom: 1px solid #888 !important;\n	text-align: center;\n	padding: 0 0px;\n	line-height: 35px;\n}\n	                  \n	.ipsFilterBar > ul { margin: 0; padding: 0; }\n	\n	.ipsFilterBar > ul > li {\n		display: inline-block;\n		float: left;\n	}\n	\n	.ipsFilterBar.two_filters > ul > li { width: 50%; }		\n	.ipsFilterBar.three_filters > ul > li { width: 33.33%; }\n	.ipsFilterBar.four_filters > ul > li { width: 25%; }\n	\n	.ipsFilterBar > ul > li > a {\n		background: #c8d7dc; /* Old browsers */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#9ca6b4), color-stop(36%,#828c95), color-stop(100%,#4a5c67)); /* Chrome,Safari4+ */\n		-webkit-box-shadow: 0px 1px 4px rgba(0,0,0,0.5) inset, 0px 1px 0px rgba(255,255,255,0.8);\n		padding: 4px 15px;\n		-webkit-border-radius: 16px;\n		text-decoration: none;\n		color: #fff;\n		font-size: 13px;\n	}\n	\n		.ipsFilterBar > ul > li.selected a {\n			background: #49c0f0; /* Old browsers */\n			background: -moz-linear-gradient(top, #49c0f0 0%, #2cafe3 100%); /* FF3.6+ */\n			background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#49c0f0), color-stop(100%,#2cafe3)); /* Chrome,Safari4+ */\n			text-shadow: 0px -1px 0 #2cafe3;\n			-webkit-box-shadow: 0px 1px 2px rgba(0,0,0,0.2) inset, 0px 1px 0px rgba(255,255,255,0.8), 0px 0px 8px rgba(141,219,255, 0.9);\n		}\n		\n.ipsFilterPane {\n	position: absolute;\n	width: 90%;\n	left: 5%;\n	top: 20px;\n	background: rgba(0,0,0,0.9);\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#7d7e7d), color-stop(8%,#0e0e0e)); /* Chrome,Safari4+ */\n	-webkit-border-radius: 10px;\n	-webkit-box-shadow: 0px 3px 12px rgba(0,0,0,0.7);\n	border: 1px solid #0e0e0e;\n	z-index: 1000;\n}\n	\n	.ipsFilterPane > div { padding: 10px; }\n	\n	.ipsFilterPane h4 {\n		text-align: center;\n		font-size: 16px;\n		color: #fff;\n		padding: 0 0 10px 0;\n		text-shadow: 0 -1px 0 #0e0e0e;\n	}\n	\n		.ipsFilterPane h5 {\n			font-size: 11px;\n			color: #d1d1d1;\n			text-align: center;\n			text-shadow: 0 -1px 0 #0e0e0e;\n			margin-top: -10px;\n			padding: 0 0 10px 0;\n			font-weight: normal;\n		}\n	\n	.ipsFilterPane ul, .ipsFilterPane_inner { \n		background: #fff;\n		-webkit-border-radius: 6px;\n		position: relative;\n	}\n	\n	.ipsFilterPane li { \n		font-size: 14px;\n		border-top: 1px solid #e9edf1;\n		font-weight: bold;\n	}\n	\n		.ipsFilterPane li.active a, .ipsFilterPane li:focus a {\n			background: url(http://onlineage2.com/forum/public/style_images/mobile/icon_check.png ) no-repeat 10px 13px;\n		}\n		\n		.ipsFilterPane li:active a {\n			background: #5376a0; /* Old browsers */\n			background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#5376a0), color-stop(100%,#385885)); /* Chrome,Safari4+ */\n		}\n\n			.ipsFilterPane li:active a { color: #fff; }\n	\n	.ipsFilterPane a {\n		padding: 10px 10px 10px 30px;\n		display: block;\n		color: #000;\n		text-decoration: none;\n	}\n	\n	.ipsFilterPane .ipsFilterPane_close {\n		position: absolute;\n		top: -5px;\n		right: -5px;\n		background: #000;\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#7d7e7d), color-stop(100%,#0e0e0e)); /* Chrome,Safari4+ */\n		color: #fff;\n		font-size: 16px;\n		border: 2px solid #fff;\n		height: 22px;\n		line-height: 22px;\n		width: 22px;\n		text-align: center;\n		padding: 0;\n		-webkit-border-radius: 22px;\n		box-shadow: 0px 2px 4px rgba(0,0,0,0.4);\n	}\n		\n		.ipsFilterPane .ipsFilterPane_close span {\n			position: relative;\n			top: -1px;\n		}\n	\n#filter-letters { text-align: center; }\n\n#shareStrip { text-align: center;  padding-bottom:4px }\n	#shareStrip .button.secondary { width: auto; }\n	#shareStrip a img { margin-top:-4px; }\n	\n.ipsTagBox_launcher {\n	background: #f6f6f6;\n	background: -moz-linear-gradient(top, #f6f6f6 0%, #e5e5e5 100%); /* firefox */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#f6f6f6), color-stop(100%,#e5e5e5)); /* webkit */\n	-webkit-box-shadow: 0px 1px 0 #fff;\n	color: #616161;\n	height: 26px;\n	line-height: 26px;\n	padding: 0 12px;\n	-moz-border-radius: 20px;\n	-webkit-border-radius: 20px;\n	border-radius: 4px;\n	display: block;\n	text-align: center;\n	text-decoration: none;\n	border: 1px solid #dbdbdb;\n	text-shadow: 0px 1px 0 #fff;\n}\n\n.ipsTagBox { min-height: 200px; }\n.ipsTagBox_editor {\n	position: absolute;\n	bottom: 0px;\n	padding: 10px 0px;\n	background: #f6f6f6;\n	background: -moz-linear-gradient(top, #f6f6f6 0%, #e5e5e5 100%); /* firefox */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#f6f6f6), color-stop(100%,#e5e5e5)); /* webkit */\n	border-top: 1px solid #e5e5e5;\n	width: 100%;\n	-webkit-border-radius: 0 0 6px 6px;\n	-webkit-box-shadow: 0 -1px 5px rgba(0,0,0,0.1);\n	text-align: center;\n}\n	.ipsTagBox_editor .input_text, .ipsTagBox_editor .input_select { width: 70%; }\n	.ipsTagBox_editor .input_select { font-size: 19px !important; }	\n	.ipsTagBox_editor .input_submit {\n		background: #8fc800; /* Old browsers */\n		background: -moz-linear-gradient(top, #8fc800 0%, #5ba000 100%); /* FF3.6+ */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#8fc800), color-stop(100%,#5ba000)); /* Chrome,Safari4+ */\n		border: 1px solid #5ba000;\n		color: #fff;\n		text-shadow: 0px -1px 0 #5ba000;\n		padding: 5px 10px;\n		width: 20%;\n		margin-left: 1%;\n		-webkit-box-shadow: 0px 1px 0px rgba(255,255,255,0.5) inset;\n	}\n	\n	.ipsTagBox_editor input.ipsTagBox_remove {\n		background: #ff3019; /* Old browsers */\n		background: -moz-linear-gradient(top, #ff3019 0%, #cf0404 100%); /* FF3.6+ */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#ff3019), color-stop(100%,#cf0404)); /* Chrome,Safari4+ */\n		text-shadow: 0 -1px 0 #cf0404;\n		border-color: #cf0404;\n		width: 60%;\n	}\n	\n.ipsTagBox_taglist { padding: 5px; }\n.ipsTagBox_taglist li {\n	display: inline-block;\n	padding: 3px 10px;\n	background: #5376a0; /* Old browsers */\n	background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#4774a2), color-stop(100%,#2c5687)); /* Chrome,Safari4+ */\n	border: 1px solid #2c5687;\n	color: #fff;\n	font-size: 12px;\n	font-weight: normal;\n	-webkit-border-radius: 12px;\n	text-shadow: 0px -1px 0 #2c5687;\n	margin: 0 5px 5px 0;\n	-webkit-box-shadow: 0px 1px 0px rgba(255,255,255,0.3) inset;\n}\n\n	.ipsTagBox_taglist li.selected {\n		background: #49c0f0; /* Old browsers */\n		background: -moz-linear-gradient(top, #49c0f0 0%, #2cafe3 100%); /* FF3.6+ */\n		background: -webkit-gradient(linear, left top, left bottom, color-stop(0%,#49c0f0), color-stop(100%,#2cafe3)); /* Chrome,Safari4+ */\n		text-shadow: 0px -1px 0 #2cafe3;\n		border-color: #2cafe3;\n		-webkit-box-shadow: 0px 0px 8px rgba(141,219,255, 0.9);\n		-webkit-transform: scale(1.07);\n	}\n	\n#shade {\n    position: absolute;\n    top: 43px;\n    width: 100%;\n    min-height: 468px;\n    z-index: 2;\n    background: rgba(0, 0, 0, 0.4);\n    padding: 0;\n}\n\n#loadingBox {\n	position: absolute;\n	width: 300px;\n	height: 100px;\n	margin: 0px;\n	z-index: 2;\n    background: rgba(0, 0, 0, 0.75);\n    -webkit-border-radius: 5px;\n	-moz-border-radius: 5px;\n	border-radius: 5px;\n	text-align: center;\n}\n	\n	#loadingBox span {\n		line-height: 100px;\n		color: #fff;\n		font-size: 16px;\n		text-shadow: 0px -1px 0 #000;\n	}\n	\n/* Enforce a smaller recaptcha */\n#recaptcha_area { zoom: 86%; }\n#task { height: 0; line-height: 0; overflow: hidden; }\n/************************************************************************/\n/*  BBCODE STYLES */\n/* 	NOTE: These selectors style bbcodes throughout IPB. It is recommended that you DO NOT change these \n	styles if you are creating a skin since it may interfere with user expectation\n	of what certain BBCodes look like (quote boxes are an exception to this). */\n\nstrong.bbc				{	font-weight: bold !important; }\nem.bbc 					{	font-style: italic !important; }\nspan.bbc_underline 		{ 	text-decoration: underline !important; }\nacronym.bbc 			{ 	border-bottom: 1px dotted #000; }\ndiv.bbc_center 			{	text-align: center; }\ndiv.bbc_left 			{	text-align: left; }\ndiv.bbc_right 			{	text-align: right; }\ndiv.bbc_indent 			{	margin-left: 50px; }\ndel.bbc 				{	text-decoration: line-through !important; }\nul.bbc 					{	list-style: disc outside; margin-left: 30px; }\n	ul.bbc ul.bbc 			{	list-style-type: circle; }\n		ul.bbc ul.bbc ul.bbc 	{	list-style-type: square; }\nul.bbcol.decimal 				{ margin-left: 30px; list-style: decimal outside; }\n	ul.bbcol.lower-alpha		{ margin-left: 30px; list-style: lower-alpha outside; }\n	ul.bbcol.upper-alpha		{ margin-left: 30px; list-style: upper-alpha outside; }\n	ul.bbcol.lower-roman		{ margin-left: 30px; list-style: lower-roman outside; }\n	ul.bbcol.upper-roman		{ margin-left: 30px; list-style: upper-roman outside; }\nhr.bbc 					{ 	display: block; border-top: 2px solid #777; }\ndiv.bbc_spoiler 		{	 }\ndiv.bbc_spoiler span	{ 	font-weight: bold; }\ndiv.bbc_spoiler_wrapper	{ 	border: 1px inset #777; padding: 4px; }\ndiv.bbc_spoiler_content	{ 	 }\ninput.bbc_spoiler_show	{ 	width: 45px; font-size: .7em; margin: 0px; padding: 0px; }\npre.prettyprint 		{ padding: 5px; background: #f8f8f8; border: 1px solid #c9c9c9; overflow: auto; margin-left: 10px; font-size: 11px; line-height: 140%; }\n.bbc_member, .bbc_url	{	color: inherit; }\n\nimg.bbc_img				{ max-width: 100%; }\n\n/* Quote boxes */\np.citation {\n	color: #000;\n	font-size: 0.9em;\n	font-weight: bold;\n	padding: 5px 8px 5px 0;\n}\n\n	div.blockquote {\n		background: #f8f8f8;\n		border: 1px solid #d4d4d4;\n		font-size: 0.9em;\n		margin: 0px;\n		margin-top: 0px;\n		padding: 6px;\n	}\n	\n/* Blog specific */\n.blog_excerpt {\n	margin: 5px 0;\n	line-height: 130%;\n}\n\n/* Status updates */\n.status_updates .row p {\n	margin-left: 45px;\n}', 'setBy', 'appInfo', 'core-0', 'attributes', 'title=\"Main\" media=\"screen\"', 'modules', '');
INSERT INTO `ibf_skin_cache` VALUES ('992', '1338223377', 'phptemplate', '1', 'group', 'skin_profile', '', '', '', 'class skin_profile_1 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n$this->_funcHooks[\'customField__gender\'] = array(\'male\',\'female\',\'nottelling\',\'gender_set\');\n$this->_funcHooks[\'customField__generic\'] = array(\'genericIsArray\');\n$this->_funcHooks[\'customFieldGroup__contact\'] = array(\'cfieldgroups\',\'cf_icon\',\'cf_skype\',\'cf_jabber\',\'cf_website\',\'cf_icq\',\'cf_yahoo\',\'cf_msn\',\'cf_aim\',\'cf_array\',\'contact_field\');\n$this->_funcHooks[\'dnameWrapper\'] = array(\'records\',\'hasDnameHistory\');\n$this->_funcHooks[\'friendsList\'] = array(\'norep\',\'posrep\',\'negrep\',\'repson\',\'weAreSupmod\',\'addfriend\',\'notus\',\'sendpm\',\'blog\',\'gallery\',\'norep\',\'posrep\',\'negrep\',\'repson\',\'loopOnPending\',\'friendsList\',\'friendListPages\',\'tabIsList\',\'tabIsPending\',\'friendListNone\',\'hasFriendsList\',\'friendListPagesBottom\');\n$this->_funcHooks[\'photoEditor\'] = array(\'canHasURL\',\'allowGravatars\',\'hasTwitter\',\'hasFacebook\');\n$this->_funcHooks[\'profileModern\'] = array(\'tabactive\',\'tabs\',\'pcfieldsLoop\',\'pcfieldsOtherLoopCheckInner\',\'pcfieldsOtherLoopCheck2\',\'pcfieldsOtherLoopCheck\',\'pcfieldsOtherLoop\',\'cfields\',\'friendsLoop\',\'visitorismember\',\'visitorismember3\',\'visitoris