INSERT INTO `ibf_skin_cache` VALUES ('999', '1338223377', 'phptemplate', '1', 'group', 'skin_status_like', '', '', '', 'class skin_status_like_1 {\n\n/**\r\n* Construct\r\n*/\r\nfunction __construct( ipsRegistry $registry )\r\n{\r\n	/* Make object */\r\n	$this->registry   =  $registry;\r\n	$this->DB         =  $this->registry->DB();\r\n	$this->settings   =& $this->registry->fetchSettings();\r\n	$this->request    =& $this->registry->fetchRequest();\r\n	$this->lang       =  $this->registry->getClass(\'class_localization\');\r\n	$this->member     =  $this->registry->member();\r\n	$this->memberData =& $this->registry->member()->fetchMemberData();\r\n	$this->cache      =  $this->registry->cache();\r\n	$this->caches     =& $this->registry->cache()->fetchCaches();\r\n	\n\n$this->_funcHooks = array();\n\n\n}\n\n/* -- likeMoreDialogue --*/\nfunction likeMoreDialogue($data, $relId) {\n$IPBHTML = \"\";\n\nif ( ! isset( $this->registry->templateStriping[\'faverave\'] ) ) {\n$this->registry->templateStriping[\'faverave\'] = array( FALSE, \"row1\",\"row2\");\n}\n$IPBHTML .= \"<h3>Liked By</h3>\n<div class=\'general_box likepop\'>\n	\".$this->__f__54262f3389916bdbee577353ac260e76($data,$relId).\"</div>\";\nreturn $IPBHTML;\n}\n\n\nfunction __f__54262f3389916bdbee577353ac260e76($data, $relId)\r\n{\r\n	$_ips___x_retval = \'\';\r\n	$__iteratorCount = 0;\r\n	foreach( $data as $mid => $data )\r\n	{\r\n		\r\n		$__iteratorCount++;\r\n		$_ips___x_retval .= \"\n		<div class=\'\" .  IPSLib::next( $this->registry->templateStriping[\"faverave\"] ) . \"\'>\n			<em class=\'desc\'>Added: \" . $this->registry->getClass(\'class_localization\')->getDate($data[\'like_added\'],\"short\", 0) . \"</em>\n			<img src=\'{$data[\'pp_thumb_photo\']}\' width=\'{$data[\'pp_thumb_width\']}\' height=\'{$data[\'pp_thumb_height\']}\' class=\'photo\' />\n			<div>\n				<strong>{$data[\'members_display_name\']}</strong>\n				<p class=\'desc\'>\n					\" . IPSLib::makeNameFormatted( $data[\'g_title\'], $data[\'g_id\'] ) . \"\n					<br />\n					Joined: \" . $this->registry->getClass(\'class_localization\')->getDate($data[\'joined\'],\"joined\", 0) . \"\n				</p>\n			</div>\n		</div>\n	\n\";\r\n	}\r\n	$_ips___x_retval .= \'\';\r\n	unset( $__iteratorCount );\r\n	return $_ips___x_retval;\r\n}\n\n/* -- likeSetDialogue --*/\nfunction likeSetDialogue($app, $area, $relid, $data) {\n$IPBHTML = \"\";\n$IPBHTML .= \"<h3>{$this->lang->words[\'fave_title\']}</h3>\n<div class=\'general_box\'>\n	<fieldset>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input type=\\\"checkbox\\\" name=\\\"notify\\\" id=\\\"like_notify\\\" class=\\\"input_check\\\" value=\\\"1\\\" />\n				<label for=\\\"like_notify\\\">\" . sprintf($this->lang->words[\'label_notify\'], $data[\'notifyType\'][1]) . \"</label>\n			</li>\n			<li class=\'field\'>\n				<label for=\\\"like_freq\\\">{$this->lang->words[\'label_freq\']}\n					<select name=\\\"freq\\\" id=\\\"like_freq\\\" class=\\\"input_select\\\">\n						\".$this->__f__746d840b27acf7293a4c2e1e43ff043e($app,$area,$relid,$data).\"					</select>\n				</label>		 				\n			</li>\n			<li class=\'field checkbox\'>\n				<input type=\\\"checkbox\\\" name=\\\"anon\\\" id=\\\"like_anon\\\" class=\\\"input_check\\\" value=\\\"1\\\" />\n				<label for=\\\"like_anon\\\">{$this->lang->words[\'label_anon\']}<br /><span class=\'desc\'>{$this->lang->words[\'label_anon_desc\']}</span></label>\n			</li>\n			<li class=\\\"submit\\\" style=\\\"float:right\\\">\n				<input type=\\\"submit\\\" value=\\\"Set Favorite\\\" class=\\\"input_submit _fsubmit\\\" />\n			</li>\n	</fieldset>\n</div>\";\nreturn $IPBHTML;\n}\n\n\nfunction __f__746d840b27acf7293a4c2e1e43ff043e($app, $area, $relid, $data)\r\n{\r\n	$_ips___x_retval = \'\';\r\n	$__iteratorCount = 0;\r\n	foreach( $data[\'frequencies\'] as $freq )\r\n	{\r\n		\r\n		$__iteratorCount++;\r\n		$_ips___x_retval .= \"\n							<option value=\\\"$freq\\\">{$this->lang->words[ \'freq_\' . $freq ]}</option>\n						\n\";\r\n	}\r\n	$_ips___x_retval .= \'\';\r\n	unset( $__iteratorCount );\r\n	return $_ips___x_retval;\r\n}\n\n/* -- likeSummary --*/\nfunction likeSummary($data, $relId, $opts) {\n$IPBHTML = \"\";\n\nif ( ! function_exists( \'parsetemplate\' ) )\n{\n	function parsetemplate( $content=\'\' )\n	{\n		$out = \'\';\n		\n		/* Make sure javascript doesn\'t complain! */\n		$out = str_replace( \'\"\', \"\'\", $content );\n		$out = str_replace( \"\\n\", \'\', $out );\n		$out = str_replace( \"\\t\", \'\', $out );\n		$out = str_replace( \"\\r\", \'\', $out );\n		\n		/* Return the happy HTML */\n		return $out;\n	}\n}\n$template = parsetemplate(\"\" . ( method_exists( $this->registry->getClass(\'output\')->getTemplate(\'status_like\'), \'likeSummaryContents\' ) ? $this->registry->getClass(\'output\')->getTemplate(\'status_like\')->likeSummaryContents($data, $relId, $opts) : \'\' ) . \"\");\n$IPBHTML .= \"\" . $this->registry->getClass(\'output\')->addJSModule(\"like\", \"0\" ) . \"\n<span class=\'ips_like\' data-app=\\\"{$data[\'app\']}\\\" data-area=\\\"{$data[\'area\']}\\\" data-relid=\\\"{$relId}\\\" data-isfave=\\\"{$data[\'iFave\']}\\\">\n	&middot; <a href=\'#\' title=\\\"\" . (($data[\'iFave\']) ? (\"Unlike and stop notifications\") : (\"Like and receive notifications on updates\")) . \"\\\" class=\'ftoggle \" . (($data[\'iFave\']) ? (\" on\") : (\"\")) . \"\" . (($opts[\'button-new-line\']) ? (\" _newline\") : (\"\")) . \"\'>\" . (($data[\'iFave\']) ? (\"Unlike\") : (\"Like\")) . \"</a>\" . (($data[\'totalCount\']>0) ? (\"&nbsp;<a href=\'#\' title=\'More\' class=\'_fmore total_count\'>({$data[\'totalCount\']})</a>\") : (\"\")) . \"\n</span>\n<script type=\\\"text/javascript\\\">	\n	$(\'statusContent-{$relId}\').insert( { bottom: \\\"{$template}\\\" } );\n</script>\";\nreturn $IPBHTML;\n}\n\n/* -- likeSummaryContents --*/\nfunction likeSummaryContents($data, $relId, $opts=array()) {\n$IPBHTML = \"\";\n\n/* Make sure javascript doesn\'t complain! */\n$data[\'formatted\'] = str_replace( \'\"\', \"\'\", $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\n\", \'\', $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\t\", \'\', $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\r\", \'\', $data[\'formatted\'] );\n	\n$template	= \"<div class=\'ips_like\' id=\'like_info_{$relId}\'>{$data[\'formatted\']}</div>\";\n$update		= \"{$data[\'formatted\']}\";\n$IPBHTML .= \"\" . ((IPS_IS_AJAX) ? (\"&middot; <a href=\'#\' title=\\\"\" . (($data[\'iFave\']) ? (\"Unlike and stop notifications\") : (\"Like and receive notifications on updates\")) . \"\\\" class=\'ftoggle \" . (($data[\'iFave\']) ? (\" on\") : (\"\")) . \"\" . (($opts[\'button-new-line\']) ? (\" _newline\") : (\"\")) . \"\'>\" . (($data[\'iFave\']) ? (\"Unlike\") : (\"Like\")) . \"</a>\" . (($data[\'totalCount\']>0) ? (\"&nbsp;<a href=\'#\' title=\'More\' class=\'_fmore total_count\'>({$data[\'totalCount\']})</a>\") : (\"\")) . \"\" . ((!$this->request[\'likesidebar\']) ? (\"<script type=\'text/javascript\'>\n	if( $(\'like_info_{$relId}\') )\n	{\n		\" . (($data[\'formatted\']) ? (\"\n			$(\'like_info_{$relId}\').update( \\\"{$update}\\\" );\n		\") : (\"\n			$(\'like_info_{$relId}\').remove();\n		\")) . \"\n	}\n	else\n	{\n		$(\'statusContent-{$relId}\').insert( { bottom: \\\"{$template}\\\" } );\n	}\n</script>\") : (\"\")) . \"\") : (\"\" . (($data[\'formatted\']&&!$this->request[\'likesidebar\']) ? (\"<div class=\'ips_like\' id=\'like_info_{$relId}\'>{$data[\'formatted\']}</div>\") : (\"\")) . \"\")) . \"\";\nreturn $IPBHTML;\n}\n\n/* -- statusLike --*/\nfunction statusLike($like) {\n$IPBHTML = \"\";\n$IPBHTML .= \"<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ips.like.js\'></script>\n	<style type=\'text/css\'>\n		.status_like { display: inline; }\n		\n		.status_like span.ips_like {\n			display: inline;\n			background: transparent;\n			clear: none;\n			padding: 0;\n			font-size: 1em;\n			line-height: 100%;\n		}\n		\n			.status_like span.ips_like a {\n				border: none;\n				background: transparent;\n				color: #284B72;\n				margin: 0;\n				padding: 0;\n				float: none;\n				font-size: 1em;\n			}\n			\n				.status_like span.ips_like a:hover {\n					background: transparent !important;\n					color: #528f6c;\n				}\n.total_count { display: none !important; }\n\" . (($this->request[\'likesidebar\']==1) ? (\"\n.total_count { display: inline !important; }\n.status_like { font-size: 0.8em; }\n\") : (\"\")) . \"\n	</style>\n<span class=\'status_like\'>{$like}</span>\";\nreturn $IPBHTML;\n}\n\n\n}\n', '', '', '', '', '', '', '');
