INSERT INTO `ibf_skin_templates` VALUES ('7', '0', 'skin_editors', '<!-- RTE ON: $rte_mode -->\n{parse js_module=\"editor\"}\n{parse addtohead=\"{$this->settings[\'css_base_url\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_editor.css\" type=\"importcss\"}\n<!--top-->\n<input type=\'hidden\' name=\'{$editor_id}_wysiwyg_used\' id=\'{$editor_id}_wysiwyg_used\' value=\'0\' />\n<input type=\'hidden\' name=\'editor_ids[]\' value=\'{$editor_id}\' />\n<if test=\"$show_sidebar = IPSCookie::get(\'emoticon_sidebar\')\"></if>\n<div class=\'ips_editor <if test=\"$show_sidebar == \'1\' && $this->settings[\'_remove_emoticons\'] == 0\">with_sidebar</if>\' id=\'editor_{$editor_id}\'>\n	<if test=\"$this->settings[\'_remove_emoticons\'] == 0\">\n		<div class=\'sidebar row1 altrow\' id=\'{$editor_id}_sidebar\' <if test=\"IPSCookie::get(\'emoticon_sidebar\') != \'1\'\">style=\'display: none\'</if>>\n			<h4><img src=\'{$this->settings[\'img_url\']}/close_popup.png\' alt=\'\' id=\'{$editor_id}_close_sidebar\' /><span>{$this->lang->words[\'emoticons_template_title\']}</span></h4>\n			<div id=\'{$editor_id}_emoticon_holder\' class=\'emoticon_holder\'></div>\n			<div class=\'show_all_emoticons\' id=\'{$editor_id}_showall_bar\'>\n				<input type=\'button\' value=\'{$this->lang->words[\'show_all_emotes\']}\' id=\'{$editor_id}_showall_emoticons\' class=\'input_submit emoticons\' />\n			</div>\n		</div>\n	</if>\n	<div id=\'{$editor_id}_controls\' class=\'controls\'>\n		<ul id=\'{$editor_id}_toolbar_1\' class=\'toolbar\' style=\'display: none\'>\n			<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_removeformat\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_noformat\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/remove_formatting.png\' alt=\'{$this->lang->words[\'js_tt_noformat\']}\' /></span>\n			</li>\n			<!--<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_togglesource\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_htmlsource\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/toggle_source.png\' alt=\'{$this->lang->words[\'js_tt_htmlsource\']}\' /></span>\n			</li>-->\n			<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_otherstyles\' class=\'rte_control rte_menu rte_special\' title=\'{$this->lang->words[\'box_other_desc\']}\' style=\'display: none\'>{$this->lang->words[\'box_other\']}</span>\n			</li>\n			<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_fontname\' class=\'rte_control rte_menu rte_font\' title=\'{$this->lang->words[\'box_font_desc\']}\'>{$this->lang->words[\'box_font\']}</span>\n			</li>\n			<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_fontsize\' class=\'rte_control rte_menu rte_fontsize\' title=\'{$this->lang->words[\'box_size_desc\']}\'>{$this->lang->words[\'box_size\']}</span>\n			</li>\n			<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_forecolor\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_font_col\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/font_color.png\' alt=\'{$this->lang->words[\'js_tt_font_col\']}\' /></span>\n			</li>\n			<!--<li class=\'left\'>\n				<span id=\'{$editor_id}_cmd_backcolor\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_back_col\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/background_color.png\' alt=\'{$this->lang->words[\'js_tt_back_col\']}\' /></span>\n			</li>-->\n			\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_spellcheck\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_spellcheck\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/spellcheck.png\' alt=\'{$this->lang->words[\'js_tt_spellcheck\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_r_small\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_resizesmall\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/resize_small.png\' alt=\'{$this->lang->words[\'js_tt_resizesmall\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_r_big\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_resizebig\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/resize_big.png\' alt=\'{$this->lang->words[\'js_tt_resizebig\']}\' /></span>\n			</li>\n			<li class=\'right sep\'>\n				<span id=\'{$editor_id}_cmd_help\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_help\']}\'><a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=legends&amp;do=bbcode\" base=\"public\"}\' title=\'{$this->lang->words[\'js_tt_help\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/help.png\' alt=\'{$this->lang->words[\'js_tt_help\']}\' /></a></span>\n			</li>			\n			<li class=\'right sep\'>\n				<span id=\'{$editor_id}_cmd_undo\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_undo\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/undo.png\' alt=\'{$this->lang->words[\'js_tt_undo\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_redo\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_redo\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/redo.png\' alt=\'{$this->lang->words[\'js_tt_redo\']}\' /></span>\n			</li>\n		</ul>\n		<ul id=\'{$editor_id}_toolbar_2\' class=\'toolbar\' style=\'display: none\'>\n			<li>\n				<span id=\'{$editor_id}_cmd_bold\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_bold\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/bold.png\' alt=\'{$this->lang->words[\'js_tt_bold\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_italic\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_italic\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/italic.png\' alt=\'{$this->lang->words[\'js_tt_italic\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_underline\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_underline\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/underline.png\' alt=\'{$this->lang->words[\'js_tt_underline\']}\' /></span>\n			</li>\n			<li class=\'sep\'>\n				<span id=\'{$editor_id}_cmd_strikethrough\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_strike\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/strike.png\' alt=\'{$this->lang->words[\'js_tt_strike\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_subscript\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_sub\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/subscript.png\' alt=\'{$this->lang->words[\'js_tt_sub\']}\' /></span>\n			</li>\n			<li class=\'sep\'>\n				<span id=\'{$editor_id}_cmd_superscript\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_sup\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/superscript.png\' alt=\'{$this->lang->words[\'js_tt_sup\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_insertunorderedlist\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_list\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/unordered_list.png\' alt=\'{$this->lang->words[\'js_tt_list\']}\' /></span>\n			</li>\n			<li class=\'sep\'>\n				<span id=\'{$editor_id}_cmd_insertorderedlist\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_list\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/ordered_list.png\' alt=\'{$this->lang->words[\'js_tt_list\']}\' /></span>\n			</li>			\n		<if test=\"removeemoticons:|:$this->settings[\'_remove_emoticons\'] == 0\">\n			<li>\n				<span id=\'{$editor_id}_cmd_emoticons\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_emoticons\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/emoticons.png\' alt=\'{$this->lang->words[\'js_tt_emoticons\']}\' /></span>\n			</li>\n		</if>\n			<li>\n				<span id=\'{$editor_id}_cmd_link\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_link\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/link.png\' alt=\'{$this->lang->words[\'js_tt_link\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_image\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_image\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/picture.png\' alt=\'{$this->lang->words[\'js_tt_image\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_email\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_email\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/email.png\' alt=\'{$this->lang->words[\'js_tt_email\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_ipb_quote\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_quote\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/quote.png\' alt=\'{$this->lang->words[\'js_tt_quote\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_ipb_code\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_code\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/code.png\' alt=\'{$this->lang->words[\'js_tt_code\']}\' /></span>\n			</li>\n			<li>\n				<span id=\'{$editor_id}_cmd_media\' class=\'rte_control rte_palette\' title=\'{$this->lang->words[\'js_tt_media\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/media.png\' alt=\'{$this->lang->words[\'js_tt_media\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_justifyright\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_right\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/align_right.png\' alt=\'{$this->lang->words[\'js_tt_right\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_justifycenter\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_center\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/align_center.png\' alt=\'{$this->lang->words[\'js_tt_center\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_justifyleft\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_left\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/align_left.png\' alt=\'{$this->lang->words[\'js_tt_left\']}\' /></span>\n			</li>\n			<li class=\'right sep\'>\n				<span id=\'{$editor_id}_cmd_indent\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_indent\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/indent.png\' alt=\'{$this->lang->words[\'js_tt_indent\']}\' /></span>\n			</li>\n			<li class=\'right\'>\n				<span id=\'{$editor_id}_cmd_outdent\' class=\'rte_control rte_button\' title=\'{$this->lang->words[\'js_tt_outdent\']}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/outdent.png\' alt=\'{$this->lang->words[\'js_tt_outdent\']}\' /></span>\n			</li>\n		</ul>\n	</div>\n	<div id=\'{$editor_id}_wrap\' class=\'editor\'>\n		<textarea name=\"{$form_field}\" class=\"input_rte\" id=\"{$editor_id}_textarea\" rows=\"10\" cols=\"60\" tabindex=\"0\">{$initial_content}</textarea>\n	</div>\n</div>\n	\n<!-- Toolpanes -->\n<script type=\"text/javascript\">\n//<![CDATA[\n$(\'{$editor_id}_toolbar_1\').show();\n$(\'{$editor_id}_toolbar_2\').show();\n// Rikki: Had to remove <form>... </form> because Opera would see </form> and not pass the topic icons / hidden fields properly. Tried \"</\" + \"form>\" but when it is parsed, it had the same affect\nipb.editor_values.get(\'templates\')[\'link\'] = new Template(\"<label for=\'#{id}_url\'>{$this->lang->words[\'js_template_url\']}</label><input type=\'text\' class=\'input_text\' id=\'#{id}_url\' value=\'http://\' tabindex=\'10\' /><label for=\'#{id}_urltext\'>{$this->lang->words[\'js_template_link\']}</label><input type=\'text\' class=\'input_text _select\' id=\'#{id}_urltext\' value=\'{$this->lang->words[\'js_template_default\']}\' tabindex=\'11\' /><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_insert_link\']}\' tabindex=\'12\' />\");\nipb.editor_values.get(\'templates\')[\'image\'] = new Template(\"<label for=\'#{id}_img\'>{$this->lang->words[\'js_template_imageurl\']}</label><input type=\'text\' class=\'input_text\' id=\'#{id}_img\' value=\'http://\' tabindex=\'10\' /><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_insert_img\']}\' tabindex=\'11\' />\");\nipb.editor_values.get(\'templates\')[\'email\'] = new Template(\"<label for=\'#{id}_email\'>{$this->lang->words[\'js_template_email_url\']}</label><input type=\'text\' class=\'input_text\' id=\'#{id}_email\' tabindex=\'10\' /><label for=\'#{id}_emailtext\'>{$this->lang->words[\'js_template_link\']}</label><input type=\'text\' class=\'input_text _select\' id=\'#{id}_emailtext\' value=\'{$this->lang->words[\'js_template_email_me\']}\' tabindex=\'11\' /><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_insert_email\']}\' tabindex=\'12\' />\");\nipb.editor_values.get(\'templates\')[\'media\'] = new Template(\"<label for=\'#{id}_media\'>{$this->lang->words[\'js_template_media_url\']}</label><input type=\'text\' class=\'input_text\' id=\'#{id}_media\' value=\'http://\' tabindex=\'10\' /><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_insert_media\']}\' tabindex=\'11\' />\");\nipb.editor_values.get(\'templates\')[\'generic\'] = new Template(\"<div class=\'rte_title\'>#{title}</div><strong>{$this->lang->words[\'js_template_example\']}</strong><pre>#{example}</pre><label for=\'#{id}_option\' class=\'optional\'>#{option_text}</label><input type=\'text\' class=\'input_text optional\' id=\'#{id}_option\' tabindex=\'10\' /><label for=\'#{id}_text\' class=\'tagcontent\'>#{value_text}</label><textarea class=\'input_text _select tagcontent\' id=\'#{id}_text\' tabindex=\'11\' rows=\'4\' cols=\'30\' style=\'width: 98%\' /></textarea><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_add\']}\' tabindex=\'12\' />\");\nipb.editor_values.get(\'templates\')[\'toolbar\'] = new Template(\"<ul id=\'#{id}_toolbar_#{toolbarid}\' class=\'toolbar\' style=\'display: none\'>#{content}</ul>\");\nipb.editor_values.get(\'templates\')[\'button\'] = new Template(\"<li><span id=\'#{id}_cmd_custom_#{cmd}\' class=\'rte_control rte_button specialitem\' title=\'#{title}\'><img src=\'{$this->settings[\'img_url\']}/rte_icons/#{img}\' alt=\'\' /></span></li>\");\nipb.editor_values.get(\'templates\')[\'menu_item\'] = new Template(\"<li id=\'#{id}_cmd_custom_#{cmd}\' class=\'specialitem clickable\'>#{title}</li>\");\nipb.editor_values.get(\'templates\')[\'togglesource\'] = new Template(\"<fieldset id=\'#{id}_ts_controls\' class=\'submit\' style=\'text-align: left\'><input type=\'button\' class=\'input_submit\' value=\'{$this->lang->words[\'js_template_update\']}\' id=\'#{id}_ts_update\' />&nbsp;&nbsp;&nbsp; <a href=\'#\' id=\'#{id}_ts_cancel\' class=\'cancel\'>{$this->lang->words[\'js_template_cancel_source\']}</a></fieldset>\");\nipb.editor_values.get(\'templates\')[\'emoticons_showall\'] = new Template(\"<input class=\'input_submit emoticons\' type=\'button\' id=\'#{id}_all_emoticons\' value=\'{$this->lang->words[\'show_all_emoticons\']}\' />\");\nipb.editor_values.get(\'templates\')[\'emoticon_wrapper\'] = new Template(\"<h4><span>{$this->lang->words[\'emoticons_template_title\']}</span></h4><div id=\'#{id}_emoticon_holder\' class=\'emoticon_holder\'></div>\");\n// Add smilies into the mix\nipb.editor_values.set( \'show_emoticon_link\', <if test=\"$allow_sidebar\">true<else />false</if> );\nipb.editor_values.set( \'emoticons\', \\$H({ $smilies }) );\nipb.editor_values.set( \'bbcodes\', \\$H({IPSLib::fetchBbcodeAsJson()}) );\nipb.vars[\'emoticon_url\'] = \"{$this->settings[\'emoticons_url\']}\";\nipb.editors[ \'{$editor_id}\' ] = new ipb.editor( \'{$editor_id}\', USE_RTE );\n//]]>\n</script>', 'ips_editor', '$form_field=\"\",$initial_content=\"\",$images_path=\"\",$rte_mode=0,$editor_id=\'ed-0\',$smilies=\'\',$allow_sidebar=1', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('8', '0', 'skin_editors', '<div class=\'clearfix\'>\n	{$pages}\n</div>\n<div>\n	<ul class=\'media_results\'>\n		<if test=\"hasrows:|:count($rows)\">\n			<foreach loop=\"genericmedia:$rows as $row\">\n				<li class=\'result\' onclick=\"return CKEDITOR.plugins.ipsmedia.insert( \'{$row[\'insert\']}\' );\">\n					<if test=\"hasimage:|:$row[\'image\']\">\n							<img src=\'{$row[\'image\']}\' alt=\'\'<if test=\"haswidth:|:$row[\'width\']\"> width=\'{$row[\'width\']}\'</if><if test=\"hasheight:|:$row[\'height\']\"> height=\'{$row[\'height\']}\'</if> style=\'max-width: 80px;\' class=\'media_image\' /><br />\n					</if>\n					\n						<strong>{parse expression=\"IPSText::truncate( $row[\'title\'], 15 )\"}</strong>\n						<if test=\"hasdescription:|:$row[\'desc\']\">\n							<br /><span class=\'desc\'>{parse expression=\"IPSText::truncate( $row[\'desc\'], 15 )\"}</span>\n						</if>\n				</li>\n			</foreach>\n		<else />\n			<li class=\'no_messages\'>\n				{$this->lang->words[\'no_mymedia_rows\']}\n			</li>\n		</if>\n	</ul>\n</div>\n<div class=\'clearfix\'>\n	{$pages}\n</div>', 'mediaGenericWrapper', '$rows, $pages, $app, $plugin', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('9', '0', 'skin_editors', '<h3>{$this->lang->words[\'mymedia_title\']}</h3>\n<div class=\'fixed_inner ipsBox\'>\n	<div id=\'mymedia_inserted\' style=\'display: none\'>{$this->lang->words[\'added_to_editor\']}</div>\n	<div class=\'ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_smallleft clearfix\'>\n		<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\'>\n			<ul id=\'mymedia_tabs\'>\n				<foreach loop=\"mediatabs:$tabs as $tab\">\n					<li id=\'{$tab[\'app\']}_{$tab[\'plugin\']}\'><a href=\'#\' onclick=\"return CKEDITOR.plugins.ipsmedia.loadTab( \'{$tab[\'app\']}\', \'{$tab[\'plugin\']}\' );\">{$tab[\'title\']}</a></li>\n				</foreach>\n			</ul>\n		</div>\n		<div class=\'ipsVerticalTabbed_content ipsLayout_content ipsBox_container\' style=\'position: relative\'>\n			<div class=\'ipsType_small\' id=\'mymedia_toolbar\'>\n				<a href=\'#\' id=\'mymedia_finish\' class=\'ipsButton no_width\' onclick=\"CKEDITOR.plugins.ipsmedia.popup.hide(); return false;\"><img src=\'{$this->settings[\'img_url\']}/accept.png\' /> &nbsp;{$this->lang->words[\'mymedia_finished\']}</a>\n				<input type=\'hidden\' name=\'sharedmedia_search_app\' id=\'sharedmedia_search_app\' value=\'\' />\n				<input type=\'hidden\' name=\'sharedmedia_search_plugin\' id=\'sharedmedia_search_plugin\' value=\'\' />\n				<input type=\'text\' name=\'search_string\' id=\'sharedmedia_search\' value=\"{$this->lang->words[\'start_typing_sms\']}\" size=\'30\' class=\'input_text inactive\' />\n				<input class=\'input_submit\' type=\'button\' id=\'sharedmedia_submit\' value=\'{$this->lang->words[\'search_string_search\']}\' />\n				&nbsp;&nbsp;<a href=\'#\' id=\'sharedmedia_reset\' class=\'ipsType_smaller\'>{$this->lang->words[\'search_string_reset\']}</a>\n			</div>\n			<div id=\'mymedia_content\' class=\'ipsPad\'>\n				{parse template=\"sharedMediaDefault\" group=\"editors\" params=\"\"}\n			</div>\n		</div>\n	</div>\n</div>\n<script type=\'text/javascript\'>\nipb.vars[\'sm_init_value\']	= \"{$this->lang->words[\'start_typing_sms\']}\";\nCKEDITOR.plugins.ipsmedia.searchinit();\n</script>', 'sharedMedia', '$tabs', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('10', '0', 'skin_editors', '<h1 class=\'ipsType_pagetitle\' style=\'text-align: center\'>{$this->lang->words[\'mymedia_title\']}</h1>\n				<h2 class=\'ipsType_subtitle desc\' style=\'text-align: center\'>{$this->lang->words[\'shareable_media_warn\']}</h2>', 'sharedMediaDefault', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('11', '0', 'skin_emails', '<h1 class=\'ipsType_pagetitle\'>{$title}</h1>\n<div class=\'row2 ipsPad rules\'>\n	{$body}\n</div>\n<br />', 'boardRules', '$title=\"\",$body=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('12', '0', 'skin_emails', '<form action=\"{parse url=\"app=forums&amp;module=extras&amp;section=forward\" base=\"public\"}\" method=\"post\" name=\'REPLIER\'>\n	<input type=\"hidden\" name=\"do\" value=\"01\" />\n	<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n	<input type=\"hidden\" name=\"f\" value=\"{$this->request[\'f\']}\" />\n	<input type=\"hidden\" name=\"t\" value=\"{$this->request[\'t\']}\" />\n	<input type=\"hidden\" name=\"url\" value=\"{$this->request[\'url\']}\" />\n	<input type=\"hidden\" name=\"title\" value=\"{$this->request[\'title\']}\" />\n	<input type=\'hidden\' name=\'k\' value=\'{$this->member->form_hash}\' />\n	<if test=\"hasError:|:$msg\">\n		<p class=\'message error\'>{$this->lang->words[ $msg ]}</p><br />\n	<else />\n		<p class=\'message\'>{$this->lang->words[\'email_friend\']}</p><br />\n	</if>\n	\n	<h2 class=\'maintitle\'>{$this->lang->words[\'title\']}</h2>\n	<div class=\'generic_bar\'></div>\n	<div class=\'ipsForm ipsForm_horizontal\'>\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'email_recepient\']}</h3>\n			<ul class=\'ipsPad\'>\n				<if test=\"count($this->caches[\'lang_data\']) == 1\">\n					<input type=\'hidden\' name=\'lang\' value=\'{$this->caches[\'lang_data\'][0][\'lang_id\']}\' />\n				<else />\n					<li class=\'ipsField clear\'>\n						<label for=\'to_lang\' class=\'ipsField_title\'>{$this->lang->words[\'send_lang\']}</label>\n						<p class=\'ipsField_content\'>\n							<select name=\'lang\' class=\'input_select\' id=\'to_lang\'>\n								<foreach loop=\"lang:$this->caches[\'lang_data\'] as $l\">\n									<option value=\'{$l[\'lang_id\']}\' <if test=\"language:|:$l[\'lant_id\'] == $this->memberData[\'language\']\">selected=\'selected\'</if>>{$l[\'lang_title\']}</option>\n								</foreach>\n							</select>\n						</p>\n					</li>\n				</if>\n				<li class=\'ipsField clear\'>\n					<label for=\'to_name\' class=\'ipsField_title\'>{$this->lang->words[\'to_name\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"text\" id=\'to_name\' class=\'input_text\' name=\"to_name\" value=\"{$this->request[\'to_name\']}\" size=\"30\" maxlength=\"100\" />\n					</p>\n				</li>\n				<li class=\'ipsField clear\'>\n					<label for=\'to_email\' class=\'ipsField_title\'>{$this->lang->words[\'to_email\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"text\" id=\'to_email\' class=\'input_text\' name=\"to_email\" value=\"{$this->request[\'to_email\']}\" size=\"30\" maxlength=\"100\" />\n					</p>\n				</li>\n				<li class=\'ipsField clear\'> \n					<label for=\'subject\' class=\'ipsField_title\'>{$this->lang->words[\'subject\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"text\" id=\"subject\" class=\"input_text\" name=\"subject\" value=\"<if test=\"hasSubject:|:$this->request[\'subject\']\">{$this->request[\'subject\']}<else />$title</if>\" size=\"30\" maxlength=\"120\" />\n					</p>\n				</li> 				\n				<li class=\'ipsField clear\'>\n					<label for=\'to_message\' class=\'ipsField_title\'>{$this->lang->words[\'message\']}</label>\n					<p class=\'ipsField_content\'>\n						<textarea id=\'to_message\' cols=\"60\" rows=\"12\" wrap=\"soft\" name=\"message\" class=\"input_text\"><if test=\"hasText:|:$this->request[\'message\']\">{$this->request[\'message\']}<else />$text</if></textarea>\n					</p>\n				</li>\n				<if test=\"hasCaptcha:|:$captchaHTML\">\n					<li class=\'ipsField clear\'>\n						{$captchaHTML}\n					</li>\n				</if>\n			</ul>\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'submit_send\']}\" />\n		</fieldset>\n	</div>\n</form>', 'forward_form', '$title=\"\",$text=\"\",$lang=\"\", $captchaHTML=\'\', $msg=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('13', '0', 'skin_global', '<a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'go_home\']}\' rel=\"home\" accesskey=\'1\'><img src=\'{parse replacement=\"logo_img\"}\' alt=\'{$this->lang->words[\'logo\']}\' /></a>', 'defaultHeader', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('14', '0', 'skin_global', '<form id=\'forum_jump\' action=\'{parse url=\"\" base=\"public\"}\' method=\'get\'>\n		<fieldset>\n			<select name=\'showforum\' id=\'showforumJump\' class=\'input_select\'>\n				<optgroup label=\"{$this->lang->words[\'forum_jump\']}\">\n					<option value=\'0\'>{$this->lang->words[\'forum_home\']}</option>\n					{$html}\n				</optgroup>\n			</select>\n			<if test=\"$this->member->session_type != \'cookie\'\"><input type=\'hidden\' name=\'s\' value=\'{$this->member->session_id}\' /></if>\n			<input type=\'submit\' value=\'{$this->lang->words[\'jmp_go\']}\' class=\'input_submit alt\' id=\'forum_jump_submit\' />\n		</fieldset>\n	</form>', 'forum_jump', '$html', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('15', '0', 'skin_global', '<!DOCTYPE html>\n	<html xml:lang=\"en\" lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\"<if test=\"fbcenabled:|:IPSLib::fbc_enabled() === TRUE || $this->settings[\'fbc_appid\']\"> xmlns:fb=\"http://www.facebook.com/2008/fbml\"</if>>\n	<head>\n		<meta http-equiv=\"content-type\" content=\"text/html; charset={$this->settings[\'gb_char_set\']}\" />\n		<title>{$header_items[\'title\']}<if test=\"pagenumberintitle:|:$header_items[\'page\']\"> {$this->lang->words[\'page_title_page\']} {$header_items[\'page\']}</if></title>\n		<link rel=\"shortcut icon\" href=\'<if test=\"$this->registry->output->isHTTPS\">{$this->settings[\'board_url_https\']}<else />{$this->settings[\'board_url\']}</if>/favicon.ico\' />\n		<link rel=\"image_src\" href=\'{$this->settings[\'meta_imagesrc\']}\' />\n		<script type=\'text/javascript\'>\n		//<![CDATA[\n			jsDebug			= {parse expression=\"intval($this->settings[\'_jsDebug\'])\"}; /* Must come before JS includes */\n			USE_RTE			= <if test=\"userte:|:$this->memberData[\'members_editor_choice\'] == \'rte\'\">1<else />0</if>;\n			DISABLE_AJAX	= parseInt({$this->settings[\'disable_text_ajax\']}); /* Disables ajax requests where text is sent to the DB; helpful for charset issues */\n			inACP			= false;\n			var isRTL		= false;\n			var rtlIe		= \'\';\n			var rtlFull		= \'\';\n		//]]>\n		</script>\n		{parse template=\"includeCSS\" group=\"global\" params=\"$css\"}\n		{parse template=\"includeMeta\" group=\"global\" params=\"$metaTags\"}\n		<meta property=\"og:title\" content=\"{$this->registry->output->encodeMetaTagContent( str_replace( \' - \' . $this->settings[\'board_name\'], \'\', $header_items[\'title\'] ) )}\"/>\n		<meta property=\"og:site_name\" content=\"{$this->registry->output->encodeMetaTagContent( $this->settings[\'board_name\'] )}\"/>\n		<meta property=\"og:image\" content=\"{$this->settings[\'meta_imagesrc\']}\"/>\n		<meta property=\"og:type\" content=\"article\" />\n		<if test=\"isLargeTouch:|:$this->registry->output->isLargeTouchDevice()\">\n		<!--<meta name=\"viewport\" content=\"width=device-width;\">-->\n		</if>\n		<if test=\"isSmallTouch:|:$this->registry->output->isSmallTouchDevice()\">\n		<meta name=\"viewport\" content=\"width=1024px\">\n		</if>\n		{parse template=\"includeJS\" group=\"global\" params=\"$jsModules\"}\n		{parse template=\"includeFeeds\" group=\"global\" params=\"$documentHeadItems\"}\n		{parse template=\"includeRTL\" group=\"global\" params=\"\"}		\n		{parse template=\"includeVars\" group=\"global\" params=\"$header_items\"}\n	</head>\n	<body id=\'ipboard_body\'>\n		<p id=\'content_jump\' class=\'hide\'><a id=\'top\'></a><a href=\'#j_content\' title=\'{$this->lang->words[\'jump_to_content\']}\' accesskey=\'m\'>{$this->lang->words[\'jump_to_content\']}</a></p>\n		<div id=\'ipbwrapper\'>\n			<!-- ::: TOP BAR: Sign in / register or user drop down and notification alerts ::: -->\n			<div id=\'header_bar\' class=\'clearfix\'>\n				<div class=\'main_width\'>\n					<if test=\"accessreports:|:$this->memberData[\'is_mod\'] OR !empty($this->memberData[\'access_report_center\']) || ($this->memberData[\'g_access_cp\'] AND !$this->settings[\'security_remove_acp_link\'])\">\n						<ul id=\'admin_bar\' class=\'ipsList_inline left\'>\n							<if test=\"showacplink:|:$this->memberData[\'g_access_cp\'] AND !$this->settings[\'security_remove_acp_link\']\">\n								<li>\n									<a href=\"{$this->settings[\'_admin_link\']}\" title=\'{$this->lang->words[\'admin_cp\']}\' target=\"_blank\">{$this->lang->words[\'login_to_acp\']}</a>\n								</li>\n							</if>\n							<li><a href=\"{parse url=\"app=core&amp;module=modcp\" base=\"public\"}\" title=\'{$this->lang->words[\'gbl_modcp_link\']}\'>{$this->lang->words[\'gbl_modcp_link\']}</a></li>\n							<if test=\"rclink:|:$this->memberData[\'access_report_center\'] && $this->memberData[\'_cache\'][\'report_num\'] > 0\">\n								<li class=\'active\'>\n									<a href=\"{parse url=\"app=core&amp;module=reports&amp;do=index\" base=\"public\"}\" title=\'{$this->lang->words[\'view_reports\']}\'>{$this->memberData[\'_cache\'][\'report_num\']} {$this->lang->words[\'report_member_bar\']}</a>\n								</li>\n							</if>\n						</ul>\n					</if>\n					<if test=\"memberbox:|:$this->memberData[\'member_id\']\">\n						<div id=\'user_navigation\' class=\'logged_in\'>\n							<ul class=\'ipsList_inline right\'>\n								<if test=\"showInboxNotify:|:! ( ! $this->memberData[\'member_id\'] && $this->settings[\'force_login\'] ) && !($this->settings[\'board_offline\'] && !$this->memberData[\'g_access_offline\'])\">\n									<if test=\"messengerlink:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0\">\n										<li><a data-clicklaunch=\"getInboxList\" id=\'inbox_link\' href=\'{parse url=\"app=members&amp;module=messaging\" base=\"public\"}\' title=\'{$this->lang->words[\'your_messenger\']}\'><if test=\"notifications:|:$this->memberData[\'msg_count_new\']\"><span class=\'ipsHasNotifications\'>{$this->memberData[\'msg_count_new\']}</span></if>&nbsp;</a></li>\n									</if>\n									<li><a data-clicklaunch=\"getNotificationsList\" id=\'notify_link\' href=\"{parse url=\"app=core&amp;module=usercp&amp;area=notificationlog\" base=\"public\"}\" title=\"{$this->lang->words[\'notifications_at_the_top\']}\"><if test=\"notifications:|:$this->memberData[\'notification_cnt\']\"><span class=\'ipsHasNotifications\'>{$this->memberData[\'notification_cnt\']}</span></if>&nbsp;</a></li>\n								</if>\n								<li><a id=\'user_link\' href=\"{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\"  title=\'{$this->lang->words[\'your_profile\']}\'>{$this->memberData[\'members_display_name\']} &nbsp;<span id=\'user_link_dd\'></span></a></li>							\n								<li><a href=\"{parse url=\"app=core&amp;module=global&amp;section=login&amp;do=logout&amp;k={$this->member->form_hash}\" base=\"public\"}\">{$this->lang->words[\'log_out\']}</a></li>								\n								<if test=\"authenticating:|:$this->memberData[\'member_group_id\'] == $this->settings[\'auth_group\']\">\n									<li><a href=\"{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=reval\" base=\"public\"}\" title=\'{$this->lang->words[\'resend_val\']}\'>{$this->lang->words[\'resend_val\']}</a></li>\n								</if>\n							</ul>\n						</div>\n						<!-- ::: USER DROP DOWN MENU ::: -->\n						<div id=\'user_link_menucontent\' class=\'ipsHeaderMenu clearfix boxShadow\' style=\'display: none\'>\n							<a href=\"{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" title=\'{$this->lang->words[\'your_profile\']}\' class=\'ipsUserPhotoLink left\'>\n								<img src=\'{$this->memberData[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$this->memberData[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium photo\' />\n							</a>\n							\n							<div class=\'left\'>\n								<if test=\"canUpdateStatus:|:$this->registry->getClass(\'memberStatus\')->canCreate( $this->memberData ) && !($this->settings[\'board_offline\'] && !$this->memberData[\'g_access_offline\'])\">\n									<form id=\'statusForm\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=new&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}\' method=\'post\'>\n										<input type=\'text\' id=\'statusUpdateGlobal\' name=\'content\' class=\'input_text\' style=\'width: 97%\' /><br />\n										<input type=\'submit\' id=\'statusSubmitGlobal\' class=\'ipsButton_secondary\' value=\'{$this->lang->words[\'global_update_status\']}\' />\n										<if test=\"update:|:(IPSLib::twitter_enabled() OR IPSLib::fbc_enabled() ) AND ( $this->memberData[\'fb_uid\'] OR $this->memberData[\'twitter_id\'] )\">\n											&nbsp;&nbsp;\n											<if test=\"updateTwitter:|:IPSLib::twitter_enabled() AND ( $this->memberData[\'twitter_id\'] )\"><input type=\'checkbox\' id=\'su_TwitterGlobal\' value=\'1\' name=\'su_Twitter\' /> <label for=\'su_TwitterGlobal\' class=\'desc ipsType_smaller\'>Twitter</label></if> &nbsp; \n											<if test=\"updateFacebook:|:IPSLib::fbc_enabled() AND ( $this->memberData[\'fb_uid\'] )\">&nbsp;<input type=\'checkbox\' id=\'su_FacebookGlobal\' value=\'1\' name=\'su_Facebook\' /> <label for=\'su_FacebookGlobal\' class=\'desc ipsType_smaller\'>Facebook</label></if>\n										</if>\n										<br />\n										<hr />\n									</form>\n								</if>\n									<ul id=\'links\'>\n										<li id=\'user_profile\'><a href=\'{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'your_profile\']}\'>{$this->lang->words[\'my_profile\']}</a></li>\n										<li id=\'user_ucp\'><a href=\"{parse url=\"app=core&amp;module=usercp\" base=\"public\"}\" title=\"{$this->lang->words[\'cp_tool_tip\']}\">{$this->lang->words[\'your_cp\']}</a></li>\n										<li id=\'user_content\'><a href=\"{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$this->memberData[\'member_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'my_content_link\']}\">{$this->lang->words[\'my_content_link\']}</a></li>\n										<if test=\"userLikeLink:|:count( IPSLib::getEnabledApplications(\'like\') )\">\n											<li id=\'user_likes\'><a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed\" base=\"public\"}\' title=\'{$this->lang->words[\'your_likes\']}\'>{$this->lang->words[\'your_likes\']}</a></li>\n										</if>\n										<if test=\"nobbyNoMates:|:$this->settings[\'friends_enabled\'] && $this->memberData[\'g_can_add_friends\']\">\n											<li id=\'user_friends\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=list\" base=\"public\"}\' title=\"{$this->lang->words[\'manage_friends\']}\" class=\'manage_friends\'>{$this->lang->words[\'manage_friends\']}</a></li>\n										</if>\n										<li id=\'user_enemies\'><a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=ignoredusers\" base=\"public\"}\' title=\"{$this->lang->words[\'manage_ignored_users\']}\" class=\'manage_enemies\'>{$this->lang->words[\'manage_ignored_users\']}</a></li>\n										<if test=\"bloglink:|:$this->memberData[\'has_blog\'] AND IPSLib::appIsInstalled(\'blog\')\">\n											<li id=\'user_blog\'><a href=\"{parse url=\"app=blog&amp;module=manage\" base=\"public\" template=\"manageblog\" seotitle=\"false\"}\">{$this->lang->words[\'manage_blogs\']}</a></li>\n										</if>\n										<if test=\"pmLink:|:$this->memberData[\'members_disable_pm\'] != 2\">\n											<li id=\'user_pm\'><a href=\"{parse url=\"app=members&module=messaging\" base=\"public\"}\">{$this->lang->words[\'user_dd_go_pm\']}</a></li>\n										</if>\n										<if test=\"gallerylink:|:$this->memberData[\'has_gallery\'] AND IPSLib::appIsInstalled(\'gallery\')\">\n											<li id=\'user_gallery\'><a href=\'{parse url=\"app=gallery&amp;user={$this->memberData[\'member_id\']}\" base=\"public\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"useralbum\"}\' title=\"{$this->lang->words[\'go_to_my_gallery\']}\">{$this->lang->words[\'my_gallery\']}</a></li>\n										</if>\n										<if test=\"nexuslink:|:IPSLib::appIsInstalled(\'nexus\')\">\n											<li id=\'user_nexus\'><a href=\'{parse url=\"app=nexus&amp;module=clients\" base=\"public\"}\' title=\"{$this->lang->words[\'client_area\']}\">{$this->lang->words[\'client_area\']}</a></li>\n										</if>										\n									</ul>\n							</div>\n						</div>\n					<else />\n						<div id=\'user_navigation\' class=\'not_logged_in\'>\n							\n							<ul class=\'ipsList_inline right\'>\n								<li>\n									<span class=\'services\'>\n										<if test=\"limFacebook:|:IPSLib::loginMethod_enabled(\'facebook\')\">\n											<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;serviceClick=facebook\" base=\"public\"}\'>{parse replacement=\"lim_facebook\"}</a>\n										</if>\n										<if test=\"limTwitter:|:IPSLib::loginMethod_enabled(\'twitter\')\">\n											<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;serviceClick=twitter\" base=\"public\"}\'>{parse replacement=\"lim_twitter\"}</a>\n										</if>\n										<if test=\"limOpenid:|:IPSLib::loginMethod_enabled(\'openid\')\">\n											<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;serviceClick=openid\" base=\"public\"}\'>{parse replacement=\"lim_openid\"}</a>\n										</if>\n										<if test=\"limWindows:|:IPSLib::loginMethod_enabled(\'live\')\">\n											<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;serviceClick=live\" base=\"public\"}\'>{parse replacement=\"lim_windows\"}</a>\n										</if>\n									</span>\n									&nbsp;&nbsp;&nbsp;&nbsp;\n									<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login\" base=\"public\"}\' title=\'{$this->lang->words[\'sign_in\']}\' id=\'sign_in\' <if test=\"IPS_APP_COMPONENT == \'ccs\'\">class=\'no_ajax\'</if>>{$this->lang->words[\'sign_in\']}</a>&nbsp;&nbsp;&nbsp;\n								</li>\n								<li>\n									<a href=\"{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\" title=\'{$this->lang->words[\'register\']}\' id=\'register_link\'>{$this->lang->words[\'register\']}</a>\n								</li>\n							</ul>\n						</div>\n					</if>\n				</div>\n			</div>\n			<!-- ::: BRANDING STRIP: Logo and search box ::: -->\n			<div id=\'branding\'>\n				<div class=\'main_width\'>\n					<div id=\'logo\'>\n						<if test=\"brandingBar:|:ipsRegistry::$applications[ $this->registry->getCurrentApplication() ][\'hasCustomHeader\']\">\n							{parse template=\"overwriteHeader\" group=\"{current_app}_global\" params=\"\"}\n						<else />\n							{parse template=\"defaultHeader\" group=\"global\" params=\"\"}\n						</if>\n					</div>\n					{parse template=\"quickSearch\" group=\"global\" params=\"\"}\n				</div>\n			</div>\n			<!-- ::: APPLICATION TABS ::: -->\n			<div id=\'primary_nav\' class=\'clearfix\'>\n				<div class=\'main_width\'>\n					<ul class=\'ipsList_inline\' id=\'community_app_menu\'>\n						<if test=\"showQuickNav:|:! ( ! $this->memberData[\'member_id\'] && $this->settings[\'force_login\'] ) && !($this->settings[\'board_offline\'] && !$this->memberData[\'g_access_offline\'])\">\n							<li class=\'right\'>\n								<a href=\"{parse url=\"app=core&amp;module=global&amp;section=navigation&amp;inapp={parse expression=\"IPS_APP_COMPONENT\"}\" base=\"public\"}\" rel=\"quickNavigation\" accesskey=\'9\' id=\'quickNavLaunch\' title=\'{$this->lang->words[\'launch_quicknav\']}\'><span>&nbsp;</span></a>\n							</li>\n						</if>\n						<li id=\'nav_explore\' class=\'right\'>\n							<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=<if test=\"viewnewcontentapp:|:$this->registry->getCurrentApplication() != \'core\' AND IPSLib::appIsSearchable( $this->registry->getCurrentApplication() )\">{$this->registry->getCurrentApplication()}<else />forums</if>\" base=\"public\"}\' accesskey=\'2\'>{$this->lang->words[\'view_new_posts\']}</a>\n						</li>\n						<if test=\"showhomeurl:|:$this->settings[\'home_url\'] AND $this->settings[\'home_name\']\">\n							<li id=\'nav_home\' class=\'left\'><a href=\'{$this->settings[\'home_url\']}\' title=\'{$this->lang->words[\'homepage_title\']}\' rel=\"home\">{$this->settings[\'home_name\']}</a></li>\n						</if>\n						{parse variable=\"forumActive\" default=\"\" oncondition=\"IPS_APP_COMPONENT == \'forums\'\" value=\"active\"}\n						{parse variable=\"membersActive\" default=\"\" oncondition=\"IPS_APP_COMPONENT == \'members\'\" value=\"active\"}\n						{parse variable=\"helpActive\" default=\"\" oncondition=\"IPS_APP_COMPONENT == \'core\' AND $this->request[\'module\'] == \'help\'\" value=\"active\"}\n						<if test=\"!ipsRegistry::$applications[\'forums\'][\'app_hide_tab\'] && (!count(ipsRegistry::$applications[\'forums\'][\'app_tab_groups\']) OR IPSMember::hasOtherGroups( $this->memberData, ipsRegistry::$applications[\'forums\'][\'app_tab_groups\']) )\"><li id=\'nav_discussion\' class=\'left {parse variable=\"forumActive\"}\'><a href=\'{parse url=\"act=idx\" seotitle=\"false\" base=\"public\"}\' title=\'{$this->lang->words[\'go_to_discussion\']}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li></if>\n						<if test=\"!ipsRegistry::$applications[\'members\'][\'app_hide_tab\'] && (!count(ipsRegistry::$applications[\'members\'][\'app_tab_groups\']) OR IPSMember::hasOtherGroups( $this->memberData, ipsRegistry::$applications[\'members\'][\'app_tab_groups\']) )\"><li id=\'nav_members\' class=\'left {parse variable=\"membersActive\"}\'><a href=\'{parse url=\"app=members&amp;module=list\" base=\"public\" template=\"members_list\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'go_to_memberlist\']}\'>{IPSLib::getAppTitle( \'members\' )}</a></li></if>\n						<if test=\"applicationsloop:|:is_array($header_items[\'applications\']) AND count($header_items[\'applications\'])\">\n							<foreach loop=\"applications:$header_items[\'applications\'] as $data\">\n								<if test=\"showingapp:|:$data[\'app_show\']\">\n									{parse variable=\"appActive\" default=\"\" oncondition=\"$data[\'app_active\']\" value=\"active\"}\n									<li id=\'nav_app_{$data[\'app_dir\']}\' class=\"left {parse variable=\"appActive\"}\"><a href=\'{parse url=\"{$data[\'app_link\']}\" seotitle=\"false\" base=\"public\"}\' title=\'{parse expression=\"sprintf( $this->lang->words[\'go_to_prefix\'], IPSLib::getAppTitle($data[\'app_dir\']) )\"}\'>{IPSLib::getAppTitle($data[\'app_dir\'])}</a></li>\n								</if>\n							</foreach>\n						</if>\n						<li id=\'nav_other_apps\' style=\'display: none\'>\n							<a href=\'#\' class=\'ipbmenu\' id=\'more_apps\'>{$this->lang->words[\'more_apps\']} <img src=\'{$this->settings[\'img_url\']}/useropts_arrow.png\' /></a>\n						</li>\n					</ul>\n				</div>\n				<script type=\'text/javascript\'>\n					if( $(\'primary_nav\') ){	ipb.global.activateMainMenu(); }\n				</script>\n			</div>	\n			\n			<!-- ::: MAIN CONTENT AREA ::: -->\n			<div id=\'content\' class=\'clearfix\'>\n				<!-- ::: NAVIGATION BREADCRUMBS ::: -->\n				<if test=\"count( $items[\'navigation\'] )\">\n					<div id=\'secondary_navigation\' class=\'clearfix\'>\n						<ol class=\'breadcrumb top ipsList_inline left\'>\n							<php>$this->did_first = 0;</php>\n							<if test=\"switchnavigation:|:!$this->settings[\'remove_forums_nav\'] OR ipsRegistry::$current_application == \'forums\'\">\n								<li itemscope itemtype=\"http://data-vocabulary.org/Breadcrumb\">\n									<a href=\'{parse url=\"act=idx\" seotitle=\"false\" base=\"public\"}\' itemprop=\"url\">\n										<span itemprop=\"title\">{$this->settings[\'board_name\']}</span>\n									</a>\n								</li>\n								<if test=\"didfirstnav:|:$this->did_first=1\"></if>\n							</if>\n							<foreach loop=\"navigation:$items[\'navigation\'] as $idx => $data\">\n								<li itemscope itemtype=\"http://data-vocabulary.org/Breadcrumb\">\n									<if test=\"didfirstappnow:|:$this->did_first\"><span class=\'nav_sep\'>{parse replacement=\"f_nav_sep\"}</span></if>\n									 <if test=\"navigationlink:|:$data[1]\"><a href=\'{parse url=\"{$data[1]}\" base=\"$data[4]\" seotitle=\"$data[2]\" template=\"$data[3]\"}\' title=\'{$this->lang->words[\'nav_return_to\']} {$data[0]}\' itemprop=\"url\"></if><span itemprop=\"title\">{$data[0]}</span><if test=\"closenavigationlink:|:$data[1]\"></a></if>\n								</li>\n								<if test=\"forsuredidfirstnav:|:$this->did_first=1\"></if>\n							</foreach>\n						</ol>\n					</div>\n					<br />\n				</if>\n				<noscript>\n					<div class=\'message error\'>\n						<strong>{$this->lang->words[\'gbl_no_js_title\']}</strong>\n						<p>{$this->lang->words[\'gbl_no_js\']}</p>\n					</div>\n					<br />\n				</noscript>\n				<!-- ::: CONTENT ::: -->\n				<if test=\"hasHeaderAd:|:$items[\'adHeaderCode\']\">\n					<div class=\'ipsAd\'>{$items[\'adHeaderCode\']}</div>\n				</if>\n				<if test=\"mainpageContent:|:$html\">{$html}</if>\n				<if test=\"hasFooterAd:|:$items[\'adFooterCode\']\">\n					<div class=\'ipsAd\'>{$items[\'adFooterCode\']}</div>\n				</if>\n				<ol class=\'breadcrumb bottom ipsList_inline left clearfix clear\'>\n					<if test=\"count( $items[\'navigation\'] )\">\n						<php>$this->did_first_bottom = 0;</php>\n						<if test=\"switchnavigation:|:!$this->settings[\'remove_forums_nav\'] OR ipsRegistry::$current_application == \'forums\'\">\n							<li><a href=\'{parse url=\"act=idx\" seotitle=\"false\" base=\"public\"}\'>{$this->settings[\'board_name\']}</a></li>\n							<if test=\"didfirstnav:|:$this->did_first_bottom=1\"></if>\n						</if>\n						<foreach loop=\"navigation:$items[\'navigation\'] as $idx => $data\">\n							<li><if test=\"didfirstappnow:|:$this->did_first_bottom\"><span class=\'nav_sep\'>{parse replacement=\"f_nav_sep\"}</span></if> <if test=\"navigationlink:|:$data[1]\"><a href=\'{parse url=\"{$data[1]}\" base=\"$data[4]\" seotitle=\"$data[2]\" template=\"$data[3]\"}\' title=\'{$this->lang->words[\'nav_return_to\']} {$data[0]}\'></if>{$data[0]}<if test=\"closenavigationlink:|:$data[1]\"></a></if></li>\n							<if test=\"forsuredidfirstnav:|:$this->did_first_bottom=1\"></if>\n						</foreach>\n					<else />\n						<li>&nbsp;</li>\n					</if>\n					<if test=\"siteruleslink:|:$this->settings[\'gl_show\'] and $this->settings[\'gl_title\']\">\n						<li class=\'right ipsType_smaller\'>\n							<a href=\'<if test=\"ruleslink:|:$this->settings[\'gl_link\']\">{$this->settings[\'gl_link\']}<else />{parse url=\"app=forums&amp;module=extras&amp;section=boardrules\" base=\"public\"}</if>\'><if test=\"siterulestitle:|:$this->settings[\'gl_title\']\">{$this->settings[\'gl_title\']}<else />{$this->lang->words[\'board_rules\']}</if></a>\n						</li>\n					</if>	\n				</ol>\n			</div>\n			<!-- ::: FOOTER (Change skin, language, mark as read, etc) ::: -->\n			<div id=\'footer_utilities\' class=\'main_width clearfix clear\'>\n				<a rel=\"nofollow\" href=\'#top\' id=\'backtotop\' title=\'{$this->lang->words[\'go_to_top\']}\'><img src=\'{$this->settings[\'img_url\']}/top.png\' alt=\'\' /></a>\n				<ul class=\'ipsList_inline left\'>\n					<li>\n						<img src=\'{$this->settings[\'img_url\']}/feed.png\' alt=\'{$this->lang->words[\'rss_feed\']}\' id=\'rss_feed\' class=\'clickable\' />\n					</li>\n					<if test=\"skinchanger:|:count($footer_items[\'skin_chooser\']) > 1\">\n						<if test=\"uagentlocked:|:$this->memberData[\'userAgentLocked\'] AND ! $this->memberData[\'userAgentBypass\']\">\n							<li id=\'useragent_msg\'>\n								{$this->lang->words[\'skin_browser_set\']} <a href=\'{parse url=\"{$this->settings[\'query_string_formatted\']}&amp;unlockUserAgent=1\" base=\"public\"}\'>{$this->lang->words[\'override_browser_theme\']}</a>\n							</li>\n						<else />\n						<if test=\"isTouchDevice:|:$this->registry->output->isTouchDevice()\">\n							<li>\n								<a href=\'{parse url=\"{$this->settings[\'query_string_formatted\']}&amp;setAsMobile=1\" base=\"public\"}\'>{$this->lang->words[\'set_mobile_theme\']}</a>\n							</li>\n						</if>\n							<li>\n								<a rel=\"nofollow\" id=\'new_skin\' href=\'#\'>{$this->lang->words[\'change_theme\']}</a>			\n								<ul id=\'new_skin_menucontent\' class=\'ipbmenu_content with_checks\' style=\'display: none\'>\n									<foreach loop=\"$footer_items[\'skin_chooser\'] as $skin\">\n										<li <if test=\"$skin[\'selected\']\">class=\'selected\'</if>>\n											<a href=\'{parse url=\"{$this->settings[\'query_string_formatted\']}&amp;k={$this->member->form_hash}&amp;settingNewSkin={$skin[\'id\']}\" base=\"public\"}\'>{$skin[\'title\']}</a>\n										</li>\n									</foreach>\n								</ul>\n							</li>\n						</if>\n					</if>\n					<if test=\"langchooser:|:count( $footer_items[\'lang_chooser\'][\'options\'] ) > 1\">\n						<li>\n							<a rel=\"nofollow\" href=\'#\' id=\'new_language\'>{$footer_items[\'lang_chooser\'][\'default\']}</a>							\n							<ul id=\'new_language_menucontent\' class=\'ipbmenu_content with_checks\' style=\'display: none\'>\n								<foreach loop=\"$footer_items[\'lang_chooser\'][\'options\'] as $lang\">\n									<li <if test=\"$lang[\'selected\']\">class=\'selected\'</if>>\n										<a href=\"{parse url=\"{$this->settings[\'query_string_formatted\']}&amp;k={$this->member->form_hash}&amp;setlanguage=1&amp;langurlbits={$this->settings[\'query_string_safe\']}&amp;cal_id={$this->request[\'cal_id\']}&amp;langid={$lang[\'id\']}\" base=\"public\"}\">{$lang[\'title\']}</a>\n									</li>\n								</foreach>\n							</ul>\n						</li>\n					</if>\n					<li>\n						<a rel=\"nofollow\" id=\'mark_all_read\' href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=all&amp;k={$this->member->form_hash}\" base=\"public\"}\" title=\'{$this->lang->words[\'mark_all_as_read\']}\'>{$this->lang->words[\'mark_board_as_read\']}</a>\n						<ul id=\'mark_all_read_menucontent\' class=\'ipbmenu_content\' style=\'display: none\'>\n							<foreach loop=\"$footer_items[\'mark_read_apps\'] as $app => $appData\">\n								<li>\n									<if test=\"hideRcForPerms:|:$this->memberData[\'showReportCenter\'] OR $app != \'core\'\">\n										<a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=app&amp;markApp={$app}&amp;k={$this->member->form_hash}\" base=\"public\"}\"><if test=\"isCoreRC:|:$app==\'core\'\">{$this->lang->words[\'markread_rc_link\']}<else />{IPSLib::getAppTitle($app)}</if></a>\n									</if>\n								</li>\n							</foreach>\n							<li>\n								<a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=all&amp;k={$this->member->form_hash}\" base=\"public\"}\"><strong>{$this->lang->words[\'mark_all_as_read\']}</strong></a>\n							</li>\n						</ul>\n					</li>\n					<li>\n						<a href=\"{parse url=\"app=core&amp;module=help\" base=\"public\"}\" title=\'{$this->lang->words[\'view_help\']}\' rel=\"help\" accesskey=\'6\'>{$this->lang->words[\'sj_help\']}</a>\n					</li>				\n				</ul>\n				{$footer_items[\'copyright\']}\n			</div>\n			<if test=\"showdebuglevel:|:$this->memberData[\'member_id\'] and $this->settings[\'debug_level\']\">\n				<div id=\'ipsDebug_footer\'>\n					<strong>{$this->lang->words[\'time_now\']}</strong> {$footer_items[\'time\']}\n					<if test=\"lastvisit:|:$this->memberData[\'member_id\'] AND $this->memberData[\'last_visit\']\"><strong>{$this->lang->words[\'you_last_visit\']}</strong> {parse date=\"$this->memberData[\'last_visit\']\" format=\"short\"}</if>\n					<strong>{$this->lang->words[\'stat_exec\']}</strong> {$stats[\'ex_time\']} <if test=\"isfloat:|:is_float($stats[\'ex_time\'])\">{$this->lang->words[\'stats_sec\']}</if>\n					<strong>{$this->lang->words[\'stat_load\']}</strong> {$stats[\'server_load\']}\n					<strong>{$this->lang->words[\'stat_queries\']}</strong> {$stats[\'queries\']} <if test=\"sqldebuglink:|:IPS_SQL_DEBUG_MODE\"><a href=\'{parse url=\"{$this->settings[\'query_string_safe\']}&amp;debug=1\" base=\"public\"}\'></if>{$this->lang->words[\'stats_queries\']}<if test=\"closesqldebuglink:|:IPS_SQL_DEBUG_MODE\"></a></if>\n					<strong>{$this->lang->words[\'stat_gzip\']}</strong> {$stats[\'gzip_status\']}\n				</div>\n			</if>\n			{$stats[\'task\']}\n			<if test=\"includeLightboxDoReal:|:$this->settings[\'do_include_lightbox_real\']\">\n				{parse template=\"include_lightbox_real\" group=\"global\" params=\"\"}\n			</if>\n		</div>\n		\n		<!--DEBUG_STATS-->\n	</body>\n</html>', 'globalTemplate', '$html, $documentHeadItems, $css, $jsModules, $metaTags, array $header_items, $items=array(), $footer_items=array(), $stats=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('16', '0', 'skin_global', '<script type=\"text/javascript\" src=\"https://apis.google.com/js/plusone.js\"></script>\n<li><div class=\'googlePlusOne\'><g:plusone count=\"false\" size=\"small\"></g:plusone></div></li>', 'googlePlusOneButton', '$url, $title', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('17', '0', 'skin_global', '{parse addtohead=\"{$this->settings[\'css_base_url\']}style_css/prettify.css\" type=\"importcss\"}\n	<script type=\"text/javascript\" src=\"{$this->settings[\'js_base_url\']}js/3rd_party/prettify/prettify.js\"></script>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}js/3rd_party/prettify/lang-sql.js\'></script>\n	<!-- By default we load generic code, php, css, sql and xml/html; load others here if desired -->\n	<script type=\"text/javascript\">\n	//<![CDATA[\n		Event.observe( window, \'load\', function(e){ prettyPrint() });\n	//]]>\n	</script>', 'include_highlighter', '$load_when_needed=0', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('18', '0', 'skin_global', '<php>$this->settings[\'do_include_lightbox_real\'] = 1;</php>', 'include_lightbox', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('19', '0', 'skin_global', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/lightbox.js\'></script>\n<script type=\'text/javascript\'>\n//<![CDATA[\n	// Lightbox Configuration\n	LightboxOptions = Object.extend({\n	    fileLoadingImage:        \'{$this->settings[\'img_url\']}/lightbox/loading.gif\',     \n	    fileBottomNavCloseImage: \'{$this->settings[\'img_url\']}/lightbox/closelabel.gif\',\n	    overlayOpacity: 0.8,   // controls transparency of shadow overlay\n	    animate: true,         // toggles resizing animations\n	    resizeSpeed: 7,        // controls the speed of the image resizing animations (1=slowest and 10=fastest)\n	    borderSize: 10,         //if you adjust the padding in the CSS, you will need to update this variable\n		// When grouping images this is used to write: Image # of #.\n		// Change it for non-english localization\n		labelImage: \"{$this->lang->words[\'lightbox_label\']}\",\n		labelOf: \"{$this->lang->words[\'lightbox_of\']}\"\n	}, window.LightboxOptions || {});\n/* Watch for a lightbox image and set up our downloadbutton watcher */\ndocument.observe(\'click\', (function(event){\n    var target = event.findElement(\'a[rel*=\"lightbox\"]\') || event.findElement(\'area[rel*=\"lightbox\"]\') || event.findElement(\'span[rel*=\"lightbox\"]\');\n    if (target) {\n        event.stop();\n        gbl_addDownloadButton();\n    }\n}).bind(this));\nvar _to    = \'\';\nvar _last  = \'\';\nfunction gbl_addDownloadButton()\n{\n	if ( typeof( ipsLightbox.lightboxImage ) != \'undefined\' && ipsLightbox.lightboxImage.src )\n	{\n		if ( _last != ipsLightbox.lightboxImage.src )\n		{\n			if ( ! $(\'gbl_d\') )\n			{\n				$(\'bottomNav\').insert( { top: \"<div id=\'gbl_d\' style=\'text-align:right;padding-bottom:4px;\'></div>\" } );\n			}\n			\n			$(\'gbl_d\').update( \"<a href=\'\"+ ipsLightbox.lightboxImage.src + \"\' target=\'_blank\'><img src=\'{$this->settings[\'img_url\']}/lightbox/download-icon.png\' /></a>\" );\n			\n			_last = ipsLightbox.lightboxImage.src;\n		}\n	}\n	\n	/* Check for init and then keep checking for new image */\n	_to = setTimeout( \"gbl_addDownloadButton()\", 1000 );\n}\n//]]>\n</script>', 'include_lightbox_real', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('20', '0', 'skin_global', '<if test=\"hasimportcss:|:is_array( $css[\'import\'] )\">\n	<if test=\"minifycss:|:$this->settings[\'use_minify\']\"><php>$this->minify = array();</php></if>\n	<foreach loop=\"cssImport:$css[\'import\'] as $data\">\n		<php>\n			if( $this->settings[\'use_minify\'] AND ( ! $data[\'attributes\'] OR stripos( $data[\'attributes\'], \'screen\' ) !== false ) )\n			{\n				$this->minify[] = \"{$data[\'content\']}\";\n			}\n		</php>\n		<if test=\"donotminifycss:|:!$this->settings[\'use_minify\'] OR ( $data[\'attributes\'] AND stripos( $data[\'attributes\'], \'screen\' ) === false )\">\n			<link rel=\"stylesheet\" type=\"text/css\" {$data[\'attributes\']} href=\"{$data[\'content\']}?ipbv={parse expression=\"trim(ipsRegistry::$vn_full)\"}\" />\n		</if>\n	</foreach>\n	<if test=\"csstominify:|:$this->settings[\'use_minify\'] AND count($this->minify)\">\n		<link rel=\"stylesheet\" type=\"text/css\" media=\'screen,print\' href=\"{$this->settings[\'css_base_url\']}min/index.php?ipbv={parse expression=\"trim(ipsRegistry::$vn_full)\"}&amp;f={parse expression=\"str_replace( $this->settings[\'css_base_url\'], PUBLIC_DIRECTORY . \'/\', implode( \',\', $this->minify ) )\"}\" />\n	</if>\n</if>\n<if test=\"inlinecss:|:is_array( $css[\'inline\'] ) AND count( $css[\'inline\'] )\">\n	<foreach loop=\"cssInline:$css[\'inline\'] as $data\">\n	<style type=\"text/css\" {$data[\'attributes\']}>\n		/* Inline CSS */\n		{$data[\'content\']}\n	</style>\n	</foreach>\n</if>\n<!--[if lte IE 7]>\n	<link rel=\"stylesheet\" type=\"text/css\" title=\'Main\' media=\"screen\" href=\"{$this->settings[\'css_base_url\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_ie.css\" />\n<![endif]-->\n<!--[if lte IE 8]>\n	<style type=\'text/css\'>\n		.ipb_table { table-layout: fixed; }\n		.ipsLayout_content { width: 99.5%; }\n	</style>\n<![endif]-->\n<if test=\"$this->settings[\'resize_img_force\']\">\n	<!-- Forces resized images to an admin-defined size -->\n	<style type=\'text/css\'>\n		img.bbc_img {\n			max-width: {$this->settings[\'resize_img_force\']}px !important;\n			max-height: {$this->settings[\'resize_img_force\']}px !important;\n		}\n	</style>\n<else />\n	<style type=\'text/css\'>\n		img.bbc_img { max-width: 100% !important; }\n	</style>\n</if>', 'includeCSS', '$css', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('21', '0', 'skin_global', '<if test=\"hasdocheaditems:|:count($documentHeadItems)\">\n	<foreach loop=\"headitemsType:$documentHeadItems as $type => $idx\">\n		<foreach loop=\"documentHeadItems:$documentHeadItems[ $type ] as $idx => $data\">\n			<if test=\"dhjavascript:|:$type == \'javascript\'\">\n				<script type=\"text/javascript\" src=\"{$data}\" charset=\"<% CHARSET %>\"></script>\n			</if>\n			<if test=\"dhcss:|:$type == \'rss\'\">\n				<link rel=\"alternate\" type=\"application/rss+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n			</if>\n			<if test=\"dhrsd:|:$type == \'rsd\'\">\n				<link rel=\"EditURI\" type=\"application/rsd+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n			</if>\n			<if test=\"dhraw:|:$type == \'raw\'\">\n				{$data}\n			</if>\n		</foreach>\n	</foreach>\n</if>', 'includeFeeds', '$documentHeadItems', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('22', '0', 'skin_global', '<if test=\"minifyjs:|:$this->settings[\'use_minify\']\">\n	<if test=\"remoteloadjs:|:$this->settings[\'remote_load_js\']\">\n		<script type=\'text/javascript\' src=\'<if test=\"usehttpsprototype:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/prototype/1.7/prototype.js\'></script>\n		<script type=\'text/javascript\' src=\'<if test=\"usehttpsscriptaculous:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/scriptaculous/1.8/scriptaculous.js?load=effects,dragdrop,builder\'></script>\n	<else />\n		<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}min/index.php?ipbv={parse expression=\"trim(ipsRegistry::$vn_full)\"}&amp;g=js\'></script>\n	</if>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}min/index.php?ipbv={parse expression=\"trim(ipsRegistry::$vn_full)\"}&amp;charset={$this->settings[\'gb_char_set\']}&amp;f={parse expression=\"PUBLIC_DIRECTORY\"}/js/ipb.js,cache/lang_cache/{$this->lang->lang_id}/ipb.lang.js,{parse expression=\"PUBLIC_DIRECTORY\"}/js/ips.hovercard.js,{parse expression=\"PUBLIC_DIRECTORY\"}/js/ips.quickpm.js<if test=\"hasjsmodules:|:count($jsModules)\">,{parse expression=\"PUBLIC_DIRECTORY\"}/js/ips.{parse expression=\"implode(\'.js,\' . PUBLIC_DIRECTORY . \'/js/ips.\', array_unique( array_keys( $jsModules ) ) )\"}.js</if>\' charset=\'{$this->settings[\'gb_char_set\']}\'></script>\n<else />\n	<if test=\"nominifyremoteloadjs:|:$this->settings[\'remote_load_js\']\">\n		<script type=\'text/javascript\' src=\'<if test=\"nmusehttpsp:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/prototype/1.7/prototype.js\'></script>\n	<else />\n		<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}js/3rd_party/prototype.js\'></script>\n	</if>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}js/ipb.js?ipbv={parse expression=\"trim(ipsRegistry::$vn_full)\"}&amp;load=quickpm,hovercard,{parse expression=\"implode(\',\', array_unique( array_keys( $jsModules ) ) )\"}\'></script>\n	<if test=\"nominifyremoteloadjs2:|:$this->settings[\'remote_load_js\']\">\n		<script type=\'text/javascript\' src=\'<if test=\"nmusehttpss:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/scriptaculous/1.8/scriptaculous.js?load=effects,dragdrop,builder\'></script>\n	<else />\n		<script type=\'text/javascript\' src=\'{$this->settings[\'js_base_url\']}js/3rd_party/scriptaculous/scriptaculous-cache.js\'></script>\n	</if>\n	<script type=\"text/javascript\" src=\'{$this->settings[\'cache_dir\']}lang_cache/{$this->lang->lang_id}/ipb.lang.js\' charset=\'{$this->settings[\'gb_char_set\']}\'></script>\n</if>\n{parse template=\"liveEditJs\" group=\"global\"}\n<if test=\"isLargeTouch:|:$this->registry->output->isLargeTouchDevice()\">\n<script type=\"text/javascript\" src=\'{$this->settings[\'js_base_url\']}js/3rd_party/iscroll/iscroll.js\'></script>\n</if>', 'includeJS', '$jsModules', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('23', '0', 'skin_global', '<if test=\"metatags:|:is_array( $metaTags ) AND count( $metaTags )\">\n	<foreach loop=\"metaTags:$metaTags as $tag => $content\">\n		<meta name=\"{$tag}\" content=\"{$content}\" />\n		<if test=\"hasIdentifier:|:$tag == \'identifier-url\'\">\n			<meta name=\"og:url\" content=\"{$content}\" />\n		</if>\n	</foreach>\n</if>', 'includeMeta', '$metaTags', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('24', '0', 'skin_global', '<php>$this->isRtlLang	= false;</php>\n<foreach loop=\"langData:$this->cache->getCache(\'lang_data\') as $data\">\n	<if test=\"checkrtl:|:intval($this->member->language_id) == intval($data[\'lang_id\'])\">\n		<if test=\"isrtl:|:$data[\'lang_isrtl\']\">\n			<if test=\"$this->isRtlLang = true\"></if>\n		</if>\n	</if>\n</foreach>\n<if test=\"importrtlcss:|:$this->isRtlLang AND is_file( DOC_IPS_ROOT_PATH . \'/\' . PUBLIC_DIRECTORY . \'/style_css/\' . $this->registry->output->skin[\'_csscacheid\'] . \'/ipb_rtl.css\' )\">\n	<link rel=\"stylesheet\" type=\"text/css\" media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_rtl.css\" />\n	<script type=\'text/javascript\'>\n		var rtlFull	= \"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_rtl.css\";\n		var isRTL	= true;\n	</script>\n<else />\n	<if test=\"importrtlcss:|:$this->isRtlLang AND is_file( DOC_IPS_ROOT_PATH . \'/\' . PUBLIC_DIRECTORY . \'/style_css/ipb_rtl.css\' )\">\n		<link rel=\"stylesheet\" type=\"text/css\" media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/ipb_rtl.css\" />\n		<script type=\'text/javascript\'>\n			var rtlFull	= \"{$this->settings[\'public_dir\']}style_css/ipb_rtl.css\";\n			var isRTL	= true;\n		</script>\n	</if>\n</if>\n<if test=\"importrtlcss:|:$this->isRtlLang AND is_file( DOC_IPS_ROOT_PATH . \'/\' . PUBLIC_DIRECTORY . \'/style_css/\' . $this->registry->output->skin[\'_csscacheid\'] . \'/ipb_rtl_ie.css\' )\">\n	<!--[if lte IE 7]>\n	<link rel=\"stylesheet\" type=\"text/css\" media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_rtl_ie.css\" />\n	<![endif]-->\n	<script type=\'text/javascript\'>\n		var rtlIe	= \"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_rtl_ie.css\";\n	</script>\n<else />\n	<if test=\"importrtlcss:|:$this->isRtlLang AND is_file( DOC_IPS_ROOT_PATH . \'/\' . PUBLIC_DIRECTORY . \'/style_css/ipb_rtl_ie.css\' )\">\n		<!--[if lte IE 7]>\n		<link rel=\"stylesheet\" type=\"text/css\" media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/ipb_rtl_ie.css\" />\n		<![endif]-->\n		<script type=\'text/javascript\'>\n			var rtlIe	= \"{$this->settings[\'public_dir\']}style_css/ipb_rtl_ie.css\";\n		</script>\n	</if>\n</if>\n<if test=\"hasMemberTopicMax:|:$this->settings[\'member_topic_avatar_max\']\">\n	<!-- Forces topic photo to show without thumb -->\n	<style type=\'text/css\'>\n		.ipsUserPhoto_variable { max-width: {parse expression=\"intval($this->settings[\'member_topic_avatar_max\'])\"}px !important; }\n		<if test=\"RTLMargin:|:$this->isRtlLang\">\n			.post_body { margin-right: {parse expression=\"((intval($this->settings[\'member_topic_avatar_max\']  + 25 ) < 185 ) ? 185 : intval($this->settings[\'member_topic_avatar_max\']  + 25 ) )\"}px !important; }\n		<else />\n			.post_body { margin-left: {parse expression=\"((intval($this->settings[\'member_topic_avatar_max\']  + 25 ) < 185 ) ? 185 : intval($this->settings[\'member_topic_avatar_max\']  + 25 ) )\"}px !important; }\n		</if>\n	</style>\n</if>', 'includeRTL', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('25', '0', 'skin_global', '<script type=\'text/javascript\'>\n	//<![CDATA[\n		/* ---- URLs ---- */\n		ipb.vars[\'base_url\'] 			= \'<if test=\"$this->registry->output->isHTTPS\">{parse expression=\"str_replace( \'http://\', \'https://\', \"{$this->settings[\'js_base\']}\" )\"}<else />{$this->settings[\'js_base\']}</if>\';\n		ipb.vars[\'board_url\']			= \'{$this->settings[\'board_url\']}\';\n		ipb.vars[\'img_url\'] 			= \"{$this->settings[\'img_url\']}\";\n		ipb.vars[\'loading_img\'] 		= \'{$this->settings[\'img_url\']}/loading.gif\';\n		ipb.vars[\'active_app\']			= \'{$this->registry->getCurrentApplication()}\';\n		ipb.vars[\'upload_url\']			= \'{$this->settings[\'upload_url\']}\';\n		/* ---- Member ---- */\n		ipb.vars[\'member_id\']			= parseInt( {$this->memberData[\'member_id\']} );\n		ipb.vars[\'is_supmod\']			= parseInt( {parse expression=\"intval($this->memberData[\'g_is_supmod\'])\"} );\n		ipb.vars[\'is_admin\']			= parseInt( {$this->memberData[\'g_access_cp\']} );\n		ipb.vars[\'secure_hash\'] 		= \'{$this->member->form_hash}\';\n		ipb.vars[\'session_id\']			= \'{$this->member->session_id}\';\n		ipb.vars[\'twitter_id\']			= {parse expression=\"intval($this->memberData[\'twitter_id\'])\"};\n		ipb.vars[\'fb_uid\']				= <if test=\"hasFBCHash:|:$this->memberData[\'fb_token\']\">{parse expression=\"intval($this->memberData[\'fb_uid\'])\"}<else />0</if>;\n		ipb.vars[\'auto_dst\']			= parseInt( {$this->memberData[\'members_auto_dst\']} );\n		ipb.vars[\'dst_in_use\']			= parseInt( {$this->memberData[\'dst_in_use\']} );\n		ipb.vars[\'is_touch\']			= <if test=\"istl:|:$this->registry->output->isLargeTouchDevice()\">\'large\';<else /><if test=\"istm:|:$this->registry->output->isSmallTouchDevice()\">\'small\';<else />false;</if></if>\n		ipb.vars[\'member_group\']		= {parse expression=\"json_encode( array( \'g_mem_info\' => $this->memberData[\'g_mem_info\'] ) )\"}\n		/* ---- cookies ----- */\n		ipb.vars[\'cookie_id\'] 			= \'{$this->settings[\'cookie_id\']}\';\n		ipb.vars[\'cookie_domain\'] 		= \'{$this->settings[\'cookie_domain\']}\';\n		ipb.vars[\'cookie_path\']			= \'{$this->settings[\'cookie_path\']}\';\n		/* ---- Rate imgs ---- */\n		ipb.vars[\'rate_img_on\']			= \'{$this->settings[\'img_url\']}/star.png\';\n		ipb.vars[\'rate_img_off\']		= \'{$this->settings[\'img_url\']}/star_off.png\';\n		ipb.vars[\'rate_img_rated\']		= \'{$this->settings[\'img_url\']}/star_rated.png\';\n		/* ---- Uploads ---- */\n		ipb.vars[\'swfupload_swf\']		= \'{parse url=\"js/3rd_party/swfupload/swfupload.swf\" base=\"public_dir\"}\';\n		ipb.vars[\'swfupload_enabled\']	= <if test=\"canswfupload:|:$this->settings[\'uploadFormType\']\">true<else />false</if>;\n		ipb.vars[\'use_swf_upload\']		= ( \'{$this->memberData[\'member_uploader\']}\' == \'flash\' ) ? true : false;\n		ipb.vars[\'swfupload_debug\']		= false;\n		/* ---- other ---- */\n		ipb.vars[\'highlight_color\']     = \"#ade57a\";\n		ipb.vars[\'charset\']				= \"{$this->settings[\'gb_char_set\']}\";\n		ipb.vars[\'seo_enabled\']			= {parse expression=\"intval($this->settings[\'use_friendly_urls\'])\"};\n		<if test=\"usefurl:|:$this->settings[\'use_friendly_urls\']\">\n		ipb.vars[\'seo_params\']			= {parse expression=\"json_encode($this->registry->getClass(\'output\')->seoTemplates[\'__data__\'])\"};\n		</if>\n		/* Templates/Language */\n		ipb.templates[\'inlineMsg\']		= \"{$header_items[\'inlineMsg\']}\";\n		ipb.templates[\'ajax_loading\'] 	= \"<div id=\'ajax_loading\'><img src=\'{$this->settings[\'img_url\']}/ajax_loading.gif\' alt=\'\" + ipb.lang[\'loading\'] + \"\' /></div>\";\n		ipb.templates[\'close_popup\']	= \"<img src=\'{$this->settings[\'img_url\']}/close_popup.png\' alt=\'x\' />\";\n		ipb.templates[\'rss_shell\']		= new Template(\"<ul id=\'rss_menu\' class=\'ipbmenu_content\'>#{items}</ul>\");\n		ipb.templates[\'rss_item\']		= new Template(\"<li><a href=\'#{url}\' title=\'#{title}\'>#{title}</a></li>\");\n		ipb.templates[\'m_add_friend\']	= new Template(\"<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id=#{id}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a>\");\n		ipb.templates[\'m_rem_friend\']	= new Template(\"<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id=#{id}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a>\");\n		ipb.templates[\'autocomplete_wrap\'] = new Template(\"<ul id=\'#{id}\' class=\'ipb_autocomplete\' style=\'width: 250px;\'></ul>\");\n		ipb.templates[\'autocomplete_item\'] = new Template(\"<li id=\'#{id}\' data-url=\'#{url}\'><img src=\'#{img}\' alt=\'\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />&nbsp;&nbsp;#{itemvalue}</li>\");\n		ipb.templates[\'page_jump\']		= new Template(\"<div id=\'#{id}_wrap\' class=\'ipbmenu_content\'><h3 class=\'bar\'>{$this->lang->words[\'global_page_jump\']}</h3><p class=\'ipsPad\'><input type=\'text\' class=\'input_text\' id=\'#{id}_input\' size=\'8\' /> <input type=\'submit\' value=\'{$this->lang->words[\'jmp_go\']}\' class=\'input_submit add_folder\' id=\'#{id}_submit\' /></p></div>\");\n		ipb.templates[\'global_notify\'] 	= new Template(\"<div class=\'popupWrapper\'><div class=\'popupInner\'><div class=\'ipsPad\'>#{message} #{close}</div></div></div>\");\n		<if test=\"hasNotification:|:! empty( $header_items[\'notifications\'] )\">\n			ipb.vars[\'notificationData\']          = {$header_items[\'notifications\']};\n			ipb.templates[\'notificationTemplate\'] = new Template( \"<div><h3>#{notify_title}</h3><div class=\'fixed_inner ipsPad row1\'><h4 class=\'ipsType_sectiontitle\'>#{member_PhotoTag} #{title} <span class=\'ipsType_smaller\'>{$this->lang->words[\'by_ucfirst\']} #{member_members_display_name} - #{date_parsed}</span><p class=\'ipsType_smaller right ipsPad_half\'><a href=\'#{url}\'>{parse expression=\"sprintf( $this->lang->words[\'global_pm_read_short\'], \'#{type}\' )\"}</a></p></h4><p class=\'ipsPad_half\'>#{content}</p></div></div>\");\n		</if>\n		\n		ipb.templates[\'header_menu\'] 	= new Template(\"<div id=\'#{id}\' class=\'ipsHeaderMenu boxShadow\'></div>\");\n		<if test=\"autodst:|:$this->memberData[\'members_auto_dst\'] == 1 AND $this->settings[\'time_dst_auto_correction\']\">\n			ipb.global.checkDST();\n		</if>\n		Loader.boot();\n	//]]>\n	</script>', 'includeVars', '$header_items=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('26', '0', 'skin_global', '<if test=\"liveEditOn:|: defined( \'IPS_LIVE_EDIT\') && IPS_LIVE_EDIT\">\n	<script type=\'text/javascript\'>	\n		skingen_imgs = \"{$this->settings[\'public_dir\']}style_extra/skin_creator\";\n		<if test=\"hasSkinData:|: ! empty( $this->registry->output->skinGenSession[\'skin_gen_data\'] )\">\n		var IPS_SKIN_GEN_SAVED_DATA = {parse expression=\"json_encode( $this->registry->output->skinGenSession[\'skin_gen_data\'] )\"};\n		</if>\n	</script>\n	<link rel=\"stylesheet\" href=\"{$this->settings[\'public_dir\']}style_css/skin_creator.css\" type=\"text/css\"  media=\"screen\" />\n	<link rel=\"stylesheet\" href=\"{$this->settings[\'js_base_url\']}js/3rd_party/prototype/colorpicker/css/prototype_colorpicker.css\" type=\"text/css\"  media=\"screen\" />\n	<script type=\"text/javascript\" src=\"{$this->settings[\'js_base_url\']}js/3rd_party/prototype/colorpicker/js/prototype_colorpicker.js\"></script>\n	<script type=\"text/javascript\" src=\"{$this->settings[\'cache_dir\']}skinGenJsonCache.js\"></script>\n	<script type=\"text/javascript\" src=\"{$this->settings[\'js_base_url\']}js/ips.skin_gen.js\"></script>\n</if>', 'liveEditJs', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('27', '0', 'skin_global', '<if test=\"haspages:|:$data[\'totalItems\'] > $data[\'itemsPerPage\']\">\n	<div class=\'left pagination clear\'>\n		<ul class=\'ipsList_inline back forward\'>\n			<if test=\"prevpage:|:$data[\'_hasPrevious\']\">\n				<li class=\'prev\'>\n					<if test=\"useAjaxPrev:|:$data[\'ajaxLoad\']\">\n						<a href=\"#\" onclick=\"return ipb.global.ajaxPagination( \'{$data[\'ajaxLoad\']}\', \'{parse url=\"{$data[\'baseUrl\']}&amp;secure_key={$this->member->form_hash}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] - $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\' );\" title=\"{$this->lang->words[\'tpl_prev\']}\" rel=\'prev\'>{$this->lang->words[\'_larr\']} {$this->lang->words[\'prev\']}</a>\n					<else />\n						<a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] - $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"{$this->lang->words[\'tpl_prev\']}\" rel=\'prev\'>{$this->lang->words[\'_larr\']} {$this->lang->words[\'prev\']}</a>\n					</if>\n				</li>\n			</if>\n			<if test=\"nextpage:|:$data[\'_hasNext\']\">\n				<li class=\'next\'>\n					<if test=\"useAjaxNext:|:$data[\'ajaxLoad\']\">\n						<a href=\"#\" onclick=\"return ipb.global.ajaxPagination( \'{$data[\'ajaxLoad\']}\', \'{parse url=\"{$data[\'baseUrl\']}&amp;secure_key={$this->member->form_hash}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] + $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\' );\" title=\"{$this->lang->words[\'tpl_next\']}\" rel=\'next\'>{$this->lang->words[\'next\']} {$this->lang->words[\'_rarr\']}</a>\n					<else />\n						<a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] + $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"{$this->lang->words[\'tpl_next\']}\" rel=\'next\'>{$this->lang->words[\'next\']} {$this->lang->words[\'_rarr\']}</a>\n					</if>\n				</li>\n			</if>\n		</ul>\n	</div>\n</if>', 'nextPreviousTemplate', '$data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('28', '0', 'skin_global', '<if test=\"haspages:|:$work[\'pages\'] > 1\">\n	<div class=\'pagination clearfix left <if test=\"!$data[\'showNumbers\']\">no_numbers</if>\'>\n		<ul class=\'ipsList_inline back left\'>\n			<if test=\"firstpage:|:1 < ($work[\'current_page\'] - $data[\'dotsSkip\'])\">\n				<li class=\'first\'><a href=\'{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}=0{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\' title=\'{$this->lang->words[\'tpl_gotofirst\']}\' rel=\'start\'>{$this->lang->words[\'_laquo\']} <!--{$this->lang->words[\'ps_first\']}--></a></li>\n			</if>\n			<if test=\"prevpage:|:$work[\'current_page\'] > 1\">\n				<li class=\'prev\'><a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] - $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"{$this->lang->words[\'tpl_prev\']}\" rel=\'prev\'>{$this->lang->words[\'prev\']}</a></li>\n			</if>\n		</ul>\n		<ul class=\'ipsList_inline left pages\'>\n			<if test=\"$this->request[\'module\'] != \'ajax\' AND !$data[\'noDropdown\']\">\n				<li class=\'pagejump clickable pj{$data[\'uniqid\']}\'>\n					<a href=\'#\'>{parse expression=\"sprintf( $this->lang->words[\'tpl_pages\'], $work[\'current_page\'], $work[\'pages\'] )\"} <!--{parse replacement=\"dropdown\"}--></a>\n					<script type=\'text/javascript\'>\n						ipb.global.registerPageJump( \'{$data[\'uniqid\']}\', { url: \"{parse url=\"{$data[\'baseUrl\']}\" template=\"{$data[\'seoTemplate\']}\" seotitle=\"{$data[\'seoTitle\']}\" base=\"{$data[\'base\']}\"}<if test=\"furlinfo:|:$data[\'isFriendly\']\">/</if>\", stKey: \'{$data[\'startValueKey\']}\', perPage: {$data[\'itemsPerPage\']}, totalPages: {$work[\'pages\']}, anchor: \'{$data[\'anchor\']}\' } );\n					</script>\n				</li>\n			<else />\n				<li class=\'pagejump\'>\n					{parse expression=\"sprintf( $this->lang->words[\'tpl_pages\'], $work[\'current_page\'], $work[\'pages\'] )\"}\n				</li>\n			</if>\n			<if test=\"normalpages:|:is_array( $work[\'_pageNumbers\'] ) && count( $work[\'_pageNumbers\'] )\">\n				<foreach loop=\"pagination:$work[\'_pageNumbers\'] as $_real => $_page\">\n					<if test=\"activepage:|:$_real == $data[\'currentStartValue\']\">\n						<li class=\'page active\'>{$_page}</li>\n					<else />\n						<li class=\'page\'><a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={$_real}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"$_page\">{$_page}</a></li>\n					</if>\n				</foreach>\n			</if>\n		</ul>\n		<ul class=\'ipsList_inline forward left\'>\n			<if test=\"nextpage:|:$work[\'current_page\'] < $work[\'pages\']\">\n				<li class=\'next\'><a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( $data[\'currentStartValue\'] + $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"{$this->lang->words[\'tpl_next\']}\" rel=\'next\'>{$this->lang->words[\'next\']}</a></li>\n			</if>\n			<if test=\"lastpage:|:!empty( $work[\'_showEndDots\'] )\">\n				<li class=\'last\'><a href=\"{parse url=\"{$data[\'baseUrl\']}&amp;{$data[\'startValueKey\']}={parse expression=\"intval( ( $work[\'pages\'] - 1 ) * $data[\'itemsPerPage\'] )\"}{$data[\'anchor\']}\" base=\"{$data[\'base\']}\" seotitle=\"{$data[\'seoTitle\']}\" template=\"{$data[\'seoTemplate\']}\"}\" title=\"{$this->lang->words[\'tpl_gotolast\']}\" rel=\'last\'>{$this->lang->words[\'_raquo\']}</a></li>\n			</if>\n		</ul>\n	</div>\n<else />\n	<if test=\"notDisableSinglePage:|:!$data[\'disableSinglePage\']\">\n		<p class=\'pagination no_pages left ipsType_small\'><span>{$this->lang->words[\'page_1_of_1\']}</span></p>\n	</if>\n</if>', 'paginationTemplate', '$work, $data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('29', '0', 'skin_global', '<div id=\'search\' class=\'right\'>\n	<form action=\"{parse url=\"app=core&amp;module=search&amp;do=search&amp;fromMainBar=1\" base=\"public\"}\" method=\"post\" id=\'search-box\' >\n		<fieldset>\n			<label for=\'main_search\' class=\'hide\'>{$this->lang->words[\'sj_search\']}</label>\n			<a href=\'{parse url=\"app=core&amp;module=search&amp;search_in=<if test=\"hasSearchApp:|:isset($this->request[\'search_app\']) AND $this->request[\'search_app\']\">{$this->request[\'search_app\']}<else />{$this->registry->getCurrentApplication()}</if>\" base=\"public\"}\' title=\'{$this->lang->words[\'advanced_search\']}\' accesskey=\'4\' rel=\"search\" id=\'adv_search\' class=\'right\'>{$this->lang->words[\'advanced\']}</a>\n			<span id=\'search_wrap\' class=\'right\'>\n				<input type=\'text\' id=\'main_search\' name=\'search_term\' class=\'inactive\' size=\'17\' tabindex=\'6\' />\n				<span class=\'choice ipbmenu clickable\' id=\'search_options\' style=\'display: none\'></span>\n				<ul id=\'search_options_menucontent\' class=\'ipbmenu_content ipsPad\' style=\'display: none\'>\n					<li class=\'title\'><strong>{$this->lang->words[\'context_search_title\']}</strong></li>\n					<if test=\"inTopic:|:$this->request[\'showtopic\']\">\n						<li class=\'special\'><label for=\'s_topic\' title=\'{$this->lang->words[\'context_search_topic\']}\'><input type=\'radio\' name=\'search_app\' value=\"forums:topic:{$this->request[\'showtopic\']}\" class=\'input_radio\' id=\'s_topic\' checked=\"checked\" /> <strong>{$this->lang->words[\'context_search_topic\']}</strong></label></li>\n					</if>\n					<if test=\"inForum:|:( $this->request[\'showforum\'] AND $this->registry->getClass(\'class_forums\')->forum_by_id[ $this->request[\'showforum\'] ][\'sub_can_post\'] ) || $this->request[\'showtopic\']\">\n						<li class=\'special\'><label for=\'s_forum\' title=\'{$this->lang->words[\'context_search_forum\']}\'><input type=\'radio\' name=\'search_app\' value=\"forums:forum:{$this->request[\'f\']}\" class=\'input_radio\' id=\'s_forum\' <if test=\"!$this->request[\'showtopic\']\">checked=\"checked\"</if> /> <strong>{$this->lang->words[\'context_search_forum\']}</strong></label></li>\n					</if>\n					<if test=\"lookElsewhere:|:! in_array( $this->registry->getCurrentApplication(), array( \'forums\', \'members\', \'core\' ) )\">\n						<if test=\"appContextSearch:|:method_exists( $this->registry->output->getTemplate( $this->registry->getCurrentApplication() . \'_global\' ), \'contextSearch\' )\">\n							{parse template=\"contextSearch\" group=\"{current_app}_global\" params=\"\"}\n						</if>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'forums\', \'search\' )\">\n						<li class=\'app\'><label for=\'s_forums\' title=\'{IPSLib::getAppTitle(\'forums\')}\'><input type=\'radio\' name=\'search_app\' class=\'input_radio\' id=\'s_forums\' value=\"forums\" <if test=\"inThisApp:|:( ( isset($this->request[\'search_app\']) AND $this->request[\'search_app\'] == \'forums\' ) ) || ( !IPSLib::appIsSearchable( $this->registry->getCurrentApplication(), \'search\' ) ) || ( ( $this->registry->getCurrentApplication() == \'forums\' ) && ! $this->request[\'search_app\'] ) && !$this->request[\'showtopic\'] && !$this->request[\'showforum\']\">checked=\"checked\"</if> />{IPSLib::getAppTitle( \'forums\' )}</label></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'members\', \'search\' )\">\n						<li class=\'app\'><label for=\'s_members\' title=\'{IPSLib::getAppTitle(\'members\')}\'><input type=\'radio\' name=\'search_app\' class=\'input_radio\' id=\'s_members\' value=\"members\" <if test=\"inThisApp:|:( ( isset($this->request[\'search_app\']) AND $this->request[\'search_app\'] == \'members\' ) ) || ( ( $this->registry->getCurrentApplication() == \'members\' ) && ! $this->request[\'search_app\'] ) && !$this->request[\'showtopic\'] && !$this->request[\'showforum\']\">checked=\"checked\"</if> />{IPSLib::getAppTitle( \'members\' )}</label></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'core\', \'search\' )\">\n						<li class=\'app\'><label for=\'s_core\' title=\'{IPSLib::getAppTitle(\'core\')}\'><input type=\'radio\' name=\'search_app\' class=\'input_radio\' id=\'s_core\' value=\"core\" <if test=\"inThisApp:|:( ( isset($this->request[\'search_app\']) AND $this->request[\'search_app\'] == \'core\' ) ) || ( ( $this->registry->getCurrentApplication() == \'core\' ) && ! $this->request[\'search_app\'] ) && !$this->request[\'showtopic\'] && !$this->request[\'showforum\']\">checked=\"checked\"</if> />{IPSLib::getAppTitle( \'core\' )}</label></li>\n					</if>\n					<foreach loop=\"appLoop:$this->registry->getApplications() as $app => $data\">\n						<if test=\"IPSLib::appIsSearchable( $app, \'search\' ) AND !in_array( $app, array( \'forums\', \'members\', \'core\' ) )\">\n							<li class=\'app\'><label for=\'s_{$app}\' title=\'{IPSLib::getAppTitle( $app )}\'><input type=\'radio\' name=\'search_app\' class=\'input_radio\' id=\'s_{$app}\' value=\"{$app}\" <if test=\"inThisApp:|:( ( isset($this->request[\'search_app\']) AND $this->request[\'search_app\'] == $app ) || ( !IPSLib::appIsSearchable( $this->registry->getCurrentApplication(), \'search\' ) AND $app == \'core\' ) || ( ( $this->registry->getCurrentApplication() == $app ) && ( !isset($this->request[\'search_app\']) OR !$this->request[\'search_app\'] ) ) ) && !$this->request[\'showtopic\'] && !$this->request[\'showforum\'] && ( !method_exists( $this->registry->output->getTemplate( $this->registry->getCurrentApplication() . \'_global\' ), \'contextSearch\' ) or ipsRegistry::$appSearch )\">checked=\"checked\"</if> />{IPSLib::getAppTitle( $app )}</label></li>\n						</if>\n					</foreach>\n				</ul>\n				<input type=\'submit\' class=\'submit_input clickable\' value=\'{$this->lang->words[\'sj_search\']}\' />\n			</span>\n			\n		</fieldset>\n	</form>\n</div>', 'quickSearch', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('30', '0', 'skin_global', '{parse js_module=\"sharelinks\"}\n<if test=\"gotLinks:|:is_array( $links )\">\n	<ul class=\'{$cssClass} shareButtons ipsList_inline\'>\n	<foreach loop=\"cacheLoop:$links as $id => $data\">\n		<if test=\"isEnabled:|:$data[\'share_enabled\']\">\n			<if test=\"hasCustom:|:$data[\'customOutput\'] and is_array( $data[\'customOutput\'] )\">\n				{parse expression=\"$this->registry->output->getTemplate($data[\'customOutput\'][0])->$data[\'customOutput\'][1]( $url, $title )\"}\n			<else />\n			<li><a href=\"{parse url=\"sharelink={$data[\'share_key\']};{$data[\'_url\']};{$title}\" base=\"public\"}\" rel=\"nofollow\" target=\"_blank\" title=\"<if test=\"!in_array( $data[\'share_key\'], array( \'print\', \'download\' ) )\">{$this->lang->words[\'gbl_sharelink_with\']} {$data[\'share_title\']}<else />{$this->lang->words[\'gbl_sharelink_with_\' . $data[\'share_key\'] ]}</if>\" class=\'_slink\' id=\'slink_{$data[\'share_key\']}\'><img src=\"{$this->settings[\'public_cdn_url\']}style_extra/sharelinks/{$data[\'share_key\']}.png\" /></a></li>\n			</if>\n		</if>\n	</foreach>\n	</ul>\n	<script type=\"text/javascript\">\n		ipb.sharelinks.url   = \"{parse expression=\"IPSText::base64_decode_urlSafe($url)\"}\";\n		ipb.sharelinks.title = \"{parse expression=\"IPSText::base64_decode_urlSafe( IPSText::htmlspecialchars( $title ) )\"}\";\n		ipb.sharelinks.bname = \"{parse expression=\"trim(addslashes($this->settings[\'board_name\']))\"}\";\n	</script>\n</if>', 'shareLinks', '$links, $title=\'\', $url=\'\', $cssClass=\'topic_share left\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('31', '0', 'skin_global', '<div class=\"signature\" data-memberid=\"{$author_id}\">\n	<if test=\"notMe:|: $this->memberData[\'member_id\'] && $this->memberData[\'member_id\'] != $author_id && $can_ignore\"><a href=\'#\' class=\'hide_signature\'></a></if>\n	{$sig}\n</div>', 'signature_separator', '$sig=\"\", $author_id=0, $can_ignore=true', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('32', '0', 'skin_global', '<if test=\"hasMemberId:|:$member[\'member_id\']\"><a hovercard-ref=\"member\" hovercard-id=\"{$member[\'member_id\']}\" class=\"_hovertrigger url fn\" href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'></if>{$member[\'members_display_name\']}<if test=\"hasMemberIdClose:|:$member[\'member_id\']\"></a></if>', 'userHoverCard', '$member=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('33', '0', 'skin_global', '<div class=\'user_details\'>\n	<ul class=\'basic_info\'>\n		<if test=\"membertitle:|:$author[\'member_title\']\">\n			<p class=\'desc member_title\'>{$author[\'member_title\']}</p>\n		</if>\n		<if test=\"avatar:|:$author[\'member_id\']\">\n			<li class=\'avatar\'>\n				<a href=\"{parse url=\"showuser={$author[\'member_id\']}\" template=\"showuser\" seotitle=\"{$author[\'members_seo_name\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'view_profile\']}\" class=\'ipsUserPhotoLink\'>\n				<if test=\"hasVariable:|:$this->settings[\'member_topic_avatar_max\']\">	\n					<img src=\'{$author[\'pp_main_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_variable\' />\n				<else />\n					<img src=\'{$author[\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_large\' />\n				</if>\n				</a>\n			</li>\n		<else />\n			<li class=\'avatar\'>\n				<img src=\'{$author[\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_large\' />\n			</li>\n		</if>\n		<li class=\'group_title\'>\n			{$author[\'_group_formatted\']}\n		</li>\n		<if test=\"rankimage:|:$author[\'member_rank_img\']\">\n			<li class=\'group_icon\'>\n			<if test=\"rankimageimage:|:$author[\'member_rank_img_i\'] == \'img\'\">\n				<img src=\'{$author[\'member_rank_img\']}\' alt=\'\' />\n			<else />\n				{$author[\'member_rank_img\']}\n			</if>\n			</li>\n		</if>\n		<if test=\"postCount:|:$author[\'member_id\']\">\n		<li class=\'post_count desc lighter\'>\n			{parse expression=\"$this->registry->getClass(\'class_localization\')->formatNumber( intval( $author[\'posts\'] ) )\"} {$this->lang->words[\'m_posts\']}\n		</li>\n		</if>\n	</ul>\n	\n	<if test=\"authorcfields:|:$author[\'custom_fields\'] != \"\"\">\n		<ul class=\'custom_fields\'>\n			<foreach loop=\"customFieldsOuter:$author[\'custom_fields\'] as $group => $data\">\n				<foreach loop=\"customFields:$author[\'custom_fields\'][ $group ] as $field\">\n					<if test=\"$field != \'\'\">\n						<li>\n							{$field}\n						</li>\n					</if>\n				</foreach>\n			</foreach>\n		</ul>\n	</if>	\n		\n	<if test=\"authorwarn:|:$author[\'warn_percent\'] !== NULL\">		\n		<ul>\n			<li>\n				<br />\n				<div class=\'warn_panel clear rounded ipsType_small\'>\n						<strong><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;do=view&amp;mid={$author[\'member_id\']}&amp;_tab=warn\" base=\"public\"}\' id=\'warn_link_{$contentid}_{$author[\'member_id\']}\' title=\'{$this->lang->words[\'warn_view_history\']}\' class=\'warn_link\'>{$this->lang->words[\'warn_status\']}</a></strong>\n					<if test=\"highwarn:|:$author[\'warn_percent\'] >= 80\">\n						<p class=\'progress_bar user_warn limit\' title=\'{$this->lang->words[\'warn_level\']} {$author[\'warn_percent\']}%\'>\n					<else />\n						<p class=\'progress_bar user_warn\' title=\'{$this->lang->words[\'warn_level\']} {$author[\'warn_percent\']}%\'>\n					</if>\n						<span style=\'width: {$author[\'warn_percent\']}%\'><span>{$this->lang->words[\'warn_level\']} {$author[\'warn_percent\']}%</span></span>\n					</p>\n				</div>\n			</li>\n		</ul>\n	</if>\n</div>', 'userInfoPane', '$author, $contentid, $options', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('34', '0', 'skin_global_comments', '<php>\n// Adjust author name as needed\nif( empty($r[\'author\'][\'member_id\']) && !empty($r[\'author\'][\'comment_author_name\']) )\n{\n	$r[\'author\'][\'members_display_name\'] = $r[\'author\'][\'comment_author_name\'];\n}\n</php>\n<if test=\"canEditNoPost:|:!$this->hasEditJs AND !$parent[\'_canComment\'] AND $r[\'comment\'][\'_canEdit\']\">\n	{parse template=\"getEditJs\" group=\"global_comments\" params=\"\"}\n</if>\n<a id=\'comment_{$r[\'comment\'][\'comment_id\']}\'></a>\n<div data-commentid=\'{$r[\'comment\'][\'comment_id\']}\' class=\'ipsComment clearfix <if test=\"commentQueued:|:!$r[\'comment\'][\'comment_approved\']\">moderated</if>\' id=\'comment_id_{$r[\'comment\'][\'comment_id\']}\'>\n	<if test=\"commentignored:|:$r[\'comment\'][\'_ignored\'] || $r[\'comment\'][\'_repignored\']\">\n		<div class=\'post_ignore\'>\n			<if test=\"userIgnoredLang:|:$r[\'comment\'][\'_repignored\'] == 1\">{$this->lang->words[\'comment_ignored_rep\']}<else />{$this->lang->words[\'ignored_comments_not\']}</if> <if test=\"hasauthormemid:|:$r[\'author\'][\'member_id\']\"><a href=\'{parse url=\"showuser={$r[\'author\'][\'member_id\']}\" base=\"public\"}\'></if>{$r[\'author\'][\'members_display_name\']}<if test=\"hasauthormidclose:|:$r[\'author\'][\'member_id\']\"></a></if>. <a href=\'#entry{$r[\'comment\'][\'comment_id\']}\' title=\'{$this->lang->words[\'ignored_comments_not\']}\' style=\'display: none\' id=\'unhide_post_{$r[\'comment\'][\'comment_id\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n		</div>\n	</if>\n	<div class=\'ipsComment_author\'>\n		<if test=\"linkPhotoStart:|:$r[\'author\'][\'member_id\']\"><a class=\'ipsUserPhotoLink\' href=\'{parse url=\"showuser={$r[\'author\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$r[\'author\'][\'members_seo_name\']}\" base=\"public\"}\'></if><img src=\'{$r[\'author\'][\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' /><if test=\"linkPhotoEnd:|:$r[\'author\'][\'member_id\']\"></a></if><br />{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'author\']\"}<br />\n		<span class=\'post_id\'>\n			<a rel=\'bookmark\' class=\'desc lighter ipsType_smaller\' href=\'{parse url=\"app=core&amp;module=global&amp;section=comments&amp;do=findComment&amp;comment_id={$r[\'comment\'][\'comment_id\']}&amp;parentId={$parent[\'parent_id\']}&amp;fromApp={$settings[\'fromApp\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'comment_permalink\']}\'>{parse date=\"$r[\'comment\'][\'comment_date\']\" format=\"short\"}</a>\n		</span>\n	</div>	\n	<div id=\'comment_{$r[\'comment\'][\'comment_id\']}\' class=\'ipsComment_comment\'>\n		<div class=\'comment_content\'>{$r[\'comment\'][\'comment_text\']}</div>\n		\n		<ul class=\'ipsComment_controls ipsList_inline ipsType_smaller\'>\n			<if test=\"moderateCheckbox:|:$parent[\'_canModerate\']\">\n				<li class=\'right\'>&nbsp;&nbsp;<input class=\"ipsComment_mod\" type=\'checkbox\' name=\'\' id=\'mod_comment_id_{$r[\'comment\'][\'comment_id\']}\' /></li>\n			</if>\n			<if test=\"enableRep:|:$settings[\'enableRep\']\">\n				<li class=\'right\'>\n					{parse template=\"repButtons\" group=\"global_other\" params=\"$r[\'author\'], array_merge( array( \'primaryId\' => $r[\'comment\'][\'comment_id\'], \'domLikeStripId\' => \'like_post_\' . $r[\'comment\'][\'comment_id\'], \'domCountId\' => \'rep_comment_\' . $r[\'comment\'][\'comment_id\'], \'app\' => $settings[\'thisApp\'], \'type\' => $settings[\'repType\'], \'likeFormatted\' => $r[\'comment\'][\'like\'][\'formatted\'] ), $r[\'comment\'] )\"}\n				</li>\n			</if>\n			<if test=\"canReply:|:$r[\'comment\'][\'_canReply\']\">\n				<li><a href=\'{$this->settings[\'this_url\']}<if test=\"hasAppend:|:! strstr( $this->settings[\'this_url\'], \'_rcid\')\"><if test=\"hasQ:|:strstr($this->settings[\'this_url\'], \'?\')\">&amp;<else />?</if>_rcid={$r[\'comment\'][\'comment_id\']}</if>#fastreply\' title=\"{$this->lang->words[\'reply_to_comment\']}\" id=\'reply_comment_{$r[\'comment\'][\'comment_id\']}\' class=\'ipsButton_secondary reply_comment\'>{$this->lang->words[\'comment_reply\']}</a></li>\n			</if>\n			<if test=\"canDelete:|:$r[\'comment\'][\'_canDelete\']\">\n				<li>\n					<a href=\'{parse url=\"app=core&amp;module=global&amp;section=comments&amp;do=delete&amp;comment_id={$r[\'comment\'][\'comment_id\']}&amp;parentId={$parent[\'parent_id\']}&amp;fromApp={$settings[\'fromApp\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' id=\'delete_comment_{$r[\'comment\'][\'comment_id\']}\' class=\'delete_comment\' title=\'{$this->lang->words[\'delete_comment\']}\'>{$this->lang->words[\'delete_link\']}</a>\n				</li>\n			</if>\n			<if test=\"canEdit:|:$r[\'comment\'][\'_canEdit\']\">\n				<li>\n					<a href=\"{parse url=\"app=core&amp;module=global&amp;section=comments&amp;do=showEdit&amp;comment_id={$r[\'comment\'][\'comment_id\']}&amp;parentId={$parent[\'parent_id\']}&amp;fromApp={$settings[\'fromApp\']}\" base=\"public\"}\" id=\'edit_comment_{$r[\'comment\'][\'comment_id\']}\' class=\'edit_comment\'>{$this->lang->words[\'edit_link\']}</a>\n				</li>\n			</if>\n			<if test=\"hasReport:|:$r[\'comment\'][\'urls-report\']\">\n				<li>\n					<a href=\"{parse url=\"{$r[\'comment\'][\'urls-report\']}&amp;st={$this->request[\'st\']}\" base=\"public\"}\">{$this->lang->words[\'report_link\']}</a>\n				</li>\n			</if>\n		</ul>\n		\n	</div>\n</div>\n<if test=\"commentinitignored:|:$r[\'comment\'][\'_ignored\'] || $r[\'comment\'][\'_repignored\']\">\n	<script type=\'text/javascript\'>\n		ipb.comments.setCommentHidden( {$r[\'comment\'][\'comment_id\']} );\n	</script>\n</if>', 'comment', '$r, $parent, $settings', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('35', '0', 'skin_global_comments', '<script type=\'text/javascript\'>\n	ipb.templates[\'comment_moderation\'] = new Template(\"<div id=\'comment_moderate_box\' class=\'ipsFloatingAction\' style=\'display: none\'><span class=\'desc\'>{$this->lang->words[\'comment_action_count\']} </span><select name=\'modOptions\' class=\'input_select\' id=\'commentModAction\'><option value=\'approve\'>{$this->lang->words[\'approve_x_comments\']}</option><option value=\'unapprove\'>{$this->lang->words[\'unapprove_x_comments\']}</option><option value=\'delete\'>{$this->lang->words[\'delete_x_comments\']}</option></select>&nbsp;&nbsp;<input type=\'button\' class=\'input_submit\' id=\'submitModAction\' value=\'{$this->lang->words[\'comments_act_go\']}\' /></div>\");\n	\n	ipb.templates[\'comment_delete\'] = new Template(\"<h3>{$this->lang->words[\'comm_confirm_delete\']}</h3><div class=\'ipsPad ipsForm_center desc\'>{$this->lang->words[\'comm_confirm_delete_desc\']}<br /><br /><input type=\'button\' class=\'input_submit\' id=\'delPush\' onclick=\'ipb.comments.deleteIt(event)\' value=\'{$this->lang->words[\'del_comm_now\']}\' />\");\n</script>\n{parse js_module=\"comments\"}\n<a id=\'commentsStart\'></a>\n<if test=\"comments_top:|:$pages\">\n	<div class=\'topic_controls\'>\n		{$pages}\n	</div>\n</if>\n<div class=\'ipsComment_wrap\' id=\'comment_wrap\'>\n	<foreach loop=\"comments:$comments as $id => $r\">\n		{parse template=\"comment\" group=\"global_comments\" params=\"$r, $parent, $settings\"}\n	</foreach>\n</div>\n<if test=\"comments_bottom:|:$pages\">\n	<div class=\'topic_controls\'>\n		{$pages}\n	</div>\n</if>\n<if test=\"allow_comments:|:$parent[\'_canComment\']\">\n	<br />\n	<a id=\"fastreply\"></a>\n	<div id=\'fast_reply\' class=\'ipsComment_reply row2 ipsPad\'>\n		<form action=\"{parse url=\"\" base=\"publicWithApp\"}\" method=\"post\">\n			<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n			<input type=\"hidden\" name=\"fromApp\" value=\"{$settings[\'fromApp\']}\" />\n			<input type=\"hidden\" name=\"app\" value=\"core\" />\n			<input type=\"hidden\" name=\"module\" value=\"global\" />\n			<input type=\"hidden\" name=\"section\" value=\"comments\" />	\n			<input type=\"hidden\" name=\"do\" value=\"add\" />\n			<input type=\"hidden\" name=\"parentId\" value=\"{$parent[\'parent_id\']}\" />\n			<input type=\"hidden\" name=\"fast_reply_used\" value=\"1\" />\n			<div class=\'ipsComment_reply_user\'>\n				<img src=\'{$this->memberData[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'your_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_medium\' />\n			</div>\n			<div id=\'commentReply\' class=\'ipsComment_comment\'>\n				<if test=\"guestName:|:!$this->memberData[\'member_id\']\">\n					<div id=\'commentName\'>\n						<label for=\'comment_name\'>{$this->lang->words[\'yourname_captcha\']}</label> <input type=\'text\' id=\'comment_name\' name=\'comment_name\' class=\'input_text\' />\n						{$this->lang->words[\'or\']} <a href=\'{parse url=\"app=core&amp;module=global&amp;section=login\" base=\"public\"}\' title=\'{$this->lang->words[\'sign_in\']}\' data-clicklaunch=\"inlineSignin\" data-clickscope=\"ipb.global\">{$this->lang->words[\'click_here_to_log_in\']}</a>\n					</div>\n					<if test=\"hasCaptcha:|:$settings[\'captcha\']\">\n						<div id=\'commentCaptcha\' style=\'display:none;\'>\n							{$settings[\'captcha\']}\n						</div>\n					</if>\n				</if>\n				{parse editor=\"Post\" content=\"$preReply\" options=\"array( \'type\' => \'mini\', \'minimize\' => 1, \'autoSaveKey\' => $settings[\'autoSaveKey\'] )\"}\n				<br />\n				<div id=\'commentButtons\'>\n					<input type=\'submit\' name=\"submit\" class=\'input_submit\' id=\'commentPost\' value=\'{$this->lang->words[\'comment_button_post\']}\' tabindex=\'0\' accesskey=\'s\' />\n				</div>\n			</div>\n		</form>\n	</div>\n</if>\n<if test=\"$comments\">\n	<!-- REPUTATION FILTERS -->\n	<if test=\"reputationFilter:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_content\'] && $this->memberData[\'member_id\'] != 0 && is_array($this->caches[\'reputation_levels\'])\">\n		<div id=\'reputation_filter\' class=\'filter_bar rounded\'>\n			<span id=\'show_filters\' class=\'clickable\' style=\'display: none\'>{$this->lang->words[\'rep_f_currently\']} <if test=\"repFilterDefault:|:$this->memberData[\'_members_cache\'][\'rep_filter\'] && $this->memberData[\'_members_cache\'][\'rep_filter\'] === \'*\'\">{$this->lang->words[\'g_rep_f_viewing_all\']} <else />{$this->lang->words[\'g_rep_f_hiding\']} {$this->memberData[\'_members_cache\'][\'rep_filter\']} {$this->lang->words[\'rep_f_points\']}.</if> {$this->lang->words[\'rep_f_threshold\']}</span>\n			<form id=\'filter_form\' method=\"post\" action=\"{parse url=\"\" base=\"public\"}\">\n				<fieldset>\n		 			<input type=\"hidden\" name=\"app\" value=\"gallery\" />\n			 		<input type=\"hidden\" name=\"module\" value=\"images\" />\n			 		<input type=\"hidden\" name=\"section\" value=\"viewimage\" />\n			 		<input type=\"hidden\" name=\"rep_filter\" value=\"update\" />\n					<input type=\"hidden\" name=\"img\" value=\"{$this->request[\'img\']}\" />\n					<input type=\"hidden\" name=\"cat\" value=\"{$this->request[\'cat\']}\" />\n			 		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n			 		<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n			 		<label for=\'rep_filter_select\'>{$this->lang->words[\'rep_f_hide\']}</label>\n			 		<select name=\'rep_filter_set\' id=\'rep_filter_select\'>\n			 			<option value=\'*\' <if test=\"optSelectStar:|:isset( $this->memberData[\'_members_cache\'][\'rep_filter\'] ) AND $this->memberData[\'_members_cache\'][\'rep_filter\'] == \'*\'\"> selected=\'selected\'</if>>{$this->lang->words[\'g_rep_f_all_posts\']}</option>\n					<if test=\"repFilterOptions:|:is_array($this->caches[\'reputation_levels\'])\">\n						<foreach loop=\"reputation_levels:$this->caches[\'reputation_levels\'] as $k => $v\">\n						<option value=\'{$v[\'level_points\']}\'<if test=\"optRepFilterSelected:|:isset( $this->memberData[\'_members_cache\'][\'rep_filter\'] ) AND $v[\'level_points\'] == $this->memberData[\'_members_cache\'][\'rep_filter\']\"> selected=\'selected\'</if>>{$v[\'level_points\']} {$this->lang->words[\'rep_f_points\']}</option>\n						</foreach>\n					</if>\n					</select>\n					<input type=\"submit\" name=\"gobutton\" value=\"{$this->lang->words[\'rep_f_update\']}\" class=\"input_submit alt\" />\n				</fieldset>\n			</form>\n		</div>\n		<script type=\'text/javascript\'>\n			$(\'show_filters\').show();\n		</script>\n	</if>\n</if>\n<script type=\'text/javascript\'>\n	ipb.global.post_width			= 500;\n	document.observe(\"dom:loaded\", function(){\n		ipb.comments.parentId = {parse expression=\"intval( $parent[\'parent_id\'] )\"};\n		ipb.comments.setData( {parse expression=\"json_encode( $settings )\"} );\n	});\n</script>', 'commentsList', '$comments, $settings, $pages, $parent, $preReply=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('36', '0', 'skin_global_comments', '<if test=\"comment_errors:|:$errors\">\n	<p class=\'message error\'>{$errors}</p>\n</if>\n<div class=\'post_form\'>\n	<form method=\"post\" action=\"{$this->settings[\'base_url\']}\" name=\"REPLIER\">\n		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		<input type=\"hidden\" name=\"fromApp\" value=\"{$settings[\'fromApp\']}\" />\n		<input type=\"hidden\" name=\"app\" value=\"core\" />\n		<input type=\"hidden\" name=\"module\" value=\"global\" />\n		<input type=\"hidden\" name=\"section\" value=\"comments\" />	\n		<input type=\"hidden\" name=\"do\" value=\"saveEdit\" />\n		<input type=\"hidden\" name=\"parentId\" value=\"{$parent[\'parent_id\']}\" />\n		<input type=\"hidden\" name=\"comment_id\" value=\"{$comment[\'comment\'][\'comment_id\']}\" />\n		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		\n		<h3 class=\'maintitle\'>\n		<if test=\"$do == \'saveEdit\'\">\n			{$this->lang->words[\'edit_comment\']} {$parent[\'parent_title\']}\n		</if>\n		</h3>\n		<div class=\'generic_bar\'></div>\n		\n		<if test=\"guest_captcha:|:$this->memberData[\'member_id\'] == 0 AND $this->settings[\'guest_captcha\']\">\n			<fieldset>\n				<ul>\n					<li class=\'field\'>\n						<label for=\'\'>{$this->lang->words[\'guest_captcha\']}</label>\n						{$imgid}\n					</li>\n				</ul>\n			</fieldset>\n		</if>\n		\n		<fieldset>\n			{$editor}\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input type=\"submit\" name=\"submit\" value=\"{$this->lang->words[\'comment_save\']}\" tabindex=\"0\" class=\"input_submit\" accesskey=\"s\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"app=core&amp;module=global&amp;section=comments&amp;do=findComment&amp;comment_id={$comment[\'comment\'][\'comment_id\']}&amp;parentId={$parent[\'parent_id\']}&amp;fromApp={$settings[\'fromApp\']}\" base=\"public\"}\' class=\'cancel\' title=\'{$this->lang->words[\'cancel\']}\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</form>\n</div>', 'form', '$comment, $parent, $editor=\"\", $settings, $errors=\"\", $do=\'saveEdit\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('37', '0', 'skin_global_comments', '<php>\n$pluginEditorHook = IPSLib::loadLibrary( IPS_ROOT_PATH . \'sources/classes/editor/composite.php\', \'classes_editor_composite\' );\n$editor = new $pluginEditorHook();\n$smilies	= $editor->fetchEmoticons( 20 );\n$bypass		= $editor->getRteEnabled() ? 0 : 1;\n$this->hasEditJs = true;\n</php>\n{parse template=\"editorLoadJs\" group=\"editors\" params=\"array( \'bypassCKEditor\' => $bypass, \'smilies\' => $smilies )\"}', 'getEditJs', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('38', '0', 'skin_global_other', '<h3>{$this->lang->words[\'ap_error\']}</h3>\n<div class=\'general_box\'>\n	<div>\n		<if test=\"msg:|:$msg\">\n			$msg\n		<else />\n			{$this->lang->words[\'ap_np_msg\']}\n		</if>\n	</div>\n</div>', 'ajaxPopUpNoPermission', '$msg=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('39', '0', 'skin_global_other', '<input type=\"hidden\" id=\"regid\" name=\"captcha_unique_id\" value=\"{$captcha_unique_id}\" />\n<fieldset id=\'captcha\' class=\'gd\'>\n	<ul class=\'ipsForm <if test=\"$this->request[\'section\'] == \'register\' || $this->request[\'section\'] == \'lostpass\'\">ipsForm_horizontal<else />ipsForm_vertical</if>\'>\n		<li class=\'ipsField\'>\n			<label class=\'ipsField_title\'>{$this->lang->words[\'glb_captcha_image\']} <span class=\'ipsForm_required\'>*</span></label>\n			<div class=\'ipsField_content\'>\n				<p class=\'clearfix\'>\n					<img id=\'gd-antispam\' class=\'antispam_img left\' src=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=captcha&amp;do=showimage&amp;captcha_unique_id={$captcha_unique_id}\' />\n					<a href=\'#\' id=\'gd-image-link\' class=\'ipsButton_secondary left\' title=\"{$this->lang->words[\'captcah_new\']}\"><img src=\'{$this->settings[\'img_url\']}/icon_refresh.png\' alt=\"{$this->lang->words[\'captcah_new\']}\" /></a>\n				</p>\n				<input type=\"text\" class=\'input_text\' size=\"36\" maxlength=\"20\" value=\"\" name=\"captcha_string\" tabindex=\'0\' id=\'captcha_string\' />\n			</div>\n		</li>\n	</ul>\n</fieldset>\n<script type=\'text/javascript\'>\n	ipb.global.initGD();\n	$(\'captcha_string\').defaultize( \"{$this->lang->words[\'captcha_string_enter\']}\" );\n</script>', 'captchaGD', '$captcha_unique_id', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('40', '0', 'skin_global_other', '<fieldset id=\'captcha\' class=\'recaptcha\'>\n	<ul class=\'ipsForm <if test=\"$this->request[\'section\'] == \'register\' || $this->request[\'section\'] == \'lostpass\'\">ipsForm_horizontal<else />ipsForm_vertical</if>\'>\n		<li class=\'ipsField\'>\n			<label class=\'ipsField_title\'>{$this->lang->words[\'glb_captcha_image\']} <span class=\'ipsForm_required\'>*</span></label>\n			<div class=\'ipsField_content\'>\n				{$html}\n			</div>\n		</li>\n	</ul>\n</fieldset>', 'captchaRecaptcha', '$html=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('41', '0', 'skin_global_other', '<h1 class=\'ipsType_pagetitle\'>{parse expression=\"sprintf( $this->lang->words[\'board_offline_desc\'], $this->settings[\'board_name\'])\"}</h1>\n<div class=\'ipsType_pagedesc\'>{$message}</div>\n<br /><br />\n<p>\n	<if test=\"!$this->memberData[\'member_id\']\">\n		<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login\" base=\"public\"}\' title=\'{$this->lang->words[\'attempt_login\']}\' class=\'ipsButton\'>{$this->lang->words[\'click_login\']}</a>\n	<else />\n		<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;do=logout&amp;k={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'log_out\']}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'log_out\']}</a>\n	</if>\n</p>', 'displayBoardOffline', '$message=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('42', '0', 'skin_global_other', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\"> \n<html xml:lang=\"en\" lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\"> \n	<head>\n		<!-- THIS TEMPLATE (displayPopUpWindow) IS DEPRICATED AND WILL BE REMOVED IN A FUTURE VERSION -->\n		<meta http-equiv=\"content-type\" content=\"text/html; charset={$this->settings[\'gb_char_set\']}\" />\n		<title>{$title}</title>\n		<link rel=\"shortcut icon\" href=\"favicon.ico\" />\n		<if test=\"popupcssimport:|:is_array( $css[\'import\'] )\">\n			<if test=\"popupcssimportminify:|:$this->settings[\'use_minify\']\">\n				<php>$this->minify = array();</php>\n			</if>\n			<foreach loop=\"popupcssImport:$css[\'import\'] as $data\">\n				<php>\n					if( $this->settings[\'use_minify\'] AND stripos( $data[\'attributes\'], \'screen\' ) )\n					{\n						$this->minify[] = \"{$data[\'content\']}\";\n					}\n				</php>\n				<if test=\"popupcssimportnominify:|:!$this->settings[\'use_minify\']\">\n					<link rel=\"stylesheet\" type=\"text/css\" {$data[\'attributes\']} href=\"{$data[\'content\']}\" />\n				<else />\n					<if test=\"popupcssnoscreen:|:!stripos( $data[\'attributes\'], \'screen\' )\">\n						<link rel=\"stylesheet\" type=\"text/css\" {$data[\'attributes\']} href=\"{$this->settings[\'public_dir\']}min/index.php?f={parse expression=\"str_replace( $this->settings[\'public_dir\'], PUBLIC_DIRECTORY . \'/\', $data[\'content\'] )\"}\" />\n					</if>\n				</if>\n			</foreach>\n			<if test=\"popupminifycss:|:$this->settings[\'use_minify\'] AND count($this->minify)\">\n				<link rel=\"stylesheet\" type=\"text/css\" media=\'screen\' href=\"{$this->settings[\'public_dir\']}min/index.php?f={parse expression=\"str_replace( $this->settings[\'public_dir\'], PUBLIC_DIRECTORY . \'/\', implode( \',\', $this->minify ) )\"}\" />\n			</if>\n		</if>\n		<if test=\"popupcssinline:|:is_array( $css[\'inline\'] ) AND count( $css[\'inline\'] )\">\n			<foreach loop=\"popupcssInline:$css[\'inline\'] as $data\">\n			<style type=\"text/css\" {$data[\'attributes\']}>\n				/* Inline CSS */\n				{$data[\'content\']}\n			</style>\n			</foreach>\n		</if>\n		<!--[if lte IE 7]>\n			<link rel=\"stylesheet\" type=\"text/css\" title=\'Main\' media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_ie.css\" />\n		<![endif]-->\n		\n		{parse template=\"includeRTL\" group=\"global\" params=\"\"}	\n		<if test=\"popupmetatags:|:is_array( $metaTags ) AND count( $metaTags )\">\n			<foreach loop=\"popupmetaTags:$metaTags as $tag => $content\">\n			<meta name=\"{$tag}\" content=\"$content\" />\n			</foreach>\n		</if>\n		<script type=\'text/javascript\'>\n			jsDebug		= {parse expression=\"intval($this->settings[\'_jsDebug\'])\"}; /* Must come before JS includes */\n			USE_RTE		= <if test=\"popupuserte:|:$this->memberData[\'members_editor_choice\'] == \'rte\'\">1<else />0</if>;\n			var isRTL	= false;\n			var rtlIe	= \'\';\n			var rtlFull	= \'\';\n		</script>\n		<if test=\"popupminifyjs:|:$this->settings[\'use_minify\']\">\n			<if test=\"popupminfyjsrl:|:$this->settings[\'remote_load_js\']\">\n				<script type=\'text/javascript\' src=\'<if test=\"popupminfiyrlhttpsp:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/prototype/1.6/prototype.js\'></script>\n				<script type=\'text/javascript\' src=\'<if test=\"popupminfiyrlhttpss:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/scriptaculous/1.8/scriptaculous.js?load=effects,dragdrop,builder\'></script>\n			<else />\n				<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}min/index.php?g=js\'></script>\n			</if>\n			<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}min/index.php?f={parse expression=\"PUBLIC_DIRECTORY\"}/js/ipb.js,{parse expression=\"PUBLIC_DIRECTORY\"}/js/ips.quickpm.js<if test=\"popupjsmodules:|:count($jsLoaderItems) AND is_array($jsLoaderItems)\">,{parse expression=\"PUBLIC_DIRECTORY\"}/js/ips.{parse expression=\"implode(\'.js,\' . PUBLIC_DIRECTORY . \'/js/ips.\', array_unique( array_keys( $jsLoaderItems ) ) )\"}.js</if>,cache/lang_cache/{$this->lang->lang_id}/ipb.lang.js\'></script>\n		<else />\n			<if test=\"popuprl:|:$this->settings[\'remote_load_js\']\">\n				<script type=\'text/javascript\' src=\'<if test=\"popuphttpsp:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/prototype/1.6/prototype.js\'></script>\n			<else />\n				<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/prototype.js\'></script>\n			</if>\n			<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ipb.js?load=quickpm<if test=\"popupjsmodules:|:count($jsLoaderItems) AND is_array($jsLoaderItems)\">,{parse expression=\"implode(\',\', array_unique( array_keys( $jsLoaderItems ) ) )\"}</if>\'></script>\n			\n			<if test=\"popuprl2:|:$this->settings[\'remote_load_js\']\">\n				<script type=\'text/javascript\' src=\'<if test=\"popuphttpss:|:$this->registry->output->isHTTPS\">https<else />http</if>://ajax.googleapis.com/ajax/libs/scriptaculous/1.8/scriptaculous.js?load=effects,dragdrop,builder\'></script>\n			<else />\n				<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/scriptaculous/scriptaculous-cache.js\'></script>\n			</if>\n			<script type=\"text/javascript\" src=\'{$this->settings[\'cache_dir\']}lang_cache/{$this->member->language_id}/ipb.lang.js\'></script>\n		</if>\n		<if test=\"popupdocumenthead:|:count($documentHeadItems)\">\n			<foreach loop=\"popupheaditemtype:$documentHeadItems as $type => $idx\">\n				<foreach loop=\"popupdocumentHeadItems:$documentHeadItems[ $type ] as $idx => $data\">\n					<if test=\"popupjavascript:|:$type == \'javascript\'\">\n						<script type=\"text/javascript\" src=\"{$data}\" charset=\"<% CHARSET %>\"></script>\n					</if>\n					<if test=\"popuprss:|:$type == \'rss\'\">\n						<link rel=\"alternate feed\" type=\"application/rss+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n					</if>\n					<if test=\"popuprss:|:$type == \'rsd\'\">\n						<link rel=\"EditURI\" type=\"application/rsd+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n					</if>\n					<if test=\"popupraw:|:$type == \'raw\'\">\n						{$data}\n					</if>\n				</foreach>\n			</foreach>\n		</if>\n		\n		<script type=\'text/javascript\'>\n		//<![CDATA[\n			/* ---- URLs ---- */\n			ipb.vars[\'base_url\'] 			= \'{parse url=\"\" base=\"public\"}\';\n			ipb.vars[\'board_url\']			= \'{$this->settings[\'board_url\']}\';\n			ipb.vars[\'loading_img\'] 		= \'{$this->settings[\'img_url\']}/loading.gif\';\n			ipb.vars[\'active_app\']			= \'{$this->registry->getCurrentApplication()}\';\n			ipb.vars[\'upload_url\']			= \'{$this->settings[\'upload_url\']}\';\n			/* ---- Member ---- */\n			ipb.vars[\'member_id\']			= parseInt( {$this->memberData[\'member_id\']} ),\n			ipb.vars[\'is_supmod\']			= parseInt( {parse expression=\"intval($this->memberData[\'g_is_supmod\'])\"} ),\n			ipb.vars[\'is_admin\']			= parseInt( {$this->memberData[\'g_access_cp\']} ),\n			ipb.vars[\'secure_hash\'] 		= \'{$this->member->form_hash}\';\n			ipb.vars[\'session_id\']			= \'{$this->member->session_id}\';\n			ipb.vars[\'can_befriend\']		= <if test=\"popupbefriend:|:$this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">true<else />false</if>;\n			ipb.vars[\'auto_dst\']			= parseInt( {$this->memberData[\'members_auto_dst\']} );\n			ipb.vars[\'dst_in_use\']			= parseInt( {$this->memberData[\'dst_in_use\']} );\n			/* ---- cookies ----- */\n			ipb.vars[\'cookie_id\'] 			= \'{$this->settings[\'cookie_id\']}\';\n			ipb.vars[\'cookie_domain\'] 		= \'{$this->settings[\'cookie_domain\']}\';\n			ipb.vars[\'cookie_path\']			= \'{$this->settings[\'cookie_path\']}\';\n			/* ---- Rate imgs ---- */\n			ipb.vars[\'rate_img_on\']			= \'{$this->settings[\'img_url\']}/bullet_star.png\';\n			ipb.vars[\'rate_img_off\']		= \'{$this->settings[\'img_url\']}/bullet_star_off.png\';\n			ipb.vars[\'rate_img_rated\']		= \'{$this->settings[\'img_url\']}/bullet_star_rated.png\';\n			/* ---- Uploads ---- */\n			ipb.vars[\'swfupload_swf\']		= \'{parse url=\"js/3rd_party/swfupload/swfupload.swf\" base=\"public_dir\" httpauth=\"true\"}\';\n			ipb.vars[\'swfupload_enabled\']	= <if test=\"popupswfupload:|:$this->settings[\'uploadFormType\']\">true<else />false</if>;\n			ipb.vars[\'use_swf_upload\']		= ( \'{$this->memberData[\'member_uploader\']}\' == \'flash\' ) ? true : false;\n			ipb.vars[\'swfupload_debug\']		= false;\n			/* ---- other ---- */\n			ipb.vars[\'highlight_color\']		= \"#ade57a\";\n			ipb.vars[\'charset\']				= \"{$this->settings[\'gb_char_set\']}\";\n			ipb.vars[\'use_rte\']				= 1;\n			ipb.vars[\'image_resize_force\']  = {parse expression=\"intval($this->settings[\'resize_img_force\'])\"};\n			ipb.vars[\'seo_enabled\']			= {parse expression=\"intval($this->settings[\'use_friendly_urls\'])\"};\n			<if test=\"popupfurl:|:$this->settings[\'use_friendly_urls\']\">\n			ipb.vars[\'seo_params\']			= {parse expression=\"json_encode($this->registry->getClass(\'output\')->seoTemplates[\'__data__\'])\"};\n			</if>\n			/* Templates/Language */\n			ipb.templates[\'ajax_loading\'] 	= \"<div id=\'ajax_loading\'>\" + ipb.lang[\'loading\'] + \"</div>\";\n			ipb.templates[\'close_popup\']	= \"<img src=\'{$this->settings[\'img_url\']}/close_popup.png\' alt=\'x\' />\";\n			ipb.templates[\'rss_shell\']		= new Template(\"<ul id=\'rss_menu\'>#{items}</ul>\");\n			ipb.templates[\'rss_item\']		= new Template(\"<li><a href=\'#{url}\' title=\'#{title}\'>#{title}</a></li>\");\n			ipb.templates[\'resized_img\']	= new Template(\"<span>{$this->lang->words[\'resized_image\']}</span>\");\n			ipb.templates[\'m_add_friend\']	= new Template(\"<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id=#{id}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a>\");\n			ipb.templates[\'m_rem_friend\']	= new Template(\"<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id=#{id}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a>\");\n			ipb.templates[\'autocomplete_wrap\'] = new Template(\"<ul id=\'#{id}\' class=\'ipb_autocomplete\' style=\'width: 250px;\'></ul>\");\n			ipb.templates[\'autocomplete_item\'] = new Template(\"<li id=\'#{id}\' data-url=\'#{url}\'><img src=\'#{img}\' alt=\'\' width=\'#{img_w}\' height=\'#{img_h}\' />&nbsp;&nbsp;#{itemvalue}</li>\");\n			ipb.templates[\'page_jump\']		= new Template(\"<div id=\'#{id}_wrap\' class=\'ipbmenu_content\'><h3 class=\'bar\'>{$this->lang->words[\'global_page_jump\']}</h3><input type=\'text\' class=\'input_text\' id=\'#{id}_input\' size=\'8\' /> <input type=\'submit\' value=\'{$this->lang->words[\'jmp_go\']}\' class=\'input_submit add_folder\' id=\'#{id}_submit\' /></div>\");\n			Loader.boot();\n		//]]>\n		</script>\n	</head>\n	<body id=\'ipboard_body\' style=\'padding: 20px\'>\n		<div id=\'ipbwrapper\'>\n			{$output}\n		</div>\n	</body>\n</html>', 'displayPopUpWindow', '$documentHeadItems, $css, $jsLoaderItems, $title=\"\", $output=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('43', '0', 'skin_global_other', '<script type=\"text/javascript\">\n<!--\nfunction contact_admin() {\n  // Very basic spam bot stopper\n  admin_email_one = \'{$ad_email_one}\';\n  admin_email_two = \'{$ad_email_two}\';\n  window.location = \'mailto:\'+admin_email_one+\'@\'+admin_email_two+\'?subject={$this->lang->words[\'mailto_erroronforums\']}\';  \n}\n//-->\n</script>\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'error_title\']}</h1>\n<if test=\"showerrortitle:|:$show_top_msg == 1\">\n	<p class=\'ipsType_pagedesc\'>{$this->lang->words[\'exp_text\']}</p>\n	<br />\n</if>\n<div class=\'message error\'>\n	 <if test=\"haserrorcode:|:$code\">[#{$code}] </if>{$message}\n</div>\n<br />\n{$login}\n<if test=\"savedpost:|:$post\">\n	<div class=\'general_box alt\'>\n		{$post}\n	</div>\n<br />\n</if>\n<div class=\'general_box alt\'>	\n	<h3>{$this->lang->words[\'er_useful_links\']}</h3>\n	<br />\n	<ul class=\'bullets\'>\n		<li><a href=\"{parse url=\"app=core&amp;module=global&amp;section=lostpass&amp;do=10\" base=\"public\"}\" title=\'{$this->lang->words[\'er_lost_pass\']}\'>{$this->lang->words[\'er_lost_pass\']}</a></li>\n		<li><a href=\"{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=00\" base=\"public\"}\" title=\'{$this->lang->words[\'er_register\']}\'>{$this->lang->words[\'er_register\']}</a></li>\n		<li><a href=\"{parse url=\"app=core&module=help\" base=\"public\"}\" rel=\"help\" title=\'{$this->lang->words[\'er_help_files\']}\'>{$this->lang->words[\'er_help_files\']}</a></li>\n		<li><a href=\"javascript:contact_admin();\" title=\'{$this->lang->words[\'er_contact_admin\']}\'>{$this->lang->words[\'er_contact_admin\']}</a></li>\n	</ul>\n	<br />\n	<p class=\"submit\">\n		<strong><a href=\"javascript:history.go(-1)\">{$this->lang->words[\'error_back\']}</a></strong>\n	</p>\n</div>', 'Error', '$message=\"\",$code=0,$ad_email_one=\"\",$ad_email_two=\"\",$show_top_msg=0, $login=\"\", $post=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('44', '0', 'skin_global_other', '<div class=\'general_box alt\'>\n	<h3>{$this->lang->words[\'not_signed_in\']}</h3>\n	<p class=\'field\'>{parse replacement=\"signin_icon\"} <a href=\'{parse url=\"app=core&amp;module=global&amp;section=login\" base=\"public\"}\' title=\'{$this->lang->words[\'submit_li\']}\'>{$this->lang->words[\'click_login\']}</a>.</p>\n</div>\n<br />', 'error_log_in', '$q_string=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('45', '0', 'skin_global_other', '<h3>{$this->lang->words[\'err_title\']}</h3>\n<p>{$this->lang->words[\'err_expl\']}</p>\n<div class=\"fieldwrap\">\n	<h4>{$this->lang->words[\'err_title\']}</h4>\n	<form name=\"mehform\">\n		<textarea cols=\"70\" rows=\"5\" name=\"saved\" tabindex=\"2\">{$post}</textarea>\n	</form>\n	<p class=\"formbuttonrow1\"><input class=\"button\" type=\"button\" tabindex=\"1\" value=\"{$this->lang->words[\'err_select\']}\" onclick=\"document.mehform.saved.select()\" /></p>\n</div>', 'error_post_textarea', '$post=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('46', '0', 'skin_global_other', '<div class=\'ipsForm_center\'>\n	<br />\n	<strong>{$this->lang->words[\'facebook_post_ok\']}</strong>\n	<br />\n	<br />\n	<br />\n	<br />\n</div>', 'facebookDone', '$user', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('47', '0', 'skin_global_other', '<h3>{$this->lang->words[\'share_via_facebook\']}</h3>\n<div class=\'fixed_inner\'>\n	<div class=\'ipsPad\'><fb:like href=\"\" id=\"fbLikeButton\" layout=\"standard\" show_faces=\"false\" width=\"350\" height=\"45\" action=\"like\" colorscheme=\"light\" /></div>\n	<if test=\"hasFbConnected:|:$user[\'id\']\">\n		<ul class=\'ipsList_withminiphoto\' id=\"fParent\">\n			<li class=\'clearfix ipsPad_half\'>\n				<img src=\'{$user[\'pic_square\']}\' class=\'left ipsUserPhoto ipsUserPhoto_small\'/>\n				<img src=\"{$this->settings[\'public_dir\']}style_status/facebook.png\" class=\'left\' style=\'margin-top: -2px; margin-left: -12px;\'/>\n				<div class=\'list_content\' style=\'margin-left:58px\' id=\'fWrap\' >\n					<textarea class=\'input_text\' rows=\'3\' cols=\'10\' name=\'fContent\' style=\'width: 97%;\' id=\'fContent\'></textarea>\n					<div>\n						<div class=\'right clear\'>\n							<input type=\'button\' id=\'fSubmit\' class=\'input_submit\' value=\'{$this->lang->words[\'facebook_share\']}\' />\n						</div>\n						<div class=\'ipsType_smaller desc\'>{$this->lang->words[\'share_fb_name\']} {$user[\'first_name\']} {$user[\'last_name\']}</div>\n					</div>\n					\n				</div>\n			</li>\n		</ul>\n	<else />\n		<div class=\'ipsPad ipsForm_center\'><a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"\" /></a></div>\n	</if>\n	<div id=\"fb-root\"></div>\n	<script>\n		window.fbAsyncInit = function() {\n			FB.init({appId: \'{$this->settings[\'fbc_appid\']}\', status: true, cookie: true, xfbml: true});\n			if ( $(\'fParent\') )\n			{\n				FB.Event.subscribe(\'edge.create\', function(response) {\n	 				new Effect.Fade( $(\'fParent\'), { duration: 0.2 } );\n				});\n						\n				FB.Event.subscribe(\'edge.remove\', function(response) {\n	 				new Effect.Appear( $(\'fParent\'), { duration: 0.2 } );\n				});\n			}\n		};\n		(function() {\n			var e = document.createElement(\'script\'); e.async = true;\n		    e.src = document.location.protocol + \'//connect.facebook.net/{$this->settings[\'fb_locale\']}/all.js\';\n			document.getElementById(\'fb-root\').appendChild(e);\n				    \n			$(\'fbLikeButton\').writeAttribute(\'href\', $(\'ipsCanonical\').readAttribute(\'href\') );\n			\n			if ( $(\'fContent\') )\n			{\n				$(\'fContent\').defaultize(\'{$this->lang->words[\'fb_share_default\']}\');\n			}\n		}());\n	</script>\n</div>', 'facebookPop', '$user=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('48', '0', 'skin_global_other', '<form action=\"{parse url=\"app=core&amp;module=global&amp;section=like&amp;do=doUnsubscribe\" base=\"public\"}\" method=\"post\">\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'like_rel_id\' value=\'{$data[ $this->memberData[\'member_id\'] ][\'like_rel_id\']}\' />\n<input type=\'hidden\' name=\'like_area\' value=\'{$data[ $this->memberData[\'member_id\'] ][\'like_area\']}\' />\n<input type=\'hidden\' name=\'like_app\' value=\'{$data[ $this->memberData[\'member_id\'] ][\'like_app\']}\' />\n<input type=\'hidden\' name=\'like_id\' value=\'{$data[ $this->memberData[\'member_id\'] ][\'like_id\']}\' />\n<h3 class=\'maintitle\'>{$this->lang->words[\'pg_unfollow_title\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad_double ipsType_textblock\'>\n		{parse expression=\"sprintf( $this->lang->words[\'pg_unfollow_text\'], $data[ $this->memberData[\'member_id\'] ][\'members_display_name\'], $meta[\'like.url\'], $meta[\'like.title\'] )\"}\n		<br />\n		<br />\n		<p>\n			<input type=\"submit\" value=\"{$this->lang->words[\'pg_unfollow_confirm\']}\" class=\'ipsButton\'>\n			{$this->lang->words[\'or\']}\n			<a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n		</p>\n	</div>\n</div>\n</form>', 'followUnsubscribe', '$data, $meta', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('49', '0', 'skin_global_other', '<if test=\"topicIsMoved:|:$imgArray[\'is_moved\']\">\n	<span title=\"{$this->lang->words[\'pm_moved\']}\">{parse replacement=\"t_moved\"}</span>\n</if>\n<if test=\"topicIsClosed:|:$imgArray[\'is_closed\']\">\n	<span title=\"{$this->lang->words[\'pm_locked\']}\">{parse replacement=\"t_closed\"}</span>\n</if>\n<if test=\"topicReadDot:|:$imgArray[\'show_dot\'] && empty( $unreadUrl )\">{parse replacement=\"t_read_dot\"}</if>\n<if test=\"gotolatestwrap:|: ! empty( $unreadUrl ) && ! $imgArray[\'is_moved\']\">\n	<a href=\'{$unreadUrl}\' title=\'{$this->lang->words[\'first_unread_post\']}\'>\n	<if test=\"topicUnreadDot:|:$imgArray[\'show_dot\']\">\n		{parse replacement=\"t_unread_dot\"}\n	<else />\n		{parse replacement=\"t_unread\"}\n	</if>\n	</a>\n</if>', 'generateTopicIcon', '$imgArray, $unreadUrl', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('50', '0', 'skin_global_other', '<!DOCTYPE html>\n	<html xml:lang=\"en\" lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\"<if test=\"fbcenabled:|:IPSLib::fbc_enabled() === TRUE\"> xmlns:fb=\"http://www.facebook.com/2008/fbml\"</if>>\n	<head>\n		<meta http-equiv=\"content-type\" content=\"text/html; charset={$this->settings[\'gb_char_set\']}\" />\n		<title>{$header_items[\'title\']}<if test=\"pagenumberintitle:|:$header_items[\'page\']\"> {$this->lang->words[\'page_title_page\']} {$header_items[\'page\']}</if></title>\n		<link rel=\"shortcut icon\" href=\'<if test=\"$this->registry->output->isHTTPS\">{$this->settings[\'board_url_https\']}<else />{$this->settings[\'board_url\']}</if>/favicon.ico\' />\n		<link rel=\"image_src\" href=\'{$this->settings[\'meta_imagesrc\']}\' />\n		<script type=\'text/javascript\'>\n		//<![CDATA[\n			jsDebug			= {parse expression=\"intval($this->settings[\'_jsDebug\'])\"}; /* Must come before JS includes */\n			USE_RTE			= <if test=\"userte:|:$this->memberData[\'members_editor_choice\'] == \'rte\'\">1<else />0</if>;\n			DISABLE_AJAX	= parseInt({$this->settings[\'disable_text_ajax\']}); /* Disables ajax requests where text is sent to the DB; helpful for charset issues */\n			inACP			= false;\n			var isRTL		= false;\n			var rtlIe		= \'\';\n			var rtlFull		= \'\';\n		//]]>\n		</script>\n		{parse template=\"includeCSS\" group=\"global\" params=\"$css\"}\n		{parse template=\"includeMeta\" group=\"global\" params=\"$metaTags\"}\n		<meta property=\"og:title\" content=\"{IPSText::htmlspecialchars( str_replace( \' - \' . $this->settings[\'board_name\'], \'\', $header_items[\'title\'] ) )}\"/>\n		<meta property=\"og:site_name\" content=\"{IPSText::htmlspecialchars( $this->settings[\'board_name\'] )}\"/>\n		<meta property=\"og:image\" content=\"{$this->settings[\'meta_imagesrc\']}\"/>\n		<if test=\"isLargeTouch:|:$this->registry->output->isLargeTouchDevice()\">\n		<meta name=\"viewport\" content=\"width=1024px; initial-scale=1.0; minimum-scale=1.0;\">\n		</if>\n		<if test=\"isSmallTouch:|:$this->registry->output->isSmallTouchDevice()\">\n		<meta name=\"viewport\" content=\"width=1024px\">\n		</if>\n		{parse template=\"includeJS\" group=\"global\" params=\"$jsModules\"}\n		{parse template=\"includeFeeds\" group=\"global\" params=\"$documentHeadItems\"}\n		{parse template=\"includeRTL\" group=\"global\" params=\"\"}		\n		{parse template=\"includeVars\" group=\"global\" params=\"$header_items\"}\n	</head>\n	<body id=\'ipboard_body\' class=\'minimal\'>\n		<p id=\'content_jump\' class=\'hide\'><a id=\'top\'></a><a href=\'#j_content\' title=\'{$this->lang->words[\'jump_to_content\']}\' accesskey=\'m\'>{$this->lang->words[\'jump_to_content\']}</a></p>\n		<div id=\'ipbwrapper\'>		\n			<div id=\'content\' class=\'clearfix\'>\n				{$items[\'adHeaderCode\']}\n				<if test=\"mainpageContent:|:$html\">{$html}</if>\n				{$items[\'adFooterCode\']}\n			</div>\n			<div id=\'footer_utilities\' class=\'main_width clearfix clear\'>\n				{$footer_items[\'copyright\']}\n			</div>\n			<if test=\"showdebuglevel:|:$this->memberData[\'member_id\'] and $this->settings[\'debug_level\']\">\n				<div id=\'ipsDebug_footer\'>\n					<strong>{$this->lang->words[\'time_now\']}</strong> {$footer_items[\'time\']}\n					<if test=\"lastvisit:|:$this->memberData[\'member_id\'] AND $this->memberData[\'last_visit\']\"><strong>{$this->lang->words[\'you_last_visit\']}</strong> {parse date=\"$this->memberData[\'last_visit\']\" format=\"short\"}</if>\n					<strong>{$this->lang->words[\'stat_exec\']}</strong> {$stats[\'ex_time\']} <if test=\"isfloat:|:is_float($stats[\'ex_time\'])\">{$this->lang->words[\'stats_sec\']}</if>\n					<strong>{$this->lang->words[\'stat_load\']}</strong> {$stats[\'server_load\']}\n					<strong>{$this->lang->words[\'stat_queries\']}</strong> {$stats[\'queries\']} <if test=\"sqldebuglink:|:IPS_SQL_DEBUG_MODE\"><a href=\'{parse url=\"{$this->settings[\'query_string_safe\']}&amp;debug=1\" base=\"public\"}\'></if>{$this->lang->words[\'stats_queries\']}<if test=\"closesqldebuglink:|:IPS_SQL_DEBUG_MODE\"></a></if>\n					<strong>{$this->lang->words[\'stat_gzip\']}</strong> {$stats[\'gzip_status\']}\n				</div>\n			</if>\n			{$stats[\'task\']}\n		</div>\n		\n		<!--DEBUG_STATS-->\n	</body>\n</html>', 'globalTemplateMinimal', '$html, $documentHeadItems, $css, $jsModules, $metaTags, array $header_items, $items=array(), $footer_items=array(), $stats=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('51', '0', 'skin_global_other', '<!DOCTYPE html>\n	<html xml:lang=\"en\" lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\">\n	<head>\n		<meta http-equiv=\"content-type\" content=\"text/html; charset={$this->settings[\'gb_char_set\']}\" />\n		<title><#subject#></title>\n		<style type=\"text/css\">\n			body,div,dl,dt,dd,ul,ol,li,h1,h2,h3,h4,h5,h6,pre,form,fieldset,input,textarea,p,blockquote,th,td { margin:0; padding:0; } \n			table {	border-collapse:collapse; border-spacing:0; }\n			fieldset,img { border:0; }\n			address,caption,cite,code,dfn,th,var { font-style:normal; font-weight:normal; }\n			ol,ul { list-style:none; }\n			caption,th { text-align:left; }\n			h1,h2,h3,h4,h5,h6 { font-size:100%;	font-weight:normal; }\n			q:before,q:after { content:\'\'; }\n			abbr,acronym { border:0; }\n			address{ display: inline; }\n			\n			html, body {\n				background-color: #d8dde8;\n				color: #5a5a5a;\n			}\n			body {\n				font: normal 13px helvetica, arial, sans-serif;\n				position: relative;\n			}\n			\n			h3, strong { font-weight: bold; }\n			em { font-style: italic; }\n			img, .input_check, .input_radio { vertical-align: middle; }\n			legend { display: none; }\n			table { width: 100%; }\n			td { padding: 3px; }\n			\n			a {\n				color: #225985;\n				text-decoration: none;\n			}\n			\n			a:hover { color: #328586; }\n			\n			div.outer { margin: 0 auto; padding: 14px; }\n			\n			table.wrap { max-width: 800px; margin: 0 auto; }\n			\n			td.logo {\n				background-color: #0f3854;\n				padding: 8px;\n			}\n			\n			td.content {\n				background-color: #fff;\n				font-size: 14px !important;\n				color: black !important;\n				line-height: 150% !important;\n				padding: 8px;\n			}\n		</style>\n	</head>\n	<body>\n	<div class=\'outer\'>\n	<table class=\'wrap\'>\n		<tr>\n			<td class=\'logo\'><img src=\"{$this->settings[\'img_url\']}/logo_transparent.png\" /></td>\n		</tr>\n		<tr>\n			<td class=\'content\'>{$content}</td>\n		</tr>\n	</table>\n	</div>\n	</body>\n</html>', 'htmlEmailWrapper', '$content', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('52', '0', 'skin_global_other', '<h4 class=\'ipsType_sectiontitle\'>{$this->lang->words[\'inbox_at_the_top\']}<p class=\'ipsPad_half ipsType_smaller right\'><a href=\'{parse url=\"app=members&amp;module=messaging\" base=\"public\"}\' class=\'configure\'>{$this->lang->words[\'inbox_list_view\']}</a> &middot; <a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'compose_new\']}\'>{$this->lang->words[\'compose_new\']}</a></p></h4>\n<ul class=\'ipsList_withminiphoto\'>\n	<if test=\"hasTopics:|:count($topics)\">\n		<foreach loop=\"loopynotify:$topics as $topic\">\n		<li class=\'<if test=\"$topic[\'map_has_unread\']\">unread</if> ipsType_small clearfix\'>\n			<img src=\'{$topic[\'_starterMemberData\'][\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$topic[\'_starterMemberData\'][\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini left\' />\n			<div class=\'list_content\'>\n				<a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$topic[\'mt_id\']}&amp;msgID=__firstUnread__\" base=\"public\"}\'>\n				<if test=\"$topic[\'map_has_unread\']\"><strong></if>{$topic[\'mt_title\']}<if test=\"$topic[\'map_has_unread\']\"></strong></if>\n				</a>\n				<br />\n				<span class=\'ipsType_smaller desc lighter\'>{$topic[\'_starterMemberData\'][\'members_display_name\']} - {parse date=\"$topic[\'msg_date\']\" format=\"short\"}</span>\n			</div>\n		</li>\n		</foreach>\n	<else />\n		<li class=\'row1 ipsPad_half ipsType_smaller\'>{$this->lang->words[\'inbox_list_none\']}</li>\n	</if>\n</ul>', 'inboxList', '$topics', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('53', '0', 'skin_global_other', '<html>\n<head>\n</head>\n<body>\n<script type=\'text/javascript\'>\n	parent.ipb.inlineUploader.complete( $json );\n</script>\n</body>\n</html>', 'inlineUploaderComplete', '$json', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('54', '0', 'skin_global_other', '<h3>{$this->lang->words[\'followed_by\']}</h3>\n<div class=\'likepop fixed_inner\'>\n	<if test=\"hasVisibleEntries:|:is_array($data) && count($data)\">\n		<ul class=\'ipsList_withminiphoto\'>\n			<foreach loop=\"$data as $mid => $data\">\n				<li class=\'clearfix ipsPad_half <if test=\"$data[\'like_is_anon\']\">faded</if>\'>\n					<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'>\n						<img src=\'{$data[\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n					</a>\n					<div class=\'list_content\'>\n						<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$data[\'members_display_name\']}</strong></a>\n						<if test=\"$data[\'like_is_anon\']\"><em class=\'desc\'>{$this->lang->words[\'followed_anonymously\']}</em></if>\n						<p class=\'desc\'>\n							{parse expression=\"IPSMember::makeNameFormatted( $data[\'g_title\'], $data[\'g_id\'] )\"}\n						</p>\n					</div>\n				</li>\n			</foreach>\n		</ul>\n	</if>\n	<if test=\"hasAnonEntries:|:$cache[\'anonCount\']\">\n		<p class=\'desc ipsPad ipsForm_center\'>\n			(<if test=\"count( $data )\">{$this->lang->words[\'fave_and\']}</if> {parse expression=\"sprintf( ($cache[\'anonCount\'] > 1) ? $this->lang->words[\'follow_anon_count_p\'] : $this->lang->words[\'follow_anon_count_s\'], $cache[\'anonCount\'] )\"})\n		</p>\n	</if>\n</div>', 'likeMoreDialogue', '$data, $relId, $cache', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('55', '0', 'skin_global_other', '<h3>{parse expression=\"$this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ]\"}</h3>\n<fieldset class=\'ipsPad ipsForm ipsForm_vertical\'>\n	<ul>\n		<li class=\'ipsField ipsField_checkbox\'>\n			<input type=\"checkbox\" name=\"notify\" id=\"like_notify\" class=\"input_check\" value=\"1\" checked=\'checked\' />\n			<p class=\'ipsField_content\'>\n				<label for=\"like_notify\">{$this->lang->words[\'label_notify\']}</label>\n				<select name=\"freq\" id=\"like_freq\" class=\"input_select\">\n					<foreach loop=\"$data[\'frequencies\'] as $freq\">\n						<option value=\"$freq\">{$this->lang->words[ \'freq_\' . $freq ]}</option>\n					</foreach>\n				</select>\n			</p>\n		</li>\n		<li class=\'ipsField ipsField_checkbox\'>\n			<input type=\"checkbox\" name=\"anon\" id=\"like_anon\" class=\"input_check\" value=\"1\" />\n			<p class=\'ipsField_content\'>\n				<label for=\"like_anon\">{$this->lang->words[\'label_anon\']}<br /><span class=\'desc lighter\'>{$this->lang->words[\'label_anon_desc\']}</span></label>\n			</p>\n		</li>\n		<li class=\"submit ipsForm_center\">\n			<input type=\"submit\" value=\"{parse expression=\"sprintf( $this->lang->words[\'set_fave_button\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}\" class=\"input_submit _fsubmit\" />\n		</li>\n</fieldset>', 'likeSetDialogue', '$app, $area, $relid, $data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('56', '0', 'skin_global_other', '{parse js_module=\"like\"}\n<div class=\'ips_like\' data-app=\"{$data[\'app\']}\" data-area=\"{$data[\'area\']}\" data-relid=\"{$relId}\" data-isfave=\"{$data[\'iLike\']}\">\n	{parse template=\"likeSummaryContents\" group=\"global_other\" params=\"$data, $relId, $opts\"}\n</div>\n<script type=\"text/javascript\">\n	var FAVE_TEMPLATE = new Template( \"<h3>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_title\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}</h3><div><span class=\'desc\'>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_words\'], $this->lang->words[\'like_un\' . $data[\'vernacular\'] ])\"}</span><br /><p style=\'text-align:right\'><input type=\'button\' value=\'{parse expression=\"sprintf( $this->lang->words[\'unset_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}\' class=\'input_submit _funset\' /></p></div>\");\n</script>', 'likeSummary', '$data, $relId, $opts', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('57', '0', 'skin_global_other', '<if test=\"$data[\'formatted\']\">{$data[\'formatted\']}<else />&nbsp;</if>\n<if test=\"likeOnlyMembers:|:$this->memberData[\'member_id\']\">\n	<a href=\'#\' title=\"<if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'fave_tt_on\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'fave_tt_off\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if>\" class=\'ftoggle <if test=\"$data[\'iLike\']\"> on</if><if test=\"$opts[\'button-new-line\']\"> _newline</if>\'><if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'unset_fave_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'set_fave_button\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if></a>\n</if>', 'likeSummaryContents', '$data, $relId, $opts=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('58', '0', 'skin_global_other', '<h4 class=\'ipsType_sectiontitle\'>{$this->lang->words[\'notifications_at_the_top\']}\n	<p class=\'ipsPad_half ipsType_smaller right\'>\n	<a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=notificationlog\" base=\"public\"}\' class=\'configure\'>{$this->lang->words[\'notifications_viewall\']}</a>\n	&middot; <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=notifications\" base=\"public\"}\' class=\'configure\'>{$this->lang->words[\'generic_opts_link\']}</a>\n	</p>\n</h4>\n<ul class=\'ipsList_withminiphoto\'>\n	<if test=\"hasnotifications:|:count($notifications)\">\n		<foreach loop=\"loopynotify:$notifications as $notify\">\n		<li class=\'<if test=\"!$notify[\'notify_read\']\">unread</if> ipsType_small clearfix\'>\n			<img src=\'{$notify[\'member\'][\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$notify[\'member\'][\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini left\' />\n			<div class=\'list_content\'>\n				<if test=\"strpos( $notify[\'notify_title\'], \'<a href\' ) === false\">\n					<a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=viewNotification&amp;do=view&amp;view={$notify[\'notify_id\']}\" base=\"public\"}\'>\n				</if>\n				<if test=\"!$notify[\'notify_read\']\"><strong></if>{$notify[\'notify_title\']}<if test=\"!$notify[\'notify_read\']\"></strong></if>\n				<if test=\"strpos( $notify[\'notify_title\'], \'<a href\' ) === false\">\n					</a>\n				</if>\n				<br />\n				<span class=\'ipsType_smaller desc lighter\'>{parse date=\"$notify[\'notify_sent\']\" format=\"short\"}</span>\n			</div>\n		</li>\n		</foreach>\n	<else />\n		<li class=\'desc\'>{$this->lang->words[\'nonotifications_list\']}</li>\n	</if>\n</ul>', 'notificationsList', '$notifications', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('59', '0', 'skin_global_other', '<fieldset id=\'q_n_a\'>	\n	<input type=\"hidden\" name=\"qanda_id\" value=\"{$data[\'qa_id\']}\" />\n	<ul class=\'ipsForm ipsForm_horizontal\'>\n		<li class=\'ipsField\'>\n			<label for=\'qna\' class=\'ipsField_title\'>{$this->lang->words[\'registration_question\']} <span class=\'ipsForm_required\'>*</span></label>\n			<div class=\'ipsField_content\'>\n				<strong>{$data[\'qa_question\']}</strong><br />\n				<input type=\"text\" class=\'input_text\' size=\"45\" maxlength=\"100\" value=\"<if test=\"qadefault:|:$this->request[\'qanda_id\'] AND $this->request[\'qanda_id\']==$data[\'qa_id\']\">{$this->request[\'qa_answer\']}</if>\" name=\"qa_answer\" id=\'qna\' tabindex=\'0\' /><br />\n				<span class=\'desc lighter\'>{$this->lang->words[\'qa_question_desc\']}</span>\n			</div>\n		</li>\n	</ul>\n</fieldset>', 'questionAndAnswer', '$data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('60', '0', 'skin_global_other', '<h3>{$this->lang->words[\'navigation_title\']}</h3>\n<div class=\'fixed_inner ipsBox\'>\n	<div class=\'message error\'><strong>{$this->lang->words[\'board_offline_desc\']}</strong><br /><br />{$message}</div>\n</div>', 'quickNavigationOffline', '$message', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('61', '0', 'skin_global_other', '<div>\n	<foreach loop=\"outer:$data as $_data\">\n		<if test=\"hasTitle:|: ! empty( $_data[\'title\'] )\"><h3>{$_data[\'title\']}</h3></if>\n		<ul class=\'block_list\'>\n		<foreach loop=\"innerAgain:$_data[\'links\'] as $link\">\n	 		<li><if test=\"depth:|:!empty($link[\'depth\'])\">{parse expression=\"str_repeat( \'&nbsp;&nbsp;&nbsp;&nbsp;\', $link[\'depth\'])\"}</if><a <if test=\"important:|:!empty($link[\'important\'])\">style=\"font-weight:bold\"</if> href=\"{$link[\'url\']}\">{$link[\'title\']}</a></li>\n		</foreach>\n		</ul>\n	</foreach>\n</div>', 'quickNavigationPanel', '$data=array(), $currentApp=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('62', '0', 'skin_global_other', '<h3>{$this->lang->words[\'navigation_title\']}</h3>\n<div class=\'fixed_inner ipsBox\'>\n	<if test=\"isLargeTouch:|:$this->registry->output->isLargeTouchDevice()\">\n		<div class=\'message\' style=\'margin-bottom: 5px;\'>{$this->lang->words[\'scroll_tip\']}</div>\n	</if>\n	<div class=\'ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_smallleft clearfix\'>\n		<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\'>		\n			<ul>\n				<foreach loop=\"navTabs:$tabs as $app => $title\">\n					<li <if test=\"active:|:$app == $currentApp\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=global&amp;section=navigation&amp;inapp={$app}\" base=\"public\"}\' rel=\"ipsQuickNav\" data-app=\"{$app}\">{$title}</a></li>\n				</foreach>\n			</ul>\n		</div>\n	\n		<div class=\'ipsVerticalTabbed_content ipsLayout_content ipsBox_container\' style=\'position: relative\' id=\'ipsNav_content\'>\n			{parse template=\"quickNavigationPanel\" group=\"global_other\" params=\"$data, $currentApp\"}\n		</div>\n	</div>\n</div>', 'quickNavigationWrapper', '$tabs=array(), $data=array(), $currentApp=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('63', '0', 'skin_global_other', '<!DOCTYPE html PUBLIC \"-//W3C//DTD XHTML 1.0 Transitional//EN\" \"http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd\"> \n<html xml:lang=\"en\" lang=\"en\" xmlns=\"http://www.w3.org/1999/xhtml\"> \n	<head>\n	    <meta http-equiv=\"content-type\" content=\"text/html; charset=<% CHARSET %>\" /> \n		<title>{$this->lang->words[\'stand_by\']}</title>\n		<if test=\"redirectfull:|:$full==true\">\n			<meta http-equiv=\"refresh\" content=\"2; url={parse url=\"$url\" base=\"none\"}\" />\n		<else />\n			<meta http-equiv=\"refresh\" content=\"2; url={parse url=\"$url\" base=\"public\"}\" />\n		</if>\n		<link rel=\"shortcut icon\" href=\'<if test=\"$this->registry->output->isHTTPS\">{$this->settings[\'board_url_https\']}<else />{$this->settings[\'board_url\']}</if>/favicon.ico\' />\n		<if test=\"redirectcssimport:|:is_array( $css[\'import\'] )\">\n			<foreach loop=\"redirectcssImport:$css[\'import\'] as $data\">\n				<link rel=\"stylesheet\" type=\"text/css\" {$data[\'attributes\']} href=\"{$data[\'content\']}\">\n			</foreach>\n		</if>\n		<if test=\"redirectcssinline:|:is_array( $css[\'inline\'] ) AND count( $css[\'inline\'] )\">\n			<foreach loop=\"redirctcssInline:$css[\'inline\'] as $data\">\n				<style type=\"text/css\" {$data[\'attributes\']}>\n					/* Inline CSS */\n					{$data[\'content\']}\n				</style>\n			</foreach>\n		</if>\n		<!--[if lte IE 7]>\n			<link rel=\"stylesheet\" type=\"text/css\" title=\'Main\' media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_ie.css\" />\n		<![endif]-->\n		\n		{parse template=\"includeRTL\" group=\"global\" params=\"\"}	\n		<script type=\'text/javascript\'>\n			jsDebug		= 0; /* Must come before JS includes */\n			var isRTL	= false;\n			var rtlIe	= \'\';\n			var rtlFull	= \'\';\n		</script>\n		<if test=\"redirectdh:|:count($documentHeadItems)\">\n			<foreach loop=\"redirectdocumentHeadItems:$documentHeadItems as $type => $idx\">\n				<foreach loop=\"redirectdocumentHeadItemsSub:$documentHeadItems[ $type ] as $idx => $data\">\n					<if test=\"redirectjs:|:$type == \'javascript\'\">\n						<script type=\"text/javascript\" src=\"{$data}\" charset=\"<% CHARSET %>\"></script>\n					</if>\n					<if test=\"redirectrss:|:$type == \'rss\'\">\n						<link rel=\"alternate\" type=\"application/rss+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n					</if>\n					<if test=\"redirectrsd:|:$type == \'rsd\'\">\n						<link rel=\"EditURI\" type=\"application/rsd+xml\" title=\"{$data[\'title\']}\" href=\"{$data[\'url\']}\" />\n					</if>\n					<if test=\"redirectraw:|:$type == \'raw\'\">\n						$data\n					</if>\n				</foreach>\n			</foreach>\n		</if>\n		<!--/CSS-->\n		<script type=\'text/javascript\'>\n		//<![CDATA[\n		// Fix Mozilla bug: 209020\n		if ( navigator.product == \'Gecko\' )\n		{\n			navstring = navigator.userAgent.toLowerCase();\n			geckonum  = navstring.replace( /.*gecko\\/(\\d+)/, \"$1\" );\n			setTimeout(\"moz_redirect()\",1500);\n		}\n		function moz_redirect()\n		{\n			<if test=\"redirectmozfull:|:$full==true\">\n				var url_bit     = \"{parse url=\"$url\" base=\"none\"}\";\n			<else />\n				var url_bit     = \"{parse url=\"$url\" base=\"public\"}\";\n			</if>\n			window.location = url_bit.replace( new RegExp( \"&amp;\", \"g\" ) , \'&\' );\n		}\n		//>\n		</script>\n	</head>\n	<body  id=\'ipboard_body\' class=\'redirector\'>\n		<div id=\'ipbredirectwrapper\'>\n			<p class=\'message\'>\n				<strong>{$text}</strong>\n				<br /><br />\n				{$this->lang->words[\'transfer_you\']}\n				<br />\n				<span class=\'desc\'>(<a href=\"<if test=\"redirectlink:|:$full==true\">{parse url=\"{$url}\" base=\"none\"}<else />{parse url=\"{$url}\" base=\"public\"}</if>\">{$this->lang->words[\'dont_wait\']}</a>)</span>	\n			</p>\n		</div>\n	</body>\n</html>', 'redirectTemplate', '$documentHeadItems, $css, $jsLoaderItems, $text=\"\",$url=\"\", $full=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('64', '0', 'skin_global_other', '<php>\n	// Apps can set the key empty to disable, but this will allow all apps to use the popup to show who repped\n	if( !isset($data[\'jsCallback\']) )\n	{\n		$data[\'jsCallback\']	= \"ipb.global.repPopUp( this, {$data[\'primaryId\']}, \'{$data[\'app\']}\', \'{$data[\'type\']}\' );\";\n	}\n	\n	$repClickable	= ( $this->memberData[\'gbw_view_reps\'] AND $data[\'jsCallback\'] ) ? \'onclick=\"\' . $data[\'jsCallback\'] . \'\"\' : \'\';\n</php>\n<if test=\"reputationBox:|:$this->settings[\'reputation_enabled\']\">\n	<if test=\"canRep:|:!( $this->settings[\'reputation_protected_groups\'] && in_array( $member[\'member_group_id\'], explode( \',\', $this->settings[\'reputation_protected_groups\'] ) ) ) and $this->memberData[\'member_id\']\">	\n		<if test=\"isLike:|:$this->settings[\'reputation_point_types\'] == \'like\'\">\n			<div class=\'ipsLikeBar right clearfix\' id=\'{$data[\'domCountId\']}\'>\n				<ul class=\'ipsList_inline\'>\n					<if test=\"!isset($data[\'hide_text\']) OR !$data[\'hide_text\']\">\n						<li id=\"{$data[\'domLikeStripId\']}\" class=\'ipsLikeBar_info\' <if test=\"hasNoLikes:|:!$data[\'likeFormatted\']\">style=\"display:none\"</if>>\n							{$data[\'likeFormatted\']}\n						</li>\n					</if>\n					<if test=\"canGiveRep:|:IPSMember::canGiveRep( $data, $member ) !== false\">\n						<li <if test=\"giveRepUp:|:IPSMember::canRepUp( $data, $member ) === false\">style=\"display:none\"</if>>\n							<a class=\'ipsLikeButton ipsLikeButton_enabled rep_up\' href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate={$data[\'app\']}&amp;type={$data[\'type\']}&amp;type_id={$data[\'primaryId\']}&amp;rating=1&amp;secure_key={$this->member->form_hash}&amp;post_return={$data[\'primaryId\']}\' title=\'{$this->lang->words[\'do_like_up\']}\'>{$this->lang->words[\'like_this\']}</a>\n						</li>\n						<li <if test=\"giveRepDown:|:IPSMember::canRepDown( $data, $member ) === false\">style=\"display:none\"</if>>\n							<a class=\'ipsLikeButton ipsLikeButton_disabled rep_down\' href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate={$data[\'app\']}&amp;type={$data[\'type\']}&amp;type_id={$data[\'primaryId\']}&amp;rating=-1&amp;secure_key={$this->member->form_hash}&amp;post_return={$data[\'primaryId\']}\' title=\'{$this->lang->words[\'do_like_down\']}\'>{$this->lang->words[\'unlike_this\']}</a>\n						</li>\n					</if>\n				</ul>\n			</div>\n		<else />\n			<div class=\'rep_bar clearfix <if test=\"pos:|:!$data[\'position\'] || $data[\'position\'] == \'right\'\">right</if>\' id=\'{$data[\'domCountId\']}\'>\n				{parse variable=\"repClickable\" default=\"\" oncondition=\"$this->memberData[\'gbw_view_reps\']\" value=\" clickable\"}\n				<ul class=\'ipsList_inline\'>\n					<if test=\"canGiveRep:|:IPSMember::canGiveRep( $data, $member ) !== false\">			\n						<li <if test=\"giveRepUp:|:IPSMember::canRepUp( $data, $member ) === false\">style=\"display:none\"</if>>\n							<a href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate={$data[\'app\']}&amp;type={$data[\'type\']}&amp;type_id={$data[\'primaryId\']}&amp;rating=1&amp;secure_key={$this->member->form_hash}&amp;post_return={$data[\'primaryId\']}\' class=\'rep_up\' title=\'{$this->lang->words[\'reputation_up\']}\'>{parse replacement=\"rep_up\"}</a>\n						</li>\n						<li <if test=\"giveRepDown:|:IPSMember::canRepDown( $data, $member ) === false\">style=\"display:none\"</if>>\n							<a href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate={$data[\'app\']}&amp;type={$data[\'type\']}&amp;type_id={$data[\'primaryId\']}&amp;rating=-1&amp;secure_key={$this->member->form_hash}&amp;post_return={$data[\'primaryId\']}\' class=\'rep_down\' title=\'{$this->lang->words[\'reputation_down\']}\'>{parse replacement=\"rep_down\"}</a>\n						</li>\n					</if>\n					<if test=\"isNotLike:|:$this->settings[\'reputation_point_types\'] != \'like\'\">\n						<if test=\"hasNoRep:|:$data[\'rep_points\'] == 0\">\n							<li><span class=\'reputation zero rep_show{parse variable=\"repClickable\"}\' title=\'{$this->lang->words[\'reputation\']}\' {$repClickable}>\n						</if>\n						<if test=\"hasPosRep:|:$data[\'rep_points\'] > 0\">\n							<li><span class=\'reputation positive rep_show{parse variable=\"repClickable\"}\' title=\'{$this->lang->words[\'reputation\']}\' {$repClickable}>\n						</if>\n						<if test=\"hasNegRep:|:$data[\'rep_points\'] < 0\">\n							<li><span class=\'reputation negative rep_show{parse variable=\"repClickable\"}\' title=\'{$this->lang->words[\'reputation\']}\' {$repClickable}>\n						</if>\n							{$data[\'rep_points\']}\n							</span>\n						</li>\n					</if>\n				</ul>\n			</div>\n		</if>\n	</if>\n</if>\n<script type=\'text/javascript\'>\n	ipb.global.registerReputation( \'{$data[\'domCountId\']}\', { domLikeStripId: \'{$data[\'domLikeStripId\']}\', app: \'{$data[\'app\']}\', type: \'{$data[\'type\']}\', typeid: \'{$data[\'primaryId\']}\' }, parseInt(\'{$data[\'rep_points\']}\') );\n</script>', 'repButtons', '$member, $data=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('65', '0', 'skin_global_other', '<h3>{$this->lang->words[\'liked_by_title\']}</h3>\n<div class=\'likepop fixed_inner\'>\n	<ul class=\'ipsList_withminiphoto\'>\n		<foreach loop=\"$data as $mid => $data\">\n			<li class=\'clearfix ipsPad_half <if test=\"$data[\'like_is_anon\']\">faded</if>\'>\n				<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'>\n					<img src=\'{$data[\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n				</a>\n				<div class=\'list_content\'>\n					<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$data[\'members_display_name\']}</strong></a>\n					<em class=\'desc\'>{$this->lang->words[\'likeadded\']} {parse date=\"$data[\'rep_date\']\" format=\"short\"}</em>\n					<p class=\'desc\'>\n						{parse expression=\"IPSMember::makeNameFormatted( $data[\'g_title\'], $data[\'g_id\'] )\"}\n					</p>\n				</div>\n			</li>\n		</foreach>\n	</ul>\n</div>', 'repMoreDialogue', '$data, $relId', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('66', '0', 'skin_global_other', '<div>\n	<h3>{$this->lang->words[\'rep_given\']}</h3>\n	<div class=\'ipsPad\' style=\'min-height: 60px\'>\n		<if test=\"empty($reps)\">\n			<em>{$this->lang->words[\'no_rep\']}</em>\n		<else />\n			<foreach loop=\"$reps as $r\">\n				<if test=\"$r[\'rep_rating\'] > 0\">\n					{parse replacement=\"rep_up\"}\n				<else />\n					{parse replacement=\"rep_down\"}\n				</if>\n				 <a href=\'{parse url=\"showuser={$r[\'member\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$r[\'member\'][\'members_seo_name\']}\"}\'>{$r[\'member\'][\'members_display_name\']}</a><br />\n			</foreach>\n		</if>\n	</div>\n</div>', 'reputationPopup', '$reps', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('67', '0', 'skin_global_other', '<h3 class=\'maintitle\'>Tags</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<ul class=\'ipsList_inline\'>\n		<foreach loop=\"eachTag:$tags[\'tags\'] as $id => $data\">\n			<li><span class=\"{$data[\'className\']}\">{$data[\'tagWithUrl\']}</span></li>\n		</foreach>\n		</ul>\n	</div>\n</div>', 'tagCloud', '$tags', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('68', '0', 'skin_global_other', '<if test=\"isNotHuman:|:!$this->member->is_not_human\">\n	<a <if test=\"noClass:|:!$noClass\">class=\'ipsTag\'</if> href=\"{parse url=\"app=core&amp;module=search&amp;do=search&amp;search_tags={parse expression=\"urlencode($tag)\"}&amp;search_app=<if test=\"inSearch:|:isset($this->request[\'search_app\']) AND $this->request[\'search_app\']\">{$this->request[\'search_app\']}<else />{$app}</if>\" base=\"public\"}\" data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'find_more_tags\'], $tag )\"}\"><span>{$tag}</span></a>\n<else />\n	{$tag}\n</if>', 'tagEntry', '$tag, $noClass=false, $app=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('69', '0', 'skin_global_other', '<if test=\"isNotHuman:|:!$this->member->is_not_human\">\n	<a href=\"{parse url=\"app=core&amp;module=search&amp;do=search&amp;search_tags={parse expression=\"urlencode($tag)\"}&amp;search_app=<if test=\"inSearch:|:isset($this->request[\'search_app\']) AND $this->request[\'search_app\']\">{$this->request[\'search_app\']}<else />{$app}</if>\" base=\"public\"}\" class=\'ipsBadge ipsBadge_lightgrey\'>{$tag}</a>\n<else />\n	{$tag}\n</if>', 'tagPrefix', '$tag, $app=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('70', '0', 'skin_global_other', '{parse js_module=\"tags\"}\n<input type=\"text\" class=\"input_text\" size=\"50\" value=\"\" name=\"{$options[\'fieldId\']}\" id=\"{$options[\'fieldId\']}\" <if test=\"isClosedField:|: ! $options[\'isOpenSystem\']\">readonly=\"readonly\"</if> />\n<if test=\"canPrefix:|:$options[\'prefixesEnabled\'] && !$this->memberData[\'gbw_disable_prefixes\']\">\n	&nbsp;&nbsp;<span class=\"desc lighter\"><input type=\"checkbox\" value=\"1\" name=\"{$options[\'fieldId\']}_prefix\" id=\"{$options[\'fieldId\']}_prefix\" <if test=\"prefixChecked:|:$tags[\'formatted\'][\'prefix\'] OR $this->request[ $options[\'fieldId\'] . \'_prefix\' ]\">checked=\'checked\'</if> /> {$this->lang->words[\'firsttagprefix\']}</span>\n</if>\n<if test=\"!$options[\'minTags\'] && $options[\'maxTags\']\">\n	<br /><span class=\'desc lighter\'>{parse expression=\"sprintf( $this->lang->words[\'tags_max_no_min\'], $options[\'maxTags\'] )\"}</span>\n</if>\n<if test=\"$options[\'minTags\'] && !$options[\'maxTags\']\">\n	<br /><span class=\'desc lighter\'>{parse expression=\"sprintf( $this->lang->words[\'tags_min_no_max\'], $options[\'minTags\'] )\"}</span>\n</if>\n<if test=\"$options[\'minTags\'] && $options[\'maxTags\']\">\n	<br /><span class=\'desc lighter\'>{parse expression=\"sprintf( $this->lang->words[\'tags_max_and_min\'], $options[\'minTags\'], $options[\'maxTags\'] )\"}</span>\n</if>\n<php>\n	$options[\'lang\'][\'tag_add_link\']	= $this->lang->words[\'add_a_tag\'];\n	$options[\'lang\'][\'tip_text\']		= $this->lang->words[\'tag_tip\'];\n	$options[\'forceLowercase\']			= $this->settings[\'tags_force_lower\'];\n	$options[\'existingTags\']			= count($tags[\'tags\']) ? $tags[\'tags\'] : null;\n	\n	$_tmp = $options;\n	\n	/* Always return as UTF-8 */\n	array_walk_recursive( $_tmp, array( \'IPSText\', \'arrayWalkCallbackConvert\' ) );\n	$jsonEncoded = json_encode( $_tmp );\n	$jsonEncoded = IPSText::convertCharsets($jsonEncoded, \"UTF-8\", IPS_DOC_CHAR_SET);\n</php>\n<script type=\"text/javascript\">\n	$( \"{$options[\'fieldId\']}\" ).tagify( {parse expression=\"$jsonEncoded\"} );\n</script>', 'tagTextEntryBox', '$tags, $options, $where', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('71', '0', 'skin_global_other', '<div class=\'ipsForm_center\'>\n	<br />\n	<strong>{$this->lang->words[\'tweet_ok\']}</strong>\n	<br />\n	<br />\n	<p><a href=\"http://twitter.com/{$user[\'screen_name\']}/status/{$user[\'status\'][\'id\']}\" target=\"_blank\">twitter.com/{$user[\'screen_name\']}/status/{$user[\'status\'][\'id\']}</a></p>\n</div>', 'twitterDone', '$user', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('72', '0', 'skin_global_other', '<h3>{$this->lang->words[\'share_via_twitter\']}</h3>\n<div class=\'fixed_inner\'>\n	<ul class=\'ipsList_withminiphoto\'>\n		<li class=\'clearfix ipsPad_half\'>\n			<img src=\'{$user[\'profile_image_url\']}\' class=\'left ipsUserPhoto ipsUserPhoto_small\'/>\n			<img src=\"{$this->settings[\'public_dir\']}style_status/twitter.png\" class=\'left\' style=\'margin-top: -2px; margin-left: -12px;\'/>\n			<div class=\'list_content\' style=\'margin-left:58px\' id=\'tWrap\' >\n				<p class=\'ipsType_small desc\'>{$user[\'screen_name\']}</p>\n				<textarea class=\'input_text\' rows=\'3\' cols=\'10\' name=\'tContent\' style=\'width: 97%;\' id=\'tContent\'></textarea>\n				<div>\n					<div class=\'right\'><input type=\'button\' id=\'tSubmit\' class=\'input_submit\' value=\'{$this->lang->words[\'twitter_share\']}\' /></div>\n					<div class=\'ipsType_smaller desc\'><span id=\'cLeft\' style=\'font-weight:bold\'>0</span> {$this->lang->words[\'twitter_chrs_left\']}</div>\n				</div>\n			</div>\n		</li>\n	</ul>\n</div>', 'twitterPop', '$user', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('73', '0', 'skin_help', '<if test=\"notajax:|:!$this->request[\'xml\']\">\n<div class=\'topic_controls\'>\n	<ul class=\'topic_buttons\'>\n		<li><a href=\"{parse url=\"app=core&amp;module=help\" base=\"public\"}\" title=\"{$this->lang->words[\'help_back_list_title\']}\"><img src=\'{$this->settings[\'img_url\']}/back.png\' alt=\'\' /> {$this->lang->words[\'help_return_list\']}</a></li>\n	</ul>\n</div>\n</if>\n<if test=\"isajax:|:$this->request[\'xml\']\">\n<br />\n</if>\n<if test=\"notajax:|:!$this->request[\'xml\']\">\n	<h1 class=\'ipsType_pagetitle\'>{$one_text}: {$three_text}</h1>\n<else />\n	<h1 class=\'ipsType_subtitle\'>{$one_text}: {$three_text}</h1>\n</if>\n<br />\n<div class=\'row2 help_doc ipsPad bullets\'>\n	{$text}\n</div>\n<br />', 'helpShowSection', '$one_text=\"\",$two_text=\"\",$three_text=\"\", $text', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('74', '0', 'skin_help', '{parse js_module=\"help\"}\n<p class=\'message unspecific\'>{$two_text}</p>\n<h2 class=\'maintitle\'>{$this->lang->words[\'help_topics\']}</h2>\n<div class=\'generic_bar\'></div>\n<ol id=\'help_topics\'>\n	{parse striping=\"help\" classes=\"row1,row2\"}\n	<if test=\"count($rows)\">\n		<foreach loop=\"helpfiles:$rows as $entry\">\n		<li class=\'{parse striping=\"help\"} helpRow\'>\n			<h3><a href=\"{parse url=\"app=core&amp;module=help&amp;do=01&amp;HID={$entry[\'id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'help_read_document\']}\">{$entry[\'title\']}</a></h3>\n			<p>\n				{$entry[\'description\']}\n			</p>\n		</li>\n		</foreach>\n	<else />\n		<li class=\'no_messages\'>{$this->lang->words[\'no_help_topics\']}</li>\n	</if>\n</ol>', 'helpShowTopics', '$one_text=\"\",$two_text=\"\",$three_text=\"\",$rows', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('75', '0', 'skin_login', '<php>\n	$uses_name		= false;\n	$uses_email		= false;\n	$_redirect		= \'\';\n	\n	foreach( $this->cache->getCache(\'login_methods\') as $method )\n	{\n		if( $method[\'login_user_id\'] == \'username\' or $method[\'login_user_id\'] == \'either\' )\n		{\n			$uses_name	= true;\n		}\n		\n		if( $method[\'login_user_id\'] == \'email\' or $method[\'login_user_id\'] == \'either\' )\n		{\n			$uses_email	= true;\n		}\n		\n		if( $method[\'login_login_url\'] )\n		{\n			$_redirect	= $method[\'login_login_url\'];\n		}\n	}\n	if( $uses_name AND $uses_email )\n	{\n		$this->lang->words[\'enter_name\']	= $this->lang->words[\'enter_name_and_email\'];\n	}\n	else if( $uses_email )\n	{\n		$this->lang->words[\'enter_name\']	= $this->lang->words[\'enter_useremail\'];\n	}\n	else\n	{\n		$this->lang->words[\'enter_name\']	= $this->lang->words[\'enter_username\'];\n	}\n</php>\n<if test=\"hasRedirect:|:$_redirect\">\n<script type=\'text/javascript\'>\nwindow.location = \'{$_redirect}\';\n</script>\n<else />\n<div id=\'inline_login_form\'>\n	<form action=\"{parse url=\"app=core&amp;module=global&amp;section=login&amp;do=process\" base=\"public\"}\" method=\"post\" id=\'login\'>\n		<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n		<input type=\"hidden\" name=\"referer\" value=\"{parse expression=\"my_getenv(\'HTTP_REFERER\')\"}\" />\n		<h3>{$this->lang->words[\'log_in\']}</h3>\n		<if test=\"registerServices:|: IPSLib::fbc_enabled() || IPSLib::twitter_enabled() === true\">\n			<div class=\'ipsBox_notice\'>\n				<ul class=\'ipsList_inline\'>\n					<if test=\"registerUsingFb:|:IPSLib::fbc_enabled()\">\n						<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"\" /></a></li>\n					</if>\n					<if test=\"twitterBox:|:IPSLib::twitter_enabled() === true\">\n						<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/twitter/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/twitter_login.png\" alt=\"\" /></a></li>\n					</if>\n				</ul>\n			</div>\n		</if>\n		<br />\n		<div class=\'ipsForm ipsForm_horizontal\'>\n			<fieldset>\n				<ul>\n					<li class=\'ipsField\'>\n						<div class=\'ipsField_content\'>\n							{$this->lang->words[\'register_prompt_1\']} <a href=\"{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\" title=\'{$this->lang->words[\'register_prompt_2\']}\'>{$this->lang->words[\'register_prompt_2\']}</a>\n						</div>\n					</li>\n					<li class=\'ipsField ipsField_primary\'>\n						<label for=\'ips_username\' class=\'ipsField_title\'>{$this->lang->words[\'enter_name\']}</label>\n						<div class=\'ipsField_content\'>\n							<input id=\'ips_username\' type=\'text\' class=\'input_text\' name=\'ips_username\' size=\'30\' />\n						</div>\n					</li>\n					<li class=\'ipsField ipsField_primary\'>\n						<label for=\'ips_password\' class=\'ipsField_title\'>{$this->lang->words[\'enter_pass\']}</label>\n						<div class=\'ipsField_content\'>\n							<input id=\'ips_password\' type=\'password\' class=\'input_text\' name=\'ips_password\' size=\'30\' /><br />\n							<a href=\'{parse url=\"app=core&amp;module=global&amp;section=lostpass\" base=\"public\"}\' title=\'{$this->lang->words[\'retrieve_pw\']}\'>{$this->lang->words[\'login_forgotten_pass\']}</a>\n						</div>\n					</li>\n					<li class=\'ipsField ipsField_checkbox\'>\n						<input type=\'checkbox\' id=\'inline_remember\' checked=\'checked\' name=\'rememberMe\' value=\'1\' class=\'input_check\' />\n						<div class=\'ipsField_content\'>\n							<label for=\'inline_remember\'>\n								<strong>{$this->lang->words[\'rememberme\']}</strong><br />\n								<span class=\'desc lighter\'>{$this->lang->words[\'notrecommended\']}</span>\n							</label>\n						</div>\n					</li>\n					<if test=\"anonymous:|:!$this->settings[\'disable_anonymous\']\">\n						<li class=\'ipsField ipsField_checkbox\'>\n							<input type=\'checkbox\' id=\'inline_invisible\' name=\'anonymous\' value=\'1\' class=\'input_check\' />\n							<div class=\'ipsField_content\'>\n								<label for=\'inline_invisible\'>\n									<strong>{$this->lang->words[\'form_invisible\']}</strong><br />\n									<span class=\'desc lighter\'>{$this->lang->words[\'anon_name\']}</span>\n								</label>\n							</div>\n						</li>\n					</if>\n				</ul>\n			</fieldset>\n			<div class=\'ipsForm_submit ipsForm_center\'>\n				<input type=\'submit\' class=\'ipsButton\' value=\'{$this->lang->words[\'log_in\']}\' />\n			</div>	\n		</div>	\n	</form>\n</div>\n</if>', 'ajax__inlineLogInForm', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('76', '0', 'skin_login', '<p class=\'message error\'>\n	{$data}\n</p>\n<br /><br />', 'errors', '$data=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('77', '0', 'skin_login', '{parse js_module=\"signin\"}\n<div id=\'login_form\' class=\'clearfix\'>\n	\n	<div id=\'member_login\'>\n		<h2 class=\'maintitle\'>{$this->lang->words[\'log_in\']}</h2>\n		<form action=\"{parse url=\"app=core&amp;module=global&amp;section=login&amp;do=process\" base=\"public\"}\" method=\"post\" id=\'login\'>\n			<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n			<if test=\"referer:|:$referer\"><input type=\"hidden\" name=\"referer\" value=\"{$referer}\" /></if>\n			<div id=\'regular_signin\'>\n				<a id=\'_regularsignin\'></a>\n				<h3 class=\'bar\'>{$this->lang->words[\'enter_name_and_pass\']}</h3>\n				<ul class=\'ipsForm ipsForm_vertical ipsPad_double left\'>\n					<li class=\'ipsField\'>\n						<label for=\'ips_username\' class=\'ipsField_title\'>{$this->lang->words[\'enter_name\']}</label>\n						<p class=\'ipsField_content\'>\n							<input id=\'ips_username\' type=\'text\' class=\'input_text\' name=\'ips_username\' size=\'50\' tabindex=\'1\' /><br />\n							<span class=\'desc ipsType_smaller\'>{$this->lang->words[\'register_prompt_1\']} <a href=\'{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\' title=\'{$this->lang->words[\'register_prompt_2\']}\'>{$this->lang->words[\'register_prompt_2\']}</a></span>\n						</p>\n					</li>\n					<li class=\'ipsField\'>\n						<label for=\'ips_password\' class=\'ipsField_title\'>{$this->lang->words[\'enter_pass\']}</label>\n						<p class=\'ipsField_content\'>\n							<input id=\'ips_password\' type=\'password\' class=\'input_text\' name=\'ips_password\' size=\'50\' tabindex=\'2\' /><br />\n							<a href=\'{parse url=\"app=core&amp;module=global&amp;section=lostpass\" base=\"public\"}\' class=\'ipsType_smaller\' title=\'{$this->lang->words[\'retrieve_pw\']}\'>{$this->lang->words[\'login_forgotten_pass\']}</a>\n						</p>\n					</li>\n				</ul>\n				<div class=\'right ipsPad_double\' id=\'other_signin\'>\n					<ul class=\'ipsList_data clear ipsType_small\'>\n						<if test=\"facebook:|:IPSLib::fbc_enabled()\">\n							<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"Facebook\" /></a></li>\n						</if>\n						<if test=\"twitterBox:|:IPSLib::twitter_enabled() === true\">\n							<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/twitter/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/twitter_login.png\" alt=\"Twitter\" /></a></li>\n						</if>\n						\n						<if test=\"hasopenid:|:in_array( \'openid\', $login_methods )\">\n							<li><a href=\'#_openid\' title=\'{$this->lang->words[\'use_openid\']}\' id=\'openid_open\'>{parse replacement=\"openid_small\"} {$this->lang->words[\'have_openid\']}</a></li>\n						</if>\n						<if test=\"haswindowslive:|:in_array( \'live\', $login_methods )\">\n							<li><a href=\'#_live\' title=\'{$this->lang->words[\'use_live\']}\' id=\'live_open\'>{parse replacement=\"live_small\"} {$this->lang->words[\'sign_in_winlive\']}</a></li>\n						</if>\n						<if test=\"extraform:|:is_array($extra_form) AND count($extra_form)\">\n							<foreach loop=\"extrafields:$extra_form as $form_fields\">\n								{$form_fields}\n							</foreach>\n						</if>\n					</ul>\n				</div>\n			</div>\n			<if test=\"openidform:|:in_array( \'openid\', $login_methods )\">\n				<div id=\'openid_signin\'>\n					<a id=\'_openid\'></a>\n					<h3 class=\'bar\'>{$this->lang->words[\'sign_in_openid\']}</h3>\n					<ul class=\'ipsForm_horizontal ipsPad_double left\'>\n						<li class=\'ipsField\'>\n							<label for=\'openid\' class=\'ipsField_title\'>{parse replacement=\"openid_large\"}</label>\n							<p class=\'ipsField_content ipsPad\'>\n								<input id=\'openid\' type=\'text\' class=\'input_text\' name=\'openid_url\' value=\'http://\' size=\'30\' /><br />\n								<span class=\'desc\'>{$this->lang->words[\'openid_example\']}</span>\n							</p>\n						</li>\n					</ul>\n					<p class=\'extra\'><a href=\'#_regularsignin\' title=\'{$this->lang->words[\'regular_signin\']}\' id=\'openid_close\'>{$this->lang->words[\'use_regular\']}</a></p>\n				</div>\n			</if>\n			<if test=\"liveform:|:in_array( \'live\', $login_methods )\">\n				<div id=\'live_signin\'>\n					<a id=\'_live\'></a>\n					<h3 class=\'bar\'>{$this->lang->words[\'sign_in_winlive\']}</h3>\n					<div class=\'ipsPad_double\'>\n						<br />\n						<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;do=process&amp;use_live=1&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' class=\'ipsButton\'>{parse replacement=\"live_large\"} &nbsp;&nbsp;{$this->lang->words[\'signin_with_live\']}</a>\n					</div>\n					<p class=\'extra\'><a href=\'#_regularsignin\' title=\'{$this->lang->words[\'regular_signin\']}\' id=\'live_close\'>{$this->lang->words[\'use_regular\']}</a></p>\n				</div>\n			</if>\n			<hr />\n			<fieldset id=\'signin_options\'>\n				<legend>{$this->lang->words[\'sign_in_options\']}</legend>\n				<ul class=\'ipsForm ipsForm_vertical ipsPad_double\'>\n					<li class=\'ipsField ipsField_checkbox clearfix\'>\n						<input type=\'checkbox\' id=\'remember\' checked=\'checked\' name=\'rememberMe\' value=\'1\' class=\'input_check\' />\n						<p class=\'ipsField_content\'>\n							<label for=\'remember\'>{$this->lang->words[\'rememberme\']}</label><br />\n							<span class=\'desc lighter\'>{$this->lang->words[\'notrecommended\']}</span>\n						</p>\n					</li>\n					<if test=\"anonymous:|:!$this->settings[\'disable_anonymous\']\">\n						<li class=\'ipsField ipsField_checkbox clearfix\'>\n							<input type=\'checkbox\' id=\'invisible\' name=\'anonymous\' value=\'1\' class=\'input_check\' />\n							<p class=\'ipsField_content\'>\n								<label for=\'invisible\'>{$this->lang->words[\'form_invisible\']}</label><br />\n								<span class=\'desc lighter\'>{$this->lang->words[\'anon_name\']}</span>\n							</p>\n						</li>\n					</if>\n				</ul>\n			</fieldset>\n			<fieldset class=\'submit\'>\n				<input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'sign_in_button\']}\' tabindex=\'3\' /> {$this->lang->words[\'or\']} <a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n			</fieldset>\n		</form>\n	</div>\n</div>\n<if test=\"toggleOpenId:|:$this->request[\'serviceClick\'] == \'openid\'\">\n<script type=\'text/javascript\'>\ndocument.observe(\"dom:loaded\", function(e){ ipb.signin.toggleOpenID(e); });\n</script>\n</if>\n<if test=\"toggleLive:|:$this->request[\'serviceClick\'] == \'live\'\">\n<script type=\'text/javascript\'>\ndocument.observe(\"dom:loaded\", function(e){ ipb.signin.toggleLive(e); });\n</script>\n</if>', 'showLogInForm', '$message=\"\",$referer=\"\",$extra_form=\"\", $login_methods=array(), $facebookOpts=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('78', '0', 'skin_modcp', '{parse js_module=\"topic\"}\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n<script type=\'text/javascript\'>\n	ipb.topic.inSection	= \'topicview\';\n</script>\n<style type=\'text/css\'>\n	.post_mod, .post_id { display: none; }\n</style>\n{$this->templateVars[\'test\']}\n<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<if test=\"hasPosts:|:is_array( $posts ) AND count( $posts )\">\n		<div id=\'ips_Posts\'>\n			<foreach loop=\"post_data:$posts as $post\">\n					{parse template=\"modCPpost\" group=\"modcp\" params=\"$post, array( \'sdData\' => $other_data ), $post, \'deleted\'\"}\n			</foreach>\n		</div>\n	<else />\n		<div class=\'no_messages\'>\n			{$this->lang->words[\'no_deleted_posts\']}\n		</div>\n	</if>\n	<div>{$pagelinks}</div>\n</div>', 'deletedPosts', '$posts, $other_data=array(), $pagelinks=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('79', '0', 'skin_modcp', '{parse js_module=\"forums\"}\n<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<table class=\'ipb_table topic_list\' id=\'forum_table\'>\n		<if test=\"hastopics:|:is_array( $topics ) AND count( $topics )\">\n			{parse striping=\"forumTable\" classes=\"row1,row2\"}\n			{parse template=\"modCPtopic\" group=\"modcp\" params=\"$topics, $pagelinks, \'deleted\', $sdelete\"}\n		<else />\n			<tr> \n				<td colspan=\'3\' class=\'no_messages\'>{$this->lang->words[\'no_deleted_topics\']}</td>\n			</tr>\n		</if>\n	</table>\n	<div>{$pagelinks}</div>\n</div>', 'deletedTopics', '$topics, $sdelete=array(), $pagelinks=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('80', '0', 'skin_modcp', '<form action=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'doeditmember\' />\n<input type=\'hidden\' name=\'mid\' value=\'{$profile[\'member_id\']}\' />\n<input type=\"hidden\" name=\"_st\" value=\"{$this->request[\'_st\']}\" />\n<input type=\"hidden\" name=\"t\" value=\"{$this->request[\'t\']}\" />\n<input type=\"hidden\" name=\"pf\" value=\"{$this->request[\'pf\']}\" />\n<style type=\'text/css\'>\n	.cke_contents { height: 100px !important; }\n</style>\n<h2 class=\'maintitle\'>{$this->lang->words[\'cp_em_title\']}: <a href=\'{parse url=\"showuser={$profile[\'_parsedMember\'][\'member_id\']}\" seotitle=\"{$profile[\'_parsedMember\'][\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$profile[\'_parsedMember\'][\'members_display_name\']}</a></h2>\n<div class=\'\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'edit_user_images\']}</h3>\n		<ul class=\'ipsForm ipsForm_horizontal\'>\n			<li class=\'ipsField\'>\n				<label for=\'photo\' class=\'ipsField_title\'>{$this->lang->words[\'cp_remove_photo\']}</label>\n				<p class=\'ipsForm_content\'>\n					<select name=\"photo\" id=\'photo\' class=\'input_select\'>\n						<option value=\"0\">{$this->lang->words[\'no\']}</option>\n						<option value=\"1\">{$this->lang->words[\'yes\']}</option>\n					</select>\n					&nbsp;&nbsp;\n					<img src=\'{$profile[\'_parsedMember\'][\'pp_mini_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_tiny\' />\n				</p>\n			</li>\n		</ul>\n		<if test=\"editusercfields:|:count($custom_fields->out_fields)\">\n			<h3 class=\'bar\'>{$this->lang->words[\'edit_user_profile\']}</h3>\n			<ul class=\'ipsForm ipsForm_horizontal\'>\n				<li class=\'ipsField\'>\n					<label for=\'title\' class=\'ipsField_title\'>{$this->lang->words[\'edit_user_title\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\'text\' class=\"input_text\" name=\'title\' size=\'50\' value=\'{$profile[\'title\']}\' />\n					</p>\n				</li>\n				<foreach loop=\"custom_fields:$custom_fields->out_fields as $id => $data\">\n					<li class=\'ipsField\'>\n						<label for=\'field_{$id}\' class=\'ipsField_title\'>{$custom_fields->field_names[ $id ]}</label>\n						<div class=\'ipsField_content\'>\n							{$data}\n							<if test=\"editusercfielddesc:|:$custom_fields->field_desc[ $id ]\">\n								<br /><span class=\'desc\'>{$custom_fields->field_desc[ $id ]}</span>\n							</if>\n						</div>\n					</li>\n				</foreach>\n			</ul>\n		</if>\n		<h3 class=\'bar\'>{$this->lang->words[\'cp_edit_signature\']}</h3>\n		<div class=\'ipsPad\'>\n			{$profile[\'signature\']}\n		</div>\n		<h3 class=\'bar\'>{$this->lang->words[\'cp_edit_aboutme\']}</h3>\n		<div class=\'ipsPad\'>\n			{$profile[\'aboutme\']}\n		</div>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'cp_em_submit\']}\" />\n	</fieldset>\n</div>\n</form>', 'editUserForm', '$profile, $custom_fields=null', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('81', '0', 'skin_modcp', '<p class=\'message unspecific\'>{$msg}</p>', 'inlineModIPMessage', '$msg=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('82', '0', 'skin_modcp', '<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<table class=\'ipb_table\'>\n		<tr class=\'header\'>\n			<th scope=\'col\'>{$this->lang->words[\'w_v_warnby\']}</th>\n			<th scope=\'col\'>{$this->lang->words[\'w_v_warnto\']}</th>\n			<th scope=\'col\'>{$this->lang->words[\'w_v_notes\']}</th>\n		</tr>\n		<if test=\"haswarnings:|:is_array( $warnings ) AND count( $warnings )\">\n			{parse striping=\"warnings\" classes=\"row1,row2 altrow\"}\n			<foreach loop=\"warningloop:$warnings as $r\">\n				<tr class=\'{parse striping=\"warnings\"}\'>\n					<td>{$r[\'punisher_photo\']} <a href=\'{parse url=\"showuser={$r[\'punisher_id\']}\" base=\"public\" seotitle=\"{$r[\'punisher_seo_name\']}\" template=\"showuser\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$r[\'punisher_name\']}</strong></a></td>\n					<td><img src=\'{$r[\'pp_mini_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' alt=\'\' /> <a href=\'{parse url=\"showuser={$r[\'member_id\']}\" base=\"public\" seotitle=\"{$r[\'members_seo_name\']}\" template=\"showuser\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$r[\'members_display_name\']}</strong></a></td>\n					<td>{$this->lang->words[\'mod_warn_added\']} <strong>{parse date=\"$r[\'wlog_date\']\" format=\"long\" relative=\"false\"}</strong></td>\n				</tr>\n				<tr class=\'{parse striping=\"warnings\"}\'>\n					<td>\n						<span class=\"<if test=\"warnlognote:|:$r[\'wlog_type\'] == \'note\' OR $r[\'wlog_type\'] == \'pos\'\">positive<else />negative</if>\" <if test=\"warnlogcolor:|:$r[\'wlog_type\'] == \'note\' || $r[\'wlog_type\'] == \'nochan\' || $r[\'wlog_type\'] == \'custom\'\">style=\'color:gray\'</if>>\n							<if test=\"warnlognotetype:|:$r[\'wlog_type\'] == \'note\'\">\n								{$this->lang->words[\'mod_warn_note\']}\n							<else />\n								<if test=\"warnlogpos:|:$r[\'wlog_type\'] == \'pos\'\">\n									{$this->lang->words[\'w_v_minus\']}\n								</if>\n								<if test=\"warnlogneg:|:$r[\'wlog_type\'] == \'neg\'\">\n									{$this->lang->words[\'w_v_add\']}\n								</if>\n								<if test=\"warnlognochange:|:$r[\'wlog_type\'] == \'nochan\'\">\n									{$this->lang->words[\'w_v_nochan\']}\n								</if>\n								<if test=\"warnlogcustchange:|:$r[\'wlog_type\'] == \'custom\'\">\n									{$this->lang->words[\'w_v_custom\']}\n								</if>\n							</if>\n						</span>\n					</td>\n					<td colspan=\'2\'>{$r[\'content\']}</td>\n				</tr>\n			</foreach>\n		<else />\n			<tr>\n				<td class=\"no_messages\" colspan=\"3\">{$this->lang->words[\'warn__no_recent\']}</td>\n			</tr>\n		</if>\n	</table>\n	<div>{$pagelinks}</div>\n</div>', 'latestWarnLogs', '$warnings, $pagelinks', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('83', '0', 'skin_modcp', '<if test=\"canEditMember:|:$this->memberData[\'g_is_supmod\']\">\n{parse js_module=\"modcp\"}\n<script type=\'text/javascript\'>\nipb.modcp.initialtext = \"{$this->lang->words[\'start_typing_lup\']}\";\n</script>\n<h2 class=\'maintitle\'>{$this->lang->words[\'memberlookup_title\']}</h2>\n<div class=\'clearfix ipsBox\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'memberlookup_desc\']}</h3>\n		<p class=\'desc\'>{$this->lang->words[\'starttypeingmember\']}</p>\n		<form action=\'#\' method=\'post\' style=\'margin-top: 10px\'>\n			<input type=\'text\' name=\'memberlookup\' id=\'memberlookup\' class=\'input_text\' size=\'50\' />\n		</form>\n	</div>\n	<script type=\'text/javascript\'>\n		$(\'memberlookup\').defaultize( \"{$this->lang->words[\'start_typing_lup\']}\" );\n	</script>\n</div>\n<else />\n<div class=\'clearfix \'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<p>{$this->lang->words[\'intro_blurb\']}</p>\n	</div>\n</div>\n</if>', 'memberLookup', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('84', '0', 'skin_modcp', '<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<div id=\'member_list\' class=\'clear block_wrap\'>\n		<div id=\'member_wrap\'>\n			<ul class=\'ipsMemberList\'>\n				<if test=\"showmembers:|:is_array( $members ) and count( $members )\">\n					{parse striping=\"memberStripe\" classes=\"row1,row2\"}\n					<foreach loop=\"members:$members as $member\">\n						<li id=\'member_id_{$member[\'member_id\']}\' class=\'ipsPad clearfix member_entry {parse striping=\"memberStripe\"}\'>\n							<a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$member[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n							<div class=\'ipsBox_withphoto\'>\n								<ul class=\'ipsList_inline right\'>\n									<if test=\"weAreSupmod:|:$this->memberData[\'g_is_supmod\'] == 1 && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n										<li><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;auth_key={$this->member->form_hash}&amp;mid={$member[\'member_id\']}&amp;pf={$member[\'member_id\']}\" base=\"public\"}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'edit_member\']}</a></li>\n									</if>\n									<if test=\"memberwarn:|:$member[\'warn_percent\'] !== NULL\">\n										<a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;do=view&amp;mid={$member[\'member_id\']}&amp;_tab=warn\" base=\"public\"}\' id=\'warn_link_modcp_{$member[\'member_id\']}\' title=\'{$this->lang->words[\'warn_view_history\']}\' class=\'warn_link ipsButton_secondary\'>{$this->lang->words[\'warn_status\']}</a>\n									</if>\n									<if test=\"sendpm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' ) && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n										<li class=\'pm_button\' id=\'pm_xxx_{$member[\'pp_member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'pp_member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n									</if>\n									<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'gbl_find_my_content\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"find_topics_link\"}</a></li>\n									<if test=\"blog:|:$member[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) AND $member[\'has_blog\'] != \'recache\'\">\n										<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n									</if>\n									<if test=\"gallery:|:$member[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n										<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n									</if>\n								</ul>\n								\n								<h3 class=\'ipsType_subtitle\'>\n									<strong><a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></strong>\n								</h3>\n								<if test=\"repson:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n									<if test=\"norep:|:$member[\'pp_reputation_points\'] == 0 || !$member[\'pp_reputation_points\']\">\n										<p class=\'reputation zero ipsType_small left\'>\n									</if>\n									<if test=\"posrep:|:$member[\'pp_reputation_points\'] > 0\">\n										<p class=\'reputation positive ipsType_small left\'>\n									</if>\n									<if test=\"negrep:|:$member[\'pp_reputation_points\'] < 0\">\n										<p class=\'reputation negative ipsType_small left\'>\n									</if>							\n											<span class=\'number\'>{$member[\'pp_reputation_points\']}</span>\n										</p>\n								</if>\n								<span class=\'desc\'>\n									{$this->lang->words[\'member_joined\']} {parse date=\"$member[\'joined\']\" format=\"joined\"}<br />\n									{IPSMember::makeNameFormatted( $member[\'group\'], $member[\'member_group_id\'] )} &middot; <strong>{$this->lang->words[\'modqueued_til\']}: <if test=\"isnotbanned:|:in_array( $type, array( \'modposts\', \'suspended\', \'restrictposts\' ) )\"><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;mid={$member[\'member_id\']}&amp;_tab=warn&amp;type=minus\" base=\"public\"}\'></if><em>{$member[\'_language\']}</em><if test=\"isnotbanned2:|:in_array( $type, array( \'modposts\', \'suspended\', \'restrictposts\' ) )\"></a></if></strong>\n								</span>\n							</div>\n						</li>\n					</foreach>\n				<else />\n					<p class=\'no_messages\'>{$this->lang->words[\'no_results\']}</p>\n				</if>\n			</ul>\n		</div>\n	</div>\n</div>\n	<div>{$pagelinks}</div>', 'membersList', '$type, $members, $pagelinks=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('85', '0', 'skin_modcp', '<h2 class=\'maintitle\'>{$this->lang->words[\'menu_ipsearch\']}</h2>\n<div class=\'ipsBox clearfix\'>\n	<form id=\"userCPForm\" action=\"{parse url=\"app=core&amp;module=modcp&amp;tab=iplookup&amp;fromapp=members&amp;_do=submit\" base=\"public\"}\" method=\"post\">\n	<fieldset class=\"ipsBox_container ipsPad\">\n		<if test=\"modIpIe:|:$inlineMsg\">\n			{$inlineMsg}\n		</if>\n		<br />\n		\n		<ul class=\'ipsForm ipsForm_horizontal\'>\n			<li class=\'ipsField\'>\n				<label for=\'ipsearch\' class=\'ipsField_title\'>{$this->lang->words[\'ip_enter\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\"text\" size=\"40\" maxlength=\"24\" class=\'input_text\' name=\"ip\" value=\"<if test=\"$ip\">{$ip}<else />{$this->request[\'ip\']}</if>\" />\n					<select name=\"iptool\" class=\'input_select\'>\n						<option value=\"resolve\">{$this->lang->words[\'ip_resolve\']}</option>\n						<option value=\"posts\">{$this->lang->words[\'ip_posts\']}</option>\n						<option value=\"members\">{$this->lang->words[\'ip_members\']}</option>\n					</select>&nbsp;\n					<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'ip_submit\']}\" />\n				</p>\n			</li>\n		</ul>\n		<p class=\'message unspecific\'>\n			{$this->lang->words[\'ip_desc_text\']}\n		</p>\n		<p class=\'desc\'>\n			{$this->lang->words[\'ip_warn_text\']}\n		</p>\n	</fieldset>\n	</form>\n</div>', 'membersModIPForm', '$ip=\"\", $inlineMsg=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('86', '0', 'skin_modcp', '<div class=\'topic_controls\'>\n	{$pages}\n</div>\n<br />\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th style=\'width: 20%\'>{$this->lang->words[\'ipm_name\']}</th>\n		<th style=\'width: 15%\'>{$this->lang->words[\'ipm_ip\']}</th>\n		<th style=\'width: 10%\' class=\'short\'>{$this->lang->words[\'ipm_posts\']}</th>\n		<th style=\'width: 20%\' class=\'short\'>{$this->lang->words[\'ipm_reg\']}</th>\n		<th style=\'width: 15%\'>{$this->lang->words[\'ipm_group\']}</th>\n		<th style=\'width: 10%\'>&nbsp;</th>\n	</tr>\n	<if test=\"modIPMembers:|:is_array( $members ) AND count( $members )\">\n		{parse striping=\"members\" classes=\"row1,row2\"}\n		<foreach loop=\"ipMembers:$members as $id => $row\">\n			<tr class=\'{parse striping=\"members\"}\'>\n				<td><a href=\"{parse url=\"showuser={$row[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$row[\'members_seo_name\']}\"}\">{IPSMember::makeNameFormatted( $row[\'members_display_name\'], $row[\'member_group_id\'] )}</a></td>\n				<td class=\'altrow\'>{$row[\'ip_address\']}</td>\n				<td class=\'short\'>{$row[\'posts\']}</td>\n				<td class=\"altrow short\">{$row[\'joined\']}</td>\n				<td>{$row[\'groupname\']}</td>\n				<td class=\"altrow short\">\n					<a href=\"{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;mid={$row[\'member_id\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\" title=\"{$this->lang->words[\'ipm_edit\']}\" class=\'ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'ipm_edit\']}</a>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<br />\n<div class=\'topic_controls\'>\n	{$pages}\n</div>', 'membersModIPFormMembers', '$pages=\"\",$members', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('87', '0', 'skin_modcp', '<p class=\'message\'>\n	{$this->lang->words[\'ipp_found\']} {$count}\n</p>\n<br />\n<div class=\'topic_controls\'>\n	{$pageLinks}\n</div>\n<br />\n<if test=\"modFindMemberPosts:|:count($results)\">\n	{parse striping=\"posts\" classes=\"row1,row2\"}\n	<foreach loop=\"ipPosts:$results as $result\">\n		<div class=\'post_block ucp no_sidebar {parse striping=\"posts\"}\'>\n			<h3><a href=\'{parse url=\"showtopic={$result[\'topic_id\']}&amp;findpost={$result[\'pid\']}\" template=\"showtopic\" seotitle=\"{$result[\'seo_title\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'modip_viewposts\']}\'>{$result[\'members_display_name\']} | {parse date=\"$result[\'post_date\']\" format=\"long\"}</a></h3>\n			<div class=\'post_body\'>\n				<div class=\'post\'>{$result[\'post\']}</div>\n			</div>\n		</div>\n		<hr />\n	</foreach>\n</if>\n<br />\n<div class=\'topic_controls\'>\n	{$pageLinks}\n</div>', 'membersModIPFormPosts', '$count=0, $pageLinks=\'\', $results', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('88', '0', 'skin_modcp', '<form action=\"{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=save&amp;announce_id={$announce[\'announce_id\']}&amp;type={$type}\" base=\"public\"}\" method=\"post\" id=\'postingform\'>\n<fieldset class=\'row1\'>\n	<h3 class=\'ipsType_subtitle\'><if test=\"buttonlang:|:$type==\'add\'\">{$this->lang->words[\'announce_add\']}<else />{$this->lang->words[\'announce_button_edit\']}</if></h3>\n	<br />\n	<if test=\"announceMessage:|:$msg\">\n		<p class=\'message unspecific\'>{$msg}</p>\n	</if>\n	<ul class=\'ipsForm ipsForm_horizontal\'>\n		<li class=\'ipsField clearfix\'>\n			<label for=\'announce_title\' class=\'ipsField_title\'>{$this->lang->words[\'announce_form_title\']}</label>\n			<p class=\'ipsField_content\'>\n				<input class=\'input_text\' type=\"text\" size=\"50\" name=\"announce_title\" id=\'announce_title\' value=\"{$announce[\'announce_title\']}\" tabindex=\"1\" />\n			</p>\n		</li>\n		<li class=\'ipsField clearfix\'>\n			<label for=\'announce_start\' class=\'ipsField_title\'>{$this->lang->words[\'announce_form_start\']}</label>\n			<p class=\'ipsField_content\'>\n				<input class=\'input_text\' type=\"text\" size=\"10\" name=\"announce_start\" id=\'announce_start\' value=\"{$announce[\'announce_start\']}\" tabindex=\"2\" /><br />\n				<span class=\"desc lighter\">{$this->lang->words[\'announce_form_date\']} {$this->lang->words[\'announce_form_startdesc\']}</span>\n			</p>\n		</li>\n		<li class=\'ipsField clearfix\'>\n			<label for=\'announce_end\' class=\'ipsField_title\'>{$this->lang->words[\'announce_form_end\']}</label>\n			<p class=\'ipsField_content\'>\n				<input class=\'input_text\' type=\"text\" size=\"10\" name=\"announce_end\" id=\'announce_end\' value=\"{$announce[\'announce_end\']}\" tabindex=\"2\" /><br />\n				<span class=\"desc lighter\">{$this->lang->words[\'announce_form_date\']} {$this->lang->words[\'announce_form_enddesc\']}</span>\n			</p>				\n		</li>\n		<li class=\'ipsField clearfix\'>\n			<label for=\'announce_forum\' class=\'ipsField_title\'>{$this->lang->words[\'announce_form_forums\']}</label>\n			<p class=\'ipsField_content\'>\n				<select class=\"input_select\" multiple=\"multiple\" size=\"10\" id=\'announce_forum\' name=\"announce_forum[]\" tabindex=\"4\">{$forum_html}</select><br />\n				<span class=\"desc lighter\">{$this->lang->words[\'announce_form_forums2\']}</span>\n			</p>\n		</li>\n		<li class=\'ipsField clearfix\'>\n			<label for=\'\' class=\'ipsField_title\'>{$this->lang->words[\'announce_form_announce\']}</label>\n			<div class=\'ipsField_content\'>\n				{$editor_html}\n			</div>\n		</li>\n		<li class=\'ipsField ipsField_checkbox\'>\n			<input type=\"checkbox\" class=\"checkbox\" name=\"announce_active\" id=\'announce_active\' value=\"1\" {$announce[\'announce_active_checked\']} />\n			<p class=\'ipsField_content\'>\n				<label for=\'announce_active\'>{$this->lang->words[\'announce_form_enable\']}</label>\n			</p>\n		</li>\n		<li class=\'ipsField ipsField_checkbox\'>\n			<input type=\"checkbox\" class=\"checkbox\" name=\"announce_html_enabled\" id=\'announce_html_enabled\' value=\"1\" {$announce[\'html_checkbox\']} />\n			<p class=\'ipsField_content\'>\n				<label for=\'announce_html_enabled\'>{$this->lang->words[\'announce_use_html\']}</label>\n			</p>\n		</li>\n		<li class=\'ipsField ipsField_checkbox\'>\n			<input type=\"checkbox\" class=\"checkbox\" name=\"announce_nlbr_enabled\" id=\'announce_nlbr_enabled\' value=\"1\" {$announce[\'nlbr_checkbox\']} />\n			<p class=\'ipsField_content\'>\n				<label for=\'announce_nlbr_enabled\'>{$this->lang->words[\'announce_use_nlbr\']}</label>\n			</p>\n		</li>\n	</ul>\n</fieldset>\n<br />\n<fieldset class=\'submit\'>\n	<input type=\"submit\" value=\"<if test=\"buttonlang:|:$type==\'add\'\">{$this->lang->words[\'announce_add\']}<else />{$this->lang->words[\'announce_button_edit\']}</if>\" class=\"input_submit\" tabindex=\"7\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel_edit\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n</fieldset>\n</form>', 'modAnnounceForm', '$announce,$forum_html,$type,$editor_html,$msg=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('89', '0', 'skin_modcp', '{parse js_module=\"ucp\"}\n<form action=\"{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=save\" base=\"public\"}\" id=\"mutliact\" method=\"post\">\n<div class=\'topic_buttons\'>\n	<ul class=\'topic_controls\'>\n		<li>\n			<a href=\"{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=add\" base=\"public\"}\" class=\'ipsButton\'>{$this->lang->words[\'announce_add\']}</a>\n		</li>\n	</ul>\n</div>\n	<h3 class=\'maintitle clear\'>{$this->lang->words[\'announce_current\']}</h3>\n	<table class=\'ipb_table\' summary=\"{$this->lang->words[\'ucp_announcements\']}\">\n		<tr class=\'header\'>\n			<th scope=\'col\' style=\"width: 40%\">{$this->lang->words[\'announce_title\']}</th>\n			<th scope=\'col\' class=\'short\' style=\"width: 10%\">{$this->lang->words[\'announce_form_starts\']}</th>\n			<th scope=\'col\' class=\'short\' style=\"width: 10%\">{$this->lang->words[\'announce_form_end\']}</th>\n			<th scope=\'col\' style=\"width: 25%\">{$this->lang->words[\'announce_forums\']}</th>\n			<th scope=\'col\' style=\"width: 15%\">&nbsp;</th>\n		</tr>\n		<if test=\"hasAnnouncements:|:is_array( $announcements ) AND count( $announcements )\">\n			{parse striping=\"announcements\" classes=\"row1,row2\"}\n			<foreach loop=\"announcements:$announcements as $announce\">\n				<tr class=\"{parse striping=\"announcements\"} <if test=\"notactive:|:!$announce[\'announce_active\']\">moderated</if>\">\n					<td>\n						<strong><a href=\"{parse url=\"showannouncement={$announce[\'announce_id\']}&amp;f=0\" base=\"public\" template=\"showannouncement\" seotitle=\"{$announce[\'announce_seo_title\']}\"}\">{$announce[\'announce_title\']}</a></strong> <if test=\"notactive:|:!$announce[\'announce_active\']\"><span class=\'desc\'>{$this->lang->words[\'announce_page_disabled\']}</span></if><br /><span class=\"desc\">{$this->lang->words[\'by_ucfirst\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$announce\"}</span>\n					</td>\n					<td class=\"short\">\n						{parse date=\"$announce[\'announce_start\']\" format=\"DATE\" relative=\"false\"}\n					</td>\n					<td class=\"short\">\n						{parse date=\"$announce[\'announce_end\']\" format=\"DATE\" relative=\"false\"}\n					</td>\n					<td>\n						<div class=\"forumdesc\">\n							<if test=\"announceForum:|:$announce[\'announce_forum\'] == \'*\'\">\n								{$this->lang->words[\'announce_page_allforums\']}\n							<else />\n								<if test=\"announceHasForums:|:is_array( $announce[\'_forums\'] ) and count( $announce[\'_forums\'] )\">\n									<ul>\n									<foreach loop=\"announce_forums:$announce[\'_forums\'] as $forum\">\n										<li><a href=\"{parse url=\"showforum={$forum[0]}\" base=\"public\"}\">{$forum[1]}</a></li>\n									</foreach>\n									</ul>\n								<else />\n									{$announce[\'announce_forum_show\']}\n								</if>\n							</if>\n						</div>\n					</td>\n					<td class=\"short\">\n						<ul class=\'ipsList_inline ipsList_nowrap\'>\n							<li>\n								<a href=\"{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=edit&amp;announce_id={$announce[\'announce_id\']}\" base=\"public\"}\" class=\'ipsButton_secondary\'>{$this->lang->words[\'announce_edit\']}</a>\n							</li>\n							<li>\n								<a href=\"{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=delete&amp;announce_id={$announce[\'announce_id\']}\" base=\"public\"}\" id=\"del_{$announce[\'announce_id\']}\" class=\'ipsButton_secondary\'>{$this->lang->words[\'announce_delete\']}</a>\n							</li>\n						</ul>\n						<script type=\'text/javascript\'>\n							$(\'del_{$announce[\'announce_id\']}\').observe(\'click\', ipb.ucp.deleteAnnouncement.bindAsEventListener( this, {$announce[\'announce_id\']} ) );\n						</script>\n					</td>\n				</tr>\n			</foreach>\n		<else />\n			<tr>\n				<td align=\"center\" colspan=\"5\">{$this->lang->words[\'announce_none\']}</td>\n			</tr>\n		</if>\n	</table>\n</form>', 'modAnnouncements', '$announcements', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('90', '0', 'skin_modcp', '<h1 class=\'ipsType_pagetitle\'>{parse expression=\"sprintf( $this->lang->words[\'modcp_editing_h1\'], $return[\'members_display_name\'] )\"}</h1>\n<if test=\"fromprofile:|:$this->request[\'pf\']\">\n	<a href=\'{parse url=\"showuser={$return[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$return[\'members_seo_name\']}\"}\'>{$this->lang->words[\'_larr\']} {parse expression=\"sprintf( $this->lang->words[\'go_back_profile\'], $return[\'members_display_name\'] )\"}</a>\n<else />\n	<if test=\"fromprofile:|:$this->request[\'t\']\">\n		<a href=\'{parse url=\"showtopic={$return[\'tid\']}\" base=\"public\" template=\"showtopic\" seotitle=\"{$return[\'title_seo\']}\"}\'>{$this->lang->words[\'_larr\']} {parse expression=\"sprintf( $this->lang->words[\'go_back_general\'], $return[\'title\'] )\"}</a>\n	<else />\n		<a href=\'{parse url=\"app=core&amp;module=modcp\" base=\"public\"}\'>{$this->lang->words[\'_larr\']} {$this->lang->words[\'go_back_modcp\']}</a>\n	</if>\n</if>\n<br /><br />\n<div class=\'ipsBox clear vcard\' id=\'profile_background\'>\n	<div class=\'ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_smallleft clearfix\'>\n		<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\' id=\'modcp_tabs\'>\n			<ul class=\'modcp_tabs\'>\n				<if test=\"issupermod:|:$editmember\">\n					<li id=\'editmember_tab\'<if test=\"isEditActive:|:empty($this->request[\'_tab\'])\"> class=\'active\'</if>><a href=\'#\'>{$this->lang->words[\'editmember_tab\']}</a></li>\n				</if>\n				<if test=\"warnenabled:|:$this->settings[\'warn_on\']\">\n					<li id=\'warnpanel_tab\'<if test=\"isWarnActive:|:(!empty($this->request[\'_tab\']) AND $this->request[\'_tab\'] == \'warn\') OR !$editmember\"> class=\'active\'</if>><a href=\'#\'>{$this->lang->words[\'warnpanel_tab\']}</a></li>\n					<li id=\'warnlogs_tab\'<if test=\"isLogActive:|:!empty($this->request[\'_tab\']) AND $this->request[\'_tab\'] == \'warnlogs\'\"> class=\'active\'</if>><a href=\'#\'>{$this->lang->words[\'warnlog_tab\']}</a></li>\n					<li id=\'noteform_tab\'<if test=\"isNotesActive:|:!empty($this->request[\'_tab\']) AND $this->request[\'_tab\'] == \'noteform\'\"> class=\'active\'</if>><a href=\'#\'>{$this->lang->words[\'addnote_tab\']}</a></li>\n				</if>\n			</ul>\n		</div>\n		<div class=\'ipsVerticalTabbed_content ipsLayout_content ipsBox_container\' id=\'profile_content\'>\n			<div class=\'ipsPad\'>\n				<if test=\"issupermodpane:|:$editmember\">\n					<div id=\'editmember_pane\' <if test=\"isEditPaneActive:|:!empty($this->request[\'_tab\']) AND in_array( $this->request[\'_tab\'], array(\'warn\',\'warnlogs\',\'noteform\') )\">style=\'display: none\'</if>>\n						{$editmember}\n					</div>\n				</if>\n				<if test=\"warnenabledpane:|:$this->settings[\'warn_on\']\">\n					<div id=\'warnpanel_pane\' <if test=\"isWarnActive:|:(empty($this->request[\'_tab\']) OR $this->request[\'_tab\'] != \'warn\') AND $editmember\">style=\'display: none\'</if>>\n						{$warnpanel}\n					</div>\n					<div id=\'warnlogs_pane\' <if test=\"isWarnActive:|:empty($this->request[\'_tab\']) OR $this->request[\'_tab\'] != \'warnlogs\'\">style=\'display: none\'</if>>\n						{$warnlogs}\n					</div>\n					<div id=\'noteform_pane\' <if test=\"isWarnActive:|:empty($this->request[\'_tab\']) OR $this->request[\'_tab\'] != \'noteform\'\">style=\'display: none\'</if>>\n						{$noteForm}\n					</div>\n				</if>\n			</div>\n		</div>\n	</div>\n</div>\n<script type=\'text/javascript\'>\n(function(){\n	var currentTab = $(\'modcp_tabs\').select(\"li.active\")[0];\n	\n	if( !currentTab )\n	{\n		currentTab = $(\'modcp_tabs\').select(\'li\')[0];\n	}\n	var togglePane = function(e, elem){\n		if(e){ Event.stop(e) }\n		\n		if( currentTab ){\n			if( getId( currentTab.id ) == getId( elem.id ) ){\n				return;\n			}\n			\n			$( getId( currentTab.id ) + \'_pane\' ).fade({duration: 0.3});\n		}\n		\n		var newPane = $( getId( elem.id ) + \'_pane\' );\n		$( newPane ).appear({duration: 0.3});\n		\n		$(\'modcp_tabs\').select(\"li\").invoke(\"removeClassName\", \'active\');\n		\n		$(elem).addClassName(\'active\');\n		currentTab = elem;\n	};\n	\n	var getId = function( id ){\n		return id.replace(/\\_pane|\\_tab/g, \'\');\n	};\n	\n	$(\'modcp_tabs\').on(\'click\', \'li\', togglePane);\n	togglePane( null, currentTab );\n})();\n	\n</script>', 'modControls', '$editmember, $warnpanel, $warnlogs, $noteForm, $return', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('91', '0', 'skin_modcp', '<!--post:{$post[\'post\'][\'pid\']}-->\n<script type=\"text/javascript\">\nvar pid = parseInt({$post[\'post\'][\'pid\']});\nif ( pid > ipb.topic.topPid ){\n	ipb.topic.topPid = pid;\n}\n</script>\n<if test=\"\">\n<div class=\'post_block hentry clear no_sidebar <if test=\"reputation:|:$this->settings[\'reputation_enabled\']\">with_rep</if>\' id=\'post_id_{$post[\'post\'][\'pid\']}\'>\n	<a id=\'entry{$post[\'post\'][\'pid\']}\'></a>\n	<if test=\"repIgnored:|:!empty( $post[\'post\'][\'_repignored\'] ) AND $post[\'post\'][\'_repignored\'] == 1 && $post[\'post\'][\'_ignored\'] != 1\">\n		<div class=\'post_ignore\'>\n			<if test=\"noRep:|:$post[\'post\'][\'rep_points\'] == 0\">\n				<span class=\'reputation zero\' title=\'{$this->lang->words[\'top_rep\']}\'>\n			</if>\n			<if test=\"posRep:|:$post[\'post\'][\'rep_points\'] > 0\">\n				<span class=\'reputation positive\' title=\'{$this->lang->words[\'top_rep\']}\'>\n			</if>\n			<if test=\"negRep:|:$post[\'post\'][\'rep_points\'] < 0\">\n				<span class=\'reputation negative\' title=\'{$this->lang->words[\'top_rep\']}\' >\n			</if>\n					{$post[\'post\'][\'rep_points\']}</span> {$this->lang->words[\'top_this_post_by\']} <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {$this->lang->words[\'top_below_thresh\']}. <a href=\'#\' title=\'{$this->lang->words[\'ignore_view_post\']}\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n		</div>\n	</if>\n	\n	<div class=\'post_wrap\'>\n		<if test=\"postMid:|:$post[\'author\'][\'member_id\']\">\n			<h3 class=\'row2\'>\n		<else />\n			<h3 class=\'guest row2\'>\n		</if>\n				<if test=\"postModCheckbox:|:$this->memberData[\'is_mod\']\">\n				<!--<span class=\'right\'>\n					<label for=\'checkbox_{$post[\'post\'][\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$post[\'post\'][\'pid\']}\' name=\'selectedpids[]\' value=\'{$post[\'post\'][\'pid\']}\' class=\'post_mod right\'<if test=\"postModSelected:|:!empty( $post[\'post\'][\'_pid_selected\'] )\"> checked=\'checked\'</if> />\n				</span>-->\n				</if>\n				<img src=\'{$post[\'author\'][\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_tiny\' />&nbsp;\n				<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n					<span class=\"author vcard\">{parse template=\"userHoverCard\" group=\"global\" params=\"$post[\'author\']\"}</span>\n				<else />\n					{$post[\'author\'][\'members_display_name\']}\n				</if>\n				\n				<if test=\"postIp:|:$post[\'post\'][\'_show_ip\']\">\n					<span class=\'ip right ipsType_small\'>({$this->lang->words[\'ip\']}:\n					<if test=\"postAdmin:|:$post[\'author\'][\'g_access_cp\']\">\n						<em>{$this->lang->words[\'ip_private\']}</em>\n					<else />\n						<a href=\"{parse url=\"app=core&amp;module=modcp&amp;tab=iplookup&amp;fromapp=members&amp;_do=submit&amp;ip={$post[\'post\'][\'ip_address\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'info_about_this_ip\']}\'>{$post[\'post\'][\'ip_address\']}</a>\n					</if>)\n					</span>\n				</if>\n			</h3>\n		\n		<div class=\'post_body\'>\n			<if test=\"isDeleted:|:$type == \'deleted\'\">\n				<ul class=\'ipsList_inline\'>\n					\n				</ul>\n				<ul class=\'ipsList_inline modcp_post_controls\'>\n					<if test=\"postIsHardDeleted:|:!$post[\'post\'][\'_isDeleted\']\">\n						<li>\n							<img data-tooltip=\"{$this->lang->words[\'hard_delete_warn_post\']}\" src=\'{$this->settings[\'img_url\']}/icon_timewarning.png\' />\n						</li>\n					</if>\n					<li>\n						<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=p_hrestore&amp;f={$post[\'post\'][\'forum_id\']}&amp;t={$post[\'post\'][\'topic_id\']}&amp;pid[]={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' class=\'ipsButton_secondary ipsType_smaller\' title=\'{$this->lang->words[\'restore_post_desc\']}\'>{$this->lang->words[\'restore_post\']}</a>\n					</li>\n					<li>\n						<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=p_hdelete&amp;f={$post[\'post\'][\'forum_id\']}&amp;t={$post[\'post\'][\'topic_id\']}&amp;pid[]={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' class=\'ipsButton_secondary ipsType_smaller\' title=\'{$this->lang->words[\'restore_post_desc\']}\'>{$this->lang->words[\'perm_delete_post\']}</a>\n					</li>\n					<li class=\'desc\'>\n						<strong>{$this->lang->words[\'posted\']}</strong> <span class=\'desc lighter\'>{parse date=\"$post[\'post\'][\'post_date\']\" format=\"short\"}</span>\n					</li>\n					<li class=\'desc\'>\n						<strong>{$this->lang->words[\'deleted_post_date\']}</strong> <span class=\'desc lighter\'>{parse date=\"$topic[\'post\'][\'pdelete_time\']\" format=\"short\"}</span>\n					</li>\n					<li class=\'desc\'>\n						<strong>{$this->lang->words[\'delete_from_topic\']}</strong> <a class=\'desc lighter\' href=\'{parse url=\"showtopic={$topic[\'post\'][\'tid\']}\" seotitle=\"{$topic[\'post\'][\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'go_to_topic\']}\'>{IPSText::truncate( $topic[\'post\'][\'title\'], 25 )}</a>\n					</li>\n				</ul>\n			</if>\n			<if test=\"isUnapproved:|:$type == \'unapproved\'\">\n				<ul class=\'ipsList_inline\'>\n					\n				</ul>\n				<ul class=\'ipsList_inline modcp_post_controls\'>\n					<if test=\"canEdit:|:$post[\'post\'][\'_can_edit\'] === TRUE\">\n						<li class=\'post_edit\'><a href=\'{parse url=\"app=forums&amp;module=post&amp;section=post&amp;do=edit_post&amp;f={$post[\'post\'][\'forum_id\']}&amp;t={$post[\'post\'][\'topic_id\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;return=modcp:unapproved\" base=\"public\"}\' title=\'{$this->lang->words[\'post_edit_title\']}\' class=\'ipsButton_secondary ipsType_smaller\' id=\'edit_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'post_edit\']}</a></li>\n					</if>\n					<!-- Matt: Approve / unapprove post button -->\n					<if test=\"approvePost:|:$this->memberData[\'is_mod\']\">\n						<li id=\'toggle_post_{$post[\'post\'][\'pid\']}\'>\n							<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=postchoice&amp;tact=approve&amp;selectedpids[{$post[\'post\'][\'pid\']}]={$post[\'post\'][\'pid\']}&amp;t={$post[\'post\'][\'topic_id\']}&amp;f={$post[\'post\'][\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:unapproved\" base=\"public\"}\' title=\'{$this->lang->words[\'post_toggle_visible\']}\' class=\'ipsButton_secondary ipsType_smaller\'><span id=\'toggletext_post_{$post[\'post\'][\'pid\']}\'><if test=\"approveUnapprove:|:$post[\'post\'][\'queued\']==1\">{$this->lang->words[\'post_approve\']}<else />{$this->lang->words[\'post_unapprove\']}</if></span></a>\n						</li>\n					</if>\n					<if test=\"canDelete:|:$post[\'post\'][\'_can_delete\'] === TRUE OR $post[\'post\'][\'_softDelete\']\">\n						<li class=\'post_del\' id=\'del_post_{$post[\'post\'][\'pid\']}\'>\n							<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=04&amp;f={$post[\'post\'][\'forum_id\']}&amp;t={$post[\'post\'][\'topic_id\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:unapproved\" base=\"public\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'delete_post ipsButton_secondary important ipsType_smaller\'>{$this->lang->words[\'post_delete\']}</a>\n						</li>\n					</if>\n					<if test=\"reportedPostData:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n						<img src=\"{$this->settings[\'img_url\']}/reports/post_alert_{$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\']][\'gfx\']}.png\" alt=\"\" class=\'ipbmenu clickable\' id=\'post-report-{$post[\'post\'][\'pid\']}\' />\n					</if>\n					<li class=\'desc\'>\n						<strong>{$this->lang->words[\'posted\']}</strong> <span class=\'desc lighter\'>{parse date=\"$post[\'post\'][\'post_date\']\" format=\"short\"}</span>\n					</li>\n					<li class=\'desc\'>\n						<strong>{$this->lang->words[\'in_topic\']}</strong> <a class=\'desc lighter\' href=\'{parse url=\"showtopic={$topic[\'post\'][\'tid\']}\" seotitle=\"{$topic[\'post\'][\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\'>{IPSText::truncate( $topic[\'post\'][\'title\'], 35 )}</a>\n					</li>\n				</ul>\n			</if>\n			<!--<p class=\'posted_info desc lighter blend_links ipsType_small\'>\n				{$this->lang->words[\'posted\']} <abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $post[\'post\'][\'post_date\'] )\"}\">{parse date=\"$post[\'post\'][\'post_date\']\" format=\"long\"}</abbr>\n			</p>-->\n			<div class=\'post entry-content <if test=\"$post[\'post\'][\'_repignored\'] == 1\">imgsize_ignore</if>\'>\n				{$post[\'post\'][\'post\']}\n				{$post[\'post\'][\'attachmentHtml\']}\n				<br />\n				<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n					<p class=\'edit\'>\n						{$post[\'post\'][\'edit_by\']}\n						<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n							<br />\n							<span class=\'reason\'>{$this->lang->words[\'reason_for_edit\']} {$post[\'post\'][\'post_edit_reason\']}</span>\n						</if>\n					</p>\n				</if>\n			</div>\n						\n				<br />\n		</div>\n			\n				<script type=\'text/javascript\'>\n					if( $(\'toggle_post_{$post[\'post\'][\'pid\']}\') ){\n						$(\'toggle_post_{$post[\'post\'][\'pid\']}\').show();\n					}\n					\n					// Add perm data\n					ipb.topic.deletePerms[{$post[\'post\'][\'pid\']}] = { \'canDelete\' : {parse expression=\"intval($post[\'post\'][\'_can_delete\'])\"}, \'canSoftDelete\' : {parse expression=\"intval($post[\'post\'][\'_softDelete\'])\"} };\n				</script>\n				<if test=\"reportedPostData:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n					<ul id=\'post-report-{$post[\'post\'][\'pid\']}_menucontent\' class=\'ipbmenu_content report_menu\' style=\'display: none\'>\n						<li><a href=\"{parse url=\"app=core&amp;module=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'info\'][\'id\']}\" base=\"public\"}\" id=\'report_mark_{$post[\'post\'][\'pid\']}\'><img src=\'{$this->settings[\'img_url\']}/reports/mark_complete.png\' alt=\'\' /> {$this->lang->words[\'report_menu_mark_complete\']}</a></li>\n						<li><a href=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;section=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']}\"><img src=\'{$this->settings[\'img_url\']}/reports/view_report.png\' alt=\'\' /> {$this->lang->words[\'report_menu_view_report\']}</a></li>\n					</ul>\n					<script type=\"text/javascript\">\n						$(\'report_mark_{$post[\'post\'][\'pid\']}\').observe(\'click\',\n						 	ipb.global.updateReportStatus.bindAsEventListener( 	\n								this, {$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']},2,2\n							)\n						);\n					</script>\n				</if>\n			</div>		\n		</div>\n		</if>', 'modCPpost', '$post, $displayData, $topic, $type', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('92', '0', 'skin_modcp', '<foreach loop=\"topics:$topics as $tid => $data\">\n	<tr class=\'__topic\' id=\'trow_{$data[\'tid\']}\' data-tid=\"{$data[\'tid\']}\">\n		<td class=\'__tid{$data[\'tid\']} with_mod_links\'>	\n			<if test=\"isLink:|:$data[\'state\'] == \'link\'\">\n				{$this->lang->words[\'moved_topic_link\']}\n				<em>\n			</if>		\n			<a id=\"tid-link-{$data[\'tid\']}\" href=\"{parse url=\"showtopic={$data[\'tid\']}\" base=\"public\" template=\"showtopic\" seotitle=\"{$data[\'title_seo\']}\"}\" title=\'{$this->lang->words[\'topic_started_on\']} {parse date=\"$data[\'start_date\']\" format=\"LONG\"}\' class=\'topic_title\'>{$data[\'title\']}</a>\n			<if test=\"isLinkEnd:|:$data[\'state\'] == \'link\'\">\n				</em>\n			</if>\n			<if test=\"multipages:|:isset( $data[\'pages\'] ) AND is_array( $data[\'pages\'] ) AND count( $data[\'pages\'] )\">\n				<ul class=\'mini_pagination\'>\n				<foreach loop=\"pages:$data[\'pages\'] as $page\">\n						<if test=\"haslastpage:|:$page[\'last\']\">\n							<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']} {$this->lang->words[\'_rarr\']}</a></li>\n						<else />\n							<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']}</a></li>\n						</if>\n				</foreach>\n				</ul>\n			</if>\n			<br />\n			<if test=\"isntLink:|:$data[\'state\'] != \'link\'\">\n				<ul class=\'ipsList_inline\'>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_startedby\']}</strong> <span class=\'desc lighter blend_links\'><if test=\"hasStarterId:|:$data[\'starter_id\']\">{parse template=\"userHoverCard\" group=\"global\" params=\"$data\"}<else />{$data[\'starter\']}</if></span>\n					</li>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_posted\']}</strong> <span class=\'desc lighter\'>{parse date=\"$data[\'start_date\']\" format=\"short\"}</span>\n					</li>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_inforum\']}</strong> <span class=\'desc lighter\'><a href=\'{parse url=\"showforum={$data[\'forum\'][\'id\']}\" template=\"showforum\" seotitle=\"{$data[\'forum\'][\'name_seo\']}\" base=\"public\"}\'>{$data[\'forum\'][\'name\']}</a></span>\n					</li>\n				</ul>\n			<else />\n				<ul class=\'ipsList_inline\'>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_link_from\']}</strong>\n						<span class=\'desc lighter\'><a href=\'{parse url=\"showforum={$data[\'_toForum\'][\'id\']}\" template=\"showforum\" seotitle=\"{$data[\'_toForum\'][\'name_seo\']}\" base=\"public\"}\'>{$data[\'_toForum\'][\'name\']}</a></span>\n					</li>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_link_to\']}</strong>\n						<span class=\'desc lighter\'><a href=\'{parse url=\"showforum={$data[\'forum\'][\'id\']}\" template=\"showforum\" seotitle=\"{$data[\'forum\'][\'name_seo\']}\" base=\"public\"}\'>{$data[\'forum\'][\'name\']}</a></span>\n					</li>\n				</ul>\n			</if>\n			<if test=\"topicDeletedReason:|:$data[\'_isDeleted\']\">\n				<ul class=\'ipsList_inline\'>\n					<li class=\'desc lighter\'>\n						<strong>{$this->lang->words[\'dlt_topic_deletedby\']}</strong> <span class=\'desc lighter blend_links\'>{parse template=\"userHoverCard\" group=\"global\" params=\"$sdelete[ $data[\'tid\'] ]\"}</span>\n					</li>\n					<if test=\"showReason:|:$data[\'permissions\'][\'SoftDeleteReason\']\">\n						<li class=\'desc lighter\'>\n							<strong>{$this->lang->words[\'dlt_topic_reason\']}</strong> <span class=\'desc lighter\'>{$sdelete[ $data[\'tid\'] ][\'sdl_obj_reason\']}<else />{$this->lang->words[\'tdb__noreasongi\']}</span>\n						</li>\n					</if>\n				</span>\n			</if>\n		</td>\n		<td>\n			<if test=\"isntLink3:|:$data[\'state\'] == \'link\'\">\n				<span class=\'desc\'>{parse format_number=\"$data[\'posts\']\"} <if test=\"replylang:|:intval($data[\'posts\']) == 1\">{$this->lang->words[\'reply\']}<else />{$this->lang->words[\'replies\']}</if></span>\n			</if>\n		</td>\n		<td>\n			<ul class=\'ipsList_inline right\'>\n				<if test=\"$type == \'deleted\'\">\n					<if test=\"isntLink4:|:$data[\'state\'] == \'link\'\">\n						<if test=\"tidRestore:|:$data[\'permissions\'][\'TopicSoftDeleteRestore\']\">\n							<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=topic_restore&amp;t={$data[\'real_tid\']}&amp;f={$data[\'_toForum\'][\'id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' title=\'{$this->lang->words[\'restore_topic_desc\']}\' class=\'ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'restore_topic\']}</a></li>\n						</if>\n						<if test=\"$this->memberData[\'g_is_supmod\'] == 1 || $this->memberData[\'forumsModeratorData\'][ $data[\'forum_id\'] ][\'delete_topic\']\">\n							<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=09&amp;t={$data[\'real_tid\']}&amp;f={$data[\'_toForum\'][\'id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' title=\'{$this->lang->words[\'dlt_delete_topic\']}\' class=\'ipsButton_secondary ipsType_smaller important\'>{$this->lang->words[\'perm_delete_topic\']}</a></li>\n						</if>\n					<else />\n						<if test=\"topicIsHardDeleted:|:!$data[\'_isDeleted\']\">\n							<li>\n								<img data-tooltip=\"{$this->lang->words[\'hard_delete_warn_topic\']}\" src=\'{$this->settings[\'img_url\']}/icon_timewarning.png\' />\n							</li>\n						</if>\n						<if test=\"tidRestore:|:$data[\'permissions\'][\'TopicSoftDeleteRestore\']\">\n							<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=topic_restore&amp;t={$data[\'real_tid\']}&amp;f={$data[\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' title=\'{$this->lang->words[\'restore_topic_desc\']}\' class=\'ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'restore_topic\']}</a></li>\n						</if>\n						<if test=\"$this->memberData[\'g_is_supmod\'] == 1 || $this->memberData[\'forumsModeratorData\'][ $data[\'forum_id\'] ][\'delete_topic\']\">\n							<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=09&amp;t={$data[\'real_tid\']}&amp;f={$data[\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:deleted\" base=\"public\"}\' title=\'{$this->lang->words[\'dlt_delete_topic\']}\' class=\'ipsButton_secondary ipsType_smaller important\'>{$this->lang->words[\'perm_delete_topic\']}</a></li>\n						</if>\n					</if>\n				</if>\n				<if test=\"$type == \'unapproved\'\">\n					<li>\n						<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=topic_approve&amp;t={$data[\'real_tid\']}&amp;f={$data[\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:unapproved\" base=\"public\"}\' class=\'ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'modcp_approvelink\']}</a>\n					</li>\n					<li>\n						<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=03&amp;t={$data[\'real_tid\']}&amp;f={$data[\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;return=modcp:unapproved\" base=\"public\"}\' class=\'ipsButton_secondary ipsType_smaller important\'>{$this->lang->words[\'modcp_deletelink\']}</a>\n					</li>\n				</if>\n			</ul>\n		</td>\n	</tr>\n</foreach>', 'modCPtopic', '$topics, $pagelinks, $type, $sdelete=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('93', '0', 'skin_modcp', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'modcp_page_title\']}</h1>\n<br />\n<div class=\'ipsBox\'>\n	<div class=\'ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_smallleft clearfix\'>\n		<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\' id=\'modcp_tabs\'>\n			<ul class=\'clear\'>\n				<li id=\'index\' class=\'<if test=\"$_activeNav[\'primary\'] == \'index\' && $_activeNav[\'secondary\'] == \'index\'\">active </if>tab_toggle\'>\n					<a href=\'{parse url=\"app=core&amp;module=modcp\" base=\"public\"}\'>{$this->lang->words[\'modcp_tab_index\']}</a>\n				</li>\n				<if test=\"accessRC:|:IPSMember::isInGroup( $this->memberData, explode( \',\', IPSText::cleanPermString( $this->settings[\'report_mod_group_access\'] ) ) )\">\n					<li id=\'reported_content\' class=\'<if test=\"$_activeNav[\'primary\'] == \'reported_content\' && $_activeNav[\'secondary\'] == \'reports\'\">active </if>tab_toggle\'>\n						<a href=\'{parse url=\"app=core&amp;module=reports&amp;do=index\" base=\"public\"}\'>{$this->lang->words[\'modcp_tab_reports\']}</a>\n					</li>\n				</if>\n				<foreach loop=\"tabs:$tabs as $mainTabKey => $subTabs\">\n					<li id=\'{$mainTabKey}\' class=\'<if test=\"$_activeNav[\'primary\'] == $mainTabKey\">active </if>tab_toggle\' data-tabid=\'{$mainTabKey}\'>\n						<a href=\'{parse url=\"app=core&amp;module=modcp&amp;fromapp={$subTabs[0][1]}&amp;tab={$subTabs[0][0]}\" base=\"public\"}\'>{$this->lang->words[\'modcp_mtab_\' . $mainTabKey ]}</a>\n					</li>\n				</foreach>\n			</ul>\n		</div>\n		<div class=\'ipsVerticalTabbed_content ipsLayout_content ipsBox_container\' id=\'modcp_content\'>\n			<div class=\'ipsPad\'>\n				{$output}\n			</div>\n		</div>\n	</div>\n</div>\n<script type=\'text/javascript\'>\n	$(\"modcp_content\").setStyle( { minHeight: $(\'modcp_tabs\').measure(\'margin-box-height\') + 5 + \"px\" } );\n</script>', 'portalPage', '$output, $tabs=array(), $_activeNav=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('94', '0', 'skin_modcp', '<foreach loop=\"findTab:$this->templateVars[\'tabs\'] as $mainTabKey => $subTabs\">\n	<if test=\"isMainTab:|:$mainTabKey == $this->templateVars[\'activeNav\'][\'primary\']\">\n		<if test=\"count( $subTabs ) > 1\">\n			<div class=\'maintitle ipsFilterbar clear\'>\n				<ul class=\'ipsList_inline\'>									\n					<foreach loop=\"subTabs:$subTabs as $sub\">\n						<li<if test=\"$this->templateVars[\'activeNav\'][\'secondary\'] == $sub[0]\"> class=\'active\'</if>>\n							<a href=\'{parse url=\"app=core&amp;module=modcp&amp;fromapp={$sub[1]}&amp;tab={$sub[0]}\" base=\"public\"}\'>\n							{$this->lang->words[\'modcp_tab_\' . $sub[0] ]}</a>\n						</li>\n					</foreach>\n				</ul>\n			</div>\n		</if>\n	</if>\n</foreach>', 'subTabLoop', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('95', '0', 'skin_modcp', '{parse js_module=\"topic\"}\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n<script type=\'text/javascript\'>\n	ipb.topic.inSection	= \'topicview\';\n</script>\n<style type=\'text/css\'>\n	.post_mod { display: none; }\n</style>\n<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<if test=\"hasPosts:|:is_array( $posts ) AND count( $posts )\">\n		<div id=\'ips_Posts2\'>\n			<foreach loop=\"post_data:$posts as $post\">\n				{parse template=\"modCPpost\" group=\"modcp\" params=\"$post, array(), $post, \'unapproved\'\"}\n			</foreach>\n		</div>\n	<else />\n		<div class=\'no_messages\'>\n			{$this->lang->words[\'no_unapproved_posts\']}\n		</div>\n	</if>\n	<div>{$pagelinks}</div>\n</div>', 'unapprovedPosts', '$posts, $pagelinks', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('96', '0', 'skin_modcp', '{parse js_module=\"forums\"}\n<div>{$pagelinks}</div>\n{parse template=\"subTabLoop\" group=\"modcp\" params=\"\"}\n<div class=\'clearfix\'>\n	<table class=\'ipb_table topic_list\' id=\'forum_table\'>\n		<if test=\"hastopics:|:is_array( $topics ) AND count( $topics )\">\n			{parse striping=\"forumTable\" classes=\"row1,row2\"}\n			{parse template=\"modCPtopic\" group=\"modcp\" params=\"$topics, $pagelinks, \'unapproved\'\"}\n		<else />\n			<tr> \n				<td colspan=\'3\' class=\'no_messages\'>{$this->lang->words[\'no_unapproved_topics\']}</td>\n			</tr>\n		</if>\n	</table>\n	<div>{$pagelinks}</div>\n</div>', 'unapprovedTopics', '$topics, $pagelinks', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('97', '0', 'skin_modcp', '<form method=\"post\" action=\"{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;do=save_note&amp;mid={$member[\'member_id\']}\" base=\"public\"}\" id=\'postingform\'>\n	<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n	<input type=\'hidden\' name=\'popup\' value=\'{$this->request[\'popup\']}\' />\n	<input type=\"hidden\" name=\"_st\" value=\"{$this->request[\'_st\']}\" />\n	<input type=\"hidden\" name=\"t\" value=\"{$this->request[\'t\']}\" />\n	<input type=\"hidden\" name=\"pf\" value=\"{$this->request[\'pf\']}\" />\n	<h2 class=\'maintitle\'>{$this->lang->words[\'mod_warn_new_note\']} <a href=\"{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></h2>\n	<div class=\'generic_bar\'></div>\n	<div class=\'post_form\'>\n		<fieldset class=\'row1\'>\n			<h3 class=\'bar\'>{$this->lang->words[\'mod_warn_fieldset\']}</h3>\n			<ul>\n				<li class=\'field\'>\n					<textarea name=\'note\' style=\'width: 95%; height:150px\'>{$this->request[\'note\']}</textarea>\n				</li>\n			</ul>\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'mod_warn_note_save\']}\' />\n		</fieldset>\n	</div>\n</form>', 'warn_add_note_form', '$member', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('98', '0', 'skin_modcp', '<if test=\"isAjaxModuleTitle:|:$this->request[\'module\']==\'ajax\'\">\n		<h3>{$this->lang->words[\'w_v_title\']}: <a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></h3>\n	<else />\n		<h2 class=\'maintitle\'>{$this->lang->words[\'w_v_title\']}: <a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></h2>\n	</if>\n	<if test=\"isAjaxModuleDivStart:|:$this->request[\'module\']==\'ajax\'\">\n		<div class=\'fixed_inner\'>\n	</if>\n		<table class=\'ipb_table\'>\n			<tr class=\'header\'>\n				<th scope=\'col\'>{$this->lang->words[\'w_v_warnby\']}</th>\n				<th scope=\'col\'>{$this->lang->words[\'w_v_notes\']}</th>\n			</tr>\n			<if test=\"warnlogentries:|:!is_array($rows) OR !count($rows)\">\n				<tr>\n					<td class=\"no_messages\" colspan=\"2\">{$this->lang->words[\'w_v_none\']}</td>\n				</tr>\n			<else />\n				{parse striping=\"modlog\" classes=\"row2,row1\"}\n				<foreach loop=\"logs:$rows as $r\">\n					<tr class=\'{parse striping=\"modlog\"}\'>\n						<td><a href=\'{parse url=\"showuser={$r[\'punisher_id\']}\" base=\"public\" seotitle=\"{$r[\'members_seo_name\']}\" template=\"showuser\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$r[\'punisher_name\']}</strong></a></td>\n						<td>{$this->lang->words[\'mod_warn_added\']} <strong>{parse date=\"$r[\'wlog_date\']\" format=\"long\" relative=\"false\"}</strong></td>\n					</tr>\n					<tr class=\'{parse striping=\"modlog\"}\'>\n						<td>\n							<span class=\"<if test=\"warnlognote:|:$r[\'wlog_type\'] == \'note\' OR $r[\'wlog_type\'] == \'pos\'\">positive<else />negative</if>\" <if test=\"warnlogcolor:|:$r[\'wlog_type\'] == \'note\' || $r[\'wlog_type\'] == \'nochan\' || $r[\'wlog_type\'] == \'custom\'\">style=\'color:gray\'</if>>\n								<if test=\"warnlognotetype:|:$r[\'wlog_type\'] == \'note\'\">\n									{$this->lang->words[\'mod_warn_note\']}\n								<else />\n									<if test=\"warnlogpos:|:$r[\'wlog_type\'] == \'pos\'\">\n										{$this->lang->words[\'w_v_minus\']}\n									</if>\n									<if test=\"warnlogneg:|:$r[\'wlog_type\'] == \'neg\'\">\n										{$this->lang->words[\'w_v_add\']}\n									</if>\n									<if test=\"warnlognochange:|:$r[\'wlog_type\'] == \'nochan\'\">\n										{$this->lang->words[\'w_v_nochan\']}\n									</if>\n									<if test=\"warnlogcustchange:|:$r[\'wlog_type\'] == \'custom\'\">\n										{$this->lang->words[\'w_v_custom\']}\n									</if>\n								</if>\n							</span>\n						</td>\n						<td>{$r[\'content\']}</td>\n					</tr>\n				</foreach>\n			</if>\n		</table>\n		<div class=\'ipsPad\'>\n			{$links}\n		</div>\n	<if test=\"isAjaxModuleDivEnd:|:$this->request[\'module\']==\'ajax\'\">\n		</div>\n		<div class=\'ipsForm_submit ipsForm_right\'>\n			<a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;mid={$member[\'member_id\']}&amp;_tab=warn\" base=\"public\"}\' class=\'ipsButton\'><img src=\'{$this->settings[\'img_url\']}/moderation_cog.png\' /> &nbsp;{$this->lang->words[\'alter_warn_level\']}</a>\n		</div>\n	</if>', 'warn_view_log', '$member, $rows, $links=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('99', '0', 'skin_modcp', '{parse js_module=\"profile\"}\n<script type=\'text/javascript\'>\n	ipb.profile.viewingProfile = {$member[\'member_id\']};\n</script>\n<if test=\"warnerrors:|:$errors\">\n	<h2>{$this->lang->words[\'errors_found\']}</h2>\n	<p class=\'message error\'>{$errors}</p>\n	<br />\n</if>\n<form method=\"post\" action=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;do=dowarn&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' id=\'postingform\'>\n<input type=\"hidden\" name=\"key\" value=\"{$this->member->form_hash}\" />\n<input type=\"hidden\" name=\"type\" value=\"{$this->request[\'type\']}\" />\n<input type=\"hidden\" name=\"_st\" value=\"{$this->request[\'_st\']}\" />\n<input type=\"hidden\" name=\"t\" value=\"{$this->request[\'t\']}\" />\n<input type=\"hidden\" name=\"pf\" value=\"{$this->request[\'pf\']}\" />\n<div class=\'post_form\'>\n<h2 class=\'maintitle\'>{$this->lang->words[\'warn_logs_for\']} <a href=\'{parse url=\"showuser={$member[\'member_id\']}\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></h2>\n<div class=\'generic_bar\'></div>\n<fieldset class=\'with_subhead\'>\n	<h3 class=\'bar\'>{$this->lang->words[\'warn_member_details\']}</h3>\n	<h4>\n		<img class=\"ipsUserPhoto ipsUserPhoto_large\" src=\'{$member[\'pp_thumb_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\" />\n	</h4>\n	<ul>\n		<li class=\'field\'>\n			{parse replacement=\"find_topics_link\"} <a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\'>{$this->lang->words[\'gbl_find_my_content\']}</a>\n		</li>\n		<if test=\"displaynamehistory:|:$this->memberData[\'g_mem_info\'] && $this->settings[\'auth_allow_dnames\']\">\n			<li class=\'field\' id=\'dname_history\'>\n				{parse replacement=\"display_name\"} <a href=\'{parse url=\"app=members&amp;module=profile&amp;section=dname&amp;id={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_dname_history\']}\'>{$this->lang->words[\'display_history\']}</a>\n			</li>\n		</if>\n		<if test=\"warnreputation:|:$this->settings[\'reputation_enabled\']\">\n			<li class=\'field\'>\n				<if test=\"RepPositive:|:$member[\'pp_reputation_points\'] > 0\">\n					<div class=\'reputation positive\' style=\'min-width: 150px; text-align: center\'>\n				</if>\n				<if test=\"RepNegative:|:$member[\'pp_reputation_points\'] < 0\">\n					<div class=\'reputation negative\' style=\'min-width: 150px; text-align: center\'>\n				</if>\n				<if test=\"RepZero:|:$member[\'pp_reputation_points\'] == 0\">\n					<div class=\'reputation zero\' style=\'min-width: 150px; text-align: center\'>\n				</if>\n					<span class=\'number\'>{$member[\'pp_reputation_points\']}</span>\n					<if test=\"reptext:|:$member[\'author_reputation\'] && $member[\'author_reputation\'][\'text\']\">\n						<p class=\'title\'>{$member[\'author_reputation\'][\'text\']}</p>\n					</if>\n					<if test=\"repimage:|:$member[\'author_reputation\'] && $member[\'author_reputation\'][\'image\']\">\n						<p class=\'image\'>{$member[\'author_reputation\'][\'image\']}</p>\n					</if>\n				</div>\n			</li>\n		</if>\n	</ul>\n</fieldset>\n<fieldset class=\'with_subhead\'>\n	<h3 class=\'bar\'>{$this->lang->words[\'warn_details\']}</h3>\n	<h4>{$this->lang->words[\'w_adjust_level\']}<br /><span class=\'desc\'>{$this->lang->words[\'warn_current_level\']} {$member[\'warn_level\']}/{$this->settings[\'warn_max\']}</span></h4>\n	<ul>\n		<li class=\'field checkbox\'>\n			<input type=\"radio\" name=\"level\" id=\"nochange\" class=\"input_radio\" value=\"nochange\" <if test=\"warnnochange:|:$this->request[\'type\'] == \'nochange\' OR !$this->request[\'type\']\">checked=\'checked\'</if> />\n			<label for=\'nochange\'>{$this->lang->words[\'w_nochange\']}</label>\n		</li>\n		<li class=\'field checkbox negative\'>\n			<input type=\"radio\" name=\"level\" id=\"add\" class=\"input_radio\" value=\"add\" <if test=\"addwarn:|:$this->request[\'type\'] == \'add\'\">checked=\'checked\'</if> />\n			<label for=\'add\'>{$this->lang->words[\'w_add\']}</label>\n		</li>\n		<li class=\'field checkbox positive\'>\n			<input type=\"radio\" name=\"level\" id=\"minus\" class=\"input_radio\" value=\"remove\" <if test=\"subwarn:|:$this->request[\'type\'] == \'minus\'\">checked=\'checked\'</if> />\n			<label for=\'minus\'>{$this->lang->words[\'w_remove\']}</label>\n		</li>	\n		<if test=\"warnsupermod:|:$this->memberData[\'g_is_supmod\']\">\n			<li class=\'field checkbox custom\'>\n				<input type=\"radio\" name=\"level\" id=\"custom\" class=\"input_radio\" value=\"custom\" <if test=\"warncustom:|:$this->request[\'type\'] == \'custom\'\">checked=\'checked\'</if> />\n				<label for=\'level_custom\'>{parse expression=\"sprintf( $this->lang->words[\'w_change_custom\'], $this->settings[\'warn_max\'])\"}</label>\n				 <input type=\'text\' id=\'level_custom\' name=\'level_custom\' value=\'<if test=\"warncustomlevel:|:isset($this->request[\'customLevel\'])\">{$this->request[\'customLevel\']}<else />{$member[\'warn_level\']}</if>\' size=\'3\' />\n			</li>\n		</if>\n	</ul>\n	<h4>{$this->lang->words[\'w_reason\']}<br /><span class=\'desc\'>{$this->lang->words[\'w_reason2\']}</span></h4>\n	<ul>\n		<li class=\'field\'>\n			<textarea rows=\"6\" cols=\"50\" class=\"input_text\" name=\"reason\">{IPSText::br2nl( $this->request[\'reason\'] )}</textarea>\n		</li>\n	</ul>\n</fieldset>\n<fieldset class=\'with_subhead\'>\n	<h3 class=\'bar\'>{$this->lang->words[\'member_suspension\']}</h3>\n	<if test=\"modqueue:|:$modque == true\">\n		<php>\n			$mod_arr	= array( \'timespan\' => 0, \'days\' => 0, \'hours\' => 0 );\n			$mhours		= 0;\n			\n			if( $member[\'mod_posts\'] > 0 AND $member[\'mod_posts\'] != 1 )\n			{\n				$mod_arr	= IPSMember::processBanEntry( $member[\'mod_posts\'] );\n				\n				if( $mod_arr[\'date_end\'] > time() )\n				{\n					$mhours		= ceil( ( $mod_arr[\'date_end\'] - time() ) / 3600 );\n				}\n			}\n		</php>\n		<h4>{$this->lang->words[\'w_modq\']}</h4>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input class=\'input_check\' id=\'modq\' type=\"checkbox\" name=\"mod_indef\" value=\"1\" <if test=\"modqueueposts:|:$member[\'mod_posts\'] == 1\">checked=\'checked\'</if> />\n				<label for=\'modq\'>{$this->lang->words[\'w_modq_i\']}</label>\n			</li>\n			<li class=\'field checkbox\'>\n				<label for=\'mod_value\'>{$this->lang->words[\'w_orfor\']}</label>\n				<input class=\'input_text\' type=\"text\" id=\'mod_value\' name=\"mod_value\" value=\"<if test=\"modqueuehours:|:$mhours >= 24 and ( ($mhours / 24) == ceil($mhours / 24) ) and $timespan = ($mhours / 24)\">{$timespan}<else />{$mhours}</if>\" size=\"5\" />&nbsp;\n				<select name=\"mod_unit\" class=\'input_select\'>\n					<option value=\"d\" <if test=\"modunitd:|:$mhours >= 24 and ( ($mhours / 24) == ceil($mhours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_day\']}</option>\n					<option value=\"h\" <if test=\"modunith:|:$mhours < 24 or ( ($mhours / 24) != ceil($mhours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_hour\']}</option>\n				</select>\n				<if test=\"modqueueon:|:$mhours > 0\">\n					<span class=\'desc\'>{$this->lang->words[\'w_restricted\']}</span>\n				</if>\n			</li>\n		</ul>\n	</if>\n	<if test=\"postqueue:|:$postque == true\">\n		<php>\n			$post_arr	= array( \'timespan\' => 0, \'hours\' => 0, \'days\' => 0 );\n			$phours		= 0;\n			\n			if( $member[\'restrict_post\'] > 0 AND $member[\'restrict_post\'] != 1 )\n			{\n				$post_arr	= IPSMember::processBanEntry( $member[\'restrict_post\'] );\n				\n				if( $post_arr[\'date_end\'] > time() )\n				{\n					$phours		= ceil( ( $post_arr[\'date_end\'] - time() ) / 3600 );\n				}\n			}\n		</php>\n		<h4>{$this->lang->words[\'w_resposts\']}</h4>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input class=\'input_check\' id=\'restrict_posts\' type=\"checkbox\" name=\"post_indef\" value=\"1\" <if test=\"postqueueposts:|:$member[\'restrict_post\'] == 1\">checked=\'checked\'</if> />\n				<label for=\'restrict_posts\'>{$this->lang->words[\'w_resposts_i\']}</label>\n			</li>\n			<li class=\'field checkbox\'>\n				<label for=\'post_value\'>{$this->lang->words[\'w_orfor\']}</label>\n				<input class=\'input_text\' type=\"text\" id=\'post_value\' name=\"post_value\" value=\"<if test=\"postqueuehours:|:$phours >= 24 and ( ($phours / 24) == ceil($phours / 24) ) and $timespan = ($phours / 24)\">{$timespan}<else />{$phours}</if>\" size=\"5\" />&nbsp;\n				<select name=\"post_unit\" class=\'input_select\'>\n					<option value=\"d\" <if test=\"postunitd:|:$phours >= 24 and ( ($phours / 24) == ceil($phours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_day\']}</option>\n					<option value=\"h\" <if test=\"postunith:|:$phours < 24 or ( ($phours / 24) != ceil($phours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_hour\']}</option>\n				</select>\n				<if test=\"postqueueon:|:$phours > 0\">\n					<span class=\'desc\'>{$this->lang->words[\'w_restricted\']}</span>\n				</if>\n			</li>\n		</ul>\n	</if>\n	<if test=\"banqueue:|:$ban == true\">\n		<php>\n			$ban_arr	= array( \'timespan\' => 0, \'days\' => 0, \'hours\' => 0 );\n			$hours		= 0;\n			\n			if( $member[\'temp_ban\'] AND $member[\'temp_ban\'] != 1 )\n			{\n				$ban_arr	= IPSMember::processBanEntry( $member[\'temp_ban\'] );\n				\n				if( $ban_arr[\'date_end\'] > time() )\n				{\n					$hours		= ceil( ( $ban_arr[\'date_end\'] - time() ) / 3600 );\n				}\n			}\n		</php>\n		<h4>{$this->lang->words[\'w_suspend\']}</h4>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input class=\'input_check\' id=\'suspend_member\' type=\"checkbox\" name=\"ban_indef\" value=\"1\" <if test=\"bannedison:|:$member[\'member_banned\'] == 1\">checked=\'checked\'</if> />\n				<label for=\'suspend_member\'>{$this->lang->words[\'w_ban_indef\']}</label>\n			</li>\n			<li class=\'field checkbox\'>\n				<label for=\'susp_value\'>{$this->lang->words[\'w_suspend_or\']}</label>\n				<input type=\"text\" id=\'susp_value\' class=\'input_text\' name=\"susp_value\" value=\"<if test=\"bannedhours:|:$hours >= 24 and ( ($hours / 24) == ceil($hours / 24) ) and $timespan = ($hours / 24)\">{$timespan}<else />{$hours}</if>\" size=\"5\" />\n				<select name=\"susp_unit\" class=\'input_select\'>\n					<option value=\"d\" <if test=\"banunitd:|:$hours >= 24 and ( ($hours / 24) == ceil($hours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_day\']}</option>\n					<option value=\"h\" <if test=\"banunith:|:$hours < 24 or ( ($hours / 24) != ceil($hours / 24) )\">selected=\'selected\'</if>>{$this->lang->words[\'w_hour\']}</option>\n				</select>\n				<if test=\"banon:|:$member[\'temp_ban\']\">\n					<span class=\'desc\'>{$this->lang->words[\'w_restricted\']}</span>\n				</if>\n			</li>\n		</ul>\n	</if>\n</fieldset>\n<fieldset class=\'with_subhead\'>\n	<h3 class=\'bar\'>{$this->lang->words[\'warn_mem_content\']}</h3>\n	<h4>{$this->lang->words[\'warn_posts_topics\']}</h4>\n	<ul>\n		<li class=\'field checkbox\'>\n			<select name=\"topicPosts_type\" class=\'input_select\'>\n				<option value=\'unapprove\' <if test=\"unapproveposts:|:$this->request[\'topicPosts_type\'] == \'unapprove\'\">selected=\'selected\'</if>>{$this->lang->words[\'warn_stuff_unapprove\']}</option>\n				<option value=\'approve\' <if test=\"approveposts:|:$this->request[\'topicPosts_type\'] == \'approve\'\">selected=\'selected\'</if>>{$this->lang->words[\'warn_stuff_approve\']}</option>\n			</select>\n		</li>\n		<li class=\'field checkbox\'>\n			<input type=\"checkbox\" id=\'topicPosts_topics\' class=\'input_check\' name=\"topicPosts_topics\" value=\"1\" />\n			<label for=\'topicPosts_topics\'>{$this->lang->words[\'warn_stuff_alltopics\']}</label>\n		</li>\n		<li class=\'field checkbox\'>\n			<input type=\"checkbox\" id=\'topicPosts_replies\' class=\'input_check\' name=\"topicPosts_replies\" value=\"1\" />\n			<label for=\'topicPosts_replies\'>{$this->lang->words[\'warn_stuff_allposts\']}</label>\n		</li>\n		<li class=\'field checkbox\'>\n			<label for=\'topicPosts_lastx\'>{$this->lang->words[\'warn_stuff_datecutoff\']}</label>\n			<input type=\"text\" id=\'topicPosts_lastx\' class=\'input_text\' name=\"topicPosts_lastx\" value=\"\" size=\"5\" />\n			<select name=\"topicPosts_lastxunits\" class=\'input_select\'>\n				<option value=\"d\">{$this->lang->words[\'w_day\']}</option>\n				<option value=\"h\">{$this->lang->words[\'w_hour\']}</option>\n			</select>\n		</li>\n	</ul>\n</fieldset>\n<fieldset>\n	<h3 class=\'bar\'>{$this->lang->words[\'warn_contact_member\']}</h3>\n	<ul>\n		<li class=\'field\'>\n			<label for=\'subj\'>{$this->lang->words[\'w_c_subj\']}</label>\n			<input id=\'subj\' class=\'input_text\' type=\"text\" name=\"subject\" value=\"{$this->request[\'subject\']}\" size=\"30\" />\n		</li>\n		<li class=\'field\'>\n			<label for=\'method\'>{$this->lang->words[\'w_c\']}</label>\n			<select id=\'method\' name=\"contactmethod\" class=\'input_select\'>\n				<if test=\"disablepm:|:$member[\'members_disable_pm\'] != 1\">\n					<option value=\"pm\">{$this->lang->words[\'w_c_p\']}</option>\n				</if>\n				<option value=\"email\">{$this->lang->words[\'w_c_e\']}</option>\n			</select>\n		</li>\n		<li>\n			{$editor_html}\n		</li>\n	</ul>\n</fieldset>\n<fieldset class=\'submit\'>\n	<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'w_submit\']}\" tabindex=\'0\'/>\n</fieldset>\n	\n</div>\n</form>', 'warnForm', '$member, $errors=\'\', $modque=false, $postque=false, $ban=false, $editor_html=\'\'', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('100', '0', 'skin_register', '{parse js_module=\"register\"}\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.register.inSection	   = \"completeReg\";\n	ipb.register.nameMaxLength = \"{$this->settings[\'max_user_name_length\']}\";\n	ipb.register.allowedChars  = \"{$this->settings[\'username_characters\']}\";\n	ipb.register.memberPartial = parseInt(\'{$mid}\');\n	ipb.templates[\'accept\']    = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_accept\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/accept.png\' alt=\'\' /> [msg]</span>\";\n	ipb.templates[\'error\']     = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_error\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/exclamation.png\' alt=\'\' /> [msg]</span>\";\n//]]>\n</script>\n<div id=\'register_form\'>	\n	<h1 class=\'ipsType_pagetitle\'><if test=\"hasAName:|:$this->request[\'members_display_name\'] OR $userFromService[\'_name\']\">{parse expression=\"sprintf($this->lang->words[\'connect_sub\'], $userFromService[\'_name\'] ? IPSText::utf8ToEntities( $userFromService[\'_name\'] ) : $this->request[\'members_display_name\'])\"}<else />{$this->lang->words[\'connect_sub2\']}</if></h1>\n	<br />\n	<if test=\"count( $userFromService ) AND ! empty( $userFromService[\'service\'] )\">\n		<input type=\'hidden\' name=\'connectService\' value=\'{$userFromService[\'service\']}\' />\n		<div id=\'facebookComplete\' class=\'clearfix\'>\n			<img src=\"{$userFromService[\'_pic\']}\" class=\'ipsUserPhoto ipsUserPhoto_medium left\' />\n			<img src=\"{$userFromService[\'_sImage\']}\" class=\'servicepic\' />\n			<p class=\'ipsBox_withphoto\'>\n				{parse expression=\"sprintf($this->lang->words[\'connect_sub_desc\'], ucfirst($userFromService[\'service\']))\"}\n				<br />\n				{parse expression=\"sprintf($this->lang->words[\'connect_desc\'], ucfirst($userFromService[\'service\']))\"}\n			</p>\n		</div>\n	<else />\n		<p class=\'message\'>{$this->lang->words[\'clogin_text\']}</p>\n	</if>\n	<br />\n	<if test=\"partialLoginErrors:|:!empty( $errors )\">\n		<p class=\'message error\'>\n			<strong>{$this->lang->words[\'errors_found\']}</strong>\n			{$errors}\n		</p>\n		<br />\n	</if>\n	<div id=\'connect_choose\'>\n		<h2 class=\'ipsType_subtitle\'>{parse expression=\"sprintf( $this->lang->words[\'already_have_account\'], $this->settings[\'board_name\'] )\"}</h2>\n		<div class=\'ipsBox\' style=\'margin-top: 5px\'>\n			<div class=\'ipsBox_container ipsPad\' style=\'text-align: center\'>\n				<a href=\'#connect_new\' class=\'ipsButton\' id=\'choose_new\'>{$this->lang->words[\'need_to_create_acc\']}</a>&nbsp;&nbsp;&nbsp;\n				<if test=\"count( $userFromService ) AND ! empty( $userFromService[\'service\'] )\">\n					<a href=\'#connect_existing\' id=\'choose_existing\'>{$this->lang->words[\'use_an_existing_acc\']}</a>\n				</if>\n			</div>\n		</div>\n	</div>\n	<div id=\'connect_new\'>\n		<br />\n		<h2 class=\'maintitle\'>{$this->lang->words[\'new_account_title\']}</h2>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container <if test=\"count( $userFromService ) AND ! empty( $userFromService[\'service\'] )\"> completeLeft</if>\'>\n				<form action=\"{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=complete_login_do&amp;key=$key&amp;mid=$mid&amp;connectService={$userFromService[\'service\']}\" base=\"public\"}\" method=\"POST\">\n					<input type=\"hidden\" name=\"termsread\" value=\"1\" />\n					<input type=\"hidden\" name=\"agree_to_terms\" value=\"1\" />\n					<input type=\'hidden\' name=\'from\' value=\'new\' />\n					<fieldset class=\'main\'>\n						<ul class=\'ipsForm ipsForm_horizontal ipsPad\'>\n							<if test=\"partialAllowDnames:|:$this->settings[\'auth_allow_dnames\'] == 1\">\n								<li class=\'ipsField clear\'>\n									<if test=\"fbDisplayName:|:$userFromService[\'service\'] == \'facebook\' AND $this->settings[\'fb_realname\'] != \'any\' AND $userFromService[\'_displayName\']\">\n										<if test=\"fbDNInner:|:$this->settings[\'fb_realname\'] == \'prefilled\'\">\n											<label for=\'display_name\' class=\'ipsField_title\'>{$this->lang->words[\'dname_name\']}</label>\n											<p class=\'ipsField_content\'>\n												<input id=\'display_name\' class=\'input_text\'  type=\"text\" size=\"40\" maxlength=\"64\" value=\"{$userFromService[\'_displayName\']}\" name=\"members_display_name\" />\n											</p>\n										<else />\n											<span class=\'ipsField_title\'></span>\n											<p class=\'ipsField_content\'><strong>{IPSText::utf8ToEntities( $userFromService[\'_displayName\'] )}</strong></p>\n											<input type=\"hidden\" value=\"{$userFromService[\'_displayName\']}\" name=\"members_display_name\" />\n										</if>\n									<else />\n										<label for=\'display_name\' class=\'ipsField_title\'>{$this->lang->words[\'dname_name\']}</label>\n										<p class=\'ipsField_content\'>\n											<input id=\'display_name\' class=\'input_text\'  type=\"text\" size=\"40\" maxlength=\"64\" value=\"{$this->request[\'members_display_name\']}\" name=\"members_display_name\" />\n										</p>\n									</if>\n								</li>\n							</if>\n							<if test=\"partialNoEmail:|:! $reg[\'partial_email_ok\']\">\n								<li class=\'ipsField clear\'>\n									<label for=\'email_1\' class=\'ipsField_title\'>{$this->lang->words[\'email_address\']}</label>\n									<p class=\'ipsField_content\'>\n										<input id=\'email_1\' class=\'input_text\'  type=\"text\" size=\"40\" maxlength=\"50\" value=\"{$this->request[\'EmailAddress\']}\" name=\"EmailAddress\" />\n									</p>\n								</li>\n								<li class=\'ipsField clear\'>\n									<label for=\'email_2\' class=\'ipsField_title\'>{$this->lang->words[\'email_address_confirm\']}</label>\n									<p class=\'ipsField_content\'>\n										<input id=\'email_2\' class=\'input_text\'  type=\"text\" size=\"40\" maxlength=\"50\"  value=\"{$this->request[\'EmailAddress_two\']}\" name=\"EmailAddress_two\" />\n									</p>\n								</li>\n							</if>\n							<if test=\"partialCustomFields:|:$custom_fields != \'\'\">\n								<fieldset class=\'rcomplete\'>\n								<if test=\"reqCfields:|:is_array( $custom_fields[\'required\'] ) && count( $custom_fields[\'required\'] )\">\n									<foreach loop=\"custom_required:$custom_fields[\'required\'] as $_field\">\n										<li class=\'ipsField clear {$_field[\'type\']}\'>\n											<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']} <span class=\'ipsForm_required\'>*</span></label>\n											<div class=\'ipsField_content\'>\n												{$_field[\'field\']}\n												<if test=\"reqCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><span class=\'desc\'>{$_field[\'desc\']}</span></if>\n											</div>\n										</li>\n									</foreach>\n								</if>\n	\n								<if test=\"optCfields:|:is_array( $custom_fields[\'optional\'] ) && count( $custom_fields[\'optional\'] )\">\n									<foreach loop=\"custom_optional:$custom_fields[\'optional\'] as $_field\">\n										<li class=\'ipsField clear {$_field[\'type\']}\'>\n											<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']}</label>\n											<div class=\'ipsField_content\'>\n												{$_field[\'field\']}\n												<if test=\"optCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><span class=\'desc\'>{$_field[\'desc\']}</span></if>\n											</div>\n										</li>\n									</foreach>\n								</if>\n								</fieldset>\n							</if>\n						</ul>\n					</fieldset>\n					<fieldset class=\'submit\'>\n						<input type=\'submit\' value=\'{$this->lang->words[\'new_account_submit\']}\' class=\'input_submit\' />\n					</fieldset>\n				</form>\n			</div>\n		</div>\n	</div>\n	<if test=\"count( $userFromService ) AND ! empty( $userFromService[\'service\'] )\">\n		<br />\n		<div id=\'connect_existing\'>\n			<h2 class=\'maintitle\'>{$this->lang->words[\'connect_account_title\']}</h2>\n			<div class=\'ipsBox\'>\n				<div class=\'ipsBox_container\'>\n					<form action=\"{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=complete_login_do&amp;key={$key}&amp;mid={$mid}&amp;connectService={$userFromService[\'service\']}\" base=\"public\"}\" method=\"POST\">\n						<input type=\"hidden\" name=\"termsread\" value=\"1\" />\n						<input type=\"hidden\" name=\"agree_to_terms\" value=\"1\" />\n						<input type=\'hidden\' name=\"from\" value=\"existing\" />\n						<fieldset class=\'ipsPad_double\'>\n							<ul class=\'ipsForm ipsForm_horizontal\'>\n								<li class=\'ipsField clear\'>\n									<label for=\'login_user\' class=\'ipsField_title\'>{$this->lang->words[\'connect_username\']}</label>\n									<div class=\'ipsField_content\'>\n										<input id=\'login_user\' class=\'input_text\' type=\"text\" size=\"50\" maxlength=\"50\" value=\"{$this->request[\'login_user\']}\" name=\"login_user\" /><br />\n										<span class=\'desc\'>{$this->lang->words[\'connect_username_desc\']}</span> \n									</div>\n								</li>\n								<li class=\'ipsField clear\'>\n									<label for=\'login_pass\' class=\'ipsField_title\'>{$this->lang->words[\'connect_password\']}</label>\n									<div class=\'ipsField_content\'>\n										<input id=\'login_pass\' class=\'input_text\' type=\"password\" size=\"50\" maxlength=\"50\"  value=\"\" name=\"login_pass\" /><br />\n										<span class=\'desc\'>{$this->lang->words[\'connect_password_desc\']}</span>\n									</div>\n								</li>\n							</ul>\n						</fieldset>\n						<fieldset class=\'submit\'>\n							<input type=\'submit\' value=\'{$this->lang->words[\'connect_account_submit\']}\' class=\'input_submit\' />\n						</fieldset>\n					</form>\n				</div>\n			</div>\n		</div>\n	</if>\n</div>\n<script type=\'text/javascript\'>\n	<if test=\"$this->request[\'from\']\">\n		ipb.vars[\'register_active\'] = \"{$this->request[\'from\']}\";\n	</if>\n	\n	function setUpSignin(){\n		if( !$(\'connect_existing\') ){\n			$(\'connect_choose\').hide();\n			return;\n		}\n		\n		if( !Object.isUndefined( ipb.vars[\'register_active\'] ) ){\n			if( ipb.vars[\'register_active\'] == \'new\' ){\n				$(\'connect_new\').show();\n				$(\'connect_existing\').hide();\n			} else {\n				$(\'connect_existing\').show();\n				$(\'connect_new\').hide();\n			}\n		} else {\n			$(\'connect_new\').hide();\n			$(\'connect_existing\').hide();\n		}\n		\n		$(\'choose_new\').observe(\'click\', toggleSignIn);\n		$(\'choose_existing\').observe(\'click\', toggleSignIn);\n	}\n	\n	function toggleSignIn(e){\n		Event.stop(e);\n		var toggleTo = Event.findElement(e, \'a\');\n		if( !toggleTo ){ return; }\n		\n		if( toggleTo == $(\'choose_new\') ){\n			if( !$(\'connect_new\').visible() ){\n				$(\'connect_existing\').fade( { duration: 0.3, afterFinish: function(){\n					$(\'connect_new\').appear( { duration: 0.2 } );\n				} } );\n			}\n		} else {\n			if( !$(\'connect_existing\').visible() ){\n				$(\'connect_new\').fade( { duration: 0.3, afterFinish: function(){\n					$(\'connect_existing\').appear({ duration: 0.2});\n				}});\n			}\n		}\n	}\n	\n	setUpSignin();\n</script>', 'completePartialLogin', '$mid=\"\",$key=\"\",$custom_fields=\"\",$errors=\"\", $reg=\"\", $userFromService=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('101', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'lost_pass_form\']}</h1>\n<div class=\'ipsType_pagedesc\'>\n	{$this->lang->words[\'lost_your_password\']} {$this->lang->words[\'lp_text\']}\n</div>\n<br />\n<if test=\"lostPasswordErrors:|:!empty( $errors )\">\n	<p class=\'message error\'>\n		<strong>{$this->lang->words[\'errors_found\']}</strong><br />\n		{$errors}\n	</p>\n	<br />\n</if>\n\n<form action=\"{parse url=\"app=core&module=global&section=lostpass\" base=\"public\"}\" method=\"post\">\n<input type=\"hidden\" name=\"do\" value=\"11\" />\n<h2 class=\'maintitle\'>{$this->lang->words[\'recover_password\']}</h2>\n<div id=\'lost_pass_form\' class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad_double\'>\n		<fieldset>\n			<ul class=\'ipsForm ipsForm_horizontal\'>\n				<li class=\'ipsField clear\'>\n					<label for=\'member_name\' class=\'ipsField_title\'>{$this->lang->words[\'lp_user_name\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"text\" size=\"32\" name=\"member_name\" id=\'member_name\' class=\'input_text\' />\n					</p>\n				</li>\n				<li class=\'ipsField clear\'>\n					<label for=\'email_addy\' class=\'ipsField_title\'>{$this->lang->words[\'lp_email_or\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"text\" size=\"32\" name=\"email_addy\" id=\'email_addy\' class=\'input_text\' />\n					</p>\n				</li>\n			</ul>\n		</fieldset>\n		<!--{REG.ANTISPAM}-->\n	</div>\n	<fieldset class=\'submit\'>\n			<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'lp_send\']}\" /> {$this->lang->words[\'or\']} <a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'lostPasswordForm', '$errors=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('102', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'lpf_title\']}</h1>\n<br />\n<p class=\'message\'>\n	{$this->lang->words[\'lpass_text\']}\n</p>', 'lostPasswordWait', '$member=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('103', '0', 'skin_register', '<html>\n	<head>\n		<meta http-equiv=\"content-type\" content=\"text/html; charset=<% CHARSET %>\" />\n		<title>{$this->lang->words[\'cpf_title\']}</title>\n	</head>\n	\n	<body>\n	<h2>{$this->settings[\'board_name\']}: {$this->lang->words[\'cpf_title\']}</h2>\n	<if test=\"coppaConsentExtra:|:$this->settings[\'coppa_consent_extra\']\">\n		<div>\n			<b>{$this->lang->words[\'coppa_additional_info\']}</b>\n			<div>{$this->settings[\'coppa_consent_extra\']}</div>\n		</div>\n	</if>\n	<hr />\n	<div>\n		<b>{$this->lang->words[\'cpf_perm_parent\']}</b>\n		<div style=\'padding:8px;\'>{$this->lang->words[\'cpf_fax\']} <u>{$this->settings[\'coppa_fax\']}</u></div>\n		<div style=\'padding:8px;\'>{$this->lang->words[\'cpf_address\']}<br />\n			<address>{$this->settings[\'coppa_address\']}</address>\n		</div>\n	</div>\n	<hr />\n	<div>	\n		<table class=\'ipbtable\' cellspacing=\"1\" cellpadding=\'8\'>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'user_name\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'password\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'email_address\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n		</table>\n	</div>\n	<hr />\n	<div>\n		<b>{$this->lang->words[\'cpf_sign\']}</b>\n	</div>\n	<br />\n	<div>\n		<table class=\'ipbtable\' cellspacing=\"1\" cellpadding=\'8\'>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_name\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_relation\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_signature\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_email\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_phone\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n			<tr>\n				<td width=\"40%\">{$this->lang->words[\'cpf_date\']}</td>\n				<td style=\'text-decoration:underline;\'>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</td>\n			</tr>\n		</table>\n	</div>\n	<hr />\n	<div><b>{$this->lang->words[\'coppa_admin_reminder\']}</b>\n		<div>{$this->lang->words[\'coppa_admin_remtext\']}</div>\n	</div>\n	</body>\n</html>', 'registerCoppaForm', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('104', '0', 'skin_register', '<if test=\"useCoppa:|:$this->settings[\'use_coppa\'] && (!$this->request[\'coppa\'] && !IPSCookie::get(\'coppa\'))\">\n<div class=\'post_form\' id=\'coppa_form\'>\n	<fieldset class=\'general_box\'>\n		<h3>{$this->lang->words[\'coppa_info\']}</h3>\n		<div class=\'ipsPad\'>\n			{$this->lang->words[\'confirm_over_thirteen\']}\n		</div>\n		<div class=\'ipsPad ipsForm_center\'>\n			<form>\n			<select name=\'month\' id=\'coppa_bday_m\'>\n				<foreach loop=\"coppaMRange:$this->lang->words as $k => $v\">\n					<if test=\"isMKey:|:strpos( $k, \'M_\' ) === 0\">\n						<option value=\'{parse expression=\"str_replace( \'M_\', \'\', $k )\"}\'>{$v}</option>\n					</if>\n				</foreach>\n			</select>\n			&nbsp;\n			<select name=\'day\' id=\'coppa_bday_d\'>\n				<foreach loop=\"coppaDRange:range( 1, 31 ) as $_day\">\n					<option value=\'{$_day}\'>{$_day}</option>\n				</foreach>\n			</select>\n			&nbsp;\n			<select name=\'year\' id=\'coppa_bday_y\'>\n				<foreach loop=\"coppaYRange:array_reverse( range( date(\'Y\') - 110, date(\'Y\') ) ) as $_year\">\n					<option value=\'{$_year}\'>{$_year}</option>\n				</foreach>\n			</select>\n			</form>\n		</div>\n	</fieldset>\n	<fieldset class=\'ipsForm_submit ipsForm_right\'>\n		<a href=\'{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=coppa_two&amp;coppa=1\" base=\"public\"}\' id=\'confirm_coppa\' class=\'ipsButton\'>{$this->lang->words[\'coppa_continue_button\']}</a>\n	</fieldset>\n</div>\n<script type=\'text/javascript\'>\n	$(\'coppa_form\').hide();\n	\n	function validateDate( popup )\n	{\n		var day		= parseInt($(\'coppa_bday_d\').value);\n		var month	= parseInt($(\'coppa_bday_m\').value);\n		var year	= parseInt($(\'coppa_bday_y\').value);\n		var compare		= Math.round( new Date( year + 13, month, day ).getTime() / 1000 );\n		var today		= Math.round( new Date().getTime() / 1000 );\n		if ( (today - compare) < 0 )\n		{\n			window.location = ipb.vars[\'base_url\'] + \"app=core&module=global&section=register&do=coppa_two\";\n		}\n		else\n		{\n			popup.hide();\n			ipb.Cookie.set(\'coppa\', \'no\', true);\n		}\n	}\n	\n	ipb.vars[\'coppa_popup\'] = new ipb.Popup( \'coppa_popup\', {	type: \'pane\',\n																initial: $(\'coppa_form\').show(),\n																hideAtStart: false,\n																hideClose: true,\n																defer: false,\n																modal: true,\n																w: \'550px\' },\n															{\n																afterInit: function( popup ){\n																	popup.getObj().select(\"#confirm_coppa\")[0].observe(\'click\', function(e){\n																		Event.stop(e);\n																		\n																		return validateDate( popup );\n																	});\n																}\n															} );\n</script>\n</if>', 'registerCoppaStart', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('105', '0', 'skin_register', '{parse js_module=\"register\"}\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'cp2_title\']}</h1>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad_double\'>\n		<h2 class=\'clear ipsType_subtitle\'>{$this->lang->words[\'coppa_form\']}</h2>\n		<p>\n			{$this->lang->words[\'cp2_text\']}<br /><br />\n			<strong><a href=\'{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=12\" base=\"public\"}\' title=\'{$this->lang->words[\'coppa_form\']}\'>{$this->lang->words[\'coppa_clickhere\']}</a></strong>\n		</p>\n		<p>\n			<br />\n			{$this->lang->words[\'coppa_form_text\']}\n		</p>\n		<p>\n			<br />\n			<a href=\'{parse url=\"app=core&amp;module=global&amp;section=register&amp;do=coppa_one\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>&lt; {$this->lang->words[\'cancel\']}</a>\n		</p>\n	</div>	\n</div>', 'registerCoppaTwo', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('106', '0', 'skin_register', '{parse js_module=\"register\"}\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.register.inSection = \"mainform\";\n	ipb.register.nameMaxLength = \"{$this->settings[\'max_user_name_length\']}\";\n	ipb.register.allowedChars = \"{$this->settings[\'username_characters\']}\";\n	ipb.templates[\'accept\'] = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_accept\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/accept.png\' alt=\'\' /> [msg]</span>\";\n	ipb.templates[\'error\'] = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_error\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/exclamation.png\' alt=\'\' /> [msg]</span>\";\n//]]>\n</script>\n<div id=\'register_form\'>\n	<!--<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'ready_register\']}</h1>-->\n	{parse template=\"registerStepBar\" group=\"register\" params=\"array(\'register_form\' => \'ipsSteps_active\', \'confirmation\' => \'\')\"}\n	<if test=\"registerHasErrors:|:is_array( $general_errors ) && count( $general_errors )\">\n	<div class=\'message error\'>\n		{$this->lang->words[\'following_errors\']}\n		<ul>\n			<foreach loop=\"general_errors:$general_errors as $r\">\n				<li>{$r}</li>\n			</foreach>\n		</ul>\n	</div>\n	<br />\n	</if>\n	<form action=\"{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\" method=\"post\" name=\"REG\" id=\'register\'>\n		<input type=\"hidden\" name=\"termsread\" value=\"1\" />\n		<input type=\"hidden\" name=\"agree_to_terms\" value=\"1\" />\n		<input type=\"hidden\" name=\"do\" value=\"process_form\" />\n		<input type=\"hidden\" name=\"coppa_user\" value=\"{$data[\'coppa_user\']}\" />\n		<input type=\'hidden\' name=\'nexus_pass\' value=\'1\' />\n		<input type=\'hidden\' name=\'time_offset\' id=\'auto_time_offset\' value=\'0\' />\n		<input type=\'hidden\' name=\'dst\' id=\'auto_dst\' value=\'0\' />\n		\n		<h1 class=\'maintitle\'>\n			{$this->lang->words[\'ready_register\']}\n		</h1>\n		<div class=\'ipsBox\'>\n		\n			<div class=\'ipsBox_container ipsPad\'>\n			\n				<if test=\"registerServices:|:IPSLib::fbc_enabled() || IPSLib::twitter_enabled() === true\">\n					<div class=\'ipsBox_container ipsBox_notice ipsForm ipsForm_horizontal\' id=\'external_services\'>\n						<strong class=\'ipsField_title\' id=\'save_time\'>{$this->lang->words[\'want_to_save_time\']}</strong>\n						<div class=\'ipsField_content\'>\n							<ul class=\'ipsList_inline\'>\n								<if test=\"registerUsingFb:|:IPSLib::fbc_enabled()\">\n									<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"\" /></a></li>\n								</if>\n								<if test=\"twitterBox:|:IPSLib::twitter_enabled() === true\">\n									<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/twitter/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/twitter_login.png\" alt=\"\" /></a></li>\n								</if>\n							</ul>\n						</div>\n					</div>\n				</if>\n			\n				<if test=\"registerHasInlineErrors:|:is_array( $inline_errors ) && ( $inline_errors[\'username\'] || $inline_errors[\'dname\'] || $inline_errors[\'email\'] || $inline_errors[\'password\'] )\">\n					<p class=\'message error\'>{$this->lang->words[\'reg_errors_found\']}</p>\n					<br />	\n				</if>\n				<fieldset>\n					<ul class=\'ipsForm ipsForm_horizontal\'>\n						<li class=\'ipsField\'>\n							<p class=\'ipsField_content\'>\n								<span class=\'ipsForm_required ipsType_smaller\'>* {$this->lang->words[\'required_field\']}</span>\n							</p>\n						</li>\n						<li class=\'ipsField clear <if test=\"ieDnameClass:|:$inline_errors[\'dname\']\">error</if>\'>\n							<label for=\'display_name\' class=\'ipsField_title\'>{$this->lang->words[\'reg_choose_dname\']} <span class=\'ipsForm_required\'>*</span></label>\n							<p class=\'ipsField_content\'>\n								<input type=\'text\' class=\'input_text\' id=\'display_name\' size=\'45\' maxlength=\'{$this->settings[\'max_user_name_length\']}\' value=\'{$this->request[\'members_display_name\']}\' name=\'members_display_name\' /><br />\n								<span class=\'desc primary lighter\'>\n									<if test=\"ieDname:|:$inline_errors[\'dname\']\"><span class=\'error\'>{$inline_errors[\'dname\']}<br /></span></if>\n									{parse expression=\"sprintf( $this->lang->words[\'dname_desc\'], $this->settings[\'max_user_name_length\'])\"}\n								</span>\n							</p>\n						</li>\n						<li class=\'ipsField clear <if test=\"ieEmailClass:|:$inline_errors[\'email\']\">error</if>\'>\n							<label for=\'email_1\' class=\'ipsField_title\'>{$this->lang->words[\'reg_enter_email\']} <span class=\'ipsForm_required\'>*</span></label>\n							<p class=\'ipsField_content\'>\n								<input type=\'text\' id=\'email_1\' class=\'input_text email\' size=\'45\' maxlength=\'150\' name=\'EmailAddress\' value=\'{$this->request[\'EmailAddress\']}\' /><br />\n								<if test=\"ieEmail:|:$inline_errors[\'email\']\"><span class=\'desc\'><span class=\'error\'>{$inline_errors[\'email\']}</span></span></if>\n							</p>\n						</li>		\n						<li class=\'ipsField clear <if test=\"iePasswordClass:|:$inline_errors[\'password\']\">error</if>\'>\n							<label for=\'password_1\' class=\'ipsField_title\'>{$this->lang->words[\'reg_choose_password\']} <span class=\'ipsForm_required\'>*</span></label>\n							<p class=\'ipsField_content\'>\n								<input type=\'password\' id=\'password_1\' class=\'input_text password\' size=\'45\' maxlength=\'32\' value=\'{$this->request[\'PassWord\']}\' name=\'PassWord\' /><br />\n								<span class=\'desc lighter\'><if test=\"iePassword:|:$inline_errors[\'password\']\"><span class=\'error\'>{$inline_errors[\'password\']}<br /></span></if>{$this->lang->words[\'reg_choose_password_desc\']}</span>\n							</p>\n						</li>\n						<li class=\'ipsField clear\'>\n							<label for=\'password_2\' class=\'ipsField_title\'>{$this->lang->words[\'reg_reenter_password\']} <span class=\'ipsForm_required\'>*</span></label>\n							<p class=\'ipsField_content\'>\n								<input type=\'password\' id=\'password_2\' class=\'input_text password\' size=\'45\' maxlength=\'32\' value=\'{$this->request[\'PassWord_Check\']}\' name=\'PassWord_Check\' /><br />\n							</p>\n						</li>\n					</ul>\n				</fieldset>\n				<if test=\"hasNexusFields:|:!empty( $nexusFields )\">\n					<script type=\'text/javascript\'>\n						var _countriesWithStates = [];\n						<foreach loop=\"statesJs:$nexusStates as $k => $v\">\n							_countriesWithStates[\"{$k}\"] = 1;\n						</foreach>\n					</script>\n					<hr />\n					<fieldset>\n						<ul class=\'ipsForm ipsForm_horizontal\'>\n							<foreach loop=\"fields:$nexusFields as $f\">\n								<if test=\"isAddressOrPhone:|:in_array( $f[\'f_column\'], array( \'cm_address_1\', \'cm_phone\' ) )\">\n									<br />\n								</if>\n								<if test=\"isText:|:$f[\'f_type\'] == \'text\'\">\n									<li class=\'ipsField clear\'>\n										<label for=\'{$f[\'f_column\']}\' class=\'ipsField_title\'><if test=\"isAddress1:|:$f[\'f_column\'] == \'cm_address_1\'\">{$this->lang->words[\'cm_address\']}<else /><if test=\"isAddress2:|:$f[\'f_column\'] == \'cm_address_2\'\">&nbsp;<else />{$f[\'f_name\']}</if></if> <if test=\"textRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\n										<p class=\'ipsField_content\'>\n											<input type=\'text\' class=\'input_text\' id=\'{$f[\'f_column\']}\' size=\'25\' maxlength=\'255\' value=\'{$this->request[ $f[\'f_column\'] ]}\' name=\'{$f[\'f_column\']}\' />\n										</p>\n										<if test=\"textErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\n										</if>\n									</li>\n								</if>\n								<if test=\"isDropdown:|:$f[\'f_type\'] == \'dropdown\'\">\n									<li class=\'ipsField clear\'>\n										<label for=\'{$f[\'f_column\']}\' class=\'ipsField_title\'>{$f[\'f_name\']} <if test=\"dropdownRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\n										<div class=\'ipsField_content\'>\n											<select name=\'{$f[\'f_column\']}\' id=\'{$f[\'f_column\']}\' <if test=\"isCountry:|:$f[\'f_column\'] == \'cm_country\'\">onchange=\'states()\'</if>>\n												<foreach loop=\"options:explode( \"\\n\", $f[\'f_extra\'] ) as $k => $v\">\n													{parse variable=\"selected\" default=\"\" oncondition=\"$k == $this->request[ $f[\'f_column\'] ] or $v == $this->request[ $f[\'f_column\'] ]\" value=\" selected=\'selected\'\"}\n													<option value=\'<if test=\"isCountrySelect:|:$f[\'f_column\'] == \'cm_country\'\">{$v}<else />{$k}</if>\'{parse variable=\"selected\"}><if test=\"isCountryWords:|:$f[\'f_column\'] == \'cm_country\'\">{$this->lang->words[\'nc_\'.$v]}<else />{$v}</if></option>\n												</foreach>\n											</select>\n										</div>\n										<if test=\"dropdownErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\n										</if>\n									</li>\n								</if>\n								<if test=\"isSpecial:|:$f[\'f_type\'] == \'special\'\">\n									<li class=\'ipsField clear\'>\n										<label for=\'cm_state\' class=\'ipsField_title\'>{$this->lang->words[\'cm_state\']} <if test=\"specialRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\n										<div class=\'ipsField_content\'>\n											<input type=\'text\' class=\'input_text\' id=\'text-states\' size=\'25\' name=\'cm_state\' value=\'{$this->request[\'cm_state\']}\' />\n											<foreach loop=\"statesCountries:$nexusStates as $country => $_states\">\n												<select name=\'_cm_state\' id=\'{$country}-states\' class=\'input_select\' style=\'display:none\'>\n													<foreach loop=\"states:$_states as $s\">\n														{parse variable=\"selected\" default=\"\" oncondition=\"$s[0] == $this->request[\'cm_state\']\" value=\" selected=\'selected\'\"}\n														<option value=\'{$s[0]}\'{parse variable=\"selected\"}>{$s[1]}</option>\n													</foreach>\n												</select>\n											</foreach>\n										</div>\n										<if test=\"specialErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\n										</if>\n									</li>\n								</if>\n							</foreach>\n						</ul>\n					</fieldset>\n					<script type=\'text/javascript\'>\n						function states()\n						{\n							var c = $(\'cm_country\').value;\n							if ( c in _countriesWithStates )\n							{\n								$( _display ).style.display = \'none\';\n								$( _display ).name = \'_cm_state\';\n								\n								$( c + \'-states\' ).style.display = \'\';\n								$( c + \'-states\' ).name = \'cm_state\';\n								\n								_display = c + \'-states\';\n							}\n							else\n							{\n								$( _display ).style.display = \'none\';\n								$( _display ).name = \'_cm_state\';\n								\n								$( \'text-states\' ).style.display = \'\';\n								$( \'text-states\' ).name = \'cm_state\';\n								\n								_display = \'text-states\';\n							}\n						}\n						\n						var _display = \'text-states\';\n						states();\n					</script>\n				</if>				\n				<if test=\"hasCfields:|:( is_array( $custom_fields[\'required\'] ) && count( $custom_fields[\'required\'] ) ) || ( is_array( $custom_fields[\'optional\'] ) && count( $custom_fields[\'optional\'] ) )\">\n				<hr />\n					<fieldset>\n						<ul class=\'ipsForm ipsForm_horizontal\'>\n						<if test=\"reqCfields:|:is_array( $custom_fields[\'required\'] ) && count( $custom_fields[\'required\'] )\">\n							<foreach loop=\"custom_required:$custom_fields[\'required\'] as $_field\">\n								<li class=\'ipsField clear ipsField_{$_field[\'type\']}\'>\n									<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']} <span class=\'ipsForm_required\'>*</span></label>\n									<div class=\'ipsField_content\'>\n										{$_field[\'field\']}\n										<if test=\"reqCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><br /><span class=\'desc\'>{$_field[\'desc\']}</span></if>\n									</div>\n								</li>\n							</foreach>\n						</if>\n			\n						<if test=\"optCfields:|:is_array( $custom_fields[\'optional\'] ) && count( $custom_fields[\'optional\'] )\">\n							<foreach loop=\"custom_optional:$custom_fields[\'optional\'] as $_field\">\n								<li class=\'ipsField clear ipsField_{$_field[\'type\']}\'>\n									<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']}</label>\n									<div class=\'ipsField_content\'>\n										{$_field[\'field\']}\n										<if test=\"optCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><br /><span class=\'desc\'>{$_field[\'desc\']}</span></if>\n									</div>\n								</li>\n							</foreach>\n						</if>\n					</fieldset>				\n				</if>\n				<hr />\n				{$data[\'qandaHTML\']}\n				{$data[\'captchaHTML\']}\n				<hr />\n				<fieldset>\n					<ul class=\'ipsForm ipsForm_horizontal\'>\n						<li class=\'ipsField clear ipsField_checkbox\'>\n							<input type=\"checkbox\" name=\"allow_admin_mail\" id=\"allow_admin_mail\" value=\"1\" class=\"input_check\" <if test=\"defaultAAE:|:$this->request[\'allow_admin_mail\'] || !isset( $this->request[\'allow_admin_mail\'] )\">checked=\'checked\'</if> />\n							<p class=\'ipsField_content\'>\n								<label for=\'allow_admin_mail\'>{$this->lang->words[\'receive_admin_emails\']}</label>\n							</p>\n						</li>\n						<li class=\'ipsField clear ipsField_checkbox\'>\n							<input type=\'checkbox\' name=\'agree_tos\' id=\'agree_tos\' value=\'1\' class=\'input_check\' <if test=\"checkedTOS:|:$this->request[\'agree_tos\']\">checked=\"checked\"</if> />\n							<p class=\'ipsField_content\'>\n								<label for=\'agree_tos\' <if test=\"ieDnameClass:|:$inline_errors[\'dname\']\">error</if>>\n									<strong>{$this->lang->words[\'agree_to_tos\']} <a href=\'#\' id=\'tou_link\'>{$this->lang->words[\'terms_of_use\']}</a></strong>\n									<if test=\"ieTOS:|:$inline_errors[\'tos\']\"><br /><span class=\'error\'>{$inline_errors[\'tos\']}</span></if>\n								</label>	\n								<textarea id=\'tou\' class=\'input_text\' style=\'width: 350px; height: 100px; display: block;\'>\n									{$this->settings[\'_termsAndConditions\']}\n								</textarea>\n							</p>\n						</li>\n					</ul>\n					<script type=\'text/javascript\'>\n						$(\'tou\').hide();				\n					</script>\n				</fieldset>\n				<br />\n				<fieldset>\n					<input type=\'submit\' class=\'ipsButton\' id=\'register_submit\' value=\'{$this->lang->words[\'register\']}\' />\n				</fieldset>	\n			</div>\n		</div>\n	</form>\n	<script type=\'text/javascript\'>\n		ipb.templates[\'registration_terms\'] = new Template(\"<h3>{$this->lang->words[\'reg_terms_popup_title\']}</h3><div class=\'ipsPad\' id=\'tou_popup\'>#{content}</div>\");\n	</script>\n	{parse template=\"registerCoppaStart\" group=\"register\" params=\"\"}\n</div>', 'registerForm', '$general_errors=array(), $data=array(), $inline_errors=array(), $time_select=array(), $custom_fields=array(), $nexusFields=array(), $nexusStates=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('107', '0', 'skin_register', '<php>\n	$this->templateVars[\'step_count\'] = 1;\n</php>\n<div class=\'ipsSteps clearfix\'>\n	<ul>\n		<if test=\"IPSLib::appIsInstalled(\'nexus\') AND $this->settings[\'nexus_reg_show\'] AND $this->settings[\'nexus_store_online\']\">\n			<li class=\'<if test=\"$this->request[\'nexus_pass\']\">ipsSteps_done<else />ipsSteps_active</if>\'>\n				<strong class=\'ipsSteps_title\'>{parse expression=\"sprintf($this->lang->words[\'regstep\'], $this->templateVars[\'step_count\'])\"}</strong>\n				<span class=\'ipsSteps_desc\'>{$this->lang->words[\'regstep_choose_package\']}</span>\n				<span class=\'ipsSteps_arrow\'>&nbsp;</span>\n			</li>\n			<!--Don\'t delete: {parse expression=\"$this->templateVars[\'step_count\']++\"}-->\n		</if>\n		<li class=\'{$step[\'register_form\']}\'>\n			<strong class=\'ipsSteps_title\'>{parse expression=\"sprintf($this->lang->words[\'regstep\'], $this->templateVars[\'step_count\'])\"}</strong>\n			<span class=\'ipsSteps_desc\'>{$this->lang->words[\'regstep_your_account\']}</span>\n			<span class=\'ipsSteps_arrow\'>&nbsp;</span>\n			<!--Don\'t delete: {parse expression=\"$this->templateVars[\'step_count\']++\"}-->\n		</li>\n		<li class=\'{$step[\'confirmation\']}\'>\n			<strong class=\'ipsSteps_title\'>{parse expression=\"sprintf($this->lang->words[\'regstep\'], $this->templateVars[\'step_count\'])\"}</strong>\n			<span class=\'ipsSteps_desc\'>{$this->lang->words[\'regstep_confirm\']}</span>\n			<span class=\'ipsSteps_arrow\'>&nbsp;</span>\n		</li>\n	</ul>\n</div>\n<br />', 'registerStepBar', '$step', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('108', '0', 'skin_register', '<input type=\"hidden\" name=\"uid\" value=\"{$uid}\" />\n<input type=\"hidden\" name=\"aid\" value=\"{$aid}\" />', 'show_lostpass_form_auto', '$aid=\"\",$uid=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('109', '0', 'skin_register', '<h3 class=\'bar\'>{$this->lang->words[\'lpf_title\']}</h3>\n	<ul>\n		<li class=\'field\'>\n			<label for=\'user_id\'>{$this->lang->words[\'user_id\']}</label>\n			<input type=\"text\" size=\"32\" maxlength=\"32\" name=\"uid\" id=\'user_id\' class=\'input_text\' />\n		</li>\n		<li class=\'field\'>\n			<label for=\'aid\'>{$this->lang->words[\'val_key\']}</label>\n			<input type=\"text\" size=\"32\" maxlength=\"50\" name=\"aid\" id=\'aid\' class=\'input_text\' />\n		</li>\n	</ul>', 'show_lostpass_form_manual', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('110', '0', 'skin_register', '<div id=\'register_form\'>\n	{parse template=\"registerStepBar\" group=\"register\" params=\"array(\'register_form\' => \'\', \'confirmation\' => \'ipsSteps_active\')\"}\n	<h1 class=\'maintitle\'>{$this->lang->words[\'ready_register\']}</h1>\n	<div class=\'ipsBox\'>\n		<div class=\'ipsBox_container ipsPad\'>\n			{$this->lang->words[\'thank_you\']} {$member[\'members_display_name\']}. {$this->lang->words[\'auth_text\']} {$member[\'email\']}\n		</div>\n	</div>\n</div>', 'showAuthorize', '$member=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('111', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'dumb_header\']}</h1>\n<div class=\'ipsType_pageinfo\'>\n	{$this->lang->words[\'dumb_text\']}\n</div>\n<if test=\"lostpassFormErrors:|:!empty( $error )\">\n	<p class=\'message error\'>\n		{$error}\n	</p>\n</if>\n<form action=\"{parse url=\"app=core&module=global&section=lostpass\" base=\"public\"}\" method=\"post\">\n<input type=\"hidden\" name=\"do\" value=\"03\" />\n<input type=\"hidden\" name=\"type\" value=\"lostpass\" />\n<div class=\'generic_bar\'></div>\n	<div class=\'post_form\'>\n		<!--IBF.INPUT_TYPE-->\n		<h3 class=\'bar\'>{$this->lang->words[\'new_password\']}</h3>\n		<if test=\"lpFormMethodChoose:|:$this->settings[\'lp_method\'] == \'choose\'\">\n			<ul>\n				<li class=\'field\'>\n					<label for=\"pass1\">{$this->lang->words[\'lpf_pass1\']}</label>\n					<input type=\"password\" size=\"32\" maxlength=\"32\" name=\"pass1\" id=\'pass1\' class=\'input_text\' />\n					<br /><span class=\'desc\'>{$this->lang->words[\'lpf_pass11\']}</span>\n				</li>\n				<li class=\'field\'>\n					<label for=\"pass2\">{$this->lang->words[\'lpf_pass2\']}</label>\n					<input type=\"password\" size=\"32\" maxlength=\"32\" name=\"pass2\" id=\'pass2\' class=\'input_text\' />\n					<br /><span class=\'desc\'>{$this->lang->words[\'lpf_pass22\']}</span>\n				</li>\n			</ul>\n		<else />\n			<p class=\'field\'>\n		 		{$this->lang->words[\'lp_random_pass\']}\n			</p>\n		</if>\n		<!--{REG.ANTISPAM}-->\n		<fieldset class=\'submit\'>\n			<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'dumb_submit\']}\" />\n		</fieldset>\n	</div>\n</form>', 'showLostpassForm', '$error', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('112', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'lpf_title\']}</h1>\n<br />\n<p class=\'message\'>\n	{$this->lang->words[\'lpass_text_random\']}\n</p>', 'showLostPassWaitRandom', '$member=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('113', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'dumb_header\']}</h1>\n<form action=\"{parse url=\"\" base=\"public\"}\" method=\"post\" name=\"REG\">\n<input type=\"hidden\" name=\"app\" value=\"core\" />\n<input type=\"hidden\" name=\"module\" value=\"global\" />\n<input type=\"hidden\" name=\"section\" value=\"register\" />\n<input type=\"hidden\" name=\"do\" value=\"auto_validate\" />\n<input type=\"hidden\" name=\"type\" value=\"{$type}\" />\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset class=\'row1\'>\n		<h3 class=\'bar\'>{$this->lang->words[\'complete_form\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'userid\'>{$this->lang->words[\'user_id\']}</label>\n				<input type=\"text\" size=\"32\" maxlength=\"32\" name=\"uid\" id=\'userid\' class=\'input_text\' />\n			</li>\n			<li class=\'field\'>\n				<label for=\'valkey\'>{$this->lang->words[\'val_key\']}</label>\n				<input type=\"text\" size=\"32\" maxlength=\"50\" name=\"aid\" id=\'valkey\' class=\'input_text\' />\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'dumb_submit\']}\" />\n	</fieldset>\n</div>\n</form>', 'showManualForm', '$type=\"reg\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('114', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'registration_process\']}</h1>\n<br />\n<p class=\'message\'>\n	{$this->lang->words[\'thank_you\']} {$member[\'members_display_name\']}. {$this->lang->words[\'preview_reg_text\']}\n</p>', 'showPreview', '$member=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('115', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'rv_title\']}</h1>\n<br />\n<p class=\'message\'>\n	{$this->lang->words[\'rv_process\']}<br />\n	{$this->lang->words[\'rv_done\']}\n</p>', 'showRevalidated', '', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('116', '0', 'skin_register', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'rv_title\']}</h1>\n<br />\n<if test=\"revalidateError:|:$error\">\n<p class=\'message error\'>{$this->lang->words[$error]}</p>\n<br />\n</if>\n<form action=\"{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\" method=\"post\" name=\"REG\">\n<input type=\"hidden\" name=\"do\" value=\"reval2\" />\n	<p class=\'message unspecific\'>\n		{$this->lang->words[\'rv_ins\']}\n	</p>\n	\n	<div class=\'post_form\'>\n		<fieldset class=\'general_box\'>\n			<h3>{$this->lang->words[\'rv_bar_title\']}</h3>\n			<label for=\'username\'>{$this->lang->words[\'rv_name\']}</label>\n			<input type=\"text\" class=\'input_text\' id=\'username\' size=\"32\" maxlength=\"64\" name=\"username\" value=\"$name\" />\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'rv_go\']}\" /> {$this->lang->words[\'or\']} <a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</div>\n</form>', 'showRevalidateForm', '$name=\"\",$error=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('117', '0', 'skin_reports', '<h2 class=\'maintitle\'>{$this->lang->words[\'report_basic_title\']}</h2>\n<div class=\'generic_bar\'></div>\n<form action=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;rcom={$this->request[\'rcom\']}&amp;send=1\" method=\"post\" name=\"REPLIER\">\n	<input type=\'hidden\' name=\'k\' value=\'{$this->member->form_hash}\' />\n	<div class=\'ipsForm ipsForm_horizontal\'>\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'reporting_title\']} <a href=\"{$url}\" title=\'{$this->lang->words[\'view_content\']}\'>{$name}</a></h3>\n			<ul class=\'ipsPad\'>\n				<li class=\'ipsField\'>\n					<label for=\'message\' class=\'ipsField_title\'>{$this->lang->words[\'report_basic_enter\']}</label>\n					<p class=\'ipsField_content\'>\n						<textarea id=\'message\' class=\'input_text\' name=\'message\' cols=\'60\' rows=\'8\'></textarea><br />\n						<span class=\'desc\'>{$this->lang->words[\'report_basic_desc\']}</span>\n					</p>\n				</li>\n				{$extra_data}\n			</ul>\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'report_basic_submit\']}\" accesskey=\'s\' /> {$this->lang->words[\'or\']} <a href=\'{$url}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</div>\n</form>', 'basicReportForm', '$name=\"\", $url=\"\", $extra_data=\"\"', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('118', '0', 'skin_reports', '{parse js_module=\"reports\"}\n<if test=\"noviewall:|:!$this->request[\'showall\']\">\n	<p class=\'message\'>{$this->lang->words[\'only_active_note\']}  <a href=\'{parse url=\"app=core&amp;module=reports&amp;do=index&amp;showall=1\" base=\"public\"}\'>{$this->lang->words[\'click_here_link\']}</a> {$this->lang->words[\'to_view_allrep\']}</p>\n</if>\n<if test=\"hasPages:|:$pages\">\n	<div class=\'topic_controls\'>\n		{$pages}\n	</div>\n</if>\n<br class=\'clear\' />\n<form method=\"post\" action=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;do=process&amp;st={$this->request[\'st\']}\">\n<input type=\'hidden\' name=\'k\' value=\'{$this->member->form_hash}\' />\n<table class=\'ipb_table report_center\' summary=\'{$this->lang->words[\'reported_content_summary\']}\'>\n	<caption class=\'maintitle\'>{$this->lang->words[\'list_title\']}</caption>\n	<tr class=\'header\'>\n		<th scope=\'col\' class=\'col_r_icon\'>&nbsp;</th>\n		<th scope=\'col\' class=\'col_r_title\'>{$this->lang->words[\'list_header_title\']}</th>\n		<th scope=\'col\' class=\'col_r_section\'>{$this->lang->words[\'list_header_section\']}</th>\n		<th scope=\'col\' class=\'col_r_total short\'>{$this->lang->words[\'list_header_reports\']}</th>\n		<th scope=\'col\' class=\'col_r_comments short\'>{$this->lang->words[\'list_header_comments\']}</th>\n		<th scope=\'col\' class=\'col_r_updated\'>{$this->lang->words[\'list_header_updated_by\']}</th>\n		<th scope=\'col\' class=\'col_r_mod\'><input type=\'checkbox\' id=\'checkAllReports\' title=\'{$this->lang->words[\'select_all_reports\']}\' class=\'input_check\' /></th>\n	</tr>\n	<if test=\"indexHasReports:|:count($reports)\">\n		{parse striping=\"reportsTable\" classes=\"row1,row2\"}\n		<foreach loop=\"reports:$reports as $report\">\n			<tr class=\'{parse striping=\"reportsTable\"}\'>\n				<td class=\'short altrow\'>\n					<if test=\"isread:|:$report[\'_isRead\']\">\n						{parse replacement=\"t_read\"}\n					<else />\n						{parse replacement=\"t_unread\"}\n					</if>\n					<a href=\"{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=process&amp;report_ids[{$report[\'id\']}]={$report[\'id\']}&amp;newstatus=2&amp;k={$this->member->form_hash}\" base=\"public\"}\" title=\'{$this->lang->words[\'change_current_status\']}\' class=\'ipbmenu\' id=\'change_status-{$report[\'id\']}\'><span id=\"rstat-{$report[\'id\']}\">{$report[\'status_icon\']}</span></a>\n				</td>\n				<td>\n					<a href=\"{$this->settings[\'base_url\']}&amp;app=core&amp;module=reports&amp;do=show_report&amp;rid={$report[\'id\']}\" title=\'{$this->lang->words[\'view_report\']}\'>{$report[\'title\']}</a>\n					<if test=\"statusesLoop:|:is_array( $statuses ) && count( $statuses )\">\n						<ul class=\'ipbmenu_content\' id=\'change_status-{$report[\'id\']}_menucontent\'>\n							<foreach loop=\"statuses:$statuses as $status_id => $status\">\n								<li class=\'{$status_id} <if test=\"$status_id == $report[\'status\']\">status-selected</if>\'><a href=\"{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=process&amp;report_ids[{$report[\'id\']}]={$report[\'id\']}&amp;newstatus={$status_id}&amp;k={$this->member->form_hash}\" base=\"public\"}\" title=\'{$this->lang->words[\'change_status_title\']}\' class=\'change-status\' id=\'{$report[\'id\']}:{$status_id}\'>{$this->lang->words[\'mark_status_as\']} <strong>{$status[\'title\']}</strong></a></li>\n							</foreach>\n						</ul>\n					</if>\n				</td>\n				<td class=\'altrow\'>\n					<if test=\"indexReportUrl:|:$report[\'section\'][\'url\']\">\n						<if test=\"!$report[\'section\'][\'title\']\">\n							<a href=\"{$report[\'section\'][\'url\']}\" title=\'{$this->lang->words[\'go_to_section\']}\' class=\'desc blend_links\'>{$this->lang->words[\'report_no_title\']}</a>\n						<else />\n							<a href=\"{$report[\'section\'][\'url\']}\" title=\'{$this->lang->words[\'go_to_section\']}\'>{$report[\'section\'][\'title\']}</a>\n						</if>\n					<else />\n						<if test=\"!$report[\'section\'][\'title\']\">\n							{$this->lang->words[\'report_no_title\']}\n						<else />\n							{$report[\'section\'][\'title\']}\n						</if>\n					</if>\n				</td>\n				<td class=\'short\'>{$report[\'num_reports\']}</td>\n				<td class=\'short altrow\'>{$report[\'num_comments\']}</td>\n				<td>\n					<a href=\'{parse url=\"showuser={$report[\'updated_by\']}\" seotitle=\"{$report[\'member\'][\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n						<img src=\'{$report[\'member\'][\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n					</a>\n					<ul class=\'last_post ipsType_small\'>\n						<li>{$this->lang->words[\'by_ucfirst\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$report[\'member\']\"}</li>\n						<li>{parse date=\"$report[\'date_updated\']\" format=\"date\"}</li>\n					</ul>\n				</td>\n				<td class=\'short altrow\'>\n					<input type=\'checkbox\' id=\'report_check_{$report[\'id\']}\' class=\'input_check checkall\' name=\'report_ids[]\' value=\'{$report[\'id\']}\' />\n				</td>\n			</tr>\n		</foreach>\n	<else />\n		<tr>\n			<td colspan=\'7\' class=\'no_messages row1\'>\n				{$this->lang->words[\'no_reports\']}\n			</td>\n		</tr>\n	</if>\n</table>\n<div id=\'topic_mod\' class=\'moderation_bar rounded with_action clear\'>\n	<a href=\'#\' class=\'ipsButton_secondary left\' id=\'prune_reports\'>{$this->lang->words[\'report_option_prune\']}</a>\n	<span class=\'desc\'>{$this->lang->words[\'r_with_selected\']}</span>\n	<select name=\"newstatus\" id=\"report_actions\">\n		<option value=\"x\">---</option>\n		<if test=\"accessACP:|:$this->memberData[\'g_access_cp\']\">\n			<optgroup label=\"{$this->lang->words[\'report_actions\']}\"  style=\"font-style: normal;\">\n			<if test=\"$this->memberData[\'g_access_cp\']\"><option value=\"d\">{$this->lang->words[\'report_option_delete\']}</option></if>\n			</optgroup>\n		</if>\n		<optgroup label=\"{$this->lang->words[\'report_actions_mark_optgroup\']}\" style=\"font-style: normal;\">\n		{$acts}\n		</optgroup>\n	</select>\n	<label for=\'pruneDayBox\' id=\'pruneDayLabel\'>{$this->lang->words[\'older_than\']}</label>\n	<input type=\"text\" name=\"pruneDays\" id=\"pruneDayBox\" class=\'input_text\' size=\"3\" value=\"\" />\n	<span id=\'pruneDayLang\'>{$this->lang->words[\'report_prune_days_box\']}</span>\n	<input type=\"submit\" id=\'report_mod\' class=\"input_submit alt\" value=\"{$this->lang->words[\'r_go\']}\" />\n</div>\n</form>\n<div id=\'prune_reports_form\' style=\'display: none\'>\n	<div class=\'ipsPad ipsForm_center\'>\n		<form method=\"post\" action=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;do=process&amp;st={$this->request[\'st\']}\">\n		<input type=\'hidden\' name=\'k\' value=\'{$this->member->form_hash}\' />\n		<input type=\'hidden\' name=\'newstatus\' value=\'p\' />\n		{$this->lang->words[\'report_prune_1\']} <input type=\"text\" name=\"pruneDays\" id=\"pruneDayBox\" class=\'input_text\' size=\"3\" value=\"\" /> {$this->lang->words[\'report_prune_2\']}&nbsp;&nbsp;\n		<input type=\"submit\" id=\'report_mod\' class=\"input_submit alt\" value=\"{$this->lang->words[\'r_go\']}\" />\n	</div>\n</div>\n<script type=\'text/javascript\'>\n	$(\'prune_reports\').observe(\'click\', function(e){\n		Event.stop(e);\n		if( ipb.reports.prunePopup ){\n			ipb.reports.prunePopup.kill();\n		}\n		else\n		{\n			ipb.reports.prunePopup = new ipb.Popup( \'prune\', { type: \'balloon\',\n																	initial: $(\'prune_reports_form\').show(),\n																	stem: true,\n																	hideClose: true,\n																	attach: { target: $(\'prune_reports\'), position: \'auto\' },\n																	hideAtStart: false,\n																	w: \'350px\' });\n		}\n	});\n</script>', 'reportsIndex', '$reports=array(), $acts=\"\", $pages=\"\", $statuses=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('119', '0', 'skin_reports', '<img src=\'{$this->settings[\'public_dir\']}{$img}\' alt=\'{$this->lang->words[\'status\']}\' />', 'statusIcon', '$img, $width, $height', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('120', '0', 'skin_reports', '{parse js_module=\"reports\"}\n<div class=\'message\'>\n	{$this->lang->words[\'report_about_intro\']} <if test=\"handlePmSpecial:|:$options[\'class\'] == \'messages\'\">\n		{$this->lang->words[\'report_about_pm\']} {$options[\'title\']}.\n		<if test=\"canJoinPm:|:in_array( $this->memberData[\'member_group_id\'], explode( \',\', $this->registry->getClass(\'reportLibrary\')->plugins[\'messages\']->_extra[\'plugi_messages_add\'] ) )\">\n			<a href=\'{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=showMessage&amp;topicID={$options[\'topicID\']}\" base=\"public\"}\'>{$this->lang->words[\'report_join_pm\']}</a>\n		</if>\n	<else />\n		<a href=\"{$options[\'url\']}\" title=\"{$this->lang->words[\'report_view_reported\']}\">{$options[\'title\']}</a>\n	</if>\n</div>\n<br />\n<div class=\'topic_controls\'>\n	<ul class=\'topic_buttons\'>\n		<if test=\"$this->memberData[\'g_access_cp\']\"><li><a href=\'{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=process&amp;report_ids[{$options[\'rid\']}]={$options[\'rid\']}&amp;newstatus=d&amp;k={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'delete_report\']}\'><img src=\'{$this->settings[\'img_url\']}/delete.png\' alt=\'\' id=\'delete_report\' /> {$this->lang->words[\'delete_report\']}</a></li></if>\n		<li><a href=\'{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=process&amp;report_ids[{$options[\'rid\']}]={$options[\'rid\']}&amp;newstatus=2&amp;k={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'change_current_status\']}\' class=\'ipbmenu\' id=\'change_status\'>{$options[\'status_icon\']} {$this->lang->words[\'current_status\']} <strong>{$options[\'status_text\']}</strong></a></li>\n	</ul>\n</div>\n<if test=\"statusesLoop:|:is_array( $options[\'statuses\'] ) && count( $options[\'statuses\'] )\">\n	<ul class=\'ipbmenu_content\' id=\'change_status_menucontent\'>\n		<foreach loop=\"statuses:$options[\'statuses\'] as $status_id => $status\">\n			<if test=\"setStatus:|:$status_id != $options[\'status_id\']\">\n				<li><a href=\"{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;do=process&amp;report_ids[{$options[\'rid\']}]={$options[\'rid\']}&amp;newstatus={$status_id}&amp;k={$this->member->form_hash}\" base=\"public\"}\" title=\'{$this->lang->words[\'change_status_title\']}\' />{$this->lang->words[\'mark_status_as\']} <strong>{$status[\'title\']}</strong></a></li>\n			</if>\n		</foreach>\n	</ul>\n</if>\n<br />\n<div class=\'topic hfeed\'>\n<h2 class=\'maintitle\'>{$this->lang->words[\'reports_h2\']}</h2>\n<div class=\'generic_bar\'></div>\n<if test=\"hasReports:|:is_array($reports) AND count($reports)\">\n	<foreach loop=\"viewReports:$reports as $report\">\n		<div class=\'post_block  hentry clear\'>\n			<div class=\'post_wrap\'>\n				<h3><a href=\'{parse url=\"showuser={$report[\'member_id\']}\" seotitle=\"{$report[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_member\']}\'>{$report[\'members_display_name\']}</a></h3>\n				<div class=\'author_info\'>\n					{parse template=\"userInfoPane\" group=\"global\" params=\"$report[\'author\'], \'mreport\', array()\"}\n				</div>\n				<div class=\'post_body\'>\n					<p class=\'posted_info\'>{$this->lang->words[\'posted_prefix\']} {parse date=\"$report[\'date_reported\']\" format=\"long\"}</p>\n					<div class=\'post entry-content\'>{$report[\'report\']}</div>\n				</div>\n			</div>\n			<br class=\'clear\' />\n		</div>\n	</foreach>\n</if>\n</div>\n<br /><hr /><br />\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<h2 class=\'ipsType_subtitle\'>{$comments[\'count\']} {$this->lang->words[\'comments_h2\']}</h2>\n		<div>\n			{$comments[\'html\']}\n		</div>\n	</div>\n</div>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}', 'viewReport', '$options=array(), $reports=array(), $comments=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('121', '0', 'skin_search', '<!--Begin Msg Number {$data[\'pid\']}-->\n<div class=\'post_block hentry clear no_sidebar ipsBox_container\' id=\'post_id_{$data[\'pid\']}\'>\n	<div class=\'post_wrap\'>\n		<if test=\"postMid:|:$data[\'member_id\']\">\n			<h3 class=\'row2\'>\n		<else />\n			<h3 class=\'guest row2\'>\n		</if>\n		<if test=\"postModCheckbox:|:$this->memberData[\'g_is_supmod\']\">\n			<span class=\'right\'>\n				<label for=\'checkbox_{$data[\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$data[\'pid\']}\' name=\'selectedpids[]\' value=\'{$data[\'pid\']}\' class=\'post_mod right\'<if test=\"postModSelected:|:!empty( $data[\'_pid_selected\'] )\"> checked=\'checked\'</if> />\n			</span>\n		</if>\n			<span class=\'post_id right ipsType_small desc blend_links\'><a href=\'{parse url=\"showtopic={$data[\'topic_id\']}&amp;view=findpost&amp;p={$data[\'pid\']}\" template=\"showtopic\" seotitle=\"{$data[\'title_seo\']}\" base=\"public\"}\' rel=\'bookmark\' title=\'{$this->lang->words[\'link_to_post\']} #{$data[\'pid\']}\'>#{$data[\'pid\']}</a></span>\n			<a href=\"{parse url=\"showtopic={$data[\'tid\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\">{IPSText::truncate( $data[\'topic_title\'], 80)}</a>\n		</h3>\n		<div class=\'post_body\'>\n			<p class=\'posted_info desc lighter ipsType_small\'>\n				<img src=\'{$data[\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_tiny\' /> {$this->lang->words[\'posted\']} {$this->lang->words[\'search_by\']}\n				<if test=\"postMember:|:$data[\'member_id\']\"><span class=\"author vcard\">{parse template=\"userHoverCard\" group=\"global\" params=\"$data\"}</span><else />{$data[\'members_display_name\']}</if>\n				{$this->lang->words[\'on\']} <abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $data[\'_post_date\'] )\"}\">{parse date=\"$data[\'_post_date\']\" format=\"long\"}</abbr>\n				<if test=\"hasForumTrail:|:$data[\'_forum_trail\']\">\n					in\n					<foreach loop=\"topicsForumTrail:$data[\'_forum_trail\'] as $i => $f\">\n						<if test=\"notLastFtAsForum:|:$i+1 == count( $data[\'_forum_trail\'] )\"><a href=\'{parse url=\"{$f[1]}\" template=\"showforum\" seotitle=\"{$f[2]}\" base=\"public\"}\'>{$f[0]}</a></if>\n					</foreach>\n				</if>\n			</p>\n			<div class=\'post entry-content\'>\n				{$data[\'post\']}\n				{$data[\'attachmentHtml\']}\n			</div>\n		</div>\n	</div>\n	<br />\n</div>\n<hr />\n<br />', 'asForumPosts', '$data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('122', '0', 'skin_search', '<tr class=\'__topic __tid{$data[\'tid\']} <if test=\"!$data[\'_icon\'][\'is_read\']\">unread</if> expandable <if test=\"$data[\'approved\'] != 1\"> moderated</if>\' id=\'trow_{$data[\'tid\']}\' data-tid=\"{$data[\'tid\']}\">\n	<td class=\'col_f_icon short altrow\'>\n		{parse template=\"generateTopicIcon\" group=\"global_other\" params=\"$data[\'_icon\'], $data[\'_unreadUrl\']\"}\n	</td>\n	<td>\n		<if test=\"hasPrefix:|:!empty($data[\'tags\'][\'formatted\'][\'prefix\'])\">\n			{$data[\'tags\'][\'formatted\'][\'prefix\']}\n		</if>\n		<h4><a href=\'{parse url=\"showtopic={$data[\'tid\']}<if test=\"isNewPostTR:|:$this->request[\'do\']==\'new_posts\' OR $this->request[\'do\']==\'active\'\">&amp;view=getnewpost<else /><if test=\"resultIsPostTR:|:$data[\'pid\'] AND $data[\'pid\'] != $data[\'topic_firstpost\']\">&amp;view=findpost&amp;p={$data[\'pid\']}</if></if>&amp;hl={$data[\'cleanSearchTerm\']}&amp;fromsearch=1\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'view_result\']}\'>{$data[\'_shortTitle\']}</a></h4>\n		<span class=\'desc blend_links\'>\n			<foreach loop=\"topicsForumTrail:$data[\'_forum_trail\'] as $i => $f\">\n			<if test=\"notLastFtAsForum:|:$i+1 == count( $data[\'_forum_trail\'] )\"><span class=\'desc lighter\'>{$this->lang->words[\'search_aft_in\']}</span> <a href=\'{parse url=\"{$f[1]}\" template=\"showforum\" seotitle=\"{$f[2]}\" base=\"public\"}\'>{$f[0]}</a></if>\n			</foreach>\n		</span>\n		<span class=\'desc lighter blend_links toggle_notify_off\'>\n			<br />{$this->lang->words[\'aft_started_by\']} {$data[\'starter\']}, {parse date=\"$data[\'start_date\']\" format=\"DATE\"}\n			<if test=\"hasTags:|:count($data[\'tags\'][\'formatted\'])\">\n				&nbsp;<img src=\'{$this->settings[\'img_url\']}/icon_tag.png\' /> {$data[\'tags\'][\'formatted\'][\'truncatedWithLinks\']}\n			</if>\n		</span>\n		<if test=\"multipages:|:isset( $data[\'pages\'] ) AND is_array( $data[\'pages\'] ) AND count( $data[\'pages\'] )\">\n			<ul class=\'mini_pagination toggle_notify_off\'>\n			<foreach loop=\"pages:$data[\'pages\'] as $page\">\n					<if test=\"haslastpage:|:$page[\'last\']\">\n						<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']} {$this->lang->words[\'_rarr\']}</a></li>\n					<else />\n						<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']}</a></li>\n					</if>\n			</foreach>\n			</ul>\n		</if>\n		<if test=\"bothSearchUnderTitle:|:IPSSearchRegistry::get(\'set.searchResultType\') == \'both\'\">\n			<span class=\'desc lighter blend_links toggle_notify_off\'>\n				<br />{$this->lang->words[\'n_last_post_by\']} {$data[\'last_poster\']},\n				<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;view=getlastpost\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{parse date=\"$data[\'_last_post\']\" format=\"DATE\"}</a>\n			</span>\n		</if>\n		<if test=\"isFollowedStuff:|:count($data[\'_followData\'])\">\n			{parse template=\"followData\" group=\"search\" params=\"$data[\'_followData\']\"}\n		</if>			\n	</td>\n	<td class=\'col_f_preview __topic_preview\'>\n		<a href=\'#\' class=\'expander closed\' title=\'{$this->lang->words[\'view_topic_preview\']}\'>&nbsp;</a>\n	</td>\n	<td class=\'col_f_views\'>\n		<ul>\n			<li>{parse format_number=\"$data[\'posts\']\"} <if test=\"replylang:|:intval($data[\'posts\']) == 1\">{$this->lang->words[\'reply\']}<else />{$this->lang->words[\'replies\']}</if></li>\n			<li class=\'views desc\'>{parse format_number=\"$data[\'views\']\"} {$this->lang->words[\'views\']}</li>\n		</ul>\n	</td>\n	<td class=\'col_f_post\'>\n		<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n			<img src=\'{$data[\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n		</a>\n		<ul class=\'last_post ipsType_small\'>\n			<if test=\"bothSearch:|:IPSSearchRegistry::get(\'set.searchResultType\') == \'both\'\">\n				<li>{parse template=\"userHoverCard\" group=\"global\" params=\"$data\"}</li>\n				<li>\n					<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;view=getlastpost\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{$this->lang->words[\'n_posted\']} {parse date=\"$data[\'_post_date\']\" format=\"DATE\"}</a>\n				</li>\n			<else />\n				<li>{$data[\'last_poster\']}</li>\n				<li>\n					<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;view=getlastpost\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{parse date=\"$data[\'_last_post\']\" format=\"DATE\"}</a>\n				</li>\n			</if>								\n		</ul>\n	</td>\n	<if test=\"isFollowedStuff:|:count($data[\'_followData\'])\">\n		<td class=\'col_f_mod\'>\n			<input class=\'input_check checkall toggle_notify_on\' type=\"checkbox\" name=\"likes[]\" value=\"{$data[\'_followData\'][\'like_app\']}-{$data[\'_followData\'][\'like_area\']}-{$data[\'_followData\'][\'like_rel_id\']}\" />\n		</td>\n	<else />\n		<if test=\"isAdmin:|:$this->memberData[\'g_is_supmod\']\">\n			<td class=\'col_f_mod\'>\n				<input type=\'checkbox\' class=\'input_check topic_mod\' id=\'tmod_{$data[\'tid\']}\' />\n			</td>\n		</if>\n	</if>\n</tr>\n<if test=\"$data[\'pid\']\">\n<script type=\'text/javascript\'>\nipb.global.searchResults[ {$data[\'tid\']} ] = { pid: {parse expression=\"intval($data[\'pid\'])\"}, searchterm:\"{$data[\'cleanSearchTerm\']}\" };\n</script>\n</if>', 'asForumTopics', '$data', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('123', '0', 'skin_search', '<p class=\'notify_info toggle_notify_on\'>\n	<span>\n		<if test=\"$followData[\'like_notify_do\']\">\n			<img src=\'{$this->settings[\'img_url\']}/icon_follow_freq.png\' /> &nbsp;{$this->lang->words[\'notify_freq_\' . $followData[\'like_notify_freq\'] ]}\n		<else />\n		 	<img src=\'{$this->settings[\'img_url\']}/icon_follow_freq_none.png\' /> &nbsp;{$this->lang->words[\'notify_freq_none\']}\n		</if>\n	</span>\n	<if test=\"$followData[\'like_is_anon\']\">\n		<span>\n			<img src=\'{$this->settings[\'img_url\']}/icon_follow_anon.png\' /> &nbsp;{$this->lang->words[\'anonymous\']}\n		</span>\n	</if>\n</p>', 'followData', '$followData', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('124', '0', 'skin_search', '{parse js_module=\"forums\"}\n<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ips.forums.js\'></script>\n<table class=\'ipb_table topic_list\' id=\'forum_table\'>\n	<if test=\"count($results)\">\n		<foreach loop=\"NCresultsAsForum:$results as $result\">\n			{$result[\'html\']}\n		</foreach>\n	</if>\n</table>', 'followedContentForumsWrapper', '$results', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('125', '0', 'skin_search', '<script type=\'text/javascript\'>\n//<![CDATA[\n	var markerURL  = \"{parse url=\"app=forums&module=ajax&section=markasread&i=1\" base=\"public\"}\"; // Ajax URL so don\'t use &amp;\n	var unreadIcon = \"<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\";\n//]]>\n</script>\n<table class=\'ipb_table topic_list\' id=\'forum_table\'>\n	<if test=\"count($results)\">\n		<foreach loop=\"NCresultsAsForum:$results as $forum_data\">\n			<tr class=\'<if test=\"$forum_data[\'_has_unread\']\">unread</if>\'>\n				<td class=\'col_c_icon altrow\'>\n					<if test=\"$forum_data[\'_has_unread\']\">\n						<a id=\'forum_img_{$forum_data[\'id\']}\' href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$this->request[\'f\']}&amp;i=1\" base=\"public\"}\" data-tooltip=\"{$this->lang->words[\'bi_markread\']}\" class=\'forum_marker\'><img src=\'{$this->settings[\'img_url\']}/f_icon.png\' /></a>\n						<script type=\'text/javascript\'>\n							ipb.global.registerMarker( \"forum_img_{$forum_data[\'id\']}\", \"{$forum_data[\'img_new_post\']}\", markerURL + \"&forumid={$forum_data[\'id\']}\" );\n						</script>\n					<else />\n						<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\n					</if>\n				</td>\n				<td class=\'col_c_forum\'>\n					<h4><a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$forum_data[\'name\']}</a></h4>\n					\n					<if test=\"showSubForums:|:$forum_data[\'show_subforums\'] AND count( $forum_data[\'subforums\'] ) AND $forum_data[\'show_subforums\']\">\n						<br />\n						<ol class=\'ipsList_inline ipsType_small subforums toggle_notify_off\' id=\'subforums_{$forum_data[\'id\']}\'>\n							<foreach loop=\"subforums:$forum_data[\'subforums\'] as $__id => $__data\">\n								<if test=\"showSubForumsLit:|:$__data[3]\"><li class=\'unread\'><else /><li></if>\n									<a href=\"{parse url=\"showforum={$__data[0]}\" seotitle=\"{$__data[2]}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$__data[1]}</a>\n								</li>\n							</foreach>\n						</ol>\n					</if>\n					<if test=\"isFollowedStuff:|:count($forum_data[\'_followData\'])\">\n						{parse template=\"followData\" group=\"search\" params=\"$forum_data[\'_followData\']\"}\n					</if>\n				</td>\n				<td class=\'col_c_stats ipsType_small\'>\n					<strong>{$forum_data[\'topics\']}</strong> {$this->lang->words[\'topics\']}<br />\n					<strong>{$forum_data[\'posts\']}</strong> {$this->lang->words[\'replies\']}\n				</td>\n				<td class=\'col_c_post\'>\n					<if test=\"hideLastInfo:|:$forum_data[\'hide_last_info\']\">\n						<ul class=\'last_post\'>\n							<li class=\'desc\'>{$this->lang->words[\'f_protected\']}</li>\n						</ul>\n					<else />\n						<if test=\"hasphoto:|:$forum_data[\'pp_small_photo\'] AND !$forum_data[\'hide_last_info\']\">\n							<a href=\'{parse url=\"showuser={$forum_data[\'last_poster_id\']}\" template=\"showuser\" seotitle=\"{$forum_data[\'seo_last_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n								<img src=\'{$forum_data[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n							</a>\n						</if>\n						<ul class=\'last_post ipsType_small\'>\n							<if test=\"!$forum_data[\'last_id\']\">\n								<li class=\'desc lighter\'><em>{$this->lang->words[\'f_none\']}</em></li>\n							<else />\n								<li>\n									<a href=\'{parse url=\"showtopic={$forum_data[\'last_topic_id\']}&amp;view=getnewpost\" seotitle=\"{$forum_data[\'seo_last_title\']}\" template=\"showtopic\" base=\"public\"}\' title=\"{$this->lang->words[\'view_new_post\']}\">\n										{parse expression=\"IPSText::truncate( $forum_data[\'last_title\'], 28)\"}\n									</a>\n								</li>\n								<if test=\"lastPosterID:|:$forum_data[\'last_poster_id\']\">\n									<li>{$this->lang->words[\'by_ucfirst\']} {parse expression=\"IPSMember::makeProfileLink($forum_data[\'last_poster_name\'], $forum_data[\'last_poster_id\'], $forum_data[\'seo_last_name\'])\"}</li>\n								</if>\n								<if test=\"hideDateUrl:|:$forum_data[\'_hide_last_date\']\">\n									<li class=\'desc lighter\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</li>\n								<else />\n									<li class=\'desc lighter blend_links\'><a href=\'{parse url=\"showtopic={$forum_data[\'last_id\']}&amp;view=getlastpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$forum_data[\'seo_last_title\']}\"}\' title=\'{$this->lang->words[\'view_last_post\']}\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</a></li>\n								</if>\n							</if>\n						</ul>\n					</if>\n				</td>\n				<td class=\'col_f_mod\'>\n					<input class=\'input_check checkall toggle_notify_on\' type=\"checkbox\" name=\"likes[]\" value=\"{$forum_data[\'_followData\'][\'like_app\']}-{$forum_data[\'_followData\'][\'like_area\']}-{$forum_data[\'_followData\'][\'like_rel_id\']}\" />\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>', 'followedContentForumsWrapperForums', '$results', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('126', '0', 'skin_search', '<if test=\"haslikeserror:|:$error\">\n<p class=\'message error\'>\n	{$error}\n</p>\n<else />\n	<if test=\"hasconfirm:|:$this->request[\'confirm\']\">\n	<p class=\'message\'>\n		{$this->lang->words[\'likes_rem_suc\']}\n	</p>\n	</if>\n</if>\n<br />\n<input type=\'hidden\' name=\"usedInJsLater\" id=\"urlString\" value=\"{parse expression=\"base64_encode( $this->registry->output->buildUrl( \"app=core&amp;module=search&amp;do=followed&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}\", \"public\" ) )\"}\" />\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'followed_content\']}</h1>\n<div class=\'ipsType_pagedesc\'>\n	{$this->lang->words[\'followed_content_desc\']}\n</div>\n<br />\n<div class=\'ipsLayout ipsLayout_withleft clearfix\'>\n	<div class=\'ipsLayout_left\'>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container ipsSideMenu\'>\n				<h4>{$this->lang->words[\'filter_by_app\']}</h4>\n				<ul>\n					<if test=\"memberFollow:|:IPSLib::appSupportsExtension( \'forums\', array(\'like\') )\"><li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed&amp;search_app=forums&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li></if>\n					<if test=\"memberFollow:|:IPSLib::appSupportsExtension( \'members\', array(\'like\') )\"><li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed&amp;search_app=members&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li></if>\n					<foreach loop=\"apps:$this->registry->getApplications() as $app\">\n						<if test=\"supportsLikes:|:IPSLib::appSupportsExtension( $app[\'app_directory\'], array(\'like\') ) AND !in_array( $app[\'app_directory\'], array(\'core\',\'forums\',\'members\') )\">\n							<li <if test=\"appIsSearched:|:$this->request[\'search_app\'] == $app[\'app_directory\']\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed&amp;search_app={$app[\'app_directory\']}&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>\n									{IPSLib::getAppTitle( $app[\'app_directory\'] )}\n								</a>\n							</li>\n				 		</if>\n					</foreach>\n				</ul>\n				<if test=\"is_array($contentTypes) AND count( $contentTypes )\">\n					<h4>{$this->lang->words[\'filter_by_section\']}</h4>\n					<ul>\n						<foreach loop=\"$contentTypes as $type\">\n							<li <if test=\"$this->request[\'contentType\'] == $type\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=followed&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;contentType={$type}\" base=\"public\"}\'>{$this->lang->words[\'followed_type__\' . $type]}</a>\n							</li>\n						</foreach>\n					</ul>\n				</if>\n			</div>\n		</div>\n	</div>\n	<form action=\"{parse url=\"app=core&amp;module=search&amp;do=manageFollowed&amp;search_app={$this->request[\'search_app\']}&amp;contentType={$this->request[\'contentType\']}\" base=\"public\"}\" id=\"checkBoxForm\" method=\"post\">\n	<input type=\"hidden\" name=\"secure_key\" value=\"{$this->member->form_hash}\" />\n	\n	<div class=\'right clearfix\'>\n		<a href=\'#\' id=\'toggle_notification\' class=\'ipsButton_secondary\'>{$this->lang->words[\'display_edit_options\']}</a>\n	</div>\n	<br /><br />\n	\n	<div class=\'ipsLayout_content\'>\n		<h2 class=\'maintitle\'>\n			<span class=\'right\'>\n				<input type=\'checkbox\' id=\'checkAllLikes\' class=\'input_check toggle_notify_on\' title=\'{$this->lang->words[\'search_select_all\']}\' value=\'1\' />\n			</span>\n			<if test=\"searchedApp:|:$this->request[\'search_app\']\">{IPSLib::getAppTitle( $this->request[\'search_app\'] )}<else />All</if>\n		</h2>\n		<div>\n			<if test=\"NPTotal:|:$total\">\n				{$results}\n				\n				<if test=\"hasLikeForMod:|:count($results)\">\n					\n					<div class=\'moderation_bar rounded with_action toggle_notify_on\'>\n						<select name=\'modaction\' class=\'input_select\'>\n							<option value=\'\'>{$this->lang->words[\'like_mod__chose\']}</option>\n							<option value=\'delete\'>{$this->lang->words[\'like_mod__delete\']}</option>\n							<option value=\'change-donotify\'>{$this->lang->words[\'like_mod__change_donotify\']}</option>\n							<option value=\'change-donotnotify\'>{$this->lang->words[\'like_mod__change_nonotify\']}</option>\n							<option value=\'change-immediate\'>{$this->lang->words[\'like_mod__change_immediate\']}</option>\n							<option value=\'change-offline\'>{$this->lang->words[\'like_mod__change_offline\']}</option>\n							<if test=\"forumsDigests:|:$this->request[\'search_app\'] == \'forums\'\">\n								<option value=\'change-daily\'>{$this->lang->words[\'like_mod__change_daily\']}</option>\n								<option value=\'change-weekly\'>{$this->lang->words[\'like_mod__change_weekly\']}</option>\n							</if>\n							<option value=\'change-anon\'>{$this->lang->words[\'like_mod__change_anon\']}</option>\n							<option value=\'change-noanon\'>{$this->lang->words[\'like_mod__change_noanon\']}</option>\n						</select>\n							\n						<input type=\"submit\" class=\"input_submit alt\" value=\"{$this->lang->words[\'update_selected\']}\" />\n					</div>\n				</if>\n				<br />\n				{$pagination}\n			<else />\n				<p class=\'no_messages\'>{$this->lang->words[\'followed_content_none\']}</p>\n			</if>\n		</div>\n	</div>\n	\n	</form>\n</div>\n<br class=\'clear\' />\n<script type=\'text/javascript\'>\n	ipb.global.registerCheckAll(\'checkAllLikes\', \'checkall\');\n	\n	if( $(\'toggle_notification\') ){\n		$(\'toggle_notification\').observe( \'click\', function(e){\n			Event.stop(e);\n			$(\'checkBoxForm\').toggleClassName(\'show_notify\');\n		});\n	}\n</script>', 'followedContentView', '$results, $pagination, $total, $error, $contentTypes', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('127', '0', 'skin_search', '<fieldset class=\'{parse striping=\"search\"}\'>\n	<span class=\'search_msg\'>\n		{$this->lang->words[\'s_forum_desc\']}\n	</span>\n	<ul class=\'ipsForm_horizontal\'>\n		<li class=\'ipsField ipsField_select clear\'>\n			<label class=\'ipsField_title\' for=\'forums_filter\'>{$this->lang->words[\'find_forum\']}</label>\n			<p class=\'ipsField_content\'>\n				<select name=\'search_app_filters[forums][forums][]\' class=\'input input_select\' size=\'6\' multiple=\'multiple\'>\n					{$forums}\n				</select>\n			</p>\n		</li>\n		<li class=\'ipsField clear\'>\n			<label class=\'ipsField_title\' for=\'forums_display\'>{$this->lang->words[\'s_forum_display\']}</label>\n			<p class=\'ipsField_content\'>\n				<input type=\'radio\' name=\'search_app_filters[forums][noPreview]\' value=\'0\' /> {$this->lang->words[\'s_forum_asposts\']}&nbsp;&nbsp;&nbsp;\n				<input type=\'radio\' name=\'search_app_filters[forums][noPreview]\' value=\'1\' checked=\"checked\" /> {$this->lang->words[\'s_forum_astopics\']}\n			</p>\n		</li>\n		<li class=\'ipsField clear\'>\n			<label class=\'ipsField_title\' for=\'f_p_data\'>{$this->lang->words[\'s_forum_stuff\']}</label>\n			<p class=\'ipsField_content\'>\n				{parse expression=\"sprintf( $this->lang->words[\'s_forum_stuff_2\'], \"<input id=\'f_p_count\' type=\'text\' name=\'search_app_filters[forums][pCount]\' class=\'input_text\' style=\'vertical-align: middle; width:40px\' size=\'5\' value=\'\' />\", \"<input id=\'f_p_views\' type=\'text\' name=\'search_app_filters[forums][pViews]\' class=\'input_text\' style=\'vertical-align: middle; width:40px\' size=\'5\' value=\'\' />\")\"}\n			</p>\n		</li>\n	</ul>\n</fieldset>', 'forumAdvancedSearchFilters', '$forums', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('128', '0', 'skin_search', '<h3>\n	{$this->lang->words[\'vnc_filters_header\']}\n</h3>\n<div class=\'fixed_inner ipsBox ipsLayout clearfix\'>\n	<div class=\'ipsLayout_content ipsBox_container search_filter_container\'>\n		<div id=\"vnc_filter_popup_close\"><a class=\'input_submit\' id=\'save_vnc_filters\' href=\'#\'>{$this->lang->words[\'save_vnc_filters\']}</a> &nbsp;&nbsp;{$this->lang->words[\'or\']}&nbsp;&nbsp;<a href=\'#\' id=\'cancel_vnc_filters\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a></div>\n		<ul class=\'block_list\'>\n			<li class=\'clickable<if test=\"noFiltersSet:|:$currentPrefs == null OR !count($currentPrefs)\"> active</if>\' id=\'forum_all\'><span><strong>{$this->lang->words[\'vnc_filter_showall_forums\']}</strong></span><input type=\'hidden\' name=\'forum_all\' id=\'hf_all\' value=\'<if test=\"noFiltersSet:|:$currentPrefs == null OR !count($currentPrefs)\">1</if>\' /></li>\n			<foreach loop=\"forumlist:$data as $_data\">\n				<if test=\"hasTitle:|: ! empty( $_data[\'important\'] )\">\n					<li><span class=\'heading\'>{$_data[\'title\']}</span></li>\n				<else />\n					<li class=\'clickable<if test=\"hasFiltersSet:|:count($currentPrefs) AND in_array($_data[\'id\'], $currentPrefs)\"> active</if>\' id=\'forum_{$_data[\'id\']}\'><if test=\"depth:|:!empty($_data[\'depth\'])\"></if><span>{parse expression=\"str_repeat( \'&nbsp;&nbsp;&nbsp;&nbsp;\', $_data[\'depth\'])\"}{$_data[\'title\']}</span><input type=\'hidden\' name=\'forum_{$_data[\'id\']}\' id=\'hf_{$_data[\'id\']}\' value=\'<if test=\"hasFiltersSet:|:count($currentPrefs) AND in_array($_data[\'id\'], $currentPrefs)\">1<else />0</if>\' /></li>\n				</if>\n			</foreach>\n		</ul>\n	</div>\n</div>', 'forumsVncFilters', '$data, $currentPrefs', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('129', '0', 'skin_search', '<php>\n$st = IPSSearchRegistry::get(\'in.search_higlight\');\n</php>\n<div class=\'result_info\'>\n	<h3><a href=\'{parse url=\"app=core&amp;module=help&amp;do=01&amp;HID={$r[\'type_id_2\']}&amp;hl={$st}\" base=\"public\"}\'>{$r[\'content_title\']}</a></h3>\n	<if test=\"showHelpContent:|:!$resultAsTitle\">\n	<p>\n		{$r[\'content\']}\n	</p>\n	</if>\n</div>', 'helpSearchResult', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('130', '0', 'skin_search', '<if test=\"isReply:|: ! empty( $r[\'reply_id\'] )\">\n	<span class=\'icon\'>\n		{parse expression=\"IPSMember::buildPhotoTag( $r[\'reply_author\'], \'small\' )\"}<if test=\"forSomeoneElseImg:|:$r[\'reply_author\'][\'member_id\'] != $r[\'status_member_id\']\">{parse expression=\"IPSMember::buildPhotoTag( $r[\'status_member\'], \'inset\' )\"}</if>\n	</span>\n	<div class=\'result_info\'>\n		<h3>\n			{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'reply_author\']\"}\n			<if test=\"forSomeoneElse:|:$r[\'reply_author\'][\'member_id\'] != $r[\'status_member_id\']\">\n				&rarr;\n				{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'status_member\']\"}\n			</if>\n		</h3>\n		<span class=\'desc breadcrumb\'>\n			<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$r[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{$this->lang->words[\'results_pf_reply\']}</a>,\n		   {parse date=\"$r[\'reply_date\']\" format=\"short\"}\n		</span>\n		<p>\n			{$r[\'reply_content\']}\n		</p>\n	</div>\n<else />\n	<if test=\"isUpdate:|: $r[\'status_member_id\'] == $r[\'status_author_id\']\">\n		<span class=\'icon\'>\n			{parse expression=\"IPSMember::buildPhotoTag( $r[\'status_author\'], \'small\' )\"}\n		</span>\n		<div class=\'result_info\'>\n			<h3>{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'status_author\']\"}</h3>\n			<span class=\'desc breadcrumb\'>\n				<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$r[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{$this->lang->words[\'results_pf_status\']}</a>, {parse date=\"$r[\'status_date\']\" format=\"short\"}\n			</span>\n			<p>\n				{$r[\'status_content\']}\n			</p>\n		</div>\n	<else />\n		<span class=\'icon\'>\n			{parse expression=\"IPSMember::buildPhotoTag( $r[\'status_author\'], \'small\' )\"}\n			{parse expression=\"IPSMember::buildPhotoTag( $r[\'status_member\'], \'inset\' )\"}\n		</span>\n		<div class=\'result_info\'>\n			<h3>\n				{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'status_author\']\"}\n				&rarr;\n				{parse template=\"userHoverCard\" group=\"global\" params=\"$r[\'status_member\']\"}\n			</h3>\n			<span class=\'desc breadcrumb\'>\n				<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$r[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{$this->lang->words[\'results_pf_comment\']}</a>, {parse date=\"$r[\'status_date\']\" format=\"short\"}\n			</span>\n			<p>\n				{$r[\'status_content\']}\n			</p>\n		</div>\n	</if>\n</if>', 'memberCommentsSearchResult', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('131', '0', 'skin_search', '<if test=\"showMemberData:|:!$resultAsTitle\">\n	<span class=\'icon\'>\n		<a href=\'{parse url=\"showuser={$r[\'type_id_2\']}\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink\'>\n			{IPSMember::buildPhotoTag( $r, \'small\' )}\n		</a>\n	</span>\n</if>\n<div class=\'result_info\'>\n	<h3><a href=\'{parse url=\"showuser={$r[\'type_id_2\']}\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\'>{$r[\'content_title\']}</a></h3>\n	<span class=\'desc lighter breadcrumb\'>\n		{$this->lang->words[\'member_joined\']} {parse date=\"$r[\'joined\']\" format=\"short\"}<br />\n		{IPSMember::makeNameFormatted( $r[\'group\'], $r[\'member_group_id\'] )} &middot; {parse format_number=\"$r[\'posts\']\"} {$this->lang->words[\'member_posts\']}\n	</span>\n</div>', 'memberSearchResult', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('132', '0', 'skin_search', '{parse js_module=\"search\"}\n<input type=\'hidden\' name=\"usedInJsLater\" id=\"urlString\" value=\"{parse expression=\"base64_encode( $this->registry->output->buildUrl( \"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}\", \"public\" ) )\"}\" />\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'new_content\']}</h1>\n<div class=\'ipsType_pagedesc\'>\n	{$this->lang->words[\'new_content_desc\']}\n</div>\n<br />\n<div class=\'ipsLayout ipsLayout_withleft clearfix\'>\n	<div class=\'ipsLayout_left\'>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container ipsSideMenu\'>\n				<h4>{$this->lang->words[\'filter_by_app\']}</h4>\n				<ul>\n					<if test=\"IPSLib::appIsSearchable( \'forums\', \'vnc\' ) || IPSLib::appIsSearchable( \'forums\', \'active\' )\">\n						<li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=forums&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'members\', \'vnc\' ) || IPSLib::appIsSearchable( \'members\', \'active\' )\">\n						<li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=members&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'core\', \'vnc\' ) || IPSLib::appIsSearchable( \'core\', \'active\' )\">\n						<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'core\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=core&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'core\' )}</a></li>\n					</if>\n					<foreach loop=\"apps:$this->registry->getApplications() as $app\">\n						<if test=\"appIsSearchable:|:(IPSLib::appIsSearchable( $app[\'app_directory\'], \'vnc\' ) || IPSLib::appIsSearchable( $app[\'app_directory\'], \'active\' ) ) AND !in_array( $app[\'app_directory\'], array(\'core\',\'forums\',\'members\') )\">\n							<li <if test=\"appIsSearched:|:$this->request[\'search_app\'] == $app[\'app_directory\']\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$app[\'app_directory\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>\n									{IPSLib::getAppTitle( $app[\'app_directory\'] )}\n								</a>\n							</li>\n				 		</if>\n					</foreach>\n				</ul>\n			\n				<if test=\"is_array($sortIn) AND count( $sortIn )\">\n					<h4>{$this->lang->words[\'filter_by_section\']}</h4>\n					<ul>\n						<foreach loop=\"$sortIn as $id => $_data\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] == $_data[0]\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$_data[\'0\']}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$_data[1]}</a>\n							</li>\n						</foreach>\n					</ul>\n				</if>\n			\n				<h4>{$this->lang->words[\'filter_by_time\']}</h4>\n				<ul>\n					<if test=\"hazVNC:|:IPSLib::appIsSearchable( IPSSearchRegistry::get(\'in.search_app\'), \'vncWithUnreadContent\' ) AND $this->memberData[\'member_id\']\">\n						<li <if test=\"$this->request[\'period\']==\'unread\'\">class=\'active\'</if>>\n							<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=unread&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'filter_not_read\']}</a>\n						</li>\n					</if>\n					<if test=\"hazMember:|:$this->memberData[\'member_id\']\">\n						<li <if test=\"$this->request[\'period\']==\'lastvisit\'\">class=\'active\'</if>>\n							<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=lastvisit&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'filter_new_visit\']}</a>\n						</li>\n					</if>\n					<li <if test=\"$this->request[\'period\']==\'today\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=today&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_today\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'period\']==\'week\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=week&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_week\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'period\']==\'weeks\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=weeks&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_weeks\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'period\']==\'month\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=month&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_month\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'period\']==\'months\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=months&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_months\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'period\']==\'year\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=year&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_year\']}</a>\n					</li>\n				</ul>\n				\n				<if test=\"canFollowFilter:|:IPSLib::appIsSearchable( $this->request[\'search_app\'], \'vncWithFollowFilter\' ) AND $this->memberData[\'member_id\']\">\n					<h4>{$this->lang->words[\'filter_by_other\']}</h4>\n					<ul>\n						<if test=\"checked:|:$this->request[\'followedItemsOnly\']\">\n							<li class=\"active\">\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly=0\" base=\"public\"}\'>{$this->lang->words[\'filter_i_follow\']}</a>\n							</li>\n						<else />\n							<li>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly=1\" base=\"public\"}\'>{$this->lang->words[\'filter_i_follow\']}</a>\n							</li>\n						</if>\n						<li <if test=\"$this->request[\'userMode\'] == \'all\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period={$this->request[\'period\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}&amp;userMode=<if test=\"$this->request[\'userMode\'] != \'all\'\">all</if>\" base=\"public\"}\'>{$this->lang->words[\'vnc_topics_and_posts\']}</a></li>\n						<li <if test=\"$this->request[\'userMode\'] == \'title\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period={$this->request[\'period\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}&amp;userMode=<if test=\"$this->request[\'userMode\'] != \'title\'\">title</if>\" base=\"public\"}\'>{$this->lang->words[\'vnc_topics_only\']}</a></li>\n						<if test=\"vncFilterForumsOnly:|:$this->request[\'search_app\'] == \'forums\'\"><li <if test=\"hasFilters:|:IPSSearchRegistry::get(\'forums.vncForumFilters\') != null\">class=\'active\'</if>><a href=\'\' id=\'vncForumFilter\'>{$this->lang->words[\'vnc_filter_by_forum\']}</a></li></if>\n					</ul>\n				</if>\n			</div>\n		</div>\n	</div>\n	<div class=\'ipsLayout_content\'>\n		<div class=\'clearfix\'>\n			{$pagination}\n		</div>\n		<h2 class=\'maintitle\'>\n			<if test=\"searchismod:|:$this->memberData[\'g_is_supmod\'] == 1\">\n				<span class=\'right\'>\n					<input type=\'checkbox\' id=\'tmod_all\' class=\'input_check\' title=\'{$this->lang->words[\'search_select_all\']}\' value=\'1\' />\n				</span>\n			</if>\n			{IPSLib::getAppTitle( $this->request[\'search_app\'] )}\n		</h2>\n		<div>\n			<if test=\"NPTotal:|:$total\">\n				{$results}\n				<br />\n				{$pagination}\n			<else />\n				<p class=\'no_messages\'>{$this->lang->words[\'new_content_none\']}</p>\n			</if>\n		</div>\n	</div>\n</div>\n<br class=\'clear\' />', 'newContentView', '$results, $pagination, $total, $sortDropDown, $sortIn, $dateCutSet=0', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('133', '0', 'skin_search', '<style type=\'text/css\'>\n 	@import url(\'{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/calendar_select.css\');\n</style>\n<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/calendar_date_select/calendar_date_select.js\'></script>\n{parse js_module=\"search\"}\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'search\']}</h1>\n<if test=\"searchTermsRemoved:|:is_array( $removed_search_terms ) && count( $removed_search_terms )\">\n<br />\n<p class=\'message error\'>{$this->lang->words[\'removed_search_terms\']} <strong>{parse expression=\"implode( \',\', $removed_search_terms )\"}</strong></p>\n</if>\n<if test=\"searchError:|:$msg\">\n<br />\n<p class=\'message error\'>{$msg}</p>\n</if>\n<br />\n<div class=\'ipsBox\' id=\'main_search_form\'>\n	<form action=\"{parse url=\"app=core&amp;module=search&amp;section=search&amp;do=search\" base=\"public\"}&amp;fromsearch=1\" method=\"post\" id=\'search-box\' >\n		<input type=\'hidden\' name=\'search_app\' id=\'search_app\' value=\'{$this->request[\'search_app\']}\' />\n		<fieldset id=\'\' class=\'ipsBox_container ipsPad\'>\n			<ul class=\'ipsForm_horizontal\'>\n				<li class=\'ipsField\'>\n					<label for=\'query\' class=\'ipsField_title\'>{$this->lang->words[\'find_words\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\'text\' class=\'input_text\' name=\'search_term\' id=\'query\' value=\'{$this->request[\'search_term\']}\' size=\'50\' /><br />\n						<span class=\'desc lighter\'>{$this->lang->words[\'s_andor_quotes\']}</span>\n					</p>\n				</li>\n			</ul>\n		</fieldset>\n		\n		<fieldset id=\'other_filters\' class=\'ipsBox_container ipsPad\'>\n			<ul class=\'ipsForm_horizontal\'>\n				<li class=\'ipsField ipsField_select clear\'>\n					<label for=\'andor_type\' class=\'ipsField_title\'><strong>{$this->lang->words[\'matchlabel\']}</strong></label>\n					<p class=\'ipsField_content\'>\n						<if test=\"isFullText:|:$this->settings[\'use_fulltext\'] AND $this->DB->checkBooleanFulltextSupport()\">\n							<select name=\"andor_type\" id=\"andor_type\">\n								<option value=\"and\" <if test=\"$this->settings[\'s_andor_type\'] == \'and\'\">selected=\'selected\'</if>>{$this->lang->words[\'s_andor_and\']}</option>\n								<option value=\"or\" <if test=\"$this->settings[\'s_andor_type\'] == \'or\'\">selected=\'selected\'</if>>{$this->lang->words[\'s_andor_or\']}</option>\n							</select>\n							&nbsp;&nbsp;\n						</if>\n						\n						<select name=\"search_content\" id=\"search_content\">\n							<option value=\"both\">{$this->lang->words[\'search_both_types\']}</option>\n							<option value=\"titles\">{$this->lang->words[\'search_titles_types\']}</option>\n							<option value=\"content\">{$this->lang->words[\'search_content_types\']}</option>\n						</select>\n					</p>\n				</li>\n				<if test=\"tagyouareit:|:$canTag\">\n					<li class=\'ipsField clear\'>\n						<label for=\'tags\' class=\'ipsField_title\'>{$this->lang->words[\'find_by_tags\']}</label>\n						<p class=\'ipsField_content\'>\n							<input type=\'text\' class=\'input_text input\' name=\'search_tags\' id=\'tags\' value=\'{$this->request[\'find_by_tags\']}\' size=\'50\' />\n							<br />\n							<span class=\'desc lighter\'>{$this->lang->words[\'find_by_tags_desc\']}</span>\n						</p>\n					</li>\n				</if>\n				<li class=\'ipsField clear\'>\n					<label for=\'author\' class=\'ipsField_title\'>{$this->lang->words[\'find_author\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\'text\' class=\'input_text input\' name=\'search_author\' id=\'author\' value=\'{$this->request[\'search_author\']}\' size=\'50\' />\n					</p>\n				</li>\n				<li class=\'ipsField clear\'>\n					<label for=\'date_start\' class=\'ipsField_title\'>{$this->lang->words[\'find_date\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\'text\' class=\'input_text\' name=\'search_date_start\' id=\'date_start\' value=\'{$this->request[\'_search_date_start\']}\' /><img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'\' id=\'date_start_icon\' style=\'cursor: pointer\' /> &nbsp;\n						<strong>{$this->lang->words[\'to\']}</strong> &nbsp;<input type=\'text\' class=\'input_text\' name=\'search_date_end\' id=\'date_end\' value=\'{$this->request[\'_search_date_end\']}\' /><img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'\' id=\'date_end_icon\' style=\'cursor: pointer\' />\n					</p>\n				</li>\n				<if test=\"count($filters)\">\n					<li class=\'ipsField app_chooser\'>\n						<label class=\'ipsField_title\' for=\'\'>{$this->lang->words[\'search_section\']}</label>\n						<div class=\'ipsField_content\'>\n							<ul id=\'sapps\'>\n								<if test=\"IPSLib::appIsSearchable( \'forums\', \'search\' )\">\n									<li style=\'display: inline-block;\' class=\'search_app\' id=\'sapp_forums\'>\n										<input type=\'radio\' name=\'search_app\' value=\'forums\' id=\'radio_forums\' <if test=\"$this->request[\'search_app\'] == \'forums\'\">checked=\"checked\"</if> /> <label for=\'radio_forums\'>{IPSLib::getAppTitle( \'forums\' )}</label>\n									</li>\n								</if>\n								<if test=\"IPSLib::appIsSearchable( \'members\', \'search\' )\">\n									<li style=\'display: inline-block;\' class=\'search_app\' id=\'sapp_members\'>\n										<input type=\'radio\' name=\'search_app\' value=\'members\' id=\'radio_members\' <if test=\"$this->request[\'search_app\'] == \'members\'\">checked=\"checked\"</if> /> <label for=\'radio_members\'>{IPSLib::getAppTitle( \'members\' )}</label>\n									</li>\n								</if>\n								<if test=\"IPSLib::appIsSearchable( \'core\', \'search\' )\">\n									<li style=\'display: inline-block;\' class=\'search_app\' id=\'sapp_core\'>\n										<input type=\'radio\' name=\'search_app\' value=\'core\' id=\'radio_core\' <if test=\"$this->request[\'search_app\'] == \'core\'\">checked=\"checked\"</if> /> <label for=\'radio_core\'>{IPSLib::getAppTitle( \'core\' )}</label>\n									</li>\n								</if>\n			\n								<foreach loop=\"appLoop:$this->registry->getApplications() as $app => $data\">\n									<if test=\"IPSLib::appIsSearchable( $app, \'search\' ) AND !in_array( $app, array( \'forums\', \'members\', \'core\' ) )\">\n										<li style=\'display: inline-block;\' class=\'search_app\' id=\'sapp_{$app}\'>\n											<input type=\'radio\' name=\'search_app\' value=\'{$app}\' id=\'radio_{$app}\' <if test=\"$app == $this->request[\'search_app\']\">checked=\"checked\"</if> /> <label for=\'radio_{$app}\'>{IPSLib::getAppTitle( $app )}</label>\n										</li>\n									</if>\n								</foreach>\n							</ul>\n						</div>\n					</li>\n				</if>\n			</ul>\n		</fieldset>\n		<if test=\"count($filters)\">\n			<foreach loop=\"$filters as $app => $data\">\n				<div id=\'app_filter_{$app}\' class=\'ipsBox_container ipsPad\' style=\'display: none\'>\n					<if test=\"!empty($data[\'html\'])\">\n						{$data[\'html\']}\n					</if>\n					<if test=\"count($data[\'sortDropDown\'])\">\n						<fieldset class=\'{parse striping=\"search\"}\'>\n							<if test=\"is_array($data[\'sortDropIn\']) AND count( $data[\'sortDropIn\'] )\">\n								<foreach loop=\"$data[\'sortDropIn\'] as $id => $_data\">\n									<ul class=\'ipsForm_horizontal\'>\n										<li class=\'ipsField ipsField_select\'>\n											<label class=\'ipsField_title\' for=\'search_by_{$_data[0]}\'><if test=\"! $id\">{$this->lang->words[\'s_member_sin\']}<else />&nbsp;</if></label>\n											<p class=\'ipsField_content\'>\n												<input type=\'radio\' name=\'search_app_filters[$app][searchInKey]\' value=\'{$_data[0]}\' <if test=\"$this->request[\'search_app_filters\'][$app][\'searchInKey\'] == $_data[0] || ( ! $this->request[\'search_app_filters\'][$app][\'searchInKey\'] AND ! $id )\">checked=\"checked\"</if> /> $_data[1]\n												<select name=\'search_app_filters[$app][{$_data[0]}][sortKey]\' class=\'input_select\' style=\'width:auto\'>\n												<foreach loop=\"$data[\'sortDropDown\'][$_data[0]] as $k => $l\">\n													<option value=\'$k\' <if test=\"$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortKey\'.$_data[0]] == $k\">selected=\'selected\'</if>>{$l}</option>\n												</foreach>\n												</select>\n												<select name=\'search_app_filters[$app][{$_data[0]}][sortDir]\' class=\'input_select\' style=\'width:auto\'>\n													<option value=\'0\' <if test=\"!$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_0\']}</option>\n													<option value=\'1\' <if test=\"$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_1\']}</option>\n												</select>\n											</p>\n										</li>\n									</ul>\n								</foreach>\n							<else />\n								<ul class=\'ipsForm_horizontal\'>\n									<li class=\'ipsField ipsField_select\'>\n										<label class=\'ipsField_title\' for=\'search_by\'>{$this->lang->words[\'s_search_type\']}</label>\n										<p class=\'ipsField_content\'>\n											<select name=\'search_app_filters[$app][sortKey]\' id=\'search_sort_by_{$app}\' class=\'input_select\' style=\'width:auto\'>\n											<foreach loop=\"$data[\'sortDropDown\'] as $k => $l\">\n												<option value=\'$k\' <if test=\"$this->request[\'search_app_filters\'][$app][\'sortKey\'] == $k\">selected=\'selected\'</if>>{$l}</option>\n											</foreach>\n											</select>\n											<select name=\'search_app_filters[$app][sortDir]\' id=\'search_sort_order_{$app}\' class=\'input_select\' style=\'width:auto\'>\n												<option value=\'0\' <if test=\"!$this->request[\'search_app_filters\'][$app][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_0\']}</option>\n												<option value=\'1\' <if test=\"$this->request[\'search_app_filters\'][$app][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_1\']}</option>\n											</select>\n										</p>\n									</li>\n								</ul>\n							</if>\n						</fieldset>\n					</if>\n				</div>\n			</foreach>\n		</if>\n		<fieldset class=\'submit\'>\n			<input type=\'submit\' name=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'do_search\']}\'> {$this->lang->words[\'or\']} <a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</form>\n</div>', 'searchAdvancedForm', '$filters=\'\', $msg=\'\', $current_app, $removed_search_terms=array(), $isFT=false, $canTag=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('134', '0', 'skin_search', '{parse striping=\"searchStripe\" classes=\"row1,row2\"}\n<div id=\'search_results\'>\n	<ol>\n		<if test=\"hasResults:|:is_array($results) && count($results)\">\n			<foreach loop=\"results:$results as $result\">\n				<if test=\"subResult:|:$result[\'sub\']\">\n					<li class=\'{parse striping=\"searchStripe\"} sub clearfix clear\'>\n						{$result[\'html\']}\n					</li>\n				<else />\n					<li class=\'{parse striping=\"searchStripe\"} clearfix clear\'>\n						{$result[\'html\']}\n					</li>\n				</if>\n			</foreach>\n		</if>\n	</ol>\n</div>', 'searchResults', '$results, $titlesOnly', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('135', '0', 'skin_search', '{parse js_module=\"forums\"}\n<if test=\"asTawpiks:|:$titlesOnly\">\n<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ips.forums.js\'></script>\n<table class=\'ipb_table topic_list\' id=\'forum_table\'>\n</if>\n	<if test=\"count($results)\">\n		<if test=\"asPostsStart:|:!$titlesOnly\"><div class=\'ipsBox\'></if>\n		<foreach loop=\"NCresultsAsForum:$results as $result\">\n			{$result[\'html\']}\n		</foreach>\n		<if test=\"asPostsEnd:|:!$titlesOnly\"></div></if>\n	</if>\n<if test=\"asTawpiks2:|:$titlesOnly\">\n	</table>\n	<if test=\"isAdminBottom:|:$this->memberData[\'g_is_supmod\']\">\n		<div id=\'topic_mod\' class=\'moderation_bar rounded with_action clear\'>\n			<form id=\'modform\' method=\"post\" action=\"{parse url=\"\" base=\"public\"}\">\n				<fieldset>\n					<input type=\"hidden\" name=\"app\" value=\"forums\" />\n					<input type=\"hidden\" name=\"module\" value=\"moderate\" />\n					<input type=\"hidden\" name=\"section\" value=\"moderate\" />\n					<input type=\"hidden\" name=\"do\" value=\"topicchoice\" />\n					<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n					<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n					<input type=\'hidden\' name=\'fromSearch\' value=\'1\' />\n					<input type=\'hidden\' name=\'returnUrl\' id=\'returnUrl\' value=\'{$this->request[\'returnUrl\']}\' />\n					<input type=\"hidden\" name=\"modfilter\" value=\"{$this->request[\'modfilter\']}\" />\n					<input type=\"hidden\" value=\"{$this->request[\'selectedtids\']}\" id=\'selectedtids\' name=\"selectedtids\" />\n				\n					<select name=\"tact\" id=\'mod_tact\'>\n						<option value=\"close\">{$this->lang->words[\'cpt_close_f\']}</option>\n						<option value=\"open\">{$this->lang->words[\'cpt_open_f\']}</option>\n						<option value=\"pin\">{$this->lang->words[\'cpt_pin_f\']}</option>\n						<option value=\"unpin\">{$this->lang->words[\'cpt_unpin_f\']}</option>\n						<option value=\"move\">{$this->lang->words[\'cpt_move_f\']}</option>\n						<option value=\"merge\">{$this->lang->words[\'cpt_merge_f\']}</option>\n						<option value=\"delete\">{$this->lang->words[\'search_cpt_delete\']}</option>\n						<if test=\"$this->registry->class_forums->can_Un_SoftDeleteTopics( 0, array() )\"><option value=\"sundelete\">{$this->lang->words[\'search_cpt_undelete\']}</option></if>\n						<option value=\"approve\">{$this->lang->words[\'search_cpt_approve\']}</option>\n						<option value=\"unapprove\">{$this->lang->words[\'search_cpt_unapprove\']}</option>\n					</select>&nbsp;\n					<input type=\"submit\" name=\"gobutton\" value=\"{$this->lang->words[\'f_go\']}\" class=\"input_submit alt\" id=\'mod_submit\' />\n				</fieldset>\n			</form>\n			<script type=\'text/javascript\'>\n				/* Set return string */\n				$(\'returnUrl\').value = $(\'urlString\').value;\n				$(\'modform\').observe(\'submit\', ipb.forums.submitModForm);\n				$(\'mod_tact\').observe(\'change\', ipb.forums.updateTopicModButton);\n			</script>\n		</div>\n	</if>\n<else />\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ips.topic.js\'></script>\n	<script type=\"text/javascript\">\n		ipb.topic.inSection = \'searchview\';\n	</script>\n	<if test=\"isAdmin:|:$this->memberData[\'g_is_supmod\']\">\n	<div id=\'topic_mod_2\' class=\'moderation_bar rounded\'>\n		<form method=\"post\" id=\"modform\" name=\"modform\" action=\"{parse url=\"\" base=\"public\"}\">\n			<fieldset>\n				<input type=\"hidden\" name=\"app\" value=\"forums\" />\n	 			<input type=\"hidden\" name=\"module\" value=\"moderate\" />\n	 			<input type=\"hidden\" name=\"section\" value=\"moderate\" />\n	 			<input type=\"hidden\" name=\"do\" value=\"postchoice\" />\n	 			<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n	 			<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n	 			<input type=\"hidden\" value=\"{$this->request[\'selectedpids\']}\" name=\"selectedpidsJS\" id=\'selectedpidsJS\' />\n				<input type=\'hidden\' name=\'fromSearch\' value=\'1\' />\n				<input type=\'hidden\' name=\'returnUrl\' id=\'returnUrl\' value=\'{$this->request[\'returnUrl\']}\' />\n				<select name=\"tact\" class=\"input_select\" id=\'topic_moderation\'>\n	 				<option value=\"delete\">{$this->lang->words[\'s_p_delete\']}</option>\n	 				<option value=\"sundelete\">{$this->lang->words[\'s_p_undelete\']}</option>\n	 				<option value=\"approve\">{$this->lang->words[\'s_p_approve\']}</option>\n	 				<option value=\"unapprove\">{$this->lang->words[\'s_p_unapprove\']}</option>\n				</select>&nbsp;\n				<input type=\"submit\" value=\"{$this->lang->words[\'jmp_go\']}\" class=\"input_submit alt\" />\n			</fieldset>\n		</form>\n		\n		<script type=\'text/javascript\'>\n			/* Set return string */\n			$(\'returnUrl\').value = $(\'urlString\').value;\n			$(\'modform\').observe(\'submit\', ipb.topic.submitPostModeration );\n		</script>\n	</div>\n	</if>\n	<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n		{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n	</if>\n</if>', 'searchResultsAsForum', '$results, $titlesOnly', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('136', '0', 'skin_search', '<input type=\'hidden\' name=\"usedInJsLater\" id=\"urlString\" value=\"{parse expression=\"base64_encode( $this->registry->output->buildUrl( \"{$url_string}&amp;search_app={$current_key}\", \"public\" ) )\"}\" />\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'search_results\']}</h1>\n<div class=\'ipsType_pagedesc\'>\n	<if test=\"hasSearchResults:|:$total > 0 AND $search_term != \'\'\">\n		<if test=\"hasSearchResultsCut:|:$limited AND $wasLimited\">\n			{parse expression=\"sprintf( $this->lang->words[\'your_search_limited\'], $search_term, $limited )\"}\n		<else />\n			{$this->lang->words[\'your_search\']} <em><strong>{$search_term}</strong></em> {$this->lang->words[\'your_search_returned\']} <strong>{$total}</strong> {$this->lang->words[\'your_search_results\']}\n		</if>\n	<else />\n		<if test=\"hasSearchResults:|:$total > 0 AND $search_tags != \'\'\">\n			{parse expression=\"sprintf( $this->lang->words[\'tag_search_results\'], $total, $search_tags )\"}\n		</if>\n	</if>\n</div>\n<br />\n<div class=\'ipsLayout ipsLayout_withleft clearfix\'>\n	<div class=\'ipsLayout_left\'>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container ipsSideMenu\'>\n				<h4>{$this->lang->words[\'filter_by_app\']}</h4>\n				<ul>\n					<if test=\"IPSLib::appIsSearchable( \'forums\', \'search\' )\">\n						<li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'active\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=forums\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'members\', \'search\' )\">\n						<li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'active\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=members\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'core\', \'search\' )\">\n						<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'core\'\">class=\'active\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=core\" base=\"public\"}\'>{IPSLib::getAppTitle( \'core\' )}</a></li>\n					</if>\n					<foreach loop=\"apps:$this->registry->getApplications() as $app\">\n						<if test=\"appIsSearchable:|:IPSLib::appIsSearchable( $app[\'app_directory\'], \'search\' ) AND !in_array( $app[\'app_directory\'], array(\'core\',\'forums\',\'members\') )\">\n							<li <if test=\"appIsSearched:|:$this->request[\'search_app\'] == $app[\'app_directory\']\">class=\'active\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app={$app[\'app_directory\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( $app[\'app_directory\'] )}</a></li>\n				 		</if>\n					</foreach>\n				</ul>\n			\n				<if test=\"is_array($sortIn) AND count( $sortIn )\">\n					<h4>{$this->lang->words[\'filter_by_section\']}</h4>\n					<ul>\n						<foreach loop=\"$sortIn as $id => $_data\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] == $_data[0]\">class=\'active\'</if>>\n								<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$_data[\'0\']}\" base=\"public\"}\'>{$_data[1]}</a>\n							</li>\n						</foreach>\n					</ul>\n				</if>\n			</div>\n		</div>\n	</div>\n	<div class=\'ipsLayout_content\'>		\n		<div class=\'clearfix\'>\n			{$pagination}\n		</div>\n		<div class=\'maintitle ipsFilterbar\'>				\n			<if test=\"IPSSearchRegistry::get(\'config.contentTypes\') AND is_array( IPSSearchRegistry::get(\'config.contentTypes\') )\">\n				<if test=\"count($sortDropDown)\">\n					<span class=\'ipsType_small\'>{$this->lang->words[\'sort_by\']}</span>&nbsp;&nbsp;\n					<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n						<foreach loop=\"$sortDropDown as $k => $l\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortKey\'] == $k\">class=\'active\'</if>>\n								<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortKey]={$k}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortDir]={$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortDir\']}\" base=\"public\"}\'>{$l}</a>\n							</li>\n						</foreach>\n					</ul>\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n				</if>\n				<span class=\'ipsType_small\'>{$this->lang->words[\'order\']}</span>&nbsp;&nbsp;\n				<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n					<li <if test=\"$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortDir\'] == 0\">class=\'active\'</if>>\n						<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortKey]={$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortKey\']}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortDir]=0\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_0\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortDir\'] == 1\">class=\'active\'</if>>\n						<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortKey]={$this->request[\'search_app_filters\'][$current_key][$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']][\'sortKey\']}&amp;search_app_filters[$current_key][{$this->request[\'search_app_filters\'][$current_key][\'searchInKey\']}][sortDir]=1\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_1\']}</a>\n					</li>\n				</ul>\n			<else />\n				<if test=\"count($sortDropDown)\">\n					<span class=\'ipsType_small\'>{$this->lang->words[\'sort_by\']}</span>&nbsp;&nbsp;\n					<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n						<foreach loop=\"$sortDropDown as $k => $l\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$current_key][\'sortKey\'] == $k\">class=\'active\'</if>>\n								<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][sortKey]={$k}&amp;search_app_filters[$current_key][sortDir]={$this->request[\'search_app_filters\'][$current_key][\'sortDir\']}\" base=\"public\"}\'>{$l}</a>\n							</li>\n						</foreach>\n					</ul>\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n				</if>\n				<span class=\'ipsType_small\'>{$this->lang->words[\'order\']}</span>&nbsp;&nbsp;\n				<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n					<li <if test=\"$this->request[\'search_app_filters\'][$current_key][\'sortDir\'] == 0\">class=\'active\'</if>>\n						<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][sortKey]={$this->request[\'search_app_filters\'][$current_key][\'sortKey\']}&amp;search_app_filters[$current_key][sortDir]=0\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_0\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'search_app_filters\'][$current_key][\'sortDir\'] == 1\">class=\'active\'</if>>\n						<a href=\'{parse url=\"{$url_string}&amp;search_app={$current_key}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[$current_key][sortKey]={$this->request[\'search_app_filters\'][$current_key][\'sortKey\']}&amp;search_app_filters[$current_key][sortDir]=1\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_1\']}</a>\n					</li>\n				</ul>\n			</if>\n		</div>\n		<div class=\'ipsBox_container\'>\n			<if test=\"hasTotal:|:$total\">\n				{$results}\n			<else />\n				<p class=\'no_messages\'>{$this->lang->words[\'no_results_found\']}<if test=\"noResultsTerm:|:$search_term\"> {$this->lang->words[\'no_results_found_for\']} \'{$search_term}\'</if>.</p>\n			</if>\n		</div>\n		<div class=\'clearfix\'>\n			{$pagination}\n		</div>\n	</div>\n</div>', 'searchResultsWrapper', '$results, $sortDropDown, $sortIn, $pagination, $total, $showing, $search_term, $url_string, $current_key, $removed_search_terms=array(), $limited=0, $wasLimited=false, $search_tags', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('137', '0', 'skin_search', '<div class=\'result_info\'>\n	<h3>{$r[\'content_title\']}</h3>\n	<if test=\"showGenericContent:|:!$resultAsTitle\">\n	<p>\n		{$r[\'content\']}\n	</p>\n	</if>\n</div>\n<if test=\"$r[\'updated\'] OR $r[\'member_id\']\">\n	<div class=\'result_details desc\'>\n		<ul>\n			<if test=\"$r[\'updated\']\">\n				<li>{parse date=\"$r[\'updated\']\" format=\"short\"}</li>\n			</if>\n			<if test=\"$r[\'member_id\']\">\n				<li>{$this->lang->words[\'search_by\']} <a href=\'{parse url=\"showuser={$r[\'member_id\']}\" template=\"showuser\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\'>{$r[\'members_display_name\']}</a></li>\n			</if>\n		</ul>\n	</div>\n</if>', 'searchRowGenericFormat', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('138', '0', 'skin_search', '<if test=\"whichWayToGo:|:$resultAsTitle\">\n	{parse template=\"asForumTopics\" group=\"search\" params=\"$data\"}\n<else />\n	{parse template=\"asForumPosts\" group=\"search\" params=\"$data\"}\n</if>', 'topicPostSearchResultAsForum', '$data, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('139', '0', 'skin_search', '<php>\n	$datecut		= ( $this->settings[\'search_ucontent_days\'] ) ? $this->registry->class_localization->getDate( time() - ( 86400 * intval( $this->settings[\'search_ucontent_days\'] ) ), \'joined\' ) : 0;\n</php>\n<h2 class=\'ipsType_pagetitle\'>{parse expression=\"sprintf( $this->lang->words[\'s_participation_title\'], $member[\'members_display_name\'] )\"}</h2>\n<input type=\'hidden\' name=\"usedInJsLater\" id=\"urlString\" value=\"{parse expression=\"base64_encode( $this->registry->output->buildUrl( \"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$this->request[\'search_app\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}\", \"public\" ) )\"}\" />\n<if test=\"NPhasResults:|:$total\">\n		<p class=\'ipsType_pagedesc\'>\n			{parse expression=\"sprintf( $this->lang->words[\'s_participation_msg\'], $total, $member[\'members_display_name\'] )\"}\n			<if test=\"$datecut\">\n				<span class=\'desc lighter\'>{parse expression=\"sprintf( $this->lang->words[\'s_participation_range\'], $datecut )\"}</span>\n			</if>\n		</p>\n	<br />\n</if>\n<div class=\'ipsLayout ipsLayout_withleft clearfix\'>\n	<div class=\'ipsLayout_left\'>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container ipsSideMenu\'>\n				<h4>{$this->lang->words[\'filter_by_app\']}</h4>\n				<ul>\n					<if test=\"IPSLib::appIsSearchable( \'forums\', \'usercontent\' )\">\n						<li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app=forums&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'members\', \'usercontent\' )\">\n						<li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app=members&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li>\n					</if>\n					<if test=\"IPSLib::appIsSearchable( \'core\', \'usercontent\' )\">\n						<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'core\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app=core&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'core\' )}</a></li>\n					</if>\n					<foreach loop=\"apps:$this->registry->getApplications() as $app\">\n						<if test=\"appIsSearchable:|:IPSLib::appIsSearchable( $app[\'app_directory\'], \'usercontent\' ) AND !in_array( $app[\'app_directory\'], array(\'core\',\'forums\',\'members\') )\">\n							<li <if test=\"appIsSearched:|:$this->request[\'search_app\'] == $app[\'app_directory\']\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$app[\'app_directory\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( $app[\'app_directory\'] )}</a></li>\n				 		</if>\n					</foreach>\n				</ul>\n				\n				<if test=\"$this->request[\'search_app\'] == \'forums\'\">\n					<h4>{$this->lang->words[\'userposts_morefilters\']}</h4>\n					<ul>\n						<li <if test=\"$this->request[\'userMode\'] == \'all\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$this->request[\'search_app\']}&amp;mid={$this->request[\'mid\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;userMode=all\" base=\"public\"}\'>{$this->lang->words[\'viewall_opt_dd\']}</a></li>\n						<li <if test=\"$this->request[\'userMode\'] == \'title\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$this->request[\'search_app\']}&amp;mid={$this->request[\'mid\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;userMode=title\" base=\"public\"}\'>{$this->lang->words[\'viewallt_opt_dd\']}</a></li>\n						<li <if test=\"$this->request[\'userMode\'] == \'content\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$this->request[\'search_app\']}&amp;mid={$this->request[\'mid\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;userMode=content\" base=\"public\"}\'>{$this->lang->words[\'viewallp_opt_dd\']}</a></li>\n					</ul>\n				</if>\n				\n				<if test=\"is_array($sortIn) AND count( $sortIn )\">\n					<h4>{$this->lang->words[\'filter_by_type\']}</h4>\n					<ul>\n						<foreach loop=\"$sortIn as $id => $_data\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] == $_data[0]\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;search_app={$this->request[\'search_app\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$_data[0]}\" base=\"public\"}\'>{$_data[1]}</a>\n							</li>\n						</foreach>\n					</ul>\n				</if>\n			</div>\n		</div>\n	</div>\n	<div class=\'ipsLayout_content\'>\n		<if test=\"$pagination\">\n			<div class=\'topic_controls\'>\n				{$pagination}\n			</div>\n			<br />\n		</if>\n		<div class=\'maintitle ipsFilterbar\'>\n			<if test=\"IPSSearchRegistry::get(\'config.contentTypes\') AND is_array( IPSSearchRegistry::get(\'config.contentTypes\') )\">\n				<if test=\"count($sortDropDown)\">\n					<span class=\'ipsType_small\'>{$this->lang->words[\'sort_by\']}</span>&nbsp;&nbsp;\n					<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n						<foreach loop=\"$sortDropDown as $k => $l\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortKey\'] == $k\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;search_app={$this->request[\'search_app\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortKey]={$k}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortDir]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortDir\']}\" base=\"public\"}\'>{$l}</a>\n							</li>\n						</foreach>\n					</ul>\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n				</if>\n				<span class=\'ipsType_small\'>{$this->lang->words[\'order\']}</span>&nbsp;&nbsp;\n				<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n					<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortDir\'] == 0\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app={$this->request[\'search_app\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortDir]=0\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_0\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortDir\'] == 1\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app={$this->request[\'search_app\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']][\'sortKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][{$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}][sortDir]=1\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_1\']}</a>\n					</li>\n				</ul>\n			<else />\n				<if test=\"count($sortDropDown)\">\n					<span class=\'ipsType_small\'>{$this->lang->words[\'sort_by\']}</span>&nbsp;&nbsp;\n					<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n						<foreach loop=\"$sortDropDown as $k => $l\">\n							<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortKey\'] == $k\">class=\'active\'</if>>\n								<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app={$this->request[\'search_app\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][sortKey]={$k}&amp;search_app_filters[{$this->request[\'search_app\']}][sortDir]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortDir\']}\" base=\"public\"}\'>{$l}</a>\n							</li>\n						</foreach>\n					</ul>\n					&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\n				</if>\n				<span class=\'ipsType_small\'>{$this->lang->words[\'order\']}</span>&nbsp;&nbsp;\n				<ul class=\'ipsList_inline ipsType_smaller\' style=\'display: inline\'>\n					<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortDir\'] == 0\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app={$this->request[\'search_app\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][sortKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][sortDir]=0\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_0\']}</a>\n					</li>\n					<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortDir\'] == 1\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;sid={$this->request[\'_sid\']}&amp;mid={$this->request[\'mid\']}&amp;userMode={$this->request[\'userMode\']}&amp;search_app={$this->request[\'search_app\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][sortKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'sortKey\']}&amp;search_app_filters[{$this->request[\'search_app\']}][sortDir]=1\" base=\"public\"}\'>{$this->lang->words[\'s_search_type_o_1\']}</a>\n					</li>\n				</ul>\n			</if>\n		</div>\n		<div>\n			<if test=\"NPTotal:|:$total\">\n				{$results}\n				<br />\n				{$pagination}\n			<else />\n				<p class=\'no_messages\'>{$this->lang->words[\'user_posts_none\']}</p>\n			</if>\n		</div>\n	</div>\n</div>', 'userPostsView', '$results, $pagination, $total, $member, $limited=0, $wasLimited=false, $beginTime=0, $sortIn=null, $sortDropDown=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('140', '0', 'skin_stats', '<!-- This is looped over once for admins, once for supmods, and then once for forum mods -->\n<table class=\'ipb_table ipsMemberList\'>\n	<caption class=\'maintitle\'>{$group}</caption>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 3%\'>&nbsp;</th>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'leader_name\']}</th>\n		<th scope=\'col\' style=\'width: 35%\' class=\'short\'>{$this->lang->words[\'leader_forums\']}</th>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'leader_location\']}</th>\n		<th scope=\'col\' style=\'width: 12%\'>&nbsp;</th>\n	</tr>\n	<if test=\"hasLeaders:|:count($members) AND is_array($members)\">\n		{parse striping=\"staff\" classes=\"row1,row2\"}\n		<foreach loop=\"members:$members as $info\">\n			<tr class=\'{parse striping=\"staff\"}\'>\n				<td>\n					<a href=\'{parse url=\"showuser={$info[\'member_id\']}\" seotitle=\"{$info[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' class=\'ipsUserPhotoLink\' title=\'{$this->lang->words[\'view_profile\']}\'>\n						<img src=\'{$info[\'pp_mini_photo\']}\' alt=\'photo\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n					</a>\n				</td>\n				<td>\n					<if test=\"leadermid:|:$info[\'member_id\'] > 0\">\n						{parse expression=\"IPSMember::makeProfileLink($info[\'members_display_name\'], $info[\'member_id\'], $info[\'members_seo_name\'])\"}\n					<else />\n						{$info[\'members_display_name\']}\n					</if>\n				</td>\n				<td class=\'altrow short\'>\n					<if test=\"specificForums:|:is_array($info[\'forums\'])\">\n						<form method=\"post\" action=\"{parse url=\"\" base=\"public\"}\" id=\"jmenu{$info[\'member_id\']}\" class=\'jump\'>\n							<select name=\"showforum\">\n								<option value=\"-1\">{parse expression=\"sprintf($this->lang->words[\'no_forums\'],count($info[\'forums\']))\"}</option>\n								<option value=\"-1\">---------------------------</option>\n								<foreach loop=\"forums:$info[\'forums\'] as $id => $name\">\n									<option value=\"{$id}\">{$name}</option>\n								</foreach>\n							</select>\n							<input type=\'submit\' class=\'input_submit alt\' value=\'{$this->lang->words[\'go_button\']}\' />\n						</form>\n					<else />\n						{$info[\'forums\']}\n					</if>\n				</td>\n				<td>\n					<if test=\"isonline:|:$info[\'_online\']\">\n						{$info[\'online_extra\']}\n					</if>\n				</td>\n				<td class=\'short altrow\'>\n					<ul class=\'ipsList_inline right ipsList_nowrap\'>\n						<if test=\"isFriendable:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n							<if test=\"isFriend:|:IPSMember::checkFriendStatus( $info[\'member_id\'] )\">\n								<li class=\'mini_friend_toggle is_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a></li>\n							<else />\n								<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a></li>								\n							</if>\n						</if>\n						<if test=\"canPm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n							<li class=\'pm_button\' id=\'pm_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n						</if>\n						<if test=\"hasBlog:|:$info[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n							<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n						</if>\n						<if test=\"hasGallery:|:$info[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n							<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n						</if>\n					</ul>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<br />', 'group_strip', '$group=\"\", $members=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('141', '0', 'skin_stats', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'todays_posters\']}</h1>\n<br />\n<table class=\'ipb_table ipsMemberList\'>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 3%\'>&nbsp;</th>\n		<th scope=\'col\'>{$this->lang->words[\'member\']}</th>\n		<th scope=\'col\'>{$this->lang->words[\'member_joined\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_posts\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_today\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_percent\']}</th>\n		<th scope=\'col\' class=\'short\'>&nbsp;</th>\n	</tr>\n	<if test=\"hasTopPosters:|:!is_array($rows) OR !count($rows)\">\n		<tr>\n			<td colspan=\'7\' class=\'no_messages\'>{$this->lang->words[\'no_info\']}</td>\n		</tr>\n	<else />\n		{parse striping=\"top_posters\" classes=\"row1,row2\"}\n		<foreach loop=\"topposters:$rows as $info\">\n			<tr class=\'{parse striping=\"top_posters\"}\'>\n				<td>\n					<img src=\'{$info[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$info[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n				</td>\n				<td>\n					<if test=\"topPosterMid:|:$info[\'member_id\'] > 0\">\n						{parse expression=\"IPSMember::makeProfileLink($info[\'members_display_name\'], $info[\'member_id\'], $info[\'members_seo_name\'])\"}\n					<else />\n						{$info[\'members_display_name\']}\n					</if>\n				</td>\n				<td class=\'altrow\'>\n					{parse date=\"$info[\'joined\']\" format=\"joined\"}\n				</td>\n				<td class=\'short\'>\n					{parse format_number=\"$info[\'posts\']\"}\n				</td>\n				<td class=\'altrow short\'>\n					{parse format_number=\"$info[\'tpost\']\"}\n				</td>\n				<td class=\'short\'>\n					{$info[\'today_pct\']}%\n				</td>\n				<td class=\'altrow short\'>\n					<ul class=\'ipsList_inline right\'>\n						<if test=\"tpIsFrindable:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n							<if test=\"tpIsFriend:|:IPSMember::checkFriendStatus( $info[\'member_id\'] )\">\n								<li class=\'mini_friend_toggle is_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a></li>\n							<else />\n								<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a></li>								\n							</if>\n						</if>\n						<if test=\"tpPm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n							<li class=\'pm_button\' id=\'pm_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n						</if>\n						<if test=\"tpBlog:|:$info[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n							<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n						</if>\n						<if test=\"tpGallery:|:$info[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n							<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n						</if>\n					</ul>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>', 'top_posters', '$rows', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('142', '0', 'skin_stats', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'who_farted\']} {IPSText::truncate( $title, 40 )}</h3>\n<else />\n	<h3 class=\'maintitle\'>{$this->lang->words[\'who_farted\']} {IPSText::truncate( $title, 30 )}</h3>\n</if>\n<div class=\'fixed_inner\'>\n	<table class=\'ipb_table\'>\n		<tr class=\'header\'>\n			<th>{$this->lang->words[\'whoposted_name\']}</th>\n			<th>{$this->lang->words[\'whoposted_posts\']}</th>\n		</tr>\n		<if test=\"hasPosters:|:count($rows) AND is_array($rows)\">\n			{parse striping=\"whoposted\" classes=\"row1,row2\"}\n			<foreach loop=\"whoposted:$rows as $row\">\n				<tr class=\'{parse striping=\"whoposted\"}\'>\n					<td class=\"altrow\">\n						<if test=\"posterHasMid:|:$row[\'author_id\']\">\n							<a href=\"{parse url=\"showuser={$row[\'author_id\']}\" template=\"showuser\" seotitle=\"{$row[\'members_seo_name\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'goto_profile\']}\">{$row[\'author_name\']}</a>\n						<else />\n							{$row[\'author_name\']}\n						</if>\n					</td>\n					<td>{$row[\'pcount\']}</td>\n				</tr>\n			</foreach>\n		</if>\n	</table>\n</div>', 'whoPosted', '$tid=0, $title=\"\", $rows=array()', '1338050060', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('143', '0', 'skin_editors', '<!--no data in this master skin-->', 'ajaxEditBox', '$post=\"\", $pid=0, $error_msg=\"\", $extraData', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('144', '0', 'skin_editors', '<php>\n	/* Always return as UTF-8 */\n	array_walk_recursive( $autoSaveData, array( \'IPSText\', \'arrayWalkCallbackConvert\' ) );\n	$jsonEncoded = json_encode( $autoSaveData );\n	$jsonEncoded = IPSText::convertCharsets($jsonEncoded, \"UTF-8\", IPS_DOC_CHAR_SET);\n</php>\n<if test=\"jsNotLoaded:|:empty($this->_editorJsLoaded)\">\n	{parse template=\"editorLoadJs\" group=\"editors\" params=\"$options\"}\n</if>\n<textarea id=\"{$options[\'editorName\']}\" name=\"{$formField}\" class=\'ipsEditor_textarea input_text<if test=\"ismini:|:$options[\'type\'] == \'mini\'\"> mini</if>\'>{$content}</textarea>\n<script type=\"text/javascript\">\n	ipb.textEditor.initialize(\'{$options[\'editorName\']}\', { type: <if test=\"hasType:|:$options[\'type\']\">\'{$options[\'type\']}\'<else />\'\'</if>,\n															height: <if test=\"hasHeight:|:$options[\'height\'] > 0\">{$options[\'height\']}<else /><if test=\"ismini:|:$options[\'type\'] == \'mini\'\">150<else />300</if></if>,\n															minimize: <if test=\"hasMinimize:|:$options[\'minimize\']\">\'{$options[\'minimize\']}\'<else />0</if>,\n															bypassCKEditor: {parse expression=\"intval( $options[\'bypassCKEditor\'] )\"},\n															isRte: {parse expression=\"intval( $options[\'isRte\'] )\"},\n															isTypingCallBack: <if test=\"hasCallback:|:$options[\'isTypingCallBack\']\">{$options[\'isTypingCallBack\']}<else />\'\'</if>,\n															ips_AutoSaveKey: <if test=\"hasSaveKey:|:$options[\'autoSaveKey\']\">\'{$options[\'autoSaveKey\']}\'<else />\'\'</if>,\n											                ips_AutoSaveData: {$jsonEncoded} } );\n</script>', 'editor', '$formField=\'post\', $content=\'\', $options=array(), $autoSaveData=array()', '1338050060', '0', '0', '0', '0', 'mobile');
