INSERT INTO `ibf_skin_templates` VALUES ('213', '0', 'skin_global_other', '<h3 class=\'maintitle\'>{$this->lang->words[\'mob_tags\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<ul class=\'ipsList_inline\'>\n		<foreach loop=\"eachTag:$tags[\'tags\'] as $id => $data\">\n			<li><span class=\"{$data[\'className\']}\">{$data[\'tagWithUrl\']}</span></li>\n		</foreach>\n		</ul>\n	</div>\n</div>', 'tagCloud', '$tags', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('214', '0', 'skin_global_other', '<a <if test=\"noClass:|:!$noClass\">class=\'ipsTag\'</if> href=\"{parse url=\"app=core&amp;module=search&amp;do=search&amp;search_tags={parse expression=\"urlencode($tag)\"}&amp;search_app=<if test=\"inSearch:|:$this->request[\'search_app\']\">{$this->request[\'search_app\']}<else />{parse expression=\"IPS_APP_COMPONENT\"}</if>\" base=\"public\"}\" data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'find_more_tags\'], $tag )\"}\">{$tag}</a>', 'tagEntry', '$tag, $noClass=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('215', '0', 'skin_global_other', '<a href=\"{parse url=\"app=core&amp;module=search&amp;do=search&amp;search_tags={parse expression=\"urlencode($tag)\"}&amp;search_app=<if test=\"inSearch:|:$this->request[\'search_app\']\">{$this->request[\'search_app\']}<else />{parse expression=\"IPS_APP_COMPONENT\"}</if>\" base=\"public\"}\" class=\'ipsBadge ipsBadge_lightgrey\'>{$tag}</a>', 'tagPrefix', '$tag', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('216', '0', 'skin_global_other', '<script type=\'text/javascript\' src=\"{$this->settings[\'public_dir\']}js/ips.tags.mobile.js\"></script>\n<a href=\'#\' id=\'{$options[\'fieldId\']}_tag_button\' class=\'ipsTagBox_launcher\'>{$this->lang->words[\'mob_edit_tags\']}</a>\n<div class=\'ipsFilterPane\' id=\'{$options[\'fieldId\']}_tag_pane\' style=\'display: none\'>\n	<a href=\'#\' id=\'{$options[\'fieldId\']}_close_pane\' class=\'ipsFilterPane_close\'><span>&times;</span></a>\n	<div>\n		<h4>{$this->lang->words[\'topictagsh4\']}</h4>\n		<if test=\"!$options[\'minTags\'] && $options[\'maxTags\']\">\n			<h5>{parse expression=\"sprintf( $this->lang->words[\'tags_max_no_min\'], $options[\'maxTags\'] )\"}</h5>\n		</if>\n		<if test=\"$options[\'minTags\'] && !$options[\'maxTags\']\">\n			<h5>{parse expression=\"sprintf( $this->lang->words[\'tags_min_no_max\'], $options[\'minTags\'] )\"}</h5>\n		</if>\n		<if test=\"$options[\'minTags\'] && $options[\'maxTags\']\">\n			<h5>{parse expression=\"sprintf( $this->lang->words[\'tags_max_and_min\'], $options[\'minTags\'], $options[\'maxTags\'] )\"}</h5>\n		</if>\n		<div class=\'ipsFilterPane_inner\'>\n			<div class=\'ipsTagBox\'>\n				<ul id=\'{$options[\'fieldId\']}_tags\' class=\'ipsTagBox_taglist\'></ul>\n			</div>\n			<div class=\'ipsTagBox_editor\'>\n				<span id=\'{$options[\'fieldId\']}_addwrap\'>\n					<if test=\"!$options[\'isOpenSystem\']\">\n						<select id=\'{$options[\'fieldId\']}_tag_select\' class=\'input_select\'>\n							<foreach loop=\"$options[\'predefinedTags\'] as $tag\">\n								<option value=\"$tag\">{$tag}</option>\n							</foreach>\n						</select>\n					<else />\n						<input type=\'text\' id=\'{$options[\'fieldId\']}_tag_input\' class=\'input_text\' />\n					</if> <input type=\'submit\' value=\'{$this->lang->words[\'mob_add_tag\']}\' class=\'input_submit\' id=\'{$options[\'fieldId\']}_tag_add\' />\n				</span>\n				<span id=\'{$options[\'fieldId\']}_removewrap\' style=\'display: none\'>\n					<input type=\'submit\' value=\'{$this->lang->words[\'mob_remove_tag\']}\' id=\'{$options[\'fieldId\']}_tag_remove\' class=\'input_submit ipsTagBox_remove\' />\n				</span>\n			</div>\n		</div>\n	</div>\n</div>\n<input type=\"text\" value=\"\" name=\"{$options[\'fieldId\']}\" id=\"{$options[\'fieldId\']}\" style=\'display: none\' />\n<php>\n	$options[\'lang\'][\'tag_add_link\']	= $this->lang->words[\'add_a_tag\'];\n	$options[\'lang\'][\'tip_text\']		= $this->lang->words[\'tag_tip\'];\n	$options[\'forceLowercase\']			= $this->settings[\'tags_force_lower\'];\n	$options[\'existingTags\']			= count($tags[\'tags\']) ? $tags[\'tags\'] : null;\n	$_tmp = $options;\n	\n	/* Always return as UTF-8 */\n	array_walk_recursive( $_tmp, array( \'IPSText\', \'arrayWalkCallbackConvert\' ) );\n	$jsonEncoded = json_encode( $_tmp );\n	$jsonEncoded = IPSText::convertCharsets($jsonEncoded, \"UTF-8\", IPS_DOC_CHAR_SET);\n</php>\n<script type=\"text/javascript\">\n	$( \"{$options[\'fieldId\']}\" ).mobileTagify( {$jsonEncoded} );\n</script>', 'tagTextEntryBox', '$tags, $options, $where', '1338050060', '0', '0', '0', '0', 'mobile');
