INSERT INTO `ibf_skin_templates` VALUES ('284', '0', 'skin_search', '<div class=\'row\'>\n	<div class=\'icon\'>\n		<a href=\'{parse url=\"showuser={$r[\'type_id_2\']}\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\'>\n			<if test=\"$r[\'misc\'][\'pp_thumb_photo\']\">\n				<img src=\'{$r[\'misc\'][\'pp_thumb_photo\']}\' width=\"25\" height=\"25\" class=\'photo\' />\n			<else />\n				<img src=\'{$this->settings[\'img_url\']}/profile/default_thumb.png\' width=\"25\" height=\"25\" class=\'photo\' />\n			</if>\n		</a>\n	</div>\n	<strong><a href=\'{parse url=\"showuser={$r[\'type_id_2\']}\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\'>{$r[\'content_title\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$r[\'type_id_2\'],$r[\'members_seo_name\']\"}</strong><br />\n	<span class=\'subtext\'>{$this->lang->words[\'member_joined\']} {parse date=\"$r[\'joined\']\" format=\"short\"}</span>\n</div>', 'memberSearchResult', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('285', '0', 'skin_search', '{parse js_module=\"search\"}\n<input type=\'hidden\' name=\"usedInJsLater\" id=\"urlString\" value=\"{parse expression=\"base64_encode( $this->registry->output->buildUrl( \"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}\", \"public\" ) )\"}\" />\n<h2>{$this->lang->words[\'new_content\']}</h2>\n<php>\n	$i = 2;\n	\n	if( is_array($sortIn) AND count( $sortIn ) ){ $i++;	}\n	if( IPSLib::appIsSearchable( $this->request[\'search_app\'], \'vncWithFollowFilter\' ) AND $this->memberData[\'member_id\'] ){ $i++; }\n	\n	switch( $i ){\n		case 3:\n			$classname = \'three_\';\n		break;\n		case 4:\n			$classname = \'four_\';\n		break;\n		default:\n			$classname = \'two_\';\n		break;\n	}\n</php>\n	\n<div class=\'ipsFilterBar {$classname}filters clearfix\' id=\'vnc_filters\'>\n	<ul>\n		<li id=\'filter_app\' class=\'filter\'><a href=\'#\'>{$this->lang->words[\'short_filter_by_app\']}</a></li>\n		<if test=\"is_array($sortIn) AND count( $sortIn )\">\n			<li id=\'filter_section\' class=\'filter\'><a href=\'#\'>{$this->lang->words[\'short_filter_by_section\']}</a></li>\n		</if>\n		<li id=\'filter_time\' class=\'filter\'><a href=\'#\'>{$this->lang->words[\'short_filter_by_time\']}</a></li>\n		<if test=\"canFollowFilter:|:IPSLib::appIsSearchable( $this->request[\'search_app\'], \'vncWithFollowFilter\' ) AND $this->memberData[\'member_id\']\">\n			<li id=\'filter_other\' class=\'filter\'><a href=\'#\'>{$this->lang->words[\'short_filter_by_other\']}</a></li>\n		</if>\n	</ul>\n</div>\n<div class=\'ipsFilterPane\' id=\'filter_app_pane\' style=\'display: none\'>\n	<a href=\'#\' class=\'ipsFilterPane_close\'><span>&times;</span></a>\n	<div>\n		<h4>{$this->lang->words[\'mobile_filter_by_app\']}</h4>\n		<ul>\n			<if test=\"IPSLib::appIsSearchable( \'forums\', \'vnc\' ) || IPSLib::appIsSearchable( \'forums\', \'active\' )\">\n				<li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=forums&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li>\n			</if>\n			<if test=\"IPSLib::appIsSearchable( \'members\', \'vnc\' ) || IPSLib::appIsSearchable( \'members\', \'active\' )\">\n				<li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=members&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li>\n			</if>\n			<if test=\"IPSLib::appIsSearchable( \'core\', \'vnc\' ) || IPSLib::appIsSearchable( \'core\', \'active\' )\">\n				<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'core\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app=core&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{IPSLib::getAppTitle( \'core\' )}</a></li>\n			</if>\n			<foreach loop=\"apps:$this->registry->getApplications() as $app\">\n				<if test=\"appIsSearchable:|:(IPSLib::appIsSearchable( $app[\'app_directory\'], \'vnc\' ) || IPSLib::appIsSearchable( $app[\'app_directory\'], \'active\' ) ) AND !in_array( $app[\'app_directory\'], array(\'core\',\'forums\',\'members\') )\">\n					<li <if test=\"appIsSearched:|:$this->request[\'search_app\'] == $app[\'app_directory\']\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$app[\'app_directory\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>\n							{IPSLib::getAppTitle( $app[\'app_directory\'] )}\n						</a>\n					</li>\n		 		</if>\n			</foreach>\n		</ul>\n	</div>\n</div>\n<if test=\"is_array($sortIn) AND count( $sortIn )\">\n	<div class=\'ipsFilterPane\' id=\'filter_section_pane\' style=\'display: none\'>\n		<a href=\'#\' class=\'ipsFilterPane_close\'><span>&times;</span></a>\n		<div>\n			<h4>{$this->lang->words[\'mobile_filter_by_section\']}</h4>\n			<ul>\n				<foreach loop=\"$sortIn as $id => $_data\">\n					<li <if test=\"$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] == $_data[0]\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$_data[\'0\']}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$_data[1]}</a>\n					</li>\n				</foreach>\n			</ul>		\n		</div>\n	</div>\n</if>\n<div class=\'ipsFilterPane\' id=\'filter_time_pane\' style=\'display: none\'>\n	<a href=\'#\' class=\'ipsFilterPane_close\'><span>&times;</span></a>\n	<div>\n		<h4>{$this->lang->words[\'mobile_filter_by_time\']}</h4>\n		<ul>\n			<if test=\"hazMember:|:$this->memberData[\'member_id\']\">\n				<if test=\"hazVNC:|:IPSLib::appIsSearchable( IPSSearchRegistry::get(\'in.search_app\'), \'vncWithUnreadContent\' )\">\n					<li <if test=\"$this->request[\'period\']==\'unread\'\">class=\'active\'</if>>\n						<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=unread&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'filter_not_read\']}</a>\n					</li>\n				</if>\n				<li <if test=\"$this->request[\'period\']==\'lastvisit\'\">class=\'active\'</if>>\n					<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=lastvisit&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'filter_new_visit\']}</a>\n				</li>\n			</if>\n			<li <if test=\"$this->request[\'period\']==\'today\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=today&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_today\']}</a>\n			</li>\n			<li <if test=\"$this->request[\'period\']==\'week\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=week&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_week\']}</a>\n			</li>\n			<li <if test=\"$this->request[\'period\']==\'weeks\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=weeks&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_weeks\']}</a>\n			</li>\n			<li <if test=\"$this->request[\'period\']==\'month\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=month&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_month\']}</a>\n			</li>\n			<li <if test=\"$this->request[\'period\']==\'months\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=months&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_months\']}</a>\n			</li>\n			<li <if test=\"$this->request[\'period\']==\'year\'\">class=\'active\'</if>>\n				<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period=year&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}\" base=\"public\"}\'>{$this->lang->words[\'actperiod_year\']}</a>\n			</li>\n		</ul>\n	</div>\n</div>\n<div class=\'ipsFilterPane\' id=\'filter_other_pane\' style=\'display: none\'>\n	<a href=\'#\' class=\'ipsFilterPane_close\'><span>&times;</span></a>\n	<div>\n		<h4>{$this->lang->words[\'mobile_filter_by_other\']}</h4>\n		<ul>\n			<if test=\"checked:|:$this->request[\'followedItemsOnly\']\">\n				<li class=\"active\">\n					<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly=0\" base=\"public\"}\'>{$this->lang->words[\'filter_i_follow\']}</a>\n				</li>\n			<else />\n				<li>\n					<a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[ $this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\'] ]}&amp;period={$this->request[\'period\']}&amp;userMode={$this->request[\'userMode\']}&amp;followedItemsOnly=1\" base=\"public\"}\'>{$this->lang->words[\'filter_i_follow\']}</a>\n				</li>\n			</if>\n			<li <if test=\"$this->request[\'userMode\'] == \'all\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period={$this->request[\'period\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}&amp;userMode=<if test=\"$this->request[\'userMode\'] != \'all\'\">all</if>\" base=\"public\"}\'>{$this->lang->words[\'vnc_topics_and_posts\']}</a></li>\n			<li <if test=\"$this->request[\'userMode\'] == \'title\'\">class=\'active\'</if>><a href=\'{parse url=\"app=core&amp;module=search&amp;do=viewNewContent&amp;search_app={$this->request[\'search_app\']}&amp;sid={$this->request[\'_sid\']}&amp;search_app_filters[{$this->request[\'search_app\']}][searchInKey]={$this->request[\'search_app_filters\'][$this->request[\'search_app\']][\'searchInKey\']}&amp;period={$this->request[\'period\']}&amp;followedItemsOnly={$this->request[\'followedItemsOnly\']}&amp;userMode=<if test=\"$this->request[\'userMode\'] != \'title\'\">title</if>\" base=\"public\"}\'>{$this->lang->words[\'vnc_topics_only\']}</a></li>\n			<!--<if test=\"vncFilterForumsOnly:|:$this->request[\'search_app\'] == \'forums\'\"><li <if test=\"hasFilters:|:IPSSearchRegistry::get(\'forums.vncForumFilters\') != null\">class=\'active\'</if>><a href=\'\' id=\'vncForumFilter\'>{$this->lang->words[\'vnc_filter_by_forum\']}</a></li></if>-->\n		</ul>\n	</div>\n</div>\n		\n<if test=\"NPTotal:|:$total\">\n	<div class=\'master_list\'>\n		{$results}\n	</div>\n	<if test=\"$pagination\">\n		<div class=\'controls\'>\n			<div class=\'buttons\'>\n				{$pagination}\n			</div>\n		</div>\n	</if>\n<else />\n	<p class=\'no_messages\'>{$this->lang->words[\'new_content_none\']}</p>\n</if>\n<script type=\'text/javascript\'>\n	$(\'vnc_filters\').on(\"click\", \"li.filter\", mobileFilter);\n	$(\'ipboard_body\').on(\"click\", \".ipsFilterPane_close\", closePane);\n</script>', 'newContentView', '$results, $pagination, $total, $sortDropDown, $sortIn, $dateCutSet=0', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('286', '0', 'skin_search', '<div class=\'master_list\'>\n<h2>{$this->lang->words[\'new_content\']}</h2>\n<if test=\"NPhasResults:|:$total\">\n	<p class=\'message\'>\n		{$this->lang->words[\'new_content_there\']} <strong>{$total}</strong> {$this->lang->words[\'new_content_entries\']}\n	</p>\n	<div class=\"controls\">\n<div class=\'buttons\'>\n		{$pagination}\n	</div></div>\n</if>\n<if test=\"NPTotal:|:$total\">\n	{$results}\n	\n	<div class=\"controls\">\n<div class=\'buttons\'>\n		{$pagination}\n	</div></div>\n<else />\n	<p class=\'row no_messages\'>{$this->lang->words[\'new_content_none\']}</p>\n</if>\n</div>', 'newPostsView', '$results, $pagination, $total, $sortDropDown, $sortIn, $dateCutSet=0', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('287', '0', 'skin_search', '<form action=\"{parse url=\"app=core&amp;module=search&amp;section=search&amp;do=search\" base=\"public\"}&amp;fromsearch=1\" method=\"post\" id=\'search-box\' >\n<input type=\'hidden\' name=\'search_app\' id=\'search_app\' value=\'{$this->request[\'search_app\']}\' />\n<div class=\'master_list ipsForm_vertical\'>\n	<h2>{$this->lang->words[\'search\']}</h2>\n	\n	<if test=\"searchTermsRemoved:|:is_array( $removed_search_terms ) && count( $removed_search_terms )\">\n		<div class=\'message error\'>{$this->lang->words[\'removed_search_terms\']} <strong>{parse expression=\"implode( \',\', $removed_search_terms )\"}</strong></div>\n	</if>\n	<if test=\"searchError:|:$msg\">\n		<div class=\'message error\'>{$msg}</div>\n	</if>\n	\n	<div class=\'ipsField\'>\n		<label for=\'query\' class=\'ipsField_title\'>{$this->lang->words[\'find_words\']}</label>\n		<input type=\'text\' class=\'input_text\' name=\'search_term\' size=\'30\' id=\'query\' value=\'{$this->request[\'search_term\']}\' />\n	</div>\n	<div class=\'ipsField\'>\n		<label for=\'author\' class=\'ipsField_title\'>{$this->lang->words[\'find_author\']}</label>\n		<input type=\'text\' class=\'input_text\' name=\'search_author\' size=\'30\' id=\'author\' value=\'{$this->request[\'search_author\']}\' />\n	</div>\n	\n	<h3>{$this->lang->words[\'filters\']}</h3>\n	\n	<if test=\"count($filters)\">\n		<foreach loop=\"$filters as $app => $data\">\n			<if test=\"$app == \'forums\'\">\n			<div id=\'app_filter_{$app}\'>\n				<if test=\"!empty($data[\'html\'])\">\n					{$data[\'html\']}\n				</if>\n				<if test=\"count($data[\'sortDropDown\'])\">\n					<if test=\"is_array($data[\'sortDropIn\']) AND count( $data[\'sortDropIn\'] )\">\n						<foreach loop=\"$data[\'sortDropIn\'] as $id => $_data\">\n							<ul>\n								<li>\n									<label for=\'search_by_{$_data[0]}\'><if test=\"! $id\">{$this->lang->words[\'s_member_sin\']}<else />&nbsp;</if></label>\n									<input type=\'radio\' name=\'search_app_filters[$app][searchInKey]\' value=\'{$_data[0]}\' <if test=\"$this->request[\'search_app_filters\'][$app][\'searchInKey\'] == $_data[0] || ( ! $this->request[\'search_app_filters\'][$app][\'searchInKey\'] AND ! $id )\">checked=\"checked\"</if> /> $_data[1]\n									<select name=\'search_app_filters[$app][{$_data[0]}][sortKey]\' class=\'input_select\' style=\'width:auto\'>\n									<foreach loop=\"$data[\'sortDropDown\'][$_data[0]] as $k => $l\">\n										<option value=\'$k\' <if test=\"$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortKey\'.$_data[0]] == $k\">selected=\'selected\'</if>>{$l}</option>\n									</foreach>\n									</select>\n									<select name=\'search_app_filters[$app][{$_data[0]}][sortDir]\' class=\'input_select\' style=\'width:auto\'>\n										<option value=\'0\' <if test=\"!$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_0\']}</option>\n										<option value=\'1\' <if test=\"$this->request[\'search_app_filters\'][$app][$_data[0]][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_1\']}</option>\n									</select>\n								</li>\n							</ul>\n						</foreach>\n					<else />\n						<div class=\'ipsField\'>\n							<label for=\'search_by\' class=\'ipsField_title\'>{$this->lang->words[\'s_search_type\']}</label>\n							<select name=\'search_app_filters[$app][sortKey]\' id=\'search_sort_by_{$app}\' class=\'input_select\' style=\'width:auto\'>\n								<foreach loop=\"$data[\'sortDropDown\'] as $k => $l\">\n									<option value=\'$k\' <if test=\"$this->request[\'search_app_filters\'][$app][\'sortKey\'] == $k\">selected=\'selected\'</if>>{$l}</option>\n								</foreach>\n							</select>\n							<select name=\'search_app_filters[$app][sortDir]\' id=\'search_sort_order_{$app}\' class=\'input_select\' style=\'width:auto\'>\n								<option value=\'0\' <if test=\"!$this->request[\'search_app_filters\'][$app][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_0\']}</option>\n								<option value=\'1\' <if test=\"$this->request[\'search_app_filters\'][$app][\'sortDir\']\">selected=\'selected\'</if>>{$this->lang->words[\'s_search_type_o_1\']}</option>\n							</select>\n						</div>\n					</if>\n				</if>\n			</div>\n			</if>\n		</foreach>\n		</if>	\n	<div class=\'submit\'>\n		<input type=\'submit\' name=\'submit\' class=\'button\' value=\'{$this->lang->words[\'do_search\']}\'>\n	</div>\n</div>\n</form>', 'searchAdvancedForm', '$filters=\'\', $msg=\'\', $current_app, $removed_search_terms=array(), $isFT=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('288', '0', 'skin_search', '{parse striping=\"searchStripe\" classes=\"row1,row2\"}\n<div id=\'search_results\'>\n	<ol>\n		<if test=\"is_array( $results )\">\n		<foreach loop=\"results:$results as $result\">\n			<if test=\"subResult:|:$result[\'sub\']\">\n				<li class=\'{parse striping=\"searchStripe\"} sub clearfix clear\'>\n					{$result[\'html\']}\n				</li>\n			<else />\n				<li class=\'{parse striping=\"searchStripe\"} clearfix clear\'>\n					{$result[\'html\']}\n				</li>\n			</if>\n		</foreach>\n		</if>\n	</ol>\n</div>', 'searchResults', '$results, $titlesOnly', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('289', '0', 'skin_search', '{parse template=\"searchResults\" group=\"search\" params=\"$results, $titlesOnly\"}', 'searchResultsAsForum', '$results, $titlesOnly', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('290', '0', 'skin_search', '<php>\n	$i = 0;\n	if( IPSLib::appIsSearchable( \'forums\', \'search\' ) ){ $i++;	}\n	if( IPSLib::appIsSearchable( \'members\', \'search\' ) ){ $i++;	}\n	if( IPSLib::appIsInstalled(\'blog\') && IPSLib::appIsSearchable( \'blog\', \'search\' ) ){ $i++;	}\n	if( IPSLib::appIsInstalled(\'gallery\') && IPSLib::appIsSearchable( \'gallery\', \'search\' ) ){ $i++;	}\n	\n	switch( $i ){\n		case 3:\n			$classname = \'three_\';\n		break;\n		case 4:\n			$classname = \'four_\';\n		break;\n		case 2:\n			$classname = \'two_\';\n		break;\n		default:\n			$classname = \'one_\';\n		break;\n	}\n</php>\n<div class=\'master_list\'>\n	<h2><if test=\"hasSearchResults:|:$total > 0 AND $search_term != \'\'\">{$total} </if>{$this->lang->words[\'search_results\']}</h2>\n	\n	<div class=\'ipsFilterBar {$classname}filters clearfix\' id=\'vnc_filters\'>\n		<ul>\n			<if test=\"IPSLib::appIsSearchable( \'forums\', \'search\' )\">\n				<li <if test=\"forumsTab:|:$this->request[\'search_app\'] == \'forums\'\">class=\'selected\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=forums\" base=\"public\"}\'>{IPSLib::getAppTitle( \'forums\' )}</a></li>\n			</if>\n			<if test=\"IPSLib::appIsSearchable( \'members\', \'search\' )\">\n				<li <if test=\"membersTab:|:$this->request[\'search_app\'] == \'members\'\">class=\'selected\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=members\" base=\"public\"}\'>{IPSLib::getAppTitle( \'members\' )}</a></li>\n			</if>\n			<if test=\"IPSLib::appIsInstalled(\'blog\') && IPSLib::appIsSearchable( \'blog\', \'search\' )\">\n				<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'blog\'\">class=\'selected\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=blog\" base=\"public\"}\'>{IPSLib::getAppTitle( \'blog\' )}</a></li>\n			</if>\n			<if test=\"IPSLib::appIsInstalled(\'gallery\') && IPSLib::appIsSearchable( \'gallery\', \'search\' )\">\n				<li <if test=\"helpTab:|:$this->request[\'search_app\'] == \'gallery\'\">class=\'selected\'</if>><a href=\'{parse url=\"{$url_string}&amp;search_app=gallery\" base=\"public\"}\'>{IPSLib::getAppTitle( \'gallery\' )}</a></li>\n			</if>\n		</ul>\n	</div>\n	<if test=\"searchResultsTermsRemoved:|:is_array( $removed_search_terms ) && count( $removed_search_terms )\">\n		<div class=\'message error\'>{$this->lang->words[\'removed_search_terms\']} <strong>{parse expression=\"implode( \',\', $removed_search_terms )\"}</strong></div>\n	</if>\n	<if test=\"hasSearchResults:|:$total > 0 AND $search_term != \'\'\">\n		<!--<div class=\'message\'>\n			{$this->lang->words[\'your_search\']} <em><strong>{$search_term}</strong></em> {$this->lang->words[\'your_search_returned\']} \n		</div>-->\n	</if>\n	<if test=\"$pagination\">\n		<div class=\'controls\'>\n			<div class=\'buttons\'>\n				{$pagination}\n			</div>\n		</div>\n	</if>\n	\n	<if test=\"hasTotal:|:$total\">\n		$results\n	<else />\n		<div class=\'row no_messages\'>{$this->lang->words[\'no_results_found\']}<if test=\"noResultsTerm:|:$search_term\"> {$this->lang->words[\'no_results_found_for\']} \'{$search_term}\'</if>.</div>\n	</if>\n	\n	<if test=\"$pagination\">\n		<div class=\'controls\'>\n			<div class=\'buttons\'>\n				{$pagination}\n			</div>\n		</div>\n	</if>\n</div>', 'searchResultsWrapper', '$results, $sortDropDown, $sortIn, $pagination, $total, $showing, $search_term, $url_string, $current_key, $removed_search_terms=array(), $limited=0, $wasLimited=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('291', '0', 'skin_search', '<div class=\'result_info\'>\n	<h3>{$r[\'content_title\']}</h3>\n	<if test=\"showGenericContent:|:!$resultAsTitle\">\n	<p>\n		{$r[\'content\']}\n	</p>\n	</if>\n</div>\n<div class=\'result_details desc\'>\n	<ul>\n		<li>{parse date=\"$r[\'updated\']\" format=\"short\"}</li>\n		<li>{$this->lang->words[\'search_by\']} <a href=\'{parse url=\"showuser={$r[\'member_id\']}\" template=\"showuser\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\'>{$r[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$r[\'member_id\']\"}</li>\n	</ul>\n</div>', 'searchRowGenericFormat', '$r, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('292', '0', 'skin_search', '<div class=\'row\'>\n	<div class=\'icon\'>{parse replacement=\"{$r[\'_icon\']}\"}</div>\n	<a href=\'{parse url=\"showtopic={$r[\'type_id_2\']}&amp;view=<if test=\"isNewPost:|:$this->request[\'do\']==\'new_posts\' OR $this->request[\'do\']==\'active\'\">getnewpost<else /><if test=\"resultIsPost:|:$r[\'misc\']\">findpost&amp;p={$r[\'misc\']}</if></if>&amp;hl={$this->request[\'search_higlight\']}&amp;fromsearch=1\" seotitle=\"{$r[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'view_result\']}\'><strong>{$r[\'content_title\']}</strong></a>\n	\n	{$this->lang->words[\'in\']}\n	<foreach loop=\"topicsForumTrail:$r[\'_forum_trail\'] as $i => $f\">\n		<if test=\"notLastFtAsForum:|:$i+1 == count( $r[\'_forum_trail\'] )\"><a href=\'{parse url=\"{$f[1]}\" template=\"showforum\" seotitle=\"{$f[2]}\" base=\"public\"}\'>{$f[0]}</a></if>\n	</foreach>\n	\n	<if test=\"multipages:|:isset( $r[\'pages\'] ) AND is_array( $r[\'pages\'] ) AND count( $r[\'pages\'] )\">\n		<span class=\'mini_pagination\'>\n			<foreach loop=\"pages:$r[\'pages\'] as $page\">\n				<if test=\"haslastpage:|:$page[\'last\']\">\n					<a href=\"{parse url=\"showtopic={$r[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$r[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']} {$this->lang->words[\'_rarr\']}</a>\n				<else />\n					<a href=\"{parse url=\"showtopic={$r[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$r[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']}</a>\n				</if>\n			</foreach>\n		</span>\n	</if>\n	<br />\n	<span class=\'subtext\'>{parse expression=\"sprintf( $this->lang->words[\'sr_as_post_string\'], $this->registry->getClass(\'class_localization\')->getDate( $resultAsTitle ? $r[\'_last_post\'] : $r[\'_post_date\'], \'SHORT\' ), $r[\'members_display_name\'] )\"}</span>\n</div>', 'topicPostSearchResult', '$r, $indent, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('293', '0', 'skin_search', '<if test=\"whichWayToGo:|:$resultAsTitle\">\n	{parse template=\"asForumTopics\" group=\"search\" params=\"$data\"}\n<else />\n	{parse template=\"asForumPosts\" group=\"search\" params=\"$data\"}\n</if>', 'topicPostSearchResultAsForum', '$data, $resultAsTitle=false', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('294', '0', 'skin_search', '<ol>\n		{$content}\n	</ol>', 'topicPostSubresultWrap', '$content', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('295', '0', 'skin_search', '<php>\n	$datecut = ( $this->settings[\'search_ucontent_days\'] ) ? $this->registry->class_localization->getDate( time() - ( 86400 * intval( $this->settings[\'search_ucontent_days\'] ) ), \'joined\' ) : 0;\n</php>\n<div class=\'master_list\'>\n	<h2>{parse expression=\"sprintf( $this->lang->words[\'s_participation_title\'], $member[\'members_display_name\'] )\"}</h2>	\n	<if test=\"NPhasResults:|:$total\">\n		<p class=\'message\'>\n			{parse expression=\"sprintf( $this->lang->words[\'s_participation_msg\'], $total, $member[\'members_display_name\'] )\"}\n			<if test=\"$datecut\">\n				<br /><span class=\'desc\'>{parse expression=\"sprintf( $this->lang->words[\'s_participation_range\'], $datecut )\"}</span>\n			</if>\n		</p>\n		<div class=\'controls\'>\n			{$pagination}\n		</div>\n	</if>\n	\n	<if test=\"NPTotal:|:$total\">\n	{$results}\n<else />\n	<p class=\'row no_messages\'>{$this->lang->words[\'user_posts_none\']}</p>\n</if>\n<div class=\'topic_controls\'>\n	{$pagination}\n</div>', 'userPostsView', '$results, $pagination, $total, $member, $asForum, $limited=0, $wasLimited=false, $beginTime', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('296', '0', 'skin_stats', '<!-- This is looped over once for admins, once for supmods, and then once for forum mods -->\n<table class=\'ipb_table\'>\n	<caption class=\'maintitle\'>{$group}</caption>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 3%\'>&nbsp;</th>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'leader_name\']}</th>\n		<th scope=\'col\' style=\'width: 35%\' class=\'short\'>{$this->lang->words[\'leader_forums\']}</th>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'leader_location\']}</th>\n		<th scope=\'col\' style=\'width: 12%\'>&nbsp;</th>\n	</tr>\n	<if test=\"hasLeaders:|:count($members) AND is_array($members)\">\n		{parse striping=\"staff\" classes=\"row1,row2\"}\n		<foreach loop=\"members:$members as $info\">\n			<tr class=\'{parse striping=\"staff\"}\'>\n				<td>\n					<img src=\'{$info[\'pp_mini_photo\']}\' alt=\'photo\' class=\'photo\' width=\'{$info[\'pp_mini_width\']}\' height=\'{$info[\'pp_mini_height\']}\' />\n				</td>\n				<td>\n					<if test=\"leadermid:|:$info[\'member_id\'] > 0\">\n						<a href=\'{parse url=\"showuser={$info[\'member_id\']}\" seotitle=\"{$info[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$info[\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$info[\'member_id\'],$info[\'members_seo_name\']\"}\n					<else />\n						{$info[\'members_display_name\']}\n					</if>\n				</td>\n				<td class=\'altrow short\'>\n					<if test=\"specificForums:|:is_array($info[\'forums\'])\">\n						<form method=\"post\" action=\"{parse url=\"\" base=\"public\"}\" id=\"jmenu{$info[\'member_id\']}\" class=\'jump\'>\n							<select name=\"showforum\">\n								<option value=\"-1\">{parse expression=\"sprintf($this->lang->words[\'no_forums\'],count($info[\'forums\']))\"}</option>\n								<option value=\"-1\">---------------------------</option>\n								<foreach loop=\"forums:$info[\'forums\'] as $id => $name\">\n									<option value=\"{$id}\">{$name}</option>\n								</foreach>\n							</select>\n							<input type=\'submit\' class=\'input_submit alt\' value=\'{$this->lang->words[\'go_button\']}\' />\n						</form>\n					<else />\n						{$info[\'forums\']}\n					</if>\n				</td>\n				<td>\n					<if test=\"isonline:|:$info[\'_online\']\">\n						{$info[\'online_extra\']}\n					</if>\n				</td>\n				<td class=\'short altrow\'>\n					<ul class=\'user_controls clear\'>\n						<if test=\"isFriendable:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n							<if test=\"isFriend:|:IPSMember::checkFriendStatus( $info[\'member_id\'] )\">\n								<li class=\'mini_friend_toggle is_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n							<else />\n								<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n							</if>\n						</if>\n						<if test=\"canPm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n							<li class=\'pm_button\' id=\'pm_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\'>{parse replacement=\"send_msg\"}</a></li>\n						</if>\n						<if test=\"hasBlog:|:$info[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n							<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n						</if>\n						<if test=\"hasGallery:|:$info[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n							<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n						</if>\n					</ul>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<br />', 'group_strip', '$group=\"\", $members=array()', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('297', '0', 'skin_stats', '<table class=\'ipb_table\'>\n	<caption class=\'maintitle\'>{$this->lang->words[\'todays_posters\']}</caption>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 3%\'>&nbsp;</th>\n		<th scope=\'col\'>{$this->lang->words[\'member\']}</th>\n		<th scope=\'col\'>{$this->lang->words[\'member_joined\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_posts\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_today\']}</th>\n		<th scope=\'col\' class=\'short\'>{$this->lang->words[\'member_percent\']}</th>\n		<th scope=\'col\' class=\'short\'>&nbsp;</th>\n	</tr>\n	<if test=\"hasTopPosters:|:!is_array($rows) OR !count($rows)\">\n		<tr>\n			<td colspan=\'7\' class=\'no_messages\'>{$this->lang->words[\'no_info\']}</td>\n		</tr>\n	<else />\n		{parse striping=\"top_posters\" classes=\"row1,row2\"}\n		<foreach loop=\"topposters:$rows as $info\">\n			<tr class=\'{parse striping=\"top_posters\"}\'>\n				<td>\n					<img src=\'{$info[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$info[\'members_display_name\'])\"}\" class=\'photo\' width=\'{$info[\'pp_mini_width\']}\' height=\'{$info[\'pp_mini_height\']}\' />\n				</td>\n				<td>\n					<if test=\"topPosterMid:|:$info[\'member_id\'] > 0\">\n						<a href=\'{parse url=\"showuser={$info[\'member_id\']}\" seotitle=\"{$info[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$info[\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$info[\'member_id\'], $info[\'members_seo_name\']\"}\n					<else />\n						{$info[\'members_display_name\']}\n					</if>\n				</td>\n				<td class=\'altrow\'>\n					{parse date=\"$info[\'joined\']\" format=\"joined\"}\n				</td>\n				<td class=\'short\'>\n					{parse format_number=\"$info[\'posts\']\"}\n				</td>\n				<td class=\'altrow short\'>\n					{parse format_number=\"$info[\'tpost\']\"}\n				</td>\n				<td class=\'short\'>\n					{$info[\'today_pct\']}%\n				</td>\n				<td class=\'altrow short\'>\n					<ul class=\'user_controls clear\'>\n						<if test=\"tpIsFrindable:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n							<if test=\"tpIsFriend:|:IPSMember::checkFriendStatus( $info[\'member_id\'] )\">\n								<li class=\'mini_friend_toggle is_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n							<else />\n								<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$info[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n							</if>\n						</if>\n						<if test=\"tpPm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'member_id\'] != $info[\'member_id\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n							<li class=\'pm_button\' id=\'pm_xxx_{$info[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\'>{parse replacement=\"send_msg\"}</a></li>\n						</if>\n						<if test=\"tpBlog:|:$info[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n							<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n						</if>\n						<if test=\"tpGallery:|:$info[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n							<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$info[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n						</if>\n					</ul>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>', 'top_posters', '$rows', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('298', '0', 'skin_stats', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'who_farted\']} {$title}</h3>\n<else />\n	<h3 class=\'maintitle\'>{$this->lang->words[\'who_farted\']} {$title}</h3>\n</if>\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th>{$this->lang->words[\'whoposted_name\']}</th>\n		<th>{$this->lang->words[\'whoposted_posts\']}</th>\n	</tr>\n	<if test=\"hasPosters:|:count($rows) AND is_array($rows)\">\n		{parse striping=\"whoposted\" classes=\"row1,row2\"}\n		<foreach loop=\"whoposted:$rows as $row\">\n			<tr class=\'{parse striping=\"whoposted\"}\'>\n				<td class=\"altrow\">\n					<if test=\"posterHasMid:|:$row[\'author_id\']\">\n						<a href=\"{parse url=\"showuser={$row[\'author_id\']}\" template=\"showuser\" seotitle=\"{$row[\'members_seo_name\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'goto_profile\']}\">{$row[\'author_name\']}</a>\n					<else />\n						{$row[\'author_name\']}\n					</if>\n				</td>\n				<td>{$row[\'pcount\']}</td>\n			</tr>\n		</foreach>\n	</if>\n	</table>', 'whoPosted', '$tid=0, $title=\"\", $rows=array()', '1338050060', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('299', '0', 'skin_boards', '{parse js_module=\"board\"}\n{parse variable=\"sidebar_enabled\" default=\"$show_side_blocks\"}\n<if test=\"boardIndexTop:|:true\"></if>\n<div id=\'board_index\' class=\'ipsLayout <if test=\"sideBarEnabledL:|:$this->templateVars[\'sidebar_enabled\']\">ipsLayout_withright</if> ipsLayout_largeright clearfix <if test=\"sidebarclosed:|:IPSCookie::get(\'hide_sidebar\') == \'1\'\">no_sidebar</if>\'>	\n	<div id=\'categories\' class=\'ipsLayout_content clearfix\'>\n	<!-- CATS AND FORUMS -->\n		<if test=\"cats_forums:|:is_array( $cat_data ) AND count( $cat_data )\">\n			<foreach loop=\"categories:$cat_data as $_data\">\n				<if test=\"cat_has_forums:|:is_array( $_data[\'forum_data\'] ) AND count( $_data[\'forum_data\'] )\">\n					<div id=\'category_{$_data[\'cat_data\'][\'id\']}\' class=\'category_block block_wrap\'>\n						<h3 class=\'maintitle\'>\n							<a class=\'toggle right\' href=\'#\' title=\"{$this->lang->words[\'toggle_cat\']}\">{$this->lang->words[\'toggle_cat\']}</a> <a href=\"{parse url=\"showforum={$_data[\'cat_data\'][\'id\']}\" seotitle=\"{$_data[\'cat_data\'][\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'view_cat\']}\'>{$_data[\'cat_data\'][\'name\']}</a>\n						</h3>\n						<div class=\'ipsBox table_wrap\'>\n							<div class=\'ipsBox_container\'>\n								<table class=\'ipb_table\' summary=\"{$this->lang->words[\'forums_in_cat\']} \'{$_data[\'cat_data\'][\'name\']}\'\">\n									<tr class=\'header hide\'>\n										<th scope=\'col\' class=\'col_c_icon\'>&nbsp;</th>\n										<th scope=\'col\' class=\'col_c_forum\'>{$this->lang->words[\'cat_name\']}</th>\n										<th scope=\'col\' class=\'col_c_stats stats\'>{$this->lang->words[\'stats\']}</th>\n										<th scope=\'col\' class=\'col_c_post\'>{$this->lang->words[\'last_post_info\']}</th>\n									</tr>\n									<!-- / CAT HEADER -->\n									<foreach loop=\"forums:$_data[\'forum_data\'] as $forum_id => $forum_data\">\n										<if test=\"forumRedirect:|:$forum_data[\'redirect_on\']\">\n											<tr class=\'redirect_forum\' id=\'f_{$forum_data[\'id\']}\'>\n												<td class=\'col_c_icon\'>\n													<img src=\'{$this->settings[\'img_url\']}/f_redirect.png\' />\n												</td>\n												<td colspan=\'2\' class=\'col_c_forum\'>\n													<h4><a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$forum_data[\'name\']}</a></h4>\n													<p class=\'desc\'>{$forum_data[\'description\']}</p>\n												</td>\n												<td class=\'desc\'>\n													<ul class=\'last_post ipsType_small\'>\n														<li class=\'desc lighter\'><em>{parse format_number=\"$forum_data[\'redirect_hits\']\"} {$this->lang->words[\'rd_hits\']}</em></li>\n													</ul>\n												</td>\n											</tr>\n										<else />\n											<tr class=\'<if test=\"hasUnreadClass:|:$forum_data[\'_has_unread\']\">unread</if>\'>\n												<td class=\'col_c_icon\'>\n													<if test=\"hasUnread:|:$forum_data[\'_has_unread\']\">\n														<a id=\'forum_img_{$forum_data[\'id\']}\' href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$this->request[\'f\']}&amp;i=1\" base=\"public\"}\" data-tooltip=\"{$this->lang->words[\'bi_markread\']}\" class=\'forum_marker\'><img src=\'{$this->settings[\'img_url\']}/f_icon.png\' /></a>\n													<else />\n														<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\n													</if>\n												</td>\n												<td class=\'col_c_forum\'>\n													\n													<h4>\n														<if test=\"hasQueuedAndCanSeeIcon:|:!empty($forum_data[\'_has_queued_and_can_see_icon\'])\">\n															<a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;modfilter=all\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\' title=\'{$this->lang->words[\'view_unapproved\']}\' class=\'ipsBadge ipsBadge_orange\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'f_queued\'], $forum_data[\'queued_topics\'], $forum_data[\'queued_posts\'])\"}\" style=\'vertical-align: top\'>{$this->lang->words[\'f_queued_badge\']}</a>\n														</if>\n														<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$forum_data[\'name\']}</a>\n													</h4>\n														\n													<if test=\"showSubForums:|:$forum_data[\'show_subforums\'] AND count( $forum_data[\'subforums\'] ) AND $forum_data[\'show_subforums\']\">\n														<br />\n														<ol class=\'ipsList_inline ipsType_small subforums\' id=\'subforums_{$forum_data[\'id\']}\'>\n															<foreach loop=\"subforums:$forum_data[\'subforums\'] as $__id => $__data\">\n																<if test=\"showSubForumsLit:|:$__data[3]\"><li class=\'unread\'><else /><li></if>\n																	<a href=\"{parse url=\"showforum={$__data[0]}\" seotitle=\"{$__data[2]}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$__data[1]}</a><if test=\"isNotLast:|: empty($__data[4] )\">,</if>\n																</li>\n															</foreach>\n														</ol>\n													</if>\n																					\n													<p class=\'desc __forum_desc ipsType_small\'>{$forum_data[\'description\']}</p>											\n												</td>\n												<td class=\'col_c_stats ipsType_small\'>\n													<ul>\n														<li><strong>{$forum_data[\'topics\']}</strong> {$this->lang->words[\'topics\']}</li>\n														<li><strong>{$forum_data[\'posts\']}</strong> {$this->lang->words[\'replies\']}</li>\n													</ul>\n												</td>\n												<td class=\'col_c_post\'>\n													<if test=\"hideLastInfo:|:$forum_data[\'hide_last_info\']\">\n														<ul class=\'last_post ipsType_small\'>\n															<li class=\'desc lighter\'><em>{$this->lang->words[\'f_protected\']}</em></li>\n														</ul>\n													<else />\n														<if test=\"hasphoto:|:$forum_data[\'pp_small_photo\']\">\n															<a href=\'{parse url=\"showuser={$forum_data[\'last_poster_id\']}\" template=\"showuser\" seotitle=\"{$forum_data[\'seo_last_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n																<img src=\'{$forum_data[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n															</a>\n														<else />\n															<if test=\"hasPost:|:$forum_data[\'last_id\']\">\n																<div class=\'left\'>{IPSMember::buildNoPhoto(0, \'mini\' )}</div>\n															</if>\n														</if>\n														<ul class=\'last_post ipsType_small\'>\n															<if test=\"!$forum_data[\'last_id\']\">\n																<li class=\'desc lighter\'><em>{$this->lang->words[\'f_none\']}</em></li>\n															<else />\n																<li>\n																	{$forum_data[\'last_topic_title\']}\n																</li>\n																<if test=\"lastPosterID:|:$forum_data[\'last_poster_id\']\">\n																	<li>{$this->lang->words[\'by\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$forum_data\"}</li>\n																</if>\n																<if test=\"hideDateUrl:|:$forum_data[\'_hide_last_date\']\">\n																	<li class=\'desc lighter blend_links\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</li>\n																<else />\n																	<li class=\'desc lighter blend_links\'><a href=\'{parse url=\"showtopic={$forum_data[\'last_id\']}&amp;view=getlastpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$forum_data[\'seo_last_title\']}\"}\' title=\'{$this->lang->words[\'view_last_post\']}\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</a></li>\n																</if>\n														\n															</if>\n															\n														</ul>\n													</if>\n												</td>\n											</tr>\n										</if>\n									</foreach>\n								</table>\n							</div>\n						</div>\n						<br />\n					</div>\n				</if>\n			</foreach>\n		</if>\n	</div>\n	<if test=\"sideBarEnabled2:|:$this->templateVars[\'sidebar_enabled\']\">\n		<div id=\'index_stats\' class=\'ipsLayout_right clearfix\' <if test=\"sidebarclosed2:|:IPSCookie::get(\'hide_sidebar\') == \'1\'\">style=\'display: none\'</if>>\n			<foreach loop=\"side_blocks:$side_blocks as $block\">\n				{$block}\n			</foreach>\n		</div>\n		<a href=\'#\' id=\'toggle_sidebar\' title=\'{$this->lang->words[\'toggle_sidebar\']}\' data-closed=\"{$this->lang->words[\'_laquo\']}\" data-open=\"&times;\">&nbsp;</a>\n	</if>\n</div>\n<script type=\'text/javascript\'>\n//<![CDATA[\n	var markerURL  = \"{parse url=\"app=forums&module=ajax&section=markasread&i=1\" base=\"public\"}\"; // Ajax URL so don\'t use &amp;\n	var unreadIcon = \"<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\";\n	\n	<if test=\"markercatforums:|:is_array( $cat_data ) AND count( $cat_data )\">\n		<foreach loop=\"markercategories:$cat_data as $_data\">\n			<if test=\"markerhasforums:|:is_array( $_data[\'forum_data\'] ) AND count( $_data[\'forum_data\'] )\">\n				<foreach loop=\"markerforums:$_data[\'forum_data\'] as $forum_id => $forum_data\">\n					<if test=\"markernotredirect:|:!$forum_data[\'redirect_on\']\">\n						<if test=\"markerhasunread:|:$forum_data[\'_has_unread\']\">\n	ipb.global.registerMarker( \"forum_img_{$forum_data[\'id\']}\", \"{$forum_data[\'img_new_post\']}\", markerURL + \"&forumid={$forum_data[\'id\']}\" );\n						</if>\n					</if>\n				</foreach>\n			</if>\n		</foreach>\n	</if>\n//]]>\n</script>\n<if test=\"showTotals:|:$this->settings[\'show_totals\']\">\n	<div id=\'board_stats\'>		\n		<ul class=\'ipsType_small ipsList_inline\'>\n			<li class=\'clear\'>\n				<span class=\'value\'>{$stats[\'info\'][\'total_posts\']}</span>\n				{$this->lang->words[\'total_posts\']}\n			</li>\n			<li class=\'clear\'>\n				<span class=\'value\'>{$stats[\'info\'][\'mem_count\']}</span>\n				{$this->lang->words[\'total_members\']}\n			</li>\n			<li class=\'clear\'>\n				{IPSMember::makeProfileLink( $stats[\'info\'][\'last_mem_name\'], $stats[\'info\'][\'last_mem_id\'], $stats[\'info\'][\'last_mem_seo\'], \'value\' )}\n				{$this->lang->words[\'newest_member\']}\n			</li>\n			<li class=\'clear\' data-tooltip=\"{$stats[\'info\'][\'most_time\']}\">\n				<span class=\'value\'>{$stats[\'info\'][\'most_online\']}</span>\n				{$this->lang->words[\'online_at_once\']}\n			</li>\n		</ul>\n	</div>\n</if>\n<div id=\'board_statistics\' class=\'statistics clearfix\'>\n	<ul id=\'stat_links\' class=\'ipsList_inline right ipsType_small\'>\n		<if test=\"statsLinks:|:1==1\"> <!-- Hook point -->\n			<li><a href=\"{parse url=\"app=forums&amp;module=extras&amp;section=stats&amp;do=leaders\" base=\"public\"}\" title=\"{$this->lang->words[\'sm_forum_leaders_title\']}\">{$this->lang->words[\'sm_forum_leaders\']}</a></li>\n			<li><a href=\"{parse url=\"app=forums&amp;module=extras&amp;section=stats\" base=\"public\"}\" title=\"{$this->lang->words[\'sm_all_posters_title\']}\">{$this->lang->words[\'sm_today_posters\']}</a></li>\n			<li><a href=\"{parse url=\"app=members&amp;module=list&amp;max_results=20&amp;sort_key=posts&amp;sort_order=desc&amp;filter=ALL\" base=\"public\" seotitle=\"false\"}\" title=\"{$this->lang->words[\'sm_overall_posters_title\']}\">{$this->lang->words[\'sm_overall_posters\']}</a></li>\n		</if>\n	</ul>\n	\n	<if test=\"$this->settings[\'show_active\']\">\n		<h4 class=\'statistics_head\'>{parse expression=\"sprintf( $this->lang->words[\'online_right_now\'], $stats[\'TOTAL\'] )\"} {$this->lang->words[\'active_users\']}</h4>\n		<p class=\'statistics_brief desc\'>\n			{parse expression=\"sprintf( $this->lang->words[\'active_users_detail\'], $stats[\'MEMBERS\'], $stats[\'GUESTS\'], $stats[\'ANON\'] )\"}\n			&nbsp;&nbsp;<a href=\'{parse url=\"app=members&amp;module=online&amp;sort_order=desc\" base=\"public\"}\'>({$this->lang->words[\'online_link\']})</a>\n		</p>\n	</if>\n	<if test=\"activeNames:|:count($stats[\'NAMES\']) && $this->settings[\'show_active\']\">\n		<br />\n		<p>\n			<span class=\'name\'>{parse expression=\"implode( \",</span> <span class=\'name\'>\", $stats[\'NAMES\'] )\"}</span>					\n		</p>\n	</if>\n</div>', 'boardIndexTemplate', '$lastvisit=\"\", $stats=array(), $cat_data=array(), $show_side_blocks=true, $side_blocks=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('300', '0', 'skin_boards', '<div class=\'general_box alt clearfix\' id=\'hook_watched_items\'>\n		<h3><img src=\'{$this->settings[\'img_url\']}/comment_new.png\' alt=\'\' /> {$this->lang->words[\'slh_title\']}</h3>\n		<div class=\'recent_activity _sbcollapsable\'>\n			<ol class=\'tab_bar no_title mini\'>\n				<li id=\'tab_link_most\' class=\'tab_toggle active clickable\'>{$this->lang->words[\'slh_mostly\']}</li>\n				<li id=\'tab_link_recent\' class=\'tab_toggle clickable\'>{$this->lang->words[\'slh_recently\']}</li>\n			</ol>\n			<div id=\'tab_content_most\' class=\'tab_toggle_content\'>\n				<if test=\"mostShared:|:is_array( $data[\'mostitems\'] ) && count( $data[\'mostitems\'] )\">\n					<ul class=\'clearfix\'>\n						{parse striping=\"recent_topics\" classes=\"row1,row2 altrow\"}\n						<foreach loop=\"mostitems:$data[\'mostitems\'] as $item\">\n							<li class=\'{parse striping=\"recent_topics\"}\'>\n								<img src=\"{$this->settings[\'img_url\']}/{$item[\'icon\']}\" alt=\"\" />\n								<span class=\'desc\'>[{$item[\'count\']}]</span>\n								<a href=\'{$item[\'url\']}\'>{$item[\'title\']}</a>\n							</li>\n						</foreach>\n					</ul>\n				<else />\n					<ul class=\'clearfix\'>\n						<if test=\"updatedforumsn:|:!is_array( $data[\'mostitems\'] ) OR !count( $data[\'mostitems\'] )\">\n							<li class=\'{parse striping=\"recent_topics\"}\'>{$this->lang->words[\'slh_nothingtoshow\']}</li>\n						</if>\n					</ul>\n				</if>\n			</div>\n			\n			<div id=\'tab_content_recent\' class=\'tab_toggle_content\' style=\'display:none;\'>\n				<if test=\"mostShared:|:is_array( $data[\'mostrecent\'] ) && count( $data[\'mostrecent\'] )\">\n					<ul class=\'clearfix\'>\n						{parse striping=\"recent_topics\" classes=\"row1,row2 altrow\"}\n						<foreach loop=\"mostitems:$data[\'mostrecent\'] as $item\">\n							<li class=\'{parse striping=\"recent_topics\"}\'>\n								<img src=\"{$this->settings[\'img_url\']}/{$item[\'icon\']}\" alt=\"\" />\n								<a href=\'{$item[\'url\']}\'>{$item[\'title\']}</a>\n							</li>\n						</foreach>\n					</ul>\n				<else />\n					<ul class=\'clearfix\'>\n						<if test=\"updatedforumsn:|:!is_array( $data[\'mostitems\'] ) OR !count( $data[\'mostitems\'] )\">\n							<li class=\'{parse striping=\"recent_topics\"}\'>{$this->lang->words[\'slh_nothingtoshow\']}</li>\n						</if>\n					</ul>\n				</if>\n			</div>\n		</div>\n	</div>', 'hookBoardIndexShareLinks', '$data', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('301', '0', 'skin_boards', '<script type=\'text/javascript\' src=\"{$this->settings[\'public_dir\']}js/ips.status.js\"></script>\n<div class=\'ipsSideBlock clearfix\' id=\'statusHook\'>\n	<h3>{$this->lang->words[\'recent_status_updates\']}</h3>\n	<div class=\'_sbcollapsable\'>\n		<div id=\"status_wrapper\">\n			<div id=\"status_wrapper_inside\">{parse template=\"statusUpdates\" group=\"boards\" params=\"$updates, 1, 1\"}</div>\n			<div class=\"status_main_content ipsType_small\" style=\'text-align: center\'>\n				<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=all\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\'>{$this->lang->words[\'viewallupdates\']}</a>\n			</div>\n		</div>\n	</div>\n</div>', 'hookBoardIndexStatusUpdates', '$updates=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('302', '0', 'skin_boards', '<if test=\"fbAppIdPresent:|:IPSLib::fbc_enabled()\">\n<div class=\'general_box clearfix\'>\n	<h3>{$this->lang->words[\'hook_facebookactivity\']}</h3>\n	<div  class=\'block_list clearfix _sbcollapsable\' style=\'text-align:center\'>\n		<div><fb:activity site=\"\" width=\"290\" height=\"300\" header=\"false\" border_color=\"#FFF\" colorscheme=\"light\" /></div>\n	</div>\n</div><div id=\"fb-root\"></div>\n<script>\n  window.fbAsyncInit = function() {\n    FB.init({appId: \'{$this->settings[\'fbc_appid\']}\', status: true, cookie: true,\n             xfbml: true});\n  };\n  (function() {\n    var e = document.createElement(\'script\'); e.async = true;\n    e.src = document.location.protocol +\n      \'//connect.facebook.net/{$this->settings[\'fb_locale\']}/all.js\';\n    document.getElementById(\'fb-root\').appendChild(e);\n  }());\n</script>\n</if>', 'hookFacebookActivity', '', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('303', '0', 'skin_boards', '<if test=\"recenttopics:|:is_array( $topics ) && count( $topics )\">\n<div class=\'ipsSideBlock clearfix\'>\n	<h3>{$this->lang->words[\'recently_added_topics\']}</h3>\n	<div class=\'_sbcollapsable\'>\n		<ul class=\'ipsList_withminiphoto\'>\n		<foreach loop=\"topics_hook:$topics as $r\">\n		<li class=\'clearfix\'>\n			<if test=\"$r[\'member_id\']\">\n				<a href=\'{parse url=\"showuser={$r[\'member_id\']}\" seotitle=\"{$r[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink\'>\n			</if>\n			<img src=\'{$r[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$r[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini left\' />\n			<if test=\"$r[\'member_id\']\">\n				</a>\n			</if>\n			<div class=\'list_content\'>\n				<a href=\'{parse url=\"showtopic={$r[\'tid\']}\" base=\"public\" template=\"showtopic\" seotitle=\"{$r[\'title_seo\']}\"}\' rel=\'bookmark\' class=\'ipsType_small\' title=\'{$this->lang->words[\'view_topic\']}\'>{$r[\'topic_title\']}</a>\n				<p class=\'desc ipsType_smaller\'>\n					<if test=\"$r[\'members_display_name\']\">{parse template=\"userHoverCard\" group=\"global\" params=\"$r\"}<else />{$this->settings[\'guest_name_pre\']}{$r[\'starter_name\']}{$this->settings[\'guest_name_suf\']}</if>\n					- {parse date=\"$r[\'start_date\']\" format=\"short\"}\n				</p>\n			</div>\n		</li>\n		</foreach>\n		</ul>\n	</div>\n</div>\n</if>', 'hookRecentTopics', '$topics', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('304', '0', 'skin_boards', '<div class=\'ipsSideBlock clearfix\'>\n	<h3>{$this->lang->words[\'popular_tags\']}</h3>\n	<div class=\'_sbcollapsable\'>\n		<ul class=\'ipsList_inline\'>\n		<foreach loop=\"eachTag:$tags[\'tags\'] as $id => $data\">\n			<li><span class=\"{$data[\'className\']}\">{$data[\'tagWithUrl\']}</span></li>\n		</foreach>\n		</ul>\n	</div>\n</div>', 'hookTagCloud', '$tags', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('305', '0', 'skin_boards', '<foreach loop=\"innerLoop:$replies as $reply\">\n	<div id=\'statusReply-{$reply[\'reply_id\']}\' class=\'ipsPad_half\'>\n		<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$reply[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$reply[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_tiny\' /></a>\n		<div class=\'list_content\'>\n			<div class=\'right lighter\'>\n				<span class=\'desc ipsType_smaller\'>{parse date=\"$reply[\'reply_date\']\" format=\"manual{%d %b}\" relative=\"true\"}&nbsp;&nbsp;</span>\n				<span class=\'desc mod_links ipsType_smaller\'>\n					<if test=\"canDelete:|:$reply[\'_canDelete\']\"><a href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=deleteReply&amp;status_id={$reply[\'reply_status_id\']}&amp;reply_id={$reply[\'reply_id\']}&amp;k={$this->member->form_hash}\" id=\"statusReplyDelete-{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\" class=\"__sDR __dr{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\">{$this->lang->words[\'status_delete_link\']}</a></if>\n				</span>\n			</div>\n			<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' style=\'font-weight:bold\'>{$reply[\'members_display_name\']}</a>\n			<p class=\'index_status_update ipsType_small\'>{$reply[\'reply_content\']}</p>\n		</div>\n	</div>\n</foreach>', 'statusReplies', '$replies=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('306', '0', 'skin_boards', '{parse js_module=\"status\"}\n<script type=\"text/javascript\">\n	ipb.status.maxReplies = {parse expression=\"intval($this->settings[\'su_max_replies\'])\"};\n	ipb.status.smallSpace = {parse expression=\"intval($smallSpace)\"};\n	ipb.status.skin_group = \'boards\';\n</script>\n<foreach loop=\"outerLoop:$updates as $id => $status\">\n	<if test=\"$this->memberData[\'member_id\'] AND $latestOnly AND $status[\'member_id\'] == $this->memberData[\'member_id\']\">\n		<script type=\"text/javascript\">\n			ipb.status.myLatest = {$status[\'status_id\']};\n		</script>\n	</if>\n	<ul class=\'ipsList_withminiphoto status_list\' id=\'statusWrap-{$status[\'status_id\']}\'>\n		<li class=\'clearfix\'>\n			<a href=\'{parse url=\"showuser={$status[\'member_id\']}\" seotitle=\"{$status[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$status[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$status[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini\' /></a>\n			<div class=\'list_content\'>\n				<div id=\"statusContent-{$status[\'status_id\']}\">\n					<div class=\'right desc lighter\'>\n						<span class=\'desc mod_links ipsType_smaller\'>						\n							<if test=\"canDelete:|:$status[\'_canDelete\']\"><a rel=\"nofollow\" href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=deleteStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusDelete-{$status[\'status_id\']}\" class=\"__sD __d{$status[\'status_id\']}\">{$this->lang->words[\'status_delete_link\']}</a></if>\n							<span id=\'statusUnlock-{$status[\'status_id\']}\' <if test=\"isLocked:|:$status[\'_isLocked\'] AND $status[\'_canUnlock\']\">style=\'display:inline\'<else />style=\'display:none\'</if>> &middot; <a rel=\"nofollow\"  href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=unlockStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusUnlockLink-{$status[\'status_id\']}\" class=\"__sU __u{$status[\'status_id\']}\">{$this->lang->words[\'status_unlock_link\']}</a></span>\n							<span id=\'statusLock-{$status[\'status_id\']}\' <if test=\"canLock:|:$status[\'_canLock\'] AND ! $status[\'_isLocked\']\">style=\'display:inline\'<else />style=\'display:none\'</if>> &middot; <a rel=\"nofollow\"  href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=lockStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusLockLink-{$status[\'status_id\']}\" class=\"__sL __l{$status[\'status_id\']}\">{$this->lang->words[\'status_lock_link\']}</a></span>\n						</span>\n						&nbsp;&nbsp;<span class=\'ipsType_smaller blend_links\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$status[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{parse date=\"$status[\'status_date\']\" format=\"manual{%d %b}\" relative=\"true\"}</a></span>\n					</div>\n					{parse template=\"userHoverCard\" group=\"global\" params=\"$status\"}\n					<p class=\'index_status_update ipsType_small\'>{$status[\'status_content\']}</p>\n					<span class=\'desc\' id=\'statusToggle-{$status[\'status_id\']}\'>\n						<if test=\"$status[\'_userCanReply\']\">\n							<if test=\"$status[\'status_replies\']\">\n								<a href=\"#\" class=\"__sT __t{$status[\'status_id\']} ipsType_smaller \">{parse expression=\"sprintf( $this->lang->words[\'view_comments_and_add\'], $status[\'status_replies\'])\"}</a>\n							<else />\n								<a href=\"#\" class=\"__sT __t{$status[\'status_id\']} ipsType_smaller\">{$this->lang->words[\'add_comments_only\']}</a>\n							</if>\n						<else />\n							<if test=\"$status[\'status_replies\']\">\n								<a href=\"#\" class=\"__sT __t{$status[\'status_id\']} ipsType_smaller\">{parse expression=\"sprintf( $this->lang->words[\'view_comments_only\'], $status[\'status_replies\'])\"}</a>\n							</if>\n						</if>\n						<img src=\"{$this->settings[\'img_url\']}/icon_lock.png\" id=\'statusLockImg-{$status[\'status_id\']}\' alt=\"{$this->lang->words[\'status__locked\']}\" style=\'display: none\' />\n						<if test=\"cImg:|:! $smallSpace AND $status[\'_creatorImg\']\"><img src=\"{$status[\'_creatorImg\']}\" alt=\'\' data-tooltip=\"{$this->lang->words[\'su_via\']} {$status[\'_creatorText\']}\" /></if>\n					</span>\n					<span class=\'desc\' id=\'statusToggleOff-{$status[\'status_id\']}\' style=\'display:none\'>\n						<a href=\"#\" class=\"__sTO __to{$status[\'status_id\']}\">{$this->lang->words[\'view_comments_collapse\']}</a>\n					</span>\n				</div>\n			</div>\n			<div id=\"statusFeedback-{$status[\'status_id\']}\" class=\'status_feedback\' style=\'display:none\'>\n				<div class=\'ipsList_withtinyphoto status_list\' id=\'statusReplies-{$status[\'status_id\']}\'>\n					<if test=\"$status[\'status_replies\'] AND count( $status[\'replies\'] )\">\n						<if test=\"hasMore:|:$status[\'status_replies\'] > 3\">\n							<div class=\'status_mini_wrap row2 altrow\' id=\'statusMoreWrap-{$status[\'status_id\']}\'>\n								<img src=\"{$this->settings[\'img_url\']}/comments.png\" alt=\"\" /> &nbsp;<a href=\"#\" id=\"statusMore-{$status[\'status_id\']}\" class=\'__showAll __x{$status[\'status_id\']}\'>{parse expression=\"sprintf( $this->lang->words[\'status_show_all_x\'], $status[\'status_replies\'] )\"}</a>\n							</div>\n						</if>\n						{parse template=\"statusReplies\" group=\"boards\" params=\"$status[\'replies\']\"}\n					</if>\n					<div id=\'statusReplyBlank-{$status[\'status_id\']}\' style=\'display: none\'></div>\n				</div>\n				<if test=\"$status[\'_userCanReply\']\">\n					<div class=\'ipsList_withtinyphoto status_list status_reply clearfix ipsPad_half\' id=\'statusReply-{$status[\'status_id\']}\'>\n						<img src=\'{$this->memberData[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$this->memberData[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_tiny left\' />\n						<div class=\'list_content\'>\n							<form id=\'statusReplyForm-{$status[\'status_id\']}\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=reply&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}\' method=\'post\'>\n								<textarea class=\'status_textarea\' rows=\'3\' cols=\'50\' name=\'comment-{$status[\'status_id\']}\' id=\'statusText-{$status[\'status_id\']}\'></textarea>\n								<div class=\"status_submit\"><input type=\'submit\' class=\'__submit input_submit\' id=\'statusSubmit-{$status[\'status_id\']}\' value=\'{$this->lang->words[\'status__dfcomment\']}\' /></div>\n							</form>\n							<a href=\'#\' class=\'__showform\' id=\'statusReplyFormShow-{$status[\'status_id\']}\' style=\'display: none\'>{$this->lang->words[\'status__addcomment\']}</a>\n						</div>\n					</div>\n					<script type=\'text/javascript\'>\n						if( $(\'statusReplyForm-{$status[\'status_id\']}\') ){\n							$(\'statusReplyForm-{$status[\'status_id\']}\').hide();\n						}\n						if( $(\'statusReplyFormShow-{$status[\'status_id\']}\') ){\n							$(\'statusReplyFormShow-{$status[\'status_id\']}\').show();\n						}\n					</script>\n				</if>\n			</div>\n		</li>\n	</ul>\n</foreach>', 'statusUpdates', '$updates=array(), $smallSpace=0, $latestOnly=0', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('307', '0', 'skin_boards', '<br />\n		<h4 class=\'statistics_head\'>{$this->lang->words[\'whoschatting_total\']} {$this->lang->words[\'whoschatting_loadchat\']}</h4>\n		<p>{$this->lang->words[\'whoschatting_none\']}</p>', 'whoschatting_empty', '', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('308', '0', 'skin_boards', '<br /><br />\n		<h4 class=\'statistics_head\'>{$total} {$this->lang->words[\'whoschatting_total\']} {$this->lang->words[\'whoschatting_loadchat\']}</h4>\n		<br />\n		<p>\n			<span class=\'name\'>{parse expression=\"implode( \",</span> <span class=\'name\'>\", $names )\"}</span>\n		</p>', 'whoschatting_show', '$total=\"\",$names=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('309', '0', 'skin_forum', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'attach_page_title\']}: $title</h3>\n	<if test=\"$pages\">\n		<div class=\'topic_controls\' style=\'padding-top: 4px;\'>{$pages}</div>\n	</if>\n<else />\n	<if test=\"$pages\">\n		<div class=\'topic_controls\'>{$pages}</div>\n	</if>\n	<h3 class=\'maintitle\'>{$this->lang->words[\'attach_page_title\']}: $title</h3>\n</if>\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th>&nbsp;</th>\n		<th>{$this->lang->words[\'attach_title\']}</th>\n		<th>{$this->lang->words[\'attach_size\']}</th>\n		<th>{$this->lang->words[\'attach_post\']}</th>\n	</tr>\n	{parse striping=\"attachies\" classes=\"row1,row2\"}\n	<if test=\"count($rows)\">\n		<foreach loop=\"attachments:$rows as $data\">\n			<tr class=\'{parse striping=\"attachies\"}\' id=\"{$data[\'attach_id\']}\">\n				<td class=\"altrow short\">\n					<img src=\"{$this->settings[\'mime_img\']}/{$data[\'image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" />\n				</td>\n				<td>\n					<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module=post&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\">{$data[\'short_name\']}</a><br />\n					<span class=\"desc\">( {$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']} )<br />( {$this->lang->words[\'attach_post_date\']} {$data[\'attach_date\']} )</span>\n				</td>\n				<td class=\"altrow short\">{$data[\'real_size\']}</td>\n				<td class=\'short\'><a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=findpost&amp;pid={$data[\'pid\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'view_post\']}\">{$data[\'pid\']}</a></td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<if test=\"$pages\">\n	<br />\n	<div class=\'topic_controls\'>{$pages}</div>\n</if>', 'forumAttachments', '$title, $rows, $pages', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('310', '0', 'skin_forum', '{parse js_module=\"forums\"}\n<script type=\"text/javascript\">\n//<![CDATA[\n	//Search Setup\n	ipb.vars[\'search_type\']		= \'forum\';\n	ipb.vars[\'search_type_id\']	= {$this->request[\'showforum\']};\n	ipb.templates[\'topic_rename\'] = new Template(\"<input type=\'text\' id=\'#{inputid}\' value=\'#{value}\' class=\'input_text\' size=\'50\' maxlength=\'{$this->settings[\'topic_title_max_len\']}\' /> <input type=\'submit\' value=\'{$this->lang->words[\'rename_topic_update\']}\' class=\'input_submit\' id=\'#{submitid}\' /> <a href=\'#\' id=\'#{cancelid}\' class=\'cancel\' title=\'{$this->lang->words[\'cancel\']}\'>{$this->lang->words[\'cancel\']}</a>\");\n	var markerURL  = \"{parse url=\"app=forums&module=ajax&section=markasread&i=1\" base=\"public\"}\"; // Ajax URL so don\'t use &amp;\n	var unreadIcon = \"<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\";\n//]]>\n</script>\n<if test=\"watchismember:|:$this->memberData[\'member_id\']\">\n	<if test=\"hasFollowData:|:$other_data[\'follow_data\']\">\n		{$other_data[\'follow_data\']}\n	</if>\n</if>\n<h1 class=\'ipsType_pagetitle\'>{$forum_data[\'name\']}</h1>\n<div class=\'ipsType_pagedesc forum_rules\'>\n	<if test=\"rules:|:$forum_data[\'show_rules\']\">\n		<if test=\"rulesinline:|:$forum_data[\'show_rules\'] == 2\">\n			<strong>{$forum_data[\'rules_title\']}</strong>\n			{$forum_data[\'rules_text\']}\n		</if>\n		<if test=\"ruleslink:|:$forum_data[\'show_rules\'] == 1\">\n			<a href=\'{parse url=\"app=forums&amp;module=forums&amp;section=rules&amp;f={$forum_data[\'id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_forum_rules\']}\'>{$forum_data[\'rules_title\']}</a>\n		</if>\n	<else />\n		{$forum_data[\'description\']}\n	</if>\n</div>\n<br />\n<if test=\"hasannouncements:|:is_array( $announce_data ) AND count( $announce_data )\">\n	<table class=\'ipb_table topic_list hover_rows\' summary=\'{$this->lang->words[\'forum_topic_list\']} \"{$forum_data[\'name\']}\"\' id=\'announcements\'>\n		<foreach loop=\"announcements:$announce_data as $aid => $adata\">\n			<tr class=\'row2 announcement\' id=\'arow_{$adata[\'announce_id\']}\'>\n				<td>\n					<php>$_seoTitle	= $adata[\'announce_seo_title\'] ? $adata[\'announce_seo_title\'] : \"%%{$adata[\'announce_title\']}%%\";</php>\n					{parse replacement=\"t_announcement\"}\n					<h4>\n						<a href=\"{parse url=\"showannouncement={$adata[\'announce_id\']}&amp;f={$forum_data[\'id\']}\" seotitle=\"{$_seoTitle}\" template=\"showannouncement\" base=\"public\"}\" title=\'{$this->lang->words[\'view_announcement\']}\'>{$adata[\'announce_title\']}</a>\n					</h4>&nbsp;\n					<span class=\'desc\'>{$this->lang->words[\'posted_by\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$adata\"}\n						<if test=\"announcedates:|:$adata[\'announce_start\'] AND $adata[\'announce_start\'] != \'--\'\">, {$adata[\'announce_start\']}</if>\n					</span>\n				</td>\n			</tr>\n		</foreach>\n	</table>\n	<br />	\n</if>\n<!-- __-SUBFORUMS-__ -->\n<if test=\"hassubforums:|:is_array( $sub_forum_data ) AND count( $sub_forum_data )\">\n	<div class=\'category_block block_wrap\'>\n		<h3 class=\'maintitle\'>{$this->lang->words[\'sub_forum_title\']}</h3>\n		<div class=\'ipsBox table_wrap\'>\n			<div class=\'ipsBox_container\'>\n				<table class=\'ipb_table\' summary=\"{$this->lang->words[\'cat_subforums\']} \'{$forum_data[\'name\']}\'\">\n					<foreach loop=\"subforums:$sub_forum_data as $_data\">\n						<if test=\"subforumdata:|:is_array( $_data[\'forum_data\'] ) AND count( $_data[\'forum_data\'] )\">\n							<foreach loop=\"forums:$_data[\'forum_data\'] as $forum_id => $forum_data\">\n								<if test=\"forumRedirect:|:$forum_data[\'redirect_on\']\">\n									<tr class=\'redirect_forum\' id=\'f_{$forum_data[\'id\']}\'>\n										<td class=\'col_c_icon\'>\n											<img src=\'{$this->settings[\'img_url\']}/f_redirect.png\' />\n										</td>\n										<td colspan=\'2\' class=\'col_c_forum\'>\n											<h4><a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$forum_data[\'name\']}</a></h4>\n											<p class=\'desc\'>{$forum_data[\'description\']}</p>\n										</td>\n										<td class=\'desc\'>\n											<ul class=\'last_post ipsType_small\'>\n												<li class=\'desc lighter\'><em>{parse format_number=\"$forum_data[\'redirect_hits\']\"} {$this->lang->words[\'rd_hits\']}</em></li>\n											</ul>\n										</td>\n									</tr>\n								<else />\n									<tr class=\'<if test=\"$forum_data[\'_has_unread\']\">unread</if>\'>\n										<td class=\'col_c_icon\'>\n											<if test=\"$forum_data[\'_has_unread\']\">\n												<a id=\'forum_img_{$forum_data[\'id\']}\' href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$this->request[\'f\']}&amp;i=1\" base=\"public\"}\" data-tooltip=\"{$this->lang->words[\'bi_markread\']}\" class=\'forum_marker\'><img src=\'{$this->settings[\'img_url\']}/f_icon.png\' /></a>\n												<script type=\'text/javascript\'>\n													ipb.global.registerMarker( \"forum_img_{$forum_data[\'id\']}\", \"{$forum_data[\'img_new_post\']}\", markerURL + \"&forumid={$forum_data[\'id\']}\" );\n												</script>\n											<else />\n												<img src=\'{$this->settings[\'img_url\']}/f_icon_read.png\' />\n											</if>\n										</td>\n										<td class=\'col_c_forum\'>									\n											<h4>\n												<if test=\"hasQueuedAndCanSeeIcon:|:!empty($forum_data[\'_has_queued_and_can_see_icon\'])\">\n													<a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;modfilter=all\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\' title=\'{$this->lang->words[\'view_unapproved\']}\' class=\'ipsBadge ipsBadge_orange\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'f_queued\'], $forum_data[\'queued_topics\'], $forum_data[\'queued_posts\'])\"}\" style=\'vertical-align: top\'>{$this->lang->words[\'f_queued_badge\']}</a>\n												</if>\n												<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$forum_data[\'name\']}</a>\n											</h4>\n										\n											<if test=\"showSubForums:|:$forum_data[\'show_subforums\'] AND count( $forum_data[\'subforums\'] ) AND $forum_data[\'show_subforums\']\">\n												<br />\n												<ol class=\'ipsList_inline ipsType_small subforums\' id=\'subforums_{$forum_data[\'id\']}\'>\n													<foreach loop=\"subforums:$forum_data[\'subforums\'] as $__id => $__data\">\n														<if test=\"showSubForumsLit:|:$__data[3]\"><li class=\'unread\'><else /><li></if>\n															<a href=\"{parse url=\"showforum={$__data[0]}\" seotitle=\"{$__data[2]}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\'>{$__data[1]}</a>\n														</li>\n													</foreach>\n												</ol>\n											</if>\n																	\n											<p class=\'desc __forum_desc ipsType_small\'>{$forum_data[\'description\']}</p>											\n										</td>\n										<td class=\'col_c_stats ipsType_small\'>\n											<ul>\n												<li><strong>{$forum_data[\'topics\']}</strong> {$this->lang->words[\'topics\']}</li>\n												<li><strong>{$forum_data[\'posts\']}</strong> {$this->lang->words[\'replies\']}</li>\n											</ul>\n										</td>\n										<td class=\'col_c_post\'>\n											<if test=\"hideLastInfo:|:$forum_data[\'hide_last_info\']\">\n												<ul class=\'last_post ipsType_small\'>\n													<li class=\'desc lighter\'><em>{$this->lang->words[\'f_protected\']}</em></li>\n												</ul>\n											<else />\n												<if test=\"hasphoto:|:$forum_data[\'pp_small_photo\'] AND !$forum_data[\'hide_last_info\']\">\n													<a href=\'{parse url=\"showuser={$forum_data[\'last_poster_id\']}\" template=\"showuser\" seotitle=\"{$forum_data[\'seo_last_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n														<img src=\'{$forum_data[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n													</a>\n												<else />\n													<if test=\"hasPost:|:$forum_data[\'last_id\']\"><div class=\'left\'>{IPSMember::buildNoPhoto(0, \'mini\' )}</div></if>\n												</if>\n												<ul class=\'last_post ipsType_small\'>\n													<if test=\"!$forum_data[\'last_id\']\">\n														<li class=\'desc lighter\'><em>{$this->lang->words[\'f_none\']}</em></li>\n													<else />\n														<li>\n															{$forum_data[\'last_topic_title\']}\n														</li>\n														<if test=\"lastPosterID:|:$forum_data[\'last_poster_id\']\">\n															<li>{$this->lang->words[\'by_ucfirst\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$forum_data\"}</li>\n														</if>\n														<if test=\"hideDateUrl:|:$forum_data[\'_hide_last_date\']\">\n															<li class=\'desc lighter blend_links\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</li>\n														<else />\n															<li class=\'desc lighter blend_links\'><a href=\'{parse url=\"showtopic={$forum_data[\'last_id\']}&amp;view=getlastpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$forum_data[\'seo_last_title\']}\"}\' title=\'{$this->lang->words[\'view_last_post\']}\'>{parse date=\"$forum_data[\'last_post\']\" format=\"DATE\"}</a></li>\n														</if>\n										\n													</if>\n											\n												</ul>\n											</if>\n										</td>\n									</tr>\n								</if>\n							</foreach>\n						</if>\n					</foreach>\n				</table>\n			</div>\n		</div>\n	</div>\n	<br /><br />\n</if>\n<if test=\"showtopics:|:$forum_data[\'sub_can_post\']\">\n	<div class=\'topic_controls clearfix\'>\n		{$forum_data[\'SHOW_PAGES\']}\n		<ul class=\'topic_buttons\'>\n			<if test=\"usercanpost:|:$forum_data[\'_user_can_post\']\">\n				<li><a href=\'{parse url=\"module=post&amp;section=post&amp;do=new_post&amp;f={$forum_data[\'id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'topic_start\']}\' accesskey=\'s\'>{$this->lang->words[\'topic_start\']}</a></li>\n			<else />\n				<li class=\'disabled\'><span>{$this->lang->words[\'forum_no_start_topic\']}</span></li>\n			</if>\n			<li class=\'non_button\'>\n				<a data-clicklaunch=\"forumMarkRead\" data-fid=\"{$forum_data[\'id\']}\" href=\'{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$forum_data[\'id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'mark_as_read\']}\'><img src=\'{$this->settings[\'img_url\']}/icon_check.png\' /> &nbsp;{$this->lang->words[\'mark_as_read\']}</a>\n			</li>\n		</ul>\n	</div>\n	<div class=\'ipsFilterbar maintitle\'>\n		<if test=\"topicsismod:|:$this->memberData[\'is_mod\'] == 1\">\n			<span class=\'right\'>\n				<input type=\'checkbox\' id=\'tmod_all\' class=\'input_check\' title=\'{$this->lang->words[\'topic_select_all\']}\' value=\'1\' />\n				&nbsp;\n			</span>\n		</if>\n		<ul class=\'ipsList_inline ipsType_small\'>\n			<li <if test=\"ka_last_post:|:$this->request[\'sort_key\'] == \'last_post\' and $this->request[\'sort_by\'] == \'Z-A\'\">class=\'active\'</if>><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;sort_key=last_post&amp;sort_by=Z-A\" base=\"public\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\"}\' rel=\'nofollow\'>{$this->lang->words[\'sort_recent\']}</a></li>\n			<li <if test=\"ka_start_date:|:$this->request[\'sort_key\'] == \'start_date\' and $this->request[\'sort_by\'] == \'Z-A\'\">class=\'active\'</if>><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;sort_key=start_date&amp;sort_by=Z-A\" base=\"public\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\"}\' rel=\'nofollow\'>{$this->lang->words[\'sort_start\']}</a></li>\n			<li <if test=\"ka_replies:|:$this->request[\'sort_key\'] == \'posts\' and $this->request[\'sort_by\'] == \'Z-A\'\">class=\'active\'</if>><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;sort_key=posts&amp;sort_by=Z-A\" base=\"public\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\"}\' rel=\'nofollow\'>{$this->lang->words[\'sort_replies\']}</a></li>\n			<li <if test=\"ka_viewed:|:$this->request[\'sort_key\'] == \'views\' and $this->request[\'sort_by\'] == \'Z-A\'\">class=\'active\'</if>><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;sort_key=views&amp;sort_by=Z-A\" base=\"public\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\"}\' rel=\'nofollow\'>{$this->lang->words[\'sort_views\']}</a></li>\n			<li <if test=\"$this->request[\'sort_by\'] == \'A-Z\' or !in_array( $this->request[\'sort_key\'], array( \'last_post\', \'start_date\', \'posts\', \'views\' ) )\">class=\'active\'</if>><a href=\'#forum_filter_menucontent\' id=\'forum_filter\'>{$this->lang->words[\'sort_custom\']}</a></li>\n		</ul>\n	</div>\n	<div id=\'forum_filter_menucontent\' class=\'ipbmenu_content ipsPad\' style=\'display: none\'>\n		<form id=\'filter_form\' action=\"{parse url=\"showforum={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;changefilters=1\" base=\"public\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\"}\" method=\"post\">\n			<strong>{$this->lang->words[\'filter_type\']}</strong><br />\n			<select name=\"topicfilter\" id=\'topic_filter\' class=\'input_select\'>{$footer_filter[\'topic_filter\']}</select>\n			<br /><br />\n		\n			<strong>{$this->lang->words[\'filter_sort\']}</strong><br />\n			<select name=\"sort_key\" id=\'sort_by\' class=\'input_select\'>{$footer_filter[\'sort_by\']}</select>\n			<br /><br />\n		\n			<strong>{$this->lang->words[\'filter_direction\']}</strong><br />\n			<select name=\"sort_by\" id=\'direction\' class=\'input_select\'>{$footer_filter[\'sort_order\']}</select>\n			<br /><br />\n		\n			<strong>{$this->lang->words[\'filter_time\']}</strong><br />\n			<select name=\"prune_day\" id=\'time_frame\' class=\'input_select\'>{$footer_filter[\'sort_prune\']}</select>\n			<br /><br />\n		\n			<input type=\'checkbox\' value=\'1\' name=\'remember\' class=\'input_check\' id=\'remember_filter\' /> <label for=\'remember_filter\'>{$this->lang->words[\'remember_options\']}</label>\n			<br /><br />\n			\n			<input type=\"submit\" value=\"{$this->lang->words[\'sort_submit\']}\" class=\"input_submit\" />\n		</form>\n	</div>\n	<script type=\'text/javascript\'>\n		new ipb.Menu( $(\'forum_filter\'), $(\'forum_filter_menucontent\'), { stopClose: true } );\n	</script>\n	<div class=\'ipsBox\'>\n		<div class=\'ipsBox_container\'>\n			<table class=\'ipb_table topic_list hover_rows <if test=\"topicsismod:|:$this->memberData[\'is_mod\'] == 1\">is_mod</if>\' summary=\'{$this->lang->words[\'forum_topic_list\']} \"{$forum_data[\'name\']}\"\' id=\'forum_table\'>\n				<tr class=\'header hide\'>\n					<th scope=\'col\' class=\'col_f_icon\'>&nbsp;</th>\n					<th scope=\'col\' class=\'col_f_topic\'>{$this->lang->words[\'forum_topic\']}</th>\n					<th scope=\'col\' class=\'col_f_starter short\'>{$this->lang->words[\'forum_started_by\']}</th>\n					<th scope=\'col\' class=\'col_f_views stats\'>{$this->lang->words[\'forum_stats\']}</th>\n					<th scope=\'col\' class=\'col_f_post\'>{$this->lang->words[\'forum_last_post_info\']}</th>\n					<if test=\"topicsismod:|:$this->memberData[\'is_mod\'] == 1\">\n						<th scope=\'col\' class=\'col_f_mod short\'><input type=\'checkbox\' id=\'tmod_all\' class=\'input_check\' title=\'{$this->lang->words[\'topic_select_all\']}\' value=\'1\' /></th>\n					</if>\n				</tr>	\n				<!-- BEGIN TOPICS -->\n				<if test=\"hastopics:|:is_array( $topic_data ) AND count( $topic_data )\">\n					{parse striping=\"forumTable\" classes=\"row1,row2\"}\n					<foreach loop=\"topics:$topic_data as $tid => $data\">\n						{parse template=\"topic\" group=\"forum\" params=\"$data, $forum_data, $other_data, $inforum\"}\n					</foreach>\n				<else />\n					<tr> \n						<if test=\"notopicsspan:|:$this->memberData[\'is_mod\'] == 1\">\n							<td colspan=\'6\' class=\'no_messages\'>\n						<else />\n							<td colspan=\'5\' class=\'no_messages\'>\n						</if>\n							{$this->lang->words[\'no_topics\']}\n						</td>\n					</tr>\n				</if>\n			</table>\n			<if test=\"hastopics:|:$other_data[\'hasMore\']\">\n				<div id=\'more_topics\' style=\'display: none\'>\n					<a href=\'#\' id=\'forum_load_more\'>{$this->lang->words[\'load_more_topics\']}</a>\n				</div>\n				<script type=\'text/javascript\'>\n					ipb.forums.fetchMore = {\n						\'f\': parseInt(\"{$this->request[\'showforum\']}\")	,\n						\'st\': parseInt(\"{$this->request[\'st\']}\"),\n						\'sort_by\': \"{$this->request[\'sort_by\']}\",\n						\'sort_key\': \"{$this->request[\'sort_key\']}\",\n						\'topicfilter\': \"{$this->request[\'topicfilter\']}\",\n						\'prune_day\': \"{$this->request[\'prune_day\']}\",\n						\'max_topics\': \"{$this->settings[\'display_max_topics\']}\"\n					};\n				</script>\n			</if>\n		</div>\n	</div>\n	\n	<if test=\"moderationform:|:$this->memberData[\'is_mod\'] == 1\">\n		<div class=\'ipsBox ipsPad clear clearfix\' id=\'topic_mod\'>\n			<div class=\'row2 ipsBox_container ipsPad moderation_bar with_action clearfix\'>\n				<a href=\'#\' id=\'forum_mod_options\' class=\'ipbmenu input_submit alt ipsPad_half left\'>{$this->lang->words[\'forum_management\']}</a>\n				<ul class=\'ipbmenu_content\' id=\'forum_mod_options_menucontent\' style=\'display: none\'>\n					<if test=\"$this->memberData[\'g_is_supmod\']\">\n						<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=prune_start&amp;f={$forum_data[\'id\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'mod_prumemovetopics\']}\'>{$this->lang->words[\'mod_prumemovetopics\']}</a></li>\n					</if>\n					<li><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=resync&amp;f={$forum_data[\'id\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'mod_resync\']}\'>{$this->lang->words[\'mod_resync\']}</a></li>\n					<li><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;modfilter=invisible_topics\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\' title=\'{$this->lang->words[\'mod_hidden\']}\'>{$this->lang->words[\'mod_hidden\']}</a></li>\n					<li><a href=\'{parse url=\"showforum={$forum_data[\'id\']}&amp;modfilter=invisible_posts\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\' title=\'{$this->lang->words[\'mod_hidden_posts\']}\'>{$this->lang->words[\'mod_hidden_posts\']}</a></li>\n				</ul>\n				<form id=\'modform\' class=\'right\' method=\"post\" action=\"{parse url=\"\" base=\"public\"}\">\n					<fieldset>\n						<input type=\"hidden\" name=\"app\" value=\"forums\" />\n						<input type=\"hidden\" name=\"module\" value=\"moderate\" />\n						<input type=\"hidden\" name=\"section\" value=\"moderate\" />\n						<input type=\"hidden\" name=\"do\" value=\"topicchoice\" />\n						<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n						<input type=\"hidden\" name=\"f\" value=\"{$forum_data[\'id\']}\" />\n						<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n						<input type=\"hidden\" name=\"modfilter\" value=\"{$this->request[\'modfilter\']}\" />\n						<input type=\"hidden\" value=\"{$this->request[\'selectedtids\']}\" id=\'selectedtids\' name=\"selectedtids\" />\n				\n						<select name=\"tact\" id=\'mod_tact\'>\n							<option value=\"close\">{$this->lang->words[\'cpt_close_f\']}</option>\n							<option value=\"open\">{$this->lang->words[\'cpt_open_f\']}</option>\n							<option value=\"pin\">{$this->lang->words[\'cpt_pin_f\']}</option>\n							<option value=\"unpin\">{$this->lang->words[\'cpt_unpin_f\']}</option>\n							<option value=\"move\">{$this->lang->words[\'cpt_move_f\']}</option>\n							<option value=\"merge\">{$this->lang->words[\'cpt_merge_f\']}</option>\n							<option value=\"delete\">{$this->lang->words[\'cpt_delete_f\']}</option>\n							<if test=\"$this->registry->class_forums->can_Un_SoftDeleteTopics( $forum_data[\'id\'], array() )\"><option value=\"sundelete\">{$this->lang->words[\'cpt_undelete_f\']}</option></if>\n							<option value=\"approve\">{$this->lang->words[\'cpt_approve_f\']}</option>\n							<option value=\"unapprove\">{$this->lang->words[\'cpt_unapprove_f\']}</option>\n							<if test=\"$forum_data[\'queued_topics\'] AND $this->registry->class_forums->canQueuePosts( $forum_data[\'id\'] )\">\n							<option value=\"t_approve\">{parse expression=\"sprintf( $this->lang->words[\'nmo_t_approve\'], $forum_data[\'queued_topics\'])\"}</option>\n							</if>\n							<if test=\"$forum_data[\'queued_topics\'] AND $this->registry->class_forums->canHardDeleteTopics( $forum_data[\'id\'], array() )\">\n								<option value=\"t_delete_approve\">{parse expression=\"sprintf( $this->lang->words[\'nmo_t_delete_approve\'], $forum_data[\'queued_topics\'])\"}</option>\n							</if>\n							<if test=\"$forum_data[\'permissions\'][\'TopicSoftDeleteRestore\'] AND $forum_data[\'deleted_topics\']\">\n								<option value=\"t_restore\">{parse expression=\"sprintf( $this->lang->words[\'nmo_t_restore\'], $forum_data[\'deleted_topics\'])\"}</option>\n							</if>\n							<if test=\"$forum_data[\'deleted_topics\'] AND $this->registry->class_forums->canHardDeleteTopics( $forum_data[\'id\'], array() )\">\n								<option value=\"t_delete_softed\">{parse expression=\"sprintf( $this->lang->words[\'nmo_t_delete_softed\'], $forum_data[\'deleted_topics\'])\"}</option>\n							</if>\n							<if test=\"mmdata:|:is_array( $multi_mod_data ) AND count( $multi_mod_data )\">\n								<option value=\"-1\">------------------------------</option>\n								<option value=\"-1\">{$this->lang->words[\'mm_title\']}</option>\n								<option value=\"-1\">------------------------------</option>\n								<foreach loop=\"mm:$multi_mod_data as $mm_data\">\n									<option value=\"t_{$mm_data[0]}\">--  {$mm_data[1]}</option>\n								</foreach>\n							</if>\n						</select>&nbsp;\n						<input type=\"submit\" name=\"gobutton\" value=\"{$this->lang->words[\'f_go\']}\" class=\"input_submit alt\" id=\'mod_submit\' />\n					</fieldset>\n				</form>\n			</div>\n		</div>\n	</if>	\n	\n	<br />\n	<div class=\'topic_controls clear\'>\n		{$forum_data[\'SHOW_PAGES\']}\n		<ul class=\'topic_buttons\'>\n			<if test=\"usercanpost:|:$forum_data[\'_user_can_post\']\">\n				<li><a href=\'{parse url=\"module=post&amp;section=post&amp;do=new_post&amp;f={$forum_data[\'id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'topic_start\']}\' rel=\'nofollow\' accesskey=\'s\'>{$this->lang->words[\'topic_start\']}</a></li>\n			<else />\n				<li class=\'disabled\'><span>{$this->lang->words[\'forum_no_start_topic\']}</span></li>\n			</if>\n			<if test=\"moderationlink:|:$this->memberData[\'is_mod\'] == 1\">\n				<li class=\'non_button\' style\'display: none\'>\n					<a href=\'#topic_mod\' id=\'moderator_toggle\' title=\'{$this->lang->words[\'show_mod_tools_desc\']}\'><img src=\'{$this->settings[\'img_url\']}/moderation_cog.png\' />&nbsp; {$this->lang->words[\'show_mod_tools\']}</a>\n				</li>\n			</if>\n		</ul>\n	</div>\n	<if test=\"moderationjs:|:$this->memberData[\'is_mod\'] == 1\">\n		<script type=\'text/javascript\'>\n			$(\'topic_mod\').hide();\n			$(\'moderator_toggle\').up(\'li\').show().observe(\'click\', function(e){\n				Event.stop(e);\n				$(\'moderator_toggle\').up(\'li\').hide();\n				$(\"topic_mod\").show();\n			});\n			$(\'modform\').observe(\'submit\', ipb.forums.submitModForm);\n			$(\'mod_tact\').observe(\'change\', ipb.forums.updateTopicModButton);\n		</script>\n	</if>\n	<br class=\'clear\' />	\n	<div id=\'forum_footer\' class=\'statistics clear clearfix\'>\n		<if test=\"hasmoderators:|:is_array( $mod_data ) AND count( $mod_data )\">\n			<div id=\'forum_led_by\' class=\'right ipsType_small\'>\n				<img src=\'{$this->settings[\'img_url\']}/icon_users.png\' /> &nbsp;{$this->lang->words[\'forum_led_by\']}\n				<foreach loop=\"moderators:$mod_data as $p => $r\">\n					<a href=\'{$r[0]}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$r[1]}</a><if test=\"moderatorpopup:|:$r[2]\"></if><if test=\"moderatorscomma:|:$p + 1 != count( $mod_data )\">,</if>\n				</foreach>\n			</div>\n		</if>\n		<if test=\"showactiveusers:|:!$this->settings[\'no_au_forum\']\">\n			<div id=\'forum_active_users\' class=\'active_users stats_list\'>\n				<h4 class=\'statistics_head\'>{parse expression=\"sprintf( $this->lang->words[\'active_users_titlef\'], ($active_user_data[\'members\'] + $active_user_data[\'guests\'] + $active_user_data[\'anon\'] ) )\"}</h4>\n				<p class=\'statistics_brief\'>{parse expression=\"sprintf( $this->lang->words[\'active_users_detail\'], $active_user_data[\'members\'], $active_user_data[\'guests\'], $active_user_data[\'anon\'] )\"}</p>\n				<br />\n				<ul class=\'ipsList_inline\'>\n					<if test=\"hasactiveusers:|:is_array( $active_user_data[\'names\'] ) AND count( $active_user_data[\'names\'] )\">\n						<foreach loop=\"activeusers:$active_user_data[\'names\'] as $p => $r\">\n					<li>{$r[\'p_start\']}<if test=\"aumemberid:|:$r[\'id\']\"><a href=\'{parse url=\"showuser={$r[\'id\']}\" seotitle=\"{$r[\'seo\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$r[\'p_title\']}\'></if>{$r[\'name\']}<if test=\"aumidend:|:$r[\'id\']\"></a></if>{$r[\'p_end\']}<if test=\"auaddcomma:|:$p + 1 != count( $active_user_data[\'names\'] )\">,</if></li>\n						</foreach>\n					</if>\n				</ul>\n			</div>\n		</if>	\n	</div>\n</if>\n<br class=\'clear\' />\n	\n<div id=\'delPopUp\' style=\'display:none\'>\n	<h3 class=\'bar\'>{$this->lang->words[\'dlt_title\']}</h3>\n	<div class=\'general_box\'>\n		<form action=\'#{removeUrl}\' method=\'POST\'>\n			<strong>{$this->lang->words[\'dlt_remove_from_view\']}</strong>\n			<p class=\'desc\'>{$this->lang->words[\'dlt_remove_from_view_desc\']}</p>\n			<p style=\'padding:4px 0px 4px 0px\'>{$this->lang->words[\'dlt_reason\']} <input type=\'text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' style=\'width:65%\' /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlt_remove\']}\' /></p>\n		</form>\n		<div style=\'#{permaDelete}padding-top:5px\'>\n			<strong>{$this->lang->words[\'dlt_delete_from_topic\']}</strong>\n			<p class=\'desc\'>{$this->lang->words[\'dlt_delete_from_topic_desc\']}</p>\n			<p style=\'padding:4px 0px 4px 0px\'><input type=\'button\' class=\'input_submit\' onclick=\"window.location=\'#{permaUrl}\';\" value=\'{$this->lang->words[\'dlt_delete_now\']}\' /></p>\n		</div>\n	</div>\n</div>', 'forumIndexTemplate', '$forum_data, $announce_data, $topic_data, $other_data, $multi_mod_data, $sub_forum_data, $footer_filter, $active_user_data, $mod_data, $inforum=1', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('311', '0', 'skin_forum', '<form action=\"{parse url=\"showforum={$fid}\" base=\"public\"}\" method=\"post\" style=\'width: 60%; margin: 0 auto;\'>\n	<input type=\"hidden\" name=\"L\" value=\"1\" />\n	\n	<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'need_password\']}</h1>\n	<div class=\'ipsType_pagedesc\'>{$this->lang->words[\'need_password_txt\']}</div>\n	\n	<br />\n	\n	<div>\n		<fieldset>\n			<br />\n			<ul class=\'ipsForm ipsForm_horizontal\'>\n				<li class=\'ipsField\'>\n					<label for=\'forum_pass\' class=\'ipsField_title\'>{$this->lang->words[\'enter_pass\']}</label>\n					<p class=\'ipsField_content\'>\n						<input type=\"password\" size=\"40\" name=\"f_password\" id=\'forum_pass\' class=\'input_text\' />\n					</p>\n				</li>\n			</ul>\n			<br />\n		</fieldset>\n		<fieldset class=\'submit\'>\n			<input type=\"submit\" value=\"{$this->lang->words[\'f_pass_submit\']}\" class=\"input_submit\" /> {$this->lang->words[\'or\']} <a href=\'{$this->settings[\'board_url\']}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</div>\n</form>', 'forumPasswordLogIn', '$fid=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('312', '0', 'skin_forum', '{parse js_module=\"like\"}\n<div class=\'__like right\' data-app=\"{$data[\'app\']}\" data-area=\"{$data[\'area\']}\" data-relid=\"{$relId}\" data-isfave=\"{$data[\'iLike\']}\">\n	{parse template=\"likeSummaryContents\" group=\"forum\" params=\"$data, $relId, $opts\"}\n</div>\n<script type=\"text/javascript\">\n	var FAVE_TEMPLATE = new Template( \"<h3>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_title\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}</h3><div class=\'ipsPad\'><span class=\'desc\'>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_words\'], $this->lang->words[\'like_un\' . $data[\'vernacular\'] ])\"}</span><br /><p class=\'ipsForm_center\'><input type=\'button\' value=\'{parse expression=\"sprintf( $this->lang->words[\'unset_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}\' class=\'input_submit _funset\' /></p></div>\");\n</script>', 'likeSummary', '$data, $relId, $opts', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('313', '0', 'skin_forum', '<span class=\'ipsButton_extra right <if test=\"$data[\'totalCount\']\">_fmore clickable</if>\' title=\'{parse expression=\"sprintf( $this->lang->words[\'like_totalcount_\' . $data[\'vernacular\'] ], $data[\'totalCount\'] )\"}\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'like_totalcount_\' . $data[\'vernacular\'] ], $data[\'totalCount\'] )\"}\"><img src=\'{$this->settings[\'img_url\']}/icon_users.png\' /> <strong>{$data[\'totalCount\']}</strong></span>\n<if test=\"likeOnlyMembers:|:$this->memberData[\'member_id\']\">\n	<a href=\'#\' title=\"<if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'fave_tt_on\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'fave_tt_off\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if>\" class=\'ftoggle ipsButton_secondary\'><if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'unset_fave_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'set_fave_button\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if></a>\n</if>', 'likeSummaryContents', '$data, $relId, $opts=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('314', '0', 'skin_forum', '<h2 class=\'ipsType_pagetitle\'>{$rules[\'title\']}</h2>\n<div class=\'row2 ipsPad\' style=\'line-height: 1.6\'>\n	{$rules[\'body\']}\n</div>\n<fieldset class=\'submit\'>\n	<a href=\"{parse url=\"showforum={$rules[\'fid\']}\" base=\"public\" seotitle=\"{$rules[\'fseo\']}\" template=\"showforum\"}\">{$this->lang->words[\'back_to_forum\']}</a>\n</fieldset>', 'show_rules', '$rules=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('315', '0', 'skin_forum', '<if test=\"queuedtopic:|:($this->memberData[\'is_mod\'] AND ! $data[\'approved\']) OR $data[\'_isDeleted\']\">\n<tr class=\'__topic expandable moderated\' id=\'trow_{$data[\'_tid\']}\' data-tid=\"{$data[\'_tid\']}\">\n<else />\n<tr class=\'__topic <if test=\"!$data[\'folder_img\'][\'is_read\']\">unread</if> expandable\' id=\'trow_{$data[\'_tid\']}\' data-tid=\"{$data[\'_tid\']}\">\n</if>\n	<td class=\'col_f_icon altrow short\'>\n		{parse template=\"generateTopicIcon\" group=\"global_other\" params=\"$data[\'folder_img\'], isset($data[\'_unreadUrl\']) ? $data[\'_unreadUrl\'] : \'\'\"}\n	</td>\n	<td class=\'col_f_content <if test=\"hasmodlinks:|:$this->memberData[\'is_mod\'] == 1 || $forum_data[\'permissions\'][\'TopicSoftDelete\']\"> with_mod_links</if>\'>\n		<if test=\"topicDeletedReason:|:$data[\'_isDeleted\']\">\n			<span class=\'ipsBadge ipsBadge_red\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'tdb__forumindex\'], $other_data[\'sdData\'][ $data[\'tid\'] ][\'members_display_name\'] )\"} {parse date=\"$other_data[\'sdData\'][ $data[\'tid\'] ][\'sdl_obj_date\']\" format=\"long\"}\n					<if test=\"showReason:|:$forum_data[\'permissions\'][\'SoftDeleteReason\']\">\n						<br /><span><if test=\"$other_data[\'sdData\'][ $data[\'tid\'] ][\'sdl_obj_reason\']\">{$other_data[\'sdData\'][ $data[\'tid\'] ][\'sdl_obj_reason\']}<else />{$this->lang->words[\'tdb__noreasongi\']}</if></span>\n					</if>\n				\">{$this->lang->words[\'f_deleted_badge\']}</span>\n		</if>\n		<if test=\"topicUnapproved:|:$data[\'approved\'] == 0\">\n			<span class=\'ipsBadge ipsBadge_orange\'>{$this->lang->words[\'f_queued_badge\']}</span>\n		</if>\n		<if test=\"hasPrefix:|:!empty($data[\'tags\'][\'formatted\'][\'prefix\'])\">\n			{$data[\'tags\'][\'formatted\'][\'prefix\']}\n		</if>\n		<h4>{$data[\'prefix\']}<a id=\"tid-link-{$data[\'_tid\']}\" href=\"{$data[\'_url\']}\" title=\'{$this->lang->words[\'topic_started_on\']} {parse date=\"$data[\'start_date\']\" format=\"LONG\"}\' class=\'topic_title\'>{$data[\'title\']}</a></h4>\n		<br />\n		<span class=\'desc lighter blend_links\'>\n			{parse expression=\"sprintf( $this->lang->words[\'topic_started_by\'], $data[\'starter\'] )\"} {parse date=\"$data[\'start_date\']\" format=\"DATE\"}\n			<if test=\"hasTags:|:isset($data[\'tags\']) AND $data[\'tags\']\">\n				&nbsp; <img src=\'{$this->settings[\'img_url\']}/icon_tag.png\' /> {$data[\'tags\'][\'formatted\'][\'truncatedWithLinks\']}\n			</if>\n		</span>\n		<if test=\"multipages:|:isset( $data[\'pages\'] ) AND is_array( $data[\'pages\'] ) AND count( $data[\'pages\'] )\">\n			<ul class=\'mini_pagination\'>\n			<foreach loop=\"pages:$data[\'pages\'] as $page\">\n					<if test=\"haslastpage:|:$page[\'last\']\">\n						<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']} {$this->lang->words[\'_rarr\']}</a></li>\n					<else />\n						<li><a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;st={$page[\'st\']}\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\" title=\'{$this->lang->words[\'topic_goto_page\']} {$page[\'page\']}\'>{$page[\'page\']}</a></li>\n					</if>\n			</foreach>\n			</ul>\n		</if>\n	</td>\n	<td class=\'col_f_preview __topic_preview\'>\n		<if test=\"$this->registry->permissions->check( \'read\', $forum_data )\">\n			<a href=\'{$data[\'_url\']}\' class=\'expander closed\' title=\'{$this->lang->words[\'view_topic_preview\']}\'>&nbsp;</a>\n		</if>\n	</td>\n	<td class=\'col_f_views desc blend_links\'>\n		<ul>\n			<li>\n				<if test=\"queuedpostsImg:|:($this->memberData[\'is_mod\'] AND $data[\'_hasqueued\'])\">\n					<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;modfilter=invisible_posts\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'view_uapproved_posts\']}\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'topic_queued_count\'], $data[\'topic_queuedposts\'] )\"}\"><img src=\'{$this->settings[\'img_url\']}/bullet_error.png\' alt=\'\' /></a>\n				</if>\n				<if test=\"deletedPostsImg:|:($forum_data[\'permissions\'][\'PostSoftDeleteSee\'] AND $data[\'topic_deleted_posts\'])\">\n					<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;modfilter=deleted_posts\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'view_deleted_posts\']}\'><img src=\'{$this->settings[\'img_url\']}/bullet_delete.png\' alt=\'\' /></a>\n				</if>\n				<if test=\"isLink:|:$data[\'state\'] != \'link\'\">\n					<if test=\"isHot:|:$data[\'folder_img\'][\'is_hot\']\">\n						<span class=\'ipsBadge ipsBadge_orange\'>{$this->lang->words[\'topic_is_hot\']}</span>&nbsp;\n					</if>\n					<a href=\"{parse url=\"app=forums&amp;module=extras&amp;section=stats&amp;do=who&amp;t={$data[\'tid\']}\" base=\"public\"}\" onclick=\"return ipb.forums.retrieveWhoPosted( {$data[\'tid\']} );\">{parse format_number=\"$data[\'posts\']\"} <if test=\"replylang:|:intval($data[\'posts\']) == 1\">{$this->lang->words[\'reply\']}<else />{$this->lang->words[\'replies\']}</if></a>\n				</if>\n			</li>\n			<li class=\'views desc\'>{parse format_number=\"$data[\'views\']\"} {$this->lang->words[\'views\']}</li>\n		</ul>\n	</td>\n	<td class=\'col_f_post\'>\n		<a href=\'{parse url=\"showuser={$data[\'last_poster_id\']}\" seotitle=\"{$data[\'seo_last_name\']}\" template=\"showuser\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n			<img src=\'{$data[\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n		</a>\n		<ul class=\'last_post ipsType_small\'>\n			<li>{$data[\'last_poster\']}</li>\n			<li>\n				<a href=\'{parse url=\"showtopic={$data[\'tid\']}&amp;view=getlastpost\" seotitle=\"{$data[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{parse date=\"$data[\'last_post\']\" format=\"DATE\"}</a>\n			</li>								\n		</ul>\n	</td>\n	<if test=\"mmicon:|:$this->memberData[\'is_mod\'] == 1 and $inforum == 1\">\n		<td class=\'col_f_mod short\'>\n			<a href=\'#\' class=\'ipsModMenu\' id=\'topic_mod_{$data[\'real_tid\']}\' title=\'{$this->lang->words[\'mod_actions\']}\'>&nbsp;</a>\n			<if test=\"mmtidon:|:$data[\'tidon\'] == 0\">\n				<input type=\'checkbox\' class=\'input_check topic_mod\' id=\'tmod_{$data[\'real_tid\']}\' />\n			<else />\n				<input type=\'checkbox\' class=\'input_check topic_mod\' id=\'tmod_{$data[\'real_tid\']}\' checked=\'checked\' />\n			</if>\n			<if test=\"topicIsDeleted:|:$data[\'_isDeleted\']\">\n				<ul id=\'topic_mod_{$data[\'real_tid\']}_menucontent\' class=\'ipbmenu_content\' style=\'display: none\'>\n					<if test=\"tidRestore:|:$forum_data[\'permissions\'][\'TopicSoftDeleteRestore\']\">\n						<li class=\'t_restore\'><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=sundelete\" base=\"public\"}\' title=\'{$this->lang->words[\'dlt_restore_topic\']}\'><img src=\'{$this->settings[\'img_url\']}/arrow_rotate_clockwise.png\' alt=\'{$this->lang->words[\'dlt_restore_topic\']}\' title=\'{$this->lang->words[\'dlt_restore_topic\']}\' class=\'icon\' /> {$this->lang->words[\'dlt_restore_topic\']}</a></li>\n					</if>\n					<if test=\"$this->memberData[\'g_is_supmod\'] == 1 || $this->memberData[\'forumsModeratorData\'][ $forum_data[\'id\'] ][\'delete_topic\']\">\n						<li class=\'t_restore\'><a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;t={$data[\'real_tid\']}&amp;auth_key={$this->member->form_hash}&amp;do=03\" base=\"public\"}\' title=\'{$this->lang->words[\'dlt_delete_topic\']}\'><img src=\'{$this->settings[\'img_url\']}/delete.png\' alt=\'{$this->lang->words[\'dlt_delete_topic\']}\' title=\'{$this->lang->words[\'dlt_delete_topic\']}\' class=\'icon\' /> {$this->lang->words[\'dlt_delete_topic\']}</a></li>\n					</if>\n				</ul>\n			<else />\n				<if test=\"topicmoderator:|:$this->memberData[\'is_mod\'] == 1  || $forum_data[\'permissions\'][\'TopicSoftDelete\']\">\n					<ul id=\'topic_mod_{$data[\'real_tid\']}_menucontent\' class=\'ipbmenu_content\' style=\'display: none\'>\n						<li><a class=\'t_rename\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;auth_key={$this->member->form_hash}&amp;do=05\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_rename\']}\'><img src=\'{$this->settings[\'img_url\']}/textfield_rename.png\' alt=\'{$this->lang->words[\'topic_rename\']}\' title=\'{$this->lang->words[\'topic_rename\']}\' class=\'icon\' /> {$this->lang->words[\'topic_rename\']}</a></li>\n						<if test=\"$this->memberData[\'g_is_supmod\'] == 1 || $this->memberData[\'forumsModeratorData\'][ $forum_data[\'id\'] ][\'delete_topic\'] || $forum_data[\'permissions\'][\'TopicSoftDelete\']\">\n							<li><a class=\'t_delete\' id=\'t_deletelink_{$data[\'tid\']}\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;t={$data[\'real_tid\']}&amp;auth_key={$this->member->form_hash}&amp;do=03\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_delete\']}\'><img src=\'{$this->settings[\'img_url\']}/delete.png\' alt=\'{$this->lang->words[\'topic_delete\']}\' title=\'{$this->lang->words[\'topic_delete\']}\' class=\'icon\' /> {$this->lang->words[\'topic_delete\']}</a></li>\n						</if>\n						<if test=\"islink:|:$data[\'state\'] != \'link\'\">\n							<if test=\"ispinned:|:$data[\'pinned\'] && ($this->memberData[\'g_is_supmod\'] OR $this->memberData[\'forumsModeratorData\'][ $forum_data[\'id\'] ][\'pin_topic\'])\">\n								<li><a class=\'t_pin\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=16&amp;from=forum\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_unpin\']}\'><img src=\'{$this->settings[\'img_url\']}/award_delete.png\' alt=\'{$this->lang->words[\'topic_unpin\']} icon\' title=\'{$this->lang->words[\'topic_unpin\']}\' class=\'icon\' /> {$this->lang->words[\'topic_unpin\']}</a></li>\n							<else />\n								<if test=\"issupermod:|:$this->memberData[\'g_is_supmod\'] OR $this->memberData[\'forumsModeratorData\'][ $forum_data[\'id\'] ][\'unpin_topic\']\">\n									<li><a class=\'t_pin\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=15&amp;from=forum\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_pin\']}\'><img src=\'{$this->settings[\'img_url\']}/award.png\' alt=\'{$this->lang->words[\'topic_pin\']} icon\' title=\'{$this->lang->words[\'topic_pin\']}\' class=\'icon\' /> {$this->lang->words[\'topic_pin\']}</a></li>\n								</if>\n							</if>\n						</if>\n						<if test=\"closedtopic:|:$data[\'state\'] == \'closed\' && $other_data[\'can_open_topics\']\">\n							<li><a class=\'t_lock\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=01\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_open\']}\'><img src=\'{$this->settings[\'img_url\']}/lock_open.png\' alt=\'{$this->lang->words[\'topic_open\']}\' title=\'{$this->lang->words[\'topic_open\']}\' class=\'icon\' /> {$this->lang->words[\'topic_open\']}</a></li>\n						</if>\n						<if test=\"opentopic:|:$data[\'state\'] == \'open\' && $other_data[\'can_close_topics\']\">\n							<li><a class=\'t_lock\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;t={$data[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=00&amp;_from=forum\" base=\"public\"}\' title=\'{$this->lang->words[\'topic_close\']}\'><img src=\'{$this->settings[\'img_url\']}/lock.png\' alt=\'{$this->lang->words[\'topic_close\']}\' title=\'{$this->lang->words[\'topic_close\']}\' class=\'icon\' /> {$this->lang->words[\'topic_close\']}</a></li>\n						</if>\n						<if test=\"islink2:|:$data[\'state\'] != \'link\' && $other_data[\'can_move_topics\']\">\n							<li><a class=\'t_move\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum_data[\'id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=topicchoice&amp;tact=move&amp;selectedtids={$data[\'tid\']}\" base=\"public\"}\'><img src=\'{$this->settings[\'img_url\']}/page_white_go.png\' alt=\'{$this->lang->words[\'topic_close\']}\' title=\'{$this->lang->words[\'topic_close\']}\' class=\'icon\' /> {$this->lang->words[\'topic_move\']}</a></li>\n						</if>\n					</ul>\n				</if>\n			</if>\n			<script type=\'text/javascript\'>\n				new ipb.Menu( $(\'topic_mod_{$data[\'real_tid\']}\'), $(\'topic_mod_{$data[\'real_tid\']}_menucontent\') );\n			</script>\n		</td>\n	</if>\n</tr>\n<if test=\"adCodeCheck:|:isset($data[\'_adCode\']) AND $data[\'_adCode\']\">\n<tr>\n	<th scope=\'col\' colspan=\'<if test=\"adCodeColSpan:|:$this->memberData[\'is_mod\'] == 1\">6<else />5</if>\'>\n		{$data[\'_adCode\']}\n	</th>\n</tr>\n</if>', 'topic', '$data, $forum_data, $other_data, $inforum', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('316', '0', 'skin_forum', '<span class=\'mini_rate\'>\n<foreach loop=\"ratings:array(1,2,3,4,5) as $int\">\n	<if test=\"ratinggood:|:$rating_id >= $int\">\n		{parse replacement=\"mini_rate_on\"}\n	<else />\n		{parse replacement=\"mini_rate_off\"}\n	</if>\n</foreach>\n</span>', 'topic_rating_image', '$rating_id=1', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('317', '0', 'skin_forum', '<if test=\"prefix:|:$text\">\n	<span class=\'ipsBadge ipsBadge_green\'>{$text}</span>&nbsp;\n</if>', 'topicPrefixWrap', '$text', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('318', '0', 'skin_legends', '<h2>{$this->lang->words[\'bbc_title\']}</h2>\n<span class=\'desc\'>{$this->lang->words[\'bbc_intro\']}</span>\n<br /><br />\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th style=\'width: 50%\'>{$this->lang->words[\'bbc_before\']}</th>\n		<th style=\'width: 50%\'>{$this->lang->words[\'bbc_after\']}</th>\n	</tr>\n	<foreach loop=\"bbcode:$rows as $row\">\n		<tr class=\'subhead bar altbar\'>\n			<th colspan=\'2\'>{$row[\'title\']}</th>\n		</tr>\n		<tr class=\'row1\'>\n			<td class=\'altrow\'>\n				{$row[\'before\']}\n			</td>\n			<td>\n				{$row[\'after\']}\n			</td>\n		</tr>\n	</foreach>\n</table>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}\n<script type=\'text/javascript\'>\n	try {\n		ipb.delegate.register(\'.bbc_spoiler_show\', ipb.global.toggleSpoiler);\n	} catch(err) { }\n</script>', 'bbcodePopUpList', '$rows', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('319', '0', 'skin_legends', '<if test=\"!$legacy_editor\">\n	<script type=\"text/javascript\">\n	addEmoImage = function(elem){\n		var isRte = opener.ipb.textEditor.getEditor().isRte();\n		var toAdd = \'\';\n	\n		if ( isRte ){\n			toAdd = elem.up(\'tr\').down(\'img\').readAttribute(\'src\');\n			toAdd = \'<img src=\"\' + toAdd + \'\" />&nbsp;\';\n		} else {\n			toAdd = elem.up(\'tr\').down(\'a\').innerHTML + \' \';\n		}\n	\n		opener.ipb.textEditor.getEditor().insert( toAdd );\n	}\n	</script>\n<else />\n	<script type=\'text/javascript\'>\n		function addEmoImage(elem){\n			var code = elem.up(\'tr\').down(\'a\').innerHTML;\n			var title = elem.up(\'tr\').down(\'img\').readAttribute(\'title\');\n			ipb.editors[ \'{$editor_id}\' ].insert_emoticon(\'\', title, code,\'\');\n		}\n	</script>\n</if>\n{parse striping=\"emoticons\" classes=\"row1,row2\"}\n<div class=\'full_emoticon\'>\n	<table class=\'ipb_table\'>\n		<foreach loop=\"emoticons:$rows as $row\">\n		<tr class=\'{parse striping=\"emoticons\"}\'>\n			<td style=\'text-align: center; width: 40%;\'>\n				<a href=\"#\" onclick=\"addEmoImage(this); return false;\" title=\"{$row[\'image\']}\">{$row[\'code\']}</a>\n			</td>\n			<td style=\'text-align: center; width: 60%;\'>\n				<img class=\'clickable\' src=\"{$this->settings[\'emoticons_url\']}/{$row[\'image\']}\" onclick=\"addEmoImage(this); return false;\" id=\'smid_{$row[\'smilie_id\']}\' alt=\"{$row[\'image\']}\" />\n			</td>\n		</tr>\n		</foreach>\n	</table>\n</div>', 'emoticonPopUpList', '$editor_id, $rows, $legacy_editor=false', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('320', '0', 'skin_legends', '<div><b>{$tag}</b></div>', 'wrap_tag', '$tag=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('321', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'08\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<input type=\'hidden\' name=\'return\' value=\'{$this->request[\'return\']}\' />\n<h2 class=\'maintitle\'>{$this->lang->words[\'top_delete\']}: {$forum[\'name\']} -&gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<p class=\'row1 field\'>{$this->lang->words[\'delete_topic\']}</p>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'submit_delete\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;st={$this->request[\'st\']}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'deleteTopicForm', '$forum, $topic', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('322', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'12\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2 class=\'maintitle\'>{$this->lang->words[\'top_edit\']}: {$forum[\'name\']} &gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'editing_topic_title\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'topic_title\'>{$this->lang->words[\'edit_f_title\']}</label>\n				<input class=\'input_text\' type=\"text\" size=\"40\" id=\'topic_title\' maxlength=\"{$this->settings[\'topic_title_max_len\']}\" name=\"TopicTitle\" value=\"{$topic[\'title\']}\" />\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'submit_edit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>\n<br />', 'editTopicTitle', '$forum, $topic', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('323', '0', 'skin_mod', '<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'poll_merge_title\']}</h1>\n<br />\n<div class=\'message\'>\n	{$this->lang->words[\'poll_merge_blurb\']}\n</div>\n<br />\n<foreach loop=\"$polls as $poll\">\n	<div class=\'general_box alt poll\'>\n		<h3>{$poll[\'poll_question\']}</h3>\n		<foreach loop=\"unserialize( stripslashes( $poll[\'choices\'] ) ) as $questionID => $questionData\">\n			<div class=\'poll_question\'>\n				<h4 class=\'rounded\'>{$questionData[\'question\']}</h4>\n				<ol>\n					<foreach loop=\"$questionData[\'choice\'] as $choiceID => $name\">\n						<li>\n							<span class=\'answer\'>{$name}</span>\n							<span class=\'votes\'>({$questionData[\'votes\'][$choiceID]} {$this->lang->words[\'poll_votes\']})</span>\n						</li>	\n					</foreach>\n				</ol>\n			</div>\n		</foreach>\n		<fieldset class=\'submit\'>\n			<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=topicchoice&amp;tact=merge&amp;selectedtids={$tids}&amp;f={$this->request[\'f\']}&amp;chosenpolltid={$poll[\'tid\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' class=\'ipsButton\'>{$this->lang->words[\'poll_merge_submit\']}</a>\n		</fieldset>\n	</div>\n	<br /><br />\n</foreach>', 'mergeMultiplePolls', '$polls, $tids', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('324', '0', 'skin_mod', '{parse js_module=\"moderate\"}\n<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'postchoice\' />\n<foreach loop=\"selectedpids:$this->request[\'selectedpids\'] as $pid\">\n	<input type=\"hidden\" name=\"selectedpids[{$pid}]\" value=\"{$pid}\" />\n</foreach>\n<if test=\"$this->request[\'selectedpidsJS\']\">\n	<foreach loop=\"selectedpidsjs:explode( \',\', $this->request[\'selectedpidsJS\'] ) as $pid\">\n		<input type=\"hidden\" name=\"selectedpids[{$pid}]\" value=\"{$pid}\" />\n	</foreach>\n</if>\n<input type=\"hidden\" name=\"t\" value=\"{$this->request[\'t\']}\" />\n<input type=\"hidden\" name=\"f\" value=\"{$this->request[\'f\']}\" />\n<input type=\'hidden\' name=\'tact\' value=\'merge\' />\n<input type=\'hidden\' name=\'checked\' value=\'1\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<p class=\'message\'>{$this->lang->words[\'merge_select\']}</p>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'cm_title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'post_options\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'post_date\'>{$this->lang->words[\'cm_post\']}</label>\n				<select name=\"postdate\" class=\"input_select\" id=\'post_date\'>\n					<if test=\"mergepostsdates:|:is_array($dates) AND count($dates)\">\n						<foreach loop=\"dates:$dates as $date\">\n							<option value=\'{$date[0]}\'>{$date[1]}</option>\n						</foreach>\n					</if>\n				</select>\n			</li>\n			<li class=\'field\'>\n				<label for=\'post_author\'>{$this->lang->words[\'cm_author\']}</label>\n				<select name=\"postauthor\" class=\"input_select\" id=\'post_author\'>\n					<if test=\"mergepostsauthors:|:is_array($authors) AND count($authors)\">\n						<foreach loop=\"authors:$authors as $author\">\n							<option value=\'{$author[0]}\'>{$author[1]}</option>\n						</foreach>\n					</if>\n				</select>\n			</li>\n		</ul>\n		<h3 class=\'bar\'>{$this->lang->words[\'post_content\']}</h3>\n		{$editor}\n	</fieldset>\n	<if test=\"mergepostsattachments:|:count($uploads)\">\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'cm_attach\']}</h3>\n			<h4>{$this->lang->words[\'cm_attach2\']}<h4>\n			<table>\n				<foreach loop=\"uploads:$uploads as $attach\">\n					<tr>\n						<td width=\"1%\">\n							<select name=\"attach_{$attach[\'attach_id\']}\" class=\"input_select\">\n								<option value=\"keep\">{$this->lang->words[\'cm_keep\']}</option>\n								<option value=\"delete\">{$this->lang->words[\'cm_delete\']}</option>\n							</select>\n						</td>\n						<td width=\"1%\"><img src=\"{$this->settings[\'public_dir\']}{$attach[\'image\']}\" alt=\"{$this->lang->words[\'cm_attach_alt\']}\" /></td>\n						<td width=\"15%\" nowrap=\"nowrap\">{$attach[\'size\']}</td>\n						<td width=\"95%\"><a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_id={$attach[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'cm_attach_title\']}\">{$attach[\'attach_file\']}</a> #{$attach[\'attach_rel_id\']}</td>\n					</tr>\n				</foreach>\n			</table>\n		</fieldset>\n	</if>\n	<fieldset class=\'submit\'>\n		<php>\n			$selectedPids	= implode( \',\', $this->request[\'selectedpids\'] );\n		</php>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'cm_submit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$this->request[\'t\']}&amp;selectedpids={$selectedPids}\" base=\"public\" seotitle=\"{$seoTitle}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'mergePostForm', '$editor, $dates, $authors, $uploads, $seoTitle', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('325', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'61\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2 class=\'maintitle\'>{$this->lang->words[\'mt_top\']}: {$forum[\'name\']} &gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'merge_topic_options\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'new_title\'>{$this->lang->words[\'mt_new_title\']}</label>\n				<input type=\"text\" id=\'new_title\' class=\'input_text\' size=\"40\" maxlength=\"250\" name=\"title\" value=\"{$topic[\'title\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'topic_url\'>{$this->lang->words[\'mt_tid\']}</label>\n				<input type=\"text\" id=\'topic_url\' class=\'input_text\' size=\"40\" name=\"topic_url\" value=\"\" />\n				<span class=\'desc\'>{$this->lang->words[\'mt_tid_desc\']}</span>\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'mt_submit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'mergeTopicsForm', '$forum, $topic', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('326', '0', 'skin_mod', '<if test=\"movepostserror:|:$error\">\n	<p class=\"message error\">{$error}</p>\n</if>\n{parse js_module=\"moderate\"}\n<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'postchoice\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'tact\' value=\'move\' />\n<input type=\'hidden\' name=\'checked\' value=\'1\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2 class=\'maintitle\'>{$this->lang->words[\'cmp_title\']}: {$forum[\'name\']} -&gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset class=\'row1\'>\n		<h3 class=\'bar\'>{$this->lang->words[\'move_posts_option\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'topic_url\'>{$this->lang->words[\'cmp_topic\']}</label>\n				<input type=\"text\" size=\"50\" name=\"topic_url\" value=\"\" id=\'topic_url\' class=\'input_text\' />\n				<span class=\'desc\'>{$this->lang->words[\'cmp_topic2\']}</span>\n			</li>\n		</ul>\n	</fieldset>\n</div>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'move_topic_summary\']}</h2>\n<div class=\'generic_bar\'></div>\n<if test=\"movepostsloop:|:is_array( $posts ) AND count( $posts )\">\n	<foreach loop=\"posts:$posts as $row\">\n		<div class=\'post_block topic_summary\'>\n			<h3>{$row[\'author_name\']}</h3>\n			<p class=\'posted_info\'>{$this->lang->words[\'move_posted\']} {$row[\'date\']}</p>\n			<label for=\'checkbox_{$row[\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'st_split\']}</label>\n			<input type=\'checkbox\' id=\'checkbox_{$row[\'pid\']}\' name=\'selectedpids[{$row[\'pid\']}]\' value=\'{$row[\'pid\']}\' class=\'post_mod\' checked=\'checked\' />\n			<div class=\'post_body\'>\n				<div class=\'post\'>{$row[\'post\']}</div>\n			</div>\n		</div>\n	</foreach>\n</if>\n<fieldset class=\'submit\'>\n	<php>\n		$selectedPids	= implode( \',\', $this->request[\'selectedpids\'] );\n	</php>\n	<input type=\"submit\" name=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'cmp_submit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;selectedpids={$selectedPids}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n</fieldset>\n</form>', 'movePostForm', '$forum, $topic, $posts, $error=\'\'', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('327', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'14\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n\n<p class=\'message\'>{$this->lang->words[\'move_exp\']}</p>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'top_move\']}: {$forum[\'name\']} &gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'move_topic_options\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'move_from\'>{$this->lang->words[\'move_from\']} <strong>{$forum[\'name\']}</strong> {$this->lang->words[\'to\']}</label>\n				<select name=\"move_id\" id=\'move_from\' class=\'input_select\'>{$forum_jump}</select>\n			</li>\n			<li class=\'field clear checkbox\'>\n				<input type=\'checkbox\' id=\'leave_link\' class=\'input_check\' name=\'leave\' value=\'y\' />\n				<label for=\'leave_link\'>{$this->lang->words[\'leave_link\']}</label>\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'submit_move\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'moveTopicForm', '$forum, $topic, $forum_jump', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('328', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'topicchoice\' />\n<input type=\'hidden\' name=\'tact\' value=\'domove\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<input type=\'hidden\' name=\'fromSearch\' value=\'{$this->request[\'fromSearch\']}\' />\n<input type=\'hidden\' name=\'returnUrl\' value=\'{$this->request[\'returnUrl\']}\' />\n<p class=\'message\'>{$this->lang->words[\'move_exp\']}</p>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'cp_tmove_start\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\' id=\'mod_form\'>\n	<fieldset class=\'row1\'>\n		<h3 class=\'bar\'>{$this->lang->words[\'topics_to_move\']}</h3>\n		<ul>\n			<if test=\"movetopicsloop:|:count($topics) AND is_array($topics)\">\n				<foreach loop=\"topics:$topics as $row\">\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\"checkbox\" name=\"selectedtids[{$row[\'tid\']}]\" id=\'t_{$row[\'tid\']}\' value=\"{$row[\'tid\']}\" checked=\"checked\" />\n						<label for=\'t_{$row[\'tid\']}\'>{$row[\'title\']}</label>\n					</li>\n				</foreach>\n			</if>\n		</ul>\n	</fieldset>\n	<fieldset class=\'row1\'>\n		<h3 class=\'bar\'>{$this->lang->words[\'move_topic_options\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'move_from\'>{$this->lang->words[\'move_from\']} <strong>{$forum[\'name\']}</strong> {$this->lang->words[\'to\']}</label>\n				<select name=\"df\" id=\'move_from\' class=\'input_select\'>{$jump_html}</select>\n			</li>\n			<li class=\'field clear checkbox\'>\n				<input type=\'checkbox\' id=\'leave_link\' class=\'input_check\' name=\'leave\' value=\'y\' />\n				<label for=\'leave_link\'>{$this->lang->words[\'leave_link\']}</label>\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'submit_move\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showforum={$forum[\'id\']}\" base=\"public\" seotitle=\"{$forum[\'name_seo\']}\" template=\"showforum\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</div>\n</form>', 'moveTopicsForm', '$forum, $jump_html, $topics', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('329', '0', 'skin_mod', '<if test=\"prunecompletehtml:|:$complete_html != \'\'\">\n	<div class=\'message\'>{$complete_html}</div><br />\n</if>\n	\n<h2 class=\'maintitle\'>{$this->lang->words[\'cp_prune\']} {$forum[\'name\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<if test=\"confirmprune:|:$confirm_data[\'show\'] == 1\">\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'mpt_confirm\']}: {$this->lang->words[\'cp_check_result\']}</h3>\n			\n			<ul>\n				<li class=\'field\'>\n					<label>{$this->lang->words[\'cp_total_topics\']}</label>\n					{$confirm_data[\'tcount\']}\n				</li>\n				<li class=\'field\'>\n					<label>{$this->lang->words[\'cp_total_match\']}</label>\n					{$confirm_data[\'count\']}\n				</li>\n			</ul>\n		</fieldset>\n	\n		<form action=\'{parse url=\"{$confirm_data[\'link\']}\" base=\"public\"}\' method=\"post\">\n		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		<fieldset class=\'submit\'>\n			<input type=\"submit\" class=\'input_submit\' value=\"{$confirm_data[\'link_text\']}\" />\n		</fieldset>\n		</form>\n		\n	</if>\n	<form id=\'postingform\' action=\"{parse url=\"\" base=\"public\"}\" method=\"post\">\n	<input type=\"hidden\" name=\"app\" value=\"forums\" />\n	<input type=\"hidden\" name=\"module\" value=\"moderate\" />\n	<input type=\"hidden\" name=\"section\" value=\"moderate\" />\n	<input type=\"hidden\" name=\"do\" value=\"prune_start\" />\n	<input type=\"hidden\" name=\"f\" value=\"{$forum[\'id\']}\" />\n	<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n	<input type=\"hidden\" name=\"check\" value=\"1\" />\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'mpt_help\']}</h3>\n		<p class=\'ipsPad\'>{$this->lang->words[\'cp_prune_text\']}</p><br />\n		<ul>\n			<li class=\'field\'>\n				<label for=\'df\'>{$this->lang->words[\'cp_prune_action2\']}</label>\n				<select class=\'input_select\' name=\"df\" id=\"df\">\n					<option value=\'prune\'>{$this->lang->words[\'cp_ac_prune\']}</option>\n					{$forums_html}\n				</select>\n			</li>\n			<li class=\'field\'>\n				<label for=\'pergo\'>{$this->lang->words[\'cp_per_go\']}</label>\n				<input class=\'input_text\' type=\"text\" size=\"5\" name=\"pergo\" id=\"pergo\" value=\"{$this->request[\'pergo\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'entered_name\'>{$this->lang->words[\'cp_prune_member\']}</label>\n				<input class=\'input_text\' type=\"text\" size=\"30\" name=\"member\" id=\'entered_name\' value=\"{$this->request[\'member\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'dateline\'>{$this->lang->words[\'cp_prune_days2\']}</label>\n				<input class=\'input_text\' type=\"text\" size=\"5\" name=\"dateline\" id=\"dateline\" value=\"{$this->request[\'dateline\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'posts\'>{$this->lang->words[\'cp_prune_replies\']}</label>\n				<input class=\'input_text\' type=\"text\" size=\"5\" name=\"posts\" id=\"posts\" value=\"{$this->request[\'posts\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'topic_type\'>{$this->lang->words[\'cp_prune_type\']}</label>\n				<select class=\'input_select\' name=\'topic_type\' id=\"topic_type\">\n					<foreach loop=\"types:array( \'open\', \'closed\', \'link\', \'all\' ) as $type\">\n						<option value=\'{$type}\'<if test=\"defaultselectedoption:|:$this->request[\'topic_type\'] == $type\"> selected=\'selected\'</if>>{$this->lang->words[ \'cp_pday_\' . $type ]}</option>\n					</foreach>\n				</select>\n			</li>\n			<li class=\'field\'>\n				<label for=\'cbox\'>{$this->lang->words[\'mps_ignorepin\']}</label>\n				<input class=\'input_check\' type=\"checkbox\" id=\"cbox\" name=\"ignore_pin\" value=\"1\" checked=\"checked\" />\n			</li>\n			<li class=\'field\'>\n				<span class=\'desc\'>{$this->lang->words[\'cp_optional\']}</span>\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'cp_prune_sub1\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showforum={$forum[\'id\']}\" base=\"public\" seotitle=\"{$forum[\'name_seo\']}\" template=\"showforum\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n	</form>\n</div>', 'pruneSplash', '$forum=\"\", $forums_html=\"\", $confirm_data=\"\", $complete_html=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('330', '0', 'skin_mod', '<strong>{$title}</strong><br /> {$msg}', 'simplePage', '$title=\"\", $msg=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('331', '0', 'skin_mod', '{parse js_module=\"moderate\"}\n<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' id=\'mmForm\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'topicchoice\' />\n<input type=\'hidden\' name=\'fromSearch\' value=\'{$this->request[\'fromSearch\']}\' />\n<input type=\'hidden\' name=\'returnUrl\' value=\'{$this->request[\'returnUrl\']}\' />\n<input type=\'hidden\' name=\'return\' value=\'{$this->request[\'return\']}\' />\n<foreach loop=\"$tids as $t\">\n	<input type=\'hidden\' name=\"selectedtids[$t]\" value=\"$t\" />\n</foreach>\n<input type=\'hidden\' name=\'tact\' id=\'mmTact\' value=\'sdelete\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2 class=\'maintitle\'>{parse expression=\"sprintf($this->lang->words[\'mm_delete_top\'], count( $tids ) )\"}</h2>\n<div class=\'ipsBox clearfix\'>\n	<if test=\"$canHardDelete\">\n		<div class=\'ipsBox_container left\' style=\'width: 44%; height: 130px\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlt_remove_from_view\']}</h3>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dltt_remove_from_view_desc\']}<br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlt_remove_from_view_extra\']}</span><br /><br />\n				<input type=\'text\' class=\'input_text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' style=\'width: 60%\'  /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlt_remove\']}\' />\n			</div>\n		</div>\n		<script type=\'text/javascript\'>\n			$(\'delPop_reason\').defaultize(\"{$this->lang->words[\'enter_sdelete_reason\']}\");\n		</script>\n		<div class=\'left\' style=\'width: 10%; margin: 0 0.5%\'>\n			<div class=\'ipsPad ipsForm_center\'>\n				<br /><br /><br />\n				<span style=\'font-size: 32px\'>{$this->lang->words[\'mod_or\']}</span>\n			</div>\n		</div>	\n		<div class=\'ipsBox_container right\' style=\'width: 44%; height: 130px\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlt_delete_from_topic\']}</h3>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dltt_delete_from_topic_desc\']}<br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlt_delete_from_topic_extra\']}</span><br /><br />\n				<input type=\'button\' class=\'input_submit\' onclick=\"$(\'mmTact\').value=\'deletedo\'; $(\'mmForm\').submit();\" value=\'{$this->lang->words[\'dlt_delete_now\']}\' />\n			</div>\n		</div>\n	<else />\n		<div class=\'ipsBox_container\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlt_remove_from_view\']}</h3>\n			<div class=\'ipsPad\'>\n				{$this->lang->words[\'dlt_remove_from_view_desc\']}<br /><br />\n				<input type=\'text\' class=\'input_text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' style=\'width: 60%\'  /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlt_remove\']}\' />\n			</div>\n		</div>\n	</if>\n</div>\n</form>', 'softDeleteSplash', '$forum, $tids=array(), $canHardDelete=false', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('332', '0', 'skin_mod', '{parse js_module=\"moderate\"}\n<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' id=\'mmForm\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'postchoice\' />\n<input type=\'hidden\' name=\'fromSearch\' value=\'{$this->request[\'fromSearch\']}\' />\n<input type=\'hidden\' name=\'returnUrl\' value=\'{$this->request[\'returnUrl\']}\' />\n<input type=\'hidden\' name=\'return\' value=\'{$this->request[\'return\']}\' />\n<foreach loop=\"$pids as $p\">\n	<input type=\'hidden\' name=\"selectedpids[$p]\" value=\"$p\" />\n</foreach>\n<input type=\'hidden\' name=\'tact\' id=\'mmTact\' value=\'sdelete\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2 class=\'maintitle\'>{parse expression=\"sprintf($this->lang->words[\'mm_delete_top_posts\'], count( $pids ) )\"}</h2>\n<div class=\'ipsBox clearfix\'>\n	<if test=\"$canHardDelete\">\n		<div class=\'ipsBox_container left\' style=\'width: 44%; height: 130px\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlp_remove_from_view\']}</h3>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dlp_remove_from_view_desc\']}<br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_remove_from_view_extra\']}</span><br /><br />\n				<input type=\'text\' class=\'input_text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' style=\'width: 60%\'  /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlp_remove\']}\' />\n			</div>\n		</div>\n		<script type=\'text/javascript\'>\n			$(\'delPop_reason\').defaultize(\"{$this->lang->words[\'enter_sdelete_reason\']}\");\n		</script>\n		<div class=\'left\' style=\'width: 10%; margin: 0 0.5%\'>\n			<div class=\'ipsPad ipsForm_center\'>\n				<br /><br /><br />\n				<span style=\'font-size: 32px\'>{$this->lang->words[\'mod_or\']}</span>\n			</div>\n		</div>\n		<div class=\'ipsBox_container right\' style=\'width: 44%; height: 130px\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlp_delete_from_topic\']}</h3>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dlp_delete_from_topic_desc\']}<br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_delete_from_topic_extra\']}</span><br /><br />\n				<input type=\'button\' class=\'input_submit\' onclick=\"$(\'mmTact\').value=\'deletedo\'; $(\'mmForm\').submit();\" value=\'{$this->lang->words[\'dlp_delete_now\']}\' />\n			</div>\n		</div>\n	<else />\n		<div class=\'ipsBox_container\'>\n			<h3 class=\'row2 ipsPad\'>{$this->lang->words[\'dlp_remove_from_view\']}</h3>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dlp_remove_from_view_desc\']}<br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_remove_from_view_extra\']}</span><br /><br />\n				<input type=\'text\' class=\'input_text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' style=\'width: 60%\'  /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlp_remove\']}\' />\n			</div>\n		</div>\n	</if>\n</div>\n</form>', 'softDeleteSplashPosts', '$forum, $topic, $pids=array(), $canHardDelete=false', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('333', '0', 'skin_mod', '{parse js_module=\"moderate\"}\n<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'postchoice\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'tact\' value=\'split\' />\n<input type=\'hidden\' name=\'checked\' value=\'1\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<p class=\'message\'>{$this->lang->words[\'st_explain\']}</p>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'st_top\']}: {$forum[\'name\']} &gt; {$topic[\'title\']}</h2>\n<div class=\'generic_bar\'></div>\n<div class=\'post_form\'>\n	<fieldset>\n		<h3 class=\'bar\'>{$this->lang->words[\'st_new_topic\']}</h3>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'new_title\'>{$this->lang->words[\'mt_new_title\']}</label>\n				<input type=\"text\" size=\"40\" class=\'input_text\' id=\'new_title\' maxlength=\"100\" name=\"title\" value=\"\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'new_forum\'>{$this->lang->words[\'st_forum\']}</label>\n				<select name=\"fid\" id=\'new_forum\' class=\'input_select\'>{$jump}</select>\n			</li>\n		</ul>\n	</fieldset>\n</div>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'st_post\']}</h2>\n<div class=\'generic_bar\'></div>\n<if test=\"splitpostsloop:|:is_array( $posts ) AND count( $posts )\">\n	<foreach loop=\"split_posts:$posts as $row\">\n		<div class=\'post_block topic_summary\'>\n			<h3>{$row[\'author_name\']}</h3>\n			<p class=\'posted_info\'>{$this->lang->words[\'move_posted\']} {$row[\'date\']}</p>\n			<label for=\'checkbox_{$row[\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'st_split\']}</label>\n			<input type=\'checkbox\' id=\'checkbox_{$row[\'pid\']}\' name=\'selectedpids[{$row[\'pid\']}]\' value=\'{$row[\'pid\']}\' class=\'post_mod\' checked=\'checked\' />\n			<div class=\'post_body\'>\n				<div class=\'post\'>{$row[\'post\']}</div>\n			</div>\n		</div>\n	</foreach>\n</if>\n<fieldset class=\'submit\'>\n	<php>\n		$selectedPids	= implode( \',\', $this->request[\'selectedpids\'] );\n	</php>\n	<input type=\"submit\" name=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'st_submit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;selectedpids={$selectedPids}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n</fieldset>\n</form>', 'splitPostForm', '$forum, $topic, $posts, $jump', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('334', '0', 'skin_mod', '<h2 class=\'maintitle\'>{$this->lang->words[\'th_title\']}</h2>\n<table class=\'ipb_table\' summary=\"{$this->lang->words[\'topic_history_summary\']} \'{$topic[\'title\']}\'\">\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 40%\'>{$this->lang->words[\'summary_th_title\']}</th>\n		<th scope=\'col\' style=\'width: 60%\'>{$this->lang->words[\'summary_th_info\']}</th>\n	</tr>\n	<tr class=\'row1\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_topic\']}</td>\n		<td>{$topic[\'title\']}</td>\n	</tr>\n	<tr class=\'row1\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_start_date\']}</td>\n		<td>{parse date=\"$topic[\'start_date\']\" format=\"long\"}</td>\n	</tr>\n	<tr class=\'row2\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_start_name\']}</td>\n		<td>\n			<if test=\"historystarter:|:$topic[\'starter_id\']\">\n				<a href=\'{parse url=\"showuser={$topic[\'starter_id\']}\" base=\"public\" seotitle=\"{$topic[\'seo_first_name\']}\" template=\"showuser\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$topic[\'starter_name\']}</a>\n			<else />\n				{$topic[\'starter_name\']}\n			</if>\n		</td>\n	</tr>\n	<tr class=\'row1\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_last_date\']}</td>\n		<td>{parse date=\"$topic[\'last_post\']\" format=\"long\"}</td>\n	</tr>\n	<tr class=\'row2\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_last_name\']}</td>\n		<td>\n			<if test=\"historylastposter:|:$topic[\'last_poster_id\']\">\n				<a href=\'{parse url=\"showuser={$topic[\'last_poster_id\']}\" base=\"public\" seotitle=\"{$topic[\'seo_last_name\']}\" template=\"showuser\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$topic[\'last_poster_name\']}</a>\n			<else />\n				{$topic[\'last_poster_name\']}\n			</if>\n		</td>\n	</tr>\n	<tr class=\'row1\'>\n		<td class=\'altrow\'>{$this->lang->words[\'th_avg_post\']}</td>\n		<td>{$avg_post}</td>\n	</tr>\n</table>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'ml_title\']}</h2>\n<table class=\'ipb_table\' summary=\"{$this->lang->words[\'mod_logs_topic_summary\']} \'{$topic[\'title\']}\'\">\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'ml_name\']}</th>\n		<th scope=\'col\' style=\'width: 50%\'>{$this->lang->words[\'ml_desc\']}</th>\n		<th scope=\'col\' style=\'width: 25%\'>{$this->lang->words[\'ml_date\']}</th>\n	</tr>\n	<if test=\"topicmodlogs:|:!count($mod_logs) OR !is_array($mod_logs)\">\n		<tr>\n			<td class=\"no_messages\" colspan=\"3\">{$this->lang->words[\'ml_none\']}</td>\n		</tr>\n	<else />\n		{parse striping=\"modlogs\" classes=\"row1,row2\"}\n		<foreach loop=\"mod_logs:$mod_logs as $data\">\n			<tr class=\'{parse striping=\"modlogs\"}\'>\n				<td class=\'altrow\'>\n					<if test=\"modlogmemberid:|:$data[\'member_id\']\">\n						<a href=\'{parse url=\"showuser={$data[\'member_id\']}\" template=\"showuser\" seotitle=\"{$data[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$data[\'member_name\']}</a>\n					<else />\n						{$data[\'member_name\']}\n					</if>\n				</td>\n				<td>{$data[\'action\']}</td>\n				<td class=\"altrow\">{parse date=\"$data[\'ctime\']\" format=\"long\"}</td>\n			</tr>\n		</foreach>\n	</if>\n</table>', 'topicHistory', '$topic, $avg_post, $mod_logs=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('335', '0', 'skin_mod', '<form action=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate\" base=\"public\"}\' method=\'post\'>\n<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n<input type=\'hidden\' name=\'do\' value=\'31\' />\n<input type=\'hidden\' name=\'t\' value=\'{$topic[\'tid\']}\' />\n<input type=\'hidden\' name=\'f\' value=\'{$forum[\'id\']}\' />\n<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n<h2>{$this->lang->words[\'ts_title\']}: {$forum[\'name\']} &gt; {$topic[\'title\']}</h2>\n<p class=\'message\'>{$text}</p>\n<br />\n<fieldset class=\'submit\'>\n	<input type=\"submit\" class=\'input_submit\' value=\"{$this->lang->words[\'ts_submit\']}\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"showtopic={$topic[\'tid\']}\" base=\"public\" seotitle=\"{$topic[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n</fieldset>\n</form>', 'unsubscribeForm', '$forum, $topic, $text', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('336', '0', 'skin_post', '<html>\n<head>\n	<style type=\"text/css\">\n		* {\n			margin: 0px;\n			padding: 0px;\n		}\n		\n		#waitImg {\n			position: relative;\n			top: 4px;\n		}\n	</style>\n	{parse template=\"includeRTL\" group=\"global\" params=\"\"}\n</head>\n<body style=\'background-color: transparent;\'>\n<form id=\'iframeUploadForm\' method=\'post\' enctype=\"multipart/form-data\" action=\'\'>\n<script type=\'text/javascript\'>\n	parent.Debug.write(\"Loaded iframe\");\n	parent.ipb.attach._jsonPass( $id, $JSON );\n</script>\n<input type=\'file\' id=\'iframeUploadBox_{$id}\' style=\'display: inline\' name=\'FILE_UPLOAD\' /> <input type=\'reset\' value=\'{$this->lang->words[\'clear_selection\']}\' style=\'display: inline\' />\n<img src=\"{$this->settings[\'img_url\']}/loading.gif\" style=\'display: none\' id=\"waitImg\" />\n</form>\n</body>\n</html>', 'attachiFrame', '$JSON, $id', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('337', '0', 'skin_post', '<p class=\'message error\'>\n	{$data}\n</p>\n<br />', 'errors', '$data=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('338', '0', 'skin_post', '{parse js_module=\"poll\"}\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.poll.maxQuestions = parseInt( {$data[\'max_poll_questions\']} );\n	ipb.poll.maxChoices = parseInt( {$data[\'max_poll_choices\']} );\n	ipb.poll.isPublicPoll = parseInt( {$data[\'poll_view_voters\']} );\n	ipb.poll.showOnLoad = {$data[\'show_open\']};\n	ipb.poll.isMod = {$data[\'is_mod\']};\n	\n	ipb.poll.questions = \\$H(\n		<if test=\"hasPollQuestions:|:$data[\'poll_questions\'] != \'[]\'\">{$data[\'poll_questions\']}</if>\n	);\n	\n	ipb.poll.choices = \\$H(\n		<if test=\"hasPollChoices:|:$data[\'poll_choices\'] != \'[]\'\">{$data[\'poll_choices\']}</if>\n	);\n	\n	ipb.poll.votes = \\$H(\n		<if test=\"hasPollVotes:|:$data[\'poll_votes\'] != \'[]\'\">{$data[\'poll_votes\']}</if>\n	);\n	\n	ipb.poll.multi = \\$H(\n		<if test=\"hasPollMulti:|:$data[\'poll_multi\'] != \'[]\'\">{$data[\'poll_multi\']}</if>\n	);\n	\n	ipb.templates[\'poll_question\'] = 	new Template(\"<li class=\'ipsBox_container question\' id=\'question_#{qid}_wrap\' style=\'display: none\'>\" +\n											\"<a href=\'#\' class=\'ipsPad right\' id=\'remove_question_#{qid}\' title=\'{$this->lang->words[\'remove_question\']}\'>{parse replacement=\"remove_poll_question\"}</a>\" +\n											\"	<ul class=\'ipsForm ipsForm_vertical question_title ipsPad\'>\"+\n											\"		<li class=\'ipsField\'>\" + \n											\" 			<label for=\'#{qid}\' class=\'ipsType_subtitle\'>{$this->lang->words[\'question_title\']} #{qid}</label>\"+\n											\"			<p class=\'ipsField_content\'>\" +\n											\" 				<input type=\'text\' class=\'input_text\' id=\'#{qid}\' value=\'#{value}\' size=\'62\' maxlength=\'254\' name=\'question[#{qid}]\' /></span> <input type=\'checkbox\' class=\'input_check\' value=\'1\' name=\'multi[#{qid}]\' id=\'multi_#{qid}\'/> <label for=\'multi_#{qid}\'><span class=\'desc lighter\'>{$this->lang->words[\'poll_multichoice\']}</span></label>\" +\n											\"			</p>\" +\n											\"		</li>\"+\n											\"	</ul>\" + \n											\"	<div class=\'wrap ipsPad\'>\" + \n											\"		<ol id=\'choices_for_#{qid}\'></ol>\" + \n											\"		<p class=\'ipsPad poll_control\'><a href=\'#\' class=\'ipsType_small\' id=\'add_choice_#{qid}\' title=\'{$this->lang->words[\'add_poll_choice\']}\'>{parse replacement=\"add_poll_choice\"} {$this->lang->words[\'add_another_choice\']}</a></p>\" +\n											\"	</div>\" +\n											\"</li>\");\n	ipb.templates[\'poll_choice\'] = 		new Template(\"<li id=\'poll_#{qid}_#{cid}_wrap\' style=\'display: none\'><input type=\'text\' id=\'poll_#{qid}_#{cid}\' name=\'choice[#{qid}_#{cid}]\' class=\'input_text\' value=\'#{choice}\' size=\'66\' maxlength=\'254\' /> <input type=\'text\' id=\'poll_#{qid}_#{cid}_votes\' name=\'votes[#{qid}_#{cid}]\' value=\'#{votes}\' class=\'input_text\' size=\'5\' title=\'{$this->lang->words[\'poll_votes_desc\']}\' /> <a href=\'#\' id=\'remove_#{qid}_#{cid}\' title=\'{$this->lang->words[\'remove_choice\']}\'>{parse replacement=\"remove_poll_choice\"}</a></li>\");\n//]]>\n</script>\n\n<div class=\'post_form poll_form\' id=\'poll_form\'>\n	<a href=\'#\' id=\'add_poll\' class=\'ipsType_small\'><img src=\'{$this->settings[\'img_url\']}/bullet_toggle_plus.png\' /> {$this->lang->words[\'poll_manage_link\']}</a>\n	\n	<div id=\'poll_popup_content\' style=\'display: none\'>\n		<div id=\'poll_wrap\'>\n			<h3>{$this->lang->words[\'poll_manager\']}</h3>\n			<div class=\'ipsBox_container ipsPad\'>\n				<label for=\'poll_title\'><strong>{$this->lang->words[\'poll_fs_title\']}</strong></label>&nbsp;&nbsp;\n				<input type=\'text\' class=\'input_text ipsForm_primary\' name=\'poll_question\' id=\'poll_title\' size=\'40\' value=\'{$data[\'poll_question\']}\' />&nbsp;&nbsp;&nbsp;&nbsp;\n				<if test=\"allowPublicPoll:|:$this->settings[\'poll_allow_public\'] AND ! $data[\'poll_total_votes\']\">\n					<span class=\'ipsType_small\' id=\'check_public_poll\' data-tooltip=\"{$this->lang->words[\'poll_public_warning\']}\">\n						<input type=\'checkbox\' class=\'input_check\' name=\'poll_view_voters\' id=\'poll_view_voters\' value=\'1\' <if test=\"viewPollVoters:|:$data[\'poll_view_voters\']\">checked=\'checked\'</if> />\n						<label for=\'poll_view_voters\'>{$this->lang->words[\'poll_fs_public\']}</label>\n					</span>\n				</if>\n				&nbsp;&nbsp;\n				<if test=\"makePollOnly:|:$this->settings[\'ipb_poll_only\']\">\n					<span class=\'ipsType_small\' id=\'check_poll_only\' data-tooltip=\"{$this->lang->words[\'poll_only_desc\']}\">\n						<input type=\'checkbox\' class=\'input_check\' name=\'poll_only\' id=\'poll_only\' value=\'1\' <if test=\"pollOnlyChecked:|:$data[\'poll_only\']\">checked=\'checked\'</if> />\n						<label for=\'poll_only\'>{$this->lang->words[\'poll_only_title\']}</label>\n					</span>\n				</if>\n			</div>\n			<div class=\'ipsBox fixed_inner\' id=\'poll_container_wrap\'>\n				<ul id=\'poll_container\'></ul>\n			</div>\n			<div id=\'poll_footer\' class=\'ipsForm_submit clearfix\' style=\'margin-top: 0;\'>\n				<a id=\'add_new_question\' class=\'ipsButton left\'>{parse replacement=\"add_poll_question\"} {$this->lang->words[\'add_another_question\']}</a> <span class=\'desc ipsType_smaller left ipsPad\' id=\'poll_stats\'></span>\n				<a id=\'close_poll\' class=\'ipsButton no_width right\'>{parse replacement=\"close_poll_form\"} {$this->lang->words[\'close_poll_form\']}</a>\n			</div>\n		</div>\n	</div>\n</div>', 'pollBox', '$data', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('339', '0', 'skin_post', '<if test=\"open_close_perm:|:$formData[\'modOptionsData\'][\'canSetOpenTime\'] == 1 || $formData[\'modOptionsData\'][\'canSetCloseTime\'] == 1\">\n	{parse addtohead=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/calendar_select.css\" type=\"css\"}\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/calendar_date_select/calendar_date_select.js\'></script>\n</if>\n{parse js_module=\"post\"}\n{parse striping=\"post_stripe\" classes=\"row1,row2\"}\n<h1 class=\'ipsType_pagetitle\'>{$formData[\'title\']}</h1>\n<br />\n<!--FORUM RULES-->\n<form id=\'postingform\' action=\'{$this->settings[\'base_url\']}\' method=\'post\' enctype=\'multipart/form-data\'>\n	<div class=\'ipsBox ipsForm_vertical ipsLayout ipsLayout_withright ipsPostForm clearfix\'>\n	    <div class=\'ipsBox_container ipsLayout_right ipsPostForm_sidebar\'>\n			<if test=\"pollboxHtml:|:$formData[\'pollBoxHTML\']\">\n				<h3 class=\'bar\'>{$this->lang->words[\'post_poll\']}</h3>\n				<fieldset id=\'poll_fieldset\' class=\'ipsPad\' style=\'display: none\'>\n					{$formData[\'pollBoxHTML\']}\n				</fieldset>\n				<script type=\'text/javascript\'>\n					$(\'poll_fieldset\').show();\n				</script>\n			</if>\n			<div class=\'ipsPostForm_sidebar_block\'>\n				<h3 class=\'bar\'>{$this->lang->words[\'post_options\']}</h3>\n				<ul class=\'ipsPad ipsForm ipsForm_vertical ipsType_small\'>\n				<if test=\"htmlstatus:|:is_array( $formData[\'checkBoxes\'][\'html\'] ) AND count( $formData[\'checkBoxes\'][\'html\'] )\">\n					<li class=\'ipsField\'>\n						<select name=\"post_htmlstatus\" class=\"input_select\">\n							<option value=\"0\"{$formData[\'checkBoxes\'][\'html\'][0]}>{$this->lang->words[\'pp_nohtml\']}</option>\n							<option value=\"1\"{$formData[\'checkBoxes\'][\'html\'][1]}>{$this->lang->words[\'pp_html1\']}</option>\n							<option value=\"2\"{$formData[\'checkBoxes\'][\'html\'][2]}>{$this->lang->words[\'pp_html2\']}</option>\n						</select>\n					</li>\n				</if>\n					<li class=\'ipsField ipsField_checkbox\'>\n						<input type=\"checkbox\" name=\"enableemo\" class=\"input_check\" value=\"yes\" id=\'enable_emo\' {$formData[\'checkBoxes\'][\'emo\']} />\n						<p class=\'ipsField_content\'>\n							<label for=\'enable_emo\'>{$this->lang->words[\'enable_emo\']}</label>\n						</p>\n					</li>\n				<if test=\"enablesig:|:$this->memberData[\'member_id\']\">\n					<li class=\'ipsField ipsField_checkbox\'>\n						<input type=\"checkbox\" name=\"enablesig\" class=\"input_check\" value=\"yes\" id=\'enable_sig\' {$formData[\'checkBoxes\'][\'sig\']} />\n						<p class=\'ipsField_content\'>\n							<label for=\'enable_sig\'>{$this->lang->words[\'enable_sig\']}</label>\n						</p>\n					</li>\n					<if test=\"tracking:|:$formData[\'checkBoxes\'][\'tra\'] == \'-tracking-\'\">\n						<li class=\'ipsField\'><span class=\'desc\'>{$this->lang->words[\'already_sub\']}</span><li>\n					<else />\n						<li class=\'ipsField ipsField_checkbox\'>\n							<input type=\"checkbox\" name=\"enabletrack\" class=\"input_check\" id=\'enable_track\' value=\"1\" {$formData[\'checkBoxes\'][\'tra\']} />\n							<p class=\'ipsField_content\'>\n								<label for=\'enable_track\'>{$this->lang->words[\'enable_track\']}</label>\n							</p>\n						</li>\n					</if>\n				</if>\n				</ul>\n			</div>\n			<if test=\"showModOptions:|:$formData[\'modOptionsData\'][\'dropDownOptions\'] || $formData[\'modOptionsData\'][\'canSetOpenTime\'] || $formData[\'modOptionsData\'][\'canSetCloseTime\']\">\n				<div class=\'ipsPostForm_sidebar_block\'>\n					<h3 class=\'bar\'>{$this->lang->words[\'moderator_options\']}</h3>\n					<ul class=\'ipsPad ipsForm ipsForm_vertical\'>\n						<if test=\"mod_options_check:|:$formData[\'modOptionsData\'][\'dropDownOptions\'] != \"\"\">\n							<li class=\'ipsField\'>\n								<label for=\'forminput\'><strong>{$this->lang->words[\'after_posting_pf\']}</strong></label>\n								<p class=\'ipsField_content\'>\n									{$formData[\'modOptionsData\'][\'dropDownOptions\']}</select>\n								</p>\n							</li>\n						</if>\n						<if test=\"open_time_check:|:$formData[\'modOptionsData\'][\'canSetOpenTime\'] == 1 \">\n							<li class=\'ipsField\'>\n								<label for=\'mod_open_date\'><strong>{$this->lang->words[\'mod_open_time\']}</strong></label>\n								<p class=\'ipsField_content\'>\n									<input type=\'text\' size=\'7\' name=\'open_time_time\' id=\'mod_open_time\' class=\'date input_text\' value=\'{$formData[\'modOptionsData\'][\'myTimes\'][\'open_time\']}\' />&nbsp;\n									<input type=\'text\' size=\'16\' name=\'open_time_date\' id=\'mod_open_date\' class=\'input_text date\' value=\'{$formData[\'modOptionsData\'][\'myTimes\'][\'open_date\']}\' />\n									<img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'{$this->lang->words[\'generic_date\']}\' id=\'mod_open_date_icon\' class=\'clickable\' />\n								</p>\n							</li>\n						</if>\n						<if test=\"close_time_check:|:$formData[\'modOptionsData\'][\'canSetCloseTime\'] == 1\">\n							<li class=\'ipsField\'>\n								<label for=\'mod_close_date\'><strong>{$this->lang->words[\'mod_close_time\']}</strong></label>\n								<p class=\'ipsField_content\'>\n									<input type=\'text\' size=\'7\' name=\'close_time_time\' id=\'mod_close_time\' class=\'date input_text\' value=\'{$formData[\'modOptionsData\'][\'myTimes\'][\'close_time\']}\' />&nbsp;\n									<input type=\'text\' size=\'16\' name=\'close_time_date\' id=\'mod_close_date\' class=\'date input_text\' value=\'{$formData[\'modOptionsData\'][\'myTimes\'][\'close_date\']}\' />\n									<img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'{$this->lang->words[\'generic_date\']}\' id=\'mod_close_date_icon\' class=\'clickable\' />\n							</li>\n						</if>\n					</ul>\n					<script type=\'text/javascript\'>\n						document.observe(\"dom:loaded\", function(){\n							if( $(\'mod_open_time\') ){ $(\'mod_open_time\').defaultize( \"{$this->lang->words[\'mod_time_format\']}\" ); }\n							if( $(\'mod_open_date\') ){ $(\'mod_open_date\').defaultize( \"{$this->lang->words[\'mod_date_format\']}\" ); }\n							if( $(\'mod_close_time\') ){ $(\'mod_close_time\').defaultize( \"{$this->lang->words[\'mod_time_format\']}\" ); }\n							if( $(\'mod_close_date\') ){ $(\'mod_close_date\').defaultize( \"{$this->lang->words[\'mod_date_format\']}\" ); }\n						});\n					</script>\n				</div>\n			</if>\n			<if test=\"edit_options_check:|:$formData[\'extraData\'][\'showEditOptions\']\">\n				<div class=\'ipsPostForm_sidebar_block\'>\n					<h3 class=\'bar\'>{$this->lang->words[\'edit_options\']}</h3>\n					<ul class=\'ipsPad ipsForm ipsForm_vertical\'>\n						<li class=\'ipsField ipsField_checkbox\'>\n							<input type=\"checkbox\" name=\"add_edit\" value=\"1\" id=\'append_edit\' <if test=\"checkShowEdit:|:$formData[\'extraData\'][\'checked\']\">checked=\"checked\"</if> class=\"input_check\" />\n							<p class=\'ipsField_content\'>\n								<label for=\'append_edit\'>{$this->lang->words[\'append_edit\']}</label>\n							</p>\n						</li>\n						<if test=\"showeditreason:|:$formData[\'extraData\'][\'showReason\']\">\n							<li class=\'ipsField\'>\n								<label for=\'post_edit_reason\'><strong>{$this->lang->words[\'preason_for_edit\']}</strong></label>\n								<p class=\'ipsField_content\'>\n									<input type=\"text\" name=\"post_edit_reason\" id=\'post_edit_reason\' value=\"{$formData[\'extraData\'][\'reasonForEdit\']}\" size=\'30\' maxlength=\'250\' class=\'input_text\' />\n								</p>\n							</li>\n						</if>\n					</ul>\n				</div>\n			</if>\n		</div>\n		<div class=\'ipsBox_container ipsLayout_content\'>\n			<ul class=\'ipsForm ipsForm_vertical ipsPad\'>\n				<if test=\"logged_in_check:|:!$this->memberData[\'member_id\']\">\n					<li class=\'ipsField\'>\n						<label for=\'username\' class=\'ipsField_title\'>{$this->lang->words[\'guest_name\']}</label>\n						<p class=\'ipsField_content\'>\n							<input type=\'text\' name=\'UserName\' id=\'username\' size=\'50\' value=\'{$this->request[\'UserName\']}\' maxlength=\"{$this->settings[\'max_user_name_length\']}\" class=\'input_text\' tabindex=\'0\' />\n						</p>\n					</li>\n					<if test=\"guestCaptcha:|:$formData[\'captchaHTML\']\">\n						{$formData[\'captchaHTML\']}\n					</if>\n				</if>\n				<if test=\"edit_title_check:|:$formData[\'formType\'] == \'new\' OR ( $formData[\'formType\'] == \'edit\' AND $formData[\'canEditTitle\'] )\">\n					<li class=\'ipsField ipsField_primary\'>\n						<label for=\'topic_title\' class=\'ipsField_title\'>{$this->lang->words[\'topic_title\']}</label>\n						<p class=\'ipsField_content\'>\n							<input id=\'topic_title\' class=\'input_text\' type=\"text\" size=\"60\" maxlength=\"{$this->settings[\'topic_title_max_len\']}\" name=\"TopicTitle\" value=\"{$formData[\'topicTitle\']}\" tabindex=\"0\" />\n						</p>\n					</li>\n				</if>\n				<if test=\"edit_tags_check:|:$formData[\'formType\'] == \'new\' OR ( $formData[\'formType\'] == \'edit\')\">\n					<if test=\"hazTag:|:$formData[\'tagBox\']\">\n						<li class=\'ipsField tag_field\'>\n							<label for=\'ipbTags\' class=\'ipsField_title\'>{$this->lang->words[\'topic_tags\']}</label>\n							<p class=\'ipsField_content\'>{$formData[\'tagBox\']}</p>\n						</li>\n					</if>\n				</if>\n		\n				<li class=\'ipsField ipsField_editor\'>\n					<if test=\"statusMsgs:|:is_array($formData[\'statusMsg\']) AND count($formData[\'statusMsg\']) AND strlen($formData[\'statusMsg\'][0])\">\n						<div class=\'message\'>{parse expression=\"implode( \'<br />\', $formData[\'statusMsg\'])\"}</div>\n					</if>\n					{$formData[\'editor\']}\n				</li>				\n			</ul>\n			<if test=\"upload_form_check:|:$formData[\'uploadForm\']\">\n				<fieldset class=\'attachments\'>\n					{$formData[\'uploadForm\']}\n				</fieldset>\n			</if>\n		</div>\n		\n	</div>	\n	<fieldset class=\'submit clear\'>\n		<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n		<input type=\'hidden\' name=\'app\' value=\'forums\' />\n		<input type=\'hidden\' name=\'module\' value=\'post\' />\n		<input type=\'hidden\' name=\'section\' value=\'post\' />\n		<input type=\'hidden\' name=\'do\' value=\'{$form[\'doCode\']}\' />\n		<input type=\'hidden\' name=\'s\' value=\'{$this->member->session_id}\' />\n		<input type=\'hidden\' name=\'p\' value=\'{$form[\'p\']}\' />\n		<input type=\'hidden\' name=\'t\' value=\'{$form[\'t\']}\' />\n		<input type=\'hidden\' name=\'f\' value=\'{$form[\'f\']}\' />\n		<input type=\'hidden\' name=\'parent_id\' value=\'{$form[\'parent\']}\' />\n		<input type=\'hidden\' name=\'attach_post_key\' value=\'{$form[\'attach_post_key\']}\' />\n		<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n		<input type=\'hidden\' name=\'removeattachid\' value=\'0\' />\n		<input type=\'hidden\' name=\'return\' value=\'{$this->request[\'return\']}\' />\n		<input type=\'hidden\' name=\'_from\' value=\'{$this->request[\'_from\']}\' />\n		<input type=\"submit\" name=\"dosubmit\" value=\"{$formData[\'buttonText\']}\" tabindex=\"0\" class=\"input_submit\" accesskey=\"s\"  />&nbsp;\n		<input type=\"submit\" name=\"preview\" value=\"{$this->lang->words[\'button_preview\']}\" tabindex=\"0\" class=\"input_submit alt\" />\n		{$this->lang->words[\'or\']} <if test=\"cancelposting:|:$form[\'t\']\">\n				<a href=\'{parse url=\"showtopic={$form[\'t\']}\" template=\"showtopic\" seotitle=\"{$formData[\'seoTopic\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n			<else />\n				<a href=\'{parse url=\"showforum={$form[\'f\']}\" template=\"showforum\" seotitle=\"{$formData[\'seoForum\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n			</if>\n	</fieldset>\n</form>\n{$formData[\'topicSummary\'][0][\'html\']}', 'postFormTemplate', '$formData=array(), $form = array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('340', '0', 'skin_post', '<if test=\"postpreview:|:$data AND trim($data) != \'<br />\' AND trim($data) != \'<br>\'\">\n	<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n		{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n	</if>\n	<h2 class=\'maintitle\'>{$this->lang->words[\'post_preview\']}</h2>\n	<div class=\'post_block no_sidebar\'>\n		<div class=\'post_wrap ipsBox\' id=\'post_preview\'>\n			<div class=\'ipsBox_container ipsPad\'>\n				<div class=\'post_body\'>\n					<div class=\'post entry-content\'>{$data}</div>\n				</div>\n			</div>\n		</div>\n	</div>\n	<br />\n</if>', 'preview', '$data=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('341', '0', 'skin_post', '{parse js_module=\"topic\"}\n{parse template=\"include_highlighter\" group=\"global\" params=\"\"}\n<br /><br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'topic_summary\']}</h2>\n<div class=\'generic_bar\'></div>\n<div id=\'topic_summary\'>\n<if test=\"topicsummaryposts:|:is_array( $posts ) AND count( $posts )\">\n	<foreach loop=\"posts:$posts as $pid => $data\">\n		<div class=\'post_block no_sidebar topic_summary\'>\n			<div class=\'post_wrap\'>\n				<if test=\"$data[\'member_id\']\">\n					<h3 class=\'row2\'><a href=\'{parse url=\"showuser={$data[\'member_id\']}\" base=\"public\" seotitle=\"{$data[\'members_seo_name\']}\" template=\"showuser\"}\'>{$data[\'author\']}</a></h3>\n				<else />\n					<h3 class=\'row2 guest\'>{$data[\'author\']}</h3>\n				</if>\n				<div class=\'post_body\'>\n					<p class=\'posted_info\'>{$this->lang->words[\'summary_posted\']} {$data[\'date\']}</p>\n					<if test=\"ignoringpost:|:isset( $data[\'_ignored\'] ) && $data[\'_ignored\'] == 1\">\n						<div class=\'post\'>{$this->lang->words[\'ignore_first_line\']} {$data[\'members_display_name\']}.</div>\n					<else />\n						<div class=\"post\">{$data[\'post\']}</div>\n					</if>\n				</div>\n			</div>\n			<br />\n		</div>\n	</foreach>\n</if>\n<p class=\'submit\'>\n	<a href=\'{parse url=\"showtopic={$this->request[\'t\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'review_topic\']}\' id=\'review_topic\'>{$this->lang->words[\'review_topic\']}</a>\n</p>\n</div>', 'topicSummary', '$posts=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('342', '0', 'skin_post', '<if test=\"$this->memberData[\'member_uploader\'] == \'flash\'\">\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/swfupload/swfupload.js\'></script>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/swfupload/plugins/swfupload.swfobject.js\'></script>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/swfupload/plugins/swfupload.cookies.js\'></script>\n	<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/swfupload/plugins/swfupload.queue.js\'></script>\n</if>\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.lang[\'used_space\'] = \"{parse expression=\"sprintf( $this->lang->words[\'used_space_js\'], \"{$stats[\'max_single_upload_human\']}\" )\"}\";\n//]]>\n</script>\n{parse js_module=\"attach\"}\n<div class=\'ipsPad\'>\n	<div id=\'attach_error_box\' class=\'message error\' style=\'display:none\'></div>\n	<input type=\'file\' id=\'nojs_attach_{$id}_1\' class=\'input_upload\' name=\'FILE_UPLOAD\' tabindex=\'1\' />\n	<input type=\'file\' id=\'nojs_attach_{$id}_2\' class=\'input_upload\' name=\'FILE_UPLOAD\' tabindex=\'1\' />\n	\n	<ul id=\'attachments\'><li style=\'display: none\'></li></ul>\n	\n	<div class=\'attach_controls\'>\n		<h2 class=\'ipsType_subtitle\'>{$this->lang->words[\'attach_header\']}</h2>\n		<span id=\'buttonPlaceholder\'></span>\n		<input type=\'button\' id=\'add_files_attach_{$id}\' class=\'ipsType_small ipsButton_secondary attach_button\' value=\'{$this->lang->words[\'attach_selected\']}\' style=\'display: none; clear: both\' tabindex=\'-1\' />\n		&nbsp;&nbsp;<span class=\'desc ipsType_small\' id=\'space_info_attach_{$id}\'>{parse expression=\"sprintf( $this->lang->words[\'used_space\'], \"{$stats[\'space_used_human\']}\", \"{$stats[\'total_space_allowed_human\']}\", \"{$stats[\'max_single_upload_human\']}\")\"}</span>\n		<if test=\"!IN_ACP AND $this->settings[\'uploadFormType\']\">\n			<p class=\'desc lighter ipsType_smaller\' id=\'help_msg\'>\n				<if test=\"flashuploadhelp:|:$this->memberData[\'member_uploader\'] == \'flash\'\">\n					 {$this->lang->words[\'trouble_uploading\']} <a href=\'#\' data-switch=\'default\' title=\'{$this->lang->words[\'switch\']}\' tabindex=\'1\'>{$this->lang->words[\'switch_to_basic\']}</a>\n				<else />\n					<a href=\'#\' data-switch=\'flash\' title=\'{$this->lang->words[\'switch\']}\' tabindex=\'-1\'>{$this->lang->words[\'switch_to_advanced\']}</a>\n				</if>\n			</p>\n		</if>\n	</div>\n	\n</div>\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.delegate.register(\"[data-switch]\", function(e, elem){\n		ipb.attach.switchUploadType( elem.readAttribute(\'data-switch\') );\n	});\n	\n	// Show the button and info\n	$(\'add_files_attach_{$id}\').show();\n	$(\'space_info_attach_{$id}\').show();\n	\n	var useType = \'default\';\n	var uploadURL = ipb.vars[\'base_url\'] + \"app=core&module=attach&section=attach&do=attachiFrame&attach_rel_module={$type}&attach_rel_id={$id}&attach_post_key={$post_key}&forum_id={$forum_id}&attach_id=attach_{$id}&fetch_all=1\";\n	if ( ipb.vars[\'use_swf_upload\'] && ( jimAuld.utils.flashsniffer.meetsMinVersion( 9 ) && ( ipb.vars[\'swfupload_enabled\'] ) ) )\n	{\n		useType = \'swf\';\n		var uploadURL = \"{parse url=\"app=core&module=attach&section=attach&do=attach_upload_process&attach_rel_module={$type}&attach_rel_id={$id}&attach_post_key={$post_key}&forum_id={$forum_id}&_nsc=1&s={$this->memberData[\'publicSessionID\']}\" base=\"public\"}\";\n	}\n	\n	ipb.attach.template = \"<li id=\'ali_[id]\' class=\'attach_row\' style=\'display: none\'><div><h4 class=\'attach_name\'>[name]</h4><p class=\'info\'>[info]</p><span class=\'img_holder\'></span><p class=\'progress_bar\'><span style=\'width: 0%\'>0%</span></p><p class=\'links\'><a href=\'#\' class=\'add_to_post\' title=\'{$this->lang->words[\'attach_button_title\']}\' tabindex=\'-1\'>{$this->lang->words[\'attach_button\']}</a> | <a href=\'#\' class=\'cancel delete\' title=\'{$this->lang->words[\'attach_delete_title\']}\' tabindex=\'-1\'>{$this->lang->words[\'attach_delete\']}</a></p></div></li>\"; \n	document.observe(\'dom:loaded\', function(){\n		ipb.attach.registerUploader( \'attach_{$id}\', useType, \'attachments\', {\n			\'upload_url\': uploadURL,\n			\'attach_rel_module\': \"{$type}\",\n			\'attach_rel_id\': \"{$id}\",\n			\'attach_post_key\': \"{$post_key}\",\n			\'forum_id\': \"{$forum_id}\",\n			\'file_size_limit\': \"{$stats[\'max_single_upload\']}\"\n		} )});\n//]]>\n</script>', 'uploadForm', '$post_key=\"\",$type=\"\",$stats=array(),$id=\"\",$forum_id=0', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('343', '0', 'skin_topic', '<h3>{$this->lang->words[\'dlp_title\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<h4 class=\'row2 ipsPad\'><strong>{$this->lang->words[\'dlp_remove_from_view\']}</strong></h4>\n		<div class=\'ipsPad ipsForm_center\'>\n			{$this->lang->words[\'dlp_remove_from_view_desc\']}<br />\n			<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_remove_from_view_extra\']}</span><br /><br />\n			<form action=\'#{removeUrl}\' method=\'POST\'>\n				<input type=\'text\' name=\'deleteReason\' id=\'delPop_reason\' value=\'\' class=\'input_text\' style=\'width: 60%\' /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'dlp_remove\']}\' />\n			</form>\n		</div>\n	</div>\n	<if test=\"$this->registry->class_forums->canHardDeletePosts( $this->request[\'id\'], $topic )\">\n		<div class=\'ipsPad ipsForm_center\' style=\'font-size: 32px\'>\n			{$this->lang->words[\'dlp_or\']}\n		</div>\n		<div class=\'ipsBox_container\'>\n			<h4 class=\'row2 ipsPad\'><strong>{$this->lang->words[\'dlp_delete_from_topic\']}</strong></h4>\n			<div class=\'ipsPad ipsForm_center\'>\n				{$this->lang->words[\'dlp_delete_from_topic_desc\']}</br />\n				<span class=\'desc lighter ipsType_smaller\'>{$this->lang->words[\'dlp_delete_from_topic_extra\']}</span><br /><br />\n				<input type=\'button\' class=\'input_submit\' onclick=\"window.location=\'#{permaUrl}\';\" value=\'{$this->lang->words[\'dlp_delete_now\']}\' />\n			</div>\n		</div>\n	</if>\n</div>', 'ajax__deletePost', '', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('344', '0', 'skin_topic', '<ul class=\'ipbmenu_content\'>	\n	<li class=\'clearfix\'>\n		<a href=\'#\' data-clicklaunch=\'ignoreUsersSig\' data-scope=\'ipb.topic\' data-id=\"{$post[\'member_id\']}\">{parse expression=\"sprintf( $this->lang->words[\'ignore_userx_signature\'], $post[\'members_display_name\'] )\"}</a>\n	</li>\n	<li class=\'clearfix\'>\n		<a href=\'#\' data-clicklaunch=\'ignoreUsersSig\' data-scope=\'ipb.topic\' data-id=\"all\">{$this->lang->words[\'ignore_all_signatures\']}</a>\n	</li>\n</ul>', 'ajaxSigCloseMenu', '$post', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('345', '0', 'skin_topic', '{parse js_module=\"topic\"}\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'announce_title\']}: {$announce[\'announce_title\']}</h1>\n<br />\n<h2 class=\'maintitle\'>{$this->lang->words[\'posted_by\']} \n	<if test=\"announceMember:|:$author[\'member_id\']\">\n		<span class=\"author vcard\"><a class=\"url fn\" href=\'{parse url=\"showuser={$author[\'member_id\']}\" template=\"showuser\" seotitle=\"{$author[\'members_seo_name\']}\" base=\"public\"}\'>{$author[\'members_display_name\']}</a></span>\n	<else />\n		{$author[\'members_display_name\']}\n	</if>\n</h2>\n<div class=\'post_block first hentry announcement\' id=\'announce_id_{$announce[\'announce_id\']}\'>\n	<div class=\'post_wrap\'>\n		<br />\n		<div class=\'author_info\'>\n			{parse template=\"userInfoPane\" group=\"global\" params=\"$author, \'announcement\', array()\"}\n		</div>\n		<div class=\'post_body\'>\n			<div class=\'post entry-content\'>\n				{$announce[\'announce_post\']}\n			</div>\n			<ul class=\'post_controls clear clearfix\'>\n				<if test=\"canmanage:|:$this->memberData[\'g_is_supmod\'] == 1\">\n					<li class=\'post_edit\'><a class=\'ipsButton_secondary\' href=\'{parse url=\"app=core&amp;module=modcp&amp;tab=announcements&amp;fromapp=forums&amp;_do=edit&amp;announce_id={$announce[\'announce_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'post_edit_announce\']}\' class=\'edit_post\'>{$this->lang->words[\'post_edit_announce\']}</a></li>\n				</if>\n			</ul>\n		</div>\n	</div>			\n</div>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}', 'announcement_show', '$announce=\"\",$author=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('346', '0', 'skin_topic', '<if test=\"fbAppIdPresent:|:$this->settings[\'fbc_appid\']\">\n<if test=\"checkAccess:|:$this->registry->getClass(\'class_forums\')->guestCanSeeTopic($this->request[\'f\'], $this->settings[\'fbc_bot_group\'])\">\n<br />\n<div class=\'left facebook-like\'>\n	<fb:like href=\"{$this->registry->getClass(\'output\')->fetchRootDocUrl()}\" layout=\"standard\" show_faces=\"false\" width=\"450\" action=\"like\" colorscheme=\"light\" />\n</div>\n<div id=\"fb-root\"></div>\n<script>\n  window.fbAsyncInit = function() {\n    FB.init({appId: \'{$this->settings[\'fbc_appid\']}\', status: true, cookie: true,\n             xfbml: true});\n  };\n  (function() {\n    var e = document.createElement(\'script\'); e.async = true;\n    e.src = document.location.protocol +\n      \'//connect.facebook.net/{$this->settings[\'fb_locale\']}/all.js\';\n    document.getElementById(\'fb-root\').appendChild(e);\n  }());\n</script>\n</if>\n</if>', 'hookFacebookLike', '', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('347', '0', 'skin_topic', '{parse js_module=\"like\"}\n<div class=\'__like right\' data-app=\"{$data[\'app\']}\" data-area=\"{$data[\'area\']}\" data-relid=\"{$relId}\" data-isfave=\"{$data[\'iLike\']}\">\n	{parse template=\"likeSummaryContents\" group=\"topic\" params=\"$data, $relId, $opts\"}\n</div>\n<script type=\"text/javascript\">\n	var FAVE_TEMPLATE = new Template( \"<h3>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_title\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}</h3><div class=\'ipsPad\'><span class=\'desc\'>{parse expression=\"sprintf( $this->lang->words[\'unset_fave_words\'], $this->lang->words[\'like_un\' . $data[\'vernacular\'] ])\"}</span><br /><p class=\'ipsForm_center\'><input type=\'button\' value=\'{parse expression=\"sprintf( $this->lang->words[\'unset_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}\' class=\'input_submit _funset\' /></p></div>\");\n</script>', 'likeSummary', '$data, $relId, $opts', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('348', '0', 'skin_topic', '<span class=\'ipsButton_extra right <if test=\"$data[\'totalCount\']\">_fmore clickable</if>\' title=\'{parse expression=\"sprintf( $this->lang->words[\'like_totalcount_\' . $data[\'vernacular\'] ], $data[\'totalCount\'] )\"}\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'like_totalcount_\' . $data[\'vernacular\'] ], $data[\'totalCount\'] )\"}\"><img src=\'{$this->settings[\'img_url\']}/icon_users.png\' /> <strong>{$data[\'totalCount\']}</strong></span>\n<if test=\"likeOnlyMembers:|:$this->memberData[\'member_id\']\">\n	<a href=\'#\' title=\"<if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'fave_tt_on\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'fave_tt_off\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if>\" class=\'ftoggle ipsButton_secondary\'><if test=\"$data[\'iLike\']\">{parse expression=\"sprintf( $this->lang->words[\'unset_fave_button\'], $this->lang->words[\'like_ucfirst_un\' . $data[\'vernacular\'] ])\"}<else />{parse expression=\"sprintf( $this->lang->words[\'set_fave_button\'], $this->lang->words[\'like_ucfirst_\' . $data[\'vernacular\'] ])\"}</if></a>\n</if>', 'likeSummaryContents', '$data, $relId, $opts=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('349', '0', 'skin_topic', '<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.templates[\'poll_voters\'] = new Template(\"<h3 class=\'bar\'>{$this->lang->words[\'poll_voted_for\']} #{title}</h3><div class=\'ipsPad\'>#{content}</div>\");\n//]]>\n</script>\n<div class=\'general_box alt poll\' id=\'poll_{$poll[\'pid\']}\'>\n	<form action=\"{parse url=\"app=forums&amp;module=extras&amp;section=vote&amp;t={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}&amp;do=add&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\" name=\'pollForm\' method=\"post\">\n		<h3>{$this->lang->words[\'poll\']} {$poll[\'poll_question\']}<if test=\"showPollResults:|:$showResults\"> <span class=\'desc\'>({$poll[\'_totalVotes\']} {$this->lang->words[\'poll_vote_casted\']})</span></if></h3>\n		<if test=\"publicPollNotice:|:$this->settings[\'poll_allow_public\'] AND $poll[\'poll_view_voters\'] AND ! $showResults\">\n			<div class=\'message unspecified\'>{$this->lang->words[\'poll_public_notice\']}</div>\n		</if>\n		<foreach loop=\"poll_questions:$pollData as $questionID => $questionData\">\n			<div class=\'poll_question<if test=\"votedClass:|:$showResults\"> voted</if>\'>\n				<h4 class=\'rounded\'>{$pollData[ $questionID ][\'question\']}</h4>\n				<if test=\"noGuestVote:|:! $this->settings[\'allow_result_view\'] AND ! $this->memberData[\'member_id\']\">\n					{$this->lang->words[\'poll_noview_guest\']}\n				<else />\n					<ol>\n						<foreach loop=\"poll_choices:$pollData[ $questionID ][\'choices\'] as $choiceID => $choiceData\">\n							<if test=\"showingResults:|:$showResults\">\n								<li>\n									<span class=\'answer\'><if test=\"hasVoters:|:is_array( $choiceData[\'voters\'] ) AND in_array( $this->memberData[\'member_id\'], array_keys( $choiceData[\'voters\'] ) )\"> {parse replacement=\"your_vote\"} </if>{$choiceData[\'choice\']}</span>\n									<if test=\"viewVoters:|:$poll[\'poll_view_voters\'] AND is_array( $choiceData[\'voters\'] ) AND $this->settings[\'poll_allow_public\'] AND $choiceData[\'votes\']\">\n										<a href=\'#\' class=\'votes\' id=\'l_voters_{$questionID}_{$choiceID}\' title=\'{$this->lang->words[\'poll_view_voters\']}\'>({$choiceData[\'votes\']} {$this->lang->words[\'poll_votes\']} [{$choiceData[\'percent\']}%] - <strong>{$this->lang->words[\'poll_view\']}</strong>)</a>\n									<else />\n										<span class=\'votes\'> ({$choiceData[\'votes\']} {$this->lang->words[\'poll_votes\']} [{$choiceData[\'percent\']}%])</span>\n									</if>\n									<if test=\"votersJs:|:$poll[\'poll_view_voters\'] AND is_array( $choiceData[\'voters\'] ) AND $this->settings[\'poll_allow_public\'] AND $choiceData[\'votes\']\">\n										<script type=\'text/javascript\'>\n											$(\'l_voters_{$questionID}_{$choiceID}\').observe(\'click\', ipb.topic.showVoters.bindAsEventListener( this, {$questionID}, {$choiceID} ) );\n											if( Object.isUndefined( ipb.topic.poll[ $questionID ] ) ){\n												ipb.topic.poll[ $questionID ] = [];\n											}\n											\n											var users = \"\";\n											\n											<foreach loop=\"poll_voters:$choiceData[\'voters\'] as $id => $member\">\n												users += \"<a href=\'{parse url=\"showuser={$member[\'member_id\']}\" base=\"public\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\"}\'>{$member[\'members_colored_name\']}</a><if test=\"lastVoter:|:$member[\'_last\'] == 0\">, </if>\";\n											</foreach>\n											ipb.topic.poll[ $questionID ][ $choiceID ] = { name: \"{$choiceData[\'choice\']}\", users: users};\n										</script>\n									</if>\n									<p class=\'progress_bar topic_poll\' title=\'{$this->lang->words[\'poll_percent_of_vote\']} {$choiceData[\'percent\']}%\'>\n										<span style=\'width: {$choiceData[\'percent\']}%\'><span>{$this->lang->words[\'poll_percent_of_vote\']} {$choiceData[\'percent\']}%</span></span>\n									</p>\n								</li>\n							<else />\n								<if test=\"multiVote:|:$choiceData[\'type\'] == \'multi\'\">\n									<li><input type=\'checkbox\' id=\'choice_{$questionID}_{$choiceID}\' name=\'choice_{$questionID}_{$choiceID}\' value=\'1\' class=\'input_check\' /> <label for=\'choice_{$questionID}_{$choiceID}\'>{$choiceData[\'choice\']}</label></li>\n								<else />\n									<li><input type=\'radio\' name=\'choice[{$questionID}]\' id=\'choice_{$questionID}_{$choiceID}\' class=\'input_radio\' value=\'{$choiceID}\' /> <label for=\'choice_{$questionID}_{$choiceID}\'>{$choiceData[\'choice\']}</label></li>\n								</if>\n							</if>\n						</foreach>\n					</ol>\n				</if>\n			</div>\n		</foreach>\n		<fieldset class=\'submit\'>\n			<legend>{$this->lang->words[\'poll_vote\']}</legend>\n			<if test=\"voteButton:|:$topicData[\'state\'] != \'closed\'\">\n				<if test=\"voteButtonMid:|:$this->memberData[\'member_id\']\">\n					<if test=\"voteButtonVoted:|:$poll[\'_memberVoted\']\">\n						<if test=\"deleteVote:|:$this->settings[\'poll_allow_vdelete\'] OR $this->memberData[\'g_is_supmod\']\">\n							<a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=vote&amp;t={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}&amp;do=delete&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'poll_delete_vote\']}\' id=\'poll_deletevote\' class=\'input_submit alt\'>{$this->lang->words[\'poll_delete_vote\']}</a>\n						<else />\n							{$this->lang->words[\'poll_you_voted\']}\n						</if>\n					<else />\n						<if test=\"youCreatedPoll:|:($poll[\'starter_id\'] == $this->memberData[\'member_id\']) and ($this->settings[\'allow_creator_vote\'] != 1)\">\n							{$this->lang->words[\'poll_you_created\']}\n						<else />\n							<!-- VOTE Button -->\n							<if test=\"cast:|:$this->request[\'mode\'] != \'show\'\">\n								<input class=\'input_submit\' type=\"submit\" name=\"submit\" value=\"{$this->lang->words[\'poll_add_vote\']}\" title=\"{$this->lang->words[\'tt_poll_vote\']}\" />\n							</if>\n							<!-- SHOW Button -->\n							<if test=\"displayVotes:|:$this->settings[\'allow_result_view\'] == 1\">\n								<if test=\"alreadyDisplayVotes:|:$this->request[\'mode\'] == \'show\'\">\n									<if test=\"viewVotersLink:|:! $poll_view_voters\">\n										<a href=\'{parse url=\"showtopic={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}\" base=\"public\" seotitle=\"{$topicData[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'tt_poll_svote\']}\' id=\'poll_nullvote\' class=\'input_submit alt\'>{$this->lang->words[\'pl_show_vote\']}</a>\n									</if>\n								<else />\n									<a href=\'{parse url=\"showtopic={$topicData[\'tid\']}&amp;mode=show&amp;st={$this->request[\'st\']}\" base=\"public\" seotitle=\"{$topicData[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'tt_poll_show\']}\' id=\'poll_showresults\' class=\'input_submit alt\'>{$this->lang->words[\'pl_show_results\']}</a>\n								</if>\n							<else />\n								<input class=\'input_submit\' type=\"submit\" name=\"nullvote\" value=\"{$this->lang->words[\'poll_null_vote\']}\" title=\"{$this->lang->words[\'tt_poll_null\']}\" />\n							</if>\n						</if>\n					</if>\n				<else />\n					{$this->lang->words[\'poll_no_guests\']}\n				</if>\n			</if>\n			<if test=\"editPoll:|:$editPoll\">\n				<a href=\'{parse url=\"app=forums&amp;module=post&amp;section=post&amp;do=edit_post&amp;f={$poll[\'forum_id\']}&amp;t={$poll[\'tid\']}&amp;p={$topicData[\'topic_firstpost\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'poll_edit\']}\' class=\'input_submit alt\' >{$this->lang->words[\'poll_edit\']}</a>\n			</if>\n		</fieldset>\n	</form>\n</div>', 'pollDisplay', '$poll, $topicData, $forumData, $pollData, $showResults, $editPoll=1', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('350', '0', 'skin_topic', '<!--post:{$post[\'post\'][\'pid\']}-->\n<if test=\"sDeleted:|:$post[\'post\'][\'_isDeleted\'] AND $post[\'post\'][\'_softDeleteSee\']\">\n	{parse template=\"softDeletedPostBit\" group=\"topic\" params=\"$post, $displayData[\'sdData\'], $topic\"}\n</if>\n<if test=\"sDeletedNot:|:! $post[\'post\'][\'_isDeleted\']\">\n	<div class=\'post_block hentry clear clearfix <if test=\"postQueued:|:$post[\'post\'][\'_isHidden\']\">moderated</if>\' id=\'post_id_{$post[\'post\'][\'pid\']}\'>\n		<a id=\'entry{$post[\'post\'][\'pid\']}\'></a>\n		<if test=\"repIgnored:|:!empty( $post[\'post\'][\'_repignored\'] ) AND $post[\'post\'][\'_repignored\'] == 1 && $post[\'post\'][\'_ignored\'] != 1\">\n			<div class=\'post_ignore\'>\n				<if test=\"noRep:|:$post[\'post\'][\'rep_points\'] == 0\">\n					<span class=\'reputation zero\' title=\'{$this->lang->words[\'top_rep\']}\'>\n				</if>\n				<if test=\"posRep:|:$post[\'post\'][\'rep_points\'] > 0\">\n					<span class=\'reputation positive\' title=\'{$this->lang->words[\'top_rep\']}\'>\n				</if>\n				<if test=\"negRep:|:$post[\'post\'][\'rep_points\'] < 0\">\n					<span class=\'reputation negative\' title=\'{$this->lang->words[\'top_rep\']}\' >\n				</if>\n						{$post[\'post\'][\'rep_points\']}</span> {$this->lang->words[\'top_this_post_by\']} <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {$this->lang->words[\'top_below_thresh\']}. <a href=\'#\' title=\'{$this->lang->words[\'ignore_view_post\']}\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n			</div>\n		</if>\n	\n		<if test=\"userIgnored:|:$post[\'post\'][\'_repignored\'] == 1 || $post[\'post\'][\'_ignored\']\">\n			<div class=\'post_ignore\'>\n				<if test=\"userIgnoredLang:|:$post[\'post\'][\'_repignored\'] == 1\">{$this->lang->words[\'post_ignored_rep\']}<else />{$this->lang->words[\'post_ignored\']}</if> <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a>. <a href=\'#entry{$post[\'post\'][\'pid\']}\' title=\'{$this->lang->words[\'ignore_view_post\']}\' style=\'display: none\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n				<if test=\"userIgnoredLangTwo:|:$this->settings[\'reputation_enabled\'] AND $post[\'post\'][\'_repignored\'] == 1\"><div><a href=\"{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;st={$this->request[\'st\']}&amp;rep_filter_set=*&amp;rep_filter=update&amp;secure_key={$this->member->form_hash}\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\">{$this->lang->words[\'post_ignore_reset_rep\']}</a></div></if>\n			</div>\n		</if>\n		<div class=\'post_wrap\' <if test=\"isNotIgnoring:|:$post[\'post\'][\'_ignored\'] == 1 || $post[\'post\'][\'_repignored\'] == 1\">style=\'display: none\'</if>>\n			<if test=\"postMid:|:$post[\'author\'][\'member_id\']\">\n				<h3 class=\'row2\'>\n			<else />\n				<h3 class=\'guest row2\'>\n			</if>\n				<if test=\"postModCheckbox:|:$this->memberData[\'is_mod\']\">\n					<span class=\'right\'>\n						<label for=\'checkbox_{$post[\'post\'][\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$post[\'post\'][\'pid\']}\' name=\'selectedpids[]\' value=\'{$post[\'post\'][\'pid\']}\' class=\'post_mod right\'<if test=\"postModSelected:|:!empty( $post[\'post\'][\'_pid_selected\'] )\"> checked=\'checked\'</if> />\n					</span>\n				</if>\n				<span class=\'post_id right ipsType_small desc blend_links\'><a href=\'{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;view=findpost&amp;p={$post[\'post\'][\'pid\']}\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\' rel=\'bookmark\' title=\'{$this->lang->words[\'link_to_post\']} #{$post[\'post\'][\'post_count\']}\'>#{$post[\'post\'][\'post_count\']}</a></span>\n				<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n					<span class=\"author vcard\">{parse template=\"userHoverCard\" group=\"global\" params=\"$post[\'author\']\"}</span>\n				<else />\n					{$post[\'author\'][\'members_display_name\']}\n				</if>\n			\n				<if test=\"postIp:|:$post[\'post\'][\'_show_ip\']\">\n					<span class=\'ip right ipsType_small\'>({$this->lang->words[\'ip\']}:\n					<if test=\"postAdmin:|:$post[\'author\'][\'g_access_cp\']\">\n						<em>{$this->lang->words[\'ip_private\']}</em>\n					<else />\n						<if test=\"accessModCP:|:$this->memberData[\'g_is_supmod\']\"><a href=\"{parse url=\"app=core&amp;module=modcp&amp;fromapp=members&amp;tab=iplookup&amp;ip={$post[\'post\'][\'ip_address\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'info_about_this_ip\']}\'>{$post[\'post\'][\'ip_address\']}</a><else />{$post[\'post\'][\'ip_address\']}</if>\n					</if>)\n					</span>\n				</if>\n			</h3>\n			<div class=\'author_info\'>\n				{parse template=\"userInfoPane\" group=\"global\" params=\"$post[\'author\'], $post[\'post\'][\'pid\'], array( \'isTopicView\' => true )\"}\n			</div>\n			<div class=\'post_body\'>\n				<p class=\'posted_info desc lighter ipsType_small\'>\n					{$this->lang->words[\'posted\']} <abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $post[\'post\'][\'post_date\'] )\"}\">{parse date=\"$post[\'post\'][\'post_date\']\" format=\"long\"}</abbr>\n				</p>\n				<if test=\"repHighlight:|:$this->settings[\'reputation_highlight\'] AND $post[\'post\'][\'rep_points\'] >= $this->settings[\'reputation_highlight\']\">\n					<p class=\'rep_highlight\'>{parse replacement=\"popular_post\"}<br />{$this->lang->words[\'popular_post\']}</p>\n				</if>\n				<div class=\'post entry-content <if test=\"$post[\'post\'][\'_repignored\'] == 1\">imgsize_ignore</if>\'>\n					{$post[\'post\'][\'post\']}\n					{$post[\'post\'][\'attachmentHtml\']}\n					<br />\n					<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n						<p class=\'edit\'>\n							{$post[\'post\'][\'edit_by\']}\n							<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n								<br />\n								<span class=\'reason\'>{$post[\'post\'][\'post_edit_reason\']}</span>\n							</if>\n						</p>\n					</if>\n				</div>\n				{parse template=\"repButtons\" group=\"global_other\" params=\"$post[\'author\'], array_merge( array( \'primaryId\' => $post[\'post\'][\'pid\'], \'domLikeStripId\' => \'like_post_\' . $post[\'post\'][\'pid\'], \'domCountId\' => \'rep_post_\' . $post[\'post\'][\'pid\'], \'app\' => \'forums\', \'type\' => \'pid\', \'likeFormatted\' => $post[\'post\'][\'like\'][\'formatted\'] ), $post[\'post\'] )\"}\n				<if test=\"postSignature:|:$post[\'post\'][\'signature\']\">\n					{$post[\'post\'][\'signature\']}\n				</if>\n			\n				<ul class=\'post_controls clear clearfix\'>\n					<li class=\'top hide\'><a href=\'#ipboard_body\' class=\'top\' title=\'{$this->lang->words[\'back_top\']}\'>{$this->lang->words[\'back_top\']}</a></li>\n					<if test=\"replyButton:|:$post[\'post\'][\'_canReply\']\">\n						<li><a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\"  class=\'_ips_trigger_quote ipsButton_secondary\' pid=\"{$post[\'post\'][\'pid\']}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{$this->lang->words[\'post_reply\']}</a></li>\n						<if test=\"multiquote:|:!empty( $post[\'post\'][\'_mq_selected\'] )\">\n							<li class=\'selected multiquote\' id=\'multiq_{$post[\'post\'][\'pid\']}\' style=\'display: none\'>\n						<else />\n							<li class=\'multiquote\' id=\'multiq_{$post[\'post\'][\'pid\']}\' style=\'display: none\'>\n						</if>\n							<a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'quote_with_mq\']}\" class=\'ipsButton_secondary\'>{$this->lang->words[\'mq\']}</a>\n						</li>\n					</if>\n					<if test=\"canEdit:|:$post[\'post\'][\'_can_edit\'] === TRUE\">\n						<li class=\'post_edit\'><a href=\'{parse url=\"module=post&amp;section=post&amp;do=edit_post&amp;f={$topic[\'forum_id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_edit_title\']}\' class=\'edit_post\' id=\'edit_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'post_edit\']}</a></li>\n					</if>\n					<if test=\"canDelete:|:$post[\'post\'][\'_can_delete\'] === TRUE OR $post[\'post\'][\'_softDelete\']\">\n						<li class=\'post_del\' id=\'del_post_{$post[\'post\'][\'pid\']}\'>\n							<a href=\'{parse url=\"module=moderate&amp;section=moderate&amp;do=postchoice&amp;tact=delete&amp;f={$topic[\'forum_id\']}&amp;t={$topic[\'tid\']}&amp;selectedpids[]={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'delete_post\'>{$this->lang->words[\'post_delete\']}</a>\n						</li>\n					</if>\n					<if test=\"approvePost:|:$this->memberData[\'is_mod\']\">\n						<li class=\'post_toggle toggle_post\' id=\'toggle_post_{$post[\'post\'][\'pid\']}\' style=\'display: none\'>\n							<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=postchoice&amp;tact=<if test=\"!$post[\'post\'][\'queued\']\">unapprove<else />approve</if>&amp;selectedpids[{$post[\'post\'][\'pid\']}]={$post[\'post\'][\'pid\']}&amp;t={$topic[\'tid\']}&amp;f={$forum[\'id\']}&amp;auth_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'post_toggle_visible\']}\'><span id=\'toggletext_post_{$post[\'post\'][\'pid\']}\'><if test=\"approveUnapprove:|:$post[\'post\'][\'queued\']==1\">{$this->lang->words[\'post_approve\']}<else />{$this->lang->words[\'post_unapprove\']}</if></span></a>\n						</li>\n					</if>\n					<if test=\"hasblog:|:$this->settings[\'blog_allow_bthis\'] AND $this->memberData[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) AND $post[\'post\'][\'_canReply\']\">\n						<li>\n							<a href=\'{parse url=\"app=blog&amp;blog_this=forums&amp;id1={$this->request[\'t\']}&amp;id2={$post[\'post\'][\'pid\']}\" base=\"public\"}\'>{$this->lang->words[\'blog_this\']}</a>\n						</li>\n					</if>\n					<if test=\"canReportPost:|:$topic[\'_canReport\'] and ( $this->memberData[\'member_id\'] )\">\n						<li class=\'report\'>\n							<a href=\'{parse url=\"app=core&amp;module=reports&amp;rcom=post&amp;tid={$this->request[\'t\']}&amp;pid={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"public\"}\'>{$this->lang->words[\'report\']}</a>\n						</li>\n						<if test=\"postIsReported:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n							<li class=\'report\'>\n								<a href=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;section=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']}\" id=\'post-report-{$post[\'post\'][\'pid\']}\' class=\'ipbmenu\'> <span id=\"rstat-{$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'info\'][\'id\']}\"><img src=\"{$this->settings[\'img_url\']}/reports/post_alert_{$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'gfx\']}.png\" alt=\"\" /></span> </a>\n							</li>\n						</if>\n					</if>\n				</ul>\n				<if test=\"reportedPostData:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n					<ul id=\'post-report-{$post[\'post\'][\'pid\']}_menucontent\' class=\'ipbmenu_content report_menu\'>\n						<li><a href=\"{parse url=\"app=core&amp;module=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'info\'][\'id\']}\" base=\"public\"}\" id=\'report_mark_{$post[\'post\'][\'pid\']}\'><img src=\'{$this->settings[\'img_url\']}/reports/mark_complete.png\' alt=\'\' /> {$this->lang->words[\'report_menu_mark_complete\']}</a></li>\n						<li><a href=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;section=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']}\"><img src=\'{$this->settings[\'img_url\']}/reports/view_report.png\' alt=\'\' /> {$this->lang->words[\'report_menu_view_report\']}</a></li>\n					</ul>\n					<script type=\"text/javascript\">\n						$(\'report_mark_{$post[\'post\'][\'pid\']}\').observe(\'click\',\n						 	ipb.global.updateReportStatus.bindAsEventListener( 	\n								this, {$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']},2,2\n							)\n						);\n					</script>\n				</if>	\n			</div>\n		</div>\n	</div>\n</if>\n		\n		<if test=\"initIgnoredPost:|:$post[\'post\'][\'_repignored\'] == 1 || $post[\'post\'][\'_ignored\']\">\n			<script type=\'text/javascript\'>\n				ipb.topic.setPostHidden( {$post[\'post\'][\'pid\']} );\n				$(\'unhide_post_{$post[\'post\'][\'pid\']}\').show();\n			</script>\n		</if>\n		<hr />\n		\n		<if test=\"adCodeCheck:|:$post[\'post\'][\'_adCode\']\">\n			{$post[\'post\'][\'_adCode\']}\n		</if>\n<script type=\"text/javascript\">\nvar pid = parseInt({$post[\'post\'][\'pid\']});\nif ( pid > ipb.topic.topPid ){\n	ipb.topic.topPid = pid;\n}\n<if test=\"sDeletedNotMQ:|:! $post[\'post\'][\'_isDeleted\']\">\n	// Show multiquote for JS browsers\n	if ( $(\'multiq_{$post[\'post\'][\'pid\']}\') )\n	{\n		$(\'multiq_{$post[\'post\'][\'pid\']}\').show();\n	}\n	\n	if( $(\'toggle_post_{$post[\'post\'][\'pid\']}\') )\n	{\n		$(\'toggle_post_{$post[\'post\'][\'pid\']}\').show();\n	}\n	\n	// Add perm data\n	ipb.topic.deletePerms[{$post[\'post\'][\'pid\']}] = { \'canDelete\' : {parse expression=\"intval($post[\'post\'][\'_can_delete\'])\"}, \'canSoftDelete\' : {parse expression=\"intval($post[\'post\'][\'_softDelete\'])\"} };\n</if>\n</script>', 'post', '$post, $displayData, $topic, $forum=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('351', '0', 'skin_topic', '{$post[\'post\']}\n    {$post[\'attachmentHtml\']}\n	<br />\n	<if test=\"editByQe:|:$post[\'edit_by\']\">\n		<p class=\'edit\'>\n			{$post[\'edit_by\']}\n			<if test=\"editReasonQe:|:$post[\'post_edit_reason\'] != \'\'\">\n				<br />\n				<span class=\'reason\'>{$this->lang->words[\'reason_for_edit\']} {$post[\'post_edit_reason\']}</span>\n			</if>\n		</p>\n	</if>', 'quickEditPost', '$post', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('352', '0', 'skin_topic', '<div id=\'attach_wrap\' class=\'\'>\n	<h4>{$title}</h4>\n	<ul>\n		<foreach loop=\"attach:$data as $file\">\n			<li class=\'<if test=\"attachType:|:$type == \'attach\'\">attachment</if>\'>\n				{$file}\n			</li>\n		</foreach>\n	</ul>\n</div>', 'show_attachment_title', '$title=\"\",$data=\"\",$type=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('353', '0', 'skin_topic', '<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\"><img src=\"{$this->settings[\'public_dir\']}<if test=\"hasmime:|:$data[\'mime_image\']\">{$data[\'mime_image\']}<else />style_extra/mime_types/unknown.gif</if>\" alt=\"{$this->lang->words[\'attached_file\']}\" /></a>\n&nbsp;<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\"><strong>{$data[\'attach_file\']}</strong></a> &nbsp;&nbsp;<span class=\'desc\'><strong>{$data[\'file_size\']}</strong></span>\n&nbsp;&nbsp;<span class=\"desc lighter\">{$data[\'attach_hits\']} {$this->lang->words[\'attach_hits\']}</span>', 'Show_attachments', '$data=\"\"', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('354', '0', 'skin_topic', '<a class=\'resized_img\' rel=\'lightbox[{$data[\'attach_rel_id\']}]\' id=\'ipb-attach-url-{$data[\'_attach_id\']}\' href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'location\']} - {$this->lang->words[\'attach_size\']} {$data[\'file_size\']}, {$this->lang->words[\'attach_ahits\']} {$data[\'attach_hits\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'o_location\']}\" class=\'bbc_img linked-image\' alt=\"{$this->lang->words[\'pic_attach\']}: {$data[\'location\']}\" /></a>', 'Show_attachments_img', '$data=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('355', '0', 'skin_topic', '<a class=\'resized_img\' rel=\'lightbox[{$data[\'attach_rel_id\']}]\' id=\'ipb-attach-url-{$data[\'_attach_id\']}\' href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'location\']} - {$this->lang->words[\'attach_size\']} {$data[\'file_size\']}, {$this->lang->words[\'attach_ahits\']} {$data[\'attach_hits\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'t_location\']}\" id=\'ipb-attach-img-{$data[\'_attach_id\']}\' style=\'width:{$data[\'t_width\']};height:{$data[\'t_height\']}\' class=\'attach\' width=\"{$data[\'t_width\']}\" height=\"{$data[\'t_height\']}\" alt=\"{$this->lang->words[\'pic_attach\']}: {$data[\'location\']}\" /></a>', 'Show_attachments_img_thumb', '$data=array()', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('356', '0', 'skin_topic', '<php>\n	$_sD = $sdData[ $post[\'post\'][\'pid\'] ];\n	$_sM = $_sD;\n</php>\n<div class=\'post_block hentry clear moderated\' id=\'post_id_{$post[\'post\'][\'pid\']}\'>\n	<a id=\'entry{$post[\'post\'][\'pid\']}\'></a>\n	<div class=\'post_wrap\'>\n		<if test=\"postMid:|:$post[\'author\'][\'member_id\']\">\n			<h3 class=\'row2\'>\n		<else />\n			<h3 class=\'row2 guest\'>\n		</if>\n			<if test=\"postModCheckbox:|:$this->memberData[\'is_mod\'] OR $this->memberData[\'g_is_supmod\']\">\n				<span class=\'post_id right\'>\n					<label for=\'checkbox_{$post[\'post\'][\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$post[\'post\'][\'pid\']}\' name=\'selectedpids[]\' value=\'{$post[\'post\'][\'pid\']}\' class=\'post_mod\'<if test=\"postModSelected:|:!empty( $post[\'post\'][\'_pid_selected\'] )\"> checked=\'checked\'</if> />\n				</span>\n			</if>\n				<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n						<span class=\"author vcard\"><a class=\"url fn\" href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a></span>\n				<else />\n					{$post[\'author\'][\'members_display_name\']}\n				</if>\n				<if test=\"postIp:|:$post[\'post\'][\'_show_ip\']\">\n					<span class=\'ip right ipsType_small\'>({$this->lang->words[\'ip\']}:\n					<if test=\"postAdmin:|:$post[\'author\'][\'g_access_cp\']\">\n						<em>{$this->lang->words[\'ip_private\']}</em>\n					<else />\n						<a href=\"{parse url=\"app=core&amp;module=modcp&amp;tab=iplookup&amp;fromapp=forums&amp;_do=submit&amp;ip={$post[\'post\'][\'ip_address\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'info_about_this_ip\']}\'>{$post[\'post\'][\'ip_address\']}</a>\n					</if>\n					)</span>\n				</if>\n			</h3>\n		<div class=\'post_body\' id=\'postsDelete_{$post[\'post\'][\'pid\']}\' style=\'margin-left: 0;\'>\n			<div class=\'post entry-content\' style=\'padding:10px\'>\n				{$this->lang->words[\'post_deleted_by\']} <a href=\'{parse url=\"showuser={$_sD[\'sdl_obj_member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$_sM[\'members_seo_name\']}\"}\'>{$_sM[\'members_display_name\']}</a> {$this->lang->words[\'on\']} {parse date=\"$_sD[\'sdl_obj_date\']\" format=\"long\"}.\n				<if test=\"showReason:|:$post[\'post\'][\'_softDeleteReason\']\">\n					<p class=\'desc\'><if test=\"$_sD[\'sdl_obj_reason\']\">{$_sD[\'sdl_obj_reason\']}<else />{$this->lang->words[\'no_reason_given\']}</if></p>\n				</if>\n			</div>\n		</div>\n		<if test=\"showPost:|:$post[\'post\'][\'_softDeleteContent\']\">\n		<div id=\'postsDeleteShow_{$post[\'post\'][\'pid\']}\' style=\'display:none\'>\n			<div class=\'author_info\'>\n				{parse template=\"userInfoPane\" group=\"global\" params=\"$post[\'author\'], $post[\'post\'][\'pid\'], array()\"}\n			</div>\n			<div class=\'post_body\'>\n				<p class=\'posted_info\'>\n					{$this->lang->words[\'posted\']} <abbr class=\"published\" title=\"{parse expression=\"@date( \'c\', $post[\'post\'][\'post_date\'] )\"}\">{parse date=\"$post[\'post\'][\'post_date\']\" format=\"long\"}</abbr>\n				</p>\n				<div class=\'post entry-content\'>\n					{$post[\'post\'][\'post\']}\n					{$post[\'post\'][\'attachmentHtml\']}\n					<br />\n					<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n						<p class=\'edit\'>\n							{$post[\'post\'][\'edit_by\']}\n							<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n								<br />\n								<span class=\'reason\'>{$this->lang->words[\'reason_for_edit\']} {$post[\'post\'][\'post_edit_reason\']}</span>\n							</if>\n						</p>\n					</if>\n				</div>\n				<if test=\"postSignature:|:$post[\'post\'][\'signature\']\">\n					{$post[\'post\'][\'signature\']}\n				</if>\n			</div>\n		</div>\n		</if>\n		<if test=\"sdOptions:|:$post[\'post\'][\'_softDeleteContent\'] OR $post[\'post\'][\'_softDeleteRestore\']\">\n			<ul class=\'post_controls clear clearfix\'>\n				<if test=\"$post[\'post\'][\'_softDeleteRestore\']\">\n					<li class=\'post_toggle sd_restore\' id=\'restoreContent_{$post[\'post\'][\'pid\']}\'>\n						<a class=\'ipsButton_secondary\' href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;do=postchoice&amp;tact=sundelete&amp;selectedpids[{$post[\'post\'][\'pid\']}]={$post[\'post\'][\'pid\']}&amp;pid={$post[\'post\'][\'pid\']}&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;auth_key={$this->member->form_hash}&amp;nr=1\" base=\"public\"}\'><span>{$this->lang->words[\'sdpost_restore\']}</span></a>\n					</li>\n				</if>\n				<if test=\"$post[\'post\'][\'_can_delete\']\">\n					<li>\n						<a class=\'ipsButton_secondary\' href=\'{parse url=\"module=moderate&amp;section=moderate&amp;do=04&amp;f={$topic[\'forum_id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;pid={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;nr=1\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'sd_remove\'>{$this->lang->words[\'sdpost_remove\']}</a>\n					</li>\n				</if>\n				<if test=\"$post[\'post\'][\'_softDeleteContent\']\">\n					<li class=\'post_toggle sd_content\' id=\'seeContent_{$post[\'post\'][\'pid\']}\'>\n						<a href=\'#\'><span>{$this->lang->words[\'togglepostcontent\']}</span></a>\n					</li>\n				</if>\n			</ul>\n		</if>\n	</div>\n</div>', 'softDeletedPostBit', '$post, $sdData, $topic', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('357', '0', 'skin_topic', '<foreach loop=\"$posts as $t => $post\">\n	<a href=\'{parse url=\"showuser={$post[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'members_seo_name\']}\"}\' class=\'ipsUserPhotoLink left\'>\n		<img src=\'{$post[\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_medium\' />\n	</a>\n	<div class=\'preview_col\'>\n		<p class=\'preview_info\'>\n			<strong><a href=\'{parse url=\"showuser={$post[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'members_seo_name\']}\"}\'>{$post[\'members_display_name\']}</a></strong> <if test=\"$t != \'search\'\">{$this->lang->words[\'tg_madethe\']} <a href=\"{parse url=\"showtopic={$post[\'tid\']}&amp;findpost={$post[\'pid\']}\" seotitle=\"{$post[\'title_seo\']}\" template=\"showtopic\" base=\"public\"}\">{$this->lang->words[\'tg_\'.$t]}</a><else />{$this->lang->words[\'tg_\'.$t]}</if>\n		</p>\n		{$post[\'post\']}\n	</div>\n	<br class=\'clear\' />\n</foreach>\n<br class=\'clear\' />\n<a href=\'{parse url=\"showtopic={$topic[\'tid\']}\" base=\"public\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\"}\' class=\'ipsButton\'>{$this->lang->words[\'tg_gototopic\']}</a>\n<if test=\"! $topic[\'_lastRead\'] OR $topic[\'_unreadPosts\']\">\n	&nbsp;&nbsp;<span class=\'desc\'>\n		<if test=\"$topic[\'_unreadPosts\']\">\n			{$topic[\'_unreadPosts\']} {$this->lang->words[\'newpoststp\']}\n			&middot; <a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;view=getnewpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\"}\'>{$this->lang->words[\'tg_go_last_post\']}</a>\n		</if>\n		<a data-clicklaunch=\"topicMarkRead\" data-tid=\"{$topic[\'tid\']}\" href=\"{parse url=\"showtopic={$topic[\'tid\']}&amp;view=getnewpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\"}\"><if test=\"$topic[\'_unreadPosts\']\">&middot; </if>{$this->lang->words[\'mark_topic_read\']}</a>\n	</span>\n</if>', 'topicPreview', '$topic, $posts', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('358', '0', 'skin_topic', '<if test=\"allowRating:|:$forum[\'forum_allow_rating\']\">\n{parse js_module=\"rating\"}\n</if>\n{parse js_module=\"topic\"}\n<script type=\"text/javascript\">\n//<![CDATA[\n	ipb.topic.inSection = \'topicview\';\n	ipb.topic.topic_id  = {$topic[\'tid\']};\n	ipb.topic.forum_id  = {$forum[\'id\']};\n	ipb.topic.start_id  = {parse expression=\"intval($this->request[\'st\'])\"};\n	ipb.topic.topPid    = 0;\n	ipb.topic.counts    = { postTotal: {parse expression=\"intval($topic[\'posts\']+1)\"},\n							curStart:  ipb.topic.start_id,\n							perPage:   {parse expression=\"intval($this->settings[\'display_max_posts\'])\"} };\n	//Search Setup\n	ipb.vars[\'search_type\']			= \'forum\';\n	ipb.vars[\'search_type_id\']		= {$forum[\'id\']};\n	ipb.vars[\'search_type_2\']		= \'topic\';\n	ipb.vars[\'search_type_id_2\']	= {$topic[\'tid\']};\n	\n	<if test=\"canDeleteUrls:|:!$this->member->is_not_human\">\n	// Delete stuff set up\n	ipb.topic.deleteUrls[\'hardDelete\'] = new Template(\"{parse url=\"module=moderate&section=moderate&do=04&f={$forum[\'id\']}&t={$topic[\'tid\']}&st={$this->request[\'st\']}&auth_key={$this->member->form_hash}&p=#{pid}\" base=\"publicWithApp\"}\");\n	ipb.topic.deleteUrls[\'softDelete\'] = new Template(\"{parse url=\"app=forums&module=moderate&section=moderate&do=postchoice&tact=sdelete&t={$topic[\'tid\']}&f={$forum[\'id\']}&auth_key={$this->member->form_hash}&selectedpids[#{pid}]=#{pid}&pid=#{pid}\" base=\"public\"}\");\n	</if>\n//]]>\n</script>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{$displayData[\'follow_data\']}\n<a href=\'{parse url=\"showuser={$topic[\'_starter\'][\'member_id\']}\" seotitle=\"{$topic[\'_starter\'][\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' class=\'ipsUserPhotoLink\'>\n	<img src=\'{$topic[\'_starter\'][\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_medium left\' />\n</a>\n<div class=\'ipsBox_withphoto\'>\n	<if test=\"topicRating:|:$forum[\'forum_allow_rating\']\">\n		<span class=\'rating ipsType_smaller\'>\n			<if test=\"$topic[\'_allow_rate\']\">\n				<strong>{$this->lang->words[\'js_rate_me\']}</strong>&nbsp;&nbsp;\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				<a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=rating&amp;t={$topic[\'tid\']}&amp;rating=1&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' id=\'topic_rate_1\' title=\'{$this->lang->words[\'top_js_1star\']}\'>\n			</if>\n			<if test=\"rate1:|:$topic[\'_rate_int\'] >= 1\">\n				{parse replacement=\"rate_on\"}\n			<else />\n				{parse replacement=\"rate_off\"}\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				</a><a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=rating&amp;t={$topic[\'tid\']}&amp;rating=2&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' id=\'topic_rate_2\' title=\'{$this->lang->words[\'top_js_2star\']}\'>\n			</if>\n			<if test=\"rate2:|:$topic[\'_rate_int\'] >= 2\">\n				{parse replacement=\"rate_on\"}\n			<else />\n				{parse replacement=\"rate_off\"}\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				</a><a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=rating&amp;t={$topic[\'tid\']}&amp;rating=3&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' id=\'topic_rate_3\' title=\'{$this->lang->words[\'top_js_3star\']}\'>\n			</if>\n			<if test=\"rate3:|:$topic[\'_rate_int\'] >= 3\">\n				{parse replacement=\"rate_on\"}\n			<else />\n				{parse replacement=\"rate_off\"}\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				</a><a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=rating&amp;t={$topic[\'tid\']}&amp;rating=4&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' id=\'topic_rate_4\' title=\'{$this->lang->words[\'top_js_4star\']}\'>\n			</if>\n			<if test=\"rate4:|:$topic[\'_rate_int\'] >= 4\">\n				{parse replacement=\"rate_on\"}\n			<else />\n				{parse replacement=\"rate_off\"}\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				</a><a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=rating&amp;t={$topic[\'tid\']}&amp;rating=5&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' id=\'topic_rate_5\' title=\'{$this->lang->words[\'top_js_5star\']}\'>\n			</if>\n			<if test=\"rate5:|:$topic[\'_rate_int\'] >= 5\">\n				{parse replacement=\"rate_on\"}\n			<else />\n				{parse replacement=\"rate_off\"}\n			</if>\n			<if test=\"$topic[\'_allow_rate\']\">\n				</a>\n			</if>\n			<span id=\'rating_text\'>\n				<if test=\"hasRates:|:$topic[\'topic_rating_hits\'] > 0\"><span id=\'rating_hits\'>{$topic[\'topic_rating_hits\']} {$this->lang->words[\'poll_s_votes\']}</span></if>\n			</span>\n			<if test=\"$topic[\'_allow_rate\']\">\n				<script type=\'text/javascript\'>\n				//<![CDATA[\n					rating = new ipb.rating( \'topic_rate_\', { \n										url: \'{parse url=\"app=forums&module=ajax&section=topics&do=rateTopic&t={$topic[\'tid\']}\" base=\"public\"}&md5check=\' + ipb.vars[\'secure_hash\'],\n										cur_rating: {$topic[\'_rate_int\']},\n										rated: <if test=\"jsHasRates:|:$topic[\'_rating_value\'] != -1\">1<else />0</if>,\n										allow_rate: {$topic[\'_allow_rate\']},\n										multi_rate: 1,\n										show_rate_text: true\n									  } );\n				//]]>\n				</script>\n			</if>\n		</span>\n	</if>\n	<h1 class=\'ipsType_pagetitle\'>\n		{$topic[\'title\']}\n	</h1>\n	<div class=\'desc lighter blend_links\'>\n		 {$this->lang->words[\'started_by\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$topic[\'_starter\']\"}, {parse date=\"$topic[\'start_date\']\" format=\"SHORT\"}\n	</div>\n	<if test=\"hasTags:|:is_array($topic[\'tags\'])\">\n		{$topic[\'tags\'][\'formatted\'][\'parsedWithoutComma\']}\n		<br />\n	</if>\n</div>\n<if test=\"topicHasBeenDeleted:|:$topic[\'_isDeleted\']\">\n	<br />\n	<div class=\'message error\'>\n		{$this->lang->words[\'dlp_topic_has_deleted_desc\']}\n		&nbsp;&nbsp;\n		<if test=\"tbdRestore:|:$topic[\'permissions\'][\'TopicSoftDeleteRestore\']\">\n			<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;do=sundelete\" base=\"public\"}\' title=\'{$this->lang->words[\'dl_ths_restore\']}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'dl_ths_restore\']}</a>\n		</if>\n		<if test=\"tbdRestore:|:$this->memberData[\'g_is_supmod\'] == 1 || $this->memberData[\'forumsModeratorData\'][ $forum[\'id\'] ][\'delete_topic\']\">\n			<a href=\'{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;f={$forum[\'id\']}&amp;st={$this->request[\'st\']}&amp;t={$topic[\'tid\']}&amp;auth_key={$this->member->form_hash}&amp;do=09\" base=\"public\"}\' title=\'{$this->lang->words[\'dl_ths_delete\']}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'dl_ths_delete\']}</a>\n		</if>\n	</div>\n</if>\n<br />\n<div class=\'topic_controls\'>\n	{$topic[\'SHOW_PAGES\']}\n	<ul class=\'topic_buttons\'>\n		<if test=\"closedButton:|:$displayData[\'reply_button\'][\'image\'] == \'locked\'\">\n			<li class=\'important\'>\n				<if test=\"pollOnly:|:isset($displayData[\'poll_data\'][\'poll\'][\'poll_only\']) && $displayData[\'poll_data\'][\'poll\'][\'poll_only\']\">\n					<if test=\"closedButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n						<a href=\'{$displayData[\'reply_button\'][\'url\']}\' accesskey=\'r\'>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_poll_only_reply\']}</a>\n					<else />\n						<span>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_poll_only\']}</span>\n					</if>\n				<else />\n					<if test=\"closedButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n						<a href=\'{$displayData[\'reply_button\'][\'url\']}\' accesskey=\'r\'>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_locked_reply\']}</a>\n					<else />\n						<span>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_locked\']}</span>\n					</if>\n				</if>\n			</li>\n		<else />\n			<if test=\"replyButton:|:$displayData[\'reply_button\'][\'image\']\">\n				<if test=\"replyButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n					<li><a href=\'{$displayData[\'reply_button\'][\'url\']}\' title=\'{$this->lang->words[\'topic_add_reply\']}\' accesskey=\'r\'>{$this->lang->words[\'topic_add_reply\']}</a></li>\n				<else />\n					<li class=\'disabled\'><span>{$this->lang->words[\'top_cannot_reply\']}</span></li>\n				</if>\n			</if>\n		</if>\n		<if test=\"topicDescription:|:$topic[\'hasUnreadPosts\'] AND $topic[\'posts\']\">\n			<li class=\'non_button\'><a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;view=getnewpost\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'first_unread_post\']}\'>{$this->lang->words[\'go_to_first_unread\']}</a></li>\n		</if>\n	</ul>	\n</div>\n\n<div class=\'maintitle clear clearfix\'>\n	<span class=\'ipsType_small\'>\n		<if test=\"$topic[\'posts\']\">\n			{parse expression=\"sprintf( ( $topic[\'posts\'] > 1 ) ? $this->lang->words[\'x_replies_to_topic\'] : $this->lang->words[\'x_reply_to_topic\'], $topic[\'posts\'] )\"}\n		<else />\n			{$this->lang->words[\'no_replies_to_topic\']}\n		</if>\n	</span>\n	<if test=\"reputationFilter:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_point_types\'] != \'like\' && $this->settings[\'reputation_show_content\'] && $this->memberData[\'member_id\'] != 0 && is_array($this->caches[\'reputation_levels\'])\">\n		<a href=\'#rep_filter_menucontent\' id=\'rep_filter\' class=\'right ipsType_smaller\'>\n			<if test=\"repFilterDefault:|:$this->memberData[\'_members_cache\'][\'rep_filter\'] && $this->memberData[\'_members_cache\'][\'rep_filter\'] === \'*\'\">\n				{$this->lang->words[\'rep_f_viewing_all\']}\n			<else />\n				{parse expression=\"sprintf( $this->lang->words[\'rep_f_hiding\'], $this->memberData[\'_members_cache\'][\'rep_filter\'] )\"}\n			</if>\n			<img src=\'{$this->settings[\'img_url\']}/useropts_arrow.png\' />\n		</a>\n	</if>	\n</div>\n<if test=\"reputationFilter:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_point_types\'] != \'like\' && $this->settings[\'reputation_show_content\'] && $this->memberData[\'member_id\'] != 0 && is_array($this->caches[\'reputation_levels\'])\">\n	<ul id=\'rep_filter_menucontent\' class=\'ipbmenu_content with_checks\' style=\'display: none\'>\n		<li <if test=\"optSelectStar:|:isset( $this->memberData[\'_members_cache\'][\'rep_filter\'] ) AND $this->memberData[\'_members_cache\'][\'rep_filter\'] === \'*\'\">class=\'selected\'</if>>\n			<a href=\'{parse url=\"app=forums&amp;module=forums&amp;section=topics&amp;rep_filter=update&amp;f={$topic[\'forum_id\']}&amp;t={$topic[\'tid\']}&amp;secure_key={$this->member->form_hash}&amp;st={$this->request[\'st\']}&amp;rep_filter_set=*\" base=\"public\"}\'>{$this->lang->words[\'rep_f_all_posts\']}</a>\n		</li>\n		<if test=\"repFilterOptions:|:is_array($this->caches[\'reputation_levels\'])\">\n			<foreach loop=\"reputation_levels:$this->caches[\'reputation_levels\'] as $k => $v\">\n				<li <if test=\"optRepFilterSelected:|:isset( $this->memberData[\'_members_cache\'][\'rep_filter\'] ) AND $v[\'level_points\'] == $this->memberData[\'_members_cache\'][\'rep_filter\']\">class=\'selected\'</if>>\n					<a href=\'{parse url=\"app=forums&amp;module=forums&amp;section=topics&amp;rep_filter=update&amp;f={$topic[\'forum_id\']}&amp;t={$topic[\'tid\']}&amp;secure_key={$this->member->form_hash}&amp;st={$this->request[\'st\']}&amp;rep_filter_set={$v[\'level_points\']}\" base=\"public\"}\' rel=\'nofollow\'>\n						{$this->lang->words[\'rep_f_hide\']} <strong>{$v[\'level_points\']} {$this->lang->words[\'rep_f_points\']}</strong>\n					</a>\n				</li>\n			</foreach>\n		</if>\n	</ul>\n	<script type=\'text/javascript\'>\n		new ipb.Menu( $(\'rep_filter\'), $(\'rep_filter_menucontent\') );\n	</script>\n</if>\n<div class=\'topic hfeed clear clearfix\'>\n	\n	{$displayData[\'poll_data\'][\'html\']}\n	\n	<if test=\"startModForm:|:$displayData[\'mod_links\']\">\n		<if test=\"weAreMod:|:$this->memberData[\'is_mod\'] OR $this->memberData[\'member_id\'] == $topic[\'starter_id\']\">\n			<form id=\"modform\" method=\"post\" action=\"{parse url=\"\" base=\"public\"}\">\n				<fieldset>\n	 				<input type=\"hidden\" name=\"app\" value=\"forums\" />\n		 			<input type=\"hidden\" name=\"module\" value=\"moderate\" />\n		 			<input type=\"hidden\" name=\"section\" value=\"moderate\" />\n		 			<input type=\"hidden\" name=\"do\" value=\"postchoice\" />\n		 			<input type=\"hidden\" name=\"f\" value=\"{$topic[\'forum_id\']}\" />\n		 			<input type=\"hidden\" name=\"t\" value=\"{$topic[\'tid\']}\" />\n		 			<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		 			<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n		 			<input type=\"hidden\" value=\"{$this->request[\'selectedpids\']}\" name=\"selectedpidsJS\" id=\'selectedpidsJS\' />\n				</fieldset>\n		</if>\n	</if>\n	\n<if test=\"hasPosts:|:is_array( $post_data ) AND count( $post_data )\">\n	<div class=\'ipsBox\'>\n		<div class=\'ipsBox_container\' id=\'ips_Posts\'>\n			<foreach loop=\"post_data:$post_data as $post\">\n				{parse template=\"post\" group=\"topic\" params=\"$post, $displayData, $topic, $forum\"}\n			</foreach>\n		</div>\n	</div>\n</if>\n<hr />\n<!-- MOD LINKS -->\n<if test=\"modOptions:|:$displayData[\'mod_links\']\">\n	<if test=\"showModOptions:|:$this->memberData[\'is_mod\'] OR $this->memberData[\'member_id\'] == $topic[\'starter_id\']\">\n		<div class=\'ipsBox ipsPad clear clearfix\' id=\'topic_mod\'>\n			<div class=\'row2 ipsBox_container clearfix\'>\n			<div class=\'moderation_bar with_action right\'>\n				<if test=\"showModOptionsinner:|:$this->memberData[\'is_mod\']\">\n					<label for=\'tact\' class=\'hide\'>{$this->lang->words[\'post_moderation\']}</label>\n			 		<select name=\"tact\" id=\'tact\' class=\'input_select\'>\n						<option value=\"\">{$this->lang->words[\'post_moderation\']}</option>\n		 				<option value=\"merge\">{$this->lang->words[\'cpt_merge\']}</option>\n		 				<option value=\"move\">{$this->lang->words[\'cpt_move\']}</option>\n		 				<option value=\"delete\">{$this->lang->words[\'cpt_delete\']}</option>\n		 				<if test=\"$this->registry->class_forums->can_Un_SoftDeletePosts( $forum_data[\'id\'], $topic )\"><option value=\"sundelete\">{$this->lang->words[\'cpt_undelete\']}</option></if>\n		 				<option value=\"split\">{$this->lang->words[\'cpt_split\']}</option>\n		 				<option value=\"approve\">{$this->lang->words[\'cpt_approve\']}</option>\n		 				<option value=\"unapprove\">{$this->lang->words[\'cpt_unapprove\']}</option>\n		 			</select>&nbsp;\n		 			<input type=\"submit\" id=\'mod_submit\' name=\"gobutton\" value=\"{$this->lang->words[\'f_go\']}<if test=\"modButtonCount:|:$this->request[\'selectedpidcount\']\"> ({$this->request[\'selectedpidcount\']})</if>\" class=\"input_submit alt\" />\n				 </if>\n			</div>\n			</form>\n			<script type=\'text/javascript\'>\n				$(\'modform\').observe(\'submit\', ipb.topic.submitPostModeration );\n			</script>\n			<div class=\'moderation_bar left\' id=\'topic_mod_2\'>\n				<a href=\'#\' id=\'topic_mod_options\' class=\'ipbmenu input_submit alt ipsPad_half left\'>{$this->lang->words[\'topic_moderation\']}</a>\n				<ul class=\'ipbmenu_content\' id=\'topic_mod_options_menucontent\'>\n					<foreach loop=\"mod_links:$displayData[\'mod_links\'] as $_mod_link\">\n						<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;_fromTopic=1&amp;do={$_mod_link[\'option\']}\" base=\"public\"}\">{$_mod_link[\'value\']}</a>\n					</foreach>\n					<if test=\"$topic[\'topic_queuedposts\'] AND $this->registry->class_forums->canQueuePosts( $forum[\'id\'] )\">\n						<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;_fromTopic=1&amp;do=p_approve\" base=\"public\"}\">{parse expression=\"sprintf( $this->lang->words[\'nmo_p_approve\'], $topic[\'topic_queuedposts\'])\"}</a>\n					</if>\n					<if test=\"$topic[\'topic_queuedposts\'] AND $this->registry->class_forums->canHardDeletePosts( $forum[\'id\'], $topic )\">\n						<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;_fromTopic=1&amp;do=p_delete_approve\" base=\"public\"}\">{parse expression=\"sprintf( $this->lang->words[\'nmo_p_delete_approve\'], $topic[\'topic_queuedposts\'])\"}</a>	\n					</if>\n					<if test=\"$topic[\'permissions\'][\'softDeleteRestore\'] AND $topic[\'topic_deleted_posts\']\">\n						<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;_fromTopic=1&amp;do=p_restore\" base=\"public\"}\">{parse expression=\"sprintf( $this->lang->words[\'nmo_p_restore\'], $topic[\'topic_deleted_posts\'])\"}</a>\n					</if>\n					<if test=\"$topic[\'topic_deleted_posts\'] AND $this->registry->class_forums->canHardDeletePosts( $forum[\'id\'], $topic )\">\n						<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=moderate&amp;t={$topic[\'tid\']}&amp;f={$topic[\'forum_id\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}&amp;_fromTopic=1&amp;do=p_delete_softed\" base=\"public\"}\">{parse expression=\"sprintf( $this->lang->words[\'nmo_p_delete_softed\'], $topic[\'topic_deleted_posts\'])\"}</a>	\n					</if>\n					<if test=\"mmModOptions:|:is_array( $displayData[\'multi_mod\'] ) AND count( $displayData[\'multi_mod\'] )\">\n						<foreach loop=\"mm:$displayData[\'multi_mod\'] as $mm_data\">\n							<li><a href=\"{parse url=\"app=forums&amp;module=moderate&amp;section=multimod&amp;t={$topic[\'tid\']}&amp;mm_id={$mm_data[0]}\" base=\"public\"}\">{$this->lang->words[\'mm_title\']}: {$mm_data[1]}</a></li>\n						</foreach>\n					</if>\n				</ul>\n				<script type=\'text/javascript\'>\n					new ipb.Menu( $(\'topic_mod_options\'), $(\'topic_mod_options_menucontent\') );\n				</script>\n			</div>\n		</div>\n	</div>\n	</if>\n</if>\n<hr />\n<div class=\'topic_controls clear ipsPad_top_bottom_half\'>\n	<if test=\"$topic[\'SHOW_PAGES\']\">\n		<div class=\'left\'>{$topic[\'SHOW_PAGES\']}</div>\n	</if>\n	<div class=\'ipsPad_top_slimmer right\'>\n		<a href=\'{parse url=\"showforum={$forum[\'id\']}\" template=\"showforum\" seotitle=\"{$forum[\'name_seo\']}\" base=\"public\"}\' class=\"ipsType_small desc\">{parse expression=\"sprintf( $this->lang->words[\'go_back_to\'], $forum[\'name\'] )\"}</a>\n		<if test=\"hasUnreadNext:|:$forum[\'_hasUnreadTopics\']\">\n			&middot; <a href=\'{parse url=\"showtopic={$topic[\'tid\']}&amp;view=getnextunread\" template=\"showtopicnextunread\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\' class=\"ipsType_small desc\">{$this->lang->words[\'goto_next_unread_topic\']}</a>\n		</if>\n	</div>\n	<if test=\"modOptionsLink:|:$displayData[\'mod_links\'] && ( $this->memberData[\'is_mod\'] OR $this->memberData[\'member_id\'] == $topic[\'starter_id\'] )\">\n		<div class=\'moderation_bar ipsType_small\' style=\'text-align: center; width: 40%;margin:0 auto;\'>\n			<a href=\'#\' id=\'moderator_toggle\'><img src=\'{$this->settings[\'img_url\']}/moderation_cog.png\' />&nbsp; {$this->lang->words[\'show_moderation_tools\']}</a>\n		</div>\n	</if>\n	\n</div>\n<if test=\"fastReply:|:$displayData[\'fast_reply\'] && $displayData[\'reply_button\'][\'url\']\">\n<hr />\n<div class=\'ipsBox\' id=\'fast_reply_wrapper\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<h1 class=\'ipsType_subtitle\'>{$this->lang->words[\'topic_add_reply\']}</h1>\n		<if test=\"isLockedFR:|:$topic[\'state\'] == \'closed\'\"><span class=\'error\'>{$this->lang->words[\'locked_reply_fr\']}</span><br /></if>\n		<br />\n		<if test=\"isMember:|:$this->memberData[\'member_id\']\">\n			<a href=\"{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" title=\'{$this->lang->words[\'your_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$this->memberData[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$this->memberData[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n		<else />\n			<div class=\'left\'>{IPSMember::buildNoPhoto(0, \'small\' )}</div>\n		</if>\n		<div class=\'ipsBox_withphoto clearfix\'>\n			<form action=\"{parse url=\"\" base=\"public\"}\" method=\"post\" id=\'ips_fastReplyForm\'>\n				<input type=\"hidden\" name=\"app\" value=\"forums\" />\n				<input type=\"hidden\" name=\"module\" value=\"post\" />\n				<input type=\"hidden\" name=\"section\" value=\"post\" />\n				<input type=\"hidden\" name=\"do\" value=\"reply_post_do\" />\n				<input type=\"hidden\" name=\"f\" value=\"{$forum[\'id\']}\" />\n				<input type=\"hidden\" name=\"t\" value=\"{$topic[\'tid\']}\" />\n				<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n				<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n				<input type=\"hidden\" name=\"fast_reply_used\" value=\"1\" />\n				<input type=\"hidden\" name=\"enableemo\" value=\"yes\" />\n				<input type=\"hidden\" name=\"enablesig\" value=\"yes\" />\n				<if test=\"$this->memberData[\'auto_track\']\">\n					<input type=\"hidden\" name=\"enabletrack\" value=\"1\" />\n				</if>\n				<if test=\"is_array($topic[\'_fastReplyStatusMessage\']) AND count($topic[\'_fastReplyStatusMessage\']) AND strlen($topic[\'_fastReplyStatusMessage\'][0])\">\n					<div class=\'message\'>{parse expression=\"implode( \'<br />\', $topic[\'_fastReplyStatusMessage\'] )\"}</div>\n				</if>\n				{parse editor=\"Post\" options=\"array( \'type\' => \'full\', \'minimize\' => 1, \'isTypingCallBack\' => \'ipb.topic.isTypingCallBack\', \'height\' => 180, \'autoSaveKey\' => \'reply-\' . $topic[tid] )\"}\n				<br />\n				\n				<fieldset class=\'right\' id=\'fast_reply_controls\'>\n					<input type=\'submit\' name=\"submit\" class=\'input_submit\' value=\'{$this->lang->words[\'qr_post\']}\' tabindex=\'0\' accesskey=\'s\' id=\'submit_post\' />&nbsp;&nbsp;<input type=\'submit\' name=\"preview\" class=\'input_submit alt\' value=\'{$this->lang->words[\'qr_more_opts\']}\' tabindex=\'0\' id=\'full_compose\' />			\n				</fieldset>\n			</form>\n		</div>\n		<div id=\'ips_HasReplies\'></div>\n	</div>\n</div>\n<script type=\'text/javascript\'>\n	ipb.topic.fastReplyId	= \'{$this->settings[\'_lastEditorId\']}\';\n</script>\n<else />\n	<if test=\"loadJsManually:|:$displayData[\'load_editor_js\']\">\n		{parse template=\"editorLoadJs\" group=\"editors\" params=\"$displayData[\'smilies\']\"}\n	</if>\n</if>\n<!-- Close topic -->\n</div>\n<!-- BOTTOM BUTTONS -->\n<if test=\"canShare:|:!$forum[\'disable_sharelinks\'] AND $this->settings[\'sl_enable\']\">\n	<br />\n	<div class=\'clear clearfix left\'>\n		{IPSLib::shareLinks( $topic[\'title\'] )}\n	</div>\n	<br />\n</if>\n<!-- ACTIVE USERS -->\n<if test=\"topicActiveUsers:|:is_array( $displayData[\'active_users\'] ) AND count( $displayData[\'active_users\'] )\">\n	<div id=\'topic_stats\' class=\'statistics clear clearfix\'>\n		<div id=\'topic_active_users\' class=\'active_users\'>\n			<h4 class=\'statistics_head\'>{parse expression=\"sprintf( $this->lang->words[\'active_users_title\'], ($displayData[\'active_users\'][\'members\'] + $displayData[\'active_users\'][\'guests\'] + $displayData[\'active_users\'][\'anon\'] ) )\"}</h4>\n			<p class=\'statistics_brief desc\'>{parse expression=\"sprintf( $this->lang->words[\'active_users_detail\'], $displayData[\'active_users\'][\'members\'], $displayData[\'active_users\'][\'guests\'], $displayData[\'active_users\'][\'anon\'] )\"}</p>\n			<if test=\"auNames:|:is_array( $displayData[\'active_users\'][\'names\'] ) AND count( $displayData[\'active_users\'][\'names\'] )\">\n				<br />\n				<ul class=\'ipsList_inline\'>\n					<foreach loop=\"active_users:$displayData[\'active_users\'][\'names\'] as $p => $r\">\n				<li>{$r[\'p_start\']}<if test=\"auId:|:$r[\'id\']\"><a href=\'{parse url=\"showuser={$r[\'id\']}\" seotitle=\"{$r[\'seo\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$r[\'p_title\']}\'></if>{$r[\'name\']}<if test=\"auEndId:|:$r[\'id\']\"></a></if>{$r[\'p_end\']}<if test=\"lastActiveUser:|:$p + 1 != count( $displayData[\'active_users\'][\'names\'] )\">,</if></li>\n					</foreach>\n				</ul>\n			</if>\n		</div>\n	</div>\n</if>\n<if test=\"scrollToPost:|:$this->request[\'gopid\']\">\n<script type=\'text/javascript\'>\n	var gopid = \"{$this->request[\'gopid\']}\".replace(/&amp;/g, \'\');\n	ipb.topic.scrollToPost( parseInt( gopid ) );\n</script>\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}\n<div id=\'multiQuoteInsert\' style=\'display: none;\' class=\'ipsFloatingAction\'>\n	<span class=\'ipsButton no_width\' id=\'mqbutton\'>{$this->lang->words[\'mq_reply_quoted_posts\']}</span>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<a href=\'#\' id=\'multiQuoteClear\' class=\'ipsType_smaller desc\' title=\'{$this->lang->words[\'mq_clear_desc\']}\'>{$this->lang->words[\'mq_clear\']}</a> &nbsp;&nbsp;&nbsp;\n</div>', 'topicViewTemplate', '$forum, $topic, $post_data, $displayData', '1338050062', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('359', '0', 'skin_boards', '<a href=\'{parse url=\"showuser={$user[\'member_id\']}\" seotitle=\"{$user[\'members_seo_name\']}\" template=\"showuser\"  base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$user[\'members_display_name\']}</a><if test=\"age:|:$pyear\"> (<strong>{$pyear}</strong>)</if>', 'birthday', '$user, $pyear', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('360', '0', 'skin_boards', '<if test=\"$this->settings[\'_onIndex\'] = 1\"></if>\n<div class=\'master_list\' id=\'board_index\'>\n	<if test=\"cats_forums:|:is_array( $cat_data ) AND count( $cat_data )\">\n		<foreach loop=\"categories:$cat_data as $_data\">\n			<if test=\"cat_has_forums:|:is_array( $_data[\'forum_data\'] ) AND count( $_data[\'forum_data\'] )\">\n				<h3 id=\"cat-{$_data[\'cat_data\'][\'id\']}\"><!--<a href=\"{parse url=\"showforum={$_data[\'cat_data\'][\'id\']}\" seotitle=\"{$_data[\'cat_data\'][\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" class=\"title\" title=\'{$this->lang->words[\'view_cat\']}\'>-->{$_data[\'cat_data\'][\'name\']}<!--</a>--></h3>\n				<foreach loop=\"forums:$_data[\'forum_data\'] as $forum_id => $forum_data\">\n					<if test=\"forumRedirect:|:$forum_data[\'redirect_on\']\">\n						<div class=\'row touch-row\' id=\"forum-{$forum_data[\'id\']}\">\n							<div class=\'icon\'>{parse replacement=\"f_redirect\"}</div>\n							<div class=\'rowContent\'>\n								<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\' class=\'title\'>{$forum_data[\'name\']}</a>\n								<br /><span class=\'desc\'>{$this->lang->words[\'rd_hits\']}: {parse format_number=\"$forum_data[\'redirect_hits\']\"}</span>\n							</div>\n						</div>\n					<else />\n						<div class=\'row touch-row\' id=\"forum-{$forum_data[\'id\']}\">\n							<div class=\'icon\'>\n								<if test=\"unreadicon:|:$forum_data[\'img_new_post\'] != \'f_locked\' && strstr( $forum_data[\'img_new_post\'], \'unread\' )\">\n									<a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$this->request[\'f\']}&amp;i=1\" base=\"public\"}\" title=\"{$this->lang->words[\'bi_markread\']}\" class=\'forum_marker\'>\n										{parse replacement=\"f_unread\"}\n									</a>\n								<else />\n									{parse replacement=\"f_read\"}\n								</if>\n							</div>\n							<div class=\'rowContent\'>\n								<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\' class=\'title\'>{$forum_data[\'name\']}</a>\n								<br />\n								<span class=\'desc\'>\n									<span class=\'number\'>{$forum_data[\'topics\']}</span> {$this->lang->words[\'topics\']}\n									<if test=\"hideDateUrl:|:! $forum_data[\'hide_last_info\']\">\n										&middot; {$this->lang->words[\'last_post\']} {parse date=\"$forum_data[\'last_post\']\" format=\"SHORT\"}\n									</if>\n								</span>\n							</div>\n						</div>\n					</if>\n				</foreach>\n			</if>\n		</foreach>\n	</if>\n</div>', 'boardIndexTemplate', '$lastvisit=\"\", $stats=array(), $cat_data=array(), $show_side_blocks=true, $side_blocks=array()', '1338050062', '0', '0', '0', '0', 'mobile');
