INSERT INTO `ibf_skin_templates` VALUES ('364', '0', 'skin_boards', '<div class=\'general_box clearfix\'>\n		<h3><img src=\'{$this->settings[\'img_url\']}/comment_new.png\' alt=\'\' /> {$this->lang->words[\'recently_added_entries\']}</h3>\n		<ul class=\'hfeed block_list\'>\n			<if test=\"recent_blog_entries:|:is_array( $entries ) && count( $entries )\">\n				{parse striping=\"recent_entries\" classes=\"row1,row2 altrow\"}\n				<foreach loop=\"entries_hook:$entries as $r\">\n				<li class=\'hentry {parse striping=\"recent_entries\"}\'><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;blogid={$r[\'blog_id\']}&amp;showentry={$r[\'entry_id\']}\" template=\"showentry\" seotitle=\"{$r[\'entry_name_seo\']}\" base=\"public\"}\' rel=\'bookmark\' title=\'{$this->lang->words[\'view_entry\']}\'>{$r[\'entry_name\']}</a> {$this->lang->words[\'recent_by\']} <address class=\"author vcard\"><a class=\"url fn\" href=\"{parse url=\"showuser={$r[\'entry_author_id\']}\" template=\"showuser\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'view_profile\']}\'>{$r[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$r[\'entry_author_id\'], $r[\'members_seo_name\']\"}</address><br /><span class=\'date\'><abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $r[\'entry_date\'] )\"}\">{parse date=\"$r[\'entry_date\']\" format=\"short\"}</abbr></span></li>\n				</foreach>\n			<else />\n				<li>{$this->lang->words[\'norecent_entries_hook\']}</li>\n			</if>\n		</ul>\n	</div>', 'hookRecentBlogEntries', '$entries', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('365', '0', 'skin_boards', '<div class=\'general_box clearfix\'>\n		<h3><img src=\'{$this->settings[\'img_url\']}/comment_new.png\' alt=\'\' /> {$this->lang->words[\'recently_added_topics\']}</h3>\n		<ul class=\'hfeed block_list\'>\n			<if test=\"recenttopics:|:is_array( $topics ) && count( $topics )\">\n				{parse striping=\"recent_topics\" classes=\"row1,row2 altrow\"}\n				<foreach loop=\"topics_hook:$topics as $r\">\n				<li class=\'hentry {parse striping=\"recent_topics\"}\'><a href=\'{parse url=\"showtopic={$r[\'tid\']}\" base=\"public\" template=\"showtopic\" seotitle=\"{$r[\'title_seo\']}\"}\' rel=\'bookmark\' title=\'{$this->lang->words[\'view_topic\']}\'>{$r[\'title\']}</a> \n				{$this->lang->words[\'recent_by\']} <address class=\"author vcard\"><if test=\"$r[\'members_display_name\']\"><a class=\"url fn\" href=\"{parse url=\"showuser={$r[\'starter_id\']}\" template=\"showuser\" seotitle=\"{$r[\'members_seo_name\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'view_profile\']}\'>{$r[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$r[\'starter_id\'], $r[\'members_seo_name\']\"}<else />{$this->settings[\'guest_name_pre\']}{$r[\'starter_name\']}{$this->settings[\'guest_name_suf\']}</if></address><br />\n				<span class=\'date\'><abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $r[\'start_date\'] )\"}\">{parse date=\"$r[\'start_date\']\" format=\"short\"}</abbr></span></li>\n				</foreach>\n			<else />\n				<li>{$this->lang->words[\'norecent_topics_hook\']}</li>\n			</if>\n		</ul>\n	</div>', 'hookRecentTopics', '$topics', '1338050062', '0', '0', '0', '0', 'mobile');
