INSERT INTO `ibf_skin_templates` VALUES ('369', '0', 'skin_boards', '<!--no data in this master skin-->', 'statusUpdates', '$updates=array(), $smallSpace=0, $latestOnly=0', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('370', '0', 'skin_boards', '<div id=\'active_chat\' class=\'stats_list\'>\n			<h2>\n				{$this->lang->words[\'whoschatting_total\']} {$this->lang->words[\'whoschatting_loadchat\']}\n			</h2>\n			{$this->lang->words[\'whoschatting_none\']}\n		</div>', 'whoschatting_empty', '', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('371', '0', 'skin_boards', '<div id=\'active_chat\' class=\'stats_list\'>\n			<h2>\n				{$total} {$this->lang->words[\'whoschatting_total\']} {$this->lang->words[\'whoschatting_loadchat\']}\n			</h2>\n			<if test=\"activeChat:|:count($names)\">\n				<ul>\n					<li>{parse expression=\"implode( \",</li><li>\", $names )\"}</li>\n				</ul>\n			</if>\n		</div>', 'whoschatting_show', '$total=\"\",$names=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('372', '0', 'skin_forum', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'attach_page_title\']}: $title</h3>\n	<if test=\"$pages\">\n		<div class=\'topic_controls\' style=\'padding-top: 4px;\'>{$pages}</div>\n	</if>\n<else />\n	<if test=\"$pages\">\n		<div class=\'topic_controls\'>{$pages}</div>\n	</if>\n	<h3 class=\'maintitle\'>{$this->lang->words[\'attach_page_title\']}: $title</h3>\n</if>\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th>&nbsp;</th>\n		<th>{$this->lang->words[\'attach_title\']}</th>\n		<th>{$this->lang->words[\'attach_size\']}</th>\n		<th>{$this->lang->words[\'attach_post\']}</th>\n	</tr>\n	{parse striping=\"attachies\" classes=\"row1,row2\"}\n	<if test=\"count($rows)\">\n		<foreach loop=\"attachments:$rows as $data\">\n			<tr class=\'{parse striping=\"attachies\"}\' id=\"{$data[\'attach_id\']}\">\n				<td class=\"altrow short\">\n					<img src=\"{$this->settings[\'mime_img\']}/{$data[\'image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" />\n				</td>\n				<td>\n					<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module=post&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\">{$data[\'short_name\']}</a><br />\n					<span class=\"desc\">( {$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']} )<br />( {$this->lang->words[\'attach_post_date\']} {$data[\'attach_date\']} )</span>\n				</td>\n				<td class=\"altrow short\">{$data[\'real_size\']}</td>\n				<td class=\'short\'><a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=findpost&amp;pid={$data[\'pid\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'view_post\']}\">{$data[\'pid\']}</a></td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<if test=\"$pages\">\n	<br />\n	<div class=\'topic_controls\'>{$pages}</div>\n</if>', 'forumAttachments', '$title, $rows, $pages', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('373', '0', 'skin_forum', '<h2>{parse expression=\"IPSText::truncate( $forum_data[\'name\'] )\"}</h2>\n	<if test=\"hassubforums:|:is_array( $sub_forum_data ) AND count( $sub_forum_data )\">\n		<div class=\'master_list\' id=\'board_index\'>\n			<foreach loop=\"subforums:$sub_forum_data as $_data\">\n				<if test=\"subforumdata:|:is_array( $_data[\'forum_data\'] ) AND count( $_data[\'forum_data\'] )\">\n					<foreach loop=\"forums:$_data[\'forum_data\'] as $forum_id => $forum_data\">				\n						<if test=\"forumRedirect:|:$forum_data[\'redirect_on\']\">\n							<div id=\"forum-{$forum_data[\'id\']}\" class=\'row touch-row\'>\n								<div class=\'icon\'>{parse replacement=\"f_redirect\"}</div>\n								<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\' class=\'title\'>{$forum_data[\'name\']}</a>\n								<br /><span class=\'desc\'>{$this->lang->words[\'rd_hits\']}: {parse format_number=\"$forum_data[\'redirect_hits\']\"}</span>\n							</div>\n						<else />\n							<div id=\"forum-{$forum_data[\'id\']}\" class=\'row touch-row\'>\n								<div class=\'icon\'>\n									<if test=\"unreadicon:|:$forum_data[\'img_new_post\'] != \'f_locked\' && strstr( $forum_data[\'img_new_post\'], \'unread\' )\">\n										<a href=\"{parse url=\"app=forums&amp;module=forums&amp;section=markasread&amp;marktype=forum&amp;forumid={$forum_data[\'id\']}&amp;returntoforumid={$this->request[\'f\']}&amp;i=1\" base=\"public\"}\" title=\"{$this->lang->words[\'bi_markread\']}\" class=\'forum_marker\'>\n											{parse replacement=\"f_unread\"}\n										</a>\n									<else />\n										{parse replacement=\"f_read\"}\n									</if>\n								</div>\n								<a href=\"{parse url=\"showforum={$forum_data[\'id\']}\" seotitle=\"{$forum_data[\'name_seo\']}\" template=\"showforum\" base=\"public\"}\" title=\'{$this->lang->words[\'go_to_forum\']}\' class=\'title\'>{$forum_data[\'name\']}</a>\n								<br /><span class=\'desc\'>{$forum_data[\'topics\']} {$this->lang->words[\'topics\']}</span>\n							</div>\n						</if>\n					</foreach>\n				</if>\n			</foreach>\n		</div>\n	</if>\n	\n	<div class=\'master_list\'>\n	<if test=\"showtopics:|:$forum_data[\'sub_can_post\']\">\n		\n		<!--<h2>{$forum_data[\'name\']}</h2>-->\n		<div class=\'controls\'>\n			<div class=\'buttons\'>\n				<if test=\"usercanpost:|:$forum_data[\'_user_can_post\']\">\n					<a href=\'{parse url=\"module=post&amp;section=post&amp;do=new_post&amp;f={$forum_data[\'id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'topic_start\']}\' accesskey=\'s\' class=\'button\'>{$this->lang->words[\'topic_start\']}</a>\n				</if>\n				{$forum_data[\'SHOW_PAGES\']}\n			</div>\n		</div>\n		\n		<if test=\"hasannouncements:|:is_array( $announce_data ) AND count( $announce_data )\">\n			<foreach loop=\"announcements:$announce_data as $aid => $adata\">\n				<div class=\'row touch-row\' id=\"ann-{$adata[\'announce_id\']}\">\n					<div class=\'icon\'>{parse replacement=\"t_announcement\"}</div>\n					<div class=\'rowContent\'>\n						<strong><a href=\"{parse url=\"showannouncement={$adata[\'announce_id\']}&amp;f={$forum_data[\'id\']}\" seotitle=\"%%{$adata[\'announce_title\']}%%\" template=\"showannouncement\" base=\"public\"}\" title=\'{$this->lang->words[\'view_announcement\']}\' class=\'title\'>{$adata[\'announce_title\']}</a></strong>\n					</div>\n				</div>\n			</foreach>\n		</if>\n		\n		<if test=\"hastopics:|:is_array( $topic_data ) AND count( $topic_data )\">\n			<h3>{$this->lang->words[\'forum_topic_list\']}</h3>\n			{parse striping=\"forumTable\" classes=\"row1,row2\"}\n			<foreach loop=\"topics:$topic_data as $tid => $data\">\n				<if test=\"queuedtopic:|:$data[\'approved\']\">\n					<div class=\'row touch-row <if test=\"$data[\'_unreadUrl\']\">unread</if> <if test=\"$data[\'_isDeleted\']\">moderated</if>\' id=\"topic-{$data[\'tid\']}\">\n						<div class=\'icon\'>\n							{parse template=\"generateTopicIcon\" group=\"global_other\" params=\"$data[\'folder_img\'], $data[\'_unreadUrl\']\"}\n						</div>\n						<div class=\'rowContent\'>\n							<if test=\"topichasattach:|:$data[\'topic_hasattach\']\">\n								{parse replacement=\"t_attach\"}\n							</if>\n							<a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;view=getnewpost\" base=\"public\" template=\"showtopic\" seotitle=\"{$data[\'title_seo\']}\"}\" class=\'topic_title title\'>{$data[\'title\']}</a>\n							{$data[\'prefix\']}\n							<if test=\"multipages:|:isset( $data[\'pages\'] ) AND is_array( $data[\'pages\'] ) AND count( $data[\'pages\'] )\">\n								<span class=\'mini_pagination\'>\n									{parse expression=\"sprintf( $this->lang->words[\'mini_page_count\'], $data[\'pages\'][0][\'total\'] )\"}\n								</span>\n							</if>\n							\n							<br />\n							<span class=\'subtext\'>\n								{parse format_number=\"$data[\'posts\']\"} <if test=\"replylang:|:intval($data[\'_posts\']) == 1\">{$this->lang->words[\'reply\']}<else />{$this->lang->words[\'replies\']}</if>: {$this->lang->words[\'lastby\']} {$data[\'last_poster_name\']}{parse template=\"user_popup\" group=\"global\" params=\"$data[\'last_poster_id\'], $data[\'seo_last_name\']\"}, {parse date=\"$data[\'last_post\']\" format=\"SHORT\"}\n							</span>\n						</div>\n					</div>\n				</if>\n			</foreach>\n		<else />\n			<div class=\'row no_messages\'>\n				{$this->lang->words[\'no_topics\']}\n			</div>\n		</if>\n		<div class=\'controls\'>\n			<div class=\'buttons\'>\n				<if test=\"usercanpost:|:$forum_data[\'_user_can_post\']\">\n					<a href=\'{parse url=\"module=post&amp;section=post&amp;do=new_post&amp;f={$forum_data[\'id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'topic_start\']}\' accesskey=\'s\' class=\'button\'>{$this->lang->words[\'topic_start\']}</a>\n				</if>\n				{$forum_data[\'SHOW_PAGES\']}\n			</div>\n		</div>\n	</if>	\n</div>', 'forumIndexTemplate', '$forum_data, $announce_data, $topic_data, $other_data, $multi_mod_data, $sub_forum_data, $footer_filter, $active_user_data, $mod_data, $inforum=1', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('374', '0', 'skin_forum', '<div class=\'master_list\'>\n	<div class=\'message\'>{$this->lang->words[\'need_password_txt\']}</div>\n	\n	<form action=\"{parse url=\"showforum={$fid}\" base=\"public\"}\" method=\"post\">\n		<input type=\"hidden\" name=\"L\" value=\"1\" />\n	\n		<h2>{$this->lang->words[\'need_password\']}</h2>\n		<div class=\'row\'>\n			{$this->lang->words[\'enter_pass\']}<br />\n			<input type=\"password\" size=\"30\" name=\"f_password\" id=\'forum_pass\' class=\'input_text\' />\n		</div>\n		<div class=\'submit\'>\n			<input type=\"submit\" value=\"{$this->lang->words[\'f_pass_submit\']}\" class=\"input_submit\" /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</div>\n	</form>\n</div>', 'forumPasswordLogIn', '$fid=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
