INSERT INTO `ibf_skin_templates` VALUES ('376', '0', 'skin_forum', '<!--no data in this master skin-->', 'likeSummaryContents', '$data, $relId, $opts=array()', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('377', '0', 'skin_forum', '<h2>{$rules[\'title\']}</h2>\n<div class=\'general_box\'>\n	<h3>{$this->lang->words[\'forum_rules\']}</h3>\n	<p><br />{$rules[\'body\']}</p>\n</div>\n<fieldset class=\'submit\'>\n	<a href=\"{parse url=\"showforum={$rules[\'fid\']}\" base=\"public\" seotitle=\"{$rules[\'fseo\']}\" template=\"showforum\"}\">{$this->lang->words[\'back_to_forum\']}</a>\n</fieldset>', 'show_rules', '$rules=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
