INSERT INTO `ibf_skin_templates` VALUES ('379', '0', 'skin_forum', '<span class=\'mini_rate\'>\n<foreach loop=\"ratings:array(1,2,3,4,5) as $int\">\n	<if test=\"ratinggood:|:$rating_id >= $int\">\n		{parse replacement=\"mini_rate_on\"}\n	<else />\n		{parse replacement=\"mini_rate_off\"}\n	</if>\n</foreach>\n</span>', 'topic_rating_image', '$rating_id=1', '1338050062', '0', '0', '0', '0', 'mobile');
