INSERT INTO `ibf_skin_templates` VALUES ('417', '0', 'skin_topic', '<div class=\'general_box alt poll\' id=\'poll_{$poll[\'pid\']}\'>\n	<form action=\"{parse url=\"app=forums&amp;module=extras&amp;section=vote&amp;t={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}&amp;do=add&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\" name=\'pollForm\' method=\"post\">\n		<h3>{$this->lang->words[\'poll\']} {$poll[\'poll_question\']}<if test=\"showPollResults:|:$showResults\"> <span class=\'desc\'>({$poll[\'_totalVotes\']} {$this->lang->words[\'poll_vote_casted\']})</span></if></h3>\n		<if test=\"publicPollNotice:|:$this->settings[\'poll_allow_public\'] AND $poll[\'poll_view_voters\'] AND ! $showResults\">\n			<div class=\'message unspecified\'>{$this->lang->words[\'poll_public_notice\']}</div>\n		</if>\n		<foreach loop=\"poll_questions:$pollData as $questionID => $questionData\">\n			<div class=\'<if test=\"votedClass:|:$showResults\"> voted</if>\'>\n				<h2 class=\'secondary\'>{$pollData[ $questionID ][\'question\']}</h2>\n				<if test=\"noGuestVote:|:! $this->settings[\'allow_result_view\'] AND ! $this->memberData[\'member_id\']\">\n					{$this->lang->words[\'poll_noview_guest\']}\n				<else />\n					<ol>\n						<foreach loop=\"poll_choices:$pollData[ $questionID ][\'choices\'] as $choiceID => $choiceData\">\n							<if test=\"showingResults:|:$showResults\">\n								<li class=\'row\'>\n									<span class=\'answer\'><if test=\"hasVoters:|:is_array( $choiceData[\'voters\'] ) AND in_array( $this->memberData[\'member_id\'], array_keys( $choiceData[\'voters\'] ) )\"> {parse replacement=\"your_vote\"} </if>{$choiceData[\'choice\']}</span>\n									<span class=\'votes\'> ({$choiceData[\'votes\']} {$this->lang->words[\'poll_votes\']} [{$choiceData[\'percent\']}%])</span>\n									<p class=\'progress_bar topic_poll\' title=\'{$this->lang->words[\'poll_percent_of_vote\']} {$choiceData[\'percent\']}%\'>\n										<span style=\'width: {$choiceData[\'percent\']}%\'><span>{$this->lang->words[\'poll_percent_of_vote\']} {$choiceData[\'percent\']}%</span></span>\n									</p>\n								</li>\n							<else />\n								<if test=\"multiVote:|:$choiceData[\'type\'] == \'multi\'\">\n									<li class=\'row\'><input type=\'checkbox\' id=\'choice_{$questionID}_{$choiceID}\' name=\'choice_{$questionID}_{$choiceID}\' value=\'1\' class=\'input_check\' /> <label for=\'choice_{$questionID}_{$choiceID}\'>{$choiceData[\'choice\']}</label></li>\n								<else />\n									<li class=\'row\'><input type=\'radio\' name=\'choice[{$questionID}]\' id=\'choice_{$questionID}_{$choiceID}\' class=\'input_radio\' value=\'{$choiceID}\' /> <label for=\'choice_{$questionID}_{$choiceID}\'>{$choiceData[\'choice\']}</label></li>\n								</if>\n							</if>\n						</foreach>\n					</ol>\n				</if>\n			</div>\n		</foreach>\n		<if test=\"voteButton:|:$topicData[\'state\'] != \'closed\'\">\n			<fieldset class=\'submit\'>\n				<legend>{$this->lang->words[\'poll_vote\']}</legend>\n				<if test=\"voteButtonMid:|:$this->memberData[\'member_id\']\">\n					<if test=\"voteButtonVoted:|:$poll[\'_memberVoted\']\">\n						<if test=\"deleteVote:|:$this->settings[\'poll_allow_vdelete\'] OR $this->memberData[\'g_is_supmod\']\">\n							<a href=\'{parse url=\"app=forums&amp;module=extras&amp;section=vote&amp;t={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}&amp;do=delete&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'poll_delete_vote\']}\' id=\'poll_deletevote\' class=\'button secondary\'>{$this->lang->words[\'poll_delete_vote\']}</a>\n						<else />\n							{$this->lang->words[\'poll_you_voted\']}\n						</if>\n					<else />\n						<if test=\"youCreatedPoll:|:($poll[\'starter_id\'] == $this->memberData[\'member_id\']) and ($this->settings[\'allow_creator_vote\'] != 1)\">\n							{$this->lang->words[\'poll_you_created\']}\n						<else />\n							<!-- VOTE Button -->\n							<if test=\"cast:|:$this->request[\'mode\'] != \'show\'\">\n								<input class=\'button secondary\' type=\"submit\" name=\"submit\" value=\"{$this->lang->words[\'poll_add_vote\']}\" title=\"{$this->lang->words[\'tt_poll_vote\']}\" />\n							</if>\n							<!-- SHOW Button -->\n							<if test=\"displayVotes:|:$this->settings[\'allow_result_view\'] == 1\">\n								<if test=\"alreadyDisplayVotes:|:$this->request[\'mode\'] == \'show\'\">\n									<if test=\"viewVotersLink:|:! $poll_view_voters\">\n										<a href=\'{parse url=\"showtopic={$topicData[\'tid\']}&amp;st={$this->request[\'st\']}\" base=\"public\" seotitle=\"{$topicData[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'tt_poll_svote\']}\' id=\'poll_nullvote\' class=\'button secondary\'>{$this->lang->words[\'pl_show_vote\']}</a>\n									</if>\n								<else />\n									<a href=\'{parse url=\"showtopic={$topicData[\'tid\']}&amp;mode=show&amp;st={$this->request[\'st\']}\" base=\"public\" seotitle=\"{$topicData[\'title_seo\']}\" template=\"showtopic\"}\' title=\'{$this->lang->words[\'tt_poll_show\']}\' id=\'poll_showresults\' class=\'button secondary\'>{$this->lang->words[\'pl_show_results\']}</a>\n								</if>\n							<else />\n								<input class=\'button secondary\' type=\"submit\" name=\"nullvote\" value=\"{$this->lang->words[\'poll_null_vote\']}\" title=\"{$this->lang->words[\'tt_poll_null\']}\" />\n							</if>\n						</if>\n					</if>\n				<else />\n					{$this->lang->words[\'poll_no_guests\']}\n				</if>\n			</fieldset>\n		</if>\n	</form>\n</div>', 'pollDisplay', '$poll, $topicData, $forumData, $pollData, $showResults', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('418', '0', 'skin_topic', '<!--no data in this master skin-->', 'post', '$post, $displayData, $topic, $forum=array()', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('419', '0', 'skin_topic', '{$post[\'post\']}\n    {$post[\'attachmentHtml\']}\n	<br />\n	<if test=\"editByQe:|:$post[\'edit_by\']\">\n		<p class=\'edit\'>\n			{$post[\'edit_by\']}\n			<if test=\"editReasonQe:|:$post[\'post_edit_reason\'] != \'\'\">\n				<br />\n				<span class=\'reason\'>{$this->lang->words[\'reason_for_edit\']}: {$post[\'post_edit_reason\']}</span>\n			</if>\n		</p>\n	</if>', 'quickEditPost', '$post', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('420', '0', 'skin_topic', '<div id=\'attach_wrap\' class=\'rounded clearfix\'>\n	<h4>$title</h4>\n	<ul>\n		<foreach loop=\"attach:$data as $file\">\n			<li class=\'<if test=\"attachType:|:$type == \'attach\'\">clear</if>\'>\n				{$file}\n			</li>\n		</foreach>\n	</ul>\n</div>', 'show_attachment_title', '$title=\"\",$data=\"\",$type=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('421', '0', 'skin_topic', '<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\"><img src=\"{$this->settings[\'public_dir\']}{$data[\'mime_image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" /></a>\n&nbsp;<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\">{$data[\'attach_file\']}</a> <span class=\'desc\'><strong>({$data[\'file_size\']})</strong></span>\n<br /><span class=\"desc info\">{$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']}</span>', 'Show_attachments', '$data=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('422', '0', 'skin_topic', '<a class=\'resized_img\' rel=\'lightbox[{$data[\'attach_rel_id\']}]\' id=\'ipb-attach-url-{$data[\'_attach_id\']}\' href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'location\']} - {$this->lang->words[\'attach_size\']} {$data[\'file_size\']}, {$this->lang->words[\'attach_ahits\']} {$data[\'attach_hits\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'o_location\']}\" class=\'bbc_img linked-image\' alt=\"{$this->lang->words[\'pic_attach\']}: {$data[\'location\']}\" /></a>', 'Show_attachments_img', '$file_name=\"\"', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('423', '0', 'skin_topic', '<a class=\'resized_img\' rel=\'lightbox[{$data[\'attach_rel_id\']}]\' id=\'ipb-attach-url-{$data[\'_attach_id\']}\' href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'location\']} - {$this->lang->words[\'attach_size\']} {$data[\'file_size\']}, {$this->lang->words[\'attach_ahits\']} {$data[\'attach_hits\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'t_location\']}\" id=\'ipb-attach-img-{$data[\'_attach_id\']}\' class=\'attach\' alt=\"{$this->lang->words[\'pic_attach\']}\" /></a>', 'Show_attachments_img_thumb', '$data=array()', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('424', '0', 'skin_topic', '<php>\n	$_sD = $sdData[ $post[\'post\'][\'pid\'] ];\n	$_sM = $_sD;\n</php>\n	<div class=\'topic_reply moderated\' id=\'entry{$post[\'post\'][\'pid\']}\'>\n		<h2 class=\'secondary\'>\n			<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n				<img src=\'{$post[\'author\'][\'pp_thumb_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$post[\'author\'][\'members_display_name\'])\"}\" class=\'photo\' />\n				<a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}</span>\n			<else />\n				{$post[\'author\'][\'members_display_name\']}\n			</if>\n			<span class=\'subtext\'>{parse date=\"$post[\'post\'][\'post_date\']\" format=\"DATE\"}</span>\n		</h2>\n		<div id=\'postsDelete-{$post[\'post\'][\'pid\']}\'>\n			<div class=\'padding\'>\n				<strong>{$this->lang->words[\'post_deleted_by\']} <a href=\'{parse url=\"showuser={$_sD[\'sdl_obj_member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$_sM[\'members_seo_name\']}\"}\'>{$_sM[\'members_display_name\']}</a> {$this->lang->words[\'on\']} {parse date=\"$_sD[\'sdl_obj_date\']\" format=\"long\"}.</strong>\n				<if test=\"showReason:|:$post[\'post\'][\'_softDeleteReason\']\">\n					<p class=\'desc\'><if test=\"$_sD[\'sdl_obj_reason\']\">{$_sD[\'sdl_obj_reason\']}<else />{$this->lang->words[\'no_reason_given\']}</if></p>\n				</if>\n				\n				<if test=\"sdOptions:|:$post[\'post\'][\'_softDeleteContent\'] OR $post[\'post\'][\'_softDeleteRestore\']\">			\n					<if test=\"$post[\'post\'][\'_softDeleteContent\']\">\n						<br />\n						<span class=\'post_toggle sd_content\' id=\'seeContent_{$post[\'post\'][\'pid\']}\'>\n							<a class=\'button secondary\' href=\'#\'><span>{$this->lang->words[\'togglepostcontent\']}</span></a>\n						</span>\n					</if>\n				</if>\n			</div>\n		</div>\n		<div id=\"post-{$post[\'post\'][\'pid\']}\" class=\'post line_spacing\' style=\'display: none\'>\n			<if test=\"userIgnored:|:($post[\'post\'][\'_repignored\'] == 1 || $post[\'post\'][\'_ignored\']) AND $this->request[\'view_ignored\'] != $post[\'post\'][\'pid\']\">\n				<div class=\'post_ignore\'>\n					<if test=\"userIgnoredLang:|:$post[\'post\'][\'_repignored\'] == 1\">{$this->lang->words[\'post_ignored_rep\']}<else />{$this->lang->words[\'post_ignored\']}</if> <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}. <a href=\'{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;st={$this->request[\'st\']}&amp;view_ignored={$post[\'post\'][\'pid\']}\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}#entry{$post[\'post\'][\'pid\']}\' title=\'{$this->lang->words[\'ignore_view_post\']}\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n					<if test=\"userIgnoredLangTwo:|:$this->settings[\'reputation_enabled\'] AND $post[\'post\'][\'_repignored\'] == 1\"><div><a href=\"{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;st={$this->request[\'st\']}&amp;rep_filter_set=*&amp;rep_filter=update\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\">{$this->lang->words[\'post_ignore_reset_rep\']}</a></div></if>\n				</div>\n			<else />\n				{$post[\'post\'][\'post\']}\n				{$post[\'post\'][\'attachmentHtml\']}\n				<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n					<br />\n					<strong>{$post[\'post\'][\'edit_by\']}</strong>\n					<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n						<br />\n						<span class=\'subtext\'>{$this->lang->words[\'reason_for_edit\']}: {$post[\'post\'][\'post_edit_reason\']}</span>\n					</if>\n				</if>\n			</if>\n		</div>\n		<div id=\"post-{$post[\'post\'][\'pid\']}-controls\" class=\'post_controls\'>\n			<a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{parse replacement=\"reply_post_icon\"} {$this->lang->words[\'post_reply\']}</a>\n			<if test=\"canEdit:|:$post[\'post\'][\'_can_edit\'] === TRUE\">\n				<a href=\'{parse url=\"module=post&amp;section=post&amp;do=edit_post&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_edit_title\']}\' class=\'edit_post\' id=\'edit_post_{$post[\'post\'][\'pid\']}\'>{parse replacement=\"edit_post_icon\"} {$this->lang->words[\'post_edit\']}</a>\n			</if>\n			<if test=\"canDelete:|:$post[\'post\'][\'_can_delete\'] === TRUE\">\n				<a href=\'{parse url=\"module=moderate&amp;section=moderate&amp;do=04&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'delete_post\'>{parse replacement=\"delete_post_icon\"} {$this->lang->words[\'post_delete\']}</a>\n			</if>\n		</div>\n	</div>', 'softDeletedPostBit', '$post, $sdData, $topic', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('425', '0', 'skin_topic', '<!--no data in this master skin-->', 'topicPreview', '$topic, $posts', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('426', '0', 'skin_topic', '<if test=\"$this->settings[\'_mobile_back_nav\'] = 1\"></if>\n<div class=\'master_list\'>\n	<h2>\n		{parse expression=\"IPSText::truncate( $topic[\'title\'], 45 )\"}\n	</h2>\n	<div class=\'controls\'>\n		<div class=\'buttons\'>\n			<if test=\"closedButton:|:$displayData[\'reply_button\'][\'image\'] == \'locked\'\">\n				<if test=\"closedButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n					<a href=\'{$displayData[\'reply_button\'][\'url\']}\' accesskey=\'r\' class=\'button locked\'>{$this->lang->words[\'mobile_top_locked_reply\']}</a>\n				<else />\n					<span class=\'button locked\'>{$this->lang->words[\'mobile_top_locked\']}</span>\n				</if>\n			<else />\n				<if test=\"replyButton:|:$displayData[\'reply_button\'][\'image\']\">\n					<if test=\"replyButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n						<a href=\'{$displayData[\'reply_button\'][\'url\']}\' title=\'{$this->lang->words[\'mobile_topic_add_reply\']}\' accesskey=\'r\' class=\'button\'>{$this->lang->words[\'mobile_topic_add_reply\']}</a>\n					</if>\n				</if>\n			</if>\n		{$topic[\'SHOW_PAGES\']}\n		</div>\n	</div>\n	\n	{$displayData[\'poll_data\'][\'html\']}\n	\n	<if test=\"hasPosts:|:is_array( $post_data ) AND count( $post_data )\">\n		<foreach loop=\"post_data:$post_data as $post\">\n			<if test=\"sDeleted:|:$post[\'post\'][\'_isDeleted\'] AND $post[\'post\'][\'_softDeleteSee\']\">\n				{parse template=\"softDeletedPostBit\" group=\"topic\" params=\"$post, $displayData[\'sdData\'], $topic\"}\n			<else />\n				<if test=\"deleted:|:!$post[\'post\'][\'_isDeleted\']\">\n					<div class=\'topic_reply\' id=\'entry{$post[\'post\'][\'pid\']}\'>\n						<h2 class=\'secondary\'>\n							{parse template=\"repButtons\" group=\"global_other\" params=\"$post[\'author\'], array_merge( array( \'primaryId\' => $post[\'post\'][\'pid\'], \'domLikeStripId\' => \'like_post_\' . $post[\'post\'][\'pid\'], \'domCountId\' => \'rep_post_\' . $post[\'post\'][\'pid\'], \'app\' => \'forums\', \'type\' => \'pid\', \'likeFormatted\' => $post[\'post\'][\'like\'][\'formatted\'] ), $post[\'post\'] )\"}\n							<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n								<img src=\'{$post[\'author\'][\'pp_thumb_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$post[\'author\'][\'members_display_name\'])\"}\" class=\'photo\' />\n								<a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}</span>\n							<else />\n								{$post[\'author\'][\'members_display_name\']}\n							</if>\n							<span class=\'subtext\'>{parse date=\"$post[\'post\'][\'post_date\']\" format=\"DATE\"}</span>\n						</h2>\n						<div id=\"post-{$post[\'post\'][\'pid\']}\" class=\'post line_spacing\'>\n							<if test=\"userIgnored:|:($post[\'post\'][\'_repignored\'] == 1 || $post[\'post\'][\'_ignored\']) AND $this->request[\'view_ignored\'] != $post[\'post\'][\'pid\']\">\n								<div class=\'post_ignore\'>\n									<if test=\"userIgnoredLang:|:$post[\'post\'][\'_repignored\'] == 1\">{$this->lang->words[\'post_ignored_rep\']}<else />{$this->lang->words[\'post_ignored\']}</if> <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}. <a href=\'{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;st={$this->request[\'st\']}&amp;view_ignored={$post[\'post\'][\'pid\']}\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}#entry{$post[\'post\'][\'pid\']}\' title=\'{$this->lang->words[\'ignore_view_post\']}\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n									<if test=\"userIgnoredLangTwo:|:$this->settings[\'reputation_enabled\'] AND $post[\'post\'][\'_repignored\'] == 1\"><div><a href=\"{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;st={$this->request[\'st\']}&amp;rep_filter_set=*&amp;rep_filter=update\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\">{$this->lang->words[\'post_ignore_reset_rep\']}</a></div></if>\n								</div>\n							<else />\n								{$post[\'post\'][\'post\']}\n								{$post[\'post\'][\'attachmentHtml\']}\n		\n								<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n									<br />\n									<strong>{$post[\'post\'][\'edit_by\']}</strong>\n									<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n										<br />\n										<span class=\'subtext\'>{$this->lang->words[\'reason_for_edit\']}: {$post[\'post\'][\'post_edit_reason\']}</span>\n									</if>\n								</if>\n							</if>\n						</div>\n						<div id=\"post-{$post[\'post\'][\'pid\']}-controls\" class=\'post_controls\'>\n							<a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{$this->lang->words[\'post_reply\']}</a>\n							<if test=\"canEdit:|:$post[\'post\'][\'_can_edit\'] === TRUE\">\n								<a href=\'{parse url=\"module=post&amp;section=post&amp;do=edit_post&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_edit_title\']}\' class=\'edit_post\' id=\'edit_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'post_edit\']}</a>\n							</if>\n							<if test=\"canDelete:|:$post[\'post\'][\'_can_delete\'] === TRUE\">\n								<a href=\'{parse url=\"module=moderate&amp;section=moderate&amp;do=04&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'delete_post\'>{$this->lang->words[\'post_delete\']}</a>\n							</if>\n						</div>\n					</div>\n				</if>\n			</if>\n		</foreach>\n	</if>\n	<if test=\"canShare:|:!$forum[\'disable_sharelinks\'] AND $this->settings[\'sl_enable\']\">\n		<div id=\'shareStrip\'>\n			<a class=\'button secondary\' id=\'share_facebook_trigger\' href=\'#\'>{$this->lang->words[\'share\']} <img src=\"{$this->settings[\'public_dir\']}style_extra/sharelinks/facebook.png\" /></a>\n			<a class=\'button secondary\' id=\'share_twitter_trigger\' href=\'#\'>{$this->lang->words[\'share\']} <img src=\"{$this->settings[\'public_dir\']}style_extra/sharelinks/twitter.png\" /></a>\n		</div>\n	</if>\n	<div class=\'controls\'>\n		<div class=\'buttons\'>\n			<if test=\"closedButton:|:$displayData[\'reply_button\'][\'image\'] == \'locked\'\">\n				<if test=\"closedButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n					<a href=\'{$displayData[\'reply_button\'][\'url\']}\' accesskey=\'r\' class=\'button locked\'>{$this->lang->words[\'mobile_top_locked_reply\']}</a>\n				<else />\n					<span class=\'button locked\'>{$this->lang->words[\'mobile_top_locked\']}</span>\n				</if>\n			<else />\n				<if test=\"replyButton:|:$displayData[\'reply_button\'][\'image\']\">\n					<if test=\"replyButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n						<a href=\'{$displayData[\'reply_button\'][\'url\']}\' title=\'{$this->lang->words[\'mobile_topic_add_reply\']}\' accesskey=\'r\' class=\'button\'>{$this->lang->words[\'mobile_topic_add_reply\']}</a>\n					</if>\n				</if>\n			</if>\n		{$topic[\'SHOW_PAGES\']}\n		</div>\n	</div>\n	<if test=\"fastReply:|:$displayData[\'fast_reply\'] != \'unavailable\' && $displayData[\'reply_button\'][\'url\']\">\n		<h2>{$this->lang->words[\'qr_title\']}</h2>\n		<div class=\'row\'>\n			<form action=\"{parse url=\"\" base=\"public\"}\" method=\"post\">\n				<input type=\"hidden\" name=\"app\" value=\"forums\" />\n				<input type=\"hidden\" name=\"module\" value=\"post\" />\n				<input type=\"hidden\" name=\"section\" value=\"post\" />\n				<input type=\"hidden\" name=\"do\" value=\"reply_post_do\" />\n				<input type=\"hidden\" name=\"f\" value=\"{$forum[\'id\']}\" />\n				<input type=\"hidden\" name=\"t\" value=\"{$topic[\'tid\']}\" />\n				<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n				<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n				<input type=\"hidden\" name=\"fast_reply_used\" value=\"1\" />\n				<input type=\"hidden\" name=\"enableemo\" value=\"yes\" />\n				<input type=\"hidden\" name=\"enablesig\" value=\"yes\" />\n				<if test=\"$this->memberData[\'auto_track\']\">\n					<input type=\"hidden\" name=\"enabletrack\" value=\"1\" />\n				</if>\n				<if test=\"is_array($topic[\'_fastReplyStatusMessage\']) AND count($topic[\'_fastReplyStatusMessage\']) AND strlen($topic[\'_fastReplyStatusMessage\'][0])\">\n					<div class=\'message\'>{parse expression=\"implode( \'<br />\', $topic[\'_fastReplyStatusMessage\'])\"}</div>\n				</if>\n				{parse template=\"editorShell\" group=\"editors\" params=\"\'fast-reply\', \'Post\', \'\', 1\"}\n				<div class=\"buttons\"><input type=\'submit\' name=\"submit\" class=\'button page-button\' value=\'{$this->lang->words[\'qr_post\']}\' tabindex=\'0\' accesskey=\'s\' id=\'submit_post\' /></div>\n			</form>\n		</div>\n	</if>\n</div>\n<script type=\"text/javascript\">\n	document.observe(\"dom:loaded\", function(){\n				  	\n		/* Facebook */\n		$(\'share_facebook_trigger\').on(\'click\', _fireFacebook );\n		\n		\n		/* Twitter */\n		$(\'share_twitter_trigger\').on(\'click\', _fireTwitter );\n		\n		$$(\'.bbc_spoiler_show\').find( function( elem ) {\n			elem.addClassName( \'button page-button\' ).setStyle( { \'font-size\' : \'12px\', \'padding\': \'5px\' } );\n			elem.observe(\'click\', _fireSpoiler );\n		} ) } );\n	\n	function _fireTwitter(e)\n	{\n		Event.stop(e);\n				\n		_url   = \'{parse expression=\"$this->registry->output->getCanonicalUrl()\"}\';\n		_title = $$(\'meta[property~=\"og:title\"]\').first().readAttribute(\'content\');\n		\n		window.open(\'http://twitter.com/intent/tweet?url=\' +  encodeURIComponent( _url ) + \'&text=\' + encodeURIComponent( _title ) );\n	}\n	\n	function _fireFacebook(e)\n	{\n		Event.stop(e);\n		\n		_url   = \'{parse expression=\"$this->registry->output->getCanonicalUrl()\"}\';\n		_title = $$(\'meta[property~=\"og:title\"]\').first().readAttribute(\'content\');\n		window.open(\'http://www.facebook.com/sharer.php?u=\' + encodeURIComponent( _url ) + \'&t=\' + encodeURIComponent( _title ) );\n	}\n	\n	function _fireSpoiler(e)\n	{\n		button = Event.element(e);\n		\n		Event.stop(e);\n		var returnvalue = $(button).up().down(\'.bbc_spoiler_wrapper\').down(\'.bbc_spoiler_content\').toggle();\n		\n		if( returnvalue.visible() )\n		{\n			$(button).value = ipb.lang[\'spoiler_hide\'];\n		}\n		else\n		{\n			$(button).value = ipb.lang[\'spoiler_show\'];\n		}\n	}\n</script>', 'topicViewTemplate', '$forum, $topic, $post_data, $displayData', '1338050062', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('427', '0', 'skin_messaging', '<h3>{$this->lang->words[\'pm_disabled_title\']}</h3>\n<div class=\'ipsPad\'>\n	{$this->lang->words[\'your_pm_is_disabled\']}\n	<if test=\"notByAdmin:|:$this->memberData[\'members_disable_pm\'] != 2\">\n	<p class=\'ipsForm_center\'>\n		<br />\n		<a href=\"{parse url=\"module=messaging&amp;section=view&amp;do=enableMessenger&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\" class=\'ipsButton_secondary\'>{$this->lang->words[\'pm_disabled_reactivate\']}</a>\n		<a href=\'{parse url=\"act=idx\" template=\"act=idx\" seotitle=\"true\"  base=\"public\"}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'go_board_index\']}</a>\n		</p>\n	</if>\n </div>', 'messengerDisabled', '', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('428', '0', 'skin_messaging', '{parse js_module=\"messenger\"}\n<script type=\"text/javascript\">\n	ipb.messenger.disabled  = {parse expression=\"intval($this->memberData[\'members_disable_pm\'])\"};\n</script>\n<if test=\"PMDisabled:|:$this->memberData[\'members_disable_pm\']\">\n<noscript>\n	{parse template=\"messengerDisabled\" group=\"messaging\"}\n</noscript>\n</if>\n<div id=\'messenger_utilities\' class=\'left\'>\n	<!-- Show topic participants -->\n	<if test=\"hasParticipants:|:is_array( $topicParticipants ) and count( $topicParticipants )\">\n		<div class=\'ipsSideBlock\' id=\'participants\'>\n			<h3 class=\'bar\'>{$this->lang->words[\'participants\']}</h3>\n			<ul id=\'participants_list\' class=\'ipsList_withminiphoto\'>\n				<foreach loop=\"participants:$topicParticipants as $memberID => $memberData\">\n					<li class=\'clearfix\'>\n						<if test=\"isMemberPartOpen:|:$memberData[\'member_id\']\"><a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'></if><img src=\'{$memberData[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini<if test=\"isMemberPartFloat:|:!$memberData[\'member_id\']\"> left</if>\' /><if test=\"isMemberPartClose:|:$memberData[\'member_id\']\"></a></if>\n						<p class=\'list_content\'>\n							<if test=\"userIsActive:|:$memberData[\'map_user_active\']\">\n								<if test=\"userIsStarter:|:$memberData[\'map_is_starter\']\">\n									<span class=\'name starter\'>{parse template=\"userHoverCard\" group=\"global\" params=\"$memberData\"}</span>\n								<else />\n									<span class=\'name\'>{parse template=\"userHoverCard\" group=\"global\" params=\"$memberData\"}</span>\n								</if>\n								<br />\n								<span class=\'ipsType_smaller desc\'>\n									<if test=\"messageIsDeleted:|:$memberData[\'_topicDeleted\']\">\n										<em>{$this->lang->words[\'topic_deleted\']}</em>\n									<else />\n										{$this->lang->words[\'last_read\']}\n										<if test=\"lastReadTime:|:$memberData[\'map_read_time\']\">\n											{parse date=\"$memberData[\'map_read_time\']\" format=\"short\"}\n										<else />\n											<em>{$this->lang->words[\'not_yet_read\']}</em>\n										</if>\n									</if>\n									<if test=\"notification:|:$memberData[\'map_ignore_notification\']\">\n										<span class=\'ipsBadge ipsBadge_lightgrey right\'>{$this->lang->words[\'msg_no_notify\']}</span>\n									</if>						\n								</span>\n								<if test=\"blockUserLink:|:! $memberData[\'map_is_starter\'] AND $memberData[\'_canBeBlocked\'] AND ($topicParticipants[ $this->memberData[\'member_id\'] ][\'map_is_starter\'] OR $this->memberData[\'g_is_supmod\']) AND ( $memberData[\'map_user_id\'] != $this->memberData[\'member_id\'] ) AND !$memberData[\'_topicDeleted\']\">\n									<br /><a href=\"{parse url=\"module=messaging&amp;section=view&amp;do=blockParticipant&amp;topicID={$this->request[\'topicID\']}&amp;memberID={$memberData[\'map_user_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\" title=\'{$this->lang->words[\'block_this_user\']}\' class=\'cancel\'>{$this->lang->words[\'block\']}</a>\n								</if>\n							<else />\n								<if test=\"userIsBanned:|:$memberData[\'map_user_banned\']\">\n									<span class=\'name blocked\'><a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$memberData[\'members_display_name_short\']}</strong></a></span>\n									<br />\n									<span class=\'desc\'>{$this->lang->words[\'user_is_blocked\']}</span>\n									<br />\n									<if test=\"unbanUserLink:|:$memberData[\'_canBeBlocked\'] AND ($topicParticipants[ $this->memberData[\'member_id\'] ][\'map_is_starter\'] OR $this->memberData[\'g_is_supmod\'])\">\n										<a href=\"{parse url=\"module=messaging&amp;section=view&amp;do=unblockParticipant&amp;topicID={$this->request[\'topicID\']}&amp;memberID={$memberData[\'map_user_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\" title=\'{$this->lang->words[\'unblock_this_user\']}\' class=\'cancel\'>{$this->lang->words[\'unblock\']}</a>\n									</if>\n								<else />\n									<span class=\'name left_convo\'><a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$memberData[\'members_display_name_short\']}</strong></a></span>\n									<br />\n									<span class=\'desc\'>\n										<if test=\"topicUnavailable:|:$memberData[\'_topicDeleted\']\">\n										<em>{$this->lang->words[\'topic_deleted\']}</em>\n										<else />\n											<if test=\"systemMessage:|:$memberData[\'map_is_system\']\">\n												{$this->lang->words[\'is_unable_part\']}\n											<else />\n												{$this->lang->words[\'has_left_convo\']}\n											</if>\n										</if>\n									</span>\n								</if>\n							</if>\n						</p>\n					</li>\n				</foreach>					\n			</ul>\n			<ul class=\'post_controls\'>\n				<li>\n					<a href=\'{parse url=\"module=messaging&amp;section=view&amp;do=toggleNotifications&amp;topicID={$this->request[\'topicID\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'toggle_noti_title\']}\'>\n					<if test=\"changeNotifications:|:$topicParticipants[ $this->memberData[\'member_id\'] ][\'map_ignore_notification\']\">\n						{$this->lang->words[\'turn_noti_on\']}\n					<else />\n						{$this->lang->words[\'turn_noti_off\']}\n					</if>\n					</a>\n				</li>\n			</ul>\n		</div>\n		<if test=\"inviteMoreParticipants:|:$this->memberData[\'g_max_mass_pm\'] && count( $topicParticipants ) < $this->memberData[\'g_max_mass_pm\'] && ! $deletedTopic\">\n			<div id=\'invite_more\' class=\'ipsSideBlock\'>\n				<h3>{$this->lang->words[\'invite_part\']}</h3>\n				<div id=\'invite_more_dialogue\'>\n					<form method=\'post\' action=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=addParticipants\" base=\"public\"}\'>\n					<input type=\'hidden\' name=\'authKey\' value=\'{$this->member->form_hash}\' />\n					<input type=\'hidden\' name=\'topicID\' value=\'{$this->request[\'topicID\']}\' />\n					<input type=\'hidden\' name=\'st\' value=\'{$this->request[\'st\']}\' />\n					<ul><li><label for=\'invite_more_autocomplete\'>{$this->lang->words[\'enter_member_names\']}</label> \n					<input type=\'text\' class=\'input_text\' name=\'inviteNames\' id=\'invite_more_autocomplete\' value=\'{$this->request[\'inviteNames\']}\' size=\'38\' /> \n					<br /><span class=\'desc\'>[x]{$this->lang->words[\'separated_with_commas\']}</span> \n					</li></ul><fieldset class=\'submit\'><input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'part_add\']}\' />  \n					{$this->lang->words[\'or\']} <a href=\'#\' id=\'invite_more_cancel\' class=\'cancel\' title=\'{$this->lang->words[\'cancel\']}\'>{$this->lang->words[\'cancel\']}</a></fieldset></form>\n				</div>\n				<div id=\'invite_more_default\'>\n					<if test=\"unlimitedInvites:|:$this->memberData[\'g_max_mass_pm\'] == 0\">\n						<p class=\'desc\'>{$this->lang->words[\'can_invite_unlimited\']}</p>\n						<script type=\'text/javascript\'>\n							ipb.messenger.invitesLeft = parseInt( 0 );\n							ipb.messenger.nameText = ipb.lang[\'enter_unlimited_names\'];\n						</script>\n					<else />\n						<p class=\'desc\'>{$this->lang->words[\'may_invite_upto\']} <strong>{parse expression=\"( $this->memberData[\'g_max_mass_pm\'] - count( $topicParticipants ) )\"}</strong> {$this->lang->words[\'more_members\']}</p>\n						<script type=\'text/javascript\'>\n							ipb.messenger.invitesLeft = parseInt( {parse expression=\"( $this->memberData[\'g_max_mass_pm\'] - count( $topicParticipants ) )\"} );\n							ipb.messenger.nameText = ipb.lang[\'enter_x_names\'].gsub(/\\[x\\]/, ipb.messenger.invitesLeft);\n						</script>\n					</if>\n					<ul class=\'post_controls\'>\n						<li id=\'add_participants\'><a href=\'#\' title=\'{$this->lang->words[\'add_participants\']}\'>{$this->lang->words[\'part_add\']}</a></li>\n					</ul>\n				</div>\n			</div>\n		</if>\n	</if>\n	<div id=\'folder_list\' class=\'ipsSideBlock\'>\n		<h3>{$this->lang->words[\'folders\']}</h3>\n		<ol id=\'folders\'>\n			<if test=\"myDirectories:|:count($dirData)\">\n				<foreach loop=\"dirs:$dirData as $id => $data\">\n					<if test=\"protectedFolder:|:$data[\'protected\']\">\n						<li class=\'folder protected\' id=\'f_{$id}\'>{parse replacement=\"folder_{$id}\"}\n					<else />\n						<li class=\'folder\' id=\'f_{$id}\'>{parse replacement=\"folder_generic\"}\n					</if>\n					<a href=\"{parse url=\"module=messaging&amp;section=view&amp;do=showFolder&amp;folderID={$id}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'go_to_folder\']}\" rel=\"folder_name\">{$data[\'real\']}</a>\n					<span class=\'total rounded\'>\n						<if test=\"allFolder:|:$id == \'all\'\">\n							{parse expression=\"intval($this->memberData[\'msg_count_total\'])\"}\n						<else />\n							{parse expression=\"intval($data[\'count\'])\"}\n						</if>\n					</span>\n					<if test=\"unprotectedFolder:|:! $data[\'protected\']\">\n						<span class=\'edit_folders\' style=\'display: none\'><a href=\'#\' id=\'delete_{$id}\' class=\'f_delete\' title=\"{$this->lang->words[\'delete_folder_title\']}\">{parse replacement=\"folder_delete\"}</a> <a href=\'#\' id=\'empty_{$id}\' class=\'f_empty\' title=\"{$this->lang->words[\'empty_folder_title\']}\">{parse replacement=\"folder_empty\"}</a></span></li>\n					<else />\n						<span class=\'edit_folders\' style=\'display: none\'><a href=\'#\' id=\'empty_{$id}\' class=\'f_empty\' title=\"{$this->lang->words[\'empty_folder_title\']}\">{parse replacement=\"folder_empty\"}</a></span></li>\n					</if>\n				</foreach>\n			</if>\n		</ol>\n		<div class=\'clearfix post_controls\'>\n			<ul class=\'post_controls\'>\n				<li id=\'add_folder\'><a href=\'#\' title=\'{$this->lang->words[\'add_folder\']}\'>{$this->lang->words[\'folder_add\']}</a></li>\n				<li id=\'edit_folders\'><a href=\'#\' title=\'{$this->lang->words[\'edit_folders\']}\'>{$this->lang->words[\'folders_edit\']}</a></li>\n			</ul>\n		</div>\n		<script type=\'text/javascript\'>\n		//<![CDATA[\n			ipb.messenger.folderTemplate = \"<li class=\'folder\' id=\'f_[id]\'>{parse replacement=\"folder_generic\"} <a href=\'{parse url=\"module=messaging&amp;section=view&amp;do=showFolder&amp;folderID=[id]\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'go_to_folder\']}\' rel=\'folder_name\'>[name]</a> <span class=\'total rounded\'>[total]</span><span class=\'edit_folders\' style=\'display: none\'><a href=\'#\' id=\'delete_[id]\' class=\'f_delete\' title=\'{$this->lang->words[\'delete_folder_title\']}\'>{parse replacement=\"folder_delete\"}</a> <a href=\'#\' id=\'empty_[id]\' class=\'f_empty\' title=\'{$this->lang->words[\'empty_folder_title\']}\'>{parse replacement=\"folder_empty\"}</a></span></li>\";\n		//]]>\n		</script>\n	</div>\n	<if test=\"storageBar:|:$this->memberData[\'g_max_messages\'] > 0\">\n		<div id=\'space_allowance\' class=\'ipsSideBlock\'>\n			<h3>{$this->lang->words[\'storage\']}</h3>\n			<p>{$this->lang->words[\'your_messenger_storage\']}</p>\n			<p class=\'progress_bar\' title=\'{parse expression=\"sprintf( $this->lang->words[\'pmpc_full_string\'], $totalData[\'full_percent\'] )\"}\' <if test=\"almostFull:|:$totalData[\'full_percent\'] > 80\">class=\'limit\'</if>>\n				<span style=\'width: {$totalData[\'full_percent\']}%\'>{$totalData[\'full_percent\']}%</span>\n			</p>\n			<p>\n				<span class=\'desc\'>{$totalData[\'full_percent\']}% {$this->lang->words[\'of_your_quota\']} ({$this->memberData[\'g_max_messages\']} {$this->lang->words[\'messages\']})</span>\n			</p>\n		</div>\n	</if>\n	<div id=\'message_search\' class=\'ipsSideBlock\'>\n		<h3>{$this->lang->words[\'search_messages\']}</h3>\n		<form action=\'{$this->settings[\'base_url\']}app=members&amp;module=messaging&amp;section=search\' method=\'post\'>\n			<fieldset>\n				<input type=\'text\' name=\'searchFor\' class=\'input_text\' size=\'15\' style=\'width: 60%\' /> <input type=\'submit\' class=\'input_submit\' value=\'{$this->lang->words[\'jmp_go\']}\' />\n			</fieldset>\n		</form>\n	</div>\n	<br />\n	\n	<a class=\'ipsButton_secondary cancel\' href=\"{parse url=\"module=messaging&amp;section=view&amp;do=disableMessenger&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\"\'>{$this->lang->words[\'disable_messenger\']}</a>\n	<!--<ul class=\'topic_buttons\'>\n		<li class=\'important\'></li>\n	</ul>-->\n</div>\n<div id=\'messenger_content\' class=\'right\'>\n	<if test=\"inlineError:|:$inlineError\">\n	<div class=\'message error\'>\n		<h4>{$inlineError}</h4>\n	</div>\n	<br />\n	</if>\n	{$html}\n</div>\n<!-- end -->\n<div id=\'pmDisabled\' style=\'display:none\'>\n	{parse template=\"messengerDisabled\" group=\"messaging\"}\n</div>\n<br class=\'clear\' />', 'messengerTemplate', '$html, $jumpmenu, $dirData, $totalData=array(), $topicParticipants=array(), $inlineError=\'\', $deletedTopic=0', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('429', '0', 'skin_messaging', '<form id=\'pm_to_member_{$toMemberData[\'member_id\']}\'>\n	<input type=\'hidden\' name=\'toMemberID\' value=\'{$toMemberData[\'member_id\']}\' />\n	\n	<fieldset class=\'row1\'>\n		<h3>{$this->lang->words[\'quick_send_to\']} {$toMemberData[\'members_display_name\']}</h3>\n		<div id=\'pm_error_{$toMemberData[\'member_id\']}\'>\n			<br />\n			<p class=\'message error\'></p>\n		</div>\n		<script type=\'text/javascript\'>\n			$(\'pm_error_{$toMemberData[\'member_id\']}\').hide();\n		</script>\n		<ul class=\'ipsForm ipsForm_vertical ipsPad\'>\n			<li class=\'ipsField\'>\n				<label for=\'pm_subject_{$toMemberData[\'member_id\']}\' class=\'ipsField_title\'>{$this->lang->words[\'quick_subject\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\'text\' class=\'input_text\' id=\'pm_subject_{$toMemberData[\'member_id\']}\' name=\'msg_title\' size=\'50\' tabindex=\'0\' />\n				</p>\n			</li>\n			<li class=\'ipsField\'>\n				<label for=\'pm_textarea_{$toMemberData[\'member_id\']}\' class=\'ipsField_title\'>{$this->lang->words[\'quick_message\']}</label>\n				<p class=\'ipsField_content\'>\n					<textarea class=\'input_text\' name=\'Post\' tabindex=\'0\' id=\'pm_textarea_{$toMemberData[\'member_id\']}\' cols=\'65\' rows=\'8\'></textarea>\n				</p>\n			</li>\n		</ul>\n	</fieldset>\n	<fieldset class=\'submit\'>\n		<input type=\'submit\' class=\'input_submit\' name=\'send_msg\' value=\'{$this->lang->words[\'quick_send_button\']}\' accesskey=\'s\' tabindex=\'0\' /> <input type=\'submit\' class=\'input_submit alt use_full\' name=\'use_full\' value=\'{$this->lang->words[\'use_full_editor\']}\' tabindex=\'0\' /> {$this->lang->words[\'or\']} <a href=\'#\' class=\'cancel\' title=\'{$this->lang->words[\'cancel\']}\' id=\'pm_cancel_{$toMemberData[\'member_id\']}\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n	</fieldset>\n</form>', 'PMQuickForm', '$toMemberData', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('430', '0', 'skin_messaging', '<div id=\'message_compose\' class=\'post_form\'>\n	<form id=\'msgForm\' style=\'display:block\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=send\" base=\"publicWithApp\"}\" method=\"post\" enctype=\'multipart/form-data\'>\n	\n<if test=\"newTopicPreview:|:$displayData[\'preview\']\">\n	<h2 class=\'maintitle\'>{$this->lang->words[\'pm_preview\']}</h2>\n	<div class=\'post_wrap\' id=\'post_preview\'>\n		<div class=\'row2\' style=\'padding:8px\'>\n			<div class=\'post entry-content\'>{$displayData[\'preview\']}</div>\n		</div>\n	</div>\n	<br />\n</if>\n<h2 class=\'maintitle\'>{$this->lang->words[\'mess_new\']}</h2>\n<if test=\"newTopicError:|:is_array($displayData[\'errors\']) AND count($displayData[\'errors\'])\">\n<div class=\'message error\'>\n	<h4>{$this->lang->words[\'err_errors\']}</h4>\n	<foreach loop=\"newtopicerrors:$displayData[\'errors\'] as $_error\">\n		<p>{$_error}</p>\n	</foreach>\n	<p>{$this->lang->words[\'pme_none_sent\']}</p>\n</div>\n</if>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'pro_recips\']}</h3>\n			<ul>\n				<li class=\'field\'>\n					<label for=\'entered_name\'>{$this->lang->words[\'to_whom\']}</label>\n					<input type=\"text\" class=\'input_text\' id=\'entered_name\' name=\"entered_name\" size=\"30\" value=\"{$displayData[\'name\']}\" tabindex=\"0\" />\n				</li>\n				<if test=\"newTopicInvite:|:intval($this->memberData[\'g_max_mass_pm\'])\">\n					<li class=\'field\'>\n						<label for=\'more_members\'>{$this->lang->words[\'other_recipients\']}</label>\n						<input type=\'text\' size=\"50\" class=\'input_text\' name=\'inviteUsers\' value=\'{$displayData[\'inviteUsers\']}\' id=\'more_members\' tabindex=\'0\' />\n						<span class=\'desc\'>{$this->lang->words[\'youmay_add_to\']} <strong>{$this->memberData[\'g_max_mass_pm\']}</strong> {$this->lang->words[\'youmay_suffix\']}</span>\n					</li>\n					<li class=\'field\'>\n						<label for=\'send_type\'>{$this->lang->words[\'send_to_as\']}</label>\n						<select name=\'sendType\' id=\'send_type\' tabindex=\'0\'>\n							<option value=\'invite\'<if test=\"formReloadInvite:|:$this->request[\'sendType\']==\'invite\'\"> selected=\'selected\'</if>>{$this->lang->words[\'send__invite\']}</option>\n							<option value=\'copy\'<if test=\"formReloadCopy:|:$this->request[\'sendType\']==\'copy\'\"> selected=\'selected\'</if>>{$this->lang->words[\'send__copy\']}</option>\n						</select>\n						<span class=\'desc\'>\n							<strong>{$this->lang->words[\'send__invite\']}</strong> {$this->lang->words[\'invite__desc\']}<br />\n							<strong>{$this->lang->words[\'send__copy\']}</strong> {$this->lang->words[\'copy__desc\']}\n						</span>\n					</li>				\n				</if>\n			</ul>\n		</fieldset>\n		<fieldset>\n			<h3 class=\'bar\'>{$this->lang->words[\'pro_message\']}</h3>\n			<ul>\n				<li class=\'field\'>\n					<label for=\'message_subject\'>{$this->lang->words[\'message_subject_send\']}</label>\n					<input type=\"text\" name=\"msg_title\" id=\'message_subject\' class=\'input_text\' size=\"40\" tabindex=\"0\" maxlength=\"40\" value=\"{$displayData[\'title\']}\" />\n				</li>\n				<li>\n					{$displayData[\'editor\']}\n				</li>\n			</ul>\n		</fieldset>\n		\n		<if test=\"newTopicUploads:|:$displayData[\'uploadData\'][\'canUpload\']\">\n		<fieldset class=\'attachments\'>\n			{parse template=\"uploadForm\" group=\"post\" params=\"$displayData[\'postKey\'], \'msg\', $displayData[\'uploadData\'][\'attach_stats\'], 0\"}\n		</fieldset>\n		</if>\n		<input type=\'hidden\' name=\'topicID\' value=\"{$displayData[\'topicID\']}\" />\n		<input type=\'hidden\' name=\"postKey\" value=\"{$displayData[\'postKey\']}\" />\n		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		<fieldset class=\'submit\'>\n			<input class=\'input_submit\' name=\"dosubmit\" type=\"submit\" value=\"{$this->lang->words[\'submit_send\']}\" tabindex=\"0\" accesskey=\"s\" />\n			<input class=\'input_submit alt\' type=\"submit\" value=\"{$this->lang->words[\'pm_pre_button\']}\" tabindex=\"0\" name=\"preview\" />\n			<input class=\'input_submit alt\' type=\"submit\" value=\"{$this->lang->words[\'pms_send_later\']}\" tabindex=\"0\" name=\"save\" />\n			{$this->lang->words[\'or\']} <a href=\'{parse url=\"app=members&amp;module=messaging\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</div>\n</div>\n</form>\n</div>\n{parse template=\"include_highlighter\" group=\"global\" params=\"\"}\n<br />', 'sendNewPersonalTopicForm', '$displayData', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('431', '0', 'skin_messaging', '<div id=\'message_compose\' class=\'post_form\'>\n	<if test=\"replyForm:|:$displayData[\'type\'] == \'reply\'\">\n		<form id=\'msgForm\' style=\'display:block\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=sendReply\" base=\"publicWithApp\"}\" method=\"post\" name=\"REPLIER\">\n	<else />\n		<form id=\'msgForm\' style=\'display:block\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=sendEdit\" base=\"publicWithApp\"}\" method=\"post\" name=\"REPLIER\">\n	</if>\n		<input type=\"hidden\" name=\"msgID\" value=\"{$displayData[\'msgID\']}\" />\n	<input type=\'hidden\' name=\'topicID\' value=\"{$displayData[\'topicID\']}\" />\n	<input type=\'hidden\' name=\"postKey\" value=\"{$displayData[\'postKey\']}\" />\n	<input type=\"hidden\" name=\"authKey\" value=\"{$this->member->form_hash}\" />\n	{$data[\'upload\']}	\n<if test=\"previewPm:|:$displayData[\'preview\']\">\n	<h2 class=\'maintitle\'>{$this->lang->words[\'pm_preview\']}</h2>\n	<div class=\'post_wrap\' id=\'post_preview\'>\n		<div class=\'row2\' style=\'padding:8px\'>\n			<div class=\'post entry-content\'>{$displayData[\'preview\']}</div>\n		</div>\n	</div>\n	<br />\n</if>\n<h2 class=\'maintitle\'>\n	<if test=\"formHeaderText:|:$displayData[\'type\'] == \'reply\'\">\n		{$this->lang->words[\'compose_reply\']}\n	<else />\n		{$this->lang->words[\'editing_message\']}\n	</if>\n</h2>\n<if test=\"formErrors:|:$displayData[\'errors\']\">\n<div class=\'message error\'>\n	<h4>{$this->lang->words[\'err_errors\']}</h4>\n	<foreach loop=\"replyerrors:$displayData[\'errors\'] as $_error\">\n		<p>{$_error}</p>\n	</foreach>\n	<p>{$this->lang->words[\'pme_none_sent\']}</p>\n</div>\n</if>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<fieldset>\n			<ul>\n				<li>\n					{$displayData[\'editor\']}\n				</li>\n			</ul>\n		</fieldset>\n		\n		<if test=\"attachmentForm:|:$displayData[\'uploadData\'][\'canUpload\']\">\n		<fieldset class=\'attachments\'>\n			{parse template=\"uploadForm\" group=\"post\" params=\"$displayData[\'postKey\'], \'msg\', $displayData[\'uploadData\'][\'attach_stats\'], $displayData[\'msgID\'], 0\"}\n		</fieldset>\n		</if>\n		\n		<fieldset class=\'submit\'>\n			<if test=\"replyOptions:|:$displayData[\'type\'] == \'reply\'\">\n				<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'submit_send\']}\" tabindex=\"0\" accesskey=\"s\" />\n				<input class=\'input_submit alt\' type=\"submit\" value=\"{$this->lang->words[\'pm_pre_button\']}\" tabindex=\"0\" name=\"previewReply\" />\n				{$this->lang->words[\'or\']} <a href=\'{parse url=\"app=members&amp;module=messaging&amp;do=showConversation&amp;topicID={$displayData[\'topicID\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n			<else />\n				<input class=\'input_submit\' type=\"submit\" value=\"{$this->lang->words[\'save_message_button\']}\" tabindex=\"0\" accesskey=\"s\" />\n				<input class=\'input_submit alt\' type=\"submit\" value=\"{$this->lang->words[\'pm_pre_button\']}\" tabindex=\"0\" name=\"previewReply\" />\n				{$this->lang->words[\'or\']} <a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$displayData[\'topicID\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel\']}\' class=\'cancel\' tabindex=\'0\'>{$this->lang->words[\'cancel\']}</a>\n			</if>\n			\n		</fieldset>\n	</div>\n</div>\n</form>\n</div>\n<br />', 'sendReplyForm', '$displayData', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('432', '0', 'skin_messaging', '<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}\n{parse js_module=\"topic\"}\n<script type=\"text/javascript\">\n//<![CDATA[\n	ipb.topic.inSection = \'messenger\';\n//]]>\n</script>\n<div id=\'conversation\'>\n<div class=\'topic_controls clearfix\'>\n	{$topic[\'_pages\']}\n	<ul class=\'topic_buttons\'>\n		<li><a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'go_to_compose\']}\'>{$this->lang->words[\'compose_new\']}</a></li>\n 		<li class=\'important\'><a id=\'pm_delete_t_{$topic[\'mt_id\']}\' href=\'{parse url=\"module=messaging&amp;section=view&amp;do=deleteConversation&amp;topicID={$topic[\'mt_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\'>{$this->lang->words[\'option__delete\']}</a></li>\n	</ul>\n	<script type=\'text/javascript\'>\n		$(\'pm_delete_t_{$topic[\'mt_id\']}\').observe(\'click\', ipb.messenger.deletePM.bindAsEventListener( this, {$topic[\'mt_id\']} ) );\n	</script>\n</div>\n<h2 class=\'maintitle\'>{$topic[\'mt_title\']}</h2>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<foreach loop=\"replies:$replies as $msg_id => $msg\">\n			<a id=\'msg{$msg[\'msg_id\']}\'></a>\n			<div class=\'post_block first hentry\' id=\'post_id_{$msg[\'msg_id\']}\'>\n				<div class=\'post_wrap\'>\n					<if test=\"hasAuthorId:|:$members[ $msg[\'msg_author_id\'] ][\'member_id\']\">\n						<h3 class=\'row2\'>\n					<else />\n						<h3 class=\'guest row2\'>\n					</if>\n							<if test=\"authorOnline:|:$members[ $msg[\'msg_author_id\'] ][\'member_id\']\">\n								<span class=\"author vcard\">{parse template=\"userHoverCard\" group=\"global\" params=\"$members[ $msg[\'msg_author_id\'] ]\"}</span>\n							<else />\n								{$members[ $msg[\'msg_author_id\'] ][\'members_display_name\']}\n							</if>\n							<if test=\"authorIpAddress:|:$msg[\'_ip_address\'] != \'\'\">\n								<span class=\'ip right ipsType_small\'>({$this->lang->words[\'ip\']}:\n								<if test=\"authorPrivateIp:|:$members[ $msg[\'msg_author_id\'] ][\'g_access_cp\']\">\n									<em>{$this->lang->words[\'ip_private\']}</em>\n								<else />\n									<if test=\"accessModCP:|:$this->memberData[\'g_is_supmod\']\"><a href=\"{parse url=\"app=core&amp;module=modcp&amp;fromapp=members&amp;tab=iplookup&amp;ip={$msg[\'_ip_address\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'find_info_about_ip\']}\'>{$msg[\'_ip_address\']}</a><else />{$msg[\'_ip_address\']}</if>\n								</if>\n								)</span>\n							</if>\n						</h3>\n					<div class=\'author_info\'>\n						{parse template=\"userInfoPane\" group=\"global\" params=\"$members[ $msg[\'msg_author_id\'] ], $msg_id, array()\"}\n					</div>\n					<div class=\'post_body\'>\n						<p class=\'posted_info\'>{$this->lang->words[\'pc_sent\']} {parse date=\"$msg[\'msg_date\']\" format=\"long\"}</p>\n						<div class=\'post entry-content\'>\n							{$msg[\'msg_post\']}\n							{$msg[\'attachmentHtml\']}\n						</div>\n						<if test=\"viewSigs:|:$this->memberData[\'view_sigs\'] AND $members[ $msg[\'msg_author_id\'] ][\'signature\']\">\n							{parse template=\"signature_separator\" group=\"global\" params=\"$members[ $msg[\'msg_author_id\'] ][\'signature\'], $msg[\'msg_author_id\'], IPSMember::isIgnorable( $members[ $msg[\'msg_author_id\'] ][\'member_group_id\'], $members[ $msg[\'msg_author_id\'] ][\'mgroup_others\'] )\"}\n						</if>\n						<ul class=\'post_controls clearfix clear\'>\n							<if test=\"quickReply:|:$topic[\'_canReply\'] AND empty( $topic[\'_everyoneElseHasLeft\'] )\">\n								<li>\n									<a class=\'ipsButton_secondary\' href=\"{parse url=\"module=messaging&amp;section=send&amp;do=replyForm&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{$this->lang->words[\'pc_reply\']}</a>\n								</li>\n							</if>\n							<if test=\"reportPm:|:$topic[\'_canReport\'] and $this->memberData[\'member_id\']\">\n								<li class=\'report\'>\n									<a href=\'{parse url=\"app=core&amp;module=reports&amp;rcom=messages&amp;topicID={$this->request[\'topicID\']}&amp;st={$this->request[\'st\']}&amp;msg={$msg[\'msg_id\']}\" base=\"public\"}\'>{$this->lang->words[\'pc_report\']}</a>\n								</li>\n							</if>\n							<if test=\"canEdit:|:$msg[\'_canEdit\'] === TRUE\">\n								<li class=\'post_edit\' id=\'edit_post_{$msg[\'msg_id\']}\'>\n									<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=editMessage&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'edit_this_post\']}\'>{$this->lang->words[\'pc_edit\']}</a>\n								</li>\n							</if>\n							<if test=\"canDelete:|:$msg[\'_canDelete\'] === TRUE && $msg[\'msg_is_first_post\'] != 1\">\n								<li class=\'post_del\' id=\'del_post_{$msg[\'msg_id\']}\'>\n									<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=deleteReply&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'delete_this_post\']}\' class=\'delete_post\'>{$this->lang->words[\'pc_delete\']}</a>\n								</li>\n							</if>\n						</ul>\n					</div>\n				</div>\n			</div>\n		</foreach>\n	</div>\n</div>\n<if test=\"allAlone:|: ! empty( $topic[\'_everyoneElseHasLeft\'] )\">\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container ipsPad\'>\n		<h1 class=\'ipsType_subtitle\'>{$this->lang->words[\'msg_all_alone_title\']}</h1>\n		<p>{$this->lang->words[\'msg_all_alone_desc\']}</p>\n	</div>\n</div>\n<else />\n	<if test=\"canReplyEditor:|:$topic[\'_canReply\']\">\n	<br />\n	<div class=\'ipsBox\'>\n		<div class=\'ipsBox_container ipsPad\'>\n			<h1 class=\'ipsType_subtitle\'>{$this->lang->words[\'pc_fast_reply\']}</h1>\n			<br />\n			<a href=\"{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" title=\'{$this->lang->words[\'your_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$this->memberData[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$this->memberData[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n			<div class=\'ipsBox_withphoto clearfix\'>\n				<form action=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=sendReply&amp;topicID={$topic[\'mt_id\']}\" base=\"public\"}\' method=\'post\'>\n					<input type=\"hidden\" name=\"authKey\" value=\"{$this->member->form_hash}\" />\n					<input type=\"hidden\" name=\"fast_reply_used\" value=\"1\" />\n					<input type=\"hidden\" name=\"enableemo\" value=\"yes\" />\n					<input type=\"hidden\" name=\"enablesig\" value=\"yes\" />\n					{parse editor=\"msgContent\" options=\"array( \'type\' => \'full\', \'minimize\' => 1 )\"}\n					<br />\n					<fieldset class=\'right\'>\n						<input type=\'submit\' name=\"submit\" class=\'input_submit\' value=\'{$this->lang->words[\'pc_post_button\']}\' accesskey=\'s\' />&nbsp;&nbsp;<input type=\'submit\' name=\"previewReply\" class=\'input_submit alt\' value=\'{$this->lang->words[\'pc_use_full_reply\']}\' />\n					</fieldset>\n				</form>\n			</div>\n		</div>\n	</div>\n	</if>\n</if>\n<div class=\'topic_controls clear\'>\n	{$topic[\'_pages\']}\n	<ul class=\'topic_buttons\'>\n 		<li class=\'non_button\'><a id=\'email_convo_{$this->request[\'topicID\']}\' data-tooltip=\'{parse expression=\"sprintf( $this->lang->words[\'msg_email_convo_text\'], $this->memberData[\'email\'])\"}\' href=\'#\' class=\'email_convo\'>{$this->lang->words[\'msg_email_convo\']}</a></li>\n	</ul>\n</div>\n</div>\n{parse template=\"include_highlighter\" group=\"global\" params=\"\"}', 'showConversation', '$topic, $replies, $members, $jump=\"\"', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('433', '0', 'skin_messaging', '<php>\nforeach( $members as $id => $member )\n{\n	$mems[] = $member[\'members_display_name\'];\n}\n$memberNames = implode( $mems, \', \' );\n</php>\n<html>\n	<head>\n		<title>{$topic[\'mt_title\']}</title>\n		<style type=\"text/css\">\n			* {\n				font-family: Georgia, \"Times New Roman\", serif;\n			}\n			\n			html #content {\n				font-size: 10pt;\n			}\n			\n			ol,ul { list-style:none; }\n			\n			ul.pagination {\n				margin-left: -35px;\n			}\n			\n			ul.pagination a,\n			ul.pagination li.active, \n			ul.pagination li.pagejump,\n			ul.pagination li.total {\n				text-decoration: none;\n				padding: 1px 4px 1px 0px;\n				display: block;\n			}\n			\n			ul.pagination li {\n				font-size: 0.9em;	\n				margin: 0 2px 0 2px;\n				float: left;\n			}\n			\n				ul.pagination li.total,\n				ul.pagination li.active {\n					background: none;\n					border: 0;\n					margin-left: 0px;\n				}\n			\n				ul.pagination li.active {\n					color: #000;\n					font-size: 1em;\n					font-weight: bold;\n				}\n				\n				ul.pagination li.pagejump {\n					display: none;\n				}\n			\n			#admin_bar,\n			#header,\n			#footer_utilities,\n			#utility_links,\n			.post_mod,\n			.author_info,\n			.rep_bar,\n			.post_controls,\n			.top,\n			#content_jump,\n			.topic_buttons,\n			.topic_options,\n			h1,\n			.post_id,\n			h3 img,\n			.ip,\n			hr,\n			.moderation_bar,\n			.topic_jump,\n			.topic_share,\n			#fast_reply,\n			#reputation_filter,\n			.statistics,\n			.rating,\n			.message,\n			#debug_wrapper,\n			fieldset,\n			.signature {\n				display: none;\n			}\n			\n			#breadcrumb {\n				display: block !important;\n			}\n				#breadcrumb li {\n					float: left;\n				}\n			\n			.topic, .hfeed {\n				clear: both;\n			}\n			\n			.post_block {\n				margin-bottom: 10pt;\n				border-top: 2pt solid gray;\n				line-height: 60%; \n				padding-top: 10px;\n			}\n			\n			.posted_info {\n				color: gray !important;\n				font-size: 8pt !important;\n				text-decoration: none !important;\n				padding-bottom: 3px;\n				float: right;\n				margin-top: -30px;\n			}\n			\n			span.main_topic_title {\n				font-size: 1.7em;\n				padding-left: 2px;\n			}\n			\n			.post_block h3 {\n				display: inline !important;\n				margin: 0px 0px 10px !important;\n				padding: 0px !important;\n				float: left;\n			}\n			\n			.post_block h3 a {\n				color: black !important;\n				text-decoration: none !important;\n				font-style: normal !important;\n			}\n			\n				.post_block .post_body a:after {\n				    content: \" (\" attr(href) \") \";\n				}\n			\n			.post_body {\n				line-height: 100%;\n				margin-top: 15px;\n				clear: both;\n				display: block;\n				padding: 10px;\n				border-top: 1pt solid #d3d3d3;\n			}\n			\n			h1, h2, h3 {\n				font-weight: bold;\n			}\n			\n			#copyright {\n				text-align: center;\n				color: gray;\n				font-size: 9pt;\n			}\n			\n			a img {\n				border: 0px;\n			}\n			\n			abbr.published {\n				text-decoration: none !important;\n				border: 0px;\n			}\n		</style>\n	</head>\n	<body>\n		<h2 class=\'maintitle\'>{$topic[\'mt_title\']}</h2>\n		<em>\n			{$this->lang->words[\'email_participants\']} {$memberNames}\n		</em>\n		<br />\n		<br />\n		<foreach loop=\"replies:$replies as $msg_id => $msg\">\n			<div class=\'post_block first hentry\'>\n				<div class=\'post_wrap\'>\n					<h3>\n						{$members[ $msg[\'msg_author_id\'] ][\'members_display_name\']}\n					</h3>\n					<div class=\'post_body\'>\n						<p class=\'posted_info\'>{$this->lang->words[\'pc_sent\']} {parse date=\"$msg[\'msg_date\']\" format=\"long\"}</p>\n						<div class=\'post entry-content\'>\n							{$msg[\'msg_post\']}\n						</div>\n					</div>\n					<ul class=\'post_controls\'>\n						<li>&nbsp;</li>\n					</ul>\n				</div>		\n			</div>\n		</foreach>\n	</body>\n</html>', 'showConversationForArchive', '$topic, $replies, $members', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('434', '0', 'skin_messaging', '<script type=\'text/javascript\'>\n	ipb.messenger.curFolder = \'{$currentFolderID}\';\n</script>\n<div class=\'topic_controls\'>\n{$pages}\n<if test=\"folderNotDrafts:|:$currentFolderID != \'drafts\'\">\n	{parse variable=\"folder_all\" default=\"\"}\n	{parse variable=\"folder_all\" oncondition=\"$this->request[\'folderFilter\'] == \'all\' OR ! $this->request[\'folderFilter\']\" value=\"selected=\'selected\'\"}\n	{parse variable=\"folder_in\" default=\"\"}\n	{parse variable=\"folder_in\" oncondition=\"$this->request[\'folderFilter\'] == \'in\'\" value=\"selected=\'selected\'\"}\n	{parse variable=\"folder_sent\" default=\"\"}\n	{parse variable=\"folder_sent\" oncondition=\"$this->request[\'folderFilter\'] == \'sent\'\" value=\"selected=\'selected\'\"}\n</if>\n<ul class=\'topic_buttons\'>\n	<li><a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'go_to_compose\']}\'>{$this->lang->words[\'compose_new\']}</a></li>\n</ul>\n</div>\n<div id=\'message_list\'>\n	<form action=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=multiFile&amp;cFolderID={$currentFolderID}\" base=\"public\"}\" id=\'msgFolderForm\' method=\"post\">\n		<input type=\"hidden\" name=\"sort\" value=\"{$this->request[\'sort\']}\" />\n		<input type=\"hidden\" name=\"st\" value=\"{$this->request[\'st\']}\" />\n		<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n		<div class=\'maintitle\'>\n			<span class=\'right\'>\n				<input type=\'checkbox\' class=\'input_check\' id=\'msg_checkall\' value=\'1\' /> &nbsp;\n			</span>\n			{$dirname}\n		</div>\n		<div class=\'ipsBox\'>\n			<div class=\'ipsBox_container\'>\n				<table class=\'ipb_table\' id=\'message_table\'>\n					<tr class=\'header hide\'>\n						<th scope=\'col\' class=\'col_m_status\'>&nbsp;</th>\n						<th scope=\'col\' class=\'col_m_subject\'>{$this->lang->words[\'col_topic\']}</th>\n						<th scope=\'col\' class=\'col_m_replies short\'>{$this->lang->words[\'col_replies\']}</th>\n						<th scope=\'col\' class=\'col_m_date\'>{$this->lang->words[\'col_last_message\']}</th>\n						<th scope=\'col\' class=\'col_mod short\'>&nbsp;</th>\n					</tr>\n					<if test=\"folderMessages:|:count( $messages )\">\n						<foreach loop=\"folderMessages:$messages as $id => $msg\">\n							<tr id=\'{$msg[\'mt_id\']}\' class=\'<if test=\"$msg[\'map_has_unread\']\">unread</if>\'>\n								<td class=\'col_m_photo altrow short\'>\n									<if test=\"hasStarterPhoto:|:$msg[\'_starterMemberData\'][\'member_id\']\">\n										<a href=\'{parse url=\"showuser={$msg[\'_starterMemberData\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$msg[\'_starterMemberData\'][\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink\'>\n											<img src=\'{$msg[\'_starterMemberData\'][\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n										</a>\n									<else />\n										{IPSMember::buildProfilePhoto(0,\'mini\')}\n									</if>\n								</td>\n								<td class=\'col_m_subject\'>\n									<if test=\"folderNotifications:|:$msg[\'mt_is_deleted\'] OR $msg[\'map_user_banned\']\">\n										<span class=\'ipsBadge ipsBadge_red\'>\n											{$this->lang->words[\'msg_deleted\']}\n										</span>\n									</if>\n									<h4>\n										<if test=\"$msg[\'map_has_unread\']\">\n											<a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=findMessage&amp;topicID={$msg[\'mt_id\']}&amp;msgID=__firstUnread__\" base=\"public\"}\' title=\'{$this->lang->words[\'first_unread_reply\']}\'>{parse replacement=\"f_newpost\"}</a>\n											<strong>\n										</if>\n										<a href=\'<if test=\"folderDrafts:|:$currentFolderID == \'drafts\'\">{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}<else />{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}</if>\' title=\'{$this->lang->words[\'msg_view_conversation\']}\'>\n										{$msg[\'mt_title\']}\n										</a>\n										<if test=\"$msg[\'map_has_unread\']\"></strong></if>\n									</h4>\n									<if test=\"folderNotifications:|:$msg[\'map_ignore_notification\']\">\n										<span class=\'ipsBadge ipsBadge_lightgrey\'>\n											{$this->lang->words[\'msg_no_notify\']}\n										</span>\n									</if>\n									<br />\n									<span class=\'desc lighter blend_links\'>\n										{$this->lang->words[\'msg_startedby\']}\n										<if test=\"folderStarter:|:$msg[\'_starterMemberData\'][\'members_display_name\']\">\n											{parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_starterMemberData\']\"},\n										<else />\n											<span class=\'desc\'>{$this->lang->words[\'deleted_user\']},</span>\n										</if>\n										<span class=\'desc lighter blend_links\'>\n											{$this->lang->words[\'msg_sentto\']}\n											<if test=\"folderToMember:|:$msg[\'_toMemberData\'][\'members_display_name\']\">\n												{parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_toMemberData\']\"}\n											<else />\n												<span class=\'desc\'>{$this->lang->words[\'deleted_user\']}</span>\n											</if>\n											<if test=\"folderMultipleUsers:|:$msg[\'_otherInviteeCount\'] > 0\">\n												<if test=\"folderFixPlural:|:$msg[\'_otherInviteeCount\'] > 1\">\n													<span title=\'{parse expression=\"implode( \', \', $msg[\'_invitedMemberNames\'] )\"}\'>({$this->lang->words[\'pc_and\']} {$msg[\'_otherInviteeCount\']} {$this->lang->words[\'pc_others\']})</p>\n												<else />\n													<span title=\'{parse expression=\"implode( \', \', $msg[\'_invitedMemberNames\'] )\"}\'>({$this->lang->words[\'pc_and\']} {$msg[\'_otherInviteeCount\']} {$this->lang->words[\'pc_other\']})</p>\n												</if>\n											</if>\n										</span>\n										<if test=\"folderNew:|:in_array( $currentFolderID, array( \'new\' ) )\">\n											<p class=\'ipsType_small desc\'>{$this->lang->words[\'folder_prefix\']} {$msg[\'_folderName\']}</p>\n										</if>\n									</span>	\n									<if test=\"folderPages:|:is_array( $msg[\'pages\'] ) AND count( $msg[\'pages\'] )\">\n										<ul class=\'mini_pagination\'>\n										<foreach loop=\"messagePages:$msg[\'pages\'] as $page\">\n												<if test=\"folderLastPage:|:$page[\'last\']\">\n													<li><a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}&amp;st={$page[\'st\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'goto_page\']} {$page[\'page\']}\'>{$page[\'page\']} {$this->lang->words[\'_rarr\']}</a></li>\n												<else />\n													<li><a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}&amp;st={$page[\'st\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'goto_page\']} {$page[\'page\']}\'>{$page[\'page\']}</a></li>\n												</if>\n										</foreach>\n										</ul>\n									</if>\n								</td>\n								<td class=\'col_m_replies desc blend_links\'>\n									<ul>\n										<li><if test=\"folderBannedIndicator:|:$msg[\'map_user_banned\']\">-<else />{parse expression=\"sprintf( $this->lang->words[\'msg_xreplies\'], intval( $msg[\'mt_replies\'] ) )\"}</if></li>\n									</ul>\n								</td>\n								<td class=\'col_f_post\'>\n									<if test=\"hasPosterPhoto:|:$msg[\'_lastMsgAuthor\'][\'member_id\']\">\n										<a href=\'{parse url=\"showuser={$msg[\'_lastMsgAuthor\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$msg[\'_lastMsgAuthor\'][\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n											<img src=\'{$msg[\'_lastMsgAuthor\'][\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n										</a>\n									<else />\n										<span class=\'left\'>{IPSMember::buildProfilePhoto(0,\'mini\')}</span>\n									</if>\n									<ul class=\'last_post ipsType_small\'>\n										<if test=\"folderBannedUser:|:$msg[\'map_user_banned\']\">\n											<li><em>{$this->lang->words[\'info_not_available\']}</em></li>\n										<else />\n											<li>{$this->lang->words[\'pc_by\']} <if test=\"folderToMember:|:$msg[\'_lastMsgAuthor\'][\'members_display_name\']\">{parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_lastMsgAuthor\']\"}<else /><span class=\'desc\'>{$this->lang->words[\'deleted_user\']}</span></if></li>\n										</if>\n										<li class=\'desc\'>\n											<a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=findMessage&amp;topicID={$msg[\'mt_id\']}&amp;msgID={$msg[\'mt_last_msg_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{parse date=\"$msg[\'mt_last_post_time\']\" format=\"DATE\"}</a>\n										</li>\n									</ul>\n								</td>\n								<td class=\'col_m_mod short\'>\n									<input type=\'checkbox\' class=\'input_check msg_check\' name=\'msgid[{$msg[\'mt_id\']}]\' id=\'msg_check_{$msg[\'mt_id\']}\' />\n								</td>\n							</tr>\n						</foreach>\n					<else />\n						<tr>\n							<td colspan=\'8\' class=\'no_messages row1\'>\n								{$this->lang->words[\'folder_no_messages_row\']}\n							</td>\n						</tr>\n					</if>\n				</table>\n			</div>\n		</div>\n		<div id=\'messenger_mod\' class=\'moderation_bar rounded with_action right\'>\n			<select id=\'pm_multifile\' name=\'method\' class=\'input_select\'>\n				<optgroup label=\"{$this->lang->words[\'with_selected_opt\']}\">\n					<option value=\"delete\">{$this->lang->words[\'option__delete\']}</option>\n					<if test=\"folderMultiOptions:|:$currentFolderID != \'drafts\'\">\n						<option value=\"markread\">{$this->lang->words[\'option__markread\']}</option>\n						<option value=\"markunread\">{$this->lang->words[\'option__markunread\']}</option>\n						<option value=\"notifyon\">{$this->lang->words[\'option__turnon\']}</option>\n						<option value=\"notifyoff\">{$this->lang->words[\'option__turnoff\']}</option>\n					</if>\n				</optgroup>\n				<if test=\"folderJumpHtml:|:$jumpFolderHTML AND $currentFolderID != \'drafts\' AND $currentFolderID != \'new\'\">\n					<optgroup label=\"{$this->lang->words[\'move_to_opt\']}\">\n						{$jumpFolderHTML}\n					</optgroup>\n				</if>\n			</select>\n			<input type=\"submit\" class=\'input_submit alt\' id=\'folder_moderation\' value=\"{$this->lang->words[\'jmp_go\']}\" />\n		</div>\n	</form>\n	<div id=\'messenger_filter\' class=\'left ipsPad_half\'>\n		<form method=\'post\' action=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showFolder&amp;folderID={$currentFolderID}\" base=\"public\"}\'>\n			<label for=\'conversation_filter\' class=\'desc\'>{$this->lang->words[\'filter__show\']} </label>\n			<select id=\'conversation_filter\' name=\'folderFilter\' class=\'input_select\'>\n				<option value=\'\' {parse variable=\"folder_all\"}>{$this->lang->words[\'filter__all\']}</option>\n				<option value=\'in\' {parse variable=\"folder_in\"}>{$this->lang->words[\'filter__others\']}</option>\n				<option value=\'sent\' {parse variable=\"folder_sent\"}>{$this->lang->words[\'filters__i\']}</option>\n			</select>\n			<input type=\'submit\' class=\'input_submit alt\' value=\'{$this->lang->words[\'filters__update\']}\' />\n		</form>\n	</div>\n</div>\n<br />\n<div class=\'topic_controls clear clearfix\'>\n{$pages}\n</div>', 'showFolder', '$messages, $dirname, $pages, $currentFolderID, $jumpFolderHTML', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('435', '0', 'skin_messaging', '<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.messenger.curFolder = \'in\';\n//]]>\n</script>\n<if test=\"searchError:|:$error\">\n	<p class=\'message error\'>\n		{$error}\n	</p>\n	<br />\n</if>\n<if test=\"$pages\">\n	<div class=\'topic_controls\'>\n	{$pages}\n	</div>\n	<br />\n</if>\n<h2 class=\'maintitle clear\'>{$this->lang->words[\'your_search_results\']}</h2>\n<div id=\'message_list\'>\n	<div class=\'ipsBox\'>\n		<div class=\'ipsBox_container\'>\n			<table class=\'ipb_table\' id=\'message_table\'>\n				<tr class=\'header hide\'>\n					<th scope=\'col\' class=\'col_m_photo\'>&nbsp;</th>\n					<th scope=\'col\' class=\'col_m_subject\'>{$this->lang->words[\'col_subject\']}</th>\n					<th scope=\'col\' class=\'col_m_replies short\'>{$this->lang->words[\'col_replies\']}</th>\n					<th scope=\'col\' class=\'col_m_date\'>{$this->lang->words[\'col_last_message\']}</th>\n				</tr>\n		\n				<if test=\"searchMessages:|:count( $messages )\">\n					<foreach loop=\"messages:$messages as $id => $msg\">\n						<tr id=\'{$msg[\'mt_id\']}\' class=\'<if test=\"$msg[\'map_has_unread\']\">unread</if>\'>\n							<td class=\'col_m_photo altrow short\'>\n								<a href=\'{parse url=\"showuser={$msg[\'_starterMemberData\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$msg[\'_starterMemberData\'][\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink\'>\n									<img src=\'{$msg[\'_starterMemberData\'][\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n								</a>\n							</td>\n							<td>\n								<if test=\"folderNotifications:|:$msg[\'mt_is_deleted\'] OR $msg[\'map_user_banned\']\">\n									<span class=\'ipsBadge ipsBadge_red\'>\n										{$this->lang->words[\'msg_deleted\']}\n									</span>\n								</if>\n								<h4><a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}\">{$msg[\'mt_title\']}</a></h4><br />\n								<span class=\'desc lighter blend_links\'>\n									{$this->lang->words[\'msg_startedby\']}\n									<if test=\"folderStarter:|:$msg[\'_starterMemberData\'][\'members_display_name\']\">\n										{parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_starterMemberData\']\"}\n									<else />\n										<span class=\'desc\'>{$this->lang->words[\'deleted_user\']}</span>\n									</if>\n									<span class=\'desc lighter blend_links\'>\n										, {$this->lang->words[\'msg_sentto\']}\n										<if test=\"folderToMember:|:$msg[\'_toMemberData\'][\'members_display_name\']\">\n											{parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_toMemberData\']\"}\n										<else />\n											<span class=\'desc\'>{$this->lang->words[\'deleted_user\']}</span>\n										</if>\n										<if test=\"folderMultipleUsers:|:$msg[\'_otherInviteeCount\'] > 0\">\n											<if test=\"folderFixPlural:|:$msg[\'_otherInviteeCount\'] > 1\">\n												<span title=\'{parse expression=\"implode( \', \', $msg[\'_invitedMemberNames\'] )\"}\'>({$this->lang->words[\'pc_and\']} {$msg[\'_otherInviteeCount\']} {$this->lang->words[\'pc_others\']})</p>\n											<else />\n												<span title=\'{parse expression=\"implode( \', \', $msg[\'_invitedMemberNames\'] )\"}\'>({$this->lang->words[\'pc_and\']} {$msg[\'_otherInviteeCount\']} {$this->lang->words[\'pc_other\']})</p>\n											</if>\n										</if>\n									</span>\n									<if test=\"folderNew:|:in_array( $currentFolderID, array( \'new\' ) )\">\n										<p class=\'ipsType_small desc\'>{$this->lang->words[\'folder_prefix\']} {$msg[\'_folderName\']}</p>\n									</if>\n								</span>\n								<p class=\'ipsType_small desc\'>{$this->lang->words[\'label_pc\']} {$msg[\'_folderName\']}</p>\n							</td>\n							<td class=\'col_m_replies desc blend_links\'>\n								<ul>\n									<li><if test=\"folderBannedIndicator:|:$msg[\'map_user_banned\']\">-<else />{parse expression=\"sprintf( $this->lang->words[\'msg_xreplies\'], intval( $msg[\'mt_replies\'] ) )\"}</if></li>\n								</ul>\n							</td>\n							<td class=\'col_f_post\'>\n								<a href=\'{parse url=\"showuser={$msg[\'_lastMsgAuthor\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$msg[\'_lastMsgAuthor\'][\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink left\'>\n									<img src=\'{$msg[\'_lastMsgAuthor\'][\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n								</a>\n								<ul class=\'last_post ipsType_small\'>\n									<if test=\"folderBannedUser:|:$msg[\'map_user_banned\']\">\n										<li><em>{$this->lang->words[\'info_not_available\']}</em></li>\n									<else />\n										<li>{$this->lang->words[\'pc_by\']} {parse template=\"userHoverCard\" group=\"global\" params=\"$msg[\'_lastMsgAuthor\']\"}</li>\n									</if>\n									<li class=\'desc blend_links\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=findMessage&amp;topicID={$msg[\'mt_id\']}&amp;msgID={$msg[\'mt_last_msg_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'goto_last_post\']}\'>{parse date=\"$msg[\'mt_last_post_time\']\" format=\"DATE\"}</a></li>\n								</ul>\n							</td>\n						</tr>\n					</foreach>\n				<else />\n					<tr>\n						<td colspan=\'5\' class=\'no_messages row1\'>\n							{$this->lang->words[\'no_messages_row\']}\n						</td>\n					</tr>\n				</if>\n			</table>\n		</div>\n	</div>\n</div>', 'showSearchResults', '$messages, $pages, $error', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('436', '0', 'skin_mlist', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/calendar_date_select/calendar_date_select.js\'></script>\n{parse js_module=\"memberlist\"}\n<!-- SEARCH FORM -->\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'mlist_header\']}</h1>\n<div class=\'topic_controls\'>\n	{$pages}	\n	<ul class=\'topic_buttons\'>\n		<li><a href=\'#filters\' title=\'{$this->lang->words[\'mlist_adv_filt\']}\' id=\'use_filters\'>{$this->lang->words[\'mlist_adv_filt\']}</a></li>\n	</ul>\n</div>\n<div id=\'member_filters\' class=\'general_box alt clear\'>\n	<form action=\"{parse url=\"app=members&amp;module=list\" base=\"public\" seotitle=\"false\"}\" method=\"post\">\n		<h3 class=\'bar\'>{$this->lang->words[\'mlist_adv_filt_opt\']}</h3>\n	\n		<ul id=\'filters_1\'>\n			<li class=\'field\'>\n				<label for=\'member_name\'>{$this->lang->words[\'s_name\']}</label>\n				<select name=\"name_box\" class=\'input_select\'>\n					<option value=\"begins\"<if test=\"namebox_begins:|:$this->request[\'name_box\'] == \'begins\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_begins\']}</option>\n					<option value=\"contains\"<if test=\"namebox_contains:|:$this->request[\'name_box\'] == \'contains\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_contains\']}</option>\n				</select>&nbsp;&nbsp;\n				<input type=\"text\" size=\"15\" name=\"name\" id=\'member_name\' class=\'input_text\' value=\"{parse expression=\"urldecode($this->request[\'name\'])\"}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'photo_only\'>{$this->lang->words[\'photo_only\']}</label>\n				<input class=\'input_check\' id=\'photo_only\' type=\"checkbox\" value=\"1\" name=\"photoonly\" <if test=\"photoonly:|:$defaults[\'photoonly\']\">checked=\'checked\'</if> />\n			</li>\n			<if test=\"canFilterRate:|:$this->settings[\'pp_allow_member_rate\']\">\n				<li class=\'field\'>\n					<label for=\'rating\'>{$this->lang->words[\'m_rating_morethan\']}</label>\n					<select name=\'pp_rating_real\' id=\'rating\'>\n						<option value=\'0\'<if test=\"rating0:|:! $this->request[\'pp_rating_real\']\"> selected=\'selected\'</if>>0</option>\n						<option value=\'1\'<if test=\"rating1:|:$this->request[\'pp_rating_real\'] == 1\"> selected=\'selected\'</if>>1</option>\n						<option value=\'2\'<if test=\"rating2:|:$this->request[\'pp_rating_real\'] == 2\"> selected=\'selected\'</if>>2</option>\n						<option value=\'3\'<if test=\"rating3:|:$this->request[\'pp_rating_real\'] == 3\"> selected=\'selected\'</if>>3</option>\n						<option value=\'4\'<if test=\"rating4:|:$this->request[\'pp_rating_real\'] == 4\"> selected=\'selected\'</if>>4</option>\n					</select>\n					{$this->lang->words[\'m_stars\']}\n				</li>\n			</if>\n			<if test=\"hascfields:|:count( $custom_fields->out_fields )\">\n				<foreach loop=\"customfields:$custom_fields->out_fields as $id => $field\">\n					<li class=\'field custom\'>\n						<label for=\'field_{$id}\'>{$custom_fields->field_names[$id]}</label>\n						{$field}\n					</li>\n				</foreach>\n			</if>			\n		</ul>\n		<ul id=\'filters_2\'>\n			<li class=\'field\'>\n				<label for=\'signature\'>{$this->lang->words[\'s_signature\']}</label>\n				<input type=\"text\" class=\'input_text\' size=\"28\" id=\'signature\' name=\"signature\" value=\"{parse expression=\"urldecode($this->request[\'signature\'])\"}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'posts\'>{$this->lang->words[\'s_posts\']}</label>\n				<select class=\"dropdown\" name=\"posts_ltmt\">\n					<option value=\"lt\"<if test=\"posts_ltmt_lt:|:$this->request[\'posts_ltmt\'] == \'lt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_lessthan\']}</option>\n					<option value=\"mt\"<if test=\"posts_ltmt_mt:|:$this->request[\'posts_ltmt\'] == \'mt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_morethan\']}</option>\n				</select>\n				&nbsp;<input type=\"text\" class=\'input_text\' id=\'posts\' size=\"15\" name=\"posts\" value=\"{$this->request[\'posts\']}\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'joined\'>{$this->lang->words[\'s_joined\']}</label>\n				<select class=\"dropdown\" name=\"joined_ltmt\">\n					<option value=\"lt\"<if test=\"joined_ltmt_lt:|:$this->request[\'joined_ltmt\'] == \'lt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_before\']}</option>\n					<option value=\"mt\"<if test=\"joined_ltmt_mt:|:$this->request[\'joined_ltmt\'] == \'mt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_after\']}</option>\n				</select>\n				&nbsp;<input type=\"text\" class=\'input_text\' id=\'joined\' size=\"10\" name=\"joined\" value=\"{$this->request[\'joined\']}\" /> <img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'{$this->lang->words[\'generic_date\']}\' id=\'joined_date_icon\' class=\'clickable\' /> \n				<span class=\"desc\">{$this->lang->words[\'s_dateformat\']}</span>\n			</li>\n			<li class=\'field\'>\n				<label for=\'last_post\'>{$this->lang->words[\'s_lastpost\']}</label>\n				<select class=\"dropdown\" name=\"lastpost_ltmt\">\n					<option value=\"lt\"<if test=\"lastpost_ltmt_lt:|:$this->request[\'lastpost_ltmt\'] == \'lt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_before\']}</option>\n					<option value=\"mt\"<if test=\"lastpost_ltmt_mt:|:$this->request[\'lastpost_ltmt\'] == \'mt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_after\']}</option>\n				</select>\n				&nbsp;<input type=\"text\" class=\'input_text\' id=\'last_post\' size=\"10\" name=\"lastpost\" value=\"{$this->request[\'lastpost\']}\" /> <img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'{$this->lang->words[\'generic_date\']}\' id=\'last_post_date_icon\' class=\'clickable\' /> \n				<span class=\"desc\">{$this->lang->words[\'s_dateformat\']}</span>\n			</li>\n			<li class=\'field\'>\n				<label for=\'last_visit\'>{$this->lang->words[\'s_lastvisit\']}</label>\n				<select class=\"dropdown\" name=\"lastvisit_ltmt\">\n					<option value=\"lt\"<if test=\"lastvisit_ltmt_lt:|:$this->request[\'lastvisit_ltmt\'] == \'lt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_before\']}</option>\n					<option value=\"mt\"<if test=\"lastvisit_ltmt_mt:|:$this->request[\'lastvisit_ltmt\'] == \'mt\'\"> selected=\'selected\'</if>>{$this->lang->words[\'s_after\']}</option>\n				</select>\n				&nbsp;<input type=\"text\" class=\'input_text\' id=\'last_visit\' size=\"10\" name=\"lastvisit\" value=\"{$this->request[\'lastvisit\']}\" /> <img src=\'{$this->settings[\'img_url\']}/date.png\' alt=\'{$this->lang->words[\'generic_date\']}\' id=\'last_visit_date_icon\' class=\'clickable\' />\n				<span class=\"desc\">{$this->lang->words[\'s_dateformat\']}</span>\n			</li>			\n		</ul>\n		<fieldset class=\'other_filters row2 altrow\'>\n			<select name=\'filter\' class=\'input_select\'>\n				<foreach loop=\"filter:$dropdowns[\'filter\'] as $k => $v\">\n					<option value=\'{$k}\'<if test=\"filterdefault:|:$k == $defaults[\'filter\']\"> selected=\'selected\'</if>>{$v}</option>\n				</foreach>\n			</select>\n			{$this->lang->words[\'sorting_text_by\']}\n			<select name=\'sort_key\' class=\'input_select\'>\n				<foreach loop=\"sort_key:$dropdowns[\'sort_key\'] as $k => $v\">\n					<option value=\'{$k}\'<if test=\"sortdefault:|:$k == $defaults[\'sort_key\']\"> selected=\'selected\'</if>>{$this->lang->words[ $v ]}</option>\n				</foreach>\n			</select>\n			{$this->lang->words[\'sorting_text_in\']}\n			<select name=\'sort_order\' class=\'input_select\'>\n				<foreach loop=\"sort_order:$dropdowns[\'sort_order\'] as $k => $v\">\n					<option value=\'{$k}\'<if test=\"orderdefault:|:$k == $defaults[\'sort_order\']\"> selected=\'selected\'</if>>{$this->lang->words[ $v ]}</option>\n				</foreach>\n			</select>\n			{$this->lang->words[\'sorting_text_with\']}\n			<select name=\'max_results\' class=\'input_select\'>\n				<foreach loop=\"max_results:$dropdowns[\'max_results\'] as $k => $v\">\n					<option value=\'{$k}\'<if test=\"limitdefault:|:$k == $defaults[\'max_results\']\"> selected=\'selected\'</if>>{$v}</option>\n				</foreach>\n			</select>\n			{$this->lang->words[\'sorting_text_results\']}\n		</fieldset>\n		<fieldset class=\'submit clear\'>\n			<input type=\"submit\" value=\"{$this->lang->words[\'sort_submit\']}\" class=\"input_submit\" /> {$this->lang->words[\'or\']} <a href=\'#j_memberlist\' title=\'{$this->lang->words[\'cancel\']}\' id=\'close_filters\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n		</fieldset>\n	</form>\n</div>\n<script type=\'text/javascript\'>\n	$(\'member_filters\').hide();\n</script>\n<br />\n<div class=\'ipsBox ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_tinyleft clearfix\'>\n	<div class=\'ipsVerticalTabbed_tabs ipsVerticalTabbed_minitabs ipsLayout_left\' id=\'mlist_tabs\'>\n		<ul>\n			<if test=\"letterquickjump:|:!$this->request[\'quickjump\']\">\n				<li class=\'active\'><a href=\'{parse url=\"app=members&amp;module=list\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'members_start_with\']}{$letter}\'>{$this->lang->words[\'mlist_view_all_txt\']}</a></li>\n			<else />\n				<li><a href=\'{parse url=\"app=members&amp;module=list\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'mlist_view_all_title\']}\'>{$this->lang->words[\'mlist_view_all_txt\']}</a></li>\n			</if>\n			<foreach loop=\"chars:range(65,90) as $char\">\n				<if test=\"letterdefault:|:$letter = strtoupper(chr($char))\">\n					<li <if test=\"selected:|:strtoupper( $this->request[\'quickjump\'] ) == $letter\">class=\'active\'</if>><a href=\'{parse url=\"{$url}&amp;quickjump={$letter}\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'mlist_view_start_title\']} {$letter}\'>{$letter}</a></li>\n				</if>\n			</foreach>\n		</ul>\n	</div>\n	<div class=\'ipsVerticalTabbed_content ipsLayout_content\'>\n		<div class=\'maintitle ipsFilterbar clear clearfix\'>\n			<ul class=\'ipsList_inline left\'>\n				<li <if test=\"filtermembers:|:$this->request[\'sort_key\'] == \'members_display_name\' || !$this->request[\'sort_key\']\">class=\'active\'</if>>\n					<a href=\'{parse url=\"app=members&amp;module=list&amp;{$url}&amp;sort_key=members_display_name&amp;sort_order=asc\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'sort_by_mname\']}\'>{$this->lang->words[\'sort_by_name\']}</a>\n				</li>\n				<li <if test=\"filterposts:|:$this->request[\'sort_key\'] == \'posts\'\">class=\'active\'</if>>\n					<a href=\'{parse url=\"app=members&amp;module=list&amp;{$url}&amp;sort_key=posts&amp;sort_order=desc\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'sort_by_posts\']}\'>{$this->lang->words[\'pcount\']}</a>\n				</li>\n				<li <if test=\"filterjoined:|:$this->request[\'sort_key\'] == \'joined\'\">class=\'active\'</if>>\n					<a href=\'{parse url=\"app=members&amp;module=list&amp;{$url}&amp;sort_key=joined\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'sorty_by_jdate\']}\'>{$this->lang->words[\'sort_by_joined\']}</a>\n				</li>\n			</ul>\n		</div>\n		<div class=\'ipsBox_container ipsPad\' id=\'mlist_content\'>\n			<ul class=\'ipsMemberList\'>\n				<if test=\"showmembers:|:is_array( $members ) and count( $members )\">\n					{parse striping=\"memberStripe\" classes=\"row1,row2\"}\n					<foreach loop=\"members:$members as $member\">\n						<li id=\'member_id_{$member[\'member_id\']}\' class=\'ipsPad clearfix member_entry {parse striping=\"memberStripe\"}\'>\n							<a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$member[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n							<div class=\'ipsBox_withphoto\'>\n								<ul class=\'ipsList_inline right\'>\n									<if test=\"weAreSupmod:|:$this->memberData[\'g_is_supmod\'] == 1 && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n										<li><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;auth_key={$this->member->form_hash}&amp;mid={$member[\'member_id\']}&amp;pf={$member[\'member_id\']}\" base=\"public\"}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'edit_member\']}</a></li>\n									</if>\n									<if test=\"notus:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n										<if test=\"addfriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n											<li class=\'mini_friend_toggle is_friend\' id=\'friend_mlist_{$member[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a></li>\n										<else />\n											<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_mlist_{$member[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a></li>								\n										</if>\n									</if>\n									<if test=\"sendpm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' ) && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n										<li class=\'pm_button\' id=\'pm_xxx_{$member[\'pp_member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'pp_member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n									</if>\n									<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'gbl_find_my_content\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"find_topics_link\"}</a></li>\n									<if test=\"blog:|:$member[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) AND $member[\'has_blog\'] != \'recache\'\">\n										<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n									</if>\n									<if test=\"gallery:|:$member[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n										<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n									</if>\n								</ul>\n								\n								<h3 class=\'ipsType_subtitle\'>\n									<strong><a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></strong>\n									\n									<if test=\"rating:|:$this->settings[\'pp_allow_member_rate\'] && $this->request[\'pp_rating_real\']\">\n										<span class=\'rating\'> \n											<if test=\"rate1:|:$member[\'pp_rating_real\'] >= 1\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate2:|:$member[\'pp_rating_real\'] >= 2\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate3:|:$member[\'pp_rating_real\'] >= 3\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate4:|:$member[\'pp_rating_real\'] >= 4\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate5:|:$member[\'pp_rating_real\'] >= 5\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if>\n										</span>\n									</if>\n								</h3>\n								<if test=\"repson:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n									<if test=\"norep:|:$member[\'pp_reputation_points\'] == 0 || !$member[\'pp_reputation_points\']\">\n										<p class=\'reputation zero ipsType_small left\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'member_has_x_rep\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'] )\"}\">\n									</if>\n									<if test=\"posrep:|:$member[\'pp_reputation_points\'] > 0\">\n										<p class=\'reputation positive ipsType_small left\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'member_has_x_rep\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'] )\"}\">\n									</if>\n									<if test=\"negrep:|:$member[\'pp_reputation_points\'] < 0\">\n										<p class=\'reputation negative ipsType_small left\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'member_has_x_rep\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'] )\"}\">\n									</if>							\n											<span class=\'number\'>{$member[\'pp_reputation_points\']}</span>\n										</p>\n								</if>\n								<span class=\'desc\'>\n									{$this->lang->words[\'member_joined\']} {parse date=\"$member[\'joined\']\" format=\"joined\"}<br />\n									{IPSMember::makeNameFormatted( $member[\'group\'], $member[\'member_group_id\'] )} &middot; {parse format_number=\"$member[\'posts\']\"} {$this->lang->words[\'member_posts\']}\n								</span>\n							</div>\n						</li>						\n					</foreach>\n				<else />\n					<li class=\'no_messages\'>\n						{$this->lang->words[\'no_results\']}\n					</li>\n				</if>\n			</ul>\n		</div>\n	</div>\n</div>\n<script type=\'text/javascript\'>\n	$(\"mlist_content\").setStyle( { minHeight: $(\'mlist_tabs\').measure(\'margin-box-height\') + 5 + \"px\" } );\n</script>\n{$pages}', 'member_list_show', '$members, $pages=\"\", $dropdowns=array(), $defaults=array(), $custom_fields=null, $url=\'\'', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('437', '0', 'skin_online', '<div class=\'topic_controls\'>\n	{$links}\n</div>\n<h2 class=\'maintitle\'>{$this->lang->words[\'online_page_title\']}</h2>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		<table class=\'ipb_table ipsMemberList\' summary=\"{$this->lang->words[\'users_online\']}\">\n			<tr class=\'header\'>\n				<th scope=\'col\' width=\'55\'>&nbsp;</th>\n				<th scope=\'col\'>{$this->lang->words[\'member_name\']}</th>\n				<th scope=\'col\'>{$this->lang->words[\'where\']}</th>\n				<th scope=\'col\'>{$this->lang->words[\'time\']}</th>\n				<th scope=\'col\'>&nbsp;</th>\n			</tr>\n			<if test=\"onlineusers:|:count($rows)\">\n				{parse striping=\"online\" classes=\"row1,row2\"}\n				<foreach loop=\"online:$rows as $session\">\n					<tr class=\'{parse striping=\"online\"}\'>\n						<td>\n							<img src=\'{$session[\'_memberData\'][\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'], $session[\'_memberData\'][\'members_display_name\'] ? $session[\'_memberData\'][\'members_display_name\'] : $this->lang->words[\'global_guestname\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n						</td>\n						<td>\n							<if test=\"username:|:$session[\'member_name\']\">\n								<if test=\"userid:|:$session[\'member_id\']\">\n									<a hovercard-ref=\'member\' hovercard-id=\'{$session[\'member_id\']}\' class=\'url _hovertrigger\' href=\'{parse url=\"showuser={$session[\'member_id\']}\" template=\"showuser\" seotitle=\"{$session[\'seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{IPSMember::makeNameFormatted( $session[\'member_name\'], $session[\'member_group\'] )}</a>\n								<else />\n									{IPSMember::makeNameFormatted( $session[\'member_name\'], $session[\'member_group\'] )}\n								</if>\n							<else />\n								{$this->lang->words[\'global_guestname\']}\n							</if>\n							<if test=\"anonymous:|:$session[\'login_type\'] == 1\">\n								<if test=\"viewanon:|:$this->memberData[\'g_access_cp\']\">\n									*\n								</if>\n							</if>\n							<if test=\"showip:|:$this->memberData[\'g_access_cp\']\">\n								<span class=\'ip\'>( {$session[\'ip_address\']} )</span>\n							</if>\n						</td>\n						<td>\n							<if test=\"nowhere:|:!$session[\'where_line\'] || $session[\'in_error\']\">\n								{$this->lang->words[\'board_index\']}\n							<else />\n								<if test=\"wheretext:|:$session[\'where_link\'] AND !$session[\'where_line_more\']\">\n									<if test=\"wheretextseo:|:$session[\'_whereLinkSeo\']\">\n										<a href=\'{$session[\'_whereLinkSeo\']}\'>\n									<else />\n										<a href=\'{parse url=\"{$session[\'where_link\']}\" base=\"public\"}\'>\n									</if>\n								</if>\n								{$session[\'where_line\']} \n								<if test=\"moredetails:|:$session[\'where_line_more\']\">\n									&nbsp;\n									<if test=\"wheretextseo:|:$session[\'_whereLinkSeo\']\">\n										<a href=\'{$session[\'_whereLinkSeo\']}\'>\n									<else />\n										<if test=\"detailslink:|:$session[\'where_link\']\"><a href=\'{parse url=\"{$session[\'where_link\']}\" base=\"public\"}\'></if>\n									</if>\n									{$session[\'where_line_more\']}\n									<if test=\"enddetailslink:|:$session[\'where_link\']\"></a></if>\n								<else />\n									<if test=\"nomoreenddetailslink:|:$session[\'where_link\']\"></a></if>\n								</if>\n							</if>\n						</td>\n						<td>\n							{parse date=\"$session[\'running_time\']\" format=\"long\" relative=\"false\"}\n						</td>\n						<td>\n							<if test=\"options:|:$session[\'member_id\'] AND $session[\'member_name\']\">\n								<ul class=\'ipsList_inline ipsList_nowrap right\'>\n									<if test=\"notus:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $session[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n										<if test=\"addfriend:|:IPSMember::checkFriendStatus( $session[\'member_id\'] )\">\n											<li class=\'mini_friend_toggle is_friend\' id=\'friend_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$session[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a></li>\n										<else />\n											<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$session[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a></li>								\n										</if>\n									</if>\n									<if test=\"sendpm:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $session[\'member_id\'] AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n										<li class=\'pm_button\' id=\'pm_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n									</if>\n									<if test=\"blog:|:$session[\'memberData\'][\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) AND $session[\'memberData\'][\'has_blog\'] != \'recache\'\">\n										<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n									</if>\n									<if test=\"gallery:|:$session[\'memberData\'][\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n										<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n									</if>\n								</ul>\n							<else />\n								<span class=\'desc\'>{$this->lang->words[\'no_options_available\']}</span>\n							</if>\n						</td>\n					</tr>\n				</foreach>\n			</if>\n		</table>\n	</div>\n</div>\n<div id=\'forum_filter\' class=\'ipsForm_center ipsPad\'>\n	<form method=\"post\" action=\"{parse url=\"app=members&amp;section=online&amp;module=online\" base=\"public\"}\">\n		<label for=\'sort_key\'>{$this->lang->words[\'s_by\']}</label>\n		<select name=\"sort_key\" id=\'sort_key\' class=\'input_select\'>\n			<foreach loop=\"sort_key:array( \'click\', \'name\' ) as $sort\">\n				<option value=\'{$sort}\'<if test=\"defaultsort:|:$defaults[\'sort_key\'] == $sort\"> selected=\'selected\'</if>>{$this->lang->words[\'s_sort_key_\' . $sort ]}</option>\n			</foreach>\n		</select>\n		<select name=\"show_mem\" class=\'input_select\'>\n			<foreach loop=\"show_mem:array( \'reg\', \'guest\', \'all\' ) as $filter\">\n				<option value=\'{$filter}\'<if test=\"defaultfilter:|:$defaults[\'show_mem\'] == $filter\"> selected=\'selected\'</if>>{$this->lang->words[\'s_show_mem_\' . $filter ]}</option>\n			</foreach>\n		</select>\n		<select name=\"sort_order\" class=\'input_select\'>\n			<foreach loop=\"sort_order:array( \'desc\', \'asc\' ) as $order\">\n				<option value=\'{$order}\'<if test=\"defaultorder:|:$defaults[\'sort_order\'] == $order\"> selected=\'selected\'</if>>{$this->lang->words[\'s_sort_order_\' . $order ]}</option>\n			</foreach>\n		</select>\n		<input type=\"submit\" value=\"{$this->lang->words[\'s_go\']}\" class=\"input_submit alt\" />\n	</form>\n</div>\n<br />\n<div class=\'topic_controls\'>\n	{$links}\n</div>', 'showOnlineList', '$rows, $links=\"\", $defaults=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('438', '0', 'skin_profile', '<span class=\'row_title\'>{$f->raw_data[\'pf_title\']}</span>\n<div class=\'row_data\'>\n	<if test=\"gender_set:|:$f->value\">\n		<if test=\"male:|:$f->value == \'m\'\">\n			<img src=\'{$this->settings[\'img_url\']}/profile/male.png\' alt=\'{$this->lang->words[\'js_gender_male\']}\' /> {$this->lang->words[\'js_gender_male\']}\n		</if>\n	\n		<if test=\"female:|:$f->value == \'f\'\">\n			<img src=\'{$this->settings[\'img_url\']}/profile/female.png\' alt=\'{$this->lang->words[\'js_gender_female\']}\' /> {$this->lang->words[\'js_gender_female\']}\n		</if>\n	\n		<if test=\"nottelling:|:$f->value != \'f\' AND $f->value != \'m\'\">\n			<img src=\'{$this->settings[\'img_url\']}/profile/mystery.png\' alt=\'{$this->lang->words[\'js_gender_mystery\']}\' /> {$this->lang->words[\'js_gender_mystery\']}\n		</if>\n	<else />\n		<img src=\'{$this->settings[\'img_url\']}/profile/mystery.png\' alt=\'{$this->lang->words[\'js_gender_mystery\']}\' /> {$this->lang->words[\'js_gender_mystery\']}\n	</if>\n</div>', 'customField__gender', '$f', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('439', '0', 'skin_profile', '<if test=\"$f->parsed != \'\'\">\n	<span class=\'row_title\'>{$f->raw_data[\'pf_title\']}</span>\n	<div class=\'row_data\'>\n		<if test=\"genericIsArray:|:is_array($f->parsed)\">\n			{parse expression=\"implode( \'<br />\', $f->parsed )\"}\n		<else />\n			{$f->parsed}\n		</if>\n	</div>\n</if>', 'customField__generic', '$f', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('440', '0', 'skin_profile', '<if test=\"contact_field:|:$f->parsed\">\n<li>\n	<span class=\'row_title\'>{$f->raw_data[\'pf_title\']}</span>\n	<span class=\'row_data\'>\n		<if test=\"cf_icon:|:$f->raw_data[\'pf_icon\']\"><img src=\'{$this->settings[\'public_dir\']}{$f->raw_data[\'pf_icon\']}\' alt=\'{$f->raw_data[\'pf_title\']}\' />&nbsp;</if>\n		<if test=\"cf_array:|:is_array( $f->parsed )\">\n			<foreach loop=\"cfieldgroups:$f->parsed as $value\">\n				{$value}\n			</foreach>\n		<else />\n			<if test=\"cf_aim:|:$f->raw_data[\'pf_key\'] == \'aim\'\">\n				<a class=\'url\' href=\'aim:goim?screenname={$f->parsed}\'>{$f->parsed}</a>\n			<else />\n				<if test=\"cf_msn:|:$f->raw_data[\'pf_key\'] == \'msn\'\">\n					<a class=\'url\' href=\'msnim:chat?contact={$f->parsed}\'>{$f->parsed}</a>\n				<else />\n					<if test=\"cf_yahoo:|:$f->raw_data[\'pf_key\'] == \'yahoo\'\">\n						<a class=\'url\' href=\'ymsgr:sendIM?{$f->parsed}\'>{$f->parsed}</a>\n					<else />\n						<if test=\"cf_icq:|:$f->raw_data[\'pf_key\'] == \'icq\'\">\n							<a class=\'url\' type=\"application/x-icq\" href=\'http://www.icq.com/people/cmd.php?uin={$f->parsed}&amp;action=message\'>{$f->parsed}</a>\n						<else />\n							<if test=\"cf_website:|:$f->raw_data[\'pf_key\'] == \'website\'\">\n								<a class=\'url uid\' rel=\"me\" href=\'{$f->parsed}\'>{$f->parsed}</a>\n							<else />\n								<if test=\"cf_jabber:|:$f->raw_data[\'pf_key\'] == \'jabber\'\">\n									<a class=\'url\' href=\'xmpp:{$f->parsed}\'>{$f->parsed}</a>\n								<else />\n									<if test=\"cf_skype:|:$f->raw_data[\'pf_key\'] == \'skype\'\">\n										<a class=\'url\' href=\'skype:{$f->parsed}?call\'>{$f->parsed}</a>\n									<else />\n										{$f->parsed}\n									</if>\n								</if>\n							</if>\n						</if>\n					</if>\n				</if>\n			</if>\n		</if>\n	</span>\n</li>\n</if>', 'customFieldGroup__contact', '$f', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('441', '0', 'skin_profile', '<style type=\"text/css\">\n/* Overwrite some of the standard IPB rules */\n/* Content, is the main page under the header */\n#content {\n	max-width:87%;\n	min-width: 980px;\n	margin-left: auto;\n	margin-right: auto;\n	background: transparent url(\"{style_images_url}/opacity70.png\");\n	background: rgba(255,255,255,0.3);\n}\n#profile_background {\n	background: transparent url(\"{style_images_url}/opacity70.png\");\n	background: rgba(255,255,255,0.3);\n}\n.topic_buttons li.non_button a, #footer_utilities {\n	background: #fff !important;\n}\n<if test=\"$member[\'customization\'][\'bg_color\'] OR $member[\'customization\'][\'_bgUrl\']\">\nbody {\n	<if test=\"$member[\'customization\'][\'bg_color\']\">\n		background-color: #{$member[\'customization\'][\'bg_color\']};\n	</if>\n	<if test=\"$member[\'customization\'][\'_bgUrl\']\">\n		background-image: url(\"{$member[\'customization\'][\'_bgUrl\']}\");\n		<if test=\"! $member[\'customization\'][\'bg_tile\']\">\n			background-position: 0px 0px;\n			background-attachment: fixed;\n			background-repeat: no-repeat;\n		<else />\n			background-position: 0px 0px;\n			background-attachment: fixed;\n			background-repeat: repeat;\n		</if>\n	</if>\n}\n</if>\n</style>\n<script type=\"text/javascript\">\n	ipb.profile.customization = 1;\n</script>', 'customizeProfile', '$member', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('442', '0', 'skin_profile', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'dname_window_title\']} {$member_name}</h3>\n<else />\n	<h3 class=\'maintitle\'>{$this->lang->words[\'dname_window_title\']} {$member_name}</h3>\n</if>\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_name_from\']}</th>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_name_to\']}</th>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_date\']}</th>\n	</tr>\n	<if test=\"hasDnameHistory:|:is_array($records) AND count($records)\">\n		{parse striping=\"dname\" classes=\"row1,row2\"}\n    	<foreach loop=\"records:$records as $row\">\n		<tr class=\'{parse striping=\"dname\"}\'>\n		 	<td>{$row[\'dname_previous\']}</td>\n		 	<td><strong>{$row[\'dname_current\']}</strong></td>\n		 	<td class=\'altrow\'>{parse date=\"$row[\'dname_date\']\" format=\"short\"}</td>\n		</tr>\n		</foreach>\n	<else />\n		<tr>\n			<td colspan=\'3\' class=\'no_messages\'>{$this->lang->words[\'dname_no_history\']}</td>\n		</tr>\n    </if>\n</table>', 'dnameWrapper', '$member_name=\"\",$records=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('443', '0', 'skin_profile', '{parse js_module=\"friends\"}\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'m_friends_list\']}</h1>\n<if test=\"friendListPages:|:$pages\">\n	<div class=\'topic_controls\'>\n		$pages\n	</div>\n</if>\n<div class=\'maintitle ipsFilterbar clear\'>\n	<ul class=\'ipsList_inline clearfix\'>\n		<if test=\"tabIsList:|:$this->request[\'tab\'] == \'list\' || !$this->request[\'tab\']\">\n			<li class=\'active\'><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=list\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_list\']}\'>{$this->lang->words[\'m_friends_list\']}</a></li>\n			<li><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=pending\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_pending\']}\'>{$this->lang->words[\'m_friends_pending\']}</a></li>\n		</if>\n		<if test=\"tabIsPending:|:$this->request[\'tab\'] == \'pending\'\">\n			<li><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=list\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_list\']}\'>{$this->lang->words[\'m_friends_list\']}</a></li>\n			<li class=\'active\'><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=pending\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_pending\']}\'>{$this->lang->words[\'m_friends_pending\']}</a></li>\n		</if>\n	</ul>\n</div>\n<if test=\"hasFriendsList:|:is_array($friends) and count($friends) && $this->settings[\'friends_enabled\']\">\n	{parse striping=\"memberStripe\" classes=\"row1,row2\"}\n	<ul class=\'ipsMemberList\'>\n		<foreach loop=\"friendsList:$friends as $friend\">\n			<if test=\"loopOnPending:|:$this->request[\'tab\'] == \'pending\'\">\n				<li id=\'member_id_{$friend[\'member_id\']}\' class=\'ipsPad clearfix member_entry {parse striping=\"memberStripe\"}\'>\n					<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" template=\"showuser\" seotitle=\"{$friend[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$friend[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$friend[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n					<div class=\'ipsBox_withphoto\'>\n						<ul class=\'ipsList_inline right\'>\n							<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=moderate&amp;pp_option=approve&amp;pp_friend_id[{$friend[\'member_id\']}]=1&amp;md5check={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'approve_request\']}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'approve_request\']}</a></li>\n							<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=moderate&amp;pp_option=delete&amp;pp_friend_id[{$friend[\'member_id\']}]=1&amp;md5check={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'deny_request\']}\' class=\'ipsButton_secondary important\'>{$this->lang->words[\'deny_request\']}</a></li>\n						</ul>\n						\n						<h3 class=\'ipsType_subtitle\'>\n							<strong><a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" template=\"showuser\" seotitle=\"{$friend[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$friend[\'members_display_name\']}</a></strong>\n						</h3>\n						<if test=\"repson:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n							<if test=\"norep:|:$friend[\'pp_reputation_points\'] == 0 || !$friend[\'pp_reputation_points\']\">\n								<p class=\'reputation zero ipsType_small left\'>\n							</if>\n							<if test=\"posrep:|:$friend[\'pp_reputation_points\'] > 0\">\n								<p class=\'reputation positive ipsType_small left\'>\n							</if>\n							<if test=\"negrep:|:$friend[\'pp_reputation_points\'] < 0\">\n								<p class=\'reputation negative ipsType_small left\'>\n							</if>							\n									<span class=\'number\'>{$friend[\'pp_reputation_points\']}</span>\n								</p>\n						</if>\n						<span class=\'desc\'>\n							{$this->lang->words[\'member_joined\']} {parse date=\"$friend[\'joined\']\" format=\"joined\"}<br />\n							{IPSMember::makeNameFormatted( $friend[\'group\'], $friend[\'member_group_id\'] )} &middot; {parse format_number=\"$friend[\'posts\']\"} {$this->lang->words[\'member_posts\']}\n						</span>\n					</div>\n				</li>\n			<else />\n				<li id=\'member_id_{$friend[\'member_id\']}\' class=\'ipsPad clearfix member_entry {parse striping=\"memberStripe\"}\'>\n					<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" template=\"showuser\" seotitle=\"{$friend[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$friend[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$friend[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' /></a>\n					<div class=\'ipsBox_withphoto\'>\n						<ul class=\'ipsList_inline right\'>\n							<if test=\"weAreSupmod:|:$this->memberData[\'g_is_supmod\'] == 1 && $friend[\'member_id\'] != $this->memberData[\'member_id\']\">\n								<li><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;auth_key={$this->member->form_hash}&amp;mid={$friend[\'member_id\']}&amp;pf={$friend[\'member_id\']}\" base=\"public\"}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'supmod_edit_member\']}</a></li>\n							</if>\n							<if test=\"notus:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $friend[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n								<if test=\"addfriend:|:IPSMember::checkFriendStatus( $friend[\'member_id\'] )\">\n									<li class=\'mini_friend_toggle is_friend\' id=\'friend_mlist_{$friend[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$friend[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"remove_friend\"}</a></li>\n								<else />\n									<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_mlist_{$friend[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$friend[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"add_friend\"}</a></li>								\n								</if>\n							</if>\n							<if test=\"sendpm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' ) && $friend[\'member_id\'] != $this->memberData[\'member_id\']\">\n								<li class=\'pm_button\' id=\'pm_xxx_{$friend[\'pp_member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=list&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$friend[\'pp_member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}</a></li>\n							</if>\n							<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$friend[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'gbl_find_my_content\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"find_topics_link\"}</a></li>\n							<if test=\"blog:|:$friend[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) AND $friend[\'has_blog\'] != \'recache\'\">\n								<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$friend[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"blog_link\"}</a></li>\n							</if>\n							<if test=\"gallery:|:$friend[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n								<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$friend[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"gallery_link\"}</a></li>\n							</if>\n						</ul>\n						\n						<h3 class=\'ipsType_subtitle\'>\n							<strong><a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" template=\"showuser\" seotitle=\"{$friend[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$friend[\'members_display_name\']}</a></strong>\n						</h3>\n						<if test=\"repson:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n							<if test=\"norep:|:$friend[\'pp_reputation_points\'] == 0 || !$friend[\'pp_reputation_points\']\">\n								<p class=\'reputation zero ipsType_small left\'>\n							</if>\n							<if test=\"posrep:|:$friend[\'pp_reputation_points\'] > 0\">\n								<p class=\'reputation positive ipsType_small left\'>\n							</if>\n							<if test=\"negrep:|:$friend[\'pp_reputation_points\'] < 0\">\n								<p class=\'reputation negative ipsType_small left\'>\n							</if>							\n									<span class=\'number\'>{$friend[\'pp_reputation_points\']}</span>\n								</p>\n						</if>\n						<span class=\'desc\'>\n							{$this->lang->words[\'member_joined\']} {parse date=\"$friend[\'joined\']\" format=\"joined\"}<br />\n							{IPSMember::makeNameFormatted( $friend[\'group\'], $friend[\'member_group_id\'] )} &middot; {parse format_number=\"$friend[\'posts\']\"} {$this->lang->words[\'member_posts\']}\n						</span>\n					</div>\n				</li>\n			</if>\n		\n		</foreach>\n	</ul>\n<else />\n	<p class=\'no_messages\'>\n		<if test=\"friendListNone:|:$this->request[\'tab\'] == \'pending\'\">\n			{$this->lang->words[\'no_friends_awaiting_approval\']}\n		<else />\n			{$this->lang->words[\'no_friends_to_display\']}\n		</if>\n	</p>\n</if>\n<if test=\"friendListPagesBottom:|:$pages\">\n	<div class=\'topic_controls\'>\n		{$pages}\n	</div>\n</if>', 'friendsList', '$friends, $pages', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('444', '0', 'skin_profile', '<link rel=\"stylesheet\" type=\"text/css\" media=\"screen\" href=\"{$this->settings[\'public_dir\']}style_css/{$this->registry->output->skin[\'_csscacheid\']}/ipb_photo_editor.css\" />\n<script type=\"text/javascript\">\n 	// Can\'t use normal link as loaded by Ajax\n    $$(\"head\")[0].insert(new Element(\"script\", {\n      type: \"text/javascript\",\n      src: \'{$this->settings[\'public_dir\']}js/ips.inlineUploader.js\'\n    })).\n    insert(new Element(\"script\", {\n      type: \"text/javascript\",\n      src: \'{$this->settings[\'public_dir\']}js/ips.photoEditor.js\'\n    })).\n    insert(new Element(\"script\", {\n      type: \"text/javascript\",\n      src: \'{$this->settings[\'public_dir\']}js/3rd_party/cropper/cropper.uncompressed.js\'\n    }));\n</script>\n<form method=\'post\' enctype=\"multipart/form-data\" action=\"{parse url=\"app=members&amp;module=profile&amp;section=photo&amp;do=save\" base=\"public\"}\" id=\'photoEditorForm\' name=\'photoEditorForm\'>\n<h3>{$this->lang->words[\'pe_title\']}</h3>\n<div class=\'ipsBox\'>\n<div class=\'fixed_inner\'>\n	<fieldset id=\'ips_photoWrap\' class=\'fixed_inner ipsBox_container\'>\n		<div id=\'ips_sidePanel\'>\n			<div id=\"ips_currentPhoto\">\n				{$data[\'currentPhoto\'][\'tag\']}\n			</div>\n			<div id=\'ips_cropperControls\' style=\'display:none\'>\n				<a href=\"javascript:void(0);\" class=\"ipsButton_secondary desc cropperCancel\">{$this->lang->words[\'pe_cancel\']}</a> <a href=\"javascript:void(0);\" class=\"ipsButton_secondary desc cropperAccept\">{$this->lang->words[\'pe_ok\']}</a>\n			</div>\n			<div id=\'ips_cropperStart\' style=\'<if test=\"$data[\'type\'] == \'gravatar\'\">display:none</if>;\'>\n				<a href=\"javascript:void(0);\" class=\"ipsButton_secondary desc cropperStart\">{$this->lang->words[\'adjust_crop_lnk\']}</a>\n			</div>\n		</div>\n		<div id=\'ips_photoOptions\'>\n			<ul>\n				<li class=\'ips_option row2\'>\n					<div class=\'ips_photoPreview _custom\'><label>{$data[\'custom\'][\'tag\']}</label></div>\n					<div class=\'ips_photoControls\'>\n						<input type=\'radio\' name=\'photoType\' id=\'ips_ptype_custom\' value=\'custom\' <if test=\"$data[\'type\'] == \'custom\'\">checked=\'checked\'</if> /> <strong>{$this->lang->words[\'pe_use_custom_photo\']}</strong>\n						<div class=\'ips_photoOptionText\'>\n							<span class=\'desc\'>{$this->lang->words[\'pe_upload_desc\']}.<br />{$this->lang->words[\'pe_upload_rec\']}</span>\n							<br />\n							<input type=\"file\" name=\"upload_photo\" id=\'upload_photo\' class=\'input_text\' value=\"\" size=\"20\" title=\"{$this->lang->words[\'pe_formats\']}\" />\n							<if test=\"canHasURL:|:$this->settings[\'mem_photo_url\']\">\n							<br />\n							<span class=\'desc\'>{$this->lang->words[\'pe_import_from_url\']}</span>\n							<br /><input type=\'text\' class=\'input_text\' size=\'20\' id=\'url_photo\' name=\'url_photo\' /> <input type=\'button\' id=\'url_import\' value=\'Import\' class=\'ipsButton_secondary desc\' />\n							</if>\n							<div class=\'message error\' style=\'display:none\' id=\'ips_type_custom_error\'></div>\n						</div>\n					</div>\n				</li>\n				<if test=\"allowGravatars:|:$this->settings[\'allow_gravatars\']\">\n				<li class=\'ips_option row2\'>\n					<div class=\'ips_photoPreview _gravatar\'><label>{$data[\'gravatar\'][\'tag\']}</label></div>\n					<div class=\'ips_photoControls\'>\n						<input type=\'radio\' name=\'photoType\' id=\'ips_ptype_gravatar\' value=\'gravatar\' <if test=\"$data[\'type\'] == \'gravatar\'\">checked=\'checked\'</if> /> <strong>{$this->lang->words[\'pe_use_gravatar\']}</strong>\n						<div class=\'ips_photoOptionText\'>\n							<span class=\'desc\'><a href=\"http://www.gravatar.com\" rel=\"external\">{$this->lang->words[\'pe_what_is_gravatar\']}</a></span>\n							<br /><br />\n							<input type=\"text\" name=\"gravatar\" id=\'gravatar\' class=\'input_text\' size=\"35\" value=\"{$member[\'pp_gravatar\']}\" />\n							<br /><span class=\'desc\'>{$this->lang->words[\'pe_enter_gravatar_email\']}</span>\n						</div>\n					</div>\n				</li>\n				</if>\n				<if test=\"hasTwitter:|:! empty($data[\'twitter\'][\'tag\'])\">\n				<li class=\'ips_option row2\'>\n					<div class=\'ips_photoPreview _twitter\'><label>{$data[\'twitter\'][\'tag\']}</label></div>\n					<div class=\'ips_photoControls\'>\n						<input type=\'radio\' name=\'photoType\' id=\'ips_ptype_twitter\' value=\'twitter\' <if test=\"$data[\'type\'] == \'twitter\'\">checked=\'checked\'</if> /> <strong>{$this->lang->words[\'pe_use_twitter\']}</strong>\n						<div class=\'ips_photoOptionText\'>\n							<span class=\'desc\'>{$this->lang->words[\'pe_twitter_desc\']}</span>					\n						</div>\n					</div>\n				</li>\n				</if>\n				<if test=\"hasFacebook:|:! empty($data[\'facebook\'][\'tag\'])\">\n				<li class=\'ips_option row2\'>\n					<div class=\'ips_photoPreview _facebook\'><label>{$data[\'facebook\'][\'tag\']}</label></div>\n					<div class=\'ips_photoControls\'>\n						<input type=\'radio\' name=\'photoType\' id=\'ips_ptype_facebook\' value=\'facebook\' <if test=\"$data[\'type\'] == \'facebook\'\">checked=\'checked\'</if> /> <strong>{$this->lang->words[\'pe_use_facebook\']}</strong>\n						<div class=\'ips_photoOptionText\'>\n							<span class=\'desc\'>{$this->lang->words[\'pe_facebook_desc\']}</span>					\n						</div>\n					</div>\n				</li>\n				</if>\n				<li class=\'ipsPad_half clearfix right\'>\n					<input type=\'button\' name=\'remove\' value=\'{$this->lang->words[\'pe_remove_button\']}\' class=\'ipsButton important ips_photoRemove\' />\n					<input type=\'submit\' name=\'saveit\' value=\'{$this->lang->words[\'pe_done_button\']}\' class=\'ipsButton ips_photoSubmit\' />\n				</li>\n			</ul>\n		</div>\n	</fieldset>\n</div>\n</div>\n</form>', 'photoEditor', '$data, $member', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('445', '0', 'skin_profile', '{parse js_module=\"status\"}\n{parse js_module=\"rating\"}\n{parse js_module=\"profile\"}\n<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.profile.viewingProfile = parseInt( {$member[\'member_id\']} );\n	ipb.templates[\'remove_friend\'] = \"<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=remove&amp;member_id={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_as_friend\']}\'><img src=\'{$this->settings[\'img_url\']}/user_delete.png\' alt=\'{$this->lang->words[\'remove_as_friend\']}\' />&nbsp;&nbsp; {$this->lang->words[\'remove_as_friend\']}</a>\";\n	ipb.templates[\'add_friend\'] = \"<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=add&amp;member_id={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_me_friend\']}\'><img src=\'{$this->settings[\'img_url\']}/user_add.png\' alt=\'{$this->lang->words[\'add_me_friend\']}\' />&nbsp;&nbsp; {$this->lang->words[\'add_me_friend\']}</a>\";\n	ipb.templates[\'edit_status\'] = \"<span id=\'edit_status\'><input type=\'text\' class=\'input_text\' style=\'width: 60%\' id=\'updated_status\' maxlength=\'150\' /> <input type=\'submit\' value=\'{$this->lang->words[\'save\']}\' class=\'input_submit\' id=\'save_status\' /> &nbsp;<a href=\'#\' id=\'cancel_status\' class=\'cancel\' title=\'{$this->lang->words[\'cancel\']}\'>{$this->lang->words[\'cancel\']}</a></span>\";\n	<if test=\"friendsEnabled:|:$this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n		<if test=\"jsIsFriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n			ipb.profile.isFriend = true;\n		<else />\n			ipb.profile.isFriend = false;\n		</if>\n	</if>\n//]]>\n</script>\n<if test=\"hasCustomization:|:is_array($member[\'customization\']) AND $member[\'customization\'][\'type\']\">\n	{parse template=\"customizeProfile\" group=\"profile\" params=\"$member\"}\n</if>\n<if test=\"canEditUser:|:($this->memberData[\'member_id\'] && $member[\'member_id\'] == $this->memberData[\'member_id\']) || $this->memberData[\'g_is_supmod\'] == 1 || ($this->memberData[\'member_id\'] && $member[\'member_id\'] != $this->memberData[\'member_id\'])\">\n	<ul class=\'topic_buttons\'>\n		<if test=\"weAreSupmod:|:$this->memberData[\'g_is_supmod\'] == 1 && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n			<li><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;auth_key={$this->member->form_hash}&amp;mid={$member[\'member_id\']}&amp;pf={$member[\'member_id\']}\" base=\"public\"}\'>{$this->lang->words[\'supmod_edit_member\']}</a></li>\n		</if>\n		<if test=\"weAreOwner:|:$this->memberData[\'member_id\'] && $member[\'member_id\'] == $this->memberData[\'member_id\']\">\n			<li><a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core\" base=\"public\"}\'>{$this->lang->words[\'edit_profile\']}</a></li>\n		</if>\n		<if test=\"supModCustomization:|:($member[\'member_id\'] == $this->memberData[\'member_id\'] ) AND $member[\'customization\'][\'type\']\">\n			<li class=\'non_button\'><a href=\'{parse url=\"showuser={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}&amp;removeCustomization=1\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\'>{$this->lang->words[\'cust_remove\']}</a></li>\n		</if>\n	</ul>\n</if>\n<div class=\'ipsBox clear vcard\' id=\'profile_background\'>\n	<div class=\'ipsVerticalTabbed ipsLayout ipsLayout_withleft ipsLayout_smallleft clearfix\'>\n		<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\' id=\'profile_tabs\'>\n			<p class=\'short photo_holder\'>\n				<if test=\"canEditPic:|:($this->memberData[\'member_id\'] && $member[\'member_id\'] == $this->memberData[\'member_id\']) AND (IPSMember::canUploadPhoto($member))\">\n					<a data-clicklaunch=\"launchPhotoEditor\" href=\"{parse url=\"app=members&amp;module=profile&amp;section=photo\" base=\"public\"}\" id=\'change_photo\' class=\'ipsType_smaller ipsPad\' title=\'{$this->lang->words[\'change_photo_desc\']}\'>{$this->lang->words[\'change_photo_link\']}</a>\n				</if>\n				<img class=\"ipsUserPhoto\" id=\'profile_photo\' src=\'{$member[\'pp_main_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\"  />\n			</p>\n			<if test=\"haswarn:|:$member[\'warn_percent\'] !== NULL\">\n				<div class=\'warn_panel clear ipsType_small\'>\n					<strong><a href=\'{parse url=\"app=core&amp;module=modcp&amp;section=editmember&amp;do=view&amp;mid={$member[\'member_id\']}&amp;_tab=warnlogs\" base=\"public\"}\' id=\'warn_link_xxx_{$member[\'member_id\']}\' title=\'{$this->lang->words[\'warn_view_history\']}\' class=\'warn_link\'>{$this->lang->words[\'warn_status\']}</a></strong>\n					<if test=\"highwarn:|:$member[\'warn_percent\'] >= 80\">\n						<p class=\'progress_bar user_warn limit\' title=\'{$this->lang->words[\'warn_level\']} {$member[\'warn_percent\']}%\'>\n					<else />\n						<p class=\'progress_bar user_warn\' title=\'{$this->lang->words[\'warn_level\']} {$member[\'warn_percent\']}%\'>\n					</if>\n							<span style=\'width: {$member[\'warn_percent\']}%\'><span>{$this->lang->words[\'warn_level\']} {$member[\'warn_percent\']}%</span></span>\n						</p>\n				</div>\n			</if>\n			<ul class=\'clear\'>\n				<li id=\'tab_link_core:info\' class=\'tab_toggle <if test=\"$default_tab == \'core:info\'\">active</if>\' data-tabid=\'user_info\'><a href=\'#\'>{$this->lang->words[\'pp_tab_info\']}</a></li>\n				<foreach loop=\"tabs:$tabs as $tab\">\n					<li id=\'tab_link_{$tab[\'app\']}:{$tab[\'plugin_key\']}\' class=\'<if test=\"tabactive:|:$tab[\'app\'].\':\'.$tab[\'plugin_key\'] == $default_tab || $this->request[\'tab\'] == $tab[\'plugin_key\']\">active</if> tab_toggle\' data-tabid=\'{$tab[\'plugin_key\']}\'><a href=\'{parse url=\"showuser={$member[\'member_id\']}&amp;tab={$tab[\'plugin_key\']}\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view\']} {$tab[\'_lang\']}\'>{$tab[\'_lang\']}</a></li>\n				</foreach>\n			</ul>\n		</div>\n		<div class=\'ipsVerticalTabbed_content ipsLayout_content ipsBox_container\' id=\'profile_content\'>\n			<div class=\'ipsPad\'>\n				<div id=\'profile_content_main\'>\n					<div id=\'user_info_cell\'>\n						<h1 class=\'ipsType_pagetitle\'>\n							<span class=\'fn nickname\'>{$member[\'members_display_name\']}</span>\n						</h1>\n						{$this->lang->words[\'m_member_since\']} {parse date=\"$member[\'joined\']\" format=\"DATE\"}<br />\n						<if test=\"onlineDetails:|:$member[\'_online\'] && ($member[\'online_extra\'] != $this->lang->words[\'not_online\'])\">\n							<span class=\'ipsBadge ipsBadge_green reset_cursor\' data-tooltip=\"{parse expression=\"strip_tags($member[\'online_extra\'])\"}\">{$this->lang->words[\'online_online\']}</span>\n						<else />\n							<span class=\'ipsBadge ipsBadge_lightgrey reset_cursor\'>{$this->lang->words[\'online_offline\']}</span>\n						</if>\n						<span class=\'desc lighter\'>{$this->lang->words[\'m_last_active\']} {$member[\'_last_active\']}</span> \n					</div>\n					<if test=\"userStatus:|:$status[\'status_id\']\">\n					<div id=\'user_status_cell\'>\n						<div id=\'user_latest_status\'>\n							<div>\n								{parse expression=\"IPSText::truncate( strip_tags( $status[\'status_content\'] ), 180 )\"}\n								<span class=\'ipsType_smaller desc lighter blend_links\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$status[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{$this->lang->words[\'ps_updated\']} {parse date=\"$status[\'status_date\']\" format=\"manual{%d %b}\" relative=\"true\"} &middot; {parse expression=\"intval($status[\'status_replies\'])\"} {$this->lang->words[\'ps_comments\']}</a></span>\n							</div>\n						</div>\n					</div>\n					</if>\n					<if test=\"allowRate:|:$this->settings[\'pp_allow_member_rate\']\">\n						<span class=\'rating left clear\' style=\'margin-bottom: 10px\'>\n							<if test=\"noRateYourself:|:$this->memberData[\'member_id\'] == $member[\'member_id\'] || !$this->memberData[\'member_id\']\">\n									<if test=\"rate1:|:$member[\'pp_rating_real\'] >= 1\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate2:|:$member[\'pp_rating_real\'] >= 2\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate3:|:$member[\'pp_rating_real\'] >= 3\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate4:|:$member[\'pp_rating_real\'] >= 4\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"rate5:|:$member[\'pp_rating_real\'] >= 5\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><span id=\'rating_text\' class=\'desc\'></span>\n							<else />\n									<a href=\'#\' id=\'user_rate_1\' title=\'{$this->lang->words[\'m_rate_1\']}\'><if test=\"rated1:|:$member[\'pp_rating_real\'] >= 1\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if></a><a href=\'#\' id=\'user_rate_2\' title=\'{$this->lang->words[\'m_rate_2\']}\'><if test=\"rated2:|:$member[\'pp_rating_real\'] >= 2\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if></a><a href=\'#\' id=\'user_rate_3\' title=\'{$this->lang->words[\'m_rate_3\']}\'><if test=\"rated3:|:$member[\'pp_rating_real\'] >= 3\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if></a><a href=\'#\' id=\'user_rate_4\' title=\'{$this->lang->words[\'m_rate_4\']}\'><if test=\"rated4:|:$member[\'pp_rating_real\'] >= 4\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if></a><a href=\'#\' id=\'user_rate_5\' title=\'{$this->lang->words[\'m_rate_5\']}\'><if test=\"rated5:|:$member[\'pp_rating_real\'] >= 5\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if></a> <span id=\'rating_text\' class=\'desc\'></span>\n								<script type=\'text/javascript\'>\n									rating = new ipb.rating( \'user_rate_\', { \n														url: \'{parse url=\"app=members&module=ajax&section=rate&member_id={$member[\'member_id\']}\" base=\"public\"}&md5check=\' + ipb.vars[\'secure_hash\'],\n														cur_rating: <if test=\"hasrating:|:isset($member[\'pp_rating_real\'])\">{$member[\'pp_rating_real\']}<else />0</if>,\n														rated: null,\n														allow_rate: ( {$this->memberData[\'member_id\']} != 0 ) ? 1 : 0,\n														show_rate_text: false\n													  } );\n								</script>\n							</if>\n						</span>\n					</if>\n					<ul class=\'ipsList_inline\' id=\'user_utility_links\'>\n						<if test=\"noFriendYourself:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n							<li id=\'friend_toggle\' class=\'ipsButton_secondary\'>\n								<if test=\"isFriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n									<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=remove&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'><img src=\'{$this->settings[\'img_url\']}/user_delete.png\' alt=\'{$this->lang->words[\'remove_friend\']}\' />&nbsp;&nbsp; {$this->lang->words[\'remove_as_friend\']}</a>\n								<else />\n									<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=add&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'><img src=\'{$this->settings[\'img_url\']}/user_add.png\' alt=\'{$this->lang->words[\'add_friend\']}\' />&nbsp;&nbsp; {$this->lang->words[\'add_me_friend\']}</a>\n								</if>\n							</li>\n						</if>\n						<if test=\"pmlink:|:($member[\'member_id\'] != $this->memberData[\'member_id\']) AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' ) AND $member[\'members_disable_pm\'] == 0\">\n							<li class=\'pm_button\' id=\'pm_xxx_{$member[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_this_member\']}\' class=\'ipsButton_secondary\'>{parse replacement=\"send_msg\"}&nbsp;&nbsp; {$this->lang->words[\'send_message\']}</a></li>\n						</if>\n						<li>\n							<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' class=\'ipsButton_secondary\'>{parse replacement=\"find_topics_link\"}&nbsp;&nbsp;  {$this->lang->words[\'gbl_find_my_content\']}</a>\n						</li>\n					</ul>\n				</div>\n				<div id=\'profile_panes_wrap\' class=\'clearfix\'>\n					\n					<div id=\'pane_core:info\' class=\'ipsLayout ipsLayout_withright ipsLayout_largeright clearfix\' <if test=\"$default_tab != \'core:info\'\">style=\'display: none\'</if>>						\n						<div class=\'ipsLayout_content\'>\n							<if test=\"$member[\'pp_about_me\']\">\n								<div class=\'general_box clearfix\'>\n									<h3>{$this->lang->words[\'pp_tab_aboutme\']}</h3>\n									<div class=\'ipsPad\'>\n										\n											{$member[\'pp_about_me\']}\n										\n									</div>\n								</div>\n								<hr/>\n							</if>\n							<div class=\'general_box clearfix\'>\n								<h3>{$this->lang->words[\'community_stats\']}</h3>\n								<br />								\n								<ul class=\'ipsList_data clearfix\'>									\n									<li class=\'clear clearfix\'>\n										<span class=\'row_title\'>{$this->lang->words[\'m_group\']}</span>\n										<span class=\'row_data\'>{$member[\'g_title\']}</span>\n									</li>\n									<li class=\'clear clearfix\'>\n										<span class=\'row_title\'>{$this->lang->words[\'m_posts\']}</span>\n										<span class=\'row_data\'>{parse format_number=\"$member[\'posts\']\"} ({$member[\'_posts_day\']} {$this->lang->words[\'posts_per_day\']})</span>\n									</li>\n									<if test=\"favoriteForum:|:!$this->settings[\'disable_profile_stats\'] AND $member[\'favorite_id\']\">\n										<li class=\'clear clearfix\'>\n											<span class=\'row_title\'>{$this->lang->words[\'m_active_in\']}</span>\n											<span class=\'row_data\'>\n												<a href=\'{parse url=\"showforum={$member[\'favorite_id\']}\" seotitle=\"{$this->registry->class_forums->forum_by_id[ $member[\'favorite_id\'] ][\'name_seo\']}\" template=\"showforum\" base=\"public\"}\'>{$this->registry->class_forums->forum_by_id[ $member[\'favorite_id\'] ][\'name\']}</a> ({$member[\'_fav_posts\']} {$this->lang->words[\'fav_posts\']})\n											</span>\n										</li>\n									</if>\n									<li class=\'clear clearfix\'>\n										<span class=\'row_title\'>{$this->lang->words[\'m_profile_views\']}</span>\n										<span class=\'row_data\'>{parse format_number=\"$member[\'members_profile_views\']\"}</span>\n									</li>\n									<if test=\"member_title:|:$member[\'title\'] != \'\'\">\n										<li class=\'clear clearfix\'>\n											<span class=\'row_title\'>{$this->lang->words[\'m_member_title\']}</span>\n											<span class=\'row_data\'>{$member[\'title\']}</span>\n										</li>\n									</if>\n									<li class=\'clear clearfix\'>\n										<span class=\'row_title\'>{$this->lang->words[\'m_age_prefix\']}</span>\n										<if test=\"member_age:|:$member[\'_age\'] > 0\">\n											<span class=\'row_data\'>{$member[\'_age\']} {$this->lang->words[\'m_years_old\']}</span>\n										<else />\n											<span class=\'row_data desc lighter\'>{$this->lang->words[\'m_age_unknown\']}</span>\n										</if>\n									</li>\n									<li class=\'clear clearfix\'>\n										<span class=\'row_title\'>{$this->lang->words[\'m_birthday_prefix\']}</span>\n										<if test=\"member_birthday:|:$member[\'bday_day\']\">\n											<span class=\'row_data\'>{$member[\'_bday_month\']} {$member[\'bday_day\']}<if test=\"member_bday_year:|:$member[\'bday_year\']\">, {$member[\'bday_year\']}</if></span>\n										<else />\n											<span class=\'row_data desc lighter\'>{$this->lang->words[\'m_bday_unknown\']}</span>\n										</if>\n									</li>\n									<if test=\"pcfields:|:$member[\'custom_fields\'][\'profile_info\'] != \"\"\">\n										<foreach loop=\"pcfieldsLoop:$member[\'custom_fields\'][\'profile_info\'] as $key => $value\">\n											<li class=\'clear clearfix\'>\n												{$value}\n											</li>\n										</foreach>\n									</if>\n								</ul>\n								<br />\n							</div>\n							\n							<if test=\"pcfieldsOther:|:$member[\'custom_fields\']\">\n								<foreach loop=\"pcfieldsOtherLoop:$member[\'custom_fields\'] as $group => $mdata\">\n									<if test=\"pcfieldsOtherLoopCheck:|:$group != \'profile_info\' AND $group != \'contact\'\">\n										<if test=\"pcfieldsOtherLoopCheck2:|:is_array( $member[\'custom_fields\'][ $group ] ) AND count( $member[\'custom_fields\'][ $group ] )\">\n											<div class=\'general_box clearfix\' id=\'custom_fields_{$group}\'>\n												<h3 class=\'bar\'>{$member[\'custom_field_groups\'][ $group ]}</h3>\n												<br />\n												<ul class=\'ipsList_data clearfix\'>\n													<foreach loop=\"pcfieldsOtherLoopCheckInner:$member[\'custom_fields\'][ $group ] as $key => $value\">\n														<li class=\'clear clearfix\'>\n															{$value}\n														</li>\n													</foreach>\n												</ul>\n												<br />\n											</div>\n										</if>\n									</if>\n								</foreach>\n							</if>\n							\n							<if test=\"hasContactFields:|:$this->memberData[\'g_access_cp\'] == 1 || is_array( $member[\'custom_fields\'][\'contact\'])\">\n								<div class=\'general_box clearfix\'>\n									<h3>{$this->lang->words[\'contact_info\']}</h3>\n									<br />\n								\n									<ul class=\'ipsList_data clearfix\'>\n										<if test=\"isadmin:|:$this->memberData[\'g_access_cp\'] == 1\">\n											<li class=\'clear clearfix\'>\n												<span class=\'row_title\'>{$this->lang->words[\'m_email\']}</span>\n												<span class=\'row_data\'>\n													<a href=\'mailto:{$member[\'email\']}\'>{$member[\'email\']}</a>\n												</span>\n											</li>\n										</if>\n										<if test=\"member_contact_fields:|:is_array( $member[\'custom_fields\'][\'contact\'])\">\n											<foreach loop=\"cfields:$member[\'custom_fields\'][\'contact\'] as $field\">\n												<li class=\'clear clearfix\'>\n													{$field}\n												</li>\n											</foreach>\n										</if>\n									</ul>\n								</div>\n							</if>\n						</div>\n						\n						<div class=\'ipsLayout_right\'>\n							<if test=\"ourReputation:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n								<if test=\"RepPositive:|:$member[\'pp_reputation_points\'] > 0\">\n									<div class=\'reputation positive\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'rep_description\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'])\"}\">\n								</if>\n								<if test=\"RepNegative:|:$member[\'pp_reputation_points\'] < 0\">\n									<div class=\'reputation negative\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'rep_description\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'])\"}\">\n								</if>\n								<if test=\"RepZero:|:$member[\'pp_reputation_points\'] == 0\">\n									<div class=\'reputation zero\' data-tooltip=\"{parse expression=\"sprintf( $this->lang->words[\'rep_description\'], $member[\'members_display_name\'], $member[\'pp_reputation_points\'])\"}\">\n								</if>\n										<span class=\'number\'>{$member[\'pp_reputation_points\']}</span>\n										<if test=\"RepText:|:$member[\'author_reputation\'] && $member[\'author_reputation\'][\'text\']\">\n											<span class=\'title\'>{$member[\'author_reputation\'][\'text\']}</span>\n										</if>\n										<if test=\"RepImage:|:$member[\'author_reputation\'] && $member[\'author_reputation\'][\'image\']\">\n											<span class=\'image\'><img src=\'{$member[\'author_reputation\'][\'image\']}\' alt=\'{$this->lang->words[\'m_reputation\']}\' /></span>\n										</if>\n									</div>\n								\n								<br />\n							</if>\n							\n							<if test=\"checkModTools:|:($member[\'spamStatus\'] !== NULL && $member[\'member_id\'] != $this->memberData[\'member_id\']) || ($this->memberData[\'g_mem_info\'] && $this->settings[\'auth_allow_dnames\']) || (($member[\'member_id\'] != $this->memberData[\'member_id\'] AND $this->memberData[\'g_is_supmod\'] ) AND $member[\'customization\'][\'type\'])\">\n								<div class=\'general_box clearfix\'>\n									<h3>{$this->lang->words[\'user_tools\']}</h3>\n									<ul class=\'ipsPad\'>	\n										<if test=\"authorspammer:|:$member[\'spamStatus\'] !== NULL && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n											<if test=\"authorspammerinner:|:$member[\'spamStatus\'] === TRUE\">\n												<li><a href=\'#\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, false)\">{parse replacement=\"spammer_on\"} {$this->lang->words[\'spm_on\']}</a></li>\n											<else />\n												<li><a href=\'{$this->settings[\'base_url\']}app=core&amp;module=modcp&amp;section=editmember&amp;do=setAsSpammer&amp;member_id={$member[\'member_id\']}&amp;auth_key={$this->member->form_hash}\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, true)\">{parse replacement=\"spammer_off\"} {$this->lang->words[\'spm_off\']}</a></li>\n											</if>\n										</if>\n										<if test=\"dnameHistory:|:$this->memberData[\'g_mem_info\'] && $this->settings[\'auth_allow_dnames\']\">\n											<li id=\'dname_history\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=dname&amp;id={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_dname_history\']}\'>{parse replacement=\"display_name\"} {$this->lang->words[\'display_name_history\']}</a></li>\n										</if>\n								\n										<if test=\"supModCustomizationDisable:|:($member[\'member_id\'] != $this->memberData[\'member_id\'] AND $this->memberData[\'g_is_supmod\'] ) AND $member[\'customization\'][\'type\']\">\n											<li><strong><a href=\'{parse url=\"showuser={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}&amp;removeCustomization=1\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\'><img src=\'{$this->settings[\'img_url\']}/delete.png\' alt=\'-\' /> {$this->lang->words[\'cust_remove\']}</a></strong></li>\n											<li><strong><a href=\'{parse url=\"showuser={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}&amp;removeCustomization=1&amp;disableCustomization=1\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\'><img src=\'{$this->settings[\'img_url\']}/delete.png\' alt=\'-\' /> {$this->lang->words[\'cust_disable\']}</a></strong></li>\n										</if>\n									</ul>\n								</div>\n							</if>\n							\n							<if test=\"$member[\'pp_setting_count_friends\']\">\n								<div class=\'general_box clearfix\' id=\'friends_overview\'>\n									<h3>{$this->lang->words[\'m_title_friends\']}</h3>\n									<div class=\'ipsPad\'>\n										<if test=\"hasFriends:|:count($friends) AND is_array($friends)\">\n											<foreach loop=\"friendsLoop:$friends as $friend\">\n												<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$friend[\'members_seo_name\']}\"}\' class=\'ipsUserPhotoLink\'>\n													<img src=\'{$friend[\'pp_mini_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' data-tooltip=\'{$friend[\'members_display_name\']}\' />\n												</a>\n											</foreach>\n										<else />\n											<p class=\'desc\'>\n												{$member[\'members_display_name\']} {$this->lang->words[\'no_friends_yet\']}\n											</p>\n										</if>\n									</div>\n								</div>\n							</if>\n							<br /><br />\n							\n							<if test=\"latest_visitors:|:$member[\'pp_setting_count_visitors\']\">\n								<div class=\'general_box clearfix\'>\n									<h3>{$this->lang->words[\'latest_visitors\']}</h3>\n									<if test=\"has_visitors:|:is_array( $visitors ) && count( $visitors )\">\n										<ul class=\'ipsList_withminiphoto ipsPad\'>\n											<foreach loop=\"latest_visitors_loop:$visitors as $friend\">\n											<li class=\'clearfix\'>\n												<if test=\"visitorismember:|:$friend[\'member_id\']\">\n													<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$friend[\'pp_mini_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' /></a>\n												<else />\n													<img src=\'{$friend[\'pp_mini_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini left\' />\n												</if>\n												<div class=\'list_content\'>\n													<if test=\"visitorismember3:|:$friend[\'member_id\']\"><a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'></if>{$friend[\'members_display_name_short\']}<if test=\"visitorismember4:|:$friend[\'member_id\']\"></a></if>\n													<br />\n													<span class=\'desc lighter\'>{$friend[\'_visited_date\']}</span>\n												</div>\n											</li>				\n											</foreach>\n										</ul>\n									<else />\n										<p class=\'ipsPad desc\'>{$this->lang->words[\'no_latest_visitors\']}</p>\n									</if>\n								</div>\n							</if>\n						</div>					\n					</div>\n					\n					<if test=\"$default_tab != \'core:info\'\">\n					<div id=\'pane_{$default_tab}\'>\n						{$default_tab_content}\n					</div>\n					</if>\n				</div>				\n				\n			</div>			\n		</div>\n		\n	</div>\n</div>\n<if test=\"thisIsNotUs:|:($this->memberData[\'member_id\'] && $member[\'member_id\'] != $this->memberData[\'member_id\'])\">\n	<br />\n	<ul class=\'topic_buttons\'>\n		<li class=\'non_button clearfix\'><a href=\'{parse url=\"app=core&amp;module=reports&amp;section=reports&amp;rcom=profiles&amp;member_id={$member[\'member_id\']}\" base=\"public\"}\'>{$this->lang->words[\'report_member\']}</a></li>\n	</ul>\n</if>\n<script type=\'text/javascript\'>\n	$(\"profile_content\").setStyle( { minHeight: $(\'profile_tabs\').measure(\'margin-box-height\') + 138 + \"px\" } );\n</script>\n\n<!-- ******************************************************************************************* -->\n{parse template=\"include_highlighter\" group=\"global\" params=\"\"}', 'profileModern', '$tabs=array(), $member=array(), $visitors=array(), $default_tab=\'status\', $default_tab_content=\'\', $friends=array(), $status=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('446', '0', 'skin_profile', '<div class=\'vcard userpopup\'>\n	<h3><a href=\"{parse url=\"showuser={$member[\'member_id\']}\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" class=\"fn nickname url\">{$member[\'members_display_name\']}</a></h3>\n	<div class=\'side left ipsPad\'>\n		<a href=\"{parse url=\"showuser={$member[\'member_id\']}\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" class=\"ipsUserPhotoLink\">\n			<img src=\"{$member[\'pp_thumb_photo\']}\" alt=\"{$this->lang->words[\'get_photo\']}\" class=\'ipsUserPhoto ipsUserPhoto_large\' />\n		</a>\n		<br />\n		<if test=\"cardRep:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n			<if test=\"cardRepPos:|:$member[\'pp_reputation_points\'] > 0\">\n				<div class=\'reputation positive\'>\n			</if>\n			<if test=\"cardRepNeg:|:$member[\'pp_reputation_points\'] < 0\">\n				<div class=\'reputation negative\'>\n			</if>\n			<if test=\"cardRepZero:|:$member[\'pp_reputation_points\'] == 0\">\n				<div class=\'reputation zero\'>\n			</if>\n					<span class=\'number\'>{$member[\'pp_reputation_points\']}</span>\n				</div>\n		</if>\n		<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'gbl_find_my_content\']}\' class=\'ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'gbl_find_my_content\']}</a>\n		<if test=\"cardSendPm:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' ) AND $member[\'members_disable_pm\'] == 0\">\n			<a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_this_member\']}\' id=\'pm_xxx_{$member[\'member_id\']}\' class=\'pm_button ipsButton_secondary ipsType_smaller\'>{$this->lang->words[\'pm_this_member\']}</a>\n		</if>\n	</div>\n	<div class=\'ipsPad\'>\n		<if test=\"cardStatus:|:$member[\'_status\'][\'status_content\']\">\n			<p class=\'message user_status\'>{$member[\'_status\'][\'status_content\']}</p>\n		</if>\n		<div class=\'info\'>			\n			<dl>\n				<dt>{$this->lang->words[\'m_group\']}</dt>\n				<dd>{$member[\'_group_formatted\']}</dd>\n				<dt>{$this->lang->words[\'m_posts\']}</dt>\n				<dd title=\'{$member[\'_posts_day\']} {$this->lang->words[\'posts_per_day\']}\'>{parse format_number=\"$member[\'posts\']\"}</dd>\n				<dt>{$this->lang->words[\'m_member_since\']}</dt>\n				<dd>{parse date=\"$member[\'joined\']\" format=\"joined\"}</dd>\n				<dt>{$this->lang->words[\'m_last_active\']}</dt>\n				<dd><if test=\"cardOnline:|:$member[\'_online\']\"><span class=\'ipsBadge ipsBadge_green\'>{$this->lang->words[\'online_online\']}</span><else /><span class=\'ipsBadge ipsBadge_grey\'>{$this->lang->words[\'online_offline\']}</span></if> {$member[\'_last_active\']}</dd>\n				<if test=\"cardWhere:|:$member[\'_online\']\">\n					<dt>{$this->lang->words[\'m_currently\']}</dt>\n					<dd>\n						{$member[\'online_extra\']}\n					</dd>\n				</if>\n				<if test=\"isadmin:|:$this->memberData[\'g_access_cp\'] == 1\">\n					<dt>{$this->lang->words[\'m_email\']}</dt>\n					<dd><a href=\'mailto:{$member[\'email\']}\'>{$member[\'email\']}</a></dd>\n				</if>\n			</dl>\n		</div>\n		<ul class=\'user_controls clear\'>\n			<if test=\"authorspammer:|:$member[\'spamStatus\'] !== NULL && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n				<if test=\"authorspammerinner:|:$member[\'spamStatus\'] === TRUE\">\n					<li><a href=\'#\' title=\'{$this->lang->words[\'spm_on\']}\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, false)\">{parse replacement=\"spammer_on\"}</a></li>\n				<else />\n					<li><a title=\'{$this->lang->words[\'spm_off\']}\' href=\'{$this->settings[\'base_url\']}app=core&amp;module=modcp&amp;section=editmember&amp;do=setAsSpammer&amp;member_id={$member[\'member_id\']}&amp;auth_key={$this->member->form_hash}\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, true)\">{parse replacement=\"spammer_off\"}</a></li>\n				</if>\n			</if>\n			<if test=\"cardFriend:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n				<if test=\"cardIsFriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n					<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n				<else />\n					<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n				</if>\n			</if>			\n			<if test=\"cardBlog:|:$member[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) && $member[\'has_blog\'] != \'recache\'\">\n				<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n			</if>\n			<if test=\"cardGallery:|:$member[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n				<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n			</if>\n		</ul>\n	</div>\n</div>', 'showCard', '$member, $download=0', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('447', '0', 'skin_profile', '<if test=\"!$no_wrapper\">\n	<ul class=\'ipsList_withtinyphoto clear\'>\n</if>\n<foreach loop=\"innerLoop:$replies as $reply\">\n	<li id=\'statusReply-{$reply[\'reply_id\']}\' class=\'ipsPad row2\'>\n		<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$reply[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$reply[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_tiny\' /></a>	\n		<div class=\"status_mini_content list_content\">\n			<h5>\n				<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' style=\'font-weight:bold\'>{$reply[\'members_display_name\']}</a>\n			</h5>\n			{$reply[\'reply_content\']}\n			<br />\n			<span class=\'desc lighter\'>{$reply[\'reply_date_formatted\']}</span>\n			<span class=\'desc mod_links\'>\n				<if test=\"canDelete:|:$reply[\'_canDelete\']\"> &middot; <a href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=deleteReply&amp;status_id={$reply[\'reply_status_id\']}&amp;reply_id={$reply[\'reply_id\']}&amp;k={$this->member->form_hash}\" id=\"statusReplyDelete-{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\" class=\"__sDR __dr{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\">{$this->lang->words[\'status_delete_link\']}</a></if>\n			</span>\n		</div>\n	</li>\n</foreach>\n<if test=\"!$no_wrapper\">\n	</ul>\n</if>', 'statusReplies', '$replies=array(), $no_wrapper=false', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('448', '0', 'skin_profile', '<script type=\"text/javascript\">\n//ipb.status.maxReplies = {parse expression=\"intval($this->settings[\'su_max_replies\'])\"};\n//ipb.status.smallSpace = {parse expression=\"intval($smallSpace)\"};\n</script>\n<foreach loop=\"outerLoop:$updates as $id => $status\">\n	<if test=\"$this->memberData[\'member_id\'] AND $latestOnly AND $status[\'member_id\'] == $this->memberData[\'member_id\']\">\n	<script type=\"text/javascript\">\n		ipb.status.myLatest = {$status[\'status_id\']};\n	</script>\n	</if>\n	<div class=\'ipsBox_container ipsPad\' id=\'statusWrap-{$status[\'status_id\']}\'>\n		<a href=\'{parse url=\"showuser={$status[\'member_id\']}\" seotitle=\"{$status[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'>\n			<img src=\'{$status[\'pp_small_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$status[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_medium\' />\n		</a>	\n		<div class=\"ipsBox_withphoto status_content\">\n			<div id=\"statusContent-{$status[\'status_id\']}\">\n				<h4>\n					{parse template=\"userHoverCard\" group=\"global\" params=\"$status\"}\n					<if test=\"forSomeoneElse:|:$status[\'status_member_id\'] != $status[\'status_author_id\']\">\n						&rarr;\n						{parse template=\"users_photoCard\" group=\"global\" params=\"$status[\'owner\']\"}\n					</if>\n				</h4>\n				<div class=\'status_status\'>\n					{$status[\'status_content\']}\n				</div>\n				<span class=\'desc lighter blend_links\'>\n					<img src=\"{$this->settings[\'img_url\']}/icon_lock.png\" id=\'statusLockImg-{$status[\'status_id\']}\' alt=\"{$this->lang->words[\'status__locked\']}\" <if test=\"noLocked:|:!$status[\'status_is_locked\']\">style=\'display: none\'</if> />\n					<if test=\"cImg:|:! $smallSpace AND $status[\'_creatorImg\']\"><img src=\"{$status[\'_creatorImg\']}\" alt=\'\' /></if>\n					<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=single&amp;status_id={$status[\'status_id\']}\" seotitle=\"true\" template=\"members_status_single\" base=\"public\"}\'>{$status[\'status_date_formatted_short\']}</a><if test=\"creatorText:|:$smallSpace AND $status[\'_creatorText\'] AND $status[\'status_creator\'] AND $status[\'status_creator\'] != \'ipb\'\"> {$this->lang->words[\'su_via\']} {$status[\'_creatorText\']}</if>\n				</span>\n				<span class=\'mod_links\'>\n					<if test=\"canDelete:|:$status[\'_canDelete\']\"> &middot; <a rel=\"nofollow\" href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=deleteStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusDelete-{$status[\'status_id\']}\" class=\"__sD __d{$status[\'status_id\']}\">{$this->lang->words[\'status_delete_link\']}</a></if>\n					<span id=\'statusUnlock-{$status[\'status_id\']}\' <if test=\"isLocked:|:$status[\'_isLocked\'] AND $status[\'_canUnlock\']\">style=\'display:inline\'<else />style=\'display:none\'</if>> &middot; <a rel=\"nofollow\"  href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=unlockStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusUnlockLink-{$status[\'status_id\']}\" class=\"__sU __u{$status[\'status_id\']}\">{$this->lang->words[\'status_unlock_link\']}</a></span>\n					<span id=\'statusLock-{$status[\'status_id\']}\' <if test=\"canLock:|:$status[\'_canLock\'] AND ! $status[\'_isLocked\']\">style=\'display:inline\'<else />style=\'display:none\'</if>> &middot; <a rel=\"nofollow\"  href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=lockStatus&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}\" id=\"statusLockLink-{$status[\'status_id\']}\" class=\"__sL __l{$status[\'status_id\']}\">{$this->lang->words[\'status_lock_link\']}</a></span>\n				</span>\n			</div>\n			<div id=\"statusFeedback-{$status[\'status_id\']}\" class=\'status_feedback\'>\n				<if test=\"$status[\'status_replies\'] AND count( $status[\'replies\'] )\">\n					<if test=\"hasMore:|:$status[\'status_replies\'] > 3\">\n						<div class=\'status_mini_wrap row2 altrow\' id=\'statusMoreWrap-{$status[\'status_id\']}\'>\n							<img src=\"{$this->settings[\'img_url\']}/comments.png\" alt=\"\" /> &nbsp;<a href=\"#\" id=\"statusMore-{$status[\'status_id\']}\" class=\'__showAll __x{$status[\'status_id\']}\'>{parse expression=\"sprintf( $this->lang->words[\'status_show_all_x\'], $status[\'status_replies\'] )\"}</a>\n						</div>\n					</if>\n					<ul id=\'statusReplies-{$status[\'status_id\']}\' class=\'ipsList_withtinyphoto clear\'>\n						{parse template=\"statusReplies\" group=\"profile\" params=\"$status[\'replies\'], 1\"}\n					</ul>\n				</if>\n				<div id=\'statusReplyBlank-{$status[\'status_id\']}\'></div>\n				<div id=\'statusReply-{$status[\'status_id\']}\'>\n				<if test=\"$status[\'_userCanReply\']\">\n					<ul class=\'ipsList_withtinyphoto reply row2 ipsPad\'>\n						<li>\n							<form id=\'statusReplyForm-{$status[\'status_id\']}\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=reply&amp;status_id={$status[\'status_id\']}&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}\' method=\'post\'>\n								<a href=\'{parse url=\"showuser={$this->memberData[\'member_id\']}\" seotitle=\"{$this->memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink left\'><img src=\'{$this->memberData[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$this->memberData[\'members_display_name\'])\"}\" class=\'ipsUserPhoto ipsUserPhoto_tiny\' /></a>\n								<div class=\'list_content\'>\n									<div class=\"status_mini_content\">\n										<textarea class=\'status_textarea input_text\' rows=\'3\' cols=\'50\' name=\'comment-{$status[\'status_id\']}\' id=\'statusText-{$status[\'status_id\']}\'></textarea>\n										<div class=\"status_submit\"><input type=\'submit\' class=\'__submit input_submit\' id=\'statusSubmit-{$status[\'status_id\']}\' value=\'{$this->lang->words[\'status__dfcomment\']}\' /></div>\n									</div>									\n								</div>\n							</form>\n							<a href=\'#\' class=\'__showform\' id=\'statusReplyFormShow-{$status[\'status_id\']}\' style=\'display: none\'>{$this->lang->words[\'status__addcomment\']}</a>\n						</li>\n					</ul>\n					<script type=\'text/javascript\'>\n						if( $(\'statusReplyForm-{$status[\'status_id\']}\') )\n						{\n							$(\'statusReplyForm-{$status[\'status_id\']}\').hide();\n						}\n						\n						if( $(\'statusReplyFormShow-{$status[\'status_id\']}\') )\n						{\n							$(\'statusReplyFormShow-{$status[\'status_id\']}\').show();\n						}\n					</script>\n				</if>\n				</div>\n				<div class=\'status_mini_wrap row2 altrow\' id=\'statusMaxWrap-{$status[\'status_id\']}\' <if test=\"maxReplies:|:$status[\'status_replies\'] < $this->settings[\'su_max_replies\']\">style=\'display:none\'</if>>\n					<img src=\"{$this->settings[\'img_url\']}/locked_replies.png\" title=\"{$this->lang->words[\'status_too_many_replies\']}\" alt=\'x\' /> {$this->lang->words[\'status_too_many_replies\']}\n				</div>\n			</div>\n		</div>\n	</div>\n</foreach>', 'statusUpdates', '$updates=array(), $smallSpace=0, $latestOnly=0', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('449', '0', 'skin_profile', '{parse js_module=\"status\"}\n{parse striping=\"recent_status\" classes=\"row1,row2 altrow\"}\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'status_updates__overview\']}</h1>\n<br />\n<div id=\'status_standalone_page\'>\n	<div class=\'maintitle ipsFilterbar\'>\n		<ul class=\'ipsList_inline\'>\n			<li id=\'status_all\' class=\'<if test=\"tabactive:|:! $this->request[\'status_id\'] AND ! $this->request[\'member_id\'] AND ! $this->request[\'type\'] OR $this->request[\'type\'] == \'all\'\">active</if>\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=all\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\'>{$this->lang->words[\'status__all_updates\']}</a></li>\n			<if test=\"$this->memberData[\'member_id\'] AND $this->settings[\'friends_enabled\']\">\n				<li id=\'status_all\' class=\'tab_toggle <if test=\"tabactive2:|:$this->request[\'type\'] == \'friends\'\">active</if>\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=friends\" seotitle=\"true\" template=\"members_status_friends\" base=\"public\"}\'>{$this->lang->words[\'status__myfriends\']}</a></li>\n			</if>\n			<if test=\"$this->request[\'member_id\']\">\n				<li id=\'status_by_id\' class=\'active\'><a href=\'#\'>{$this->lang->words[\'status__membersupdats\']}</a></li>\n			</if>\n			<if test=\"$this->request[\'status_id\']\">\n				<li id=\'status_by_sid\' class=\'active\'><a href=\'#\'>{$this->lang->words[\'status__singleupdate\']}</a></li>\n			</if>\n		</ul>\n	</div>\n	<if test=\"canCreate:|:$this->memberData[\'member_id\'] AND $this->registry->getClass(\'memberStatus\')->canCreate( $this->memberData )\">\n		<div class=\'status_update row2\'>\n			<form id=\'statusForm\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=new&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}\' method=\'post\'>\n			<input type=\'text\' id=\'statusUpdate_page\' name=\'content\' style=\'width:60%\' class=\'input_text\'> <input type=\'submit\' class=\'ipsButton\' id=\'statusSubmit_page\' value=\'{$this->lang->words[\'gbl_post\']}\' />\n			<if test=\"update:|:(IPSLib::twitter_enabled() OR IPSLib::fbc_enabled() ) AND ( $this->memberData[\'fb_uid\'] OR $this->memberData[\'twitter_id\'] )\">\n				<p class=\'desc\' style=\'padding-top:5px;\'>{$this->lang->words[\'st_update\']}\n					<if test=\"updateTwitter:|:IPSLib::twitter_enabled() AND ( $this->memberData[\'twitter_id\'] )\"><input type=\'checkbox\' id=\'su_Twitter\' value=\'1\' name=\'su_Twitter\' /> <img src=\"{$this->settings[\'public_dir\']}style_status/twitter.png\" style=\'vertical-align:top\' alt=\'\' /></if>\n					<if test=\"updateFacebook:|:IPSLib::fbc_enabled() AND ( $this->memberData[\'fb_uid\'] )\"><input type=\'checkbox\' id=\'su_Facebook\' value=\'1\' name=\'su_Facebook\' /> <img src=\"{$this->settings[\'public_dir\']}style_status/facebook.png\" style=\'vertical-align:top\' alt=\'\' /></if>\n				</p>\n			</if>\n			</form>\n		</div>\n	</if>\n	<div id=\"status_wrapper\" class=\'ipsBox\'>\n		<if test=\"hasUpdates:|:count( $updates )\">\n			{parse template=\"statusUpdates\" group=\"profile\" params=\"$updates\"}\n		<else />\n			<p class=\'no-status\'>{$this->lang->words[\'status_updates_none\']}</p>\n		</if>\n	</div>\n	<div class=\'topic_controls clearfix\'>\n		{$pages}\n	</div>\n</div>', 'statusUpdatesPage', '$updates=array(), $pages=\'\'', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('450', '0', 'skin_profile', '<div class=\'general_box\'>\n	<if test=\"friends:|:$this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\'] AND $member[\'pp_setting_count_friends\']\">\n		<div class=\'friend_list clear\' id=\'friend_list\'>\n			<h3 class=\'bar\'>{$this->lang->words[\'m_title_friends\']}</h3>\n			<if test=\"friends_loop:|:is_array($friends) and count($friends)\">\n				<ul class=\'clearfix\'>\n				<foreach loop=\"friends:$friends as $friend\">\n					<li>\n						<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' class=\'ipsUserPhotoLink\'>\n							<img src=\'{$friend[\'pp_small_photo\']}\' alt=\'{$this->lang->words[\'photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_medium\' />\n						</a><br />\n						<span class=\'name\'>\n							{parse expression=\"IPSMember::makeProfileLink($friend[\'members_display_name_short\'], $friend[\'member_id\'], $friend[\'members_seo_name\'])\"}\n						</span>\n					</li>\n				</foreach>\n				</ul>				\n			<else />\n				<p>\n					<em>{$member[\'members_display_name\']} {$this->lang->words[\'no_friends_yet\']}</em>\n				</p>\n			</if>\n		</div>\n	</if>\n</div>', 'tabFriends', '$friends=array(), $member=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('451', '0', 'skin_profile', '<div class=\'no_messages\'>{$this->lang->words[ $langkey ]}</div>', 'tabNoContent', '$langkey', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('452', '0', 'skin_profile', '<h3 class=\'maintitle\'>{$this->lang->words[\'posts_made\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		{$content}\n	</div>\n</div>', 'tabPosts', '$content', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('453', '0', 'skin_profile', '<div class=\'post_block no_sidebar\'>\n	<div class=\'post_wrap\'>\n		<if test=\"singleColumnTitle:|:$title\">\n			<if test=\"singleColumnUrl:|:$url\">\n				<h3 class=\'row2\'><a href=\"$url\" title=\"{$this->lang->words[\'view_topic\']}\">{parse expression=\"IPSText::truncate( $title, 90 )\"}</a></h3>\n			<else />\n				<h3 class=\'row2\'>{parse expression=\"IPSText::truncate( $title, 90 )\"}</h3>\n			</if>\n		</if>\n		<div class=\'post_body\'>\n			<p class=\'posted_info\'>\n				<if test=\"date:|:$row[\'_raw_date\']\">{parse date=\"$row[\'_raw_date\']\" format=\"long\"}<else />{$this->lang->words[\'posted\']} {$row[\'_date_array\'][\'mday\']} {$row[\'_date_array\'][\'smonth\']} {$row[\'_date_array\'][\'year\']}</if>\n			</p>\n			<div class=\'post\'>\n				{$row[\'post\']}\n			</div>\n		</div>\n	</div>\n	<br />\n</div>', 'tabSingleColumn', '$row=array(), $read_more_link=\'\', $url=\'\', $title=\'\'', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('454', '0', 'skin_profile', '{parse striping=\"recent_status\" classes=\"row1,row2\"}\n<h2 class=\'maintitle\'>{$this->lang->words[\'pp_tab_statusupdates\']}</h2>\n<if test=\"canCreate:|:$this->memberData[\'member_id\'] AND ( $this->memberData[\'member_id\'] == $member[\'member_id\'] ) AND $this->registry->getClass(\'memberStatus\')->canCreate( $member )\">\n	<div class=\'status_update\'>\n		<form id=\'statusForm\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=new&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}&amp;forMemberId={$member[\'member_id\']}\' method=\'post\'>\n		<input type=\'text\' name=\'content\' id=\'statusUpdate_page\' class=\'input_text\' /> <input type=\'submit\' class=\'ipsButton\' id=\'statusSubmit_page\' value=\'{$this->lang->words[\'gbl_post\']}\' />\n		<if test=\"update:|:(IPSLib::twitter_enabled() OR IPSLib::fbc_enabled() ) AND ( $this->memberData[\'fb_uid\'] OR $this->memberData[\'twitter_id\'] )\">\n			<p class=\'desc\' style=\'padding-top:5px;\'>{$this->lang->words[\'st_update\']}\n				<if test=\"updateTwitter:|:IPSLib::twitter_enabled() AND ( $this->memberData[\'twitter_id\'] )\"><input type=\'checkbox\' id=\'su_Twitter\' value=\'1\' name=\'su_Twitter\' /> <img src=\"{$this->settings[\'public_dir\']}style_status/twitter.png\" style=\'vertical-align:top\' alt=\'\' /></if>\n				<if test=\"updateFacebook:|:IPSLib::fbc_enabled() AND ( $this->memberData[\'fb_uid\'] )\">&nbsp;<input type=\'checkbox\' id=\'su_Facebook\' value=\'1\' name=\'su_Facebook\' /> <img src=\"{$this->settings[\'public_dir\']}style_status/facebook.png\" style=\'vertical-align:top\' alt=\'\' /></if>\n			</p>\n		</if>\n		</form>\n	</div>\n</if>\n<if test=\"leave_comment:|:$this->memberData[\'member_id\'] && $this->memberData[\'member_id\'] != $member[\'member_id\'] && $member[\'pp_setting_count_comments\']\">\n	<div class=\'status_update\'>\n		<form id=\'commentForm\' action=\'{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=new&amp;k={$this->member->form_hash}&amp;id={$this->memberData[\'member_id\']}&amp;forMemberId={$member[\'member_id\']}\' method=\'post\'>\n				<input type=\'hidden\' name=\'member_id\' value=\'{$member[\'member_id\']}\' />\n				<input type=\'hidden\' name=\'auth_key\' value=\'{$this->member->form_hash}\' />\n				<div id=\'post_comment\'>\n					<input type=\'text\' class=\'input_text\' cols=\'50\' rows=\'3\' id=\'statusUpdate_page\' name=\'content\' data-for-member-id=\"{$member[\'member_id\']}\" />\n					<input type=\'submit\' class=\'ipsButton\' value=\'{$this->lang->words[\'comment_submit_post\']}\' data-for-member-id=\"{$member[\'member_id\']}\" id=\'statusSubmit_page\' />\n				</div> \n		</form>\n	</div>\n</if>\n<div class=\'ipsBox clearfix\'>\n	<div id=\"status_wrapper\">\n		<if test=\"hasUpdates:|:count( $updates )\">\n			{parse template=\"statusUpdates\" group=\"profile\" params=\"$updates\"}\n			<div style=\'text-align: center\'>\n				<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;member_id={$member[\'member_id\']}\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\' class=\'ipsButton_secondary\'>{$this->lang->words[\'status__viewall\']}</a>\n			</div>\n		<else />\n			<p class=\'ipsBox_container ipsPad\'>{$this->lang->words[\'status_updates_none\']}</p>\n		</if>\n	</div>\n</div>', 'tabStatusUpdates', '$updates=array(), $actions, $member=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('455', '0', 'skin_profile', '<h3 class=\'maintitle\'>{$this->lang->words[\'topics_started\']}</h3>\n<div class=\'ipsBox\'>\n	<div class=\'ipsBox_container\'>\n		{$content}\n	</div>\n</div>', 'tabTopics', '$content', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('456', '0', 'skin_ucp', '<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'m_attach\']}</h3>\n<br />\n<div class=\'row1\'>	\n	<if test=\"hasAttachLimit:|:$info[\'has_limit\'] == 1\">\n		<div id=\'space_allowance\' class=\'general_box\'>\n			<p><strong>{$info[\'attach_space_used\']}</strong></p>\n			<p class=\'progress_bar <if test=\"attachAlmostFull:|:$info[\'full_percent\'] > 80\">limit</if>\' title=\'{$this->lang->words[\'ucp_attach_allowance\']} {$info[\'full_percent\']}% {$this->lang->words[\'ucp_full\']}\'>\n				<span style=\'width: {$info[\'full_percent\']}%\'>{$info[\'full_percent\']}%</span>\n			</p>\n			<p class=\'desc\'>{$info[\'attach_space_count\']}</p>\n		</div>\n	</if>\n	<if test=\"hasPagesTop:|:$pages\">\n		<div class=\'topic_controls\'>\n			{$pages}\n		</div>\n		<br class=\'clear\' />\n	</if>\n	<!-- ATTACHMENTS TABLE -->\n	<form action=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=updateAttachments&amp;do=saveIt\" base=\"public\"}\" id=\"checkBoxForm\" method=\"post\">\n	<table class=\'ipb_table\' summary=\"{$this->lang->words[\'ucp_user_attach\']}\">\n		<tr class=\'header\'>\n				<th scope=\'col\' style=\'width: 2%\'>&nbsp;</th>\n				<th scope=\'col\' style=\'width: 35%\'>{$this->lang->words[\'attach_title\']}</th>\n				<th scope=\'col\' style=\'width: 7%\'>{$this->lang->words[\'attach_hsize\']}</th>\n				<th scope=\'col\' style=\'width: 27%\'>{$this->lang->words[\'attach_topic\']}</th>\n				<th scope=\'col\' class=\'short\' style=\'width: 3%\'><input class=\'input_check\' id=\"checkAllAttachments\" type=\"checkbox\" value=\"{$this->lang->words[\'check_all\']}\" /></th>\n			</tr>\n			<if test=\"hasAttachments:|:count($attachments)\">\n				{parse striping=\"attach\" classes=\"row1,row2\"}\n				<foreach loop=\"attach:$attachments as $idx => $data\">\n					<tr id=\"a{$data[\'attach_id\']}\" class=\'{parse striping=\"attach\"}\'>\n							<td class=\'short altrow\'>\n								<if test=\"attachmentThumbLocation:|:$data[\'attach_thumb_location\']\">\n									<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'_type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'attach_thumb_location\']}\" width=\"30\" height=\"30\" alt=\'{$this->lang->words[\'attached_file\']}\' /></a>\n								<else />\n									<img src=\"{$this->settings[\'mime_img\']}/{$data[\'image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" />\n								</if>\n							</td>\n							<td>\n								<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'_type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\">{$data[\'short_name\']}</a><br />\n								<span class=\"desc\">( {$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']} )</span>\n							</td>\n							<td class=\'short altrow\'>{$data[\'real_size\']}</td>\n							<td>\n								<if test=\"attachmentPost:|:$data[\'attach_rel_id\'] > 0 AND $data[\'attach_rel_module\'] == \'post\'\">\n									<a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;view=findpost&amp;p={$data[\'attach_rel_id\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'ucp_view_org\']}\'>{$data[\'title\']}</a>\n								<else />\n									{$data[\'title\']}\n								</if>\n								<br />\n								<span class=\"desc\">{$data[\'attach_date\']}</span>\n							</td>\n							<td class=\'altrow short\'><input type=\"checkbox\" name=\"attach[{$data[\'attach_id\']}]\" value=\"1\" class=\"input_check checkall\" /></td>\n						</tr>\n				</foreach>\n			<else />\n				<tr>\n					<td colspan=\"5\" class=\'no_messages\'>{$this->lang->words[\'splash_noattach\']}</td>\n				</tr>\n			</if>\n		</table>\n		<if test=\"attachmentMultiDelete:|:count($attachments)\">\n			<div class=\'moderation_bar rounded with_action clear\' id=\'topic_mod\'>\n				<input type=\"hidden\" name=\"authKey\" value=\"{$this->member->form_hash}\" />\n				<input type=\"submit\" value=\"{$this->lang->words[\'attach_delete\']}\" class=\"input_submit alt\" />\n			</div>\n		</if>\n	</form>\n</div>\n<if test=\"hasPagesBottom:|:$pages\">\n	<div class=\'topic_controls\'>\n		{$pages}\n	</div>\n	<br class=\'clear\' />\n</if>\n<script type=\'text/javascript\'>\n	ipb.global.registerCheckAll( \'checkAllAttachments\', \'checkall\' );\n</script>', 'coreAttachments', '$info=\"\",$pages=\"\",$attachments', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('457', '0', 'skin_ucp', '<if test=\"dnameOkMessage:|:$okmessage != \"\"\">\n	<p class=\'message\'>{$okmessage}</p>\n</if>\n<fieldset class=\'row1\'>\n	<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'dname_title\']}</h3>\n	<p class=\'ipsType_pagedesc\'>{$form[\'_lang_string\']}</p>\n	<br />\n	<if test=\"$form[\'_noPerm\']\">\n		<p class=\'message error\'>{$form[\'_noPerm\']}</p>\n	<else />\n		<ul class=\'ipsForm ipsForm_horizontal\'>\n			<li class=\'ipsField\'>\n				<label for=\'displayName\' class=\'ipsField_title\'>{$this->lang->words[\'dname_choose\']}</label>\n				<p class=\'ipsField_content\'>\n					<input class=\'input_text\' type=\"text\" maxlength=\'{$this->settings[\'max_user_name_length\']}\' name=\"displayName\" id=\"displayName\" value=\"{$this->request[\'displayName\']}\" size=\'30\' /><br />\n					<span class=\'desc lighter\'>{$this->lang->words[\'dname_choose2\']}</span>\n				</p>\n			</li>\n			<if test=\"dnameFbUser:|:!$isFB\">\n			<li class=\'ipsField\'>\n				<label for=\'displayPassword\' class=\'ipsField_title\'>{$this->lang->words[\'dname_password\']}</label>\n				<p class=\'ipsField_content\'>\n					<input class=\'input_text\' type=\"password\" name=\"displayPassword\" id=\"displayPassword\" value=\"\" size=\'30\' /> <br />\n					<span class=\'desc lighter\'>{$this->lang->words[\'dname_password2\']}</span>\n				</p>\n			</li>\n			</if>\n		</ul>\n	</if>\n</fieldset>', 'displayNameForm', '$form=array(),$error=\"\",$okmessage=\"\", $isFB=false', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('458', '0', 'skin_ucp', '<script type=\"text/javascript\">\nvar msg = \"$_message\";\n	if ( msg != \"\"){\n		alert(msg);\n	}\n</script>\n<fieldset class=\'row1\'>\n<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'m_email_pass_change\']}</h3>\n<if test=\"hideMessageIfAdmin:|:!$this->memberData[\'g_access_cp\']\"><p class=\'ipsType_pagedesc\'>{$this->lang->words[\'m_email_pass_change_desc\']}</p></if>\n</fieldset>\n<if test=\"emailIsAdmin:|:$this->memberData[\'g_access_cp\']\">\n	<p class=\'message unspecific\'>\n		{$this->lang->words[\'admin_emailpassword\']}\n	</p>\n</if>\n<if test=\"emailIsNotAdmin:|:!$this->memberData[\'g_access_cp\']\">\n	<fieldset class=\'row1\'>\n		<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'change_email_title\']}</h3>\n		<p class=\'ipsType_pagedesc\'>\n			{$txt}\n		</p>\n		<br />\n		<ul class=\'ipsForm ipsForm_horizontal\'>\n			<li class=\'ipsField clearfix\'>\n				<span class=\'ipsField_title\'>{$this->lang->words[\'ce_current\']}</span>\n				<div class=\'ipsField_content\'>\n					<strong style=\'line-height: 1.8\'>{$this->memberData[\'email\']}</strong>\n				</div>\n			</li>\n			<li class=\'ipsField clearfix\'>\n				<label for=\'in_email_1\' class=\'ipsField_title\'>{$this->lang->words[\'ce_new_email\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\"text\" size=\'30\' name=\"in_email_1\" id=\'in_email_1\' class=\'input_text\' value=\"\" />\n				</p>\n			</li>\n			<li class=\'ipsField clearfix\'>\n				<label for=\'in_email_2\' class=\'ipsField_title\'>{$this->lang->words[\'ce_new_email2\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\"text\" size=\'30\' name=\"in_email_2\" id=\'in_email_2\' class=\'input_text\' value=\"\" />\n				</p>\n			</li>\n			<if test=\"passFbUser:|:!$isFB\">\n			<li class=\'ipsField clearfix\'>\n				<label for=\'password\' class=\'ipsField_title\'>{$this->lang->words[\'ec_passy\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\"password\" size=\'30\' id=\'password\' class=\'input_text\' name=\"password\" value=\"\" />\n				</p>\n			</li>\n			</if>\n		</ul>\n	</fieldset>\n	<fieldset class=\'row1\'>\n		<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'account_pass_title\']}</h3>\n		<p class=\'ipsType_pagedesc\'>\n			<if test=\"removeUser:|:! $this->memberData[\'bw_local_password_set\'] AND $this->memberData[\'members_created_remote\']\">\n				{$this->lang->words[\'remote_pass_set\']}\n			<else />\n				{$this->lang->words[\'pass_change_text\']}\n			</if>\n		</p>\n		<br />\n		<ul class=\'ipsForm ipsForm_horizontal\'>\n			<if test=\"removeUser2:|:$this->memberData[\'bw_local_password_set\'] OR ! $this->memberData[\'members_created_remote\']\">\n			<li class=\'ipsField\'>\n				<label for=\'current_pass\' class=\'ipsField_title\'>{$this->lang->words[\'account_pass_old\']}</label>\n				<p class=\'ipsField_content\'>\n					<input type=\"password\" name=\"current_pass\" value=\"\" id=\'current_pass\' class=\'input_text\' size=\'30\' />\n				</p>\n			</li>\n			</if>\n			<li class=\'ipsField\'>\n				<label for=\'new_pass_1\' class=\'ipsField_title\'><if test=\"removeUser3:|:$this->memberData[\'bw_local_password_set\'] OR ! $this->memberData[\'members_created_remote\']\">{$this->lang->words[\'account_pass_new\']}<else />{$this->lang->words[\'enter_pass_remote1\']}</if></label>\n				<p class=\'ipsField_content\'>\n					<input type=\"password\" name=\"new_pass_1\" value=\"\" id=\'new_pass_1\' class=\'input_text\' size=\'30\' />\n				</p>\n			</li>\n			<li class=\'ipsField\'>\n				<label for=\'new_pass_2\' class=\'ipsField_title\'><if test=\"removeUser4:|:$this->memberData[\'bw_local_password_set\'] OR ! $this->memberData[\'members_created_remote\']\">{$this->lang->words[\'account_pass_new2\']}<else />{$this->lang->words[\'enter_pass_remote2\']}</if></label>\n				<p class=\'ipsField_content\'>\n					<input type=\"password\" name=\"new_pass_2\" value=\"\" id=\'new_pass_2\' class=\'input_text\' size=\'30\' />\n				</p>\n			</li>\n		</ul>\n	</fieldset>\n</if>', 'emailPasswordChangeForm', '$txt, $_message, $isFB=false', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('459', '0', 'skin_ucp', '<select name=\"{$name}\" class=\'input_select\'>\n	{$options}\n</select>', 'field_dropdown', '$name=\"\",$options=\"\"', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('460', '0', 'skin_ucp', '<li class=\'custom\'>\n	<label for=\'field_{$id}\' class=\'ipsSettings_fieldtitle\'>{$title}</label>\n	<if test=\"stristr($content, \'radio\') || stristr($content, \'checkbox\')\">\n		<p class=\'wrap\'>{$content}</p>\n		<if test=\"cfieldDesc:|:$desc\"><span class=\'desc\'>{$desc}</span></if>\n	<else />\n		{$content}\n		<if test=\"cfieldDesc:|:$desc\"><br /><span class=\'desc\'>{$desc}</span></if>\n	</if>\n	\n</li>', 'field_entry', '$title=\"\",$desc=\"\",$content=\"\",$id=\"\"', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('461', '0', 'skin_ucp', '<textarea cols=\"80\" rows=\"5\" wrap=\"soft\" name=\"$name\" class=\'input_text\'>{$value}</textarea>', 'field_textarea', '$name=\"\",$value=\"\"', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('462', '0', 'skin_ucp', '<input type=\"text\" size=\"50\" name=\"{$name}\" value=\'{$value}\' class=\'input_text\' />', 'field_textinput', '$name=\"\",$value=\"\"', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('463', '0', 'skin_ucp', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n<if test=\"fbMismatch:|:$fbuid AND $linkedMemberData[\'member_id\'] AND $linkedMemberData[\'member_id\'] != $this->memberData[\'member_id\']\">\n	<!-- currently logged in FB user is linked to a different account -->\n	<div class=\'message error\'>\n		<strong>{$this->lang->words[\'fb_connect_mismatch\']}</strong>\n		<p>{$this->lang->words[\'fb_connect_mismatch_desc\']}</p>\n	</div>\n<else />\n	<if test=\"! $fbUserData[\'id\']\">\n		<div id=\'fbUserBox\'>\n			<p class=\'message\'>{$this->lang->words[\'fb_config\']}</p>\n			<br />\n			<br />\n			<a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"\" /></a>\n		</div>\n	<else />\n		<div>\n			<fieldset class=\'ipsPad_half row2\'>\n				<div class=\'left ipsUserPhoto\' style=\'margin-right:4px;\'>\n					<img src=\"{$fbUserData[\'pic_square\']}\" alt=\"\" />\n				</div>\n				<div class=\'desc\'>\n				{$this->lang->words[\'fb_logged_in_as\']} <strong>{$fbUserData[\'name\']}</strong>\n				<if test=\"fbShowStatus:|:is_array($fbUserData[\'status\']) AND $fbUserData[\'status\'][\'message\']\">\n					<br /><br />{$fbUserData[\'status\'][\'message\']}\n				</if>\n				</div>\n			</fieldset>\n			<br />\n			<fieldset class=\'row1\'>\n				<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'fb_sync_options\']}</h3>\n				<ul>\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_s_pic\' value=\'1\' <if test=\"fbSyncPic:|:$this->memberData[\'fbc_s_pic\'] > 0\">checked=\'checked\'</if> id=\'fbc_s_pic\' /><label for=\'fbc_s_pic\'>{$this->lang->words[\'fb_sync_photo\']}</label><br />\n						<span class=\'desc lighter\'>{$this->lang->words[\'fb_sync_photo_info\']}</span>\n					</li>\n					<if test=\"canUpdateStatus:|:$this->memberData[\'can_updated_status\']\">\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_s_status\' value=\'1\' <if test=\"fbSyncStatus:|:$this->memberData[\'fbc_s_status\'] > 0\">checked=\'checked\'</if> id=\'fbc_s_status\' /><label for=\'fbc_s_status\'>{$this->lang->words[\'fb_sync_status\']}</label>\n					</li>\n					</if>\n					<if test=\"statusImportGroup:|: ! $this->memberData[\'gbw_no_status_import\']\">\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_si_status\' value=\'1\' <if test=\"fbSyncStatus:|:$this->memberData[\'fbc_si_status\'] > 0\">checked=\'checked\'</if> id=\'fbc_si_status\' /><label for=\'fbc_si_status\'>{$this->lang->words[\'fb_sync_status_in\']}</label>\n					</li>\n					</if>\n				</ul>\n				<p class=\'desc\'>\n					{$this->lang->words[\'fb_last_syncd\']}\n					<if test=\"fbLastSync:|:$this->memberData[\'fb_lastsync\']\">\n						{parse date=\"$this->memberData[\'fb_lastsync\']\" format=\"long\"}\n					<else />\n						{$this->lang->words[\'fb_never\']}\n					</if>\n				</p>\n				<br />\n				<p><input type=\'submit\' class=\'input_submit alt\' id=\'fbc_sync\' value=\'{$this->lang->words[\'fb_sync_now\']}\' /></p>\n			</fieldset>\n			<br />\n			<fieldset class=\'row1\'>\n				<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'fbp_title\']}</h3>\n				<ul>\n					<li class=\'field checkbox\'>\n						<img src=\"{$this->settings[\'img_url\']}/<if test=\"pImgOA:|:$perms[\'offline_access\']\">accept.png<else />cross.png</if>\" style=\'vertical-align:top\' alt=\'\' />&nbsp;{$this->lang->words[\'fbp_offline_access\']}\n						<if test=\"pCheckOA:|:!$perms[\'offline_access\']\">&nbsp;(<fb:prompt-permission perms=\"offline_access\">{$this->lang->words[\'fbp_request\']}</fb:prompt-permission>)</if>\n						<p class=\'desc\' style=\'left:0px\'>{$this->lang->words[\'fbp_offline_access_desc\']}</p>\n					</li>\n					<li class=\'field checkbox\'>\n						<img src=\"{$this->settings[\'img_url\']}/<if test=\"pImgE:|:$perms[\'email\']\">accept.png<else />cross.png</if>\" style=\'vertical-align:top\' alt=\'\' />&nbsp;{$this->lang->words[\'fbp_email_access\']}\n						<if test=\"pCheckE:|:!$perms[\'email\']\">&nbsp;(<fb:prompt-permission perms=\"email\">{$this->lang->words[\'fbp_request\']}</fb:prompt-permission>)</if>\n						<p class=\'desc\' style=\'left:0px\'>{$this->lang->words[\'fbp_email_access_desc\']}</p>\n					</li>\n					<li class=\'field checkbox\'>\n						<img src=\"{$this->settings[\'img_url\']}/<if test=\"pImgPS:|:$perms[\'publish_stream\']\">accept.png<else />cross.png</if>\" style=\'vertical-align:top\' alt=\'\' />&nbsp;{$this->lang->words[\'fbp_publish_stream\']}\n						<if test=\"pCheckPS:|:!$perms[\'publish_stream\']\">&nbsp;(<fb:prompt-permission perms=\"publish_stream\">{$this->lang->words[\'fbp_request\']}</fb:prompt-permission>)</if>\n						<p class=\'desc\' style=\'left:0px\'>{$this->lang->words[\'fbp_publish_stream_desc\']}</p>\n					</li>\n					<li class=\'field checkbox\'>\n						<img src=\"{$this->settings[\'img_url\']}/<if test=\"pImgRS:|:$perms[\'read_stream\']\">accept.png<else />cross.png</if>\" style=\'vertical-align:top\' alt=\'\' />&nbsp;{$this->lang->words[\'fbp_read_stream\']}\n						<if test=\"pCheckRS:|:!$perms[\'read_stream\']\">&nbsp;(<fb:prompt-permission perms=\"read_stream\">{$this->lang->words[\'fbp_request\']}</fb:prompt-permission>)</if>\n						<p class=\'desc\' style=\'left:0px\'>{$this->lang->words[\'fbp_read_stream_desc\']}</p>\n					</li>\n				</ul>\n			</fieldset>\n			<fieldset class=\'row1\'>\n				<if test=\"fbPassword:|:! $this->memberData[\'bw_local_password_set\'] AND $this->memberData[\'members_created_remote\']\">\n					<div class=\'message\'>\n						<strong>{$this->lang->words[\'remote_no_password\']}</strong>\n						<p>{$this->lang->words[\'remote_no_password_1\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=password\" base=\"public\"}\'>{$this->lang->words[\'remote_no_password_2\']}</a>\n						</p>\n					</div>\n					<br />\n				</if>\n				<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'fb_disassociate\']}</h3>\n				<p class=\'desc\'>{$this->lang->words[\'fb_disassociate_desc\']}</p>\n				<if test=\"fbDefaultEmail:|:strstr( $this->memberData[\'email\'], \'@proxymail.facebook.com\' )\">\n					<div class=\'message\'>\n						<strong>{$this->lang->words[\'fb_using_email\']}</strong>\n						<p>{$this->lang->words[\'fb_disassociate_info_1\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=email\" base=\"public\"}\'>{$this->lang->words[\'fb_disassociate_info_2\']}</a> {$this->lang->words[\'fb_disassociate_info_3\']}\n						</p>\n					</div>\n					<br />\n				</if>\n				<br />\n				<p><input type=\'button\' class=\'input_submit alt\' id=\'fbc_remove\' value=\'{$this->lang->words[\'fb_disassociate_now\']}\' /></p>\n				<br />\n			</fieldset>\n		</div>\n		<script type=\"text/javascript\">\n		$(\'fbc_remove\').observe( \'click\', usercp_remove );\n		function usercp_remove(){\n			window.location = ipb.vars[\'base_url\'] + \'app=core&module=usercp&tab=core&area=facebookRemove&do=custom&secure_key=\' + ipb.vars[\'secure_hash\'];\n		}\n		</script>\n	</if>\n</if>', 'membersFacebookConnect', '$fbuid, $fbUserData, $linkedMemberData, $perms', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('464', '0', 'skin_ucp', '<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.templates[\'autocomplete_wrap\'] = new Template(\"<ul id=\'#{id}\' class=\'ipbmenu_content\' style=\'width: 250px;\'></ul>\");\n	ipb.templates[\'autocomplete_item\'] = new Template(\"<li id=\'#{id}\'><img src=\'#{img}\' alt=\'\' width=\'#{img_w}\' height=\'#{img_h}\' />&nbsp;&nbsp;#{itemvalue}</li>\");\n//]]>\n</script>\n	<!--<h2 class=\'ipsType_subtitle\'>{$this->lang->words[\'ucp_global_prefs\']}</h2>-->\n	<div class=\'ipsPad\'>\n		<input type=\'checkbox\' name=\'donot_view_sigs\' id=\'donot_view_sigs\' value=\'1\' <if test=\"canSee:|: ! $this->memberData[\'view_sigs\']\">checked=\'checked\'</if> />\n		<label class=\'desc\' for=\'donot_view_sigs\'>{$this->lang->words[\'ucp_global_prefs_desc\']}</label>\n	</div>\n	<br />\n	<h2 class=\'ipsType_subtitle\'>{$this->lang->words[\'mi5_title\']}</h2>\n	<br />\n	<table class=\'ipb_table\' summary=\"{$this->lang->words[\'ucp_ignored_users\']}\">\n		<tr class=\'header\'>\n			<th scope=\'col\' width=\"30%\">{$this->lang->words[\'mi5_name\']}</th>\n			<th scope=\'col\' width=\"30%\">{$this->lang->words[\'mi5_group\']}</th>\n			<th scope=\'col\' class=\'short\'>{$this->lang->words[\'ucp_ignore_posts\']}</th>\n			<th scope=\'col\' class=\'short\'>{$this->lang->words[\'ucp_ignore_sigs\']}</th>\n			<th scope=\'col\' class=\'short\'>{$this->lang->words[\'ucp_ignore_msgs\']}</th>\n			<if test=\"hasChat:|:IPSLib::appIsInstalled(\'ipchat\')\"><th scope=\'col\' class=\'short\'>{$this->lang->words[\'ucp_ignore_chats\']}</th></if>\n			<th scope=\'col\' class=\'short\'>&nbsp;</th>\n		</tr>\n		{parse striping=\"members\" classes=\"row1,row2\"}\n		<if test=\"count( $members )\">\n			<foreach loop=\"members:$members as $member\">\n				<tr class=\'{parse striping=\"members\"}\'>\n					<td>\n						<img src=\'{$member[\'pp_small_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini left\' style=\'margin-right: 5px\' />\n						<strong>{parse template=\"userHoverCard\" group=\"global\" params=\"$member\"}</strong><br />\n						<span class=\'desc lighter\'>{$this->lang->words[\'m_joined\']} {parse date=\"$member[\'joined\']\" format=\"joined\"}</span>\n					</td>\n					<td>{$member[\'g_title\']}</td>\n					<td class=\'short\'>\n						<if test=\"ignoreMemberTopics:|:$member[\'ignoreData\'][\'ignore_topics\'] == 1\">\n							<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=topics\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:red\'>{$this->lang->words[\'ucp_hide_disallow\']}</span></a>\n						<else />\n							<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=topics\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:green\'>{$this->lang->words[\'ucp_hide_allow\']}</span></a>\n						</if>\n					</td>\n					<td class=\'short\'>\n						<if test=\"ignoreGlobal:|:! $this->memberData[\'view_sigs\']\">\n							<span class=\'desc\'>{$this->lang->words[\'ucp_ignore_sigs_glb\']}</span>\n						<else />\n							<if test=\"ignoreMemberSigs:|:$member[\'ignoreData\'][\'ignore_signatures\'] == 1\">\n								<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=signatures\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:red\'>{$this->lang->words[\'ucp_hide_disallow\']}</span></a>\n							<else />\n								<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=signatures\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:green\'>{$this->lang->words[\'ucp_hide_allow\']}</span></a>\n							</if>\n						</if>\n					</td>\n					<td class=\'short\'>\n						<if test=\"ignoreMemberPms:|:$member[\'ignoreData\'][\'ignore_messages\'] == 1\">\n							<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=messages\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:red\'>{$this->lang->words[\'ucp_hide_disallow_msg\']}</span></a>\n						<else />\n							<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=messages\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:green\'>{$this->lang->words[\'ucp_hide_allow_msg\']}</span></a>\n						</if>\n					</td>\n					<if test=\"hasChatRow:|:IPSLib::appIsInstalled(\'ipchat\')\">\n						<td class=\'short\'>\n							<if test=\"ignoreUserchats:|:$member[\'ignoreData\'][\'ignore_chats\'] == 1\">\n								<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=chats\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:red\'>{$this->lang->words[\'ucp_hide_disallow_msg\']}</span></a>\n							<else />\n								<a class=\'ipsButton_secondary\' href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=chats\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\"><span style=\'color:green\'>{$this->lang->words[\'ucp_hide_allow_msg\']}</span></a>\n							</if>\n						</td>\n					</if>\n					<td class=\'short\'><a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=removeIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}\" base=\"public\"}\" class=\'ipsButton_secondary\' class=\'delete_ignored\'>{$this->lang->words[\'mi5_remove\']}</a></td>\n				</tr>\n			</foreach>\n		<else />\n			<tr>\n				<td colspan=\'<if test=\"hasChatNone:|:IPSLib::appIsInstalled(\'ipchat\')\">7<else />6</if>\' class=\'no_messages desc\'>{$this->lang->words[\'no_ignored_users\']}</td>\n			</tr>\n		</if>\n	</table>\n	\n	<br />\n	<div class=\'row2 ipsPad\'>\n		<h3 class=\'ipsType_subtitle\' style=\'margin-bottom: 15px\'>{$this->lang->words[\'mi5_addem\']}</h3>\n		<input type=\"text\" class=\'input_text\' size=\'40\' name=\"newbox_1\" id=\"newbox_1\" value=\"{$this->request[\'newbox_1\']}\" />\n		 &nbsp;&nbsp;<strong>{$this->lang->words[\'ucp_add_prefix\']}</strong>&nbsp;\n		<input type=\'checkbox\' class=\'input_check\' name=\'ignore_topics\' id=\'ignore_topics\' value=\'1\' />\n		<label class=\'desc\' for=\'ignore_topics\'>{$this->lang->words[\'ucp_ignore_posts\']}</label>\n		&nbsp;&nbsp;\n		<input type=\'checkbox\' class=\'input_check\' name=\'ignore_signatures\' id=\'ignore_signatures\' value=\'1\' />\n		<label class=\'desc\' for=\'ignore_signatures\'>{$this->lang->words[\'ucp_ignore_sigs\']}</label>\n		&nbsp;&nbsp;\n		<input type=\'checkbox\' class=\'input_check\' name=\'ignore_messages\' id=\'ignore_messages\' value=\'1\' />\n		<label class=\'desc\' for=\'ignore_messages\'>{$this->lang->words[\'ucp_ignore_pc\']}</label>\n		<if test=\"hasChatRow:|:IPSLib::appIsInstalled(\'ipchat\')\">\n			&nbsp;&nbsp;\n			<input type=\'checkbox\' class=\'input_check\' name=\'ignore_chats\' id=\'ignore_chats\' value=\'1\' />\n			<label class=\'desc\' for=\'ignore_chats\'>{$this->lang->words[\'ucp_ignore_chats\']}</label>\n		</if>\n	</div>\n	\n<script type=\"text/javascript\">\n	$(\'newbox_1\').defaultize( \"{$this->lang->words[\'ucp_members_name\']}\" );\n	\n	ipb.delegate.register(\'.delete_ignored\', confirmIgnoredDelete);\n	\n	var confirmIgnoredDelete = function(e, elem){\n		if( !confirm(\"{$this->lang->words[\'ignore_del_areusure\']}\") ){\n			Event.stop(e);\n		}\n	};\n	\n	document.observe(\"dom:loaded\", function(){\n		var url = ipb.vars[\'base_url\'] + \'app=core&module=ajax&section=findnames&do=get-member-names&secure_key=\' + ipb.vars[\'secure_hash\'] + \'&name=\';\n		new ipb.Autocomplete( $(\'newbox_1\'), { multibox: false, url: url, templates: { wrap: ipb.templates[\'autocomplete_wrap\'], item: ipb.templates[\'autocomplete_item\'] } } );\n	});\n</script>', 'membersIgnoredUsersForm', '$members', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('465', '0', 'skin_ucp', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/3rd_party/colorpicker/jscolor.js\'></script>\n<h3 class=\'ipsType_subtitle ipsSettings_pagetitle\'>{$this->lang->words[\'ucp_cust_bg\']}</h3>\n<p class=\'ipsType_pagedesc\'>{$this->lang->words[\'ucp_customize_msg\']}</p>\n<br />\n<if test=\"$input[\'_preview\']\">\n	<fieldset class=\'ipsSettings_section\'>\n		<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_cust_bg_preview\']}</h3>\n		<div>\n			<div style=\'width:98%; height: 100px; background-image:url(\"{$input[\'_preview\']}\");<if test=\"!$options[\'bg_tile\']\">background-repeat:no-repeat</if>\'>&nbsp;</div>\n		</div>\n	</fieldset>\n</if>\n<fieldset class=\'ipsSettings_section\'>\n	<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_cust_remove_t\']}</h3>\n	<div>\n		<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=customize&amp;do=save&amp;secure_hash={$this->member->form_hash}&amp;bg_nix=1\" base=\"public\"}\" class=\"ipsButton_secondary\">{$this->lang->words[\'ucp_cust_remove\']}</a>\n	</div>\n</fieldset>\n<if test=\"$this->memberData[\'gbw_allow_url_bgimage\'] OR $this->memberData[\'gbw_allow_upload_bgimage\']\">\n	<fieldset class=\'ipsSettings_section\'>\n		<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_cust_bg_title\']}</h3>\n		<div>\n			<ul>\n				<if test=\"$this->memberData[\'gbw_allow_url_bgimage\']\">\n					<li>\n						<label for=\'bg_img\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'ucp_cust_bg_image\']}</label>\n						<input type=\"text\" name=\"bg_url\" id=\'bg_url\' class=\'input_text\' size=\'50\' value=\"{$input[\'bg_url\']}\" /><br />\n						<p class=\'desc lighter\'>{$this->lang->words[\'ucp_cust_bg_image_img_d\']}</p>\n					</li>\n				</if>\n				<if test=\"$this->memberData[\'gbw_allow_upload_bgimage\']\">\n					<li>\n						<label for=\'bg_img\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'ucp_cust_bg_image_upl\']}</label>\n						<input type=\"file\" name=\"bg_upload\" id=\'bg_upload\' value=\"\" size=\"70\" /><br />\n						<p class=\'desc lighter\'>{parse expression=\"sprintf($this->lang->words[\'ucp_cust_bg_image_upl_d\'], intval($this->memberData[\'g_max_bgimg_upload\']) ? intval($this->memberData[\'g_max_bgimg_upload\']) : $this->lang->words[\'pf__unlimited\'] )\"}</p>\n					</li>\n				</if>\n			</ul>\n		</div>\n	</fieldset>\n	<fieldset class=\'ipsSettings_section\'>\n		<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'background_options\']}</h3>\n		<div>\n			<ul>\n				<if test=\"$this->memberData[\'gbw_allow_url_bgimage\'] OR $this->memberData[\'gbw_allow_upload_bgimage\']\">\n					<li>\n						<input type=\"checkbox\" name=\"bg_tile\" id=\'bg_tile\' class=\'input_check\' value=\"1\" <if test=\"$input[\'bg_tile\']\">checked=\'checked\'</if>/> &nbsp;<label for=\'bg_tile\'>{$this->lang->words[\'ucp_cust_bg_tile\']}</label>\n					</li>\n				</if>\n				<li>\n					<label for=\'bg_color\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'ucp_cust_bg_color\']} </label>\n					#<input type=\"text\" name=\"bg_color\" id=\'bg_color\' class=\'input_text color\' size=\'10\' value=\"{$input[\'bg_color\']}\" />\n					<p class=\"desc lighter\">{$this->lang->words[\'ucp_cust_bg_color_d\']}</p>\n				</li>\n			</ul>\n		</div>\n	</fieldset>\n</if>', 'membersProfileCustomize', '$options, $input, $errors', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('466', '0', 'skin_ucp', '<php>$this->hasOpenID = false;</php>\n<foreach loop=\"loginmethods:$this->cache->getCache(\'login_methods\') as $method\">\n	<if test=\"hasOpenid:|:$method[\'login_folder_name\'] == \'openid\'\">\n		<if test=\"setHasOpenid:|:$this->hasOpenID = true\"></if>\n	</if>\n</foreach>\n<h2 class=\'ipsType_subtitle ipsSettings_pagetitle\'>{$this->lang->words[\'general_account_settings\']}</h2>\n<div class=\'ipsSettings\'>\n	<if test=\"weDoHaveOpenid:|:$this->hasOpenID\">\n		<fieldset class=\'ipsSettings_section\'>\n			<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'identity_url_h3\']}</h3>\n			<div>\n				<ul>\n					<li>\n						<label for=\'identity_url\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'identity_url\']}</label><input class=\'input_text\' size=\'30\' type=\"text\" name=\"identity_url\" id=\"identity_url\" value=\"{$this->memberData[\'identity_url\']}\" /> <br />\n						<span class=\'desc lighter\'>{$this->lang->words[\'identity_url_desc\']}</span>\n					</li>\n				</ul>\n			</div>\n		</fieldset>\n	</if>\n	<if test=\"canUploadPhoto:|:IPSMember::canUploadPhoto( $this->memberData )\">\n		<fieldset class=\'ipsSettings_section\'>\n			<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_photo_title\']}</h3>\n			<div>\n				<a data-clicklaunch=\"launchPhotoEditor\" href=\"{parse url=\"app=members&amp;module=profile&amp;section=photo\" base=\"public\"}\" class=\'ipsButton_secondary\'>{$this->lang->words[\'ucp_photo_change\']}</a>\n			</div>\n		</fieldset>\n	</if>\n	\n	<fieldset class=\'ipsSettings_section\'>\n		<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'settings_time\']}</h3>\n		<div>\n			<ul class=\'ipsForm ipsForm_horizontal\'>\n				<li class=\'ipsField\'>\n					<label for=\'timezone\'>{$this->lang->words[\'ucp_timzeone\']}</label>\n					<select name=\'timeZone\' id=\'timezone\' class=\'input_select\'>\n					<foreach loop=\"timezones:$times as $off => $words\">\n						<option value=\'{$off}\' <if test=\"isOurTimezone:|:$off == $this->memberData[\'time_offset\']\"> selected=\"selected\"</if>>{$words}</option>\n					</foreach>\n					</select><br />\n					<span class=\'desc lighter\'>{$this->lang->words[\'settings_time_txt2\']} {parse date=\"\" format=\"LONG\" relative=\"false\"}</span>\n				</li>\n				<if test=\"$this->settings[\'time_dst_auto_correction\']\">\n					<li>\n						<if test=\"dstError:|:$this->request[\'dsterror\'] == 1\">\n							{$this->lang->words[\'dst_error\']}\n						</if>\n						<input type=\'checkbox\' class=\'input_check\' id=\'dst\' name=\"dstCheck\" onclick=\'toggle_dst()\' value=\"1\"<if test=\"doAutoDst:|:$this->memberData[\'members_auto_dst\']\"> checked=\"checked\"</if>/> &nbsp;<label for=\'dst\'>{$this->lang->words[\'dst_correction_title\']}</label>\n					</li>\n					<li id=\'dst-manual\'>\n						<input type=\'checkbox\' class=\'input_check\' id=\'dstManual\' name=\"dstOption\" value=\"1\"<if test=\"doManualDst:|:$this->memberData[\'dst_in_use\']\"> checked=\"checked\"</if>/> &nbsp;<label for=\'dstManual\'>{$this->lang->words[\'ucp_dst_now\']}</label>\n					</li>\n				<else />\n					<li>\n						<input type=\'checkbox\' class=\'input_check\' id=\'dstManual\' name=\"dstOption\" value=\"1\"<if test=\"doManualDst:|:$this->memberData[\'dst_in_use\']\"> checked=\"checked\"</if>/> &nbsp;<label for=\'dstManual\'>{$this->lang->words[\'ucp_dst_now\']}</label><br />\n						<span class=\'desc lighter\'>{$this->lang->words[\'ucp_dst_effect\']}</span>\n					</li>\n				</if>\n			</ul>\n		</div>\n	</fieldset>\n\n	<fieldset class=\'ipsSettings_section\'>\n		<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_comments\']}</h3>\n		<div>\n			<ul>\n				<li>\n					<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_comments\' value=\'1\' <if test=\"showComments:|:$this->memberData[\'pp_setting_count_comments\'] > 0\">checked=\'checked\'</if> id=\'comments_enable\' /> &nbsp;<label for=\'comments_enable\'>{$this->lang->words[\'ucp_enable_comments\']}</label>\n				</li>\n				<!-- proposing removal -->\n				<li id=\'approve_comments\'>\n					<input class=\'input_check\' type=\'checkbox\' value=\'1\'  name=\'pp_setting_moderate_comments\' id=\'pp_setting_moderate_comments\' <if test=\"yesModComments:|:$this->memberData[\'pp_setting_moderate_comments\']\">checked=\"checked\"</if> /> &nbsp;<label for=\'pp_setting_moderate_comments\'>{$this->lang->words[\'op_dd_enabled\']}</label>\n				</li>\n				<li>\n					<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_visitors\' value=\'1\' <if test=\"showLastVisitors:|:$this->memberData[\'pp_setting_count_visitors\'] > 0\">checked=\'checked\'</if> id=\'pp_latest_visitors\' /> &nbsp;<label for=\'pp_latest_visitors\'>{$this->lang->words[\'ucp_show_x_latest\']}</label>\n				</li>\n			</ul>\n		</div>\n	</fieldset>\n	<if test=\"friendsEnabled:|:$this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n		<fieldset class=\'ipsSettings_section\'>\n			<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'ucp_friends\']}</h3>\n			<div>\n				<ul>\n					<li>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_friends\' value=\'1\' <if test=\"showFriends:|:$this->memberData[\'pp_setting_count_friends\'] > 0\">checked=\'checked\'</if> id=\'friends_enable\' /> &nbsp;<label for=\'friends_enable\'>{$this->lang->words[\'ucp_show_friends_profile\']}</label>\n					</li>\n					<li>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_moderate_friends\' id=\'pp_setting_moderate_friends\' <if test=\"yesModFriends:|:$this->memberData[\'pp_setting_moderate_friends\']\">checked=\"checked\"</if> /> &nbsp;<label for=\'pp_setting_moderate_friends\'>{$this->lang->words[\'ucp_friend_approve\']}</label>\n					</li>\n				</ul>\n			</div>\n		</fieldset>\n	</if>\n	<if test=\"showProfileInfo:|:($day && $mon && $year) || ($this->settings[\'post_titlechange\'] && ($this->memberData[\'posts\'] >= $this->settings[\'post_titlechange\']))\">\n		<fieldset class=\'ipsSettings_section\'>\n			<h3 class=\'ipsSettings_sectiontitle\'>{$this->lang->words[\'profile_information\']}</h3>\n			<div>\n				<ul>\n					<li><a href=\'#\' class=\'ipsButton_secondary\' id=\'edit_aboutme\'>{$this->lang->words[\'edit_my_about_me\']}</a></li>\n				</ul>\n				<if test=\"changeMemberTitle:|:$this->settings[\'post_titlechange\'] && ($this->memberData[\'posts\'] >= $this->settings[\'post_titlechange\'])\">\n					<br />\n					<ul>\n						<li>\n							<label for=\'member_title\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'member_title\']}</label>\n							<input type=\'text\' class=\'input_text\' size=\'40\' id=\'member_title\' name=\'member_title\' value=\'{$this->memberData[\'title\']}\' />\n							<br />\n							<span class=\'desc\'>{$this->lang->words[\'member_title_desc\']}</span>\n						</li>\n					</ul>\n				</if>\n				<if test=\"birthdayFields:|:$day AND $mon AND $year\">\n					<br />\n					<ul>\n						<li>\n							<label for=\'birthday\' class=\'ipsSettings_fieldtitle\'>{$this->lang->words[\'ucp_birthday_select\']}</label>\n							<select name=\"month\">&nbsp;\n								<foreach loop=\"months:$mon as $m\">\n									<option value=\'{$m[0]}\'<if test=\"monthSelected:|:$m[0] == $this->memberData[\'bday_month\']\"> selected=\"selected\"</if>>{$m[1]}</option>\n								</foreach>\n							</select>			\n							<select name=\"day\">&nbsp;\n								<foreach loop=\"days:$day as $d\">\n									<option value=\'{$d[0]}\'<if test=\"daySelected:|:$d[0] == $this->memberData[\'bday_day\']\"> selected=\"selected\"</if>>{$d[1]}</option>\n								</foreach>\n							</select> \n							<select name=\"year\">&nbsp;\n								<foreach loop=\"years:$year as $y\">\n									<option value=\'{$y[0]}\'<if test=\"yearSelected:|:$y[0] == $this->memberData[\'bday_year\']\"> selected=\"selected\"</if>>{$y[1]}</option>\n								</foreach>\n							</select> <br />\n							<span class=\'desc\'>{$this->lang->words[\'ucp_birthday_optional\']}</span>\n						</li>\n					</ul>\n				</if>\n			</div>\n		</fieldset>\n	</if>\n	\n	<if test=\"count( $custom_fields )\">\n		<foreach loop=\"$custom_fields as $cgroup => $cfields\">\n			<if test=\"count( $cfields )\">\n				<fieldset class=\'ipsSettings_section\'>\n					<h3 class=\'ipsSettings_sectiontitle\'>{$group_titles[ $cgroup ]}</h3>\n					<div>\n						<ul>\n							<foreach loop=\"$cfields as $fid => $cfield\">\n								{$cfield[\'field\']}\n							</foreach>\n						</ul>\n					</div>\n				</fieldset>\n			</if>\n		</foreach>\n	</if>\n	\n	<div id=\'aboutme_editor\' style=\'display: none\'>\n		<h3>{$this->lang->words[\'cp_edit_aboutme\']}</h3>\n		<div>\n			{$amEditor}\n		</div>\n		<div class=\'ipsForm_submit\' style=\'margin-top: 0;\'>\n			<a href=\'#\' id=\'close_aboutme_editor\' class=\'ipsButton\'>{$this->lang->words[\'finish_aboutme_edit\']}</a>\n		</div>\n	</div>\n	<if test=\"requiredCfields:|:$required_output\">\n		<fieldset class=\'{parse striping=\"usercp\"}\'>\n			<h3>{$this->lang->words[\'ucp_required_info\']}</h3>\n			<ul>\n				{$required_output}\n			</ul>\n		</fieldset>\n	</if>\n	<if test=\"optionalCfields:|:$optional_output\">\n		<fieldset class=\'{parse striping=\"usercp\"}\'>\n			<h3>{$this->lang->words[\'ucp_other_info\']}</h3>\n			<ul>\n				{$optional_output}\n			</ul>\n		</fieldset>\n	</if>\n</div>\n<script type=\"text/javascript\">\n//<![CDATA[\nfunction toggle_dst()\n{\n	if ( $( \'dst\' ) )\n	{\n		if ( $( \'dst\' ).checked ){\n			$( \'dst-manual\' ).style.display = \'none\';\n		} else {\n			$( \'dst-manual\' ).style.display = \'block\';\n		}\n	}\n}\ntoggle_dst();\n//]]>\n</script>', 'membersProfileForm', '$custom_fields=\'\',$group_titles=\'\',$day=\'\',$mon=\'\',$year=\'\', $amEditor=\'\', $times=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('467', '0', 'skin_ucp', '<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'cp_current_sig\']}</h3>\n<div class=\'row1\'>{$signature}</div>\n<br />\n<input type=\'hidden\' name=\'removeattachid\' value=\'0\' />\n{parse striping=\"usercp\" classes=\"row1,row2\"}\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'cp_edit_sig\']}</h3>\n	<if test=\"hasSignatureLimits:|:$this->memberData[\'g_signature_limits\']\">\n		<div class=\'ipsType_pagedesc\'>\n			{$this->lang->words[\'sig_restrictions_contain\']}<br />\n			<ul class=\'ipsList_inline\' style=\'display: inline\'>\n				<if test=\"$sig_restrictions[1] !== \'\'\">\n					<li>&bull; {parse expression=\"sprintf( $this->lang->words[\'sig_max_imagesr\'], $sig_restrictions[1] )\"}</li>\n				<else />\n					<li>&bull; {$this->lang->words[\'sig_max_imagesr_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[2] !== \'\' || $sig_restrictions[3] !== \'\'\">\n					<li>&bull; {parse expression=\"sprintf( $this->lang->words[\'sig_max_imgsize\'], $sig_restrictions[2], $sig_restrictions[3] )\"}</li>\n				<else />\n					<li>&bull; {$this->lang->words[\'sig_max_imgsize_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[4] !== \'\'\">\n					<li>&bull; {parse expression=\"sprintf( $this->lang->words[\'sig_max_urls\'], $sig_restrictions[4] )\"}</li>\n				<else />\n					<li>&bull; {$this->lang->words[\'sig_max_urls_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[5] !== \'\'\">\n					<li>&bull; {parse expression=\"sprintf( $this->lang->words[\'sig_max_lines\'], $sig_restrictions[5] )\"}</li>\n				<else />\n					<li>&bull; {$this->lang->words[\'sig_max_lines_nl\']}</li>\n				</if>\n			</ul>\n		</div><br />\n	</if>\n	<div>\n		{$editor_html}\n	</div>\n</fieldset>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}', 'membersSignatureForm', '$editor_html=\"\",$sig_restrictions=array(),$signature=\'\'', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('468', '0', 'skin_ucp', '<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'cp_edit_sig\']}</h3>\n	<br />\n	<if test=\"$form[\'_noPerm\']\">\n		<p class=\'message error\'>{$form[\'_noPerm\']}</p>\n	</if>\n</fieldset>', 'membersSignatureFormError', '$form', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('469', '0', 'skin_ucp', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n<if test=\"! $isConnected\">\n<div>\n	<p class=\'message\'>{$this->lang->words[\'twitter_config\']}</p>\n	<br />\n	<br />\n	<a href=\"{$this->settings[\'_original_base_url\']}/interface/twitter/index.php\"><img src=\"{$this->settings[\'img_url\']}/twitter_connect.png\" alt=\"\" /></a>\n	<br />\n</div>\n<else />\n<div>\n	<div class=\'ipsPad row2 clearfix\'>\n		<if test=\"tcHasPic:|:$twitterUser[\'profile_image_url\']\">	\n			<img src=\"{$twitterUser[\'profile_image_url\']}\" alt=\'\' class=\'left ipsUserPhoto ipsUserPhoto_medium\' />\n			<div class=\'ipsBox_withphoto\'>\n		</if>\n		<h2 class=\'ipsType_subtitle\'>\n			{$this->lang->words[\'tc_logged_in_as\']} <strong>{$twitterUser[\'screen_name\']}</strong> ({$twitterUser[\'name\']})\n		</h2>\n		<if test=\"tcShowStatus:|:is_array($twitterUser[\'status\']) AND $twitterUser[\'status\'][\'text\']\">\n			<p class=\'desc\'>{$twitterUser[\'status\'][\'text\']}</p>\n		</if>\n		<if test=\"tcHasPic:|:$twitterUser[\'profile_image_url\']\">\n			</div>\n		</if>\n	</div>\n	\n	<br />\n	<div class=\'right row2 ipsPad clearfix\' style=\'width: 250px\'>\n		<span class=\'ipsType_smaller\'>\n			{$this->lang->words[\'tc_last_syncd\']}\n			<if test=\"tcLastSync:|:$this->memberData[\'tc_lastsync\']\">\n				{parse date=\"$this->memberData[\'tc_lastsync\']\" format=\"long\"}\n			<else />\n				{$this->lang->words[\'fb_never\']}\n			</if>\n		</span>\n		<br /><br />\n		<input type=\'submit\' class=\'ipsButton_secondary\' id=\'tc_sync\' value=\'{$this->lang->words[\'fb_sync_now\']}\' />\n		<br /><br />\n		<input type=\'button\' class=\'ipsButton_secondary\' id=\'tc_remove_start\' value=\'{$this->lang->words[\'tc_disassociate\']}\' />\n		\n		<div id=\'tc_remove_popup\' style=\'display: none\'>\n			<h3>{$this->lang->words[\'tc_disassociate\']}</h3>\n			<div class=\'ipsPad\'>\n				<p>{$this->lang->words[\'twitter_revoke\']}</p>\n				<p class=\'desc\'>{$this->lang->words[\'tc_disassociate_desc\']}</p>\n				<br />\n				<input type=\'button\' class=\'ipsButton\' id=\'tc_remove\' value=\'{$this->lang->words[\'tc_disassociate_now\']}\' />\n			</div>\n		</div>\n	</div>\n	<div>\n		<h2 class=\'ipsType_subtitle\'>{$this->lang->words[\'tc_sync_options\']}</h2>\n		<p class=\'desc\'>{$this->lang->words[\'tc_sync_options_desc\']}</p>\n		<ul class=\'ipsForm ipsForm_vertical ipsPad\'>\n			<li class=\'ipsField ipsField_checkbox\'>\n				<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'tc_s_pic\' value=\'1\' <if test=\"tcSyncPic:|:$this->memberData[\'tc_s_pic\'] > 0\">checked=\'checked\'</if> id=\'tc_s_pic\' />\n				<p class=\'ipsField_content\'>\n					<label for=\'tc_s_pic\'>{$this->lang->words[\'tc_sync_photo\']}</label><br />\n					<span class=\'desc lighter\'>{$this->lang->words[\'tc_sync_photo_info\']}</span>\n				</p>\n			</li>\n			<li class=\'ipsField ipsField_checkbox\'>\n				<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'tc_s_status\' value=\'1\' <if test=\"tcSyncStatus:|:$this->memberData[\'tc_s_status\'] > 0\">checked=\'checked\'</if> id=\'tc_s_status\' />\n				<p class=\'ipsField_content\'>\n					<label for=\'tc_s_status\'>{$this->lang->words[\'tc_sync_status_out\']}</label>\n				</p>\n			</li>\n			<if test=\"statusImportGroup:|: ! $this->memberData[\'gbw_no_status_import\']\">\n			<li class=\'ipsField ipsField_checkbox\'>\n				<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'tc_si_status\' value=\'1\' <if test=\"tcSyncIStatus:|:$this->memberData[\'tc_si_status\'] > 0\">checked=\'checked\'</if> id=\'tc_si_status\' />\n				<p class=\'ipsField_content\'>\n					<label for=\'tc_si_status\'>{$this->lang->words[\'tc_sync_status_in\']}</label>\n				</p>\n			</li>\n			</if>\n			<li class=\'ipsField ipsField_checkbox\'>\n				<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'tc_s_aboutme\' value=\'1\' <if test=\"tcSyncAboutMe:|:$this->memberData[\'tc_s_aboutme\'] > 0\">checked=\'checked\'</if> id=\'tc_s_aboutme\' />\n				<p class=\'ipsField_content\'>\n					<label for=\'tc_s_aboutme\'>{$this->lang->words[\'tc_sync_aboutme\']}</label>\n				</p>\n			</li>\n			<if test=\"canBG:|:$this->memberData[\'gbw_allow_customization\'] AND ! $this->memberData[\'bw_disable_customization\']\">\n				<li class=\'ipsField ipsField_checkbox\'>\n					<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'tc_s_bgimg\' value=\'1\' <if test=\"tcSyncBgImg:|:$this->memberData[\'tc_s_bgimg\'] > 0\">checked=\'checked\'</if> id=\'tc_s_bgimg\' />\n					<p class=\'ipsField_content\'>\n						<label for=\'tc_s_bgimg\'>{$this->lang->words[\'tc_sync_bgimg\']}</label>\n					</p>\n				</li>\n			</if>\n		</ul>\n	</div>\n	\n	<if test=\"twitterPassword:|:! $this->memberData[\'bw_local_password_set\'] AND $this->memberData[\'members_created_remote\']\">\n		<div class=\'message\'>\n			<strong>{$this->lang->words[\'remote_no_password\']}</strong>\n			<p>{$this->lang->words[\'remote_no_password_1\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=password\" base=\"public\"}\'>{$this->lang->words[\'remote_no_password_2\']}</a>\n			</p>\n		</div>\n		<br />\n	</if>\n	\n</div>\n<script type=\"text/javascript\">\n	$(\'tc_remove\').observe( \'click\', usercp_remove );\n	function usercp_remove(){\n		window.location = ipb.vars[\'base_url\'] + \'app=core&module=usercp&tab=core&area=twitterRemove&do=custom&secure_key=\' + ipb.vars[\'secure_hash\'];\n	}\n	\n	$(\'tc_remove_start\').on(\'click\', function(e){\n		new ipb.Popup( \'sign_in_popup\', {	type: \'pane\',\n											initial: $(\'tc_remove_popup\').show(),\n											hideAtStart: false,\n											hideClose: false,\n											modal: true,\n											w: \'600px\' } );\n	});\n</script>\n</if>', 'membersTwitterConnect', '$isConnected, $twitterUser=array()', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('470', '0', 'skin_ucp', '<h3 class=\'ipsType_subtitle\'>{$this->lang->words[\'board_prefs\']}</h3>\n<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'privacy_settings\']}</h3>\n	<ul>\n		<li class=\'field checkbox\'>\n			<input type=\'checkbox\' class=\'input_check\' id=\'admin_updates\' name=\'admin_send\' value=\'1\'<if test=\"allowAdminMails:|:$this->memberData[\'allow_admin_mails\']\"> checked=\"checked\"</if>/> <label for=\'admin_updates\'>{$this->lang->words[\'admin_send\']}</label><br />\n			<span class=\'desc lighter\'>{$this->lang->words[\'admin_send_desc\']} {$time}</span>\n		</li>\n	</ul>\n</fieldset>\n<fieldset class=\'row1\'>\n	<span class=\'desc\'><strong>{$this->lang->words[\'notifications_info_acp\']}</strong></span>\n	<php>\n		$this->notifyGroups = array(\n			\'topics_posts\' => array( \'followed_topics\', \'followed_forums\', \'followed_topics_digest\', \'followed_forums_digest\', \'post_quoted\', \'new_likes\' ),\n			\'status_updates\' => array( \'reply_your_status\', \'reply_any_status\', \'friend_status_update\' ),\n			\'profiles_friends\' => array( \'profile_comment\', \'profile_comment_pending\', \'friend_request\', \'friend_request_pending\', \'friend_request_approve\' ),\n			\'private_msgs\' => array( \'new_private_message\', \'reply_private_message\', \'invite_private_message\' )\n		);\n		\n		$this->_config = $config;\n		\n		$this->_colCount = IPSMember::canReceiveMobileNotifications() ? 4 : 3;\n		\n		$this->_lastApp	= \'\';\n	</php>\n	<table class=\'ipb_table notification_table\'>\n		<tr>\n			<th>&nbsp;</th>\n			<th style=\'width: 15%\' class=\'short\'><span class=\'notify_icon inline\'>&nbsp;</span> {$this->lang->words[\'notify_type_inline\']}</th>\n			<th style=\'width: 15%\' class=\'short\'><span class=\'notify_icon email\'>&nbsp;</span> {$this->lang->words[\'notify_type_email\']}</th>\n			<if test=\"IPSMember::canReceiveMobileNotifications()\">\n			<th style=\'width: 15%\' class=\'short\'><span class=\'notify_icon mobile\'>&nbsp;</span> {$this->lang->words[\'notify_type_mobile\']}</th>\n			</if>\n		</tr>\n		<foreach loop=\"notifyGroupsList:$this->notifyGroups as $groupKey => $group\">\n			<tr class=\'row2\'>\n				<td colspan=\'{$this->_colCount}\'>\n					<h3>{$this->lang->words[ \'notifytitle_\' . $groupKey ]}</h3>\n					<if test=\"isPrivateMsg:|:$groupKey == \'private_msgs\'\">\n						<p class=\'ipsPad_half checkbox ipsType_smaller desc \'>\n							<input type=\'checkbox\' class=\'input_check\' id=\'show_notification_popup\' name=\'show_notification_popup\' value=\'1\' <if test=\"$this->memberData[\'_cache\'][\'show_notification_popup\']\">checked=\'checked\'</if> /> <label for=\'show_notification_popup\' />{$this->lang->words[\'show_notification_popup\']}</label><br />\n						</p>\n					</if>\n					<if test=\"isTopicsOrPosts:|:$groupKey == \'topics_posts\'\">\n						<p class=\'ipsPad_half checkbox ipsType_smaller desc \'>\n							<input class=\'input_check\' type=\"checkbox\" id=\'auto_track\' name=\"auto_track\" value=\"1\" {$emailData[\'auto_track\']} /> <label for=\'auto_track\' />{$this->lang->words[\'auto_track\']}</label>\n							<select name=\"trackchoice\" id=\'track_choice\' class=\'input_select\'>\n								<option value=\"none\" {$emailData[\'trackOption\'][\'none\']}>{$this->lang->words[\'like_notify_freq_none\']}</option>\n								<option value=\"immediate\" {$emailData[\'trackOption\'][\'immediate\']}>{$this->lang->words[\'like_notify_freq_immediate\']}</option>\n								<option value=\"offline\" {$emailData[\'trackOption\'][\'offline\']}>{$this->lang->words[\'like_notify_freq_offline\']}</option>\n								<option value=\"daily\" {$emailData[\'trackOption\'][\'daily\']}>{$this->lang->words[\'like_notify_freq_daily\']}</option>\n								<option value=\"weekly\" {$emailData[\'trackOption\'][\'weekly\']}>{$this->lang->words[\'like_notify_freq_weekly\']}</option>\n							</select>\n							<if test=\"badConfig:|:$emailData[\'auto_track\'] AND $emailData[\'trackOption\'][\'none\']\">\n								<br />{$this->lang->words[\'auto_but_no_email\']}\n							</if>\n						</p>\n					</if>\n				</td>\n			</tr>\n			<foreach loop=\"groupKeys:$group as $key\">\n				<if test=\"keyExists:|:$this->_config[ $key ]\">\n					<tr>\n						<td class=\'notify_title desc\'>{$this->lang->words[\'notify__\' . $key]}</td>\n						<td class=\'short\'>\n							<span class=\'notify_icon inline\' title=\'{$this->lang->words[\'notify_type_inline\']}\'>&nbsp;</span>\n							<if test=\"$groupKey == \'private_msgs\'\">\n								<input type=\'checkbox\' class=\'input_check\' name=\'\' checked=\'checked\' disabled=\'disabled\' /> <span class=\'ipsBadge ipsBadge_lightgrey ipsType_smaller\' data-tooltip=\'{$this->lang->words[\'nots_pm_whatthef\']}\'>{$this->lang->words[\'nots_pm_list\']}</span>\n							<else />\n								<if test=\"isset( $this->_config[$key][\'options\'][\'inline\'] ) && $groupKey != \'private_msgs\'\">\n									<input type=\'checkbox\' class=\'input_check\' id=\'inline_{$key}\' name=\"config_{$key}[]\" value=\"inline\"<if test=\"hasconfignotify:|:is_array($this->_config[$key][\'defaults\']) AND in_array(\'inline\',$this->_config[$key][\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$this->_config[$key][\'disabled\']\"> disabled=\"disabled\"</if> />\n								<else />\n									<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n								</if>\n							</if>\n						</td>\n						<td class=\'short\'>\n							<span class=\'notify_icon email\' title=\'{$this->lang->words[\'notify_type_email\']}\'>&nbsp;</span>\n							<if test=\"isset( $this->_config[$key][\'options\'][\'email\'] )\">\n								<input type=\'checkbox\' class=\'input_check\' id=\'email_{$key}\' name=\"config_{$key}[]\" value=\"email\"<if test=\"hasconfignotify:|:is_array($this->_config[$key][\'defaults\']) AND in_array(\'email\',$this->_config[$key][\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$this->_config[$key][\'disabled\']\"> disabled=\"disabled\"</if> />\n							<else />\n								<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n							</if>\n						</td>\n						<if test=\"IPSMember::canReceiveMobileNotifications()\">\n						<td class=\'short\'>\n							<span class=\'notify_icon mobile\' title=\'{$this->lang->words[\'notify_type_mobile\']}\'>&nbsp;</span>\n							<if test=\"isset( $this->_config[$key][\'options\'][\'mobile\'] )\">\n								<input type=\'checkbox\' class=\'input_check\' id=\'mobile_{$key}\' name=\"config_{$key}[]\" value=\"mobile\"<if test=\"hasconfignotify:|:is_array($this->_config[$key][\'defaults\']) AND in_array(\'mobile\',$this->_config[$key][\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$this->_config[$key][\'disabled\']\"> disabled=\"disabled\"</if> />\n							<else />\n								<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n							</if>\n						</td>\n						</if>\n					</tr>\n					<if test=\"$this->_config[$key][\'_done\'] = 1\"></if>\n				</if>\n			</foreach>							\n		</foreach>\n		<foreach loop=\"notifyOther:$this->_config as $key => $_config\">\n			<if test=\"keyNotDone:|:!isset( $_config[\'_done\'] ) && $_config[\'_done\'] != 1\">\n				<if test=\"newNotApp:|:$this->_lastApp != $_config[\'app\']\">\n					<tr class=\'row2\'>\n						<td colspan=\'{$this->_colCount}\'>\n							<h3><if test=\"isCoreNot:|:$_config[\'app\'] == \'core\'\">{$this->lang->words[\'notifytitle_other\']}<else />{IPSLib::getAppTitle( $_config[\'app\'] )}</if></h3>\n						</td>\n					</tr>\n					<if test=\"updateLastApp:|:$this->_lastApp = $_config[\'app\']\"></if>\n				</if>\n				<tr>\n					<td class=\'notify_title desc\'>{$this->lang->words[\'notify__\' . $_config[\'key\'] ]}</h3></td>\n					<td class=\'short\'>\n						<span class=\'notify_icon inline\' title=\'{$this->lang->words[\'notify_type_inline\']}\'>&nbsp;</span>\n						<if test=\"isset( $_config[\'options\'][\'inline\'] )\">\n							<input type=\'checkbox\' class=\'input_check\' id=\'inline_{$key}\' name=\"config_{$key}[]\" value=\"inline\"<if test=\"hasconfignotify:|:is_array($_config[\'defaults\']) AND in_array(\'inline\',$_config[\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$_config[\'disabled\']\"> disabled=\"disabled\"</if> />\n						<else />\n							<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n						</if>\n					</td>\n					<td class=\'short\'>\n						<span class=\'notify_icon email\' title=\'{$this->lang->words[\'notify_type_email\']}\'>&nbsp;</span>\n						<if test=\"isset( $_config[\'options\'][\'email\'] )\">\n							<input type=\'checkbox\' class=\'input_check\' id=\'email_{$key}\' name=\"config_{$key}[]\" value=\"email\"<if test=\"hasconfignotify:|:is_array($_config[\'defaults\']) AND in_array(\'email\',$_config[\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$_config[\'disabled\']\"> disabled=\"disabled\"</if> />\n						<else />\n							<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n						</if>\n					</td>\n					<if test=\"IPSMember::canReceiveMobileNotifications()\">\n					<td class=\'short\'>\n						<span class=\'notify_icon mobile\' title=\'{$this->lang->words[\'notify_type_mobile\']}\'>&nbsp;</span>\n						<if test=\"isset( $_config[\'options\'][\'mobile\'] )\">\n							<input type=\'checkbox\' class=\'input_check\' id=\'mobile_{$key}\' name=\"config_{$key}[]\" value=\"mobile\"<if test=\"hasconfignotify:|:is_array($this->_config[$key][\'defaults\']) AND in_array(\'mobile\',$this->_config[$key][\'defaults\'])\"> checked=\"checked\"</if> <if test=\"hasconfigdisable:|:$this->_config[$key][\'disabled\']\"> disabled=\"disabled\"</if> />\n						<else />\n							<input type=\'checkbox\' class=\'input_check\' name=\'\' disabled=\'disabled\' />\n						</if>\n					</td>\n					</if>\n				</tr>\n			</if>\n		</foreach>\n	</table>\n</fieldset>', 'notificationsForm', '$config, $emailData', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('471', '0', 'skin_ucp', '<if test=\"hasnotifyerror:|:$error\">\n<p class=\'message error\'>\n	{$error}\n</p>\n<else />\n	<if test=\"hasconfirm:|:$this->request[\'confirm\']\">\n	<p class=\'message\'>\n		{$this->lang->words[\'notify_rem_suc\']}\n	</p>\n	</if>\n</if>\n<div id=\'notificationlog\'>\n	<form action=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=removeNotifications&amp;do=remove\" base=\"public\"}\" id=\"checkBoxForm\" method=\"post\">\n	<input type=\"hidden\" name=\"secure_key\" value=\"{$this->member->form_hash}\" />\n	<if test=\"hasNotifications:|:is_array( $notifications ) AND count( $notifications )\">\n		<div class=\'right ipsPad\'>\n			<input id=\"checkAllNotifications\" type=\"checkbox\" value=\"{$this->lang->words[\'check_all\']}\" />\n		</div>\n		<h2 class=\'ipsType_subtitle\'>{$this->lang->words[\'arch_notifications_head\']}</h2>\n		<br />\n		<table class=\'ipb_table\' summary=\"{$this->lang->words[\'notifications_table_head\']}\">\n			<tr class=\'header hide\'>\n				<th scope=\'col\' width=\"5%\">&nbsp;</th>\n				<th scope=\'col\' width=\"70%\">{$this->lang->words[\'th_notification\']}</th>\n				<th scope=\'col\' width=\"25%\">{$this->lang->words[\'th_sent\']}</th>\n				<th scope=\'col\' align=\"center\" width=\"5%\" class=\'short\'>&nbsp;</th>\n			</tr>\n			{parse striping=\"notify\" classes=\"row2,row1\"}\n			<foreach loop=\"categories:$notifications as $notification\">\n				<tr class=\'{parse striping=\"notify\"} <if test=\"hasReadNotify:|:!$notification[\'notify_read\']\">unread</if>\'>\n					<td class=\"col_n_icon altrow short\"><if test=\"hasReadNotify:|:$notification[\'notify_read\']\">{parse replacement=\"t_read\"}<else />{parse replacement=\"t_unread\"}</if></td>\n					<td class=\'col_n_photo short\'>\n						<if test=\"$notification[\'member\'][\'member_id\']\">\n							<a href=\'{parse url=\"showuser={$notification[\'member\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$notification[\'member\'][\'members_seo_name\']}\" base=\"public\"}\' class=\'ipsUserPhotoLink\'>\n								<img src=\'{$notification[\'member\'][\'pp_thumb_photo\']}\' class=\'ipsUserPhoto ipsUserPhoto_mini\' />\n							</a>\n						<else />\n							{IPSMember::buildNoPhoto(0, \'mini\' )}\n						</if>\n					</td>\n					<td>\n						<h4><if test=\"strpos( $notification[\'notify_title\'], \'<a href\' ) === false\"><a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=viewNotification&amp;do=view&amp;view={$notification[\'notify_id\']}\" base=\"public\"}\'></if>\n						{$notification[\'notify_title\']}\n						<if test=\"strpos( $notification[\'notify_title\'], \'<a href\' ) === false\"></a></if>\n						</h4>\n					</td>\n					<td class=\"col_n_date desc\"><a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=viewNotification&amp;do=view&amp;view={$notification[\'notify_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_notification_logentry\']}\'>{$this->lang->words[\'th_sent\']} {parse date=\"$notification[\'notify_sent\']\" format=\"long\"}</a></td>\n					<td class=\"short col_n_mod\"><input class=\'input_check checkall\' type=\"checkbox\" name=\"notifications[]\" value=\"{$notification[\'notify_id\']}\" /></td>\n				</tr>\n			</foreach>\n		</table>\n		<script type=\'text/javascript\'>\n			ipb.global.registerCheckAll(\'checkAllNotifications\', \'checkall\');\n		</script>\n	<else />\n		<p class=\'no_messages\'>{$this->lang->words[\'notifications_none\']}</p>\n	</if>\n	<if test=\"hasNotifyForMod:|:count($notifications)\">\n		<br />\n		<a href=\'{parse url=\"app=core&amp;module=usercp&amp;area=markNotification&amp;do=mark&amp;mark=all\" base=\"public\"}\' id=\'ack_pm_notification\' class=\'input_submit left\'>{$this->lang->words[\'notificationlog_mar\']}</a>\n		<div class=\'moderation_bar rounded with_action\'>\n			<input type=\"submit\" class=\"input_submit alt\" value=\"{$this->lang->words[\'ndel_selected\']}\" />\n		</div>\n		<br />\n		<div class=\'topic_controls\'>\n			{$pages}\n		</div>\n	</if>\n</form>\n</div>', 'notificationsLog', '$notifications, $error=\'\', $pages=\'\'', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('472', '0', 'skin_ucp', '<fieldset class=\'row2\'>\n	<h2>{$notification[\'notify_title\']}</h2>\n	<ul>\n		<li class=\'field\'>\n			{$this->lang->words[\'notifyview_date\']}\n			<em>{parse date=\"$notification[\'notify_sent\']\" format=\"long\"}</em>\n		</li>\n	</ul>\n</fieldset>\n<fieldset class=\'row1\'>\n	<ul>\n		<li class=\'field\'>\n			{$notification[\'notify_text\']}\n		</li>\n	</ul>\n</fieldset>\n<fieldset class=\'row2\'>\n	<ul>\n		<li class=\'field short\'>\n			<a href=\'{parse url=\"app=core&amp;module=usercp&amp;area=notificationlog\" base=\"public\"}\' class=\'input_submit\'>{$this->lang->words[\'goback\']}</a>	\n			<a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=removeNotifications&amp;do=remove&amp;secure_key={$this->member->form_hash}&amp;notifications[]={$notification[\'notify_id\']}\" base=\"public\"}\' class=\'input_submit delete\'>{$this->lang->words[\'deletenotification\']}</a>\n		</li>\n	</ul>\n</fieldset>', 'showNotification', '$notification', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('473', '0', 'skin_ucp', '{parse js_module=\"ucp\"}\n<php>\n$hasMoreTabs = (is_array($tabs[ $current_tab ][\'_menu\']) && count($tabs[ $current_tab ][\'_menu\']) > 1) ? true : false;\n</php>\n<if test=\"usercp_form:|:$hide_form == 0\">\n	<if test=\"has_max_upload:|:$maxUpload\">\n		<form method=\'post\' enctype=\"multipart/form-data\" action=\'{parse url=\"app=core&amp;module=usercp&amp;tab={$current_tab}&amp;area={$current_area}\" base=\"public\"}\' id=\'userCPForm\'>\n	<else />\n		<form method=\'post\' action=\'{parse url=\"app=core&amp;module=usercp&amp;tab={$current_tab}&amp;area={$current_area}\" base=\"public\"}\' id=\'userCPForm\'>\n	</if>\n</if>\n	<fieldset>\n		<input type=\"hidden\" name=\"MAX_FILE_SIZE\" value=\"{$maxUpload}\" />\n		<input type=\'hidden\' name=\'do\' value=\'save\' />\n		<input type=\'hidden\' name=\'secure_hash\' value=\'{$this->member->form_hash}\' />\n		<input type=\'hidden\' name=\'s\' value=\'{$this->request[\'s\']}\' />\n	</fieldset>\n<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'ucp_title\']}</h1>\n<br />\n<if test=\"count($tabs) > 1\">\n	<div class=\'maintitle ipsFilterbar clearfix\'>\n		<ul class=\'ipsList_inline\'>\n			<foreach loop=\"tabs:$tabs as $tab_app => $tab\">\n				<if test=\"active_tab:|:$tab_app == $current_tab\">\n					<li class=\'active\'><a href=\"{parse url=\"module=usercp&amp;tab={$tab_app}\" base=\"publicWithApp\"}\" title=\"<if test=\"isSettings:|:$tab_app==\'core\'\">{$this->lang->words[\'settings_for_coretab\']}<else />{parse expression=\"sprintf( $this->lang->words[\'settings_for_ucp\'], $tab[\'_name\'] )\"}</if>\">{$tab[\'_name\']}</a></li>\n				<else />\n					<li><a href=\"{parse url=\"module=usercp&amp;tab={$tab_app}\" base=\"publicWithApp\"}\" title=\"<if test=\"isSettingsInactive:|:$tab_app==\'core\'\">{$this->lang->words[\'settings_for_coretab\']}<else />{parse expression=\"sprintf( $this->lang->words[\'settings_for_ucp\'], $tab[\'_name\'] )\"}</if>\">{$tab[\'_name\']}</a></li>\n				</if>\n			</foreach>\n		</ul>\n	</div>\n</if>\n<div class=\'ipsBox\'>\n	<div class=\'ipsLayout<if test=\"hasMoreThanOneTabClass:|:$hasMoreTabs\"> ipsLayout_withleft ipsLayout_smallleft ipsVerticalTabbed</if> clearfix usercp_body\'>\n		<if test=\"hasMoreThanOneTabSidebar:|:$hasMoreTabs\">\n			<div class=\'ipsVerticalTabbed_tabs ipsLayout_left\' id=\'usercp_tabs\'>\n				<ul>\n					<foreach loop=\"items:$tabs[ $current_tab ][\'_menu\'] as $idx => $item\">\n						<if test=\"tabsMenus_active:|:$item[\'area\'] == $current_area OR $item[\'active\']\">\n							<li class=\'active\'><a href=\"{parse url=\"module=usercp&amp;tab={$current_tab}&amp;{$item[\'url\']}\" base=\"publicWithApp\"}\">{$item[\'title\']}</a></li>\n						<else />\n							<li><a href=\"{parse url=\"module=usercp&amp;tab={$current_tab}&amp;{$item[\'url\']}\" base=\"publicWithApp\"}\">{$item[\'title\']}</a></li>\n						</if>\n					</foreach>\n				</ul>\n			</div>\n		</if>\n		<div class=\'<if test=\"hasMoreThanOneTabClassContent:|:$hasMoreTabs\">ipsVerticalTabbed_content </if>ipsLayout_content ipsBox_container\' id=\'usercp_content\'>\n			<div class=\'ipsPad\'>\n				<if test=\"has_errors:|:is_array( $errors ) AND count( $errors )\">\n					<p class=\'message error\'>\n						<foreach loop=\"errors:$errors as $error\">\n							{$error}<br />\n						</foreach>\n					</p>\n					<br />\n				</if>\n				<if test=\"didSave:|:$this->request[\'saved\'] == 1\">\n					<p class=\'message\'>{$this->lang->words[\'ucp__settings_saved\']}</p>\n					<br />\n				</if>\n				{$html}\n		\n				<if test=\"submit_button:|:$hide_form == 0\">\n				<fieldset class=\'submit\'>\n					<input type=\'submit\' class=\'input_submit\' name=\'submitForm\' value=\'{$this->lang->words[\'ucp__save_changes\']}\' /> {$this->lang->words[\'or\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab={$current_tab}&amp;area={$current_area}\" base=\"public\"}\' title=\'{$this->lang->words[\'cancel_edit\']}\' class=\'cancel\'>{$this->lang->words[\'cancel\']}</a>\n				</fieldset>\n				</if>\n			</div>\n		</div>\n	</div>\n</div>\n<if test=\"end_form:|:$hide_form == 0\">\n</form>\n</if>', 'userCPTemplate', '$current_tab, $html, $tabs, $current_area, $errors=array(), $hide_form=0, $maxUpload=0', '1338050064', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('474', '0', 'skin_messaging', '<!--no data in this master skin-->', 'messengerDisabled', '', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('475', '0', 'skin_messaging', '<div class=\'master_list\'>\n	<!--<h2>{$this->lang->words[\'m_messenger\']}</h2>-->\n	<if test=\"inlineError:|:$inlineError\">\n		<div class=\'message error\'>\n			{$inlineError}\n		</div>\n	</if>\n	{$html}\n	\n	<if test=\"hasParticipants:|:is_array( $topicParticipants ) and count( $topicParticipants )\">\n		<h3>{$this->lang->words[\'participants\']}</h3>\n		<foreach loop=\"participants:$topicParticipants as $memberID => $memberData\">\n			<div class=\'row\'>\n				<div class=\'icon\'>\n					<a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' ><img src=\'{$memberData[\'pp_mini_photo\']}\' style=\'width: 30px; height: 30px;\' alt=\'{$this->lang->words[\'photo\']}\' class=\'photo\' /></a>\n				</div>\n				<if test=\"userIsActive:|:$memberData[\'map_user_active\']\">\n					<a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$memberData[\'members_display_name\']}</strong></a>\n					<if test=\"userIsStarter:|:$memberData[\'map_is_starter\']\">\n						&nbsp;&middot;&nbsp;<span class=\'subtext\'><strong>{$this->lang->words[\'col_starter\']}</strong></span>\n					</if>\n					<br />\n					<span class=\'desc\'>\n						<if test=\"messageIsDeleted:|:$memberData[\'_topicDeleted\']\">\n							<em>{$this->lang->words[\'topic_deleted\']}</em>\n						<else />\n							{$this->lang->words[\'last_read\']}\n							<if test=\"lastReadTime:|:$memberData[\'map_read_time\']\">\n								{parse date=\"$memberData[\'map_read_time\']\" format=\"short\"}\n							<else />\n								{$this->lang->words[\'not_yet_read\']}\n							</if>\n						</if>							\n					</span>\n				<else />\n					<if test=\"userIsBanned:|:$memberData[\'map_user_banned\']\">\n						<a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$memberData[\'members_display_name\']}</strong></a>\n							&nbsp;&middot;&nbsp;<span class=\'subtext\'><strong>{$this->lang->words[\'blocked\']}</strong></span>\n						<br />\n						<span class=\'desc\'>{$this->lang->words[\'user_is_blocked\']}</span>\n					<else />\n						<a href=\'{parse url=\"showuser={$memberData[\'member_id\']}\" seotitle=\"{$memberData[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><strong>{$memberData[\'members_display_name\']}</strong></a>\n						<br />\n						<span class=\'desc\'>\n							<if test=\"topicUnavailable:|:$memberData[\'_topicDeleted\']\">\n								{$this->lang->words[\'topic_deleted\']}\n							<else />\n								<if test=\"systemMessage:|:$memberData[\'map_is_system\']\">\n									{$this->lang->words[\'is_unable_part\']}\n								<else />\n									{$this->lang->words[\'has_left_convo\']}\n								</if>\n							</if>\n						</span>\n					</if>\n				</if>\n			</div>\n		</foreach>\n	</if>				\n	\n	<if test=\"$this->settings[\'_hideFolders\'] != 1\">\n		<h3>{$this->lang->words[\'folders\']} <if test=\"storageBar:|:$this->memberData[\'g_max_messages\'] > 0\"><span class=\'subtext\'>{$totalData[\'full_percent\']}% {$this->lang->words[\'full\']}</span></if></h3>\n	\n		<if test=\"myDirectories:|:count($dirData)\">\n			<foreach loop=\"dirs:$dirData as $id => $data\">\n				<div class=\'row\'>\n					<div class=\'right_info\'>\n						<if test=\"allFolder:|:$id == \'all\'\">\n							{parse expression=\"intval($this->memberData[\'msg_count_total\'])\"}\n						<else />\n							{parse expression=\"intval($data[\'count\'])\"}\n						</if>\n					</div>\n					<a href=\"{parse url=\"module=messaging&amp;section=view&amp;do=showFolder&amp;folderID={$id}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'go_to_folder\']}\" rel=\"folder_name\">{$data[\'real\']}</a>\n				</div>\n			</foreach>\n		</if>\n	</if>\n</div>', 'messengerTemplate', '$html, $jumpmenu, $dirData, $totalData=array(), $topicParticipants=array(), $inlineError=\'\', $deletedTopic=0', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('476', '0', 'skin_messaging', '<!--no data in this master skin-->', 'PMQuickForm', '$toMemberData', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('477', '0', 'skin_messaging', '<if test=\"$this->settings[\'_hideFolders\'] = 1\"></if>\n<form id=\'msgForm\' class=\'ipsForm_vertical\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=send\" base=\"publicWithApp\"}\" method=\"post\" enctype=\'multipart/form-data\'>\n	<if test=\"newTopicError:|:$displayData[\'errors\']\">\n		<div class=\'message error\'>\n			<strong>{$this->lang->words[\'err_errors\']}</strong><br />\n			{$displayData[\'errors\']}<br />\n			{$this->lang->words[\'pme_none_sent\']}\n		</div>\n	</if>\n	\n	<h3>{$this->lang->words[\'pro_recips\']}</h3>\n	<div class=\'ipsField\'>\n		<label for=\'entered_name\' class=\'ipsField_title\'>{$this->lang->words[\'to_whom\']}</label>\n		<input type=\"text\" class=\'input_text\' id=\'entered_name\' name=\"entered_name\" size=\"30\" value=\"{$displayData[\'name\']}\" tabindex=\"0\" />\n	</div>\n	<if test=\"newTopicInvite:|:intval($this->memberData[\'g_max_mass_pm\'])\">\n		<div class=\'ipsField\'>\n			<label for=\'ipsField_title\' class=\'ipsField_title\'>{$this->lang->words[\'other_recipients\']}</label>\n			<input type=\'text\' size=\"30\" class=\'input_text\' name=\'inviteUsers\' value=\'{$displayData[\'inviteUsers\']}\' id=\'more_members\' tabindex=\'0\' /><br />\n			<span class=\'desc\'>{$this->lang->words[\'youmay_add_to\']} <strong>{$this->memberData[\'g_max_mass_pm\']}</strong> {$this->lang->words[\'youmay_suffix\']}</span>\n		</div>\n		\n		<div class=\'ipsField\'>\n			<strong>{$this->lang->words[\'send_to_as\']} </strong>\n			<select name=\'sendType\' id=\'send_type\' tabindex=\'0\'>\n				<option value=\'invite\'<if test=\"formReloadInvite:|:$this->request[\'sendType\']==\'invite\'\"> selected=\'selected\'</if>>{$this->lang->words[\'send__invite\']}</option>\n				<option value=\'copy\'<if test=\"formReloadCopy:|:$this->request[\'sendType\']==\'copy\'\"> selected=\'selected\'</if>>{$this->lang->words[\'send__copy\']}</option>\n			</select><br />\n			<span class=\'desc\'>\n				<strong>{$this->lang->words[\'send__invite\']}</strong> {$this->lang->words[\'invite__desc\']}<br />\n				<strong>{$this->lang->words[\'send__copy\']}</strong> {$this->lang->words[\'copy__desc\']}\n			</span>\n		</div>\n	</if>\n	\n	<h3>{$this->lang->words[\'pro_message\']}</h3>\n	<div class=\'ipsField\'>\n		<label for=\'message_subject\' class=\'ipsField_title\'>{$this->lang->words[\'message_subject_send\']}</label>\n		<input type=\"text\" name=\"msg_title\" id=\'message_subject\' class=\'input_text\' size=\"30\" tabindex=\"0\" maxlength=\"40\" value=\"{$displayData[\'title\']}\" />\n	</div>\n	<div class=\'ipsField\'>\n		{$displayData[\'editor\']}\n	</div>\n	<input type=\'hidden\' name=\'topicID\' value=\"{$displayData[\'topicID\']}\" />\n	<input type=\'hidden\' name=\"postKey\" value=\"{$displayData[\'postKey\']}\" />\n	<input type=\"hidden\" name=\"auth_key\" value=\"{$this->member->form_hash}\" />\n	<div class=\'submit\'>\n		<input class=\'button\' name=\"dosubmit\" type=\"submit\" value=\"{$this->lang->words[\'submit_send\']}\" tabindex=\"0\" accesskey=\"s\" />\n	</div>\n		\n</form>', 'sendNewPersonalTopicForm', '$displayData', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('478', '0', 'skin_messaging', '<if test=\"$this->settings[\'_hideFolders\'] = 1\"></if>\n<if test=\"replyForm:|:$displayData[\'type\'] == \'reply\'\">\n	<form id=\'msgForm\' style=\'display:block\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=sendReply\" base=\"publicWithApp\"}\" method=\"post\" name=\"REPLIER\">\n<else />\n	<form id=\'msgForm\' style=\'display:block\' action=\"{parse url=\"module=messaging&amp;section=send&amp;do=sendEdit\" base=\"publicWithApp\"}\" method=\"post\" name=\"REPLIER\">\n</if>\n<input type=\"hidden\" name=\"msgID\" value=\"{$displayData[\'msgID\']}\" />\n<input type=\'hidden\' name=\'topicID\' value=\"{$displayData[\'topicID\']}\" />\n<input type=\'hidden\' name=\"postKey\" value=\"{$displayData[\'postKey\']}\" />\n<input type=\"hidden\" name=\"authKey\" value=\"{$this->member->form_hash}\" />\n<if test=\"formErrors:|:$displayData[\'errors\']\">\n	<div class=\'message error\'>\n		<strong>{$this->lang->words[\'err_errors\']}</strong><br />\n		{$displayData[\'errors\']}<br />\n		{$this->lang->words[\'pme_none_sent\']}\n	</div>\n</if>\n<if test=\"formHeaderText:|:$displayData[\'type\'] == \'reply\'\">\n	<h3>{$this->lang->words[\'compose_reply\']}</h3>\n<else />\n	<h3>{$this->lang->words[\'editing_message\']}</h3>\n</if>\n<div class=\'row\'>\n	{$displayData[\'editor\']}\n</div>\n<div class=\'submit\'>\n	<if test=\"replyOptions:|:$displayData[\'type\'] == \'reply\'\">\n		<input class=\'button\' type=\"submit\" value=\"{$this->lang->words[\'submit_send\']}\" tabindex=\"0\" accesskey=\"s\" />\n	<else />\n		<input class=\'button\' type=\"submit\" value=\"{$this->lang->words[\'save_message_button\']}\" tabindex=\"0\" accesskey=\"s\" />\n	</if>\n</div>', 'sendReplyForm', '$displayData', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('479', '0', 'skin_messaging', '<div class=\'controls\'>\n	<div class=\'buttons\'>\n		<if test=\"canReply:|:$topic[\'_canReply\']\">\n			<a class=\'button\' href=\'{parse url=\"module=messaging&amp;section=send&amp;do=replyForm&amp;topicID={$topic[\'mt_id\']}\" base=\"publicWithApp\"}\'>{parse replacement=\"reply_icon\"} {$this->lang->words[\'add_reply\']}</a>\n		</if>\n		<!--<a class=\'button delete\' href=\'{parse url=\"module=messaging&amp;section=view&amp;do=deleteConversation&amp;topicID={$topic[\'mt_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\'>{$this->lang->words[\'option__delete\']}</a>-->\n	</div>\n	{$topic[\'_pages\']}\n</div>\n<foreach loop=\"replies:$replies as $msg_id => $msg\">\n	<div class=\'topic_reply\'>\n		<h2 class=\'secondary\'>\n			<img src=\'{$members[ $msg[\'msg_author_id\'] ][\'pp_thumb_photo\']}\' class=\'photo\' />\n			<a class=\"url fn\" href=\'{parse url=\"showuser={$members[ $msg[\'msg_author_id\'] ][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$members[ $msg[\'msg_author_id\'] ][\'members_seo_name\']}\"}\'>{$members[ $msg[\'msg_author_id\'] ][\'members_display_name\']}</a>\n			<span class=\'subtext\'>{$this->lang->words[\'pc_sent\']} {parse date=\"$msg[\'msg_date\']\" format=\"long\"}</span>\n		</h2>\n		<div class=\'post line_spacing\' id=\'msg_{$msg[\'msg_id\']}\'>\n			{$msg[\'msg_post\']}\n			{$msg[\'attachmentHtml\']}\n		</div>\n		<div class=\'post_controls\' id=\'msg_{$msg[\'msg_id\']}-controls\'>\n			<if test=\"quickReply:|:$topic[\'_canReply\']\">\n				<a href=\"{parse url=\"module=messaging&amp;section=send&amp;do=replyForm&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{$this->lang->words[\'pc_reply\']}</a>\n			</if>\n			<if test=\"canEdit:|:$msg[\'_canEdit\'] === TRUE\">\n				<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=editMessage&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'edit_this_post\']}\'>{$this->lang->words[\'pc_edit\']}</a>\n			</if>\n			<if test=\"canDelete:|:$msg[\'_canDelete\'] === TRUE && $msg[\'msg_is_first_post\'] != 1\">\n				<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=deleteReply&amp;topicID={$topic[\'mt_id\']}&amp;msgID={$msg[\'msg_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'delete_this_post\']}\' class=\'delete_post\'>{$this->lang->words[\'pc_delete\']}</a>\n			</if>\n		</div>\n	</div>\n</foreach>\n<div class=\'controls\'>\n	<div class=\'buttons\'>\n	<!--<a class=\'button\' href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'go_to_compose\']}\'>{parse replacement=\"compose_icon\"} {$this->lang->words[\'compose_new\']}</a>-->\n		<if test=\"canReply:|:$topic[\'_canReply\']\">\n			<a class=\'button\' href=\'{parse url=\"module=messaging&amp;section=send&amp;do=replyForm&amp;topicID={$topic[\'mt_id\']}\" base=\"publicWithApp\"}\'>{parse replacement=\"reply_icon\"} {$this->lang->words[\'add_reply\']}</a>\n		</if>\n	<!--<a class=\'button delete\' href=\'{parse url=\"module=messaging&amp;section=view&amp;do=deleteConversation&amp;topicID={$topic[\'mt_id\']}&amp;authKey={$this->member->form_hash}\" base=\"publicWithApp\"}\'>{$this->lang->words[\'option__delete\']}</a>-->\n	</div>\n	{$topic[\'_pages\']}\n</div>', 'showConversation', '$topic, $replies, $members, $jump=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('480', '0', 'skin_messaging', '<!--no data in this master skin-->', 'showConversationForArchive', '$topic, $replies, $members', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('481', '0', 'skin_messaging', '<php>\n	if( !$this->request[\'folderID\'] )\n	{\n		$this->settings[\'_mobile_nav_home\'] = true;\n	}\n</php>\n<h2>{$dirname}</h2>\n<div class=\'controls\'><div class=\"buttons\">\n	<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' class=\'button\' title=\'{$this->lang->words[\'go_to_compose\']}\'>{$this->lang->words[\'compose_new\']}</a>\n	{$pages}\n</div>\n</div>\n<if test=\"folderMessages:|:count( $messages )\">\n	{parse striping=\"msg_stripe\" classes=\"row1,row2\"}\n	<foreach loop=\"folderMessages:$messages as $id => $msg\">\n		<div class=\'row touch-row\' id=\"row-{$id}\">\n			<div class=\'icon\'>\n				<if test=\"folderDeleted:|:$msg[\'mt_is_deleted\'] OR $msg[\'map_user_banned\']\">\n					{parse replacement=\"msg_deleted\"}\n				<else />\n					<if test=\"folderUnread:|:$msg[\'map_has_unread\'] == 1\">\n						{parse replacement=\"msg_icon_new\"}\n					<else />\n						{parse replacement=\"msg_icon\"}\n					</if>\n				</if>\n			</div>\n			<div class=\'row_content\'>\n				<if test=\"folderDrafts:|:$currentFolderID == \'drafts\'\">\n					<strong><a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}\" class=\"title\">{$msg[\'mt_title\']}</a></strong>\n				<else />\n					<strong><a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}\" class=\"title\">{$msg[\'mt_title\']}</a></strong>\n				</if>\n				<br />\n				<span class=\'subtext\'>\n					{$this->lang->words[\'col_starter\']}:\n					<if test=\"folderStarter:|:$msg[\'_starterMemberData\'][\'members_display_name\']\">\n						{$msg[\'_starterMemberData\'][\'members_display_name\']}\n					<else />\n						<em>{$this->lang->words[\'deleted_user\']}</em>\n					</if>\n					<if test=\"folderBannedIndicator:|:!$msg[\'map_user_banned\']\">\n						&middot; {parse expression=\"intval( $msg[\'mt_replies\'] )\"} {$this->lang->words[\'col_replies\']}\n					</if>			\n				</span>\n			</div>\n		</div>\n	</foreach>\n<else />\n	<div class=\'row no_messages\'>\n		{$this->lang->words[\'folder_no_messages_row\']}\n	</div>\n</if>\n<!--<div class=\'controls\'>\n<div class=\"buttons\">\n	<a href=\'{parse url=\"module=messaging&amp;section=send&amp;do=form\" base=\"publicWithApp\"}\' class=\'button\' title=\'{$this->lang->words[\'go_to_compose\']}\'>{$this->lang->words[\'compose_new\']}</a>\n	{$pages}\n</div>\n</div>-->', 'showFolder', '$messages, $dirname, $pages, $currentFolderID, $jumpFolderHTML', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('482', '0', 'skin_messaging', '<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.messenger.curFolder = \'in\';\n//]]>\n</script>\n<if test=\"searchError:|:$error\">\n	<p class=\'message error\'>\n		{$error}\n	</p>\n	<br />\n</if>\n<div class=\'topic_controls\'>\n{$pages}\n</div>\n<br />\n<h2 class=\'maintitle clear\'>{$this->lang->words[\'your_search_results\']}</h2>\n<div id=\'message_list\'>\n		<table class=\'ipb_table\' id=\'message_table\'>\n			<tr class=\'header\'>\n				<th scope=\'col\' class=\'col_m_status\'>&nbsp;</th>\n				<th scope=\'col\' class=\'col_m_subject\'>{$this->lang->words[\'col_subject\']}</th>\n				<th scope=\'col\' class=\'col_m_replies short\'>{$this->lang->words[\'col_replies\']}</th>\n				<th scope=\'col\' class=\'col_m_sender\'>{$this->lang->words[\'col_recipient\']}</th>\n				<th scope=\'col\' class=\'col_m_date\'>{$this->lang->words[\'col_date\']}</th>\n			</tr>\n		\n			<if test=\"searchMessages:|:count( $messages )\">\n				{parse striping=\"msg_stripe\" classes=\"row1,row2\"}\n				<foreach loop=\"messages:$messages as $id => $msg\">\n					<tr id=\'{$msg[\'mt_id\']}\' class=\'{parse striping=\"msg_stripe\"}\'>\n						<td class=\'altrow short\'>\n						</td>\n						<td>\n							<span class=\'m_title\'>\n								<if test=\"searchHasUnread:|:$msg[\'map_has_unread\'] == 1\">\n									<strong>\n								</if>\n								<a href=\"{parse url=\"app=members&amp;module=messaging&amp;section=view&amp;do=showConversation&amp;topicID={$msg[\'mt_id\']}\" base=\"public\"}\">{$msg[\'mt_title\']}</a>\n								<if test=\"searchEndHasUnread:|:$msg[\'map_has_unread\'] == 1\">\n									</strong>\n								</if>\n								<p>{$this->lang->words[\'label_pc\']} {$msg[\'_folderName\']}</p>\n							</span>\n						</td>\n						<td>\n							<span class=\'desc\'>{parse expression=\"intval( $msg[\'mt_replies\'] )\"}</span>\n						</td>\n						<td class=\'altrow\'>\n							<if test=\"searchToMember:|:$msg[\'_toMemberData\'][\'member_id\']\">\n								<a href=\'{parse url=\"showuser={$msg[\'_toMemberData\'][\'member_id\']}\" base=\"public\"}\'>{$msg[\'_toMemberData\'][\'members_display_name\']}</a>\n								<if test=\"searchInvitedCount:|:$msg[\'mt_invited_count\']\">\n									<if test=\"searchFixPlural:|:$msg[\'mt_invited_count\'] > 1\">\n										<p>({$this->lang->words[\'pc_and\']} {$msg[\'mt_invited_count\']} {$this->lang->words[\'pc_others\']})</p>\n									<else />\n										<p>({$this->lang->words[\'pc_and\']} {$msg[\'mt_invited_count\']} {$this->lang->words[\'pc_other\']})</p>\n									</if>\n								</if>\n							<else />\n								<span class=\'desc\'>{$this->lang->words[\'deleted_user\']}</span>\n							</if>\n						</td>\n						<td>\n							{parse date=\"$msg[\'mt_last_post_time\']\" format=\"long\"}\n						</td>\n					</tr>\n				</foreach>\n			<else />\n				<tr>\n					<td colspan=\'5\' class=\'no_messages row1\'>\n						{$this->lang->words[\'no_messages_row\']}\n					</td>\n				</tr>\n			</if>\n		</table>\n	</form>\n</div>', 'showSearchResults', '$messages, $pages, $error', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('483', '0', 'skin_mlist', '<div class=\'master_list\' id=\'member_list\'>\n	\n	<h2>{$this->lang->words[\'mlist_header\']}</h2>\n	<div class=\'controls\'>\n<div class=\"buttons\">\n<a class=\"button page-button\" id=\"filter-option\">Filter &raquo;</a></div>\n<div id=\"filter-letters\">\n		<foreach loop=\"chars:range(65,90) as $char\">\n			<if test=\"letterdefault:|:$letter = strtoupper(chr($char))\"></if>\n				<if test=\"selected:|:strtoupper( $this->request[\'quickjump\'] ) == $letter\">\n					<span class=\'letter-page active\'><strong>{$letter}</strong></span>&nbsp;\n				<else />\n					<span class=\"letter-page\"><a href=\'{parse url=\"app=members&amp;{$url}&amp;quickjump={$letter}\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'mlist_view_start_title\']} {$letter}\'>{$letter}</a></span>&nbsp;\n				</if>\n		</foreach>\n</div>\n</div>\n	<if test=\"showmembers:|:is_array( $members ) and count( $members )\">\n		{parse striping=\"memberStripe\" classes=\"row1,row2\"}\n		<foreach loop=\"members:$members as $member\">\n			<div class=\'row touch-row\' id=\"mem-{$member[\'member_id\']}\">\n				<div class=\'icon\'>\n					<a href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><img src=\'{$member[\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\" class=\'photo\' /></a>	\n				</div>\n				<strong><a class=\'title\' href=\'{parse url=\"showuser={$member[\'member_id\']}\" template=\"showuser\" seotitle=\"{$member[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$member[\'members_display_name\']}</a></strong>\n				<br />\n				<span class=\'subtext\'>{parse format_number=\"$member[\'posts\']\"} {$this->lang->words[\'member_posts\']} &middot; {$this->lang->words[\'member_group\']}: {IPSMember::makeNameFormatted( $member[\'group\'], $member[\'member_group_id\'] )}\n				 &middot; <a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\'>{parse replacement=\"find_topics_link\"} {$this->lang->words[\'gbl_find_my_content\']}</a></span>\n			</div>\n		</foreach>\n	<else />\n		<div class=\'no_messages\'>\n			{$this->lang->words[\'no_results\']}\n		</div>\n	</if>\n	\n	<div class=\'controls\'><div class=\"buttons\">\n		{$pages}\n	</div></div>\n</div>', 'member_list_show', '$members, $pages=\"\", $dropdowns=array(), $defaults=array(), $custom_fields=null, $url=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('484', '0', 'skin_online', '<div class=\'topic_controls\'>\n	{$links}\n</div>\n<h2 class=\'maintitle\'>{$this->lang->words[\'page_title\']}</h2>\n<table class=\'ipb_table\' summary=\"{$this->lang->words[\'users_online\']}\">\n	<tr class=\'header\'>\n		<th scope=\'col\' width=\'55\'>&nbsp;</th>\n		<th scope=\'col\'>{$this->lang->words[\'member_name\']}</th>\n		<th scope=\'col\'>{$this->lang->words[\'where\']}</th>\n		<th scope=\'col\'>{$this->lang->words[\'time\']}</th>\n		<th scope=\'col\'>&nbsp;</th>\n	</tr>\n	<if test=\"onlineusers:|:count($rows)\">\n		{parse striping=\"online\" classes=\"row1,row2\"}\n		<foreach loop=\"online:$rows as $session\">\n			<tr>\n				<td class=\'row1\'>\n					<img src=\'{$session[\'_memberData\'][\'pp_thumb_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'], $session[\'_memberData\'][\'members_display_name\'] ? $session[\'_memberData\'][\'members_display_name\'] : $this->lang->words[\'global_guestname\'] )\"}\" width=\'{$session[\'_memberData\'][\'pp_thumb_width\']}\' height=\'{$session[\'_memberData\'][\'pp_thumb_height\']}\' class=\'photo\' />\n				</td>\n				<td class=\'{parse striping=\"online\"}\'>\n					<if test=\"username:|:$session[\'member_name\']\">\n						<if test=\"userid:|:$session[\'member_id\']\">\n							<a href=\'{parse url=\"showuser={$session[\'member_id\']}\" template=\"showuser\" seotitle=\"{$session[\'seo_name\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{IPSMember::makeNameFormatted( $session[\'member_name\'], $session[\'member_group\'] )}</a>{parse template=\"user_popup\" group=\"global\" params=\"$session[\'member_id\'],$session[\'seo_name\']\"}\n						<else />\n							{IPSMember::makeNameFormatted( $session[\'member_name\'], $session[\'member_group\'] )}\n						</if>\n					<else />\n						{$this->lang->words[\'global_guestname\']}\n					</if>\n					<if test=\"anonymous:|:$session[\'login_type\'] == 1\">\n						<if test=\"viewanon:|:$this->memberData[\'g_access_cp\']\">\n							*\n						</if>\n					</if>\n					<if test=\"showip:|:$this->memberData[\'g_access_cp\']\">\n						<span class=\'ip\'>( {$session[\'ip_address\']} )</span>\n					</if>\n				</td>\n				<td class=\'{parse striping=\"online\"}\'>\n					<if test=\"nowhere:|:!$session[\'where_line\'] || $session[\'in_error\']\">\n						{$this->lang->words[\'board_index\']}\n					<else />\n						<if test=\"wheretext:|:$session[\'where_link\'] AND !$session[\'where_line_more\']\">\n							<a href=\'{parse url=\"{$session[\'where_link\']}\" base=\"public\"}\'>\n						</if>\n						{$session[\'where_line\']} \n						<if test=\"moredetails:|:$session[\'where_line_more\']\">\n							&nbsp;\n							<if test=\"wheretextseo:|:$session[\'_whereLinkSeo\']\">\n								<a href=\'{$session[\'_whereLinkSeo\']}\'>\n							<else />\n								<if test=\"detailslink:|:$session[\'where_link\']\"><a href=\'{parse url=\"{$session[\'where_link\']}\" base=\"public\"}\'></if>\n							</if>\n							{$session[\'where_line_more\']}\n							<if test=\"enddetailslink:|:$session[\'where_link\']\"></a></if>\n						<else />\n							<if test=\"nomoreenddetailslink:|:$session[\'where_link\']\"></a></if>\n						</if>\n					</if>\n				</td>\n				<td class=\'{parse striping=\"online\"}\'>\n					{parse date=\"$session[\'running_time\']\" format=\"long\" relative=\"false\"}\n				</td>\n				<td class=\'{parse striping=\"online\"}\'>\n					<if test=\"options:|:$session[\'member_id\'] AND $session[\'member_name\']\">\n						<ul class=\'user_controls clear\'>\n							<if test=\"notus:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $session[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n								<if test=\"addfriend:|:IPSMember::checkFriendStatus( $session[\'member_id\'] )\">\n									<li class=\'mini_friend_toggle is_friend\' id=\'friend_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$session[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n								<else />\n									<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$session[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n								</if>\n							</if>\n							<if test=\"sendpm:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $session[\'member_id\'] AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n								<li class=\'pm_button\' id=\'pm_online_{$session[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_member\']}\'>{parse replacement=\"send_msg\"}</a></li>\n							</if>\n							<if test=\"blog:|:$session[\'memberData\'][\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n								<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n							</if>\n							<if test=\"gallery:|:$session[\'memberData\'][\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n								<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$session[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n							</if>\n						</ul>\n					<else />\n						<span class=\'desc\'>{$this->lang->words[\'no_options_available\']}</span>\n					</if>\n				</td>\n			</tr>\n		</foreach>\n	</if>\n</table>\n<div id=\'forum_filter\' class=\'filter_bar rounded\'>\n	<form method=\"post\" action=\"{parse url=\"app=members&amp;section=online&amp;module=online\" base=\"public\"}\">\n		<label for=\'sort_key\'>{$this->lang->words[\'s_by\']}</label>\n		<select name=\"sort_key\" id=\'sort_key\' class=\'input_select\'>\n			<foreach loop=\"sort_key:array( \'click\', \'name\' ) as $sort\">\n				<option value=\'{$sort}\'<if test=\"defaultsort:|:$defaults[\'sort_key\'] == $sort\"> selected=\'selected\'</if>>{$this->lang->words[\'s_sort_key_\' . $sort ]}</option>\n			</foreach>\n		</select>\n		<select name=\"show_mem\" class=\'input_select\'>\n			<foreach loop=\"show_mem:array( \'reg\', \'guest\', \'all\' ) as $filter\">\n				<option value=\'{$filter}\'<if test=\"defaultfilter:|:$defaults[\'show_mem\'] == $filter\"> selected=\'selected\'</if>>{$this->lang->words[\'s_show_mem_\' . $filter ]}</option>\n			</foreach>\n		</select>\n		<select name=\"sort_order\" class=\'input_select\'>\n			<foreach loop=\"sort_order:array( \'desc\', \'asc\' ) as $order\">\n				<option value=\'{$order}\'<if test=\"defaultorder:|:$defaults[\'sort_order\'] == $order\"> selected=\'selected\'</if>>{$this->lang->words[\'s_sort_order_\' . $order ]}</option>\n			</foreach>\n		</select>\n		<input type=\"submit\" value=\"{$this->lang->words[\'s_go\']}\" class=\"input_submit alt\" />\n	</form>\n</div>\n<br />\n<div class=\'topic_controls\'>\n	{$links}\n</div>', 'showOnlineList', '$rows, $links=\"\", $defaults=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('485', '0', 'skin_profile', '<dt>{$f->raw_data[\'pf_title\']}:</dt>\n<dd>\n<if test=\"gender_set:|:$f->value\">\n	<if test=\"male:|:$f->value == \'m\'\">\n		<img src=\'{$this->settings[\'img_url\']}/profile/male.png\' alt=\'{$this->lang->words[\'js_gender_male\']}\' /> {$this->lang->words[\'js_gender_male\']}\n	</if>\n	\n	<if test=\"female:|:$f->value == \'f\'\">\n		<img src=\'{$this->settings[\'img_url\']}/profile/female.png\' alt=\'{$this->lang->words[\'js_gender_female\']}\' /> {$this->lang->words[\'js_gender_female\']}\n	</if>\n	\n	<if test=\"nottelling:|:$f->value ==\'u\'\">\n		<img src=\'{$this->settings[\'img_url\']}/profile/mystery.png\' alt=\'{$this->lang->words[\'js_gender_mystery\']}\' /> {$this->lang->words[\'js_gender_mystery\']}\n	</if>\n<else />\n	{$this->lang->words[\'m_no_gender\']}\n</if>\n</dd>', 'customField__gender', '$f', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('486', '0', 'skin_profile', '<if test=\"$f->parsed != \'\'\">\n	<dt>{$f->raw_data[\'pf_title\']}:</dt>\n	<dd>\n		<if test=\"genericIsArray:|:is_array($f->parsed)\">\n			{parse expression=\"implode( \'<br />\', $f->parsed )\"}\n		<else />\n			{$f->parsed}\n		</if>\n	</dd>\n</if>', 'customField__generic', '$f', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('487', '0', 'skin_profile', '<if test=\"contact_field:|:$f->parsed\">\n<dt>{$f->raw_data[\'pf_title\']}:</dt>\n<dd>\n	<if test=\"cf_icon:|:$f->raw_data[\'pf_icon\']\"><img src=\'{$this->settings[\'public_dir\']}{$f->raw_data[\'pf_icon\']}\' alt=\'{$f->raw_data[\'pf_title\']}\' />&nbsp;</if>\n	<if test=\"cf_array:|:is_array( $f->parsed )\">\n		<foreach loop=\"cfieldgroups:$f->parsed as $value\">\n			{$value}\n		</foreach>\n	<else />\n		<if test=\"cf_aim:|:$f->raw_data[\'pf_key\'] == \'aim\'\">\n			<a class=\'url\' href=\'aim:goim?screenname={$f->parsed}\'>{$f->parsed}</a>\n		<else />\n			<if test=\"cf_msn:|:$f->raw_data[\'pf_key\'] == \'msn\'\">\n				<a class=\'url\' href=\'msnim:chat?contact={$f->parsed}\'>{$f->parsed}</a>\n			<else />\n				<if test=\"cf_yahoo:|:$f->raw_data[\'pf_key\'] == \'yahoo\'\">\n					<a class=\'url\' href=\'ymsgr:sendIM?{$f->parsed}\'>{$f->parsed}</a>\n				<else />\n					<if test=\"cf_icq:|:$f->raw_data[\'pf_key\'] == \'icq\'\">\n						<a class=\'url\' type=\"application/x-icq\" href=\'http://www.icq.com/people/cmd.php?uin={$f->parsed}&amp;action=message\'>{$f->parsed}</a>\n					<else />\n						<if test=\"cf_website:|:$f->raw_data[\'pf_key\'] == \'website\'\">\n							<a class=\'url uid\' rel=\"me\" href=\'{$f->parsed}\'>{$f->parsed}</a>\n						<else />\n							<if test=\"cf_jabber:|:$f->raw_data[\'pf_key\'] == \'jabber\'\">\n								<a class=\'url\' href=\'xmpp:{$f->parsed}\'>{$f->parsed}</a>\n							<else />\n								<if test=\"cf_skype:|:$f->raw_data[\'pf_key\'] == \'skype\'\">\n									<a class=\'url\' href=\'skype:{$f->parsed}?call\'>{$f->parsed}</a>\n								<else />\n									{$f->parsed}\n								</if>\n							</if>\n						</if>\n					</if>\n				</if>\n			</if>\n		</if>\n	</if>\n</dd>\n</if>', 'customFieldGroup__contact', '$f', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('488', '0', 'skin_profile', '<!--no data in this master skin-->', 'customizeProfile', '$member', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('489', '0', 'skin_profile', '<if test=\"$this->request[\'module\']==\'ajax\'\">\n	<h3>{$this->lang->words[\'dname_window_title\']} {$member_name}</h3>\n<else />\n	<h3 class=\'maintitle\'>{$this->lang->words[\'dname_window_title\']} {$member_name}</h3>\n</if>\n<table class=\'ipb_table\'>\n	<tr class=\'header\'>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_name_from\']}</th>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_name_to\']}</th>\n		<th scope=\'col\' style=\'width: 33%\'>{$this->lang->words[\'dname_date\']}</th>\n	</tr>\n	<if test=\"hasDnameHistory:|:is_array($records) AND count($records)\">\n		{parse striping=\"dname\" classes=\"row1,row2\"}\n    	<foreach loop=\"records:$records as $row\">\n		<tr class=\'{parse striping=\"dname\"}\'>\n		 	<td>{$row[\'dname_previous\']}</td>\n		 	<td><strong>{$row[\'dname_current\']}</strong></td>\n		 	<td class=\'altrow\'>{parse date=\"$row[\'dname_date\']\" format=\"short\"}</td>\n		</tr>\n		</foreach>\n	<else />\n		<tr>\n			<td colspan=\'3\' class=\'no_messages\'>{$this->lang->words[\'dname_no_history\']}</td>\n		</tr>\n    </if>\n</table>', 'dnameWrapper', '$member_name=\"\",$records=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('490', '0', 'skin_profile', '<if test=\"friendIframeWrapper:|:$showWrapper\">\n		<div class=\'friend_list\'>\n	</if>\n		<h3 class=\'bar\'>Friends</h3>\n		<if test=\"friendIframeLoop:|:is_array($friends) and count($friends)\">\n			<ul>\n			<foreach loop=\"friendsIframe:$friends as $friend\">\n				<li>\n					<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_display_name_short\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' ><img src=\'{$friend[\'pp_thumb_photo\']}\' width=\'{$friend[\'pp_thumb_width\']}\' height=\'{$friend[\'pp_thumb_height\']}\' alt=\'Photo\' class=\'photo\' /></a><br />\n					<span class=\'name\'><a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$friend[\'members_display_name_short\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$friend[\'member_id\'], $friend[\'members_seo_name\']\"}</span>\n				</li>\n			</foreach>\n			</ul>\n		<else />\n			<p>\n				<em>{$member[\'members_display_name\']} {$this->lang->words[\'no_friends_yet\']}</em>\n			</p>\n		</if>\n	<if test=\"friendIframeEndWrapper:|:$showWrapper\">\n		</div>\n	</if>', 'friendsIframe', '$member, $friends, $showWrapper=false', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('491', '0', 'skin_profile', '{parse js_module=\"friends\"}\n<h2>{$this->lang->words[\'m_friends_list\']}</h2>\n<if test=\"friendListPages:|:$pages\">\n	<div class=\'topic_controls\'>\n		$pages\n	</div>\n</if>\n<ul class=\'tab_bar no_title\'>\n	<if test=\"tabIsList:|:$this->request[\'tab\'] == \'list\' || !$this->request[\'tab\']\">\n		<li class=\'active\'><strong>{$this->lang->words[\'m_friends_list\']}</strong></li>\n		<li><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=pending\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_pending\']}\'>{$this->lang->words[\'m_friends_pending\']}</a></li>\n	</if>\n	<if test=\"tabIsPending:|:$this->request[\'tab\'] == \'pending\'\">\n		<li><a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=list&amp;tab=list\" base=\"public\"}\' title=\'{$this->lang->words[\'m_friends_list\']}\'>{$this->lang->words[\'m_friends_list\']}</a></li>\n		<li class=\'active\'><strong>{$this->lang->words[\'m_friends_pending\']}</strong></li>\n	</if>\n</ul>\n<if test=\"hasFriendsList:|:is_array($friends) and count($friends) && $this->settings[\'friends_enabled\']\">\n	{parse striping=\"memberStripe\" classes=\"row1,row2\"}\n	<ul class=\'members\'>\n	<foreach loop=\"friendsList:$friends as $friend\">\n		<if test=\"loopOnPending:|:$this->request[\'tab\'] == \'pending\'\">\n			<li id=\'member_id_{$friend[\'member_id\']}\' class=\'general_box clear member_entry {parse striping=\"memberStripe\"}\'>\n				<h3 class=\'bar\'><a href=\'{parse url=\"showuser={$friend[\'friends_member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$friend[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$friend[\'member_id\'],$friend[\'members_seo_name\']\"}</h3>\n				<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><img src=\'{$friend[\'pp_thumb_photo\']}\' width=\'{$friend[\'pp_thumb_width\']}\' height=\'{$friend[\'pp_thumb_height\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$friend[\'members_display_name\'])\"}\" class=\'photo\' /></a>	\n			\n				<dl class=\'info\'>\n					<dt class=\'clear\'>{$this->lang->words[\'m_member_since\']}</dt>\n					<dd>{parse date=\"$friend[\'joined\']\" format=\"short\"}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_group\']}</dt>\n					<dd>{$friend[\'_group_formatted\']}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_posts\']}</dt>\n					<dd>{parse format_number=\"$friend[\'posts\']\"}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_last_active\']}</dt>\n					<dd>{parse date=\"$friend[\'last_activity\']\" format=\"short\"}</dd>\n				</dl>\n				\n				<ul class=\'user_controls clear\'>\n					<li class=\'positive\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=moderate&amp;pp_option=approve&amp;pp_friend_id[{$friend[\'member_id\']}]=1&amp;md5check={$this->member->form_hash}\" base=\"public\"}\' title=\'Approve\'>{parse replacement=\"approve\"} {$this->lang->words[\'approve_request\']}</a></li>\n					<li class=\'negative\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=moderate&amp;pp_option=delete&amp;pp_friend_id[{$friend[\'member_id\']}]=1&amp;md5check={$this->member->form_hash}\" base=\"public\"}\' title=\'Deny\'>{parse replacement=\"deny\"} {$this->lang->words[\'deny_request\']}</a></li>\n				</ul>\n				<if test=\"friendListRate:|:$this->settings[\'pp_allow_member_rate\']\">\n					<p class=\'rating\'> \n						<if test=\"friendListRate1:|:$friend[\'pp_rating_real\'] >= 1\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRate2:|:$friend[\'pp_rating_real\'] >= 2\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRate3:|:$friend[\'pp_rating_real\'] >= 3\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRate4:|:$friend[\'pp_rating_real\'] >= 4\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRate5:|:$friend[\'pp_rating_real\'] >= 5\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if>\n					</p>\n				</if>\n				\n				<if test=\"friendListRep:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n					<if test=\"friendListRepPos:|:$friend[\'pp_reputation_points\'] > 0\">\n						<p class=\'reputation positive\'>\n					</if>\n					<if test=\"friendListRepNeg:|:$friend[\'pp_reputation_points\'] < 0\">\n						<p class=\'reputation negative\'>\n					</if>\n					<if test=\"friendListRepZero:|:$friend[\'pp_reputation_points\'] == 0\">\n						<p class=\'reputation zero\'>\n					</if>\n							<span class=\'number\'>{$this->lang->words[\'m_reputation\']} {$friend[\'pp_reputation_points\']}</span>\n						</p>\n				</if>						\n			</li>\n		<else />\n			<li id=\'member_id_{$friend[\'friends_friend_id\']}\' class=\'general_box clear member_entry {parse striping=\"memberStripe\"}\'>\n				<h3 class=\'bar\'><a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$friend[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$friend[\'member_id\'],$friend[\'members_seo_name\']\"}</h3>\n				<a href=\'{parse url=\"showuser={$friend[\'member_id\']}\" seotitle=\"{$friend[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><img src=\'{$friend[\'pp_thumb_photo\']}\' width=\'{$friend[\'pp_thumb_width\']}\' height=\'{$friend[\'pp_thumb_height\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$friend[\'members_display_name\'])\"}\" class=\'photo\' /></a>	\n			\n				<dl class=\'info\'>\n					<dt class=\'clear\'>{$this->lang->words[\'m_member_since\']}</dt>\n					<dd>{parse date=\"$friend[\'joined\']\" format=\"short\"}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_group\']}</dt>\n					<dd>{$friend[\'_group_formatted\']}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_posts\']}</dt>\n					<dd>{parse format_number=\"$friend[\'posts\']\"}</dd>\n					<dt class=\'clear\'>{$this->lang->words[\'m_last_active\']}</dt>\n					<dd>{parse date=\"$friend[\'last_activity\']\" format=\"short\"}</dd>\n				</dl>\n				\n				<ul class=\'user_controls clear\'>\n					<if test=\"friendListIsMember:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $friend[\'friends_friend_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n						<if test=\"friendListIsFriend:|:IPSMember::checkFriendStatus( $friend[\'friends_friend_id\'] )\">\n							<li class=\'mini_friend_toggle is_friend\' id=\'friend_profile_{$friend[\'friends_friend_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$friend[\'friends_friend_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_as_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n						<else />\n							<li class=\'mini_friend_toggle is_not_friend\' id=\'friend_profile_{$friend[\'friends_friend_id\']}\'><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$friend[\'friends_friend_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_me_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n						</if>\n					</if>\n					<if test=\"friendListSendPm:|:$this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n						<li class=\'pm_button\' id=\'pm_xxx_{$friend[\'friends_friend_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$friend[\'friends_member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_this_member\']}\'>{parse replacement=\"send_msg\"}</a></li>\n					</if>\n					<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_posts&amp;mid={$friend[\'friends_friend_id\']}&amp;view_by_title=1&amp;search_filter_app[forums]=1\" base=\"public\"}\'>{$this->lang->words[\'find_topics\']}</a></li>\n					<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_posts&amp;mid={$friend[\'friends_friend_id\']}<if test=\"friendListSearchType:|:! in_array( $this->settings[\'search_method\'], array( \'traditional\', \'sphinx\' ) )\">&amp;search_filter_app[forums]=1</if>\" base=\"public\"}\'>{$this->lang->words[\'find_posts\']}</a></li>\n					<if test=\"friendListBlog:|:$friend[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' )\">\n						<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$friend[\'friends_friend_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n					</if>\n					<if test=\"friendListGallery:|:$friend[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n						<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$friend[\'friends_friend_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n					</if>\n				</ul>\n				<if test=\"friendListAllowRate:|:$this->settings[\'pp_allow_member_rate\']\">\n					<p class=\'rating\'> \n						<if test=\"friendListRateApp1:|:$friend[\'pp_rating_real\'] >= 1\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRateApp2:|:$friend[\'pp_rating_real\'] >= 2\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRateApp3:|:$friend[\'pp_rating_real\'] >= 3\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRateApp4:|:$friend[\'pp_rating_real\'] >= 4\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if><if test=\"friendListRateApp5:|:$friend[\'pp_rating_real\'] >= 5\">{parse replacement=\"rate_on\"}<else />{parse replacement=\"rate_off\"}</if>\n					</p>\n				</if>\n				\n				<if test=\"friendListAppRep:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n					<if test=\"friendListAppRepPos:|:$friend[\'pp_reputation_points\'] > 0\">\n						<p class=\'reputation positive\'>\n					</if>\n					<if test=\"friendListAppRepNeg:|:$friend[\'pp_reputation_points\'] < 0\">\n						<p class=\'reputation negative\'>\n					</if>\n					<if test=\"friendListAppRepZero:|:$friend[\'pp_reputation_points\'] == 0\">\n						<p class=\'reputation zero\'>\n					</if>\n							<span class=\'number\'>{$this->lang->words[\'m_reputation\']} {$friend[\'pp_reputation_points\']}</span>\n						</p>\n				</if>						\n			</li>\n		</if>\n		\n	</foreach>\n	</ul>\n<else />\n	<p class=\'no_messages\'>\n		<if test=\"friendListNone:|:$this->request[\'tab\'] == \'pending\'\">\n			{$this->lang->words[\'no_friends_awaiting_approval\']}\n		<else />\n			{$this->lang->words[\'no_friends_to_display\']}\n		</if>\n	</p>\n</if>\n<if test=\"friendListPagesBottom:|:$pages\">\n	<div class=\'topic_controls\'>\n		$pages\n	</div>\n</if>', 'friendsList', '$friends, $pages', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('492', '0', 'skin_profile', '<!--no data in this master skin-->', 'photoEditor', '$data, $member', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('493', '0', 'skin_profile', '<div class=\'master_list\'>\n	<h2>{parse expression=\"sprintf( $this->lang->words[\'their_profile\'], $member[\'members_display_name\'] )\"}</h2>	\n	<div class=\'row\'>\n		<img class=\"photo\" src=\'{$member[\'pp_main_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$member[\'members_display_name\'])\"}\"  />\n	</div>\n	\n	<h3>{$this->lang->words[\'my_info\']}</h3>\n	<div class=\'row line_spacing\'>\n		<strong>{$this->lang->words[\'m_group\']}</strong> {$member[\'g_title\']}<br />\n		<strong>{$this->lang->words[\'m_posts\']}</strong> {parse format_number=\"$member[\'posts\']\"}<if test=\"showProfileStats2:|:!$this->settings[\'disable_profile_stats\']\"> ({$member[\'_posts_day\']} {$this->lang->words[\'posts_per_day\']})</if><br />\n		<strong>{$this->lang->words[\'m_member_since\']}</strong> {parse date=\"$member[\'joined\']\" format=\"joined\"}<br />\n		<strong>{$this->lang->words[\'m_last_active\']}</strong> {$member[\'_last_active\']}\n	</div>\n	\n	<h3>{$this->lang->words[\'my_info\']}</h3>\n	<div class=\'row line_spacing\'>\n		<if test=\"member_title:|:$member[\'title\'] != \'\'\">\n			<strong>{$this->lang->words[\'m_member_title\']}</strong> {$member[\'title\']}<br />\n		</if>\n		<strong>{$this->lang->words[\'m_age_prefix\']}</strong> \n		<if test=\"member_age:|:$member[\'_age\'] > 0\">\n			{$member[\'_age\']} {$this->lang->words[\'m_years_old\']}\n		<else />\n			{$this->lang->words[\'m_age_unknown\']}\n		</if>\n		<br />\n		<strong>{$this->lang->words[\'m_birthday_prefix\']}</strong> \n		<if test=\"member_birthday:|:$member[\'bday_day\']\">\n			<!-- SKINNOTE: We should use the localized date formatting for this -->\n			{$member[\'_bday_month\']} {$member[\'bday_day\']}<if test=\"member_bday_year:|:$member[\'bday_year\']\">, {$member[\'bday_year\']}</if>\n		<else />\n			{$this->lang->words[\'m_bday_unknown\']}\n		</if>\n	</div>\n	\n	<h3>{$this->lang->words[\'user_controls\']}</h3>\n	<div class=\'row line_spacing\'>\n		<if test=\"noFriendYourself:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n			<if test=\"isFriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n				<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=remove&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{$this->lang->words[\'remove_as_friend\']}</a>\n			<else />\n				<a href=\'{parse url=\"app=members&amp;section=friends&amp;module=profile&amp;do=add&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{$this->lang->words[\'add_me_friend\']}</a>\n			</if>\n			<br />\n		</if>\n		<if test=\"pmlink:|:($member[\'member_id\'] != $this->memberData[\'member_id\']) AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n			<a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_this_member\']}\'>{$this->lang->words[\'send_message\']}</a>\n			<br />\n		</if>\n		<a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_activity&amp;mid={$member[\'member_id\']}\" base=\"public\"}\'>{parse replacement=\"find_topics_link\"} {$this->lang->words[\'gbl_find_my_content\']}</a>\n	</div>\n</div>', 'profileModern', '$tabs=array(), $member=array(), $comments=\"\", $friends=array(), $visitors=array(), $default_tab=\'posts\', $default_tab_content=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('494', '0', 'skin_profile', '<div class=\'vcard userpopup\'>\n	<h3><a href=\"{parse url=\"showuser={$member[\'member_id\']}\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\" class=\"fn nickname url\">{$member[\'members_display_name\']}</a></h3>\n	<div>\n		<if test=\"cardStatus:|:$member[\'pp_status\']\">\n			<p class=\'message user_status\'>{parse replacement=\"user_status\"}&nbsp; <strong>{$member[\'members_display_name\']}</strong> {$member[\'pp_status\']}</p>\n		</if>\n		<div class=\'info\'>\n			<img class=\'photo\' src=\"{$member[\'pp_thumb_photo\']}\" alt=\"{$this->lang->words[\'get_photo\']}\" width=\'{$member[\'pp_thumb_width\']}\' height=\'{$member[\'pp_thumb_height\']}\' alt=\'photo\' />\n			<dl>\n				<dt>{$this->lang->words[\'m_group\']}</dt>\n				<dd>{$member[\'g_title\']}</dd>\n				<dt>{$this->lang->words[\'m_posts\']}</dt>\n				<dd title=\'{$member[\'_posts_day\']} {$this->lang->words[\'posts_per_day\']}\'>{parse format_number=\"$member[\'posts\']\"}</dd>\n				<dt>{$this->lang->words[\'m_member_since\']}</dt>\n				<dd>{parse date=\"$member[\'joined\']\" format=\"joined\"}</dd>\n				<dt>{$this->lang->words[\'m_last_active\']}</dt>\n				<dd><if test=\"cardOnline:|:$member[\'_online\']\">{parse replacement=\"user_online\"}<else />{parse replacement=\"user_offline\"}</if> {$member[\'_last_active\']}</dd>\n				<dt>{$this->lang->words[\'m_currently\']}</dt>\n				<dd><if test=\"cardWhere:|:$member[\'_online\']\">\n						{$member[\'online_extra\']}\n					<else />\n						{$this->lang->words[\'online_offline\']}\n					</if>\n				</dd>\n				<if test=\"isadmin:|:$this->memberData[\'g_access_cp\'] == 1\">\n					<dt>{$this->lang->words[\'m_email\']}</dt>\n					<dd><a href=\'mailto:{$member[\'email\']}\'>{$member[\'email\']}</a></dd>\n				</if>\n			</dl>\n		</div>\n		\n		<ul class=\'user_controls clear\'>\n			<if test=\"authorspammer:|:$member[\'spamStatus\'] !== NULL && $member[\'member_id\'] != $this->memberData[\'member_id\']\">\n				<if test=\"authorspammerinner:|:$member[\'spamStatus\'] === TRUE\">\n					<li><a href=\'#\' title=\'{$this->lang->words[\'spm_on\']}\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, false)\">{parse replacement=\"spammer_on\"}</a></li>\n				<else />\n					<li><a title=\'{$this->lang->words[\'spm_off\']}\' href=\'{$this->settings[\'base_url\']}app=core&amp;module=modcp&amp;section=editmember&amp;do=setAsSpammer&amp;member_id={$member[\'member_id\']}&amp;auth_key={$this->member->form_hash}\' onclick=\"return ipb.global.toggleFlagSpammer({$member[\'member_id\']}, true)\">{parse replacement=\"spammer_off\"}</a></li>\n				</if>\n			</if>\n			<if test=\"cardFriend:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] && $this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n				<if test=\"cardIsFriend:|:IPSMember::checkFriendStatus( $member[\'member_id\'] )\">\n					<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=remove&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'remove_friend\']}\'>{parse replacement=\"remove_friend\"}</a></li>\n				<else />\n					<li><a href=\'{parse url=\"app=members&amp;module=profile&amp;section=friends&amp;do=add&amp;member_id={$member[\'member_id\']}&amp;secure_key={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'add_friend\']}\'>{parse replacement=\"add_friend\"}</a></li>								\n				</if>\n			</if>\n			<if test=\"cardSendPm:|:$this->memberData[\'member_id\'] AND $this->memberData[\'member_id\'] != $member[\'member_id\'] AND $this->memberData[\'g_use_pm\'] AND $this->memberData[\'members_disable_pm\'] == 0 AND IPSLib::moduleIsEnabled( \'messaging\', \'members\' )\">\n				<li class=\'pm_button\' id=\'pm_xxx_{$member[\'member_id\']}\'><a href=\'{parse url=\"app=members&amp;module=messaging&amp;section=send&amp;do=form&amp;fromMemberID={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'pm_this_member\']}\'>{parse replacement=\"send_msg\"}</a></li>\n			</if>\n			\n			<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_posts&amp;mid={$member[\'member_id\']}&amp;search_filter_app[forums]=1&amp;view_by_title=1\" base=\"public\"}\' title=\'{$this->lang->words[\'find_topics\']}\'>{parse replacement=\"find_topics_link\"}</a></li>		\n			<li><a href=\'{parse url=\"app=core&amp;module=search&amp;do=user_posts&amp;mid={$member[\'member_id\']}<if test=\"cardFindPostsLink:|:! in_array( $this->settings[\'search_method\'], array( \'traditional\', \'sphinx\' ) )\">&amp;search_filter_app[forums]=1</if>\" base=\"public\"}\' title=\'{$this->lang->words[\'find_posts\']}\'>{parse replacement=\"find_posts_link\"}</a></li>\n			<if test=\"cardBlog:|:$member[\'has_blog\'] AND IPSLib::appIsInstalled( \'blog\' ) && $member[\'has_blog\'] != \'recache\'\">\n				<li><a href=\'{parse url=\"app=blog&amp;module=display&amp;section=blog&amp;mid={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_blog\']}\'>{parse replacement=\"blog_link\"}</a></li>\n			</if>\n			<if test=\"cardGallery:|:$member[\'has_gallery\'] AND IPSLib::appIsInstalled( \'gallery\' )\">\n				<li><a href=\'{parse url=\"app=gallery&amp;module=user&amp;section=user&amp;user={$member[\'member_id\']}\" base=\"public\"}\' title=\'{$this->lang->words[\'view_gallery\']}\'>{parse replacement=\"gallery_link\"}</a></li>\n			</if>\n		</ul>\n		\n		\n		<if test=\"cardRep:|:$this->settings[\'reputation_enabled\'] && $this->settings[\'reputation_show_profile\']\">\n			<if test=\"cardRepPos:|:$member[\'pp_reputation_points\'] > 0\">\n				<div class=\'reputation positive\'>\n			</if>\n			<if test=\"cardRepNeg:|:$member[\'pp_reputation_points\'] < 0\">\n				<div class=\'reputation negative\'>\n			</if>\n			<if test=\"cardRepZero:|:$member[\'pp_reputation_points\'] == 0\">\n				<div class=\'reputation zero\'>\n			</if>\n					<span class=\'number\'>{$this->lang->words[\'m_reputation\']} {$member[\'pp_reputation_points\']}</span>\n				</div>\n		</if>\n	</div>\n</div>', 'showCard', '$member, $download=0', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('495', '0', 'skin_profile', '<if test=\"hasComments:|:is_array($comments) and count($comments)\">\n	<div id=\'comment_innerwrap\' class=\'comment_wrap clearfix\'>\n		<div class=\'topic_controls<if test=\"!$this->memberData[\'member_id\']\"> no-form</if>\'>\n			{$links}\n		</div>\n		<ol id=\'comment_list\' class=\'clear\'>\n		{parse striping=\"comments\" classes=\"row1,off\"}\n		<foreach loop=\"comments:$comments as $comment\">\n			<if test=\"commentCheckId:|:$new_id == 0 || $comment[\'comment_id\'] == $new_id\">\n				<li id=\'comment_id_{$comment[\'comment_id\']}\'>\n					<div class=\'comment clearfix {parse striping=\"comments\"} <if test=\"commentApproved:|:!$comment[\'comment_approved\']\"> moderated</if>\'>\n						<img src=\'{$comment[\'pp_thumb_photo\']}\' width=\'{$comment[\'pp_thumb_width\']}\' height=\'{$comment[\'pp_thumb_height\']}\' class=\'photo\' alt=\'{$this->lang->words[\'photo\']}\' />\n						<h4>\n							<a href=\"{parse url=\"showuser={$comment[\'member_id\']}\" template=\"showuser\" seotitle=\"{$comment[\'members_seo_name\']}\" base=\"public\"}\">{$comment[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$comment[\'member_id\'],$comment[\'members_seo_name\']\"}\n						</h4>\n						<span class=\'posted_date desc\'>\n							{$comment[\'_comment_date\']}\n						</span>\n						<div id=\'comment_{$comment[\'comment_id\']}\' class=\'comment_content\'>\n							{$comment[\'comment_content\']}\n						</div>\n						<if test=\"commentWeAreOwner:|:$this->memberData[\'member_id\'] == $member[\'member_id\'] OR $this->memberData[\'g_is_supmod\']\">\n							<ul class=\'comment_options\'>\n								<li>\n									<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=comments&amp;do=delete&amp;comment_id={$comment[\'comment_id\']}&amp;member_id={$member[\'member_id\']}&amp;authKey={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'delete_this_comment\']}\' class=\'delete_comment\'>{$this->lang->words[\'delete_comment_text\']}</a>\n								</li>\n								<if test=\"commentApprovLink:|:! $comment[\'comment_approved\']\">\n									<li>\n										<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=comments&amp;do=approve&amp;comment_id={$comment[\'comment_id\']}&amp;member_id={$member[\'member_id\']}&amp;authKey={$this->member->form_hash}\" base=\"public\"}\' title=\'{$this->lang->words[\'approve_this_comment\']}\'>{$this->lang->words[\'m_approve\']}</a>\n									</li>\n								</if>									\n							</ul>\n						</if>\n					</div>\n				</li>\n			</if>\n		</foreach>\n		</ol>\n		<div class=\'topic_controls\'>\n			{$links}\n		</div>\n	</div>\n	<if test=\"$new_id != 0\">\n		<div class=\'topic_controls\'>\n			{$links}\n		</div>\n	</if>\n</if>', 'showComments', '$member, $comments=array(), $new_id=0, $return_msg=\'\', $links=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('496', '0', 'skin_profile', '<div id=\'pp-iframe-wrap\' class=\'pp-contentbox-back\' style=\'overflow:auto\'>\n<form onsubmit=\'check_form()\' action=\'{parse url=\"app=members&amp;section=comments&amp;module=profile&amp;do=save&amp;member_id={$member[\'member_id\']}&amp;md5check={$this->member->form_hash}\" base=\"public\"}\' method=\'POST\'>\n	<if test=\"hasIframeComments:|:is_array($comments) and count($comments)\">\n		<foreach loop=\"commentsIframe:$comments as $comment\">\n			<if test=\"iframeCommentApproved:|:$comment[\'comment_approved\']\">\n				<div class=\'pp-contentbox-entry-noheight\' id=\'pp-comment-entry-main-{$comment[\'comment_id\']}\'>\n			<else />\n				<div class=\'pp-contentbox-entry-noheight-mod\' id=\'pp-comment-entry-main-{$comment[\'comment_id\']}\'>\n			</if>\n				<div class=\'pp-tiny-text\'>\n				<div class=\'pp-image-thumb-wrap-floatright\'><img src=\'{$comment[\'pp_thumb_photo\']}\' width=\'{$comment[\'pp_thumb_width\']}\' height=\'{$comment[\'pp_thumb_height\']}\' alt=\'\' /></div>\n					<if test=\"iframeCommentMod:|:( $member[\'member_id\'] == $this->memberData[\'member_id\'] ) OR ( $this->memberData[\'g_is_supmod\'] )\">\n						<!-- MOD CHECKBOX -->\n						<input type=\'checkbox\' class=\'input-checkbox\' id=\"pp-checked-{$comment[\'comment_id\']}\" name=\"pp-checked[{$comment[\'comment_id\']}]\" value=\'1\' onclick=\"parent.ips_personal_portal.toggle_comment_box(\'{$comment[\'comment_id\']}\', 1)\" />\n						<!-- / MOD CHECKBOX -->\n					</if>\n					<strong><if test=\"iframeCommentMember:|:$comment[\'member_id\']\"><a href=\'{parse url=\"showuser={$comment[\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$comment[\'members_seo_name\']}\"}\' target=\'_parent\'></if>{$comment[\'members_display_name\']}<if test=\"iframeEndMemberLink:|:$comment[\'member_id\']\"></a></if></strong>\n					<br />\n					{$comment[\'comment_content\']}\n					<br />\n					<strong>{$comment[\'_comment_date\']}</strong>\n				</div>\n			</div>\n		</foreach>\n		<div class=\'pp-contentbox-entry-noheight\'>\n			<div style=\'float:right\'>\n				<if test=\"iframeCommentsMulti:|:( $member[\'member_id\'] == $this->memberData[\'member_id\'] ) OR ( $this->memberData[\'g_is_supmod\'] )\">\n					<select name=\'pp-moderation\' id=\'pp-moderation\'>\n						<option value=\'approve\'>{$this->lang->words[\'m_comment_app\']}</option>\n						<option value=\'unapprove\'>{$this->lang->words[\'m_comment_unapp\']}</option>\n						<option value=\'delete\'>{$this->lang->words[\'m_comment_delete\']}</option>\n					</select>\n					<input type=\'submit\' class=\'button\' value=\'{$this->lang->words[\'m_go_button\']}\' />\n				</if>\n			</div>\n			<div style=\'margin-top:7px\'>{$pages}&nbsp;</div>\n	<else />\n		<div class=\'post1\' style=\'padding:6px\'>\n			<em>{$this->lang->words[\'m_no_comments\']} {$member[\'members_display_name\']}.</em>\n		</div>\n	</if>\n</form>\n</div>\n<br /><br /><br /> <!-- Gotta give room for page jump... -->\n<script type=\'text/javascript\'>\n//<![CDATA\nvar _saved = parseInt( \"{$this->request[\'_saved\']}\" );\nif ( _saved )\n{\n	parent.ips_personal_portal.reload_comments();\n}\n// Check form\nfunction check_form()\n{\n	var selectbox = document.getElementById(\'pp-moderation\');\n	var chosen    = selectbox.options[ selectbox.selectedIndex ].value;\n	\n	if ( chosen == \'delete\' )\n	{\n		if ( confirm(\"{$this->lang->words[\'m_confirm\']}\") )\n		{\n			return true;\n		}\n		else\n		{\n			return false;\n		}\n	}\n	else\n	{\n		return true;\n	}\n}\n//]]>\n</script>', 'showIframeComments', '$member, $comments, $pages', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('497', '0', 'skin_profile', '<foreach loop=\"innerLoop:$replies as $reply\">\n	<div id=\'statusReply-{$reply[\'reply_id\']}\' class=\'status_mini_wrap row2\'>\n		<div class=\"status_mini_photo\">\n			<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'><img src=\'{$reply[\'pp_mini_photo\']}\' width=\'{$reply[\'pp_mini_width\']}\' height=\'{$reply[\'pp_mini_height\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$reply[\'members_display_name\'])\"}\" class=\'photo\' /></a>	\n		</div>\n		<div class=\"status_mini_content\">\n			<a href=\'{parse url=\"showuser={$reply[\'member_id\']}\" seotitle=\"{$reply[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\' style=\'font-weight:bold\'>{$reply[\'members_display_name\']}</a> &middot; <span class=\'desc\'>{$reply[\'reply_date_formatted\']}<if test=\"canDelete:|:$reply[\'_canDelete\']\"> &middot; <a href=\"{$this->settings[\'base_url\']}app=members&amp;module=profile&amp;section=status&amp;do=deleteReply&amp;status_id={$reply[\'reply_status_id\']}&reply_id={$reply[\'reply_id\']}&amp;k={$this->member->form_hash}\" id=\"statusReplyDelete-{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\" class=\"__sDR __dr{$reply[\'reply_status_id\']}-{$reply[\'reply_id\']}\">{$this->lang->words[\'status_delete_link\']}</a></if></span>\n			<h5>{$reply[\'reply_content\']}</h5>\n		</div>\n	</div>\n</foreach>', 'statusReplies', '$replies=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('498', '0', 'skin_profile', '<foreach loop=\"outerLoop:$updates as $id => $status\">\n<div class=\"row touch-row clearfix\" id=\"update-{$id}\">\n	<img src=\'{$status[\'pp_thumb_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$status[\'members_display_name\'])\"}\" class=\'photo\' />\n	<p>\n		<a class=\"title\" href=\'{parse url=\"showuser={$status[\'member_id\']}\" seotitle=\"{$status[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\' title=\'{$this->lang->words[\'view_profile\']}\'>{$status[\'members_display_name\']}</a><br />\n		{$status[\'status_content\']}\n	</p>\n</div>\n</foreach>', 'statusUpdates', '$updates=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('499', '0', 'skin_profile', '{parse js_module=\"status\"}\n{parse striping=\"recent_status\" classes=\"row1,row2 altrow\"}\n<h2>{$this->lang->words[\'status_updates__overview\']}</h2>\n<div class=\"master_list status_updates\">\n<if test=\"$this->memberData[\'member_id\'] AND $this->settings[\'friends_enabled\']\">\n	<div class=\"controls\">\n		<div class=\"buttons\">\n			<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=all\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\' class=\"button\">{$this->lang->words[\'status__all_updates\']}</a>\n			<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=friends\" seotitle=\"true\" template=\"members_status_friends\" base=\"public\"}\' class=\"button\">{$this->lang->words[\'status__myfriends\']}</a>\n		</div>\n	</div>\n</if>\n<div id=\'board_index\' class=\'clearfix\'>\n	<div id=\'status_standalone_page\'>\n		<div id=\"status_wrapper\">\n			<if test=\"hasUpdates:|:count( $updates )\">\n				{parse template=\"statusUpdates\" group=\"profile\" params=\"$updates\"}\n			<else />\n				<p class=\'no_messages\'>{$this->lang->words[\'status_updates_none\']}</p>\n			</if>\n		</div>\n	</div>\n</div>\n</div>', 'statusUpdatesPage', '$updates=array(), $actions', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('500', '0', 'skin_profile', '<h3 class=\'bar\'>{$this->lang->words[\'pp_tab_aboutme\']}</h3>\n<div class=\'general_box\'>\n	<if test=\"tababoutMe:|:$member[\'pp_about_me\'] OR $member[\'signature\']\">\n		{$member[\'pp_about_me\']}\n		\n		<if test=\"tabsignature:|:$member[\'signature\']\">\n				{$member[\'signature\']}\n		</if>\n	<else />\n		{$this->lang->words[\'err_no_aboutme_to_show\']}\n	</if>\n</div>', 'tabAboutMe', '$member=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('501', '0', 'skin_profile', '<!--no data in this master skin-->', 'tabFriends', '$friends=array(), $member=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('502', '0', 'skin_profile', '<h3 class=\'bar\'>{$this->lang->words[\'tab_message_h\']}</h3>\n<div class=\'general_box\'>\n	{$this->lang->words[ $langkey ]}\n</div>', 'tabNoContent', '$langkey', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('503', '0', 'skin_profile', '<h3 class=\'bar\'>{$this->lang->words[\'posts_made\']}</h3>\n<div class=\'general_box alt\'>\n	<ol>\n		$content\n	</ol>\n</div>', 'tabPosts', '$content', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('504', '0', 'skin_profile', '<li style=\'list-style:none\'>\n	<if test=\"singleColumnTitle:|:$title\">\n		<if test=\"singleColumnUrl:|:$url\">\n			<h4><a href=\"$url\" title=\"{$this->lang->words[\'view_topic\']}\">$title</a></h4>\n		<else />\n			<h4>$title</h4>\n		</if>\n	</if>\n	<p class=\'posted_info\'>{$this->lang->words[\'posted\']} {$row[\'_date_array\'][\'mday\']} {$row[\'_date_array\'][\'smonth\']} {$row[\'_date_array\'][\'year\']}</p>\n	<div class=\'post_body\'>\n		{$row[\'post\']}\n	</div>\n</li>', 'tabSingleColumn', '$row=array(), $read_more_link=\'\', $url=\'\', $title=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('505', '0', 'skin_profile', '{parse js_module=\"status\"}\n{parse striping=\"recent_status\" classes=\"row1,row2\"}\n<div class=\'status_profile_page\'>\n	<if test=\"canCreate:|:$this->memberData[\'member_id\'] AND ( $this->memberData[\'member_id\'] == $member[\'member_id\'] ) AND $this->registry->getClass(\'memberStatus\')->canCreate( $member )\">\n		<div class=\'status_update row2 altrow\'>\n			<input type=\'text\' id=\'statusUpdate\' style=\'width:80%\'> <input type=\'submit\' class=\'input_submit\' id=\'statusSubmit\' value=\'{$this->lang->words[\'_rarr\']}\' />\n		</div>\n	</if>\n	<div id=\"status_wrapper\">\n		<if test=\"hasUpdates:|:count( $updates )\">\n			{parse template=\"statusUpdates\" group=\"profile\" params=\"$updates\"}\n		<else />\n			<p>{$this->lang->words[\'status_updates_none\']}</p>\n		</if>\n	</div>\n</div>\n<div class=\'status_profile_actions\'>\n	<if test=\"count( $actions )\">\n		<foreach loop=\"actions:$actions as $id => $row\">\n			<div class=\'{parse striping=\"recent_status\"} clear\'>\n				<div class=\'status_action_left\'><img src=\"{$this->settings[\'img_url\']}/profile/commentAction.gif\" alt=\"\" /></div>\n				<div class=\'status_action_right\'><a href=\'{parse url=\"showuser={$row[\'member_id\']}\" seotitle=\"{$row[\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\'>{$row[\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$row[\'member_id\'],$row[\'members_seo_name\']\"}\n				replied to <a href=\'{parse url=\"showuser={$row[\'owner\'][\'member_id\']}\" seotitle=\"{$row[\'owner\'][\'members_seo_name\']}\" template=\"showuser\" base=\"public\"}\'>{$row[\'owner\'][\'members_display_name\']}</a>\'s{parse template=\"user_popup\" group=\"global\" params=\"$row[\'owner\'][\'member_id\'],$row[\'owner\'][\'members_seo_name\']\"}\n				<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;type=all&amp;status_id={$row[\'action_status_id\']}\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\'>status</a>\n				<br /><span class=\'desc\'>{$row[\'action_date_formatted_short\']}</span>\n				</div>\n			</div>\n		</foreach>\n		<br />\n		<div class=\'right\'>\n			<a href=\'{parse url=\"app=members&amp;module=profile&amp;section=status&amp;member_id={$member[\'member_id\']}\" seotitle=\"true\" template=\"members_status_all\" base=\"public\"}\'>View All</a>\n		</div>\n	<else />\n		<p>{$this->lang->words[\'status_actions_none\']}</p>\n	</if>\n</div>', 'tabStatusUpdates', '$updates=array(), $actions, $member=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('506', '0', 'skin_profile', '<h3 class=\'bar\'>{$this->lang->words[\'topics_started\']}</h3>\n<div class=\'general_box alt\'>\n	<ol>\n		$content\n	</ol>\n</div>', 'tabTopics', '$content', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('507', '0', 'skin_ucp', '<div class=\'row1\'>	\n	<if test=\"hasAttachLimit:|:$info[\'has_limit\'] == 1\">\n		<div id=\'space_allowance\' class=\'general_box\'>\n			<p><strong>{$info[\'attach_space_used\']}</strong></p>\n			<p class=\'progress_bar <if test=\"attachAlmostFull:|:$info[\'full_percent\'] > 80\">limit</if>\' title=\'{$this->lang->words[\'ucp_attach_allowance\']} {$info[\'full_percent\']}% {$this->lang->words[\'ucp_full\']}\'>\n				<span style=\'width: {$info[\'full_percent\']}%\'>{$info[\'full_percent\']}%</span>\n			</p>\n			<p class=\'desc\'>{$info[\'attach_space_count\']}</p>\n		</div>\n	</if>\n	<div class=\'topic_controls\'>\n		$pages\n	</div>\n	<br />\n	<!-- ATTACHMENTS TABLE -->\n	<form action=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=updateAttachments&amp;do=saveIt\" base=\"public\"}\" id=\"checkBoxForm\" method=\"post\">\n	<table class=\'ipb_table\' summary=\"{$this->lang->words[\'ucp_user_attach\']}\">\n		<tr class=\'header\'>\n				<th scope=\'col\' style=\'width: 2%\'>&nbsp;</th>\n				<th scope=\'col\' style=\'width: 35%\'>{$this->lang->words[\'attach_title\']}</th>\n				<th scope=\'col\' style=\'width: 7%\'>{$this->lang->words[\'attach_hsize\']}</th>\n				<th scope=\'col\' style=\'width: 27%\'>{$this->lang->words[\'attach_topic\']}</th>\n				<th scope=\'col\' class=\'short\' style=\'width: 3%\'><input class=\'input_check\' id=\"checkAllAttachments\" type=\"checkbox\" value=\"{$this->lang->words[\'check_all\']}\" /></th>\n			</tr>\n			<if test=\"hasAttachments:|:count($attachments)\">\n				{parse striping=\"attach\" classes=\"row1,row2\"}\n				<foreach loop=\"attach:$attachments as $idx => $data\">\n					<tr id=\"a{$data[\'attach_id\']}\" class=\'{parse striping=\"attach\"}\'>\n							<td class=\'short altrow\'>\n								<if test=\"attachmentThumbLocation:|:$data[\'attach_thumb_location\']\">\n									<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'_type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\"><img src=\"{$this->settings[\'upload_url\']}/{$data[\'attach_thumb_location\']}\" width=\"30\" height=\"30\" alt=\'{$this->lang->words[\'attached_file\']}\' /></a>\n								<else />\n									<img src=\"{$this->settings[\'mime_img\']}/{$data[\'image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" />\n								</if>\n							</td>\n							<td>\n								<a href=\"{parse url=\"app=core&amp;module=attach&amp;section=attach&amp;attach_rel_module={$data[\'_type\']}&amp;attach_id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$data[\'attach_file\']}\">{$data[\'short_name\']}</a><br />\n								<span class=\"desc\">( {$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']} )</span>\n							</td>\n							<td class=\'short altrow\'>{$data[\'real_size\']}</td>\n							<td>\n								<if test=\"attachmentPost:|:$data[\'attach_rel_id\'] > 0 AND $data[\'attach_rel_module\'] == \'post\'\">\n									<a href=\"{parse url=\"showtopic={$data[\'tid\']}&amp;view=findpost&amp;p={$data[\'attach_rel_id\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'ucp_view_org\']}\'>{$data[\'title\']}</a>\n								<else />\n									{$data[\'title\']}\n								</if>\n								<br />\n								<span class=\"desc\">{$data[\'attach_date\']}</span>\n							</td>\n							<td class=\'altrow short\'><input type=\"checkbox\" name=\"attach[{$data[\'attach_id\']}]\" value=\"1\" class=\"input_check checkall\" /></td>\n						</tr>\n				</foreach>\n			<else />\n				<tr>\n					<td colspan=\"5\" class=\'no_messages\'>{$this->lang->words[\'splash_noattach\']}</td>\n				</tr>\n			</if>\n		</table>\n		<if test=\"attachmentMultiDelete:|:count($attachments)\">\n			<div class=\'moderation_bar rounded with_action clear\' id=\'topic_mod\'>\n				<input type=\"hidden\" name=\"authKey\" value=\"{$this->member->form_hash}\" />\n				<input type=\"submit\" value=\"{$this->lang->words[\'attach_delete\']}\" class=\"input_submit alt\" />\n			</div>\n		</if>\n	</form>\n</div>\n<script type=\'text/javascript\'>\n	ipb.global.registerCheckAll( \'checkAllAttachments\', \'checkall\' );\n</script>', 'coreAttachments', '$info=\"\",$pages=\"\",$attachments', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('508', '0', 'skin_ucp', '<if test=\"dnameOkMessage:|:$okmessage != \"\"\">\n	<p class=\'message\'>{$okmessage}</p>\n</if>\n<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'dname_title\']}</h3>\n	<br />\n	<if test=\"$form[\'_noPerm\']\">\n		<p class=\'message error\'>{$form[\'_noPerm\']}</p>\n	<else />\n		<p class=\'message unspecific\'>{$form[\'_lang_string\']}</p>\n		<ul>\n			<li class=\'field\'>\n				<label for=\'displayName\'>{$this->lang->words[\'dname_choose\']}</label><input class=\'input_text\' type=\"text\" maxlength=\'{$this->settings[\'max_user_name_length\']}\' name=\"displayName\" id=\"displayName\" value=\"{$this->request[\'displayName\']}\" size=\'30\' /> <br />\n				<span class=\'desc\'>{$this->lang->words[\'dname_choose2\']}</span>\n			</li>\n			<if test=\"dnameFbUser:|:!$isFB\">\n			<li class=\'field\'>\n				<label for=\'displayPassword\'>{$this->lang->words[\'dname_password\']}</label><input class=\'input_text\' type=\"password\" name=\"displayPassword\" id=\"displayPassword\" value=\"\" size=\'30\' /> <br />\n				<span class=\'desc\'>{$this->lang->words[\'dname_password2\']}</span>\n			</li>\n			</if>\n		</ul>\n	</if>\n</fieldset>', 'displayNameForm', '$form=array(),$error=\"\",$okmessage=\"\", $isFB=false', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('509', '0', 'skin_ucp', '<script type=\"text/javascript\">\nvar msg = \"$_message\";\n	if ( msg != \"\"){\n		alert(msg);\n	}\n</script>\n<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'change_email_title\']}</h3>\n	<br />\n	<p class=\'message unspecific\'>\n		<if test=\"emailIsAdmin:|:$this->memberData[\'g_access_cp\']\">\n			{$this->lang->words[\'admin_emailpassword\']}\n		<else />\n			{$txt}\n		</if>\n	</p>\n	<if test=\"emailIsNotAdmin:|:!$this->memberData[\'g_access_cp\']\">\n		<ul>\n			<li class=\'field\'>\n				<label for=\'in_email_1\'>{$this->lang->words[\'ce_new_email\']}</label>\n				<input type=\"text\" name=\"in_email_1\" id=\'in_email_1\' class=\'input_text\' value=\"\" />\n			</li>\n			<li class=\'field\'>\n				<label for=\'in_email_2\'>{$this->lang->words[\'ce_new_email2\']}</label>\n				<input type=\"text\" name=\"in_email_2\" id=\'in_email_2\' class=\'input_text\' value=\"\" />\n			</li>\n			<if test=\"passFbUser:|:!$isFB\">\n			<li class=\'field\'>\n				<label for=\'password\'>{$this->lang->words[\'ec_passy\']}</label>\n				<input type=\"password\" id=\'password\' class=\'input_text\' name=\"password\" value=\"\" />\n			</li>\n			</if>\n		</ul>\n	</if>\n</fieldset>\n<if test=\"emailCaptcha:|:$captchaHTML != \'\' AND !$this->memberData[\'g_access_cp\']\">\n	<br />\n	$captchaHTML\n</if>', 'emailChangeForm', '$txt, $_message, $captchaHTML, $isFB=false', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('510', '0', 'skin_ucp', '<!--no data in this master skin-->', 'emailPasswordChangeForm', '$txt, $_message, $isFB=false', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('511', '0', 'skin_ucp', '<select name=\"$name\" class=\'input_select\'>\n	$options\n</select>', 'field_dropdown', '$name=\"\",$options=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('512', '0', 'skin_ucp', '<li class=\'field\'>\n	<label for=\'field_$id\'>$title</label>\n	{$content}\n	<if test=\"cfieldDesc:|:$desc\"><span class=\'desc\'>{$desc}</span></if>\n</li>', 'field_entry', '$title=\"\",$desc=\"\",$content=\"\",$id=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('513', '0', 'skin_ucp', '<textarea cols=\"80\" rows=\"5\" wrap=\"soft\" name=\"$name\" class=\'input_text\'>$value</textarea>', 'field_textarea', '$name=\"\",$value=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('514', '0', 'skin_ucp', '<input type=\"text\" size=\"50\" name=\"$name\" value=\'$value\' class=\'input_text\' />', 'field_textinput', '$name=\"\",$value=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('515', '0', 'skin_ucp', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n<if test=\"$preview_about_me\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'cp_current_aboutme\']}</h3>\n		<div class=\'signature\'>\n			{$preview_about_me}\n		</div>\n	</fieldset>\n</if>\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3>{$this->lang->words[\'cp_edit_aboutme\']}</h3>\n	<div>\n		{$editor_html}\n	</div>\n</fieldset>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}', 'membersAboutMeForm', '$preview_about_me=\"\",$editor_html=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('516', '0', 'skin_ucp', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n<!-- Not authorized email? -->\n<if test=\"fbNoEmailWarning:|:! $this->memberData[\'fb_emailallow\'] AND strstr( $this->memberData[\'email\'], \'@proxymail.facebook.com\' )\">\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3>{$this->lang->words[\'fb_email_not_allowed\']}</h3>\n	<p>{$this->lang->words[\'fb_email_not_allowed_desc\']}</p>\n</fieldset>\n<else />\n	<if test=\"fbMismatch:|:$fbuid AND $linkedMemberData[\'member_id\'] AND $linkedMemberData[\'member_id\'] != $this->memberData[\'member_id\']\">\n		<!-- currently logged in FB user is linked to a different account -->\n		<div class=\'message error\'>\n			<strong>{$this->lang->words[\'fb_connect_mismatch\']}</strong>\n			<p>{$this->lang->words[\'fb_connect_mismatch_desc\']}</p>\n		</div>\n	<else />\n		<div id=\'fbUserBox\'>\n			{$this->lang->words[\'fb_config\']}\n			<br />\n			<br />\n			<fb:login-button size=\"medium\" background=\"light\" length=\"long\" onlogin=\"ipb.facebook.usercp_loadUser();\"></fb:login-button>\n		</div>\n		<div id=\'fb-template\' style=\'display:none\'>\n			<fieldset class=\'row2\'>\n				<div style=\'float:left; margin-right:4px;margin-bottom:3px\'>\n					<fb:profile-pic uid=\"loggedinuser\" facebook-logo=\"true\"></fb:profile-pic>\n				</div>\n				{$this->lang->words[\'fb_logged_in_as\']} <strong><fb:name uid=\"loggedinuser\" useyou=\"false\"></fb:name></strong>\n				<if test=\"fbShowStatus:|:is_array($fbUserData[\'status\']) AND $fbUserData[\'status\'][\'message\']\">\n					<br /><br /><p class=\'desc\'>{$fbUserData[\'first_name\']} {$fbUserData[\'status\'][\'message\']}</p>\n				</if>\n			</fieldset>\n			<fieldset class=\'row1\'>\n				<h3>{$this->lang->words[\'fb_sync_options\']}</h3>\n				<ul>\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_s_pic\' value=\'1\' <if test=\"fbSyncPic:|:$this->memberData[\'fbc_s_pic\'] > 0\">checked=\'checked\'</if> id=\'fbc_s_pic\' /><label for=\'fbc_s_pic\'>{$this->lang->words[\'fb_sync_photo\']}</label>\n					</li>\n<if test=\"canUpdateStatus:|:$this->memberData[\'can_updated_status\']\">\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_s_status\' value=\'1\' <if test=\"fbSyncStatus:|:$this->memberData[\'fbc_s_status\'] > 0\">checked=\'checked\'</if> id=\'fbc_s_status\' /><label for=\'fbc_s_status\'>{$this->lang->words[\'fb_sync_status\']}</label>\n					</li>\n</if>\n					<li class=\'field checkbox\'>\n						<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'fbc_s_aboutme\' value=\'1\' <if test=\"fbSyncAboutMe:|:$this->memberData[\'fbc_s_aboutme\'] > 0\">checked=\'checked\'</if> id=\'fbc_s_aboutme\' /><label for=\'fbc_s_aboutme\'>{$this->lang->words[\'fb_sync_aboutme\']}</label>\n					</li>\n				</ul>\n				<p class=\'desc\'>\n					{$this->lang->words[\'fb_last_syncd\']}\n					<if test=\"fbLastSync:|:$this->memberData[\'fb_lastsync\']\">\n						{parse date=\"$this->memberData[\'fb_lastsync\']\" format=\"long\"}\n					<else />\n						{$this->lang->words[\'fb_never\']}\n					</if>\n				</p>\n				<p><input type=\'submit\' class=\'input_submit alt\' id=\'fbc_sync\' value=\'{$this->lang->words[\'fb_sync_now\']}\' /></p>\n			</fieldset>\n			<fieldset class=\'row1\'>\n				<h3>{$this->lang->words[\'fb_disassociate\']}</h3>\n				<p class=\'desc\'>{$this->lang->words[\'fb_disassociate_desc\']}</p>\n				<if test=\"fbDefaultEmail:|:strstr( $this->memberData[\'email\'], \'@proxymail.facebook.com\' )\">\n					<div class=\'message\'>\n						<strong>{$this->lang->words[\'fb_using_email\']}</strong>\n						<p>{$this->lang->words[\'fb_disassociate_info_1\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=email\" base=\"public\"}\'>{$this->lang->words[\'fb_disassociate_info_2\']}</a> {$this->lang->words[\'fb_disassociate_info_3\']}\n						</p>\n					</div>\n					<br />\n				</if>\n				<p><input type=\'button\' class=\'input_submit alt\' id=\'fbc_remove\' value=\'{$this->lang->words[\'fb_disassociate_now\']}\' /></p>\n			</fieldset>\n		</div>\n	\n		<script type=\"text/javascript\">\n			/* Init Facebook JS */\n			try\n			{\n				ipb.facebook.mem_fb_uid = {parse expression=\"intval($this->memberData[\'fb_uid\'])\"};\n				\n				FB_RequireFeatures([\"XFBML\"], function()\n				{\n					FB.init(\"{$this->settings[\'fbc_appid\']}\", \"{$this->settings[\'fbc_xdlocation\']}\" );\n					FB.Facebook.get_sessionState().waitUntilReady(function()\n					{\n						FB.Connect.ifUserConnected( ipb.facebook.usercp_loadUser );\n					} );\n				} );\n			}\n			catch( error )\n			{\n				//alert( error );\n			}\n		</script>\n	</if>\n</if>', 'membersFacebookConnect', '$fbuid, $fbUserData, $linkedMemberData', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('517', '0', 'skin_ucp', '<script type=\'text/javascript\'>\n//<![CDATA[\n	ipb.templates[\'autocomplete_wrap\'] = new Template(\"<ul id=\'#{id}\' class=\'ipbmenu_content\' style=\'width: 250px;\'></ul>\");\n	ipb.templates[\'autocomplete_item\'] = new Template(\"<li id=\'#{id}\'><img src=\'#{img}\' alt=\'\' width=\'#{img_w}\' height=\'#{img_h}\' />&nbsp;&nbsp;#{itemvalue}</li>\");\n//]]>\n</script>\n<fieldset class=\'row1\'>\n	<h3 class=\'maintitle\'>{$this->lang->words[\'mi5_title\']}</h3>\n	<table class=\'ipb_table\' summary=\"{$this->lang->words[\'ucp_ignored_users\']}\">\n		<tr class=\'header\'>\n			<th scope=\'col\' width=\"30%\">{$this->lang->words[\'mi5_name\']}</th>\n			<th scope=\'col\' width=\"30%\">{$this->lang->words[\'mi5_group\']}</th>\n			<th scope=\'col\' width=\"10%\">{$this->lang->words[\'mi5_posts\']}</th>\n			<th scope=\'col\' width=\"10%\">{$this->lang->words[\'ucp_ignore_posts\']}</th>\n			<th scope=\'col\' width=\"10%\">{$this->lang->words[\'ucp_ignore_msgs\']}</th>\n			<th scope=\'col\' width=\"10%\">&nbsp;</th>\n		</tr>\n		{parse striping=\"members\" classes=\"row1,row2\"}\n		<foreach loop=\"members:$members as $member\">\n			<tr class=\'{parse striping=\"members\"}\'>\n				<td>\n					<img src=\'{$member[\'pp_thumb_photo\']}\' width=\'{$member[\'pp_thumb_width\']}\' height=\'{$member[\'pp_thumb_height\']}\' border=\'0\' />\n					<strong><a href=\"{parse url=\"showuser={$member[\'member_id\']}\" base=\"public\" seotitle=\"{$member[\'members_seo_name\']}\" template=\"showuser\"}\">{$member[\'members_display_name\']}</a></strong>\n					<p>{$this->lang->words[\'m_joined\']} {parse date=\"$member[\'joined\']\" format=\"joined\"}</p>\n				</td>\n				<td>{$member[\'g_title\']}</td>\n				<td>{$member[\'posts\']}</td>\n				<td>\n					<if test=\"ignoreMemberTopics:|:$member[\'ignoreData\'][\'ignore_topics\'] == 1\">\n						<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=topics\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\">{$this->lang->words[\'yes\']}</a>\n					<else />\n						<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=topics\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\">{$this->lang->words[\'no\']}</a>\n					</if>\n				</td>\n				<td>\n					<if test=\"ignoreMemberPms:|:$member[\'ignoreData\'][\'ignore_messages\'] == 1\">\n						<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=messages\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\">{$this->lang->words[\'yes\']}</a>\n					<else />\n						<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=toggleIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}&amp;field=messages\" base=\"public\"}\" title=\"{$this->lang->words[\'click_toggle\']}\">{$this->lang->words[\'no\']}</a>\n					</if>\n				</td>\n				<td><a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=removeIgnoredUser&amp;do=saveIt&amp;id={$member[\'member_id\']}\" base=\"public\"}\">{$this->lang->words[\'mi5_remove\']}</a></td>\n			</tr>\n		</foreach>\n	</table>\n</fieldset>\n<fieldset class=\"row2\">\n	<h3>{$this->lang->words[\'mi5_addem\']}</h3>\n	<ul>\n		<li class=\'field\'>\n			<label for=\'newbox_1\'>{$this->lang->words[\'ucp_members_name\']}</label>\n			<input type=\"text\" size=\'40\' name=\"newbox_1\" id=\"newbox_1\" value=\"{$this->request[\'newbox_1\']}\" />\n			<ul>\n				<li class=\'field checkbox\'>\n					<input type=\'checkbox\' class=\'input_check\' name=\'ignore_messages\' value=\'1\' />\n					{$this->lang->words[\'ucp_ignore_pc\']}\n				</li>\n				<li class=\'field checkbox\'>\n					<input type=\'checkbox\' class=\'input_check\' name=\'ignore_topics\' value=\'1\' checked=\'checked\' />\n					{$this->lang->words[\'ucp_ignore_posts\']}\n				</li>\n			</ul>\n		</li>\n	</ul>\n</fieldset>\n<script type=\"text/javascript\">\n	document.observe(\"dom:loaded\", function(){\n		var url = ipb.vars[\'base_url\'] + \'app=core&module=ajax&section=findnames&do=get-member-names&secure_key=\' + ipb.vars[\'secure_hash\'] + \'&name=\';\n		new ipb.Autocomplete( $(\'newbox_1\'), { multibox: false, url: url, templates: { wrap: ipb.templates[\'autocomplete_wrap\'], item: ipb.templates[\'autocomplete_item\'] } } );\n	});\n</script>', 'membersIgnoredUsersForm', '$members', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('518', '0', 'skin_ucp', '<!--no data in this master skin-->', 'membersProfileCustomize', '$options, $input, $errors', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('519', '0', 'skin_ucp', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3>{$this->lang->words[\'ucp_comments\']}</h3>\n	<ul>\n		<li class=\'field checkbox\'>\n			<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_comments\' value=\'1\' <if test=\"showComments:|:$this->memberData[\'pp_setting_count_comments\'] > 0\">checked=\'checked\'</if> id=\'comments_enable\' /><label for=\'comments_enable\'>{$this->lang->words[\'ucp_enable_comments\']}</label>\n		</li>\n		<li class=\'field\'>\n			<label for=\'comments_notify\'>{$this->lang->words[\'ucp_comment_notify_type\']}</label>\n			<select name=\'pp_setting_notify_comments\' id=\'comments_notify\' class=\'input_select\'>\n				<option value=\'none\'<if test=\"commentsNone:|:$this->memberData[\'pp_setting_notify_comments\'] == \'none\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_none\']}</option>\n				<option value=\'email\'<if test=\"commentsEmail:|:$this->memberData[\'pp_setting_notify_comments\'] == \'email\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_email\']}</option>\n				<option value=\'pm\'<if test=\"commentsPm:|:$this->memberData[\'pp_setting_notify_comments\'] == \'pm\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_pm\']}</option>\n			</select>\n		 	<br />\n			<span class=\'desc\'>{$this->lang->words[\'m_choose_comm_type\']}</span>\n		</li>\n		<li class=\'field\'>\n			<label for=\'comments_moderate\'>{$this->lang->words[\'ucp_comment_approval\']}</label>\n			<select name=\'pp_setting_moderate_comments\' id=\'comments_moderate\' class=\'input_select\'>\n				<option value=\'0\'<if test=\"noModComments:|:! $this->memberData[\'pp_setting_moderate_comments\']\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_disabled\']}</option>\n				<option value=\'1\'<if test=\"yesModComments:|:$this->memberData[\'pp_setting_moderate_comments\']\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_enabled\']}</option>\n			</select>\n			<br />\n			<span class=\'desc\'>{$this->lang->words[\'m_choose_cmod_type\']}</span>\n		</li>\n	</ul>\n</fieldset>\n<if test=\"friendsEnabled:|:$this->settings[\'friends_enabled\'] AND $this->memberData[\'g_can_add_friends\']\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'ucp_friends\']}</h3>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_friends\' value=\'1\' <if test=\"showFriends:|:$this->memberData[\'pp_setting_count_friends\'] > 0\">checked=\'checked\'</if> id=\'friends_enable\' /><label for=\'friends_enable\'>{$this->lang->words[\'ucp_show_friends_profile\']}</label>\n			</li>\n			<li class=\'field\'>\n				<label for=\'friend_notify\'>{$this->lang->words[\'ucp_friend_notify\']}</label>\n				<select name=\'pp_setting_notify_friend\' id=\'friend_notify\' class=\'input_select\'>\n					<option value=\'none\'<if test=\"friendsNone:|:$this->memberData[\'pp_setting_notify_friend\'] == \'none\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_none\']}</option>\n					<option value=\'email\'<if test=\"friendsEmail:|:$this->memberData[\'pp_setting_notify_friend\'] == \'email\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_email\']}</option>\n					<option value=\'pm\'<if test=\"friendsPm:|:$this->memberData[\'pp_setting_notify_friend\'] == \'pm\'\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_pm\']}</option>\n				</select>\n				<br />\n				<span class=\'desc\'>{$this->lang->words[\'m_choose_friend_type\']}</span>\n			</li>\n			<li class=\'field\'>\n				<label for=\'friend_moderate\'>{$this->lang->words[\'ucp_friend_approve\']}</label>\n				<select name=\'pp_setting_moderate_friends\' id=\'friend_moderate\' class=\'input_select\'>\n					<option value=\'0\'<if test=\"noModFriends:|:! $this->memberData[\'pp_setting_moderate_friends\']\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_disabled\']}</option>\n					<option value=\'1\'<if test=\"yesModFriends:|:$this->memberData[\'pp_setting_moderate_friends\']\"> selected=\"selected\"</if>>{$this->lang->words[\'op_dd_enabled\']}</option>\n				</select>\n				<br />\n				<span class=\'desc\'>{$this->lang->words[\'m_choose_fmod_type\']}</span>\n			</li>\n		</ul>\n	</fieldset>\n</if>\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3>{$this->lang->words[\'profile_information\']}</h3>\n	<ul>\n		<li class=\'field checkbox\'>\n			<input class=\'input_check\' type=\'checkbox\' value=\'1\' name=\'pp_setting_count_visitors\' value=\'1\' <if test=\"showFriends:|:$this->memberData[\'pp_setting_count_visitors\'] > 0\">checked=\'checked\'</if> id=\'pp_latest_visitors\' /><label for=\'pp_latest_visitors\'>{$this->lang->words[\'ucp_show_x_latest\']}</label>\n		</li>\n		<if test=\"changeMemberTitle:|:($this->settings[\'post_titlechange\']) && ($this->memberData[\'posts\'] > $this->settings[\'post_titlechange\'])\">\n			<li class=\'field\'>\n				<label for=\'member_title\'>{$this->lang->words[\'member_title\']}</label>\n				<input type=\'text\' class=\'input_text\' size=\'30\' id=\'member_title\' name=\'member_title\' value=\'{$this->memberData[\'title\']}\' />\n				<br />\n				<span class=\'desc\'>{$this->lang->words[\'member_title_desc\']}</span>\n			</li>\n		</if>\n		<if test=\"birthdayFields:|:$day AND $mon AND $year\">\n			<li class=\'field\'>\n				<label for=\'birthday\'>{$this->lang->words[\'ucp_birthday_select\']}</label>\n				<select name=\"month\">&nbsp;\n					<foreach loop=\"months:$mon as $m\">\n						<option value=\'{$m[0]}\'<if test=\"monthSelected:|:$m[0] == $this->memberData[\'bday_month\']\"> selected=\"selected\"</if>>{$m[1]}</option>\n					</foreach>\n				</select>			\n				<select name=\"day\">&nbsp;\n					<foreach loop=\"days:$day as $d\">\n						<option value=\'{$d[0]}\'<if test=\"daySelected:|:$d[0] == $this->memberData[\'bday_day\']\"> selected=\"selected\"</if>>{$d[1]}</option>\n					</foreach>\n				</select> \n				<select name=\"year\">&nbsp;\n					<foreach loop=\"years:$year as $y\">\n						<option value=\'{$y[0]}\'<if test=\"yearSelected:|:$y[0] == $this->memberData[\'bday_year\']\"> selected=\"selected\"</if>>{$y[1]}</option>\n					</foreach>\n				</select> <br />\n				<span class=\'desc\'>{$this->lang->words[\'ucp_birthday_optional\']}</span>\n			</li>\n		</if>\n	</ul>\n</fieldset>\n<if test=\"requiredCfields:|:$required_output\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'ucp_required_info\']}</h3>\n		<ul>\n			{$required_output}\n		</ul>\n	</fieldset>\n</if>\n<if test=\"optionalCfields:|:$optional_output\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'ucp_other_info\']}</h3>\n		<ul>\n			{$optional_output}\n		</ul>\n	</fieldset>\n</if>', 'membersProfileForm', '$personal_statement=\'\',$required_output=\'\',$optional_output=\'\',$day=\'\',$mon=\'\',$year=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('520', '0', 'skin_ucp', '<input type=\'hidden\' name=\'key\' value=\'{$key}\' />\n<input type=\'hidden\' name=\'removeattachid\' value=\'0\' />\n{parse striping=\"usercp\" classes=\"row1,row2\"}\n<if test=\"$preview_sig\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'cp_current_sig\']}</h3>\n		<div class=\'signature\'>\n			{$preview_sig}\n		</div>\n	</fieldset>\n</if>\n<fieldset class=\'{parse striping=\"usercp\"}\'>\n	<h3>{$this->lang->words[\'cp_edit_sig\']}</h3>\n	<div>\n		{$editor_html}\n	</div>\n</fieldset>\n<if test=\"hasSignatureLimits:|:$this->memberData[\'g_signature_limits\']\">\n	<fieldset class=\'{parse striping=\"usercp\"}\'>\n		<h3>{$this->lang->words[\'sig_restrictions\']}</h3>\n		<br />\n		<div class=\'desc\'>\n			{$this->lang->words[\'sig_restrictions_contain\']}\n			<ul class=\'bullets\'>\n				<if test=\"$sig_restrictions[1] !== \'\'\">\n					<li>{parse expression=\"sprintf( $this->lang->words[\'sig_max_imagesr\'], $sig_restrictions[1] )\"}</li>\n				<else />\n					<li>{$this->lang->words[\'sig_max_imagesr_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[2] !== \'\' || $sig_restrictions[3] !== \'\'\">\n					<li>{parse expression=\"sprintf( $this->lang->words[\'sig_max_imgsize\'], $sig_restrictions[2], $sig_restrictions[3] )\"}</li>\n				<else />\n					<li>{$this->lang->words[\'sig_max_imgsize_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[4] !== \'\'\">\n					<li>{parse expression=\"sprintf( $this->lang->words[\'sig_max_urls\'], $sig_restrictions[4] )\"}</li>\n				<else />\n					<li>{$this->lang->words[\'sig_max_urls_nl\']}</li>\n				</if>\n				<if test=\"$sig_restrictions[5] !== \'\'\">\n					<li>{parse expression=\"sprintf( $this->lang->words[\'sig_max_lines\'], $sig_restrictions[5] )\"}</li>\n				<else />\n					<li>{$this->lang->words[\'sig_max_lines_nl\']}</li>\n				</if>\n			</ul>\n		</div>\n	</fieldset>\n</if>\n<if test=\"disablelightbox:|:!$this->settings[\'disable_lightbox\']\">\n{parse template=\"include_lightbox\" group=\"global\" params=\"\"}\n</if>\n{parse template=\"include_highlighter\" group=\"global\" params=\"1\"}', 'membersSignatureForm', '$preview_sig=\"\",$editor_html=\"\",$sig_restrictions=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('521', '0', 'skin_ucp', '<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'cp_edit_sig\']}</h3>\n	<br />\n	<if test=\"$form[\'_noPerm\']\">\n		<p class=\'message error\'>{$form[\'_noPerm\']}</p>\n	</if>\n</fieldset>', 'membersSignatureFormError', '$form', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('522', '0', 'skin_ucp', '<!--no data in this master skin-->', 'membersTwitterConnect', '$isConnected, $twitterUser=array()', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('523', '0', 'skin_ucp', '<!--no data in this master skin-->', 'notificationsForm', '$config, $emailData', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('524', '0', 'skin_ucp', '<php>\n	$this->settings[\'_mobile_nav_home\'] = 1;\n</php>\n<form action=\"{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=removeNotifications&amp;do=remove\" base=\"public\"}\" id=\"checkBoxForm\" method=\"post\">\n	<input type=\"hidden\" name=\"secure_key\" value=\"{$this->member->form_hash}\" />\n	<div class=\'master_list\' id=\'notifications\'>\n		<h2>{$this->lang->words[\'arch_notifications_head\']}</h2>\n		<if test=\"hasnotifyerror:|:$error\">\n		<p class=\'message error\'>\n			{$error}\n		</p>\n		<else />\n			<if test=\"hasconfirm:|:$this->request[\'confirm\']\">\n			<p class=\'message\'>\n				{$this->lang->words[\'notify_rem_suc\']}\n			</p>\n			</if>\n		</if>\n		<foreach loop=\"categories:$notifications as $notification\">\n			<div class=\'row touch-row\'>\n				<div class=\'icon\'>\n					<if test=\"$notification[\'member\'][\'member_id\']\">\n						<a href=\'{parse url=\"showuser={$notification[\'member\'][\'member_id\']}\" template=\"showuser\" seotitle=\"{$notification[\'member\'][\'members_seo_name\']}\" base=\"public\"}\'>\n							<img src=\'{$notification[\'member\'][\'pp_thumb_photo\']}\' class=\'photo\' />\n						</a>\n					<else />\n						<img src=\'{$notification[\'member\'][\'pp_mini_photo\']}\' alt=\"{parse expression=\"sprintf($this->lang->words[\'users_photo\'],$notification[\'member\'][\'members_display_name\'])\"}\" class=\'photo\' />\n					</if>\n				</div>\n				<div class=\'rowContent\'>\n					<strong><if test=\"strpos( $notification[\'notify_title\'], \'<a href\' ) === false\"><a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=viewNotification&amp;do=view&amp;view={$notification[\'notify_id\']}\" base=\"public\"}\' class=\'title\'></if>\n					{$notification[\'notify_title\']}\n					<if test=\"strpos( $notification[\'notify_title\'], \'<a href\' ) === false\"></a></if>\n					</strong>\n					<br />\n					<span class=\'desc\'>{$this->lang->words[\'th_sent\']} {parse date=\"$notification[\'notify_sent\']\" format=\"long\"}</span>\n				</div>\n			</div>\n		</foreach>\n	</div>\n	<if test=\"hasNotifyForMod:|:count($notifications)\">\n		<div class=\'submit\'>\n			<a href=\'{parse url=\"app=core&amp;module=usercp&amp;area=markNotification&amp;do=mark&amp;mark=all\" base=\"public\"}\' id=\'ack_pm_notification\' class=\'button secondary\'>{$this->lang->words[\'notificationlog_mar\']}</a>\n		</div>\n	</if>\n</form>', 'notificationsLog', '$notifications, $error=\'\', $pages=\'\'', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('525', '0', 'skin_ucp', '<fieldset class=\'row1\'>\n	<h3>{$this->lang->words[\'account_pass_title\']}</h3>\n	<br />\n	<p class=\'message unspecific\'>\n		<if test=\"changePasswordAdmin:|:$this->memberData[\'g_access_cp\']\">\n			{$this->lang->words[\'admin_emailpassword\']}\n		<else />\n			{$this->lang->words[\'pass_change_text\']}\n		</if>\n	</p>\n	\n	<if test=\"changePasswordNotAdmin:|:!$this->memberData[\'g_access_cp\']\">\n		<ul>\n			<li class=\'field\'>\n				<label for=\'current_pass\'>{$this->lang->words[\'account_pass_old\']}</label>\n				<input type=\"password\" name=\"current_pass\" value=\"\" id=\'current_pass\' class=\'input_text\' />\n			</li>\n			<li class=\'field\'>\n				<label for=\'new_pass_1\'>{$this->lang->words[\'account_pass_new\']}</label>\n				<input type=\"password\" name=\"new_pass_1\" value=\"\" id=\'new_pass_1\' class=\'input_text\' />\n			</li>\n			<li class=\'field\'>\n				<label for=\'new_pass_2\'>{$this->lang->words[\'account_pass_new2\']}</label>\n				<input type=\"password\" name=\"new_pass_2\" value=\"\" id=\'new_pass_2\' class=\'input_text\' />\n			</li>\n		</ul>\n	</if>\n</fieldset>', 'passwordChangeForm', '', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('526', '0', 'skin_ucp', '<a href=\"{parse url=\"act=attach&amp;type={$data[\'type\']}&amp;id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\" target=\"_blank\"><img src=\"{$this->settings[\'mime_img\']}/{$data[\'mime_image\']}\" alt=\"{$this->lang->words[\'attached_file\']}\" /></a>\n&nbsp;<a href=\"{parse url=\"act=attach&amp;type={$data[\'type\']}&amp;id={$data[\'attach_id\']}\" base=\"public\"}\" title=\"{$this->lang->words[\'attach_dl\']}\" target=\"_blank\">{$data[\'attach_file\']}</a> ( {$data[\'file_size\']} )\n<span class=\"desc\">{$this->lang->words[\'attach_hits\']}: {$data[\'attach_hits\']}</span><br />', 'Show_attachments', '$data=\"\"', '1338050065', '0', '0', '0', '0', 'mobile');
