INSERT INTO `ibf_skin_templates` VALUES ('528', '0', 'skin_ucp', '{$html}', 'userCPTemplate', '$current_tab, $html, $tabs, $current_area, $errors=array(), $hide_form=0, $maxUpload=0', '1338050065', '0', '0', '0', '0', 'mobile');
INSERT INTO `ibf_skin_templates` VALUES ('529', '0', 'skin_vkontakte', '{parse striping=\"usercp\" classes=\"row1,row2\"}\n\n<if test=\"!$isConnected\">\n<div>\n	<p class=\'message\'>{$this->lang->words[\'vk_config\']}</p>\n	<br />\n	<br />\n	<a href=\"{$this->settings[\'_original_base_url\']}/interface/vkontakte/index.php\"><img src=\"{$this->settings[\'img_url\']}/vkontakte_login.png\" alt=\"\" /></a>\n	<br />\n</div>\n<else />\n<div>\n	<div class=\'ipsPad row2 clearfix\'>\n		<if test=\"vkHasPic:|:$userData[\'photo\']\">	\n			<img src=\"{$userData[\'photo\']}\" alt=\'\' class=\'left ipsUserPhoto ipsUserPhoto_medium\' />\n			<div class=\'ipsBox_withphoto\'>\n		</if>\n		<h2 class=\'ipsType_subtitle\'>\n			{$this->lang->words[\'vk_logged_in_as\']} <strong>{$userData[\'first_name\']} {$userData[\'last_name\']}</strong>\n		</h2>\n		<if test=\"tcHasPic:|:$userData[\'photo\']\">\n			</div>\n		</if>\n	</div>\n\n	<br />\n	<div class=\'right row2 ipsPad clearfix\' style=\'width: 250px\'>\n		<input type=\'button\' class=\'ipsButton_secondary\' id=\'vk_remove_start\' value=\'{$this->lang->words[\'vk_disassociate\']}\' />\n\n		<div id=\'vk_remove_popup\' style=\'display: none\'>\n			<h3>{$this->lang->words[\'vk_disassociate\']}</h3>\n			<div class=\'ipsPad\'>\n				<p>{$this->lang->words[\'vk_revoke\']}</p>\n				<p class=\'desc\'>{$this->lang->words[\'vk_disassociate_desc\']}</p>\n				<br />\n				<input type=\'button\' class=\'ipsButton\' id=\'vk_remove\' value=\'{$this->lang->words[\'tc_disassociate_now\']}\' />\n			</div>\n		</div>\n	</div>\n\n	<if test=\"vkPassword:|:! $this->memberData[\'bw_local_password_set\'] AND $this->memberData[\'members_created_remote\']\">\n		<div class=\'message\'>\n			<strong>{$this->lang->words[\'remote_no_password\']}</strong>\n			<p>{$this->lang->words[\'remote_no_password_1\']} <a href=\'{parse url=\"app=core&amp;module=usercp&amp;tab=core&amp;area=password\" base=\"public\"}\'>{$this->lang->words[\'remote_no_password_2\']}</a>\n			</p>\n		</div>\n		<br />\n	</if>\n</div>\n<script type=\"text/javascript\">\n	$(\'vk_remove\').observe( \'click\', usercp_remove );\n	function usercp_remove(){\n		window.location = ipb.vars[\'base_url\'] + \'app=core&module=usercp&tab=core&area=vkontakteRemove&do=custom&secure_key=\' + ipb.vars[\'secure_hash\'];\n	}\n\n	$(\'vk_remove_start\').on(\'click\', function(e){\n		new ipb.Popup( \'sign_in_popup\', {	type: \'pane\',\n											initial: $(\'vk_remove_popup\').show(),\n											hideAtStart: false,\n											hideClose: false,\n											modal: true,\n											w: \'600px\' } );\n	});\n</script>\n</if>\n', 'membersVkontakteConnect', '$isConnected, $userData', '1280738657', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('530', '0', 'skin_vkontakte', '<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/vkontakte/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/vkontakte_login.png\" alt=\"\" /></a></li>', 'vkInlineLogInService', '', '1311665029', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('531', '0', 'skin_vkontakte', '<a href=\'{parse url=\"app=core&amp;module=global&amp;section=login&amp;serviceClick=vkontakte\" base=\"public\"}\'>{parse replacement=\"lim_vkontakte\"}</a>', 'vkServicesLim', '', '1311664820', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('532', '0', 'skin_mlist', '<li id=\'alpha_switch\' class=\'clickable\'>РУС</li>\n		</ul>\n	</div>\n\n	<div class=\'ipsVerticalTabbed_tabs ipsVerticalTabbed_minitabs ipsLayout_left\' id=\'mlist_tabs_ru\'>\n		<ul>\n    		<if test=\"letterquickjump:|:!$this->request[\'quickjump\']\">\n    			<li class=\'active\'><a href=\'{parse url=\"app=members&amp;module=list\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'members_start_with\']}{$letter}\'>{$this->lang->words[\'mlist_view_all_txt\']}</a></li>\n    		<else />\n    			<li><a href=\'{parse url=\"app=members&amp;module=list\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'mlist_view_all_title\']}\'>{$this->lang->words[\'mlist_view_all_txt\']}</a></li>\n    		</if>\n    <foreach loop=\"array(\'А\',\'Б\',\'В\',\'Г\',\'Д\',\'Е\',\'Ё\',\'Ж\',\'З\',\'И\',\'Й\',\'К\',\'Л\',\'М\',\'Н\',\'О\',\'П\',\'Р\',\'С\',\'Т\',\'У\',\'Ф\',\'Х\',\'Ц\',\'Ч\',\'Ш\',\'Щ\',\'Ъ\',\'Ы\',\'Ь\',\'Э\',\'Ю\',\'Я\') as $char\">\n    	<if test=\"letterdefault:|:$letter=urlencode($char)\">\n          	<li <if test=\"selected:|:$this->request[\'quickjump\'] AND ($this->request[\'quickjump\'] == $letter OR $this->request[\'quickjump\'] == $char)\">class=\'active\'</if>><a href=\'{parse url=\"{$url}&amp;quickjump={$letter}\" template=\"members_list\" base=\"public\" seotitle=\"false\"}\' title=\'{$this->lang->words[\'mlist_view_start_title\']} {$char}\'>{$char}</a></li>\n    	</if>\n    </foreach>\n            <li id=\'alpha_switch_en\' class=\'clickable\'>АНГ</li>\n', 'member_alpha_ru', '$url=\'\'', '1280429247', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('607', '0', 'skin_shoutbox_hooks', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/shoutbox.js\'></script>\n<script type=\'text/javascript\'>\n/* Setup some value */\nipb.shoutbox.shoutboxGLOBAL = true;\n</script>\n\n{$d[\'emoticons\']}\n\n<div id=\'shoutbox_sidebar\' class=\'ipsSideBlock clearfix\'>\n	<h3>\n		{$this->settings[\'shoutbox_title\']}\n		<if test=\"showPopupLink:|:$this->settings[\'shoutbox_popup\']\"><a href=\"#\" id=\"shoutbox-popup-button\" title=\"{$this->lang->words[\'open_popup\']}\"><img src=\"{$this->settings[\'img_url\']}/shoutbox/popup.png\" alt=\"{$this->lang->words[\'open_popup\']}\" /></a></if>\n</h3>\n	<ul class=\'hfeed block_list\'>\n		<table class=\'ipb_table shoutbox_table\'>\n			{$d[\'announcement\']}\n			<tr class=\'row1\'>\n				<td valign=\'top\' class=\'altrow\'>\n					<div id=\'shoutbox-shouts\' style=\'height: {$d[\'shout_height\']}px; overflow-x: hidden;\'>\n						{$d[\'noshouts\']}\n						{parse template=\"inactivePrompt\" group=\"skin_shoutbox\" params=\"\"}\n						<table id=\'shoutbox-shouts-table\'>\n							<tbody>\n								{$d[\'shouts\']}\n							</tbody>\n						</table>\n					</div>\n					<img src=\'{$this->settings[\'img_url\']}/spacer.gif\' id=\'shouts-global-resizer\' border=\'0\' height=\'4px\' alt=\'{$this->lang->words[\'resize_shouts_area\']}\' style=\'cursor:n-resize;width:100%;\' />\n					{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"glb\"}\n					<if test=\"$this->memberData[\'g_shoutbox_use\']\">\n						<br />\n						<input type=\'text\' id=\'shoutbox-global-shout\' style=\'width:95%;\' class=\'input_text\' /><br /><br />\n						<div class=\'short\'>\n							<input type=\'button\' id=\'shoutbox-submit-button\' value=\'{$this->lang->words[\'shout\']}\' class=\'input_submit\' />\n							<input type=\'button\' id=\'shoutbox-clear-button\' value=\'{$this->lang->words[\'clear\']}\' class=\'input_submit alt\' />\n							<input type=\'button\' id=\'shoutbox-refresh-button\' value=\'{$this->lang->words[\'refresh\']}\' class=\'input_submit alt\' />\n						</div><br />\n						<div class=\'short\'>\n							<if test=\"$this->settings[\'shoutbox_allow_smilies\']\"> <input type=\'button\' id=\'shoutbox-smilies-button\' value=\'{$this->lang->words[\'smilies\']}\' class=\'input_submit alt\' data-clicklaunch=\"populateSmilies\" data-scope=\"shoutbox\" /></if>\n							<if test=\"$this->settings[\'shoutbox_allow_bbcode\']\"> <input type=\'button\' id=\'shoutbox-bbcode-button\' value=\'{$this->lang->words[\'bbcode\']}\' class=\'input_submit alt\' /></if>\n							<input type=\'button\' id=\'shoutbox-myprefs-button\' value=\'{$this->lang->words[\'my_prefs\']}\' class=\'input_submit alt\' />\n						</div>\n					</if>\n				</td>\n			</tr>\n		</table>\n	</ul>\n</div>\n<script type=\'text/javascript\'>\n{$d[\'js\']}\n</script>', 'hookGlobalShoutboxSidebar', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('606', '0', 'skin_shoutbox_hooks', '<if test=\"showPagination:|:$total>count($emoticons)\">\n	<h3 class=\"maintitle short\">\n		<span class=\"pager\"><if test=\"showPrevious:|:$prev!=-1\"><a href=\"#\" class=\"emoticonPager\" id=\"page_{$prev}\">&#0171;</a></if>&nbsp;</span>\n		{$this->lang->words[\'more\']}\n		<span class=\"pager\">&nbsp;<if test=\"showNext:|:(count($emoticons)+(($next-1)*$this->settings[\'shoutbox_emos_perpage\']))<$total\"><a href=\"#\" class=\"emoticonPager\" id=\"page_{$next}\">&#0187;</a></if></span>\n	</h3>\n</if>\n<table class=\"ipb_table\">\n	{parse striping=\"shoutboxEmo\" classes=\"row1,row2\"}\n	<php>$count=0;</php>\n	<foreach loop=\"$emoticons as $emo\">\n		<php>$count++;</php>\n		<if test=\"startRow:|:$count%$this->settings[\'shoutbox_emos_perrow\']==1\">\n			<tr class=\"{parse striping=\"shoutboxEmo\"}\">\n		</if>\n		<td class=\"short\">\n			<a title=\"{$emo[\'image\']}\" onclick=\'ipb.shoutbox.emoticonOnclick(\"{$emo[\'text\']}\"); return false;\' href=\"#\">\n				<img alt=\"{$emo[\'image\']}\" src=\"{$this->settings[\'emoticons_url\']}/{$emo[\'image\']}\" />\n			</a>\n		</td>\n		<if test=\"endRow:|:$count%$this->settings[\'shoutbox_emos_perrow\']==0\">\n			</tr>\n		</if>\n	</foreach>\n	<if test=\"cellCleanup:|:count($emoticons)%$this->settings[\'shoutbox_emos_perrow\']>0\">\n		<php>$extra = \"\"; for ( $i=count($emoticons)%$this->settings[\'shoutbox_emos_perrow\']; $i<$this->settings[\'shoutbox_emos_perrow\']; $i++ ) { $extra .= \"<td>&nbsp;</td>\"; }</php>\n		{$extra}\n		</tr>\n	</if>\n</table>', 'hookGlobalShoutboxEmoticons', '$emoticons=array(), $total=0, $prev=0, $next=0', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('604', '0', 'skin_shoutbox_hooks', '<div id=\'active_users\' class=\'ipsSideBlock clearfix\'>\n	<h3><a href=\"{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}\" title=\'{$this->lang->words[\'view_main_shoutbox\']}\'>{$this->lang->words[\'sb_hook_active_users\']} (<span id=\'shoutbox-active-total\'<if test=\"$this->settings[\'shoutbox_active_ajax\']\"> class=\'ajax_update\'\'</if>>{$stats[\'TOTAL\']}</span>)</a></h3>\n	<div>\n		<span class=\'desc\'><span id=\'shoutbox-active-member\'>{$stats[\'MEMBERS\']}</span> {$this->lang->words[\'members\']}, <if test=\"hideGuestCount:|:$this->caches[\'group_cache\'][ $this->settings[\'guest_group\'] ][\'g_shoutbox_view\']\"><span id=\'shoutbox-active-guests\'>{$stats[\'GUESTS\']}</span> {$this->lang->words[\'guests\']}, </if><span id=\'shoutbox-active-anon\'>{$stats[\'ANON\']}</span> {$this->lang->words[\'anon_users\']}</span>\n		<br /><br />\n		<p id=\'shoutbox-active-names\'>\n			<if test=\"count($stats[\'NAMES\'])\">\n				{parse expression=\"implode( \", \", $stats[\'NAMES\'] )\"}\n			</if>\n		</p>\n	</div>\n</div>', 'hookActiveUsersSidebar', '$stats', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('605', '0', 'skin_shoutbox_hooks', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/shoutbox.js\'></script>\n<script type=\'text/javascript\'>\n/* Setup some value */\nipb.shoutbox.shoutboxGLOBAL = true;\n</script>\n<if test=\"in_array( $this->settings[\'shoutbox_global_hook\'], array( \'b\' ) )\"><br class=\"clear\"/></if>\n<div class=\'category_block block_wrap\' id=\'category_shoutbox\'>\n	<h3 class=\'maintitle\'>\n		<a class=\'toggle right\' href=\'#\' title=\'{$this->lang->words[\'toggle_shoutbox\']}\'>{$this->lang->words[\'toggle_shoutbox\']}</a>\n		<a href=\"{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}\" title=\'{$this->lang->words[\'view_main_shoutbox\']}\'>{$this->settings[\'shoutbox_title\']}</a>\n		<if test=\"showPopupLink:|:$this->settings[\'shoutbox_popup\']\"><a href=\"#\" id=\"shoutbox-popup-button\" title=\"{$this->lang->words[\'open_popup\']}\"><img src=\"{$this->settings[\'img_url\']}/shoutbox/popup.png\" alt=\"{$this->lang->words[\'open_popup\']}\" /></a></if>\n	</h3>\n	<div class=\'ipsBox table_wrap\'><div class=\'ipsBox_container\'>\n		<table class=\'ipb_table shoutbox_table\'>\n			{$d[\'announcement\']}\n			<if test=\"$this->settings[\'shoutbox_global_theme\'] == 2\">\n				<tr class=\'row1\'>\n					<td valign=\'top\' class=\'altrow\' colspan=\'2\'>\n						<div id=\'shoutbox-shouts\' style=\'height:{$d[\'shout_height\']}px;overflow:auto\'>\n							{$d[\'noshouts\']}\n							{parse template=\"inactivePrompt\" group=\"skin_shoutbox\" params=\"\"}\n							<table id=\'shoutbox-shouts-table\'>\n								<tbody>\n									{$d[\'shouts\']}\n								</tbody>\n							</table>\n						</div>\n						<div id=\'shouts-global-resizer\'></div>\n						{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"glb\"}\n					</td>\n				</tr>\n				<if test=\"$this->memberData[\'g_shoutbox_use\']\">\n					<tr class=\'row1\'>\n						<td class=\'altrow\' valign=\'top\' colspan=\'2\'>\n							<input type=\'text\' id=\'shoutbox-global-shout\' size=\'70\' class=\'input_text\' />\n							<input type=\'button\' id=\'shoutbox-submit-button\' value=\'{$this->lang->words[\'shout\']}\' class=\'input_submit\' />\n							<input type=\'button\' id=\'shoutbox-clear-button\' value=\'{$this->lang->words[\'clear\']}\' class=\'input_submit alt\' />\n							<input type=\'button\' id=\'shoutbox-refresh-button\' value=\'{$this->lang->words[\'refresh\']}\' class=\'input_submit alt\' />\n							<if test=\"$this->settings[\'shoutbox_allow_smilies\']\"> <input type=\'button\' id=\'shoutbox-smilies-button\' value=\'{$this->lang->words[\'smilies\']}\' class=\'input_submit alt\' data-clicklaunch=\"populateSmilies\" data-scope=\"shoutbox\" /></if>\n							<if test=\"$this->settings[\'shoutbox_allow_bbcode\']\"> <input type=\'button\' id=\'shoutbox-bbcode-button\' value=\'{$this->lang->words[\'bbcode\']}\' class=\'input_submit alt\' /></if>\n							<input type=\'button\' id=\'shoutbox-myprefs-button\' value=\'{$this->lang->words[\'my_prefs\']}\' class=\'input_submit alt\' />\n						</td>\n					</tr>\n				</if>\n			<else />\n				<tr class=\'row1\'>\n					<td class=\'altrow\' valign=\'top\'<if test=\"$this->memberData[\'g_shoutbox_use\']\"> style=\'width:75%\'<else /> colspan=\'2\'</if>>\n						<div id=\'shoutbox-shouts\' style=\'height:{$d[\'shout_height\']}px;overflow:auto\'>\n							{$d[\'noshouts\']}\n							{parse template=\"inactivePrompt\" group=\"skin_shoutbox\" params=\"\"}\n							<table id=\'shoutbox-shouts-table\'>\n								<tbody>\n									{$d[\'shouts\']}\n								</tbody>\n							</table>\n						</div>\n						<div id=\'shouts-global-resizer\'></div>\n						{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"glb\"}\n					</td>\n					<if test=\"$this->memberData[\'g_shoutbox_use\']\">\n						<td class=\'short row2 altrow\' style=\'width:25%;min-width:250px;\' valign=\'top\'>\n							<textarea id=\'shoutbox-global-shout\' style=\'width:92%;overflow:auto;\' rows=\'3\' cols=\'50\' class=\'input_text\'></textarea>\n							<br /><br />\n							<input type=\'button\' id=\'shoutbox-submit-button\' value=\'{$this->lang->words[\'shout\']}\' class=\'input_submit\' />\n							<input type=\'button\' id=\'shoutbox-clear-button\' value=\'{$this->lang->words[\'clear\']}\' class=\'input_submit alt\' />\n							<input type=\'button\' id=\'shoutbox-refresh-button\' value=\'{$this->lang->words[\'refresh\']}\' class=\'input_submit alt\' />\n							<br /><br />\n							<if test=\"$this->settings[\'shoutbox_allow_smilies\']\"> <input type=\'button\' id=\'shoutbox-smilies-button\' value=\'{$this->lang->words[\'smilies\']}\' class=\'input_submit alt\' data-clicklaunch=\"populateSmilies\" data-scope=\"shoutbox\" /></if>\n							<if test=\"$this->settings[\'shoutbox_allow_bbcode\']\"> <input type=\'button\' id=\'shoutbox-bbcode-button\' value=\'{$this->lang->words[\'bbcode\']}\' class=\'input_submit alt\' /></if>\n							<input type=\'button\' id=\'shoutbox-myprefs-button\' value=\'{$this->lang->words[\'my_prefs\']}\' class=\'input_submit alt\' />\n						</td>\n					</if>\n				</tr>\n			</if>\n		</table>\n	</div></div>\n</div>\n<if test=\"in_array( $this->settings[\'shoutbox_global_hook\'], array( \'t\', \'ct\' ) )\"><br class=\"clear\"/></if>\n<script type=\'text/javascript\'>\n//<![CDATA[\n{$d[\'js\']}\n//]]>\n</script>', 'hookGlobalShoutbox', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('602', '0', 'skin_shoutbox', '{$d[\'shouts\']}\n<script type=\'text/javascript\'>\nipb.shoutbox.shouts_fade([{$d[\'ids\']}]);\n</script>', 'shouts_ajax', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('603', '0', 'skin_shoutbox_hooks', '<br />\n<h4 class=\'statistics_head\'>\n	<div id=\'shoutbox-active-total\' class=\'left<if test=\"$this->settings[\'shoutbox_active_ajax\']\"> ajax_update</if>\'>{$stats[\'TOTAL\']}</div>&nbsp;{$this->lang->words[\'active_users_text\']}&nbsp;{$this->lang->words[\'on\']}&nbsp;<a href=\"{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}\" title=\'{$this->lang->words[\'view_main_shoutbox\']}\'>{$this->settings[\'shoutbox_title\']}</a> <span>{$this->lang->words[\'active_users\']}</span><br />\n	<span class=\'desc\'><span id=\'shoutbox-active-member\'>{$stats[\'MEMBERS\']}</span> {$this->lang->words[\'members\']}, <if test=\"hideGuestCount:|:$this->caches[\'group_cache\'][ $this->settings[\'guest_group\'] ][\'g_shoutbox_view\']\"><span id=\'shoutbox-active-guests\'>{$stats[\'GUESTS\']}</span> {$this->lang->words[\'guests\']}, </if><span id=\'shoutbox-active-anon\'>{$stats[\'ANON\']}</span> {$this->lang->words[\'anon_users\']}</span>\n</h2>\n<p id=\'shoutbox-active-names\'>\n	<if test=\"count($stats[\'NAMES\'])\">\n		{parse expression=\"implode( \", \", $stats[\'NAMES\'] )\"}\n	</if>\n</p>', 'hookActiveUsers', '$stats', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('601', '0', 'skin_shoutbox', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/shoutbox.js\'></script>\n{parse template=\"editorLoadJs\" group=\"editors\" params=\"$data\"}\n<h3 id=\'category_shoutbox\' class=\'maintitle\'>\n	{$this->settings[\'shoutbox_title\']}\n	<if test=\"showPopupLink:|:$this->settings[\'shoutbox_popup\'] && $this->request[\'do\'] != \'popup\'\">\n		<a href=\"#\" id=\"shoutbox-popup-button\" title=\"{$this->lang->words[\'open_popup\']}\">\n			<img src=\"{$this->settings[\'img_url\']}/shoutbox/popup.png\" alt=\"{$this->lang->words[\'open_popup\']}\" />\n		</a>\n	</if>\n</h3>\n<div id=\'shoutbox-wrapper\' class=\'ipsBox table_wrap\'><div class=\'ipsBox_container\'>\n	<table class=\'ipb_table shoutbox_table\'>\n		<tr class=\'header\'>\n			<th scope=\'col\'>\n				<if test=\"$this->memberData[\'g_shoutbox_use\'] && $this->memberData[\'g_shoutbox_view_archive\']\">\n					<div id=\'shoutbox-archive-link\' class=\'right\'>[ <a href=\'#\' id=\'load-shoutbox-archive\'>{$this->lang->words[\'archive\']}</a> ]</div>\n				</if>\n				{$this->lang->words[\'latest_shouts\']}\n			</th>\n		</tr>\n		{$data[\'announcement\']}\n		<tr class=\'row1\'>\n			<td id=\'shoutbox-shouts-td\' valign=\'top\' class=\'altrow\'>\n				{$data[\'nomods\']}\n				{$data[\'noshouts\']}\n				<div id=\'shoutbox-shouts\' style=\'height:{$data[\'shout_height\']}px;overflow:auto;\'>\n					<table id=\'shoutbox-shouts-table\'>\n						<tbody>\n							{$data[\'shouts\']}\n						</tbody>\n					</table>\n				</div>\n				<div id=\"shouts-resizer\"></div>\n				{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"app\"}\n			</td>\n		</tr>\n		<if test=\"$this->memberData[\'g_shoutbox_use\']\">\n			<tr class=\'row1\'>\n				<td class=\'short\' class=\'altrow\'>\n					{parse editor=\"shout_msg\" content=\"\" options=\"array( \'height\' => 100 )\"}\n				</td>\n			</tr>\n			<tr class=\'row2\'>\n			  	<td class=\'altrow short\'>\n					<input type=\'button\' id=\'shoutbox-submit-button\' value=\'{$this->lang->words[\'shout\']}\' class=\'input_submit\'/>\n					<input type=\'button\' id=\'shoutbox-clear-button\' value=\'{$this->lang->words[\'clear\']}\' class=\'input_submit alt\'/>\n					<input type=\'button\' id=\'shoutbox-refresh-button\' value=\'{$this->lang->words[\'refresh\']}\' class=\'input_submit alt\'/>\n					<input type=\'button\' id=\'shoutbox-myprefs-button\' value=\'{$this->lang->words[\'my_prefs\']}\' class=\'input_submit alt\'/>\n				</td>\n			</tr>\n		</if>\n	</table>\n</div></div>\n\n{parse template=\"inactivePrompt\" group=\"skin_shoutbox\" params=\"\"}\n\n<br />\n\n<div id=\'board_stats\'>		\n	<ul class=\'ipsType_small ipsList_inline\'>\n		<li class=\'clear\'>\n			<span id=\"shoutbox-total-shouts\" class=\'value\'>{$this->registry->getClass(\'shoutboxLibrary\')->shout_total}</span>\n			{$this->lang->words[\'total_shouts\']}\n		</li>\n		<if test=\"myShoutCount:|:$this->memberData[\'member_id\']\">\n			<li class=\'clear\'>\n				<span class=\'value\'>{$stats[\'my_shouts_num\']}</span>\n				{$this->lang->words[\'my_shouts\']}\n			</li>\n		</if>\n		<li class=\'clear\'>\n			<span class=\'value\'><if test=\"$stats[\'top_shouter_id\']\">{$stats[\'top_shouter_name\']}{parse template=\"user_popup\" group=\"global\" params=\"$stats[\'top_shouter_id\'], $stats[\'top_shouter_seo\']\"} ({$stats[\'top_shouts_num\']})<else />--</if></span>\n			{$this->lang->words[\'top_shouter\']}\n		</li>\n		<li class=\'clear\'>\n			<span class=\'value\'>{parse expression=\"count($this->caches[\'shoutbox_mods\'][\'groups\'])\"}</span>\n			{$this->lang->words[\'total_mods_groups\']}\n		</li>\n		<li class=\'clear\'>\n			<span class=\'value\'>{parse expression=\"count($this->caches[\'shoutbox_mods\'][\'members\'])\"}</span>\n			{$this->lang->words[\'total_mods_members\']}\n		</li>\n	</ul>\n</div>\n\n<div id=\'board_statistics\' class=\'statistics clearfix\'>\n	<h4 class=\'statistics_head\'>\n		<div id=\'shoutbox-active-total\' class=\'left\'>{$stats[\'TOTAL\']}</div>&nbsp;{$this->lang->words[\'active_users_text\']} <span>{$this->lang->words[\'active_users\']}</span><br />\n		<span class=\'desc\'><span id=\'shoutbox-active-member\'>{$stats[\'MEMBERS\']}</span> {$this->lang->words[\'members\']}, <if test=\"hideGuestCount:|:$this->caches[\'group_cache\'][ $this->settings[\'guest_group\'] ][\'g_shoutbox_view\']\"><span id=\'shoutbox-active-guests\'>{$stats[\'GUESTS\']}</span> {$this->lang->words[\'guests\']}, </if><span id=\'shoutbox-active-anon\'>{$stats[\'ANON\']}</span> {$this->lang->words[\'anon_users\']}</span>\n	</h4>\n	<p id=\'shoutbox-active-names\'>\n		<if test=\"count($stats[\'NAMES\'])\">\n			{parse expression=\"implode( \", \", $stats[\'NAMES\'] )\"}\n		</if>\n	</p>\n</div>\n<script type=\'text/javascript\'>\n/* Setup global value */\nipb.shoutbox.shoutboxGLOBAL = false;\n{$data[\'js\']}\n{$data[\'langs\']}\nipb.textEditor.getEditor().CKEditor.on(\'key\', ipb.shoutbox.keypress_handler );\n</script>', 'shoutbox', '$data=\'\', $stats', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('600', '0', 'skin_shoutbox', '<if test=\"$ajax==false\"><tr class=\'row1\' id=\'shout-{$d[\'_archive\']}row-{$d[\'s_id\']}\'></if>\n	<td align=\'top\' class=\'sidebar_shout\'>\n		<div class=\'sidebar_shout_div\'>\n			<if test=\"$this->settings[\'shoutbox_show_photos\']\">{$d[\'photo\']}&nbsp;</if>\n			<if test=\"showAtTag:|:$this->settings[\'shoutbox_at_tag\']\">\n				&nbsp;<a href=\"#\" class=\"at_member\" data-store=\"{$d[\'members_display_name\']}\" title=\"{$this->lang->words[\'insert_name\']}\">@</a>&nbsp;\n			</if>\n			<if test=\"$d[\'member_id\']\">\n				{IPSMember::makeProfileLink($d[\'_members_display_name\'], $d[\'member_id\'], $d[\'members_seo_name\'])}\n			<else />\n				<abbr title=\"{$d[\'members_display_name\']}\">{$d[\'_members_display_name\']}</abbr>\n			</if>&nbsp;-&nbsp;<span class=\'desc\' title=\'{$d[\'_date\']}\'>({$d[\'s_date\']})<if test=\"$can_edit || ($this->registry->getClass(\'shoutboxLibrary\')->moderator && $this->registry->getClass(\'shoutboxLibrary\')->checkModeratorPerm(\'edit_shouts\',true))\">&nbsp;<a href=\'{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}#edit{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.editShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'mod_opt_edit\']}\'><img src=\"{$this->settings[\'img_url\']}/comment_edit.png\" alt=\"{$this->lang->words[\'macro__edit\']}\" /></a></if><if test=\"$this->registry->getClass(\'shoutboxLibrary\')->moderator\">&nbsp;<a href=\'{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}#shout{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.modOptsLoadShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'mmenu_load_mod_opts\']}\'>{parse replacement=\"edit_folder\"}</a></if><if test=\"!$this->registry->shoutboxLibrary->checkModeratorPerm(\'delete_shouts\', true) && $this->memberData[\'g_shoutbox_delete_own\'] && $d[\'member_id\'] == $this->memberData[\'member_id\']\">&nbsp;<a class=\"deleteMyShout\" id=\"delete_{$d[\'s_id\']}\" href=\"#\" title=\"{$this->lang->words[\'mod_opt_delete\']}\"><img src=\"{$this->settings[\'img_url\']}/delete.png\" alt=\"\" /></a></if></span>\n		</div>\n		<div style=\'padding: 5px;\'>\n			<if test=\"$d[\'_ignored\'] == 1\">\n				<span id=\'unhide_shout_{$d[\'s_id\']}\' class=\'desc\'>{$this->lang->words[\'ignored_shouter\']} <a href=\'#shout{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.showHiddenShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'ignored_shouter_view\']}\'>{$this->lang->words[\'ignored_shouter_view\']}</a></span>\n				<span id=\'hidden_shout_{$d[\'s_id\']}\' style=\'display:none\'>{$d[\'s_message\']}</span>\n			<else />\n				{$d[\'s_message\']}\n			</if>\n		</div>\n	</td>\n<if test=\"$ajax==false\"></tr></if>', 'shout_row_sidebar', '$d=\'\',$can_edit=false,$ajax=false', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('597', '0', 'skin_shoutbox', '<script type=\'text/javascript\'>\nipb.shoutbox.my_prefs = { {$d[\'prefs\']} };\nipb.shoutbox.popupUpdateStatus(\"{$d[\'msg\']}\", true);\nipb.shoutbox.updateJSPreferences();\n</script>', 'popupMyPrefsUpdate', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('598', '0', 'skin_shoutbox', '<if test=\"jsBugPatch:|:$this->caches[\'app_cache\'][\'core\'][\'app_long_version\'] < 32007\">\n	<script type=\"text/javascript\">\n	//<![CDATA[\n		inACP				= false;\n		ipb.vars[\'is_touch\']		= <if test=\"istl:|:$this->registry->output->isLargeTouchDevice()\">\'large\';<else /><if test=\"istm:|:$this->registry->output->isSmallTouchDevice()\">\'small\';<else />false;</if></if>\n		ipb.vars[\'member_group\']	= {parse expression=\"json_encode( array( \'g_mem_info\' => $this->memberData[\'g_mem_info\'] ) )\"}\n	//]]>\n	</script>\n</if>\n<div id=\"content\">\n	{$output}\n</div>', 'popupWrapper', '$output', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('599', '0', 'skin_shoutbox', '<if test=\"$ajax==false\"><tr class=\'row2\' id=\'shout-{$d[\'_archive\']}row-{$d[\'s_id\']}\'></if>\n	<if test=\"$this->settings[\'shoutbox_show_photos\']\"><td style=\'width: 1%; white-space: nowrap;\'>{$d[\'photo\']}</td></if>\n	<td style=\'width: 1%; white-space: nowrap;\'>\n		<if test=\"showAtTag:|:$this->settings[\'shoutbox_at_tag\']\">\n			<a href=\"#\" class=\"at_member\" data-store=\"{$d[\'members_display_name\']}\" title=\"{$this->lang->words[\'insert_name\']}\">@</a>&nbsp;\n		</if>\n		<if test=\"$d[\'member_id\']\">\n			{IPSMember::makeProfileLink($d[\'_members_display_name\'], $d[\'member_id\'], $d[\'members_seo_name\'])}\n		<else />\n			<abbr title=\"{$d[\'members_display_name\']}\">{$d[\'_members_display_name\']}</abbr>\n		</if>\n	</td>\n	<td style=\'width: 1%; white-space: nowrap;\'>:</td>\n	<td style=\'width: 98%;\'>\n		<span class=\'right desc\' title=\'{$d[\'_date\']}\'>({$d[\'s_date\']})<if test=\"$can_edit || ($this->registry->getClass(\'shoutboxLibrary\')->moderator && $this->registry->getClass(\'shoutboxLibrary\')->checkModeratorPerm(\'edit_shouts\', true))\">&nbsp;<a href=\'{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}#edit{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.editShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'mod_opt_edit\']}\'><img src=\"{$this->settings[\'img_url\']}/comment_edit.png\" alt=\"{$this->lang->words[\'macro__edit\']}\" /></a></if><if test=\"$this->registry->getClass(\'shoutboxLibrary\')->moderator\">&nbsp;<a href=\'{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}#shout{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.modOptsLoadShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'mmenu_load_mod_opts\']}\'>{parse replacement=\"edit_folder\"}</a></if><if test=\"!$this->registry->shoutboxLibrary->checkModeratorPerm(\'delete_shouts\', true) && $this->memberData[\'g_shoutbox_delete_own\'] && $d[\'member_id\'] == $this->memberData[\'member_id\']\">&nbsp;<a class=\"deleteMyShout\" id=\"delete_{$d[\'s_id\']}\" href=\"#\" title=\"{$this->lang->words[\'mod_opt_delete\']}\"><img src=\"{$this->settings[\'img_url\']}/delete.png\" alt=\"\" /></a></if></span>\n		<if test=\"$d[\'_ignored\'] == 1\">\n			<span id=\'unhide_shout_{$d[\'s_id\']}\' class=\'desc\'>{$this->lang->words[\'ignored_shouter\']} <a href=\'#shout{$d[\'s_id\']}\' onclick=\'return ipb.shoutbox.showHiddenShout({$d[\'s_id\']})\' title=\'{$this->lang->words[\'ignored_shouter_view\']}\'>{$this->lang->words[\'ignored_shouter_view\']}</a></span>\n			<span id=\'hidden_shout_{$d[\'s_id\']}\' style=\'display:none\'>{$d[\'s_message\']}</span>\n		<else />\n			{$d[\'s_message\']}\n		</if>\n	</td>\n<if test=\"$ajax==false\"></tr></if>', 'shout_row', '$d=\'\',$can_edit=false,$ajax=false', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('596', '0', 'skin_shoutbox', '<h3>{$this->lang->words[\'my_prefs_panel\']}</h3>\n<div class=\"ipsBox table_wrap\">\n	<div class=\"ipsBox_container\">\n		{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"myprefs\"}\n		<table class=\"ipb_table\">\n			<tr>\n				<td colspan=\"2\">\n					{$this->lang->words[\'my_prefs_welcome\']}\n				</td>\n			</tr>\n			<tr class=\"row2\">\n				<td class=\"altrow\" colspan=\"2\">\n					<strong id=\"shoutbox-popup-status\">{$this->lang->words[\'my_prefs_loaded\']}</strong>\n				</td>\n			</tr>\n			<tr>\n				<td style=\"width: 50%;\" class=\"short\">\n					<strong>{$this->lang->words[\'my_prefs_gsb\']}</strong>\n					<br />\n					<if test=\"$d[\'global_shoutbox\']\">\n						<label for=\"my_prefs_gsb_y\">{$this->lang->words[\'yes\']}</label> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_gsb\" value=\"1\" id=\"my_prefs_gsb_y\" {$d[\'gsb_y\']}/> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_gsb\" value=\"0\" id=\"my_prefs_gsb_n\" {$d[\'gsb_n\']}/> <label for=\"my_prefs_gsb_n\">{$this->lang->words[\'no\']}</label>\n					<else />\n						<span class=\"shoutbox_disabled\">{$this->lang->words[\'global_shoutbox_off\']}</span>\n						<input type=\"hidden\" name=\"my_prefs_gsb\" value=\"<if test=\"$d[\'gsb_y\'] == \'checked\'\">1<else />0</if>\" id=\"my_prefs_gsb_y\" />\n					</if>\n				</td>\n				<td style=\"width: 50%;\" class=\"short\">\n					<strong>{$this->lang->words[\'my_prefs_ets\']}</strong>\n					<br />\n					<label for=\"my_prefs_ets_y\">{$this->lang->words[\'yes\']}</label> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_ets\" value=\"1\" id=\"my_prefs_ets_y\" {$d[\'ets_y\']}/> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_ets\" value=\"0\" id=\"my_prefs_ets_n\" {$d[\'ets_n\']}/> <label for=\"my_prefs_ets_n\">{$this->lang->words[\'no\']}</label>\n				</td>\n			</tr>\n			<tr>\n				<td class=\"short\">\n					<strong>{$this->lang->words[\'my_prefs_drb\']}</strong>\n					<br />\n					<label for=\"my_prefs_drb_y\">{$this->lang->words[\'yes\']}</label> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_drb\" value=\"1\" id=\"my_prefs_drb_y\" {$d[\'drb_y\']}/> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_drb\" value=\"0\" id=\"my_prefs_drb_n\" {$d[\'drb_n\']}/> <label for=\"my_prefs_drb_n\">{$this->lang->words[\'no\']}</label>\n				</td>\n				<td class=\"short\">\n					<strong>{$this->lang->words[\'my_prefs_eqc\']}</strong>\n					<br />\n					<label for=\"my_prefs_eqc_y\">{$this->lang->words[\'yes\']}</label> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_eqc\" value=\"1\" id=\"my_prefs_eqc_y\" {$d[\'eqc_y\']}/> <input type=\"radio\" class=\"input_radio\" name=\"my_prefs_eqc\" value=\"0\" id=\"my_prefs_eqc_n\" {$d[\'eqc_n\']}/> <label for=\"my_prefs_eqc_n\">{$this->lang->words[\'no\']}</label>\n				</td>\n			</tr>\n			<tr>\n				<td class=\"short\" colspan=\"2\">\n					<input type=\"button\" id=\"myprefs_save\" value=\"{$this->lang->words[\'save_prefs\']}\" class=\"input_submit\" />\n					<input type=\"button\" id=\"myprefs_restore\" value=\"{$this->lang->words[\'restore_default\']}\" class=\"ipsButton_secondary\" />\n				</td>\n			</tr>\n		</table>\n	</div>\n</div>', 'popupMyPrefs', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('592', '0', 'skin_shoutbox', '<div id=\'shoutbox-no-mods-message\' class=\'message error short block_wrap\'>{$this->lang->words[\'error_no_mods\']}</div>', 'no_mods', '', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('593', '0', 'skin_shoutbox', '<div id=\'shoutbox-no-shouts-message\' class=\'message error short block_wrap\'>{$this->lang->words[\'error_no_shouts\']}</div>', 'no_shouts', '', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('594', '0', 'skin_shoutbox', '<div id=\'shoutbox-inline-error-{$area}\' class=\'message error block_wrap\' style=\'display:none;\'></div>', 'popupInlineError', '$area=\'app\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('595', '0', 'skin_shoutbox', '<h3>{$this->lang->words[\'mod_panel_title\']}</h3>\n<div class=\"ipsBox table_wrap\">\n	<div class=\"ipsBox_container\">\n		{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"moderator\"}\n		<table class=\"ipb_table\">\n			<tr>\n				<td valign=\'top\' width=\'25%\'>\n					<if test=\"$t == \'shout\'\">\n						<strong>{$this->lang->words[\'shout_number\']} #{$d[\'s_id\']}</strong><br />\n						<strong>{$this->lang->words[\'by\']}</strong>: {$d[\'shouted_by\']}\n					<else />\n						<strong>{$this->lang->words[\'member\']}</strong>:\n						<br />\n						<a href=\'{parse url=\"showuser={$d[\'member_id\']}\" template=\"showuser\" seotitle=\"{$d[\'members_seo_name\']}\" base=\"public\"}\' title=\'{$d[\'members_display_name\']}\'>{$d[\'_members_display_name\']}</a>\n					</if>\n				</td>\n				<td valign=\'top\' width=\'75%\'>\n					{$this->lang->words[\'mod_opts_welcome\']}\n				</td>\n			</tr>\n			<tr>\n				<td colspan=\'2\'>\n					{$d[\'s_message\']}\n				</td>\n			</tr>\n			<tr  class=\'row2\'>\n				<td class=\'altrow\' colspan=\'2\'>\n					<strong id=\'shoutbox-popup-status\'>{$this->lang->words[\'mod_opts_start_status\']}</strong>\n				</td>\n			</tr>\n			<tr class=\'row2\'>\n				<td id=\'shoutbox-popup-content\' colspan=\'2\'>\n					{$this->lang->words[\'mod_opts_start_content\']}\n				</td>\n			</tr>\n			<tr>\n				<td colspan=\'2\'>\n					<ul class=\"topic_buttons\">\n						<if test=\"$m[\'m_edit_shouts\'] && $t == \'shout\'\">\n							<li id=\'edit_shout\' class=\'clickable\'><img src=\"{$this->settings[\'img_url\']}/comment_edit.png\" alt=\"{$this->lang->words[\'macro__edit\']}\" /> {$this->lang->words[\'mod_opt_edit\']}</li>\n							<li id=\'editHistory_shout\' class=\'clickable\'<if test=\"!is_array($d[\'s_edit_history\']) || !count($d[\'s_edit_history\'])\"> style=\'display:none;\'</if>>{parse replacement=\"display_name\"} {$this->lang->words[\'mod_opt_edit_history\']}</li>\n						</if>\n						<if test=\"( ($m[\'m_delete_shouts\'] && $own) || $m[\'m_delete_shouts_user\'] ) && $t == \'shout\'\">\n							<li id=\'delete_shout\' class=\'clickable\'><img src=\"{$this->settings[\'img_url\']}/comment_delete.png\" alt=\"{$this->lang->words[\'macro__delete\']}\" /> {$this->lang->words[\'mod_opt_delete\']}</li>\n						</if>\n						<if test=\"($m[\'m_delete_shouts\'] && $own) || $m[\'m_delete_shouts_user\']\">\n							<li id=\'deleteAll_shout\' class=\'clickable\'><img src=\"{$this->settings[\'img_url\']}/comment_delete.png\" alt=\"{$this->lang->words[\'macro__delete\']}\" /> {$this->lang->words[\'mod_opt_delete_all\']}</li>\n						</if>\n						<if test=\"$d[\'member_id\'] > 0 && $this->memberData[\'member_id\'] != $d[\'member_id\']\">\n							<if test=\"$m[\'m_ban_members\']\">\n								<li id=\'ban_shout\' class=\'clickable\'<if test=\"$d[\'_cache\'][\'shoutbox_banned\']\"> style=\'display:none;\'</if>>{parse replacement=\"spammer_on\"} {$this->lang->words[\'mod_opt_ban\']}</li>\n							</if>\n							<if test=\"$m[\'m_unban_members\']\">\n								<li id=\'unban_shout\' class=\'clickable\'<if test=\"!$d[\'_cache\'][\'shoutbox_banned\']\"> style=\'display:none;\'</if>>{parse replacement=\"spammer_off\"} {$this->lang->words[\'mod_opt_unban\']}</li>\n							</if>\n							<if test=\"$m[\'m_remove_mods\'] && $d[\'_is_a_mod\'] && $d[\'member_id\'] > 0\">\n								<li id=\'removeMod_shout\' class=\'clickable\'><img src=\"{$this->settings[\'img_url\']}/cross.png\" title=\"{$this->lang->words[\'macro__deletedmsg\']}\" alt=\"*\" /> {$this->lang->words[\'mod_opt_delmod\']}</li>\n							</if>\n						</if>\n					</ul>\n				</td>\n			</tr>\n		</table>\n		\n	</div>\n</div>\n<script type=\'text/javascript\'>\n<if test=\"$t == \'shout\'\">\n	ipb.shoutbox.mod_shout_id = parseInt({$d[\'s_id\']});\n<else />\n	ipb.shoutbox.mod_member_id = parseInt({$d[\'member_id\']});\n</if>\n</script>', 'popupModerator', '$d=\'\',$m=\'\',$t=\'\', $own=0', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('591', '0', 'skin_shoutbox', '<if test=\"substr( $action, 0, 4 ) != \'edit\'\">\n	<if test=\"$action == \'delete\'\">\n		{$this->lang->words[\'mod_opt_confirm_delete\']}\n	</if>\n	<if test=\"$action == \'delete-all\'\">\n		{$this->lang->words[\'mod_opt_confirm_delete_all\']}<br /><br />\n		<em>{$this->lang->words[\'mod_shouts_to_delete\']}:&nbsp;&nbsp;&nbsp;{$data[\'total\']}</em>\n	</if>\n	<if test=\"$action == \'ban\'\">\n		{$this->lang->words[\'mod_opt_confirm_ban\']}\n	</if>\n	<if test=\"$action == \'unban\'\">\n		{$this->lang->words[\'mod_opt_confirm_unban\']}\n	</if>\n	<if test=\"$action == \'delmod\'\">\n		{$this->lang->words[\'mod_opt_confirm_delmod\']}\n	</if>\n	<br /><br />\n	<div class=\"short\">\n		<input type=\"button\" id=\"confirm_option_yes\" value=\"{$this->lang->words[\'yes\']}\" class=\"input_submit\" />&nbsp;&nbsp;&nbsp;\n		<input type=\"button\" id=\"confirm_option_no\" value=\"{$this->lang->words[\'no\']}\" class=\"ipsButton_secondary\" />\n	</div>\n<else />\n	<if test=\"$action == \'editHistory\'\">\n		{$this->lang->words[\'mod_edit_history_text\']}\n		<br /><br />\n		<table class=\"ipb_table\">\n			<tr class=\"header\">\n				<th style=\"width: 75%;\">{$this->lang->words[\'member_name\']}</th>\n				<th class=\"short\" style=\"width: 25%;\">{$this->lang->words[\'date\']}</th>\n			</tr>\n			<foreach loop=\"$data as $edit\">\n				<tr class=\"{$edit[\'class\']}\">\n					<td valign=\"top\">\n						<a href=\"{parse url=\"showuser={$edit[\'member_id\']}\" base=\"public\"}\">{$edit[\'_name\']}</a><br />\n						<span class=\"desc\">{$this->lang->words[\'ip\']}: <em>{$edit[\'ip\']}</em></span>\n					</td>\n					<td class=\"short\" valign=\"middle\">{$edit[\'_date\']}</td>\n				</tr>\n			</foreach>\n		</table>\n		<br />\n	<else />\n		<if test=\"$this->registry->getClass(\'shoutboxLibrary\')->global_on\">\n			<h3>{$this->lang->words[\'mod_opt_edit\']}</h3>\n			{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"editShout\"}\n		</if>\n		<div class=\"ipsPad\">\n			{parse editor=\"shout_msg\" content=\"$data[text]\" options=\"array( \'height\' => 100 )\"}\n			<div class=\"short ipsPad\">\n				<input type=\"button\" id=\"mod_edit_shout_confirm\" value=\"{$this->lang->words[\'mod_edit_shout\']}\" class=\"input_submit\" />\n				<input type=\"button\" id=\"mod_edit_shout_clear\" value=\"{$this->lang->words[\'clear\']}\" class=\"ipsButton_secondary\" />\n				<input type=\"button\" id=\"mod_edit_shout_cancel\" value=\"{$this->lang->words[\'cancel\']}\" class=\"ipsButton_secondary\" />\n			</div>\n		</div>\n	</if>\n</if>', 'mod_opts_content', '$action=\'\',$data=array()', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('586', '0', 'skin_shoutbox', '<script type=\'text/javascript\'>\nipb.shoutbox.shout_pages = {$d[\'pages\']};\nipb.shoutbox.archive_update_pager({$d[\'curpage\']});\n</script>', 'archive_ajax', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('587', '0', 'skin_shoutbox', '<div class=\'desc\'>{$m}</div>', 'archive_message', '$m=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('588', '0', 'skin_shoutbox', '<table id=\'shoutbox-inactive-prompt\' style=\'display:none;\'>\n	<tr class=\'row1\'>\n		<td class=\'altrow short\' valign=\'middle\'>\n			{parse expression=\"str_replace( \"<#MINUTES#>\", $this->registry->getClass(\'shoutboxLibrary\')->inactivity_cutoff, $this->lang->words[\'inactive_text\'] )\"}\n			<br /><br />\n			<input type=\'button\' value=\"{$this->lang->words[\'im_back\']}\" class=\'input_submit\' onclick=\'ipb.shoutbox.processInactivePrompt();\' />\n		</td>\n	</tr>\n</table>', 'inactivePrompt', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('589', '0', 'skin_shoutbox', 'ipb.shoutbox.myMemberID       = parseInt({$this->memberData[\'member_id\']});\nipb.shoutbox.can_use          = parseInt({$this->memberData[\'g_shoutbox_use\']});\nipb.shoutbox.can_edit         = parseInt({$this->memberData[\'g_shoutbox_edit\']});\nipb.shoutbox.flood_limit      = parseInt({$this->settings[\'shoutbox_flood_limit\']});\nipb.shoutbox.bypass_flood     = parseInt({$this->memberData[\'g_shoutbox_bypass_flood\']});\nipb.shoutbox.can_access_acp   = parseInt({$this->memberData[\'g_access_cp\']});\nipb.shoutbox.view_archive     = <if test=\"$this->memberData[\'g_shoutbox_view_archive\']\">true<else />false</if>;\nipb.shoutbox.enable_fade      = parseInt({$this->settings[\'shoutbox_shout_fade\']});\nipb.shoutbox.inactive_timeout = parseInt({$this->registry->getClass(\'shoutboxLibrary\')->inactivity_cutoff});\nipb.shoutbox.hide_refresh     = parseInt({$this->settings[\'shoutbox_autohide_refresh\']});\nipb.shoutbox.members_refresh  = $this->settings[\'shoutbox_members_viewing_refresh\'] < 30 ? 30000 : parseInt({$this->settings[\'shoutbox_members_viewing_refresh\']})*1000;\nipb.shoutbox.shouts_refresh   = $this->settings[\'shoutbox_shouts_refresh\'] < 30 ? 30000 : parseInt({$this->settings[\'shoutbox_shouts_refresh\']})*1000;\nipb.shoutbox.total_shouts     = parseInt({$this->registry->getClass(\'shoutboxLibrary\')->shout_total});\nipb.shoutbox.shout_order      = \'{$this->registry->getClass(\'shoutboxLibrary\')->shouts_order}\';\nipb.shoutbox.moderator        = {$this->registry->getClass(\'shoutboxLibrary\')->moderator};\n<if test=\"$this->registry->getClass(\'shoutboxLibrary\')->moderator\">\nipb.shoutbox.mod_perms        = { {$this->registry->getClass(\'shoutboxLibrary\')->mod_perms_js} };\n</if>\nipb.shoutbox.my_prefs         = { {$this->registry->getClass(\'shoutboxLibrary\')->prefs_js} };\nipb.shoutbox.img_disable      = parseInt({$this->settings[\'shoutbox_disable_refresh_image\']});\nipb.shoutbox.member_name      = \'{$this->memberData[\'members_display_name\']}\';\nipb.shoutbox.can_me_tag       = parseInt({$this->settings[\'shoutbox_me_tag\']});', 'javascript', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('590', '0', 'skin_shoutbox', '<span class=\'name\'>{$link}<if test=\"$this->registry->getClass(\'shoutboxLibrary\')->moderator\">&nbsp;<a href=\'{parse url=\"app=shoutbox\" seotitle=\"false\" base=\"public\"}#member{$id}\' onclick=\'return ipb.shoutbox.modOptsLoadMember({$id})\' title=\'{$this->lang->words[\'mmenu_load_mod_opts\']}\'><img src=\"{$this->settings[\'img_url\']}/user_edit.png\" alt=\"{$this->lang->words[\'macro__useredit\']}\" /></a></if></span>', 'memberViewingName', '$id, $link', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('583', '0', 'skin_shoutbox', 'Event.observe(window, \'load\', function() {\n<if test=\"$data[\'type\'] == \'mod-shout\' && $data[\'id\'] > 0\">ipb.shoutbox.modOptsLoadShout({$data[\'id\']});</if>\n<if test=\"$data[\'type\'] == \'mod-member\' && $data[\'mid\'] > 0\">ipb.shoutbox.modOptsLoadMember({$data[\'mid\']});</if>\n<if test=\"$data[\'type\'] == \'archive\'\">ipb.shoutbox.displayArchive();</if>\n<if test=\"$data[\'type\'] == \'myprefs\'\">ipb.shoutbox.myPrefsLoad();</if>\n<if test=\"$data[\'type\'] == \'edit-shout\' && $data[\'id\']\">ipb.shoutbox.editShout({$data[\'id\']});</if>\n});', 'ajax_jscmd', '$data=\'\'', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('584', '0', 'skin_shoutbox', '<tr id=\'shoutbox-announcement-row\' class=\'row2\'<if test=\"$hide\"> style=\'display:none;\'</if>>\n	<td class=\'altrow\' valign=\'middle\'<if test=\"$global\"> colspan=\'2\'</if>>\n		<div id=\'shoutbox-announcement-text\' class=\'message\'>\n			{$this->settings[\'shoutbox_announcement\']}\n		</div>\n	</td>\n</tr>', 'announcement', '$global=true, $hide=true', '1338126408', '0', '0', '0', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('585', '0', 'skin_shoutbox', '<h3>{$this->lang->words[\'sb_archive\']}</h3>\n{parse template=\"popupInlineError\" group=\"skin_shoutbox\" params=\"archive\"}\n<div id=\'beforeButtonClick\' class=\'ipsBox_container\'>\n	<table class=\'ipb_table\'>\n		<tr>\n			<td valign=\'top\' colspan=\'2\'>\n			  {$this->lang->words[\'sb_archive_welcome\']}\n			</td>\n			<td style=\"vertical-align: top;\">\n				<input type=\'button\' id=\'shoutbox_archive_filters\' value=\'{$this->lang->words[\'quick_filters\']}\' class=\'input_submit ipbmenu right\' style=\'width:140px\'/>\n				<ul class=\'ipbmenu_content\' id=\'shoutbox_archive_filters_menucontent\' style=\'width:138px\'>\n					<li id=\'filter_mine\' class=\'clickable\'><a href=\"#\">{$this->lang->words[\'my_shouts\']}</a></li>\n					<li id=\'filter_today\' class=\'clickable\'><a href=\"#\">{$this->lang->words[\'today_shouts\']}</a></li>\n					<li id=\'filter_yesterday\' class=\'clickable\'><a href=\"#\">{$this->lang->words[\'yesterday_shouts\']}</a></li>\n					<li id=\'filter_month\' class=\'clickable\'><a href=\"#\">{$this->lang->words[\'month_shouts\']}</a></li>\n					<li id=\'filter_all\' class=\'clickable\'><a href=\"#\">{$this->lang->words[\'all_shouts\']}</a></li>\n				</ul>\n			</td>\n		</tr>\n		\n		<tr class=\'row2\'>\n			<td class=\'altrow\' valign=\'top\' colspan=\'3\'>\n				<strong><span id=\'shoutbox-popup-status\'></span></strong>\n			</td>\n		</tr>\n		<tr>\n			<td valign=\'middle\' width=\'5%\'>\n				<strong>{$this->lang->words[\'start\']}:</strong>\n			</td>\n			<td valign=\'top\' width=\'70%\'>\n				<select class=\'input_text\' id=\'filter_start_month\'>{$d[\'s_months\']}</select>\n				<select class=\'input_text\' id=\'filter_start_day\'>{$d[\'s_days\']}</select>\n				<select class=\'input_text\' id=\'filter_start_year\'>{$d[\'s_years\']}</select>\n				<select class=\'input_text\' id=\'filter_start_hour\'>{$d[\'s_hours\']}</select>\n				<select class=\'input_text\' id=\'filter_start_minute\'>{$d[\'s_minutes\']}</select>\n				<if test=\"ampmForStart:|:$this->settings[\'shoutbox_archive_clock\'] == \'ampm\'\">\n					<select class=\'input_text\' id=\'filter_start_meridiem\'>{$d[\'s_meridiems\']}</select>\n				</if>\n			</td>\n			<td valign=\'bottom\' width=\'25%\'>\n			  <strong>{$this->lang->words[\'filter_by_names\']}:</strong>\n			</td>\n		</tr>\n		<tr>\n			<td valign=\'middle\'>\n				<strong>{$this->lang->words[\'end\']}:</strong>\n			</td>\n			<td valign=\'top\'>\n				<select class=\'input_text\' id=\'filter_end_month\'>{$d[\'e_months\']}</select>\n				<select class=\'input_text\' id=\'filter_end_day\'>{$d[\'e_days\']}</select>\n				<select class=\'input_text\' id=\'filter_end_year\'>{$d[\'e_years\']}</select>\n				<select class=\'input_text\' id=\'filter_end_hour\'>{$d[\'e_hours\']}</select>\n				<select class=\'input_text\' id=\'filter_end_minute\'>{$d[\'e_minutes\']}</select>\n				<if test=\"ampmForEnd:|:$this->settings[\'shoutbox_archive_clock\'] == \'ampm\'\">\n					<select class=\'input_text\' id=\'filter_end_meridiem\'>{$d[\'e_meridiems\']}</select>\n				</if>\n			</td>\n			<td valign=\'top\'>\n			  <input class=\'input_text\' type=\'text\' id=\'filter_member_name\' value=\'\' />\n			</td>\n		</tr>\n	  \n		<tr>\n			<td colspan=\'3\' style=\'padding:0;margin:0;\'>\n				<p class=\'submit\' width=\'100%\'>\n					<input type=\'button\' id=\'shoutbox-archive-filter-button\' value=\'{$this->lang->words[\'filter\']}\' class=\'input_submit\' />\n				</p>\n			</td>\n		</tr>\n	</table>\n</div>\n<div id=\'afterButtonClick\' class=\'ipsBox_container\' style=\'display:none;\'>\n	<table class=\'ipb_table\'>\n		<tr>\n			<td align=\'left\'>\n				<div id=\'shoutbox-archive-pages-floater\' class=\'right\'>\n					<div id=\'shoutbox-archive-pages-data\'>abc</div>\n				</div>\n				<a href=\'javascript:void(0);\' id=\'backToFilters\'>{$this->lang->words[\'back_to_filters\']}</a><br />\n				<div id=\'shoutbox-popup-content\' style=\'position:relative\'>\n					<div id=\'shoutbox-archive-shouts-div\' style=\'width:100%;height:{$d[\'height\']}px;overflow:auto\'>\n						<table id=\'shoutbox-archive-shouts\'>\n							<tbody>\n							</tbody>\n						</table>\n					</div>\n				</div>\n			</td>\n	  </tr>\n	</table>\n</div>\n<script type=\'text/javascript\'>\nipb.shoutbox.my_dname     = \"{parse expression=\"str_replace( \'\"\', \'\\\\\\\\\"\', $this->memberData[\'members_display_name\'] )\"}\";\nipb.shoutbox.oldest_shout = \"{$d[\'oldestShout\']}\";\n//$(\'shoutbox-archive-shouts-div\').observe(\'scroll\', ipb.shoutbox.archive_update_floaters );\n\n$(\'filter_member_name\').observe(\'click\', function() {\n	if( $(\'filter_member_name\').value == \"{parse expression=\"str_replace( \'\"\', \'\\\\\\\\\"\', $this->lang->words[\'member_name\'] )\"}\" )\n	{\n		$(\'filter_member_name\').value=\'\';\n	}\n} );\n$(\'filter_member_name\').observe(\'focus\', function() {\n	ipb.shoutbox.popupUpdateStatus(\'filter_member_name_status\');\n} );\n$(\'filter_member_name\').observe(\'blur\', function() {\n	ipb.shoutbox.popupUpdateStatus(\'sb_archive_loaded\');\n} );\n</script>', 'archive', '$d=\'\'', '1338126408', '0', '0', '0', '0', 'root');
