INSERT INTO `ibf_skin_templates` VALUES ('635', '0', 'skin_status_like', '{parse striping=\"faverave\" classes=\"row1,row2\"}\n<h3>Liked By</h3>\n<div class=\'general_box likepop\'>\n	<foreach loop=\"$data as $mid => $data\">\n		<div class=\'{parse striping=\"faverave\"}\'>\n			<em class=\'desc\'>Added: {parse date=\"$data[\'like_added\']\" format=\"short\"}</em>\n			<img src=\'{$data[\'pp_thumb_photo\']}\' width=\'{$data[\'pp_thumb_width\']}\' height=\'{$data[\'pp_thumb_height\']}\' class=\'photo\' />\n			<div>\n				<strong>{$data[\'members_display_name\']}</strong>\n				<p class=\'desc\'>\n					{parse expression=\"IPSLib::makeNameFormatted( $data[\'g_title\'], $data[\'g_id\'] )\"}\n					<br />\n					Joined: {parse date=\"$data[\'joined\']\" format=\"joined\"}\n				</p>\n			</div>\n		</div>\n	</foreach>\n</div>', 'likeMoreDialogue', '$data, $relId', '1290445375', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('636', '0', 'skin_status_like', '<h3>{$this->lang->words[\'fave_title\']}</h3>\n<div class=\'general_box\'>\n	<fieldset>\n		<ul>\n			<li class=\'field checkbox\'>\n				<input type=\"checkbox\" name=\"notify\" id=\"like_notify\" class=\"input_check\" value=\"1\" />\n				<label for=\"like_notify\">{parse expression=\"sprintf($this->lang->words[\'label_notify\'], $data[\'notifyType\'][1])\"}</label>\n			</li>\n			<li class=\'field\'>\n				<label for=\"like_freq\">{$this->lang->words[\'label_freq\']}\n					<select name=\"freq\" id=\"like_freq\" class=\"input_select\">\n						<foreach loop=\"$data[\'frequencies\'] as $freq\">\n							<option value=\"$freq\">{$this->lang->words[ \'freq_\' . $freq ]}</option>\n						</foreach>\n					</select>\n				</label>		 				\n			</li>\n			<li class=\'field checkbox\'>\n				<input type=\"checkbox\" name=\"anon\" id=\"like_anon\" class=\"input_check\" value=\"1\" />\n				<label for=\"like_anon\">{$this->lang->words[\'label_anon\']}<br /><span class=\'desc\'>{$this->lang->words[\'label_anon_desc\']}</span></label>\n			</li>\n			<li class=\"submit\" style=\"float:right\">\n				<input type=\"submit\" value=\"Set Favorite\" class=\"input_submit _fsubmit\" />\n			</li>\n	</fieldset>\n</div>', 'likeSetDialogue', '$app, $area, $relid, $data', '1290445375', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('637', '0', 'skin_status_like', '<php>\nif ( ! function_exists( \'parsetemplate\' ) )\n{\n	function parsetemplate( $content=\'\' )\n	{\n		$out = \'\';\n		\n		/* Make sure javascript doesn\'t complain! */\n		$out = str_replace( \'\"\', \"\'\", $content );\n		$out = str_replace( \"\\n\", \'\', $out );\n		$out = str_replace( \"\\t\", \'\', $out );\n		$out = str_replace( \"\\r\", \'\', $out );\n		\n		/* Return the happy HTML */\n		return $out;\n	}\n}\n$template = parsetemplate(\"{parse template=\"likeSummaryContents\" group=\"status_like\" params=\"$data, $relId, $opts\"}\");\n</php>\n{parse js_module=\"like\"}\n<span class=\'ips_like\' data-app=\"{$data[\'app\']}\" data-area=\"{$data[\'area\']}\" data-relid=\"{$relId}\" data-isfave=\"{$data[\'iFave\']}\">\n	&middot; <a href=\'#\' title=\"<if test=\"$data[\'iFave\']\">Unlike and stop notifications<else />Like and receive notifications on updates</if>\" class=\'ftoggle <if test=\"$data[\'iFave\']\"> on</if><if test=\"$opts[\'button-new-line\']\"> _newline</if>\'><if test=\"$data[\'iFave\']\">Unlike<else />Like</if></a><if test=\"$data[\'totalCount\']>0\">&nbsp;<a href=\'#\' title=\'More\' class=\'_fmore total_count\'>({$data[\'totalCount\']})</a></if>\n</span>\n<script type=\"text/javascript\">	\n	$(\'statusContent-{$relId}\').insert( { bottom: \"{$template}\" } );\n</script>', 'likeSummary', '$data, $relId, $opts', '1290445375', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('638', '0', 'skin_status_like', '<if test=\"IPS_IS_AJAX\">\n&middot; <a href=\'#\' title=\"<if test=\"$data[\'iFave\']\">Unlike and stop notifications<else />Like and receive notifications on updates</if>\" class=\'ftoggle <if test=\"$data[\'iFave\']\"> on</if><if test=\"$opts[\'button-new-line\']\"> _newline</if>\'><if test=\"$data[\'iFave\']\">Unlike<else />Like</if></a><if test=\"$data[\'totalCount\']>0\">&nbsp;<a href=\'#\' title=\'More\' class=\'_fmore total_count\'>({$data[\'totalCount\']})</a></if>\n<php>\n/* Make sure javascript doesn\'t complain! */\n$data[\'formatted\'] = str_replace( \'\"\', \"\'\", $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\n\", \'\', $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\t\", \'\', $data[\'formatted\'] );\n$data[\'formatted\'] = str_replace( \"\\r\", \'\', $data[\'formatted\'] );\n	\n$template	= \"<div class=\'ips_like\' id=\'like_info_{$relId}\'>{$data[\'formatted\']}</div>\";\n$update		= \"{$data[\'formatted\']}\";\n</php>\n<if test=\"!$this->request[\'likesidebar\']\">\n<script type=\'text/javascript\'>\n	if( $(\'like_info_{$relId}\') )\n	{\n		<if test=\"$data[\'formatted\']\">\n			$(\'like_info_{$relId}\').update( \"{$update}\" );\n		<else />\n			$(\'like_info_{$relId}\').remove();\n		</if>\n	}\n	else\n	{\n		$(\'statusContent-{$relId}\').insert( { bottom: \"{$template}\" } );\n	}\n</script>\n</if>\n<else />\n<if test=\"$data[\'formatted\']&&!$this->request[\'likesidebar\']\"><div class=\'ips_like\' id=\'like_info_{$relId}\'>{$data[\'formatted\']}</div></if>\n</if>', 'likeSummaryContents', '$data, $relId, $opts=array()', '1290445375', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('639', '0', 'skin_status_like', '<script type=\'text/javascript\' src=\'{$this->settings[\'public_dir\']}js/ips.like.js\'></script>\n	<style type=\'text/css\'>\n		.status_like { display: inline; }\n		\n		.status_like span.ips_like {\n			display: inline;\n			background: transparent;\n			clear: none;\n			padding: 0;\n			font-size: 1em;\n			line-height: 100%;\n		}\n		\n			.status_like span.ips_like a {\n				border: none;\n				background: transparent;\n				color: #284B72;\n				margin: 0;\n				padding: 0;\n				float: none;\n				font-size: 1em;\n			}\n			\n				.status_like span.ips_like a:hover {\n					background: transparent !important;\n					color: #528f6c;\n				}\n.total_count { display: none !important; }\n<if test=\"$this->request[\'likesidebar\']==1\">\n.total_count { display: inline !important; }\n.status_like { font-size: 0.8em; }\n</if>\n	</style>\n<span class=\'status_like\'>{$like}</span>', 'statusLike', '$like', '1290445375', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('640', '0', 'skin_global', '<php>\nif ( $author[\'pp_reputation_points\'] > 0)\n{\n	$tbSrtvStyle = \'positive\';\n}\nelseif ( $author[\'pp_reputation_points\'] < 0)\n{\n	$tbSrtvStyle = \'negative\';\n}\nelse\n{\n	$tbSrtvStyle = \'zero\';\n}\n</php>\n<div class=\'reputation {$tbSrtvStyle} short\' style=\'float:none;\'>\n	<div style=\'font-size:1.1em\'>{$this->lang->words[\'tb_srtv_reputation\']}: {parse expression=\"$this->lang->formatNumber( intval( $author[\'pp_reputation_points\'] ) )\"}</div>\n	<if test=\"$author[\'author_reputation\'] && $author[\'author_reputation\'][\'text\']\">\n		<span class=\'title\' style=\'font-weight:normal\'>{$author[\'author_reputation\'][\'text\']}</span>\n	</if>\n	<if test=\"$author[\'author_reputation\'] && $author[\'author_reputation\'][\'image\']\">\n		<if test=\"$author[\'author_reputation\'][\'text\']\"><br /></if>\n		<span class=\'image\'><img src=\'{$author[\'author_reputation\'][\'image\']}\' alt=\'{$this->lang->words[\'reputation\']}\' /></span>\n	</if>\n</div>', 'tbSrtvHook', '$author', '1271512351', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('641', '0', 'skin_topic', '<div id=\"ajaxFastReply\" title=\"#\" name=\"{parse expression=\"time()\"}\"></div>', 'ajaxFastReplyDivider', '', '1289161298', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('642', '0', 'skin_topic', '<script type=\"text/javascript\">\n\n// Jump to anchor embedded in query string\n\nvar regex = /pid__([0-9]+)/;\nvar anchor;\n\nif ( regex.test( document.location ) )\n{\n	anchor = \"#entry\" + regex.exec( document.location )[1];\n}\nelse\n{\n	regex = /&pid=([0-9]+)/;\n	\n	if ( regex.test( document.location ) )\n	{\n		anchor = \"#entry\" + regex.exec( document.location )[1];\n	}\n}\n\nif ( anchor != undefined )\n{\n	document.location.hash = anchor;\n}\n\n<if test=\"isLoggedIn:|:$this->memberData[\'member_id\']\">\n\ndocument.observe( \"dom:loaded\", function()\n{\n	// Avoid ipb.delegate.register() as it takes over \"Use Full Editor\" button, too\n		\n	$(\'submit_post\').observe( \'click\', ajaxFastReply );\n		\n	// Set current timestamp for getting new replies\n		\n	$(\'ajaxFastReply\').setAttribute( \'title\', document.location.hash );\n		\n	// Browser back/forward button functionality\n		\n	setInterval( \"ajaxAnchorCheck()\", 150 );\n});\n\n</if>\n\n/* ------------------------------ */\n// [EN31] Ajax Fast Reply v1.0.6\n/* ------------------------------ */\n\nfunction ajaxAnchorCheck()\n{\n	// Init effects\n	\n	var effects = new Array(5);\n									effects[0]	= function( id, parameters ) { new Effect.Shake( id, parameters ); };\n									effects[1]	= function( id, parameters ) { new Effect.Appear( id, parameters ); };\n									effects[2]	= function( id, parameters ) { new Effect.Pulsate( id, parameters ); };\n									effects[3]	= function( id, parameters ) { new Effect.BlindDown( id, parameters ); };\n									effects[4]	= function( id, parameters ) { new Effect.Highlight( id, parameters ); };\n	\n	// Has the hash changed? This fires either when\n	// a post is made or the back/forward button is pressed\n	\n	if ( document.location.hash != $(\'ajaxFastReply\').getAttribute( \'title\' ) )\n	{\n		// Init greatest PID and number of posts hidden/shown\n		\n		var pid			= 0;\n		var posts		= 0;\n		var ajaxDiv		= $(\'ajaxFastReply\');\n		var pidArray		= new Array();\n		\n		// If a hash does not contain #entry,\n		// all ajax-returned posts are hidden\n		\n		if ( document.location.hash.indexOf( \"#entry\" ) != -1 )\n		{\n			// When new posts are added, this is set to the greatest PID returned\n			\n			pid = document.location.hash.replace( \"#entry\", \"\" );\n		}\n		\n		// Loop our returned ajax posts\n\n		for ( var i = 0; i < ajaxDiv.childNodes.length; i++ )\n		{\n			if ( ajaxDiv.childNodes[i].nodeType === 1 )\n			{\n				if ( ajaxDiv.childNodes[i].id.indexOf( \'post_id_\' ) != -1 )\n				{\n					// Did we meet the criteria?\n					\n					if ( parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ) > pid )\n					{\n						// Hide and unload the post\n						\n						ajaxDiv.childNodes[i].style.display = \"none\";\n						ajaxDiv.childNodes[i].setAttribute( \'title\', \'unloaded\' );\n					}\n					else\n					{\n						if ( ajaxDiv.childNodes[i].title == \'created\' )\n						{\n							// Scroll to the current post\n\n							if ( posts == 0 && ajaxDiv.title.indexOf( \'-reset\' ) == -1 )\n							{\n								new Effect.ScrollTo( \"entry\" + parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ), {$this->settings[\'en30_scrolleffectparams\']} );\n							}\n							\n							// Does this effect highlight or reveal?\n							\n							if ( {$this->settings[\'en30_revealeffect\']} % 2 == 0 )\n							{\n								new Effect.Appear( \"post_id_\" + parseInt( ajaxDiv.childNodes[i].id.substr( 8 ) ), { duration: 0.1, queue: \'end\' } );\n							}\n							\n							// Display the main effect\n							\n							effects[ {$this->settings[\'en30_revealeffect\']} ]( ajaxDiv.childNodes[i].id, {$this->settings[\'en30_revealeffectparams\']} );\n							\n							// Post is loaded, increment and add to PID array\n							\n							ajaxDiv.childNodes[i].setAttribute( \'title\', \'loaded\' );\n							\n							pidArray[posts] = ajaxDiv.childNodes[i].id.substr( 8 );\n							posts++;\n						}\n						else\n						{\n							if ( ajaxDiv.childNodes[i].getAttribute( \'title\' ) == \'unloaded\' )\n							{\n								ajaxDiv.childNodes[i].style.display = \"block\";\n\n								// Post is loaded, increment total posts\n																	\n								ajaxDiv.childNodes[i].setAttribute( \'title\', \'loaded\' );\n								posts++;\n							}\n						}\n					}\n				}\n			}\n		}\n		\n		// Highlight any new replies\n		\n		if ( pidArray.length > 1 )\n		{\n			for ( var i = 0; i < ( pidArray.length - 1 ); i++ )\n			{\n				// Queue the highlight effect					\n				new effects[ {$this->settings[\'en30_newreplyeffect\']} ]( \"post_id_\" + pidArray[i], {$this->settings[\'en30_newreplyeffectparams\']} );\n			}\n		}\n					\n		// Reset the current anchor\n		ajaxDiv.setAttribute( \'title\', document.location.hash );\n	}\n}\n\nfunction ajaxMakeVisible( i )\n{\n	// Nice and easy\n	$(\'ajaxFastReply\').childNodes[i].style.display	= \'block\';\n}\n\nfunction ajaxAnchorSet( anchor )\n{\n	document.location.hash = anchor;\n	$(\'ajaxFastReply\').setAttribute( \'title\', anchor + \'-reset\' );\n}\n\nfunction ajaxFastReply( e )\n{\n	// Prevent standard execution of onclick()\n	Event.stop(e);\n\n	var elem = Event.element( e );\n	var form = elem.form;\n	\n	try\n	{\n		// Need to update for submit manually in this case\n		\n		ipb.editors[ \'fast-reply\' ].update_for_form_submit();\n		var Post = $( \'fast-reply_textarea\' ).getValue();\n	}\n	catch( err )\n	{\n		Debug.error( err );\n		Debug.dir( ipb.editors );\n		return;\n	}\n\n	if( Post.blank() )\n	{\n		alert( ipb.lang[\'post_empty\'] );\n		return;\n	}\n\n	// Set up POST url\n	var url = \'{$this->settings[\'base_url\']}app=forums&module=ajax&section=topics&do=ajaxFastReply\';\n\n	// Set up ajax request with our form data\n	\n	new Ajax.Request(	url,\n						{\n							method: \'post\',\n							evalJSON: \'force\',\n							encoding: \'{$this->settings[\'gb_char_set\']}\',\n							parameters: {\n								md5check: 			\'{$this->member->form_hash}\',\n								f:				form.f.value,\n								t:				form.t.value,\n								st:				form.st.value,\n								auth_key:			form.auth_key.value,\n								fast_reply_used:		form.fast_reply_used.value,\n								enableemo:			form.enableemo.value,\n								enablesig:			form.enablesig.value,\n								Post: 				Post.encodeParam(),\n								submit:				form.submit.value,\n								post_date:			$(\'ajaxFastReply\').getAttribute( \'name\' )\n							},\n\n							onSuccess: function(ajax)\n							{\n								// Debug Mode\n								//alert( ajax.responseText );\n\n								if( ajax.responseJSON[\'error\'] )\n								{\n									alert( \'Error: \' + ajax.responseJSON[\'error\'] );\n									return;\n								}\n								else\n								{\n									// Success!\n									// Clear fast reply textarea\n									\n									if ( ! USE_RTE )\n									{\n										// Using STD\n										$(\'fast-reply_textarea\').value = \"\";\n									}\n									else\n									{\n										// Using RTE\n										$(\'fast-reply_iframe\').contentWindow.document.getElementById( \'fast-reply_html\' ).childNodes[1].innerHTML = \"\";\n									}\n																	\n									// Make shortcut to returned posts JSON array\n									\n									var posts = ajax.responseJSON[\'posts\'];\n									\n									// Make shortcut to our ajax divider\n\n									var ajaxDiv	 = $(\'ajaxFastReply\');\n									\n									// Do we have a merged post on the page?\n									\n									var hasMergedPost = false;\n\n									for ( var i = 0; i < posts.length; i++ )\n									{\n										if ( document.getElementById( \'post_id_\' + posts[i][\'pid\'] ) != undefined )\n										{\n											hasMergedPost = true;\n											break;\n										}\n									}\n									\n									// Change anchor to support back/forward\n									// button functionality\n									\n									if ( ! hasMergedPost && document.location.hash != \"#entry\" + posts[ ( posts.length - 1 ) ][\'pid\'] )\n									{\n										// Firefox will flicker anytime we change the hash,\n										// even if to the same hash. The if() avoids the flicker\n										\n										document.location.hash = \"#entry\" + posts[ ( posts.length - 1 ) ][\'pid\'];\n									}\n									\n									// Init vars to be assigned in for() loop\n									\n									var a;\n									var b;\n									var pid;\n									var postDivs;\n									var postRow;\n									var rowClass;\n									var entryAnchor;\n\n									for ( var i = 0; i < posts.length; i++ )\n									{\n										// Shortcut PID\n										pid = posts[i][\'pid\'];\n										\n										// Delete concurrent posts if a merged post is returned\n										\n										if ( hasMergedPost )\n										{\n											postDivs = ajaxDiv.parentNode.getElementsByTagName( \'div\' );\n\n											for ( a = 0; a < postDivs.length; a++ )\n											{\n												if ( postDivs[a].nodeType === 1 )\n												{\n													if ( postDivs[a].id.indexOf( \'post_id\' ) != -1 )\n													{\n														if ( parseInt( postDivs[a].id.substr( 8 ) ) == pid )\n														{\n															// Scroll to the to-be-merged post\n															\n															new Effect.ScrollTo( postDivs[a].id, {$this->settings[\'en30_scrolleffectparams\']} );\n															\n															// Fade it out, then remove it from the DOM\n\n															new Effect.Fade( postDivs[a].id, { queue: \"end\", \n															afterFinish: function( effect ) { \n																							var pid = effect.element.id.substr( 8 );\n																							if ( effect.element.parentNode.id == \'ajaxFastReply\' )\n			{\n				$(\'ajaxFastReply\').removeChild( effect.element );\n			}\n																							else\n			{\n				$(\'ajaxFastReply\').parentNode.removeChild( effect.element );\n			}\n\n			ajaxAnchorSet( \"#entry\" + pid );\n																							}	\n		}\n	);\n															break;\n														}\n													}\n												}\n											}\n										}\n										\n										// Create our post anchor\n										\n										entryAnchor	= document.createElement( \'a\' );\n										\n										entryAnchor.setAttribute( \'id\', \"entry\" + pid );\n										ajaxDiv.appendChild( entryAnchor );\n										\n										// Create our post row\n										\n										postRow			= document.createElement( \'div\' );\n										rowClass		= \"post_block hentry clear\";\n										\n										// Set up the row class\n										\n										if ( {$this->settings[\'reputation_highlight\']} != 0 && posts[i][\'rep_points\'] >= {$this->settings[\'reputation_highlight\']} )\n										{\n											rowClass = rowClass + \" rep_highlight\";\n										}\n										\n										if ( posts[i][\'queued\'] == 1 )\n										{\n											rowClass = rowClass + \" moderated\";\n										}\n										\n										if ( {$this->settings[\'reputation_enabled\']} == 1 )\n										{\n											rowClass = rowClass + \"  with_rep\";\n										}\n										\n										// Set up our post divider attribute\n										\n										postRow.setAttribute( \"class\", rowClass );\n										postRow.setAttribute( \"title\", \"created\" );\n										postRow.setAttribute( \"id\", \"post_id_\" + pid );\n										\n										// This fixes the flicker of Effect.BlindDown() in Firefox\n										\n										postRow.style.margin = \"0\";\n										\n										// Hide it by default\n										\n										postRow.style.display	= \"none\";\n										postRow.innerHTML	= posts[i][\'post\'];\n										\n										// Insert it into our ajaxDiv\n\n										ajaxDiv.appendChild( postRow );\n										\n										// Register posts\' reputation controls\n										\n										ipb.global.registerReputation( \'rep_post_\' + pid, { app: \'forums\', type: \'pid\', typeid: pid }, parseInt(\'0\') );\n										// Register delete button!\n										<if test=\"canDeleteUrls:|:!$this->member->is_not_human\">\n											// Delete stuff set up\n\n											ipb.topic.deletePerms[ pid ] = { \'canDelete\' : 1, \'canSoftDelete\' : 1 };\n											ipb.delegate.register(\'.delete_post\' + pid, ipb.topic.deletePopUp);\n										</if>\n									}\n\n									// Reset last post date for fetching new replies\n									\n									$(\'ajaxFastReply\').setAttribute( \'name\', ajax.responseJSON[\'last_post\'] );\n								}\n							}\n						}\n					);\n}\n\n</script>', 'ajaxFastReplyJS', '', '1289164512', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('643', '0', 'skin_topic', '		<!--Begin Msg Number {$post[\'post\'][\'pid\']}-->\n			<if test=\"repIgnored:|:( isset( $post[\'post\'][\'_repignored\'] ) AND isset($post[\'post\'][\'_ignored\']) ) AND $post[\'post\'][\'_repignored\'] == 1 && $post[\'post\'][\'_ignored\'] != 1\">\n				<div class=\'post_ignore\'>\n					<if test=\"noRep:|:$post[\'post\'][\'rep_points\'] == 0\">\n						<span class=\'reputation zero\' title=\'{$this->lang->words[\'top_rep\']}\'>\n					</if>\n					<if test=\"posRep:|:$post[\'post\'][\'rep_points\'] > 0\">\n						<span class=\'reputation positive\' title=\'{$this->lang->words[\'top_rep\']}\'>\n					</if>\n					<if test=\"negRep:|:$post[\'post\'][\'rep_points\'] < 0\">\n						<span class=\'reputation negative\' title=\'{$this->lang->words[\'top_rep\']}\' >\n					</if>\n							{$post[\'post\'][\'rep_points\']}</span> {$this->lang->words[\'top_this_post_by\']} <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"} {$this->lang->words[\'top_below_thresh\']}. <a href=\'#\' title=\'{$this->lang->words[\'ignore_view_post\']}\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n				</div>\n			</if>\n			<if test=\"userIgnored:|:$post[\'post\'][\'_ignored\'] == 1\">\n				<div class=\'post_ignore\'>\n					{$this->lang->words[\'post_ignored\']} <a href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\"}\'>{$post[\'author\'][\'members_display_name\']}</a> {parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}. <a href=\'#entry{$post[\'post\'][\'pid\']}\' title=\'{$this->lang->words[\'ignore_view_post\']}\' style=\'display: none\' id=\'unhide_post_{$post[\'post\'][\'pid\']}\'>{$this->lang->words[\'rep_view_anyway\']}</a>\n				</div>\n			</if>\n			<div class=\'post_wrap\' <if test=\"$post[\'post\'][\'_ignored\'] == 1 || $post[\'post\'][\'_repignored\'] == 1\">style=\'display: none\'</if>>\n				<if test=\"postMid:|:$post[\'author\'][\'member_id\']\">\n					<h3>\n				<else />\n					<h3 class=\'guest\'>\n				</if>\n						<span class=\'post_id\'><a href=\'{parse url=\"showtopic={$post[\'post\'][\'topic_id\']}&amp;view=findpost&amp;p={$post[\'post\'][\'pid\']}\" template=\"showtopic\" seotitle=\"{$topic[\'title_seo\']}\" base=\"public\"}\' rel=\'bookmark\' title=\'{$this->lang->words[\'link_to_post\']} #{$topic[\'posts\']}\'>#{$topic[\'posts\']}</a></span>\n						<if test=\"postMember:|:$post[\'author\'][\'member_id\']\">\n							<if test=\"postOnline:|:$post[\'author\'][\'_online\']\">\n								{parse replacement=\"user_online\"}\n							<else />\n								{parse replacement=\"user_offline\"}\n							</if> &nbsp;\n								<span class=\"author vcard\"><a class=\"url fn\" href=\'{parse url=\"showuser={$post[\'author\'][\'member_id\']}\" base=\"public\" template=\"showuser\" seotitle=\"{$post[\'author\'][\'members_seo_name\']}\"}\'>{$post[\'author\'][\'members_display_name\']}</a>{parse template=\"user_popup\" group=\"global\" params=\"$post[\'author\'][\'member_id\'], $post[\'author\'][\'members_seo_name\']\"}</span>\n						<else />\n							{$post[\'author\'][\'members_display_name\']}\n						</if>\n						<if test=\"postIp:|:$post[\'post\'][\'_show_ip\']\">\n							<span class=\'ip\'>({$this->lang->words[\'ip\']}:\n							<if test=\"postAdmin:|:$post[\'author\'][\'g_access_cp\']\">\n								<em>{$this->lang->words[\'ip_private\']}</em>\n							<else />\n								<a href=\"{parse url=\"app=core&amp;module=usercp&amp;tab=members&amp;area=mod_ipaddress&amp;do=custom&amp;ip={$post[\'post\'][\'ip_address\']}\" base=\"public\"}\" title=\'{$this->lang->words[\'info_about_this_ip\']}\'>{$post[\'post\'][\'ip_address\']}</a>\n							</if>\n							)</span>\n						</if>\n					</h3>\n				<div class=\'author_info\'>\n					{parse template=\"userInfoPane\" group=\"global\" params=\"$post[\'author\'], $post[\'post\'][\'pid\'], array()\"}\n				</div>\n				<div class=\'post_body\'>\n					<p class=\'posted_info\'>\n						<if test=\"postModCheckbox:|:$this->memberData[\'is_mod\']\">\n							<if test=\"postModSelected:|:isset( $post[\'post\'][\'_pid_selected\'] ) && $post[\'post\'][\'_pid_selected\']\">\n								<label for=\'checkbox_{$post[\'post\'][\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$post[\'post\'][\'pid\']}\' name=\'selectedpids[]\' value=\'{$post[\'post\'][\'pid\']}\' class=\'post_mod\' checked=\'checked\' />\n							<else />\n								<label for=\'checkbox_{$post[\'post\'][\'pid\']}\' class=\'post_mod hide\'>{$this->lang->words[\'mod_select_post\']}</label><input type=\'checkbox\' id=\'checkbox_{$post[\'post\'][\'pid\']}\' name=\'selectedpids[]\' value=\'{$post[\'post\'][\'pid\']}\' class=\'post_mod\' />\n							</if>\n						</if>\n						<if test=\"postIcon:|:$post[\'post\'][\'icon_id\']\">\n							<img src=\"{$this->settings[\'public_dir\']}/style_extra/post_icons/icon{$post[\'post\'][\'icon_id\']}.gif\" alt=\"{$this->lang->words[\'post_icon\']}\" />&nbsp;\n						</if>\n						{$this->lang->words[\'posted\']} <abbr class=\"published\" title=\"{parse expression=\"date( \'c\', $post[\'post\'][\'post_date\'] )\"}\">{parse date=\"$post[\'post\'][\'post_date\']\" format=\"long\"}</abbr>\n					</p>\n					<div class=\'post entry-content\'>\n						{$post[\'post\'][\'post\']}\n						{$post[\'post\'][\'attachmentHtml\']}\n						<br />\n						<if test=\"postEditBy:|:$post[\'post\'][\'edit_by\']\">\n							<p class=\'edit\'>\n								{$post[\'post\'][\'edit_by\']}\n								<if test=\"postEditByReason:|:$post[\'post\'][\'post_edit_reason\'] != \'\'\">\n									<br />\n									<span class=\'reason\'>{$this->lang->words[\'reason_for_edit\']}: {$post[\'post\'][\'post_edit_reason\']}</span>\n								</if>\n							</p>\n						</if>\n					</div>\n					<if test=\'postSignature:|:$post[\'post\'][\'signature\']\'>\n						{$post[\'post\'][\'signature\']}\n					</if>\n				</div>\n			<if test=\"reputationBox:|:$this->settings[\'reputation_enabled\']\">\n				<if test=\"canRep:|:!( $this->settings[\'reputation_protected_groups\'] && in_array( $post[\'author\'][\'member_group_id\'], explode( \',\', $this->settings[\'reputation_protected_groups\'] ) ) )\">\n				<div class=\'rep_bar clear right\' id=\'rep_post_{$post[\'post\'][\'pid\']}\'>\n					<if test=\"repHighlight:|:$this->settings[\'reputation_highlight\'] AND $post[\'post\'][\'rep_points\'] >= $this->settings[\'reputation_highlight\']\">\n						<span class=\'rep_highlight\'>{$this->lang->words[\'popular_post\']}</span>\n					</if>\n				<if test=\"hasNoRep:|:$post[\'post\'][\'rep_points\'] == 0\">\n					<span class=\'reputation zero rep_show\' title=\'{$this->lang->words[\'reputation\']}\'>\n				</if>\n				<if test=\"hasPosRep:|:$post[\'post\'][\'rep_points\'] > 0\">\n					<span class=\'reputation positive rep_show\' title=\'{$this->lang->words[\'reputation\']}\'>\n				</if>\n				<if test=\"hasNegRep:|:$post[\'post\'][\'rep_points\'] < 0\">\n					<span class=\'reputation negative rep_show\' title=\'{$this->lang->words[\'reputation\']}\' >\n				</if>\n						{$post[\'post\'][\'rep_points\']}\n					</span>\n					<if test=\"hasNotGivenRep:|:$post[\'post\'][\'has_given_rep\'] != 1 AND $post[\'post\'][\'has_given_rep\'] != -1 AND $this->memberData[\'member_id\'] != 0 && ( $this->settings[\'reputation_can_self_vote\'] OR $post[\'author\'][\'member_id\'] != $this->memberData[\'member_id\'] )\">\n						<ul>\n						<if test=\"giveRepUp:|:$this->settings[\'reputation_point_types\'] == \'positive\' || $this->settings[\'reputation_point_types\'] == \'both\'\">\n							<li><a href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate=forums&amp;type=pid&amp;type_id={$post[\'post\'][\'pid\']}&amp;rating=1&amp;secure_key={$this->member->form_hash}&amp;post_return={$post[\'post\'][\'pid\']}\' class=\'rep_up\' title=\'{$this->lang->words[\'reputation_up\']}\'>{parse replacement=\"rep_up\"}</a></li>\n						</if>\n						<if test=\"giveRepDown:|:$this->settings[\'reputation_point_types\'] == \'negative\' || $this->settings[\'reputation_point_types\'] == \'both\'\">\n							<li><a href=\'{$this->settings[\'base_url\']}app=core&amp;module=global&amp;section=reputation&amp;do=add_rating&amp;app_rate=forums&amp;type=pid&amp;type_id={$post[\'post\'][\'pid\']}&amp;rating=-1&amp;secure_key={$this->member->form_hash}&amp;post_return={$post[\'post\'][\'pid\']}\' class=\'rep_down\' title=\'{$this->lang->words[\'reputation_down\']}\'>{parse replacement=\"rep_down\"}</a></li>\n						</if>\n						</ul>\n					</if>\n				</div>\n				</if>\n			</if>\n				<ul class=\'post_controls\'>\n					<if test=\"canReportPost:|:($this->settings[\'disable_reportpost\'] != 1) and ( $this->memberData[\'member_id\'] )\">\n						<li class=\'report\'>\n							<a href=\'{parse url=\"app=core&amp;module=reports&amp;rcom=post&amp;tid={$this->request[\'t\']}&amp;pid={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"public\"}\'>{parse replacement=\"report_post_icon\"} {$this->lang->words[\'report\']}</a>\n						</li>\n						<if test=\"postIsReported:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n							<li class=\'report\'>\n								<a href=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;section=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']}\" id=\'post-report-{$post[\'post\'][\'pid\']}\' class=\'ipbmenu\'> <span id=\"rstat-{$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'info\'][\'id\']}\"><img src=\"{$this->settings[\'img_url\']}/reports/post_alert_{$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'gfx\']}.png\" alt=\"{$this->lang->words[\'icon\']}\" /></span> </a>\n							</li>\n						</if>\n					</if>\n					<li class=\'top hide\'><a href=\'#top\' class=\'top\' title=\'{$this->lang->words[\'back_top\']}\'>{$this->lang->words[\'back_top\']}</a></li>\n					\n					<if test=\"multiquote:|:isset( $post[\'post\'][\'_mq_selected\'] ) && $post[\'post\'][\'_mq_selected\']\">\n						<li class=\'selected multiquote\' id=\'multiq_{$post[\'post\'][\'pid\']}\'>\n					<else />\n						<li class=\'multiquote\' id=\'multiq_{$post[\'post\'][\'pid\']}\'>\n					</if>\n							<a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'quote_with_mq\']}\">{parse replacement=\"mq_post_icon\"} {$this->lang->words[\'mq\']}</a>\n						</li>\n					<li><a href=\"{parse url=\"module=post&amp;section=post&amp;do=reply_post&amp;f={$this->request[\'f\']}&amp;t={$this->request[\'t\']}&amp;qpid={$post[\'post\'][\'pid\']}\" base=\"publicWithApp\"}\" title=\"{$this->lang->words[\'tt_reply_to_post\']}\">{parse replacement=\"reply_post_icon\"} {$this->lang->words[\'post_reply\']}</a></li>\n					<if test=\"canEdit:|:$post[\'post\'][\'_can_edit\'] === TRUE\">\n						<li class=\'post_edit\'><a href=\'{parse url=\"module=post&amp;section=post&amp;do=edit_post&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_edit_title\']}\' class=\'edit_post\' id=\'edit_post_{$post[\'post\'][\'pid\']}\'>{parse replacement=\"edit_post_icon\"} {$this->lang->words[\'post_edit\']}</a></li>\n					</if>\n					<if test=\"canDelete:|:$post[\'post\'][\'_can_delete\'] === TRUE\">\n						<li class=\'post_del\' id=\'del_post_{$post[\'post\'][\'pid\']}\'>\n							<a href=\'{parse url=\"module=moderate&amp;section=moderate&amp;do=04&amp;f={$forum[\'id\']}&amp;t={$topic[\'tid\']}&amp;p={$post[\'post\'][\'pid\']}&amp;st={$this->request[\'st\']}&amp;auth_key={$this->member->form_hash}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'post_delete_title\']}\' class=\'delete_post\'>{parse replacement=\"delete_post_icon\"} {$this->lang->words[\'post_delete\']}</a>\n						</li>\n					</if>\n					<!-- Matt: Approve / unapprove post button -->\n					<if test=\"approvePost:|:$this->memberData[\'is_mod\']\">\n						<li class=\'post_toggle toggle_post\' id=\'toggle_post_{$post[\'post\'][\'pid\']}\'>\n							<a href=\'{parse url=\"app=forums&amp;module=forums&amp;section=moderate&amp;do=postchoice&amp;tact=unapprove&amp;selectedpids[{$post[\'post\'][\'pid\']}]=1\" base=\"public\"}\' title=\'{$this->lang->words[\'post_toggle_visible\']}\'>{parse replacement=\"edit_post_icon\"} <span id=\'toggletext_post_{$post[\'post\'][\'pid\']}\'><if test=\"approveUnapprove:|:$post[\'post\'][\'queued\']==1\">{$this->lang->words[\'post_approve\']}<else />{$this->lang->words[\'post_unapprove\']}</if></span></a>\n						</li>\n					</if>\n				</ul>\n				<if test=\"reportedPostData:|:$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'gfx\'] > 0\">\n					<ul id=\'post-report-{$post[\'post\'][\'pid\']}_menucontent\' class=\'ipbmenu_content\'>\n						<li><a href=\"{parse url=\"app=core&amp;module=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][ $post[\'post\'][\'pid\'] ][\'info\'][\'id\']}\" base=\"public\"}\" id=\'report_mark_{$post[\'post\'][\'pid\']}\'><img src=\'{$this->settings[\'img_url\']}/reports/mark_complete.png\' alt=\'\' /> {$this->lang->words[\'report_menu_mark_complete\']}</a></li>\n						<li><a href=\"{$this->settings[\'base_url\']}app=core&amp;module=reports&amp;section=reports&amp;do=show_report&amp;rid={$this->memberData[\'_cache\'][\'report_temp\'][\'post_marker\'][\'post\'][$post[\'post\'][\'pid\']][\'info\'][\'id\']}\"><img src=\'{$this->settings[\'img_url\']}/reports/view_report.png\' alt=\'\' /> {$this->lang->words[\'report_menu_view_report\']}</a></li>\n					</ul>																							\n				</if>\n			</div>\n		<!-- </if> -->			\n		<if test=\"initIgnoredPost:|:$post[\'post\'][\'_repignored\'] == 1 || $post[\'post\'][\'_ignored\']\">\n		</if>\n		<hr />\n		<if test=\"endFirstPost:|:$post[\'post\'][\'_end_first_post\']\">\n			<!-- END OF FIRST POST IN LINEAR+, SHOW BUTTONS AND NEW TITLE -->\n			<br />\n			<div class=\'topic_controls\'>\n				{$topic[\'SHOW_PAGES\']}\n				<ul class=\'topic_buttons\'>\n					<if test=\"bottomNewTopic:|:$forum[\'_user_can_post\']\">\n						<li><a href=\'{parse url=\"module=post&amp;section=post&amp;do=new_post&amp;f={$forum[\'id\']}\" base=\"publicWithApp\"}\' title=\'{$this->lang->words[\'start_new_topic\']}\' accesskey=\'n\'>{parse replacement=\"topic_icon\"} {$this->lang->words[\'start_new_topic\']}</a></li>\n					<else />\n						<li class=\'disabled\'><span>{$this->lang->words[\'top_cannot_start\']}</span></li>\n					</if>\n					<if test=\"bottomIsClosed:|:$topic[\'state\'] == \'closed\'\">\n						<li class=\'closed\'>\n							<if test=\"bottomClosedButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n								<a href=\'{$displayData[\'reply_button\'][\'url\']}\' accesskey=\'r\'>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_locked_reply\']}</a>\n							<else />\n								<span>{parse replacement=\"lock_icon\"} {$this->lang->words[\'top_locked\']}</span>\n							</if>\n						</li>\n					<else />\n						<if test=\"bottomReplyButton:|:$displayData[\'reply_button\'][\'image\']\">\n							<if test=\"bottomReplyButtonLink:|:$displayData[\'reply_button\'][\'url\']\">\n								<li><a href=\'{$displayData[\'reply_button\'][\'url\']}\' title=\'{$this->lang->words[\'topic_add_reply\']}\' accesskey=\'r\'>{parse replacement=\"reply_icon\"} {$this->lang->words[\'topic_add_reply\']}</a></li>\n							<else />\n								<li class=\'disabled\'><span>{$this->lang->words[\'top_cannot_reply\']}</span></li>\n							</if>\n						</if>\n					</if>\n				</ul>\n			<h2 class=\'maintitle\'>{$this->lang->words[\'topic_other_replies\']}</h2>\n			<div class=\'generic_bar\'></div>\n		</if>', 'ajaxFastReplyRow', '$forum, $topic, $post', '1289161638', '1', '1', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('644', '0', 'skin_boards', '<if test=\"hasFbApp:|:$this->settings[\'flbApplicationID\']\">\n<div class=\'general_box clearfix\'>\n	<h3><img src=\'{$this->settings[\'img_url\']}/user_comment.png\' alt=\'\' /> {$this->settings[\'board_name\']} {$this->lang->words[\'facebook_feed\']}</h3>\n	<div class=\'block_list clearfix\' style=\'text-align: center;\'>\n		<div><fb:like-box profile_id=\"{$this->settings[\'flbApplicationID\']}\"{$extra}></fb:like-box></div>\n	</div>\n</div>\n<div id=\"fb-root\"></div>\n<script>\n  window.fbAsyncInit = function() {\n    FB.init({appId: \'{$this->settings[\'flbApplicationID\']}\', status: true, cookie: true,\n             xfbml: true});\n  };\n  (function() {\n    var e = document.createElement(\'script\'); e.async = true;\n    e.src = document.location.protocol +\n      \'//connect.facebook.net/en_US/all.js\';\n    document.getElementById(\'fb-root\').appendChild(e);\n  }());\n</script>\n</if>', 'hookFacebookLikeBox', '$extra=\'\'', '1275785712', '0', '0', '1', '0', 'root');
INSERT INTO `ibf_skin_templates` VALUES ('645', '1', 'skin_register', '{parse js_module=\"register\"}\r\n<script type=\'text/javascript\'>\r\n//<![CDATA[\r\n	ipb.register.inSection = \"mainform\";\r\n	ipb.register.nameMaxLength = \"{$this->settings[\'max_user_name_length\']}\";\r\n	ipb.register.allowedChars = \"{$this->settings[\'username_characters\']}\";\r\n	ipb.templates[\'accept\'] = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_accept\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/accept.png\' alt=\'\' /> [msg]</span>\";\r\n	ipb.templates[\'error\'] = \"&nbsp;<span id=\'[id]_msg\' class=\'reg_msg reg_error\' style=\'display: none\'><img src=\'{$this->settings[\'img_url\']}/exclamation.png\' alt=\'\' /> [msg]</span>\";\r\n//]]>\r\n</script>\r\n<div id=\'register_form\'>\r\n	<!--<h1 class=\'ipsType_pagetitle\'>{$this->lang->words[\'ready_register\']}</h1>-->\r\n	{parse template=\"registerStepBar\" group=\"register\" params=\"array(\'register_form\' => \'ipsSteps_active\', \'confirmation\' => \'\')\"}\r\n	<if test=\"registerHasErrors:|:is_array( $general_errors ) && count( $general_errors )\">\r\n	<div class=\'message error\'>\r\n		{$this->lang->words[\'following_errors\']}\r\n		<ul>\r\n			<foreach loop=\"general_errors:$general_errors as $r\">\r\n				<li>{$r}</li>\r\n			</foreach>\r\n		</ul>\r\n	</div>\r\n	<br />\r\n	</if>\r\n	<form action=\"{parse url=\"app=core&amp;module=global&amp;section=register\" base=\"public\"}\" method=\"post\" name=\"REG\" id=\'register\'>\r\n		<input type=\"hidden\" name=\"termsread\" value=\"1\" />\r\n		<input type=\"hidden\" name=\"agree_to_terms\" value=\"1\" />\r\n		<input type=\"hidden\" name=\"do\" value=\"process_form\" />\r\n		<input type=\"hidden\" name=\"coppa_user\" value=\"{$data[\'coppa_user\']}\" />\r\n		<input type=\'hidden\' name=\'nexus_pass\' value=\'1\' />\r\n		<input type=\'hidden\' name=\'time_offset\' id=\'auto_time_offset\' value=\'0\' />\r\n		<input type=\'hidden\' name=\'dst\' id=\'auto_dst\' value=\'0\' />\r\n		\r\n		<h1 class=\'maintitle\'>\r\n			{$this->lang->words[\'ready_register\']}\r\n		</h1>\r\n		<div class=\'ipsBox\'>\r\n		\r\n			<div class=\'ipsBox_container ipsPad\'>\r\n			\r\n				<if test=\"registerServices:|:IPSLib::fbc_enabled() || IPSLib::twitter_enabled() === true\">\r\n					<div class=\'ipsBox_container ipsBox_notice ipsForm ipsForm_horizontal\' id=\'external_services\'>\r\n						<strong class=\'ipsField_title\' id=\'save_time\'>{$this->lang->words[\'want_to_save_time\']}</strong>\r\n						<div class=\'ipsField_content\'>\r\n							<ul class=\'ipsList_inline\'>\r\n								<if test=\"registerUsingFb:|:IPSLib::fbc_enabled()\">\r\n									<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/facebook/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/facebook_login.png\" alt=\"\" /></a></li>\r\n								</if>\r\n								<if test=\"twitterBox:|:IPSLib::twitter_enabled() === true\">\r\n									<li><a href=\"{$this->settings[\'_original_base_url\']}/interface/twitter/index.php?_reg=1\"><img src=\"{$this->settings[\'img_url\']}/twitter_login.png\" alt=\"\" /></a></li>\r\n								</if>\r\n							</ul>\r\n						</div>\r\n					</div>\r\n				</if>\r\n			\r\n				<if test=\"registerHasInlineErrors:|:is_array( $inline_errors ) && ( $inline_errors[\'username\'] || $inline_errors[\'dname\'] || $inline_errors[\'email\'] || $inline_errors[\'password\'] )\">\r\n					<p class=\'message error\'>{$this->lang->words[\'reg_errors_found\']}</p>\r\n					<br />	\r\n				</if>\r\n				<fieldset>\r\n					<ul class=\'ipsForm ipsForm_horizontal\'>\r\n						<li class=\'ipsField\'>\r\n							<p class=\'ipsField_content\'>\r\n								<span class=\'ipsForm_required ipsType_smaller\'>* {$this->lang->words[\'required_field\']}</span>\r\n							</p>\r\n						</li>\r\n						<li class=\'ipsField clear <if test=\"ieDnameClass:|:$inline_errors[\'dname\']\">error</if>\'>\r\n							<label for=\'display_name\' class=\'ipsField_title\'>{$this->lang->words[\'reg_choose_dname\']} <span class=\'ipsForm_required\'>*</span></label>\r\n							<p class=\'ipsField_content\'>\r\n								<input type=\'text\' class=\'input_text\' id=\'display_name\' size=\'45\' maxlength=\'{$this->settings[\'max_user_name_length\']}\' value=\'{$this->request[\'members_display_name\']}\' name=\'members_display_name\' /><br />\r\n								<span class=\'desc primary lighter\'>\r\n									<if test=\"ieDname:|:$inline_errors[\'dname\']\"><span class=\'error\'>{$inline_errors[\'dname\']}<br /></span></if>\r\n									{parse expression=\"sprintf( $this->lang->words[\'dname_desc\'], $this->settings[\'max_user_name_length\'])\"}\r\n								</span>\r\n							</p>\r\n						</li>\r\n						<li class=\'ipsField clear <if test=\"ieEmailClass:|:$inline_errors[\'email\']\">error</if>\'>\r\n							<label for=\'email_1\' class=\'ipsField_title\'>{$this->lang->words[\'reg_enter_email\']} <span class=\'ipsForm_required\'>*</span></label>\r\n							<p class=\'ipsField_content\'>\r\n								<input type=\'text\' id=\'email_1\' class=\'input_text email\' size=\'45\' maxlength=\'150\' name=\'EmailAddress\' value=\'{$this->request[\'EmailAddress\']}\' /><br />\r\n								<if test=\"ieEmail:|:$inline_errors[\'email\']\"><span class=\'desc\'><span class=\'error\'>{$inline_errors[\'email\']}</span></span></if>\r\n							</p>\r\n						</li>		\r\n						<li class=\'ipsField clear <if test=\"iePasswordClass:|:$inline_errors[\'password\']\">error</if>\'>\r\n							<label for=\'password_1\' class=\'ipsField_title\'>{$this->lang->words[\'reg_choose_password\']} <span class=\'ipsForm_required\'>*</span></label>\r\n							<p class=\'ipsField_content\'>\r\n								<input type=\'password\' id=\'password_1\' class=\'input_text password\' size=\'45\' maxlength=\'32\' value=\'{$this->request[\'PassWord\']}\' name=\'PassWord\' /><br />\r\n								<span class=\'desc lighter\'><if test=\"iePassword:|:$inline_errors[\'password\']\"><span class=\'error\'>{$inline_errors[\'password\']}<br /></span></if>{$this->lang->words[\'reg_choose_password_desc\']}</span>\r\n							</p>\r\n						</li>\r\n						<li class=\'ipsField clear\'>\r\n							<label for=\'password_2\' class=\'ipsField_title\'>{$this->lang->words[\'reg_reenter_password\']} <span class=\'ipsForm_required\'>*</span></label>\r\n							<p class=\'ipsField_content\'>\r\n								<input type=\'password\' id=\'password_2\' class=\'input_text password\' size=\'45\' maxlength=\'32\' value=\'{$this->request[\'PassWord_Check\']}\' name=\'PassWord_Check\' /><br />\r\n							</p>\r\n						</li>\r\n					</ul>\r\n				</fieldset>\r\n				<if test=\"hasNexusFields:|:!empty( $nexusFields )\">\r\n					<script type=\'text/javascript\'>\r\n						var _countriesWithStates = [];\r\n						<foreach loop=\"statesJs:$nexusStates as $k => $v\">\r\n							_countriesWithStates[\"{$k}\"] = 1;\r\n						</foreach>\r\n					</script>\r\n					<hr />\r\n					<fieldset>\r\n						<ul class=\'ipsForm ipsForm_horizontal\'>\r\n							<foreach loop=\"fields:$nexusFields as $f\">\r\n								<if test=\"isAddressOrPhone:|:in_array( $f[\'f_column\'], array( \'cm_address_1\', \'cm_phone\' ) )\">\r\n									<br />\r\n								</if>\r\n								<if test=\"isText:|:$f[\'f_type\'] == \'text\'\">\r\n									<li class=\'ipsField clear\'>\r\n										<label for=\'{$f[\'f_column\']}\' class=\'ipsField_title\'><if test=\"isAddress1:|:$f[\'f_column\'] == \'cm_address_1\'\">{$this->lang->words[\'cm_address\']}<else /><if test=\"isAddress2:|:$f[\'f_column\'] == \'cm_address_2\'\">&nbsp;<else />{$f[\'f_name\']}</if></if> <if test=\"textRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\r\n										<p class=\'ipsField_content\'>\r\n											<input type=\'text\' class=\'input_text\' id=\'{$f[\'f_column\']}\' size=\'25\' maxlength=\'255\' value=\'{$this->request[ $f[\'f_column\'] ]}\' name=\'{$f[\'f_column\']}\' />\r\n										</p>\r\n										<if test=\"textErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\r\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\r\n										</if>\r\n									</li>\r\n								</if>\r\n								<if test=\"isDropdown:|:$f[\'f_type\'] == \'dropdown\'\">\r\n									<li class=\'ipsField clear\'>\r\n										<label for=\'{$f[\'f_column\']}\' class=\'ipsField_title\'>{$f[\'f_name\']} <if test=\"dropdownRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\r\n										<div class=\'ipsField_content\'>\r\n											<select name=\'{$f[\'f_column\']}\' id=\'{$f[\'f_column\']}\' <if test=\"isCountry:|:$f[\'f_column\'] == \'cm_country\'\">onchange=\'states()\'</if>>\r\n												<foreach loop=\"options:explode( \"\\n\", $f[\'f_extra\'] ) as $k => $v\">\r\n													{parse variable=\"selected\" default=\"\" oncondition=\"$k == $this->request[ $f[\'f_column\'] ] or $v == $this->request[ $f[\'f_column\'] ]\" value=\" selected=\'selected\'\"}\r\n													<option value=\'<if test=\"isCountrySelect:|:$f[\'f_column\'] == \'cm_country\'\">{$v}<else />{$k}</if>\'{parse variable=\"selected\"}><if test=\"isCountryWords:|:$f[\'f_column\'] == \'cm_country\'\">{$this->lang->words[\'nc_\'.$v]}<else />{$v}</if></option>\r\n												</foreach>\r\n											</select>\r\n										</div>\r\n										<if test=\"dropdownErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\r\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\r\n										</if>\r\n									</li>\r\n								</if>\r\n								<if test=\"isSpecial:|:$f[\'f_type\'] == \'special\'\">\r\n									<li class=\'ipsField clear\'>\r\n										<label for=\'cm_state\' class=\'ipsField_title\'>{$this->lang->words[\'cm_state\']} <if test=\"specialRequired:|:$f[\'f_reg_require\']\"><span class=\'ipsForm_required\'>*</span></if></label>\r\n										<div class=\'ipsField_content\'>\r\n											<input type=\'text\' class=\'input_text\' id=\'text-states\' size=\'25\' name=\'cm_state\' value=\'{$this->request[\'cm_state\']}\' />\r\n											<foreach loop=\"statesCountries:$nexusStates as $country => $_states\">\r\n												<select name=\'_cm_state\' id=\'{$country}-states\' class=\'input_select\' style=\'display:none\'>\r\n													<foreach loop=\"states:$_states as $s\">\r\n														{parse variable=\"selected\" default=\"\" oncondition=\"$s[0] == $this->request[\'cm_state\']\" value=\" selected=\'selected\'\"}\r\n														<option value=\'{$s[0]}\'{parse variable=\"selected\"}>{$s[1]}</option>\r\n													</foreach>\r\n												</select>\r\n											</foreach>\r\n										</div>\r\n										<if test=\"specialErrorMessage:|:$f[\'f_reg_require\'] and $this->request[\'do\'] == \'process_form\' and !$this->request[ $f[\'f_column\'] ]\">\r\n											<span class=\'error\'>{$this->lang->words[\'err_complete_form\']}</span>\r\n										</if>\r\n									</li>\r\n								</if>\r\n							</foreach>\r\n						</ul>\r\n					</fieldset>\r\n					<script type=\'text/javascript\'>\r\n						function states()\r\n						{\r\n							var c = $(\'cm_country\').value;\r\n							if ( c in _countriesWithStates )\r\n							{\r\n								$( _display ).style.display = \'none\';\r\n								$( _display ).name = \'_cm_state\';\r\n								\r\n								$( c + \'-states\' ).style.display = \'\';\r\n								$( c + \'-states\' ).name = \'cm_state\';\r\n								\r\n								_display = c + \'-states\';\r\n							}\r\n							else\r\n							{\r\n								$( _display ).style.display = \'none\';\r\n								$( _display ).name = \'_cm_state\';\r\n								\r\n								$( \'text-states\' ).style.display = \'\';\r\n								$( \'text-states\' ).name = \'cm_state\';\r\n								\r\n								_display = \'text-states\';\r\n							}\r\n						}\r\n						\r\n						var _display = \'text-states\';\r\n						states();\r\n					</script>\r\n				</if>				\r\n				<if test=\"hasCfields:|:( is_array( $custom_fields[\'required\'] ) && count( $custom_fields[\'required\'] ) ) || ( is_array( $custom_fields[\'optional\'] ) && count( $custom_fields[\'optional\'] ) )\">\r\n				<hr />\r\n					<fieldset>\r\n						<ul class=\'ipsForm ipsForm_horizontal\'>\r\n						<if test=\"reqCfields:|:is_array( $custom_fields[\'required\'] ) && count( $custom_fields[\'required\'] )\">\r\n							<foreach loop=\"custom_required:$custom_fields[\'required\'] as $_field\">\r\n								<li class=\'ipsField clear ipsField_{$_field[\'type\']}\'>\r\n									<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']} <span class=\'ipsForm_required\'>*</span></label>\r\n									<div class=\'ipsField_content\'>\r\n										{$_field[\'field\']}\r\n										<if test=\"reqCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><br /><span class=\'desc\'>{$_field[\'desc\']}</span></if>\r\n									</div>\r\n								</li>\r\n							</foreach>\r\n						</if>\r\n			\r\n						<if test=\"optCfields:|:is_array( $custom_fields[\'optional\'] ) && count( $custom_fields[\'optional\'] )\">\r\n							<foreach loop=\"custom_optional:$custom_fields[\'optional\'] as $_field\">\r\n								<li class=\'ipsField clear ipsField_{$_field[\'type\']}\'>\r\n									<label for=\'cprofile_{$_field[\'id\']}\' class=\'ipsField_title\'>{$_field[\'name\']}</label>\r\n									<div class=\'ipsField_content\'>\r\n										{$_field[\'field\']}\r\n										<if test=\"optCfieldDescSpan:|:$_field[\'desc\'] != \'\'\"><br /><span class=\'desc\'>{$_field[\'desc\']}</span></if>\r\n									</div>\r\n								</li>\r\n							</foreach>\r\n						</if>\r\n					</fieldset>				\r\n				</if>\r\n				<hr />\r\n				{$data[\'qandaHTML\']}\r\n				{$data[\'captchaHTML\']}\r\n				<hr />\r\n				<fieldset>\r\n					<ul class=\'ipsForm ipsForm_horizontal\'>\r\n						<li class=\'ipsField clear ipsField_checkbox\'>\r\n							<input type=\"checkbox\" name=\"allow_admin_mail\" id=\"allow_admin_mail\" value=\"1\" class=\"input_check\" <if test=\"defaultAAE:|:$this->request[\'allow_admin_mail\'] || !isset( $this->request[\'allow_admin_mail\'] )\">checked=\'checked\'</if> />\r\n							<p class=\'ipsField_content\'>\r\n								<label for=\'allow_admin_mail\'>{$this->lang->words[\'receive_admin_emails\']}</label>\r\n							</p>\r\n						</li>\r\n						<li class=\'ipsField clear ipsField_checkbox\'>\r\n							<input type=\'checkbox\' name=\'agree_tos\' id=\'agree_tos\' value=\'1\' class=\'input_check\' <if test=\"checkedTOS:|:$this->request[\'agree_tos\']\">checked=\"checked\"</if> />\r\n							<p class=\'ipsField_content\'>\r\n								<label for=\'agree_tos\' <if test=\"ieDnameClass:|:$inline_errors[\'dname\']\">error</if>>\r\n									<strong>{$this->lang->words[\'agree_to_tos\']} <a href=\'#\' id=\'tou_link\'>{$this->lang->words[\'terms_of_use\']}</a></strong>\r\n									<if test=\"ieTOS:|:$inline_errors[\'tos\']\"><br /><span class=\'error\'>{$inline_errors[\'tos\']}</span></if>\r\n								</label>	\r\n								<textarea id=\'tou\' class=\'input_text\' style=\'width: 350px; height: 100px; display: block;\'>\r\n									{$this->settings[\'_termsAndConditions\']}\r\n								</textarea>\r\n							</p>\r\n						</li>\r\n					</ul>\r\n					<script type=\'text/javascript\'>\r\n						$(\'tou\').hide();				\r\n					</script>\r\n				</fieldset>\r\n				<br />\r\n				<fieldset>\r\n					<input type=\'submit\' class=\'ipsButton\' id=\'register_submit\' value=\'{$this->lang->words[\'register\']}\' />\r\n				</fieldset>	\r\n			</div>\r\n		</div>\r\n	</form>\r\n	<script type=\'text/javascript\'>\r\n		ipb.templates[\'registration_terms\'] = new Template(\"<h3>{$this->lang->words[\'reg_terms_popup_title\']}</h3><div class=\'ipsPad\' id=\'tou_popup\'>#{content}</div>\");\r\n	</script>\r\n	{parse template=\"registerCoppaStart\" group=\"register\" params=\"\"}\r\n</div>', 'registerForm', '$general_errors=array(), $data=array(), $inline_errors=array(), $time_select=array(), $custom_fields=array(), $nexusFields=array(), $nexusStates=array()', '1338291532', '1', '0', '0', '1', '');
